insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 165, 'ആദ്യമായി വസ്ത്രം ധരിപ്പിക്കപ്പെടുന്നവൻ', 'بَابٌ: ذِكْرُ أَوَّلِ مَنْ يُكْسَى', 897 from books where volume_id=1 and book_no=31 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْمُسْلِمَ إِذَا عَادَ أَخَاهُ الْمُسْلِمَ لَمْ يَزَلْ فِي خُرْفَةِ الْجَنَّةِ". وَفِي رِوَايَةٍ: قِيلَ: مَا خُرْفَةُ الْجَنَّةِ؟ قَالَ: "جَنَاهَا". حَسَنٌ صَحِيحٌ. (م,ت)', 'സൗബാൻ(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം ഒരു മുസ്ലിം തന്റെ മുസ്ലിം സഹോദരനെ സന്ദർശിച്ചാൽ അവൻ സ്വർഗ്ഗീയ ആരാമത്തിലായിരിക്കും." മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ)യോട് ചോദിക്കപ്പെട്ടു: എന്താണ് ഖുർഫ? നബി(സ) പറഞ്ഞു: "അത് സ്വർഗ്ഗത്തിലെ കായ്കനികളാകുന്നു." ഹദീസ് ഹസനും സ്വഹീഹുമാണെനന്ന് തുർമുദി പറയുന്നു. (മു,തു)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 765, 765, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=1), 1, 'وَفِي رِوَايَةٍ: قِيلَ: مَا خُرْفَةُ الْجَنَّةِ؟ قَالَ: "جَنَاهَا". حَسَنٌ صَحِيحٌ. (م,ت)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ)യോട് ചോദിക്കപ്പെട്ടു: എന്താണ് ഖുർഫ? നബി(സ) പറഞ്ഞു: "അത് സ്വർഗ്ഗത്തിലെ കായ്കനികളാകുന്നു." ഹദീസ് ഹസനും സ്വഹീഹുമാണെനന്ന് തുർമുദി പറയുന്നു. (മു,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي فَاخِتَةَ سَعِيدِ بْنِ عِلَاقَةَ الْكُوفِيِّ قَالَ: أَخَذَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ بِيَدِي، قَالَ: انْطَلِقْ بِنَا إِلَى الْحَسَنِ نَعُودُهُ. فَوَجَدْنَا عِنْدَهُ أَبَا مُوسَى رَضِيَ اللهُ عَنْهُ، فَقَالَ عَلِيٌّ عَلَيْهِ السَّلَامُ: أَعَائِدًا جِئْتَ - يَا أَبَا مُوسَى - أَمْ زَائِرًا؟ فَقَالَ: لَا، بَلْ عَائِدًا. فَقَالَ عَلِيٌّ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ مُسْلِمٍ يَعُودُ مُسْلِمًا غُدْوَةً إِلَّا صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُمْسِيَ، وَإِنْ عَادَهُ عَشِيَّةً إِلَّا صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُصْبِحَ، وَكَانَ لَهُ خَرِيفٌ فِي الْجَنَّةِ". حَسَنٌ غَرِيبٌ. (د,ت,جه)', 'അബുഫാഖിത സഈദുബ്നു ഇലാഖതുൽ കൂഫി(റ): അലി(റ) എന്റെ കൈ പിടിച്ചുകൊണ്ട് പറഞ്ഞു: നമുക്ക് ഹസനെ സന്ദർശിക്കാൻ പോകാം. അവിടെ ഞങ്ങൾ അബുമുസ(റ)യെ കണ്ടു. അദ്ദേഹത്തോട് അലി(റ) ചോദിച്ചു: അബൂമൂസാ, നിങ്ങൾ കേവലം സന്ദർശിക്കാൻ വന്നതോ അതോ രോഗ സന്ദർശനത്തിനോ? അബൂമൂസ(റ) പറഞ്ഞു: രോഗ സന്ദർശനത്തിന് തന്നെ. അപ്പോൾ അലി(റ) പറഞ്ഞു: നബി(സ) പറഞ്ഞതായി ഞാൻ കേട്ടു: "ഒരു മുസ്ലിം മറ്റൊരു മുസ്ലിമിനെ രാവിലെ സന്ദർശിച്ചാൽ എഴുപതിനായിരം മാലാഖമാർ വൈകുന്നേരം വരെ അവനു വേണ്ടി പ്രർത്ഥിക്കുന്നതാണ്. വൈകുന്നേരം സന്ദർശിച്ചാൽ എഴുപതിനായിരം മാലാഖമാർ അവന് വേണ്ടി രാവിലെ വരെ പ്രാർത്ഥിച്ചു കൊണ്ടിരിക്കും. അവന് സ്വർഗ്ഗത്തിൽ ഒരു പൂങ്കാവനം ഉണ്ടായിരിക്കും." (ഹദീസ് ഹസനും ഗരീബുമാണെന്ന് തുർമുദി പറയുന്നു.). (ദ,തു,ജ)', 'أَبِي فَاخِتَةَ سَعِيدِ بْنِ عِلَاقَةَ الْكُوفِيِّ قَالَ', 'അബുഫാഖിത സഈദുബ്നു ഇലാഖതുൽ കൂഫി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 765, 765, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُ عَبْدَ اللهِ بْنَ أُبَيٍّ فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ، فَلَمَّا دَخَلَ عَلَيْهِ عَرَفَ فِيهِ الْمَوْتَ، قَالَ: "قَدْ كُنْتُ أَنْهَاكَ عَنْ حُبِّ يَهُودَ". قَالَ: فَقَدْ أَبْغَضَهُمْ سَعْدُ بْنُ زُرَارَةَ، فَمَهْ؟ فَلَمَّا مَاتَ أَتَاهُ ابْنُهُ فَقَالَ: يَا رَسُولَ اللهِ، إِنَّ عَبْدَ اللهِ بْنَ أُبَيٍّ قَدْ مَاتَ، فَأَعْطِنِي قَمِيصَكَ أُكَفِّنْهُ فِيهِ. فَنَزَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَمِيصَهُ، فَأَعْطَاهُ إِيَّاهُ. (د)', 'ഉസാമതുബ്നു സൈദ്(റ): നബി(സ) അബ്ദുല്ലാഹിബ്നു ഉബയ്യിന്റെ മരണാസന്ന രോഗത്തിൽ അദ്ദേഹത്തെ സന്ദർശിക്കാനായി പുറപ്പെട്ടു. നബി(സ) അവിടേക്ക് പ്രവേശിച്ചപ്പോൾ അദ്ദേഹത്തിന്റെ മരണം തിരിച്ചറിഞ്ഞു. നബി(സ) പറഞ്ഞു: "ജൂതന്മാരോട് സ്നേഹം കാണിക്കുന്നതിൽ നിന്ന് ഞാൻ നിന്നെ വിരോധിച്ചിരുന്നു." അദ്ദേഹം പറഞ്ഞു: സഅ്ദുബ്നു സുറാറ അവരെ കോപിപ്പിച്ചിരിക്കുന്നുവല്ലോ! എന്നിട്ടെന്തുണ്ടായി? ശേഷം അദ്ദേഹം മരണപ്പെട്ടപ്പോൾ അദ്ദേഹത്തിന്റെ മകൻ നബി(സ)യെ സമീപിച്ചു പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, അബ്ദുല്ലാഹിബ്നു ഉബയ്യ് മരിച്ചിരിക്കുന്നു. അദ്ദേഹത്തെ പുതപ്പിക്കാൻ അവിടുത്തെ വസ്ത്രം നൽകിയാലും. പ്രവാചകൻ(സ) തന്റെ വസ്ത്രം ഊരി അദ്ദേഹത്തിന് നൽകി. (ദ)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 765, 766, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّهُ قَالَ: كُنَّا جُلُوسًا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، إِذْ جَاءَهُ رَجُلٌ مِنَ الْأَنْصَارِ، فَسَلَّمَ عَلَيْهِ، ثُمَّ أَدْبَرَ الْأَنْصَارِيُّ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا أَخَا الْأَنْصَارِ، كَيْفَ أَخِي سَعْدُ بْنُ عُبَادَةَ؟". فَقَالَ: صَالِحٌ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ يَعُودُهُ مِنْكُمْ؟". فَقَامَ وَقُمْنَا مَعَهُ، وَنَحْنُ بِضْعَةَ عَشَرَ، مَا عَلَيْنَا نِعَالٌ وَلَا خِفَافٌ وَلَا قَلَانِسُ وَلَا قُمُصٌ، نَمْشِي فِي تِلْكَ السِّبَاخِ حَتَّى جِئْنَاهُ، فَاسْتَأْخَرَ قَوْمُهُ مِنْ حَوْلِهِ، حَتَّى دَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ الَّذِينَ مَعَهُ. (م)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം ഇരിക്കുമ്പോൾ ഒരു അൻസാരി വന്ന് നബി(സ)യോട് സലാം പറഞ്ഞു. അൻസ്വാരി പോകാനൊരുങ്ങിയപ്പോൾ നബി(സ) അയാളോട് ചോദിച്ചു: "അൻസ്വാരികളുടെ സഹോദരാ, എന്റെ സഹോദരൻ സഅ്ദുബ്നു ഉബാദക്ക് എങ്ങനെയുണ്ട്?" അൻസാരി പറഞ്ഞു: സുഖമാണ്. നബി(സ) പറഞ്ഞു: "അദ്ദേഹത്തെ സന്ദർശിക്കാൻ നിങ്ങളിലാരുണ്ട്?" നബി(സ) എഴുന്നേറ്റു. കൂടെ ഞങ്ങളും എഴുന്നേറ്റു, ഞങ്ങൾ പത്തിലധികം പേർ പാദരക്ഷയില്ലാതെ ഷൂവും തൊപ്പിയും കുപ്പായവുമില്ലാതെ ഊഷര ഭൂമിയിലൂടെ നടന്ന് അവിടെ എത്തിച്ചേർന്നു. അദ്ദേഹത്തിന്റെ സംഘം ചുറ്റുമുള്ളവരോട് മാറിനിൽക്കാൻ ആവശ്യപ്പെട്ടു. അങ്ങനെ പ്രവാചകനും(സ) കൂടെയുള്ള അനുചരന്മാരും അടുത്തു ചെന്നു. (മു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 766, 766, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: دَخَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى مَرِيضٍ يَعُودُهُ، فَقَالَ: "أَتَشْتَهِي شَيْئًا؟ أَتَشْتَهِي كَعْكًا". قَالَ: نَعَمْ. فَطَلَبُوا لَهُ. [ز: في إسناده ضعيف] (جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ഒരു രോഗിയെ സന്ദർശിക്കാൻ കടന്നുചെന്നു, എന്നിട്ട് അയാളോട് ചോദിച്ചു: "നിനക്ക് വല്ല ആഗ്രഹവുമുണ്ടോ? കേക്ക് വേണോ?" രോഗി ''അതെ'' എന്ന് പറഞ്ഞപ്പോൾ അവർ അത് അദ്ദേഹത്തിന് തേടിപ്പിടിച്ച് നൽകി. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 766, 766, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا دَخَلْتَ عَلَى مَرِيضٍ فَمُرْهُ أَنْ يَدْعُوَ لَكَ، فَإِنَّ دُعَاءَهُ كَدُعَاءِ الْمَلَائِكَةِ". [ز: في إسناده انقطاع] (جه)', 'ഉമറുബ്നു ഖത്താബ്(റ): നബി(സ) എന്നോട് പറഞ്ഞു: "ഒരു രോഗിയുടെ അടുക്കൽ ചെന്നാൽ രോഗിയോട് നിനക്കു വേണ്ടി പ്രാർത്ഥിക്കാൻ പറയുക. കാരണം അവന്റെ പ്രാർത്ഥന മലക്കുകളുടെ പ്രാർത്ഥന പോലെയാണ്." (ഇതിന്റെ പരമ്പരയിൽ വിടവുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നു ഖത്താബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده انقطاع', null, 766, 766, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لِلْمُسْلِمِ عَلَى الْمُسْلِمِ سِتٌّ بِالْمَعْرُوفِ: يُسَلِّمُ عَلَيْهِ إِذَا لَقِيَهُ، وَيُجِيبُهُ إِذَا دَعَاهُ، وَيُشَمِّتُهُ إِذَا عَطَسَ، وَيَعُودُهُ إِذَا مَرِضَ، وَيَتْبَعُ جَنَازَتَهُ إِذَا مَاتَ، وَيُحِبُّ لَهُ مَا يُحِبُّ لِنَفْسِهِ". (ت,جه)', 'അലി(റ): നബി(സ) പറഞ്ഞു: "ഒരു മുസ്ലിമിന് മറ്റൊരു മുസ്ലിമിനോട് പുണ്യകരമായ ആറ് കടമകളുണ്ട്; കണ്ടാൽ സലാം പറയുക. ക്ഷണിച്ചാൽ ക്ഷണം സ്വീകരിക്കുക, തുമ്മിയാൽ അനുഗ്രഹ പ്രാർത്ഥന നടത്തുക, രോഗിയായാൽ സന്ദർശിക്കുക, മരിച്ചാൽ ജനാസയെ അനുഗമിക്കുക, സ്വയം ഇഷ്ടപ്പെടുന്നത് അവന് വേണ്ടിയും ഇഷ്ടപ്പെടുക." (തു,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 766, 766, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لِلْمُسْلِمِ عَلَى الْمُسْلِمِ أَرْبَعُ خِلَالٍ: يُشَمِّتُهُ إِذَا عَطَسَ، وَيُجِيبُهُ إِذَا دَعَاهُ، وَيَشْهَدُهُ إِذَا مَاتَ، وَيَعُودُهُ إِذَا مَرِضَ". (جه)', 'അബുമസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "ഒരു മുസ്ലിം മറ്റൊരു മുസ്ലിമിനോട് നാല് കാര്യങ്ങളിൽ കടപ്പെട്ടിരിക്കുന്നു; തുമ്മിയാൽ പ്രാർത്ഥിക്കുക, ക്ഷണിച്ചാൽ ക്ഷണം സ്വീകരിക്കുക, അവൻ മരിച്ചാൽ അവിടെ സന്നിഹിതനാവുക, രോഗിയായാൽ സന്ദർശിക്കുക." (ജ)', 'أَبِي مَسْعُودٍ', 'അബുമസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 766, 767, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَمْسٌ مِنْ حَقِّ الْمُسْلِمِ عَلَى الْمُسْلِمِ: رَدُّ التَّحِيَّةِ، وَإِجَابَةُ الدَّعْوَةِ، وَشُهُودُ الْجَنَازَةِ، وَعِيَادَةُ الْمَرِيضِ، وَتَشْمِيتُ الْعَاطِسِ إِذَا حَمِدَ اللهَ". (جه)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അഞ്ചു കാര്യങ്ങൾ ഒരു മുസ്ലിമിന് മറ്റൊരു മുസ്ലിമിനോട് കടമയാണ്; അഭിവാദ്യത്തിന് പ്രത്യുത്തരം നൽകുക, ക്ഷണത്തിന് ഉത്തരമേകുക, ജനാസയിൽ സന്നിഹിതനാവുക, രോഗസന്ദർശനം, തുമ്മിയവൻ അല്ലാഹുവിനെ സ്തുതിച്ചാൽ അവന് വേണ്ടി പ്രാർത്ഥിക്കുക." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 767, 767, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: عَادَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَاشِيًا، وَأَبُو بَكْرٍ، وَأَنَا فِي بَنِي سَلِمَةَ. (ق,د,ت,ن,جه)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): എന്നെ നബി(സ)യും അബൂബക്കറും(റ) നടന്നു വന്ന് സന്ദർശിച്ചിരുന്നു. ഞാൻ അന്ന് ബനൂസലിമയിൽ ആയിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 767, 767, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يَعُودُ مَرِيضًا إِلَّا بَعْدَ ثَلَاثٍ. [ز: في إسناده ضعيف] (جه)', 'അനസുബ്നു മാലിക്(റ): ഒരു രോഗിയേയും മൂന്ന് ദിവസം കഴിഞ്ഞ ശേഷമല്ലാതെ നബി(സ) സന്ദർശിച്ചിരുന്നില്ല. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു.) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു.', 767, 767, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا دَخَلْتُمْ عَلَى الْمَرِيضِ فَنَفِّسُوا لَهُ فِي الْأَجَلِ، فَإِنَّ ذَلِكَ لَا يَرُدُّ شَيْئًا، وَهُوَ يُطِيبُ بِنَفْسِ الْمَرِيضِ". (ت,جه)', 'അബൂസഈദുൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഒരു രോഗിയുടെ അടുക്കൽ ചെന്നാൽ അവന് ആയുസ്സിൽ പ്രത്യാശ നൽകുക. അത് വിധിയെ തടയില്ലെങ്കിലും രോഗിയുടെ മനസ്സിന് ആശ്വാസം നൽകും." (തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 767, 767, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَادَ رَجُلًا، فَقَالَ: "مَا تَشْتَهِي؟". قَالَ: أَشْتَهِي خُبْزَ بُرٍّ. قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَ عِنْدَهُ خُبْزُ بُرٍّ فَلْيَبْعَثْ إِلَى أَخِيهِ". ثُمَّ قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا اشْتَهَى مَرِيضُ أَحَدِكُمْ شَيْئًا فَلْيُطْعِمْهُ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഒരാളെ സന്ദർശിച്ചു. നബി(സ) ചോദിച്ചു: "എന്തെങ്കിലും ആഗ്രഹമുണ്ടോ?" അയാൾ പറഞ്ഞു: ഗോതമ്പു റൊട്ടി വേണം, നബി(സ) പറഞ്ഞു: "വല്ലവന്റെയും അടുക്കൽ ഗോതമ്പു റോട്ടിയുണ്ടെങ്കിൽ ഈ സഹോദരന് എത്തിച്ചുകൊടുക്കുക." പിന്നെ നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ ആരുടെയെങ്കിലും രോഗി വല്ല ഭക്ഷണത്തിനും ആഗ്രഹം പ്രകടിപ്പിച്ചാൽ അവനെ അത് ഭക്ഷിപ്പിക്കുക." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 767, 767, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ جِبْرِيلَ أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا مُحَمَّدُ، اشْتَكَيْتَ؟ قَالَ: "نَعَمْ". قَالَ: "بِاسْمِ اللهِ أَرْقِيكَ، مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ، مِنْ شَرِّ كُلِّ نَفْسٍ وَعَيْنِ حَاسِدٍ، بِاسْمِ اللهِ أَرْقِيكَ، وَاللهُ يَشْفِيكَ". (ت,جه)', 'അബുസഈദ്(റ): ജിബ്രീൽ(അ) നബി(സ)യെ സമീപിച്ച് ചോദിച്ചു: ഓ മുഹമ്മദ്! അങ്ങ് രോഗിയാണോ? നബി(സ) പറഞ്ഞു: "അതെ". ജിബ്രീൽ(അ) പറഞ്ഞു: "അങ്ങയെ ഉപദ്രവിക്കുന്ന എല്ലാ വസ്തുക്കളിൽ നിന്നും സകല ദുഷ്ട ആത്മാവിൽനിന്നും അസൂയാലുവിന്റെ കണ്ണേറിൽ നിന്നും അങ്ങയെ അല്ലാഹുവിന്റെ നാമം കൊണ്ട് ഞാൻ മന്ത്രിക്കുന്നു. അല്ലാഹുവിന്റെ നാമം കൊണ്ട് ഞാൻ മന്ത്രിക്കുന്നു. അല്ലാഹു അങ്ങയുടെ രോഗം ശമിപ്പിക്കട്ടെ." (തു,ജ)', 'أَبِي سَعِيدٍ', 'അബുസഈദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 767, 768, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ قَالَ: دَخَلْتُ أَنَا وَثَابِتٌ الْبُنَانِيُّ عَلَى أَنَسِ ابْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا، فَقَالَ ثَابِتٌ: يَا أَبَا حَمْزَةَ، اشْتَكَيْتُ. فَقَالَ أَنَسٌ: أَفَلَا أَرْقِيكَ بِرُقْيَةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: بَلَى. قَالَ: "اللَّهُمَّ رَبَّ النَّاسِ، مُذْهِبَ الْبَاسِ، اشْفِ أَنْتَ الشَّافِي، لَا شَافِيَ إِلَّا أَنْتَ، شِفَاءً لَا يُغَادِرُ سَقَمًا". حَسَنٌ صَحِيحٌ. (خ,د,ت)', 'അബ്ദുൽ അസീസുബ്നു സുഹൈബ്(റ): ഞാനും സാബിതും(റ) കൂടി അനസുബ്നു മാലികി(റ)നെ സമീപിച്ചു. സാബിത് പറഞ്ഞു: അബൂഹംസാ, ഞാൻ രോഗിയാണ്. അനസ് പറഞ്ഞു: ഞാൻ നിന്നെ പ്രവാചകന്റെ(സ) മന്ത്രം കൊണ്ട് മന്ത്രിക്കട്ടെ? അദ്ദേഹം പറഞ്ഞു: അതെ. അപ്പോൾ അനസ്(റ) ഇങ്ങനെ മന്ത്രിച്ചു: "ജനങ്ങളുടെ രക്ഷിതാവേ! പ്രയാസം ദൂരീകരിക്കുന്നവനേ, ശമനം നൽകേണമേ. നീയാണ് ശമിപ്പിക്കുന്നവൻ. നീയല്ലാതെ ശമനം നൽകുന്ന മറ്റാരും ഇല്ല. ഒരു രോഗത്തേയും (ശമിപ്പിച്ചിട്ടല്ലാതെ) വിട്ടു കളയാത്ത ശമനം." ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,ദ,തു)', 'عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ قَالَ', 'അബ്ദുൽ അസീസുബ്നു സുഹൈബ്(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 768, 768, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ أَتَى أَخَاهُ الْمُسْلِمَ عَائِدًا مَشَى فِي خَرَافَةِ الْجَنَّةِ حَتَّى يَجْلِسَ، فَإِذَا جَلَسَ غَمَرَتْهُ الرَّحْمَةُ. فَإِنْ كَانَ غُدْوَةً صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُمْسِيَ، وَإِنْ كَانَ مَسَاءً صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُصْبِحَ". (د,جه)', 'അലി(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരാൾ തന്റെ മുസ്ലിമായ സഹോദരന്റെ രോഗം സന്ദർശിക്കാൻ ചെന്നാൽ അവൻ ഇരിക്കുന്നതു വരെ സ്വർഗ്ഗത്തിലെ കായ്ക്കനികളിലൂടെ നടക്കുകയാണ്. ഇരുന്നാൽ അനുഗ്രഹം അവനെ ആവരണം ചെയ്യുകയായി. അത് രാവിലെയാണെങ്കിൽ വൈകുന്നേരം വരെ എഴുപതിനായിരം മലക്കുകൾ അവനു വേണ്ടി പ്രാർത്ഥിക്കും. വൈകുന്നേരമാണെങ്കിൽ പ്രഭാതം വരെ എഴുപതിനായിരം മലക്കുകൾ അവനു വേണ്ടി പ്രാർത്ഥിച്ചു കൊണ്ടേയിരിക്കും." (ദ,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 768, 768, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ عَادَ مَرِيضًا نَادِي مُنَادٍ مِنَ السَّمَاءِ: طِبْتَ وَطَابَ مَمْشَاكَ، وَتَبَوَّأْتَ مِنَ الْجَنَّةِ مَنْزِلًا". (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു രോഗിയെ സന്ദർശിച്ചാൽ ആകാശത്തു നിന്ന് ഒരാൾ ഇപ്രകാരം വിളിച്ചു പറയും: നീ നല്ലതു ചെയ്തു. നിന്റെ നടത്തം ഗുണമായി ഭവിച്ചു. സ്വർഗ്ഗത്തിൽ നീയൊരു സ്ഥാനം സജ്ജമാക്കി." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 768, 768, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يُصِيبُ الْمُؤْمِنَ شَوْكَةٌ فَمَا فَوْقَهَا إِلَّا رَفَعَهُ اللهُ بِهَا دَرَجَةً، وَحَطَّ عَنْهُ بِهَا خَطِيئَةً". حَسَنٌ صَحِيحٌ. (م,ت)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "ഒരു സത്യവിശ്വാസിക്ക് ഒരു മുള്ള് തറക്കുകയോ, അതിനപ്പുറം വല്ലതും ഏൽക്കുകയോ ആണെങ്കിൽ പോലും അതുമുഖേന അല്ലാഹു അവന്റെ സ്ഥാനം ഉയർത്തുകയും പാപം കുറക്കുകയും ചെയ്യുന്നതാണ്." ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (മു,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 768, 768, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ شَيْءٍ يُصِيبُ الْمُؤْمِنَ مِنْ نَصَبٍ وَلَا حَزَنٍ وَلَا وَصَبٍ، حَتَّى الْهَمِّ يَهُمُّهُ، إِلَّا يُكَفِّرُ اللهُ بِهِ عَنْهُ سَيِّئَاتِهِ". حَسَنٌ. (ق,ت)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "ഒരു സത്യവിശ്വാസിക്ക് വല്ല ക്ഷീണമോ, ദുഃഖമോ, രോഗമോ, അവനെ അലട്ടുന്ന മനോവ്യഥ പോലും ഏൽക്കുന്നപക്ഷം അതുമുഖേന അല്ലാഹു അവന്റെ പാപങ്ങൾ പൊറുക്കാതിരിക്കില്ല." ഹദീസ് ഹസനാണെന്ന് തിർമിദി പറയുന്നു. (ബു,മു,തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 768, 769, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ عَادَ مَرِيضًا لَمْ يَحْضُرْ أَجَلُهُ، فَقَالَ عِنْدَهُ سَبْعَ مِرَارٍ: أَسْأَلُ اللهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ، إِلَّا عَافَاهُ اللهُ مِنْ ذَلِكَ الْمَرَضِ". (د,ت)', 'ഇബ്നു അബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ആയുസ്സിന്റെ കാലാവധി ആസന്നമായിട്ടില്ലാത്ത ഒരു രോഗിയെ സന്ദർശിച്ചു കൊണ്ട് ഒരാൾ അവിടെ വെച്ച് ''മഹത്തായ സിംഹാസനത്തിന്റെ അധിപനും മഹാനുമായ അല്ലാഹുവോട് ഞാൻ നിന്റെ രോഗശമനത്തിന് തേടുന്നു'' എന്ന് ഏഴ് പ്രാവശ്യം പറഞ്ഞാൽ അല്ലാഹു അയാൾക്ക് ആ രോഗത്തിന് ശാന്തി നൽകാതിരിക്കില്ല." (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 769, 769, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنِ ابْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا جَاءَ الرَّجُلُ يَعُودُ مَرِيضًا فَلْيَقُلِ: اللَّهُمَّ اشْفِ عَبْدَكَ، يَنْكَأُ لَكَ عَدُوًّا أَوْ يَمْشِي لَكَ إِلَى جَنَازَةٍ - وَفِي رِوَايَةٍ: إِلَى صَلَاةٍ". (د)', 'ഇബ്നുഅംറ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ ഒരു രോഗിയെ സന്ദർശിക്കാൻ ചെന്നാൽ ഇങ്ങനെ പറയട്ടെ: അല്ലാഹുവേ, നിന്റെ അടിമക്ക് നീ ശമനം നൽകേണമേ! അവൻ നിന്റെ ശത്രുവിനെ നിഗ്രഹിക്കും. നിനക്കുവേണ്ടി ജനാസയെ അനുഗമിക്കും." ഒരു റിപ്പോർട്ടിൽ: "നിസ്കാരത്തിലേക്ക് പോകും" എന്നാണ് വന്നിട്ടുള്ളത്. (ദ)', 'ابْنِ عَمْرٍو', 'ഇബ്നുഅംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 769, 769, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=21), 1, 'وَفِي رِوَايَةٍ: إِلَى صَلَاةٍ". (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَأَلْتُ عَائِشَةَ رَضِيَ اللهُ عَنْهَا فَقُلْتُ: أَيْ أُمَّهْ، أَخْبِرِينِي عَنْ مَرَضِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَتْ: اشْتَكَى فَعَلَقَ يَنْفُثُ، فَجَعَلْنَا نُشَبِّهُ نَفْثَهُ بِنَفْثَةِ آكِلِ الزَّبِيبِ. وَكَانَ يَدُورُ عَلَى نِسَائِهِ، فَلَمَّا ثَقُلَ اسْتَأْذَنَهُنَّ أَنْ يَكُونَ فِي بَيْتِ عَائِشَةَ، وَأَنْ يَدُرْنَ عَلَيْهِ. قَالَتْ: فَدَخَلَ عَلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ بَيْنَ رَجُلَيْنِ، وَرِجْلَاهُ تَخُطَّانِ بِالْأَرْضِ، أَحَدُهُمَا الْعَبَّاسُ. فَحَدَّثْتُ بِهِ ابْنَ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، فَقَالَ: أَتَدْرِي مَنِ الرَّجُلُ الَّذِي لَمْ تُسَمِّهِ عَائِشَةُ؟ هُوَ عَلِيُّ بْنُ أَبِي طَالِبٍ. (ق,د,ت,ن,جه)', 'ഉബൈദുല്ലാഹിബ്നു അബ്ദില്ല(റ): ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചു: ഉമ്മാ! എനിക്ക് നബി(സ)യുടെ രോഗത്തെക്കുറിച്ച് പറഞ്ഞുതരിക. ആഇശ(റ) പറഞ്ഞു: നബി(സ)ക്ക് ശാസതടസ്സമുണ്ടായിരുന്നു. ഉണങ്ങിയ അത്തിപ്പഴം കഴിക്കുമ്പേഴുണ്ടാവുന്ന പ്രയാസം പോലെയാണ് തിരുമേനി(സ)ക്കുള്ളതെന്ന് ഞങ്ങൾക്ക് തോന്നി. തിരുമേനി പത്നിമാരുടെ ഊഴം ചുറ്റുന്നത് പാലിച്ചിരുന്നു. അതിന് പ്രയാസമായപ്പോൾ പത്നിമാരോട് ആഇശ(റ)യുടെ വീട്ടിൽ താമസിക്കാൻ അനുവാദം ചോദിച്ചു. മറ്റു ഭാര്യമാർ നബി(സ)യെ അവിടെ വന്ന് സന്ദർശിക്കണമെന്ന് നിർദ്ദേശിച്ചു. ആഇശ(റ) പറഞ്ഞു: അങ്ങനെ ഭൂമിയിൽ കാൽപാദങ്ങൾ വലിച്ചിഴച്ചുകൊണ്ട് രണ്ടാളുകൾക്കിടയിലായി തിരുമേനി(സ) എന്റെ അടുക്കൽ പ്രവേശിച്ചു. അവരിൽ ഒരാൾ അബ്ബാസ്(റ) ആയിരുന്നു. ഇത് ഞാൻ ഇബ്നുഅബ്ബാസിനോട്(റ) പറഞ്ഞപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ആഇശ(റ) പേര് പരാമർശിക്കാത്ത വ്യക്തി ആരാണെന്ന് അറിയാമോ? അലിയ്യുബ്നു അബൂതാലിബ്(റ) ആയിരുന്നു അത്. (ബു,മു,ദ,തു,ന,ജ)', 'عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ', 'ഉബൈദുല്ലാഹിബ്നു അബ്ദില്ല(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 769, 769, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ عَائِشَةَ بِنْتِ سَعْدٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أَبَاهَا قَالَ: اشْتَكَيْتُ بِمَكَّةَ، فَجَاءَنِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي، وَوَضَعَ يَدَهُ عَلَى جَبْهَتِي، ثُمَّ مَسَحَ صَدْرِي وَبَطْنِي، ثُمَّ قَالَ: "اللَّهُمَّ اشْفِ سَعْدًا، وَأَتْمِمْ لَهُ هِجْرَتَهُ". (ق,د,ت,ن,جه)', 'ആഇശ ബിൻതു സഅ്ദ്(റ): മഹതിയുടെ പിതാവ് പറഞ്ഞു: മക്കയിൽ വെച്ച് എനിക്ക് രോഗം ബാധിച്ചപ്പോൾ പ്രവാചകൻ(സ) എന്നെ സന്ദർശിക്കാൻ വന്നു. തിരുമേനി(സ)യുടെ കരം എന്റെ നെറ്റിയിൽ വെക്കുകയും ശേഷം എന്റെ നെഞ്ചും വയറും തലോടിക്കൊണ്ട് ഇങ്ങനെ പ്രാർത്ഥിക്കുകയും ചെയ്തു. "അല്ലാഹുവേ സഅ്ദിന് ശമനം നൽകണേ, അദ്ദേഹത്തിന്റെ ഹിജ്റ പൂർത്തീകരിക്കേണമേ." (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ بِنْتِ سَعْدٍ', 'ആഇശ ബിൻതു സഅ്ദ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 769, 770, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَطْعِمُوا الْجَائِعَ، وَعُودُوا الْمَرِيضَ، وَفُكُّوا الْعَانِيَ". (خ,د)', 'അബൂമൂസൽ അശ്അരി(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങൾ വിശന്നവനെ ഊട്ടുക, രോഗിയെ സന്ദർശിക്കുക, ബന്ദിയെ മോചിപ്പിക്കുക." (ബു,ദ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 770, 770, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا حَضَرْتُمُ الْمَرِيضَ أَوِ الْمَيِّتَ فَقُولُوا خَيْرًا، فَإِنَّ الْمَلَائِكَةَ يُؤَمِّنُونَ عَلَى مَا تَقُولُونَ". قَالَتْ: فَلَمَّا مَاتَ أَبُو سَلَمَةَ أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللهِ، إِنَّ أَبَا سَلَمَةَ قَدْ مَاتَ. قَالَ: "قُولِي: اللَّهُمَّ اغْفِرْ لِي وَلَهُ، وَأَعْقِبْنِي مِنْهُ عُقْبَى حَسَنَةً". قَالَتْ: فَقُلْتُ، فَأَعْقَبَنِي اللهُ مَنْ هُوَ خَيْرٌ لِي مِنْهُ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,د,ت,ن,جه)', 'ഉമ്മുസലമ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങൾ രോഗിയെ അല്ലെങ്കിൽ മരണം ആസന്നമായ വ്യക്തിയെ സമീപിച്ചാൽ നല്ലത് പറയുക. കാരണം മലക്കുകൾ നിങ്ങൾ പറയുന്നതിന് ആമീൻ പറയുന്നു." ഉമ്മുസലമ(റ) പറയുന്നു: പിന്നീട് അബുസലമ(റ) മരണപ്പെട്ടപ്പോൾ ഞാൻ പ്രവാചകന്റെ(സ) അടുക്കൽ ചെന്ന് പ്രവാചകരേ അബൂസലമ മരണപ്പെട്ടിരിക്കുന്നു എന്ന് പറഞ്ഞു. പ്രവാചകൻ(സ) പറഞ്ഞു: "അല്ലാഹുവേ, എനിക്കും അദ്ദേഹത്തിനും മാപ്പ് നൽകണേ, അദ്ദേഹത്തിന് പകരം ഉത്തമമായത് നീ എനിക്ക് പ്രദാനം ചെയ്യേണമേ" എന്ന് നീ പ്രാർത്ഥിക്കുക. ഞാൻ അപ്രകാരം പ്രാർത്ഥിച്ചു. പിന്നീട് അല്ലാഹു എനിക്ക് അദ്ദേഹത്തേക്കാൾ ഉത്തമനായ മുഹമ്മദി(സ)നെ പകരം നൽകി. (മു,ദ,തു,ന,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 770, 770, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ مَعْقِلِ بْنِ يَسَارٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اقْرَءُوهَا عِنْدَ مَوْتَاكُمْ". يَعْنِي {يس}. (د,جه)', 'മഅ്ഖിലുബ്നു യസാർ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങളിൽ മരണം ആസന്നമായവരുടെ സമീപം നിങ്ങൾ അത് (യാസീൻ) പാരായണം ചെയ്യുക." (ദ,ജ)', 'مَعْقِلِ بْنِ يَسَارٍ', 'മഅ്ഖിലുബ്നു യസാർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 770, 770, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا حَضَرَتْ كَعْبًا الْوَفَاةُ أَتَتْهُ أُمُّ بِشْرٍ بِنْتُ الْبَرَاءِ بْنِ مَعْرُورٍ، فَقَالَتْ: يَا أَبَا عَبْدِ الرَّحْمَنِ، إِنْ لَقِيتَ فُلَانًا فَاقْرَأْ عَلَيْهِ مِنِّي السَّلَامَ. قَالَ: غَفَرَ اللهُ لَكِ يَا أُمَّ بِشْرٍ، نَحْنُ أَشْغَلُ مِنْ ذَلِكِ. قَالَتْ: يَا أَبَا عَبْدِ الرَّحْمَنِ، أَمَا سَمِعْتَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ أَرْوَاحَ الْمُؤْمِنِينَ فِي طَيْرٍ خُضْرٍ، تَعْلُقُ بِشَجَرِ الْجَنَّةِ". قَالَ: بَلَى. قَالَتْ: فَهُوَ ذَاكِ. (ت,ن,جه)', 'കഅബ്ബ്നു മാലിക്(റ): കഅ്ബിന്റെ മരണവേളയിൽ ബറാഅ്ബിൻ മഅ്റൂറിന്റെ മകൾ ഉമ്മുബിശ്ർ അവിടെചെന്ന് ഇങ്ങനെ പറഞ്ഞു: അബൂഅബ്ദുറഹിമാൻ, നീ ഇന്നയാളെ കണ്ടാൽ അദ്ദേഹത്തോട് എന്റെ സലാം പറയുക. അദ്ദേഹം പറഞ്ഞു: ഉമ്മുബിശ്റിന് അല്ലാഹു മാപ്പ് നൽകട്ടെ, നാം അതിനേക്കാൾ സുപ്രധാനവിഷയത്തിലാണ്. മഹതി ചോദിച്ചു: അബൂഅബ്ദുറഹ്മാൻ, പ്രവാചകൻ(സ) ഇങ്ങനെപറയുന്നത് നീ കേട്ടിട്ടില്ലേ? "സത്യവിശ്വാസികളുടെ ആത്മാക്കൾ സ്വർഗത്തിലെ വൃക്ഷങ്ങളിൽ പാറിപ്പറക്കുന്ന ഹരിത വർണ്ണക്കിളികളാണ്." അദ്ദേഹം ''അതെ'' എന്ന് പറഞ്ഞപ്പോൾ, അതു തന്നെയാണ് ഞാൻ പറഞ്ഞത് എന്ന് മഹതി പറഞ്ഞു. (തു,ന,ജ)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅബ്ബ്നു മാലിക്(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 770, 770, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ قَالَ: دَخَلْتُ عَلَى جَابِرِ بْنِ عَبْدِ اللهِ - رَضِيَ اللهُ عَنْهُمَا - وَهُوَ يَمُوتُ، فَقُلْتُ: اقْرَأْ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ السَّلَامَ. (جه)', 'മുഹമ്മദ്ബ്നു മുൻകദിർ(റ): ജാബിറുബിൻ അബ്ദുല്ല(റ)യുടെ മരണവേളയിൽ ഞാൻ അദ്ദേഹത്തെ സമീപിച്ചുകൊണ്ട് ഇങ്ങനെ പറഞ്ഞു: താങ്കൾ അല്ലാഹുവിന്റെ ദൂതരോട് എന്റെ സലാം പറഞ്ഞാലും. (ജ)', 'مُحَمَّدِ بْنِ الْمُنْكَدِرِ قَالَ', 'മുഹമ്മദ്ബ്നു മുൻകദിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 770, 771, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَعَوَّذُ بِهَؤُلَاءِ الْكَلِمَاتِ: "أَذْهِبِ الْبَاسَ رَبَّ النَّاسِ، وَاشْفِ أَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا". فَلَمَّا ثَقُلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ أَخَذْتُ بِيَدِهِ، فَجَعَلْتُ أَمْسَحُهُ وَأَقُولُهَا. فَنَزَعَ يَدَهُ مِنْ يَدِي ثُمَّ قَالَ: "اللَّهُمَّ اغْفِرْ لِي وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى". قَالَتْ: فَكَانَ هَذَا آخِرَ مَا سَمِعْتُ مِنْ كَلَامِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ق,ت,جه)', 'ആഇശ(റ): ഈ വചനങ്ങൾകൊണ്ട് നബി(സ) പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "ജനങ്ങളുടെ നാഥാ, ക്ലേശം അകറ്റി കളയേണമേ. ഒരു രോഗവും അവശേഷിപ്പിക്കാത്ത ശമനം നൽകേണമേ. നീ മാത്രമാണ് ശമനം നൽകുന്നവൻ. നിന്റെ ശമനമല്ലാതെ ശമനമില്ല." നബി(സ)യുടെ മരണരോഗം മൂർഛിക്കുമ്പോൾ ഞാൻ അവിടുത്തെ കരം പിടിച്ചു. അങ്ങനെ തിരുമേനി(സ)യുടെ കരം തടവി ഞാൻ മേൽ വചനങ്ങൾ ഉരുവിട്ടു കൊണ്ടിരുന്നു. പെട്ടെന്ന് തിരുമേനി(സ) എന്റെ കയ്യിൽനിന്ന് അവിടുത്തെ കരം ഊരി എടുത്ത് ഇങ്ങനെ പറഞ്ഞു: "അല്ലാഹുവേ, എനിക്ക് മാപ്പ് അരുളണേ! എന്നെ ഏറ്റവും ഉന്നതനായ സ്നേഹിതനേട് ചേർക്കണേ!". ആഇശ(റ) പറഞ്ഞു: ഇതാണ് ഞാൻ തിരുമേനി(സ)യിൽനിന്ന് അവസാനം കേട്ട സംസാരം. (ബു,മു,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 771, 771, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ نَبِيٍّ يَمْرَضُ إِلَّا خُيِّرَ بَيْنَ الدُّنْيَا وَالْآخِرَةِ". قَالَتْ: فَلَمَّا كَانَ مَرَضُهُ الَّذِي قُبِضَ فِيهِ أَخَذَتْهُ بُحَّةٌ، فَسَمِعْتُهُ يَقُولُ: {مَعَ الَّذِينَ أَنْعَمَ اللهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ} [النساء: ٦٩]. فَعَلِمْتُ أَنَّهُ خُيِّرَ. (ق,ت,جه)', 'ആഇശ(റ): പ്രവാചകൻ(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടു: "ഒരു പ്രവാചകനും മരണനേരത്ത് ഇഹലോകത്തിന്റേയും പരലോകത്തിന്റേയും ഇടയിൽ തിരഞ്ഞെടുപ്പിന് അവസരം നൽകപ്പെടാതിരിക്കില്ല." ആഇശ(റ) പറഞ്ഞു: തിരുമേനി(സ)യുടെ മരണരോഗത്തിൽ പരുത്ത ശബ്ദത്തിൽ അവിടുന്ന് ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ അനുഗ്രഹത്തിന് പാത്രമായ പ്രവാചകന്മാർ, സിദ്ധിഖുകൾ, രക്തസാക്ഷികൾ, സുകൃതവാന്മാർ എന്നിവരുടെ കൂടെ" (അന്നിസാഅ് 69) അപ്പോൾ തിരുമേനി(സ)ക്ക് തിരഞ്ഞെടുക്കാനുള്ള അവസരം നൽകപ്പെട്ടുവെന്ന് ഞാൻ മനസ്സിലാക്കി. (ബു,മു,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], 'النساء: ٦٩', null, 771, 771, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: اجْتَمَعْنَ نِسَاءُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ تُغَادِرْ مِنْهُنَّ امْرَأَةً، فَجَاءَتْ فَاطِمَةُ كَأَنَّ مَشْيَتَهَا مَشْيَةُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "مَرْحَبًا بِابْنَتِي". ثُمَّ أَجْلَسَهَا عَنْ شِمَالِهِ، ثُمَّ إِنَّهُ أَسَرَّ إِلَيْهَا حَدِيثًا، فَبَكَتْ فَاطِمَةُ، ثُمَّ إِنَّهُ سَارَّهَا، فَضَحِكَتْ أَيْضًا، فَقُلْتُ لَهَا: مَا يُبْكِيكِ؟ قَالَتْ: مَا كُنْتُ لِأُفْشِيَ سِرَّ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَقُلْتُ: مَا رَأَيْتُ كَالْيَوْمِ فَرَحًا أَقْرَبَ مِنْ حُزْنٍ. فَقُلْتُ لَهَا حِينَ بَكَتْ: أَخَصَّكِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِحَدِيثٍ دُونَنَا، ثُمَّ تَبْكِينَ؟ وَسَأَلْتُهَا عَمَّا قَالَ، فَقَالَتْ: مَا كُنْتُ لِأُفْشِيَ سِرَّ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. حَتَّى إِذَا قُبِضَ سَأَلْتُهَا عَمَّا قَالَ، فَقَالَتْ: إِنَّهُ كَانَ يُحَدِّثُنِي أَنَّ جِبْرَائِيلَ كَانَ يُعَارِضُهُ بِالْقُرْآنِ فِي كُلِّ عَامٍ مَرَّةً، وَأَنَّهُ عَارَضَهُ بِهِ الْعَامَ مَرَّتَيْنِ: "وَلَا أُرَانِي إِلَّا قَدْ حَضَرَ أَجَلِي، وَأَنَّكِ أَوَّلُ أَهْلِي لُحُوقًا بِي، وَنِعْمَ السَّلَفُ أَنَا لَكِ". فَبَكَيْتُ. ثُمَّ إِنَّهُ سَارَّنِي فَقَالَ: "أَلَا تَرْضَيْنَ أَنْ تَكُونِي سَيِّدَةَ نِسَاءِ الْمُؤْمِنِينَ؟ أَوْ: نِسَاءِ هَذِهِ الْأُمَّةِ". فَضَحِكْتُ لِذَلِكَ. (ق,ت,جه)', 'ആഇശ(റ): പ്രവാചക(സ)ന്റെ പത്നിമാർ എല്ലാവരും ഒരിക്കൽ സമ്മേളിച്ചു. അവരിൽനിന്ന് ആരും ഒഴിവായില്ല. അപ്പോഴാണ് ഫാതിമ(റ)യുടെ വരവ്. അവരുടെ നടത്തം പ്രവാചകന്റേത് പോലെയായിരുന്നു. "എന്റെ മകൾക്ക് സ്വാഗതം" എന്ന് തിരുമേനി(സ) പറഞ്ഞു. പിന്നീട് തിരുമേനി(സ) അവരെ തന്റെ ഇടത് ഭാഗത്ത് ഇരുത്തി. തുടർന്ന് ഫാത്തിമ(റ)യോട് രഹസ്യം പറഞ്ഞപ്പോൾ ഫാത്വിമ(റ) കരഞ്ഞു, പിന്നെ ഏതോ രഹസ്യം പറഞ്ഞപ്പോൾ ഫാത്വിമ(റ) ചിരിക്കുകയും ചെയ്തു. എന്തിനാണ് കരഞ്ഞത് എന്ന് ഞാൻ ഫാത്തിമ(റ)യോട് ചോദിച്ചപ്പോൾ, ഞാൻ പ്രവാചക(സ)ന്റെ രഹസ്യം വെളിപ്പെടുത്തില്ലെന്ന് ഫാത്വിമ(റ) മറുപടി പറഞ്ഞു. ഇന്നത്തേത് പോലെ ദുഃഖസമ്മിശ്രമായ ഒരു സന്തോഷം ഞാൻ കണ്ടിട്ടില്ല, എന്ന് ഞാൻ പറഞ്ഞു. ഫാത്വിമ കരഞ്ഞപ്പോൾ ഞാൻ ചോദിച്ചു: ഞങ്ങളെ കൂടാതെ നിന്നോട് മാത്രം തിരുമേനി(സ) സംസാരിച്ചു. എന്നിട്ട് നീയിപ്പോൾ കരയുകയാണോ? എന്താണ് നബി(സ) പറഞ്ഞതെന്ന് ചോദിച്ചപ്പോൾ ഫാത്വിമ(റ) പറഞ്ഞു: ഞാൻ പ്രവാചകന്റെ(സ) രഹസ്യം വെളിപ്പെടുത്തില്ല. നബി(സ) വഫാതായ ശേഷം ഫാത്തിമ(റ)യോട് നബി(സ) പറഞ്ഞതിനെ കുറിച്ച് ഞാൻ ചോദിച്ചു. അപ്പോൾ ഫാത്വിമ(റ) പറഞ്ഞു: ജിബ്രീൽ(അ) എല്ലാ വർഷവും ഒരു തവണയായിരുന്നു ഖുർആൻ ഓതികേൾപ്പിച്ചിരുന്നത്. എന്നാൽ ഈ വർഷം രണ്ട് തവണ കേൾപ്പിച്ചിരുന്നു. "ഇത് എന്റെ മരണം ആസന്നമായതിന്റെ സൂചനയായിട്ടല്ലാതെ ഞാൻ കാണുന്നില്ല. എന്റെ കുടുംബത്തിൽ നിന്ന് ആദ്യമായി എന്നോട് ചേരുന്നത് നീയായിരിക്കും. ഞാൻ നിനക്ക് ഉദാത്തമായ മുൻഗാമി." ഇത്രയും പ്രവാചകൻ(സ) എന്നോട് പറഞ്ഞപ്പോൾ ഞാൻ കരഞ്ഞു. പിന്നീട് എന്നെ സന്തോഷിപ്പിച്ചുകൊണ്ട് പ്രവാചകൻ(സ) ഇങ്ങനെ പറഞ്ഞു: "സത്യവിശ്വാസിനികളുടെ അല്ലെങ്കിൽ ഈ സമുദായത്തിലെ സ്ത്രീകളുടെ നേതാവ് നീയാവുന്നത് നിനക്ക് ഇഷ്ടമല്ലേ?" അപ്പോഴാണ് ഞാൻ ചിരിച്ചത്. (ബു,മു,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 771, 772, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا رَأَيْتُ أَحَدًا أَشَدَّ عَلَيْهِ الْوَجَعُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ق,ت,جه)', 'ആഇശ(റ): പ്രവാചക(സ)നേക്കാൾ വേദനയുടെ കാഠിന്യം അനുഭവിച്ചവരായി ആരേയും ഞാൻ കണ്ടിട്ടില്ല. (ബു,മു,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 772, 772, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَمُوتُ، وَعِنْدَهُ قَدَحٌ فِيهِ مَاءٌ، فَيُدْخِلُ يَدَهُ فِي الْقَدَحِ ثُمَّ يَمْسَحُ وَجْهَهُ بِالْمَاءِ، ثُمَّ يَقُولُ: "اللَّهُمَّ أَعِنِّي عَلَى سَكَرَاتِ الْمَوْتِ". (ت,جه)', 'ആഇശ(റ): നബി(സ)യുടെ മരണവേളയിൽ അവിടുത്തെ സമീപം ഒരു ജലപാത്രം ഞാൻ കണ്ടു. പാത്രത്തിൽ കൈയിട്ട് കൊണ്ട് തിരുമേനി(സ) ജലംകൊണ്ട് തന്റെ മുഖം തടവുകയും ഇങ്ങനെ പറയുകയും ചെയ്യുന്നുണ്ടായിരുന്നു: "അല്ലാഹുവേ മരണത്തിന്റെ നൊമ്പരത്തിൽ എനിക്ക് ശാന്തിയേകേണമേ." (തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 772, 772, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: آخِرُ نَظْرَةٍ نَظَرْتُهَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَشْفُ السِّتَارَةِ يَوْمَ الِاثْنَيْنِ، فَنَظَرْتُ إِلَى وَجْهِهِ كَأَنَّهُ وَرَقَةُ مُصْحَفٍ، وَالنَّاسُ خَلْفَ أَبِي بَكْرٍ فِي الصَّلَاةِ، فَأَرَادَ أَنْ يَتَحَرَّكَ فَأَشَارَ إِلَيْهِ: أَنِ اثْبُتْ. وَأَلْقَى السِّجْفَ، وَمَاتَ مِنْ آخِرِ ذَلِكَ الْيَوْمِ. (م,ن,جه)', 'അനസുബ്നുമാലിക്(റ): ഞാൻ പ്രവാചക(സ)നെ ദർശിച്ചു. അവസാന ദർശനം മറക്കുള്ളിലൂടെ ഒരു തിങ്കളാഴ്ചയായിരുന്നു. തിരുമേനി(സ)യുടെ മുഖം ഖുർആന്റെ പേജുപോലെ ഞാൻ ദർശിച്ചു. ജനങ്ങൾ അബുബക്റി(റ)ന്റെ പിന്നിൽ നിസ്കരിച്ചുകൊണ്ടിരിക്കുന്നു. അദ്ദേഹം അവിടെ നിന്നും മാറാൻ ഉദ്ദേശിച്ചു. അപ്പോൾ അവിടെ തന്നെ നിൽക്കാൻ തിരുമേനി(സ) സൂചന നൽകി. അവിടുന്ന് വിരി താഴ്തുകയും ആ ദിവസത്തിന്റെ അന്ത്യത്തിൽ തിരുമേനി(സ) വഫാതാവുകയും ചെയ്തു. (മു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 772, 772, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ سَفِينَةَ رَضِيَ اللهُ عَنْهَا، عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي مَرَضِهِ الَّذِي تُوُفِّيَ فِيهِ: "الصَّلَاةَ، وَمَا مَلَكَتْ أَيْمَانُكُمْ". فَمَا زَالَ يَقُولُهَا حَتَّى مَا يَفِيضُ بِهَا لِسَانُهُ. (جه)', 'സഫീന(റ), ഉമ്മുസലമ(റ): തിരുമേനി(സ) മരണാസന്ന രോഗത്തിൽ ആയിരിക്കവെ "നിസ്കാരത്തിന്റെ കാര്യം ശ്രദ്ധിക്കണേ, അടിമകളുടെയും" എന്നിങ്ങനെ പറയാറുണ്ടായിരുന്നു. പ്രവാചക(സ)ന്റെ നാവ് വാചാലമാകുമാറ് അത് പ്രവാചകൻ(സ) ഉരുവിട്ടുകൊണ്ടേയിരുന്നു. (ജ)', 'سَفِينَةَ', 'സഫീന(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 772, 772, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنِ الْأَسْوَدِ قَالَ: ذَكَرُوا عِنْدَ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّ عَلِيًّا رَضِيَ اللهُ عَنْهُ كَانَ وَصِيًّا. فَقَالَتْ: مَتَى أَوْصَى إِلَيْهِ؟ فَلَقَدْ كُنْتُ مُسْنِدَتَهُ إِلَى صَدْرِي - أَوْ إِلَي حَجْرِي - فَدَعَا بِالطَّسْتِ، فَلَقَدِ انْخَنَثَ فِي حَجْرِي فَمَاتَ، وَمَا شَعَرْتُ بِهِ، فَمَتَى أَوْصَى صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ (ق,ت,جه)', 'അസ്വദ്(റ): അലി(റ) പ്രവാചക(സ)ന്റെ ഒസ്യൃത്തവകാശി (നബി(സ)യുടെ ശേഷം മുസ്ലിംകളുടെ ഖലീഫ ആകാൻ പ്രവാചകൻ(സ) വസിയ്യത്ത് ചെയ്ത ആൾ) ആണെന്ന് ആഇശ(റ)യോട് പറഞ്ഞപ്പോൾ അവർ ചോദിച്ചു: എപ്പോഴാണ് വസിയ്യത്ത് ചെയ്തത്? ഞാൻ എന്റെ നെഞ്ചിലേക്ക്, (മടിയിലേക്ക്) തിരുമേനി(സ)യെ ചാരി വെച്ചിരിക്കുകയായിരുന്നു. ഒരു പാത്രം ആവശ്യപ്പെട്ടു. അങ്ങനെ എന്റെ മടിയിൽ ചാഞ്ഞ് കൊണ്ടാണ് തിരുമേനി(സ) മരിച്ചത്. അപ്പോൾ അങ്ങിനെ ഒരു വസിയ്യത്ത് ചെയ്ത കാര്യം എനിക്കറിയില്ല. പിന്നെ എപ്പോഴാണ് പ്രവാചകൻ(സ) അത്തരുണത്തിൽ വസിയ്യത്ത് ചെയതത്? (ബു,മു,തു,ജ)', 'الْأَسْوَدِ قَالَ', 'അസ്വദ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 773, 773, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ غُلَامًا مِنَ الْيَهُودِ كَانَ مَرِضَ، فَأَتَاهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُهُ، فَقَعَدَ عِنْدَ رَأْسِهِ فَقَالَ لَهُ: "أَسْلِمْ". فَنَظَرَ إِلَى أَبِيهِ وَهُوَ عِنْدَ رَأْسِهِ، فَقَالَ لَهُ أَبُوهُ: أَطِعْ أَبَا الْقَاسِمِ. فَأَسْلَمَ، فَقَامَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَقُولُ: "الْحَمْدُ لِلَّهِ الَّذِي أَنْقَذَهُ بِي مِنَ النَّارِ". (خ,د)', 'അനസ്(റ): ഒരു യഹൂദിയായ കുട്ടി രോഗിയായി. നബി(സ) അവന്റെ രോഗം സന്ദർശിച്ചു. നബി(സ) അവന്റെ തലക്കടുത്തിരുന്നു. എന്നിട്ട് നബി(സ) അവനോട് പറഞ്ഞു: "നീ മുസ്ലിമാകൂ." അപ്പോൾ അവൻ അവന്റെ പിതാവിന്റെ മുഖത്തേക്ക് നോക്കി. അപ്പോൾ പിതാവ് പറഞ്ഞു: അബുൽ ഖാസിമിനെ നീ അനുസരിക്കുക. അങ്ങനെ അവൻ മുസ്ലിമായി. നബി(സ) ഇങ്ങനെ പറഞ്ഞുകൊണ്ട് അവിടെ നിന്ന് പുറത്തുവന്നു: "അവനെ നരകത്തിൽ നിന്ന് ഞാൻ കാരണം രക്ഷിച്ച അല്ലാഹുവിന് സർവ്വസ്തുതിയും." (ബു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 773, 773, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي، لَيْسَ بِرَاكِبِ بَغْلٍ وَلَا بِرْذَوْنٍ. (خ,د,ت)', 'ജാബിർ(റ): കോവർ കഴുതയിലോ, കുതിരയിലോ, കയറാതെ വന്ന് നബി(സ) എന്നെ സന്ദർശിക്കാറുണ്ടായിരുന്നു. (ബു,ദ,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 773, 773, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ، وَعَادَ أَخَاهُ الْمُسْلِمَ مُحْتَسِبًا، بُوعِدَ مِنْ جَهَنَّمَ مَسِيرَةَ سَبْعِينَ خَرِيفًا". قِيلَ: يَا أَبَا حَمْزَةَ، وَمَا الْخَرِيفُ؟ قَالَ: الْعَامُ. (د)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും നന്നായി വുളു ചെയ്തു അല്ലാഹുവിൽ നിന്നുള്ള പ്രതിഫലം കാംക്ഷിച്ച് തന്റെ മുസ്ലിം സഹോദരന്റെ അടുക്കൽ രോഗസന്ദർശനം നടത്തിയാൽ എഴുപത് ഖരീഫ് ദൂരം അവർ നരകത്തിൽ നിന്ന് അകറ്റപ്പെടും." അനസി(റ)നോട് ഒരാൾ ചോദിച്ചു. അബൂഹംസേ എന്താണ് ഖരീഫ് (കൊണ്ട് ഉദ്ദേശിക്കുന്നത്)? അദ്ദേഹം പറഞ്ഞു: വർഷം. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 773, 773, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: مَا مِنْ رَجُلٍ يَعُودُ مَرِيضًا مُمْسِيًا إِلَّا خَرَجَ مَعَهُ سَبْعُونَ أَلْفَ مَلَكٍ يَسْتَغْفِرُونَ لَهُ حَتَّى يُصْبِحَ، وَكَانَ لَهُ خَرِيفٌ فِي الْجَنَّةِ. وَمَنْ أَتَاهُ مُصْبِحًا خَرَجَ مَعَهُ سَبْعُونَ أَلْفَ مَلَكٍ يَسْتَغْفِرُونَ لَهُ حَتَّى يُمْسِيَ، وَكَانَ لَهُ خَرِيفٌ فِي الْجَنَّةِ. وَفِي رِوَايَةٍ: عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، بِمَعْنَاهُ، لَمْ يَذْكُرِ الْخَرِيفَ. وَفِي رِوَايَةٍ: جَاءَ أَبُو مُوسَى رَضِيَ اللهُ عَنْهُ إِلَى الْحَسَنِ بْنِ عَلِيٍّ يَعُودُهُ. قَالَ أَبُو دَاوُدَ: وَسَاقَ مَعْنَى الْحَدِيثِ. قَالَ أَبُو دَاوُدَ: أُسْنِدَ هَذَا عَنْ عَلِيٍّ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، مِنْ غَيْرِ وَجْهٍ صَحِيحٍ. (د,جه)', 'അലി(റ): ആരെങ്കിലും വൈകുന്നേരം ഒരു രോഗിയെ സന്ദർശിച്ചാൽ നിശ്ചയമായും എഴുപതിനായിരം മലക്കുകൾ അവന്റെ കൂടെ പുറപ്പെടും. നേരം വെളുക്കും വരെ അവർ അവന് വേണ്ടി പാപമോചനം തേടും. അവന് സ്വർഗ്ഗത്തിലൊരു വസന്തമുണ്ടാകും. ആരെങ്കിലും രാവിലെ ഒരു രോഗിയെ സന്ദർശിച്ചാൽ ഉറപ്പായിട്ടും അവന്റെ കൂടെ എഴുപതിനായിരം മലക്കുകൾ പുറപ്പെടും. അവർ അവന്ന് പൊറുക്കലിനെ തേടും. സ്വർഗ്ഗത്തിലെ ഒരു വസന്തകാലം അവന് വേണ്ടി ലഭിക്കുകയും ചെയ്യും. മറ്റൊരു റിപ്പോർട്ടിൽ (ഇബ്നുമാജയുടെ) അലി(റ)യിൽനിന്ന് ഇതേ അർത്ഥമുള്ള ഒരു ഹദീസ് വന്നിട്ടുണ്ട്. അതിൽ ഖരീഫ് (വസന്തം) എന്ന വാക്ക് വന്നിട്ടില്ല. മറ്റൊരു റിപ്പോർട്ടിൽ: അബൂമൂസാ(റ) ഹസനുബുനു അലി(റ)യുടെ രോഗം സന്ദർശിച്ചു എന്നുണ്ട്. അബൂദാവൂദ് പറയുന്നു: മുൻ ഹദീസിൽ വന്ന അതേ ആശയത്തിലുള്ള സനദ് തുടർന്നു പറഞ്ഞു. അബൂദാവൂദ് പറയുന്നു: ഈ ഹദീസിൽ അലി(റ)യെ നബി(സ)യിലേക്ക് ചേർത്തി ഉദ്ധരിച്ചത് സ്വഹീഹല്ലാത്ത വജ്ഹിലൂടെയാണ്. (ദ,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 774, 774, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=40), 1, 'وَفِي رِوَايَةٍ: عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، بِمَعْنَاهُ، لَمْ يَذْكُرِ الْخَرِيفَ.', 'മറ്റൊരു നിവേദനിൽ (ഇബ്നുമാജയുടെ) അലി(റ)യിൽനിന്ന് ഇതേ അർത്ഥമുള്ള ഒരു ഹദീസ് വന്നിട്ടുണ്ട്. അതിൽ ഖരീഫ് (വസന്തം) എന്ന വാക്ക് വന്നിട്ടില്ല.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=40), 2, 'وَفِي رِوَايَةٍ: جَاءَ أَبُو مُوسَى رَضِيَ اللهُ عَنْهُ إِلَى الْحَسَنِ بْنِ عَلِيٍّ يَعُودُهُ. قَالَ أَبُو دَاوُدَ: وَسَاقَ مَعْنَى الْحَدِيثِ. قَالَ أَبُو دَاوُدَ: أُسْنِدَ هَذَا عَنْ عَلِيٍّ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، مِنْ غَيْرِ وَجْهٍ صَحِيحٍ. (د,جه)', 'മറ്റൊരു നിവേദനിൽ: അബൂമൂസാ(റ) ഹസനുബുനു അലി(റ)യുടെ രോഗം സന്ദർശിച്ചു എന്നുണ്ട്. അബൂദാവൂദ് പറയുന്നു: മുൻ ഹദീസിൽ വന്ന അതേ ആശയത്തിലുള്ള സനദ് തുടർന്നു പറഞ്ഞു. അബൂദാവൂദ് പറയുന്നു: ഈ ഹദീസിൽ അലി(റ)യെ നബി(സ)യിലേക്ക് ചേർത്തി ഉദ്ധരിച്ചത് സ്വഹീഹല്ലാത്ത വജ്ഹിലൂടെയാണ്. (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا أُصِيبَ سَعْدُ بْنُ مُعَاذٍ رَضِيَ اللهُ عَنْهُ يَوْمَ الْخَنْدَقِ، رَمَاهُ رَجُلٌ فِي الْأَكْحَلِ، فَضَرَبَ عَلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَيْمَةً فِي الْمَسْجِدِ لِيَعُودَهُ مِنْ قَرِيبٍ. (ق,د,ن)', 'ആഇശ(റ): ഖൻദഖ് ദിവസം സഅ്ദുബ്നു മുആദി(റ)ന് അക്ഹലുകാരനായ ഒരാളുടെ കുന്തം കൊണ്ട് പരിക്കേറ്റപ്പോൾ അദ്ദേഹത്തെ അടുത്ത് നിന്ന് സന്ദർശിക്കാനായി നബി(സ) പള്ളിക്കടുത്ത് ഒരു ടെന്റ് കെട്ടി. (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 774, 774, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُ قَالَ: عَادَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ وَجَعٍ كَانَ بِعَيْنِي. (د)', 'സൈദുബ്നു അർഖം(റ): എനിക്ക് കണ്ണു വേദനയുണ്ടായപ്പോൾ നബി(സ) എന്നെ സന്ദർശിച്ചു. (ദ)', 'زَيْدِ بْنِ أَرْقَمَ', 'സൈദുബ്നു അർഖം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 774, 774, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أُمِّ الْعَلَاءِ رَضِيَ اللهُ عَنْهَا قَالَتْ: عَادَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا مَرِيضَةٌ، فَقَالَ: "أَبْشِرِي يَا أُمَّ الْعَلَاءِ، فَإِنَّ مَرَضَ الْمُسْلِمِ يُذْهِبُ اللهُ بِهِ خَطَايَاهُ كَمَا تُذْهِبُ النَّارُ خَبَثَ الذَّهَبِ وَالْفِضَّةِ". (د)', 'ഉമ്മുൽ അലാഅ്(റ): ഞാൻ രോഗിയായിരിക്കെ റസൂൽ(സ) എന്നെ സന്ദർശിച്ചു. എന്നിട്ട് പറഞ്ഞു: "ഉമ്മുൽ അലാഅേ, സന്തോഷിച്ചു കൊള്ളുക. കാരണം മുസ്ലിമിന്റെ രോഗം കൊണ്ട് അല്ലാഹു പാപങ്ങൾ ഇല്ലാതാക്കും. തീ സ്വർണ്ണത്തിലേയും വെള്ളിയിലേയും അഴുക്ക് ഇല്ലാതാക്കുന്നതു പോലെ." (ദ)', 'أُمِّ الْعَلَاءِ', 'ഉമ്മുൽ അലാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 774, 774, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قُلْتُ: يَا رَسُولَ اللهِ، إِنِّي لَأَعْلَمُ أَشَدَّ آيَةٍ فِي الْقُرْآنِ، قَالَ: "أَيَّةُ آيَةٍ يَا عَائِشَةُ". قَالَتْ: قَوْلُ اللهِ تَعَالَى: {مَنْ يَعْمَلْ سُوءًا يُجْزَ بِهِ} [النساء: ١٢٣]. قَالَ: "أَمَا عَلِمْتِ - يَا عَائِشَةُ - أَنَّ الْمُؤْمِنَ تُصِيبُهُ النَّكْبَةُ أَوِ الشَّوْكَةُ فَيُكَافَأُ بِأَسْوَإِ عَمَلِهِ، وَمَنْ حُوسِبَ عُذِّبَ". قَالَتْ: أَلَيْسَ اللهُ يَقُولُ: {فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا} [الانشقاق: ٨]؟ قَالَ: "ذَاكُمُ الْعَرْضُ يَا عَائِشَةُ، مَنْ نُوقِشَ الْحِسَابَ عُذِّبَ". (ق,د)', 'ആഇശാ(റ): ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഖുർആനിലെ ഏറ്റവും കഠിനമായ ആയത്ത് എനിക്കറിയാം. നബി(സ) ചോദിച്ചു: "ഏതു ആയത്താണ് ആഇശാ!" അവർ പറഞ്ഞു: ''ആർ തെറ്റ് ചെയ്തുവോ അതിന്റെ പ്രതിഫലം അവന് ലഭിക്കും'' (അന്നിസാഅ്: 123) എന്ന ആയത്ത്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ആഇശാ നീ അറിഞ്ഞിട്ടില്ലേ? ഒരു വിശ്വാസിക്ക് ഒരു മുള്ള് തറക്കുന്നത് അവന്റെ ഏറ്റവും മോശമായ പ്രവർത്തനത്തിന് പകരമാകും. ആർ വിചാരണചെയ്യപ്പെട്ടുവോ അവൻ ശിക്ഷിക്കപ്പെടും." ആഇശ(റ) ചോദിച്ചു: അല്ലാഹു പറഞ്ഞിട്ടില്ലേ? ''ചെറിയ വിചാരണ ചെയ്യപ്പെടു''മെന്ന് (അൽ ഇൻശിഖാഖ്: 8) നബി(സ) പറഞ്ഞു: "ആഇശാ, അത് വെറും ഒരു കൂടി കാഴ്ചയായിരിക്കും. ആർ വിചാരണയെ നേരിടുന്നുവോ അവൻ ശിക്ഷിക്കപ്പെടും." (ബു,മു,ദ)', 'عَائِشَةَ', 'ആഇശാ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], 'الانشقاق: ٨', null, 774, 775, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُ الْمَرِيضَ، وَيَشْهَدُ الْجَنَازَةَ، وَيَرْكَبُ الْحِمَارَ، وَيُجِيبُ دَعْوَةَ الْعَبْدِ. وَكَانَ يَوْمَ بَنِي قُرَيْظَةَ عَلَى حِمَارٍ مَخْطُومٍ بِحَبْلٍ مِنْ لِيفٍ، عَلَيْهِ إِكَافٌ مِنْ لِيفٍ. (ت,جه)', 'അനസുബ്നുമാലിക്(റ): നബി(സ)രോഗികളെ സന്ദർശിച്ചിരുന്നു. ജനാസ സംസ്കരണത്തിന് പങ്കെടുത്തിരുന്നു. കുതിരപ്പുറത്ത് കയറിയിരുന്നു. അടിമ വിളിച്ചാൽ മറുപടി പറയുമായിരുന്നു. ബനുഖുറൈള യുദ്ധത്തിന്റെ ദിവസം നബി(സ) ഈത്തപ്പന നാരുകൊണ്ട് മൂക്കുകയറിട്ട ഒരു കഴുതപ്പുറത്തായിരുന്നു. ഈത്തപ്പന നാരുകൊണ്ടുള്ള ഒരു ഇരിപ്പിടം അതിനു പുറത്തുണ്ടായിരുന്നു. (തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 775, 775, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ عَمْرِو بْنِ حَزْمٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "مَا مِنْ مُؤْمِنٍ يُعَزِّي أَخَاهُ بِمُصِيبَةٍ إِلَّا كَسَاهُ اللهُ سُبْحَانَهُ مِنْ حُلَلِ الْكَرَامَةِ يَوْمَ الْقِيَامَةِ". (جه)', 'അംറുബ്നു ഹസ്മ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഒരു സത്യവിശ്വാസി തന്റെ സഹോദരന് അത്യാഹിതം വരുമ്പോൾ ആശ്വസിപ്പിക്കുന്ന പക്ഷം അല്ലാഹു അദ്ദേഹത്തിന് പുനരുദ്ധാരണ നാളിൽ മഹത്വത്തിന്റെ ഉടയാടകൾ അണിയിക്കുന്നതാണ്." (ജ)', 'عَمْرِو بْنِ حَزْمٍ', 'അംറുബ്നു ഹസ്മ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 775, 775, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ عَزَّى مُصَابًا فَلَهُ مِثْلُ أَجْرِهِ". (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസഊദ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഒരു വിപത്തിൽ കുടുങ്ങിയവനെ ഒരാൾ ആശ്വസിപ്പിച്ചാൽ അയാൾക്കുള്ളത് പോലുള്ള പ്രതിഫലം ഇയാൾക്കും ലഭിക്കുന്നതാണ്." (തു,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസഊദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 775, 775, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَرْسَلَتِ ابْنَةُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَيْهِ: إِنَّ ابْنًا لِي قُبِضَ فَأْتِنَا. فَأَرْسَلَ يُقْرِئُ السَّلَامَ وَيَقُولُ: "إِنَّ لِلَّهِ مَا أَخَذَ وَلَهُ مَا أَعْطَى، وَكُلُّ شَيْءٍ عِنْدَ اللهِ بِأَجَلٍ مُسَمًّى، فَلْتَصْبِرْ وَلْتَحْتَسِبْ". فَأَرْسَلَتْ إِلَيْهِ تُقْسِمُ عَلَيْهِ لَيَأْتِيَنَّهَا، فَقَامَ وَمَعَهُ سَعْدُ بْنُ عُبَادَةَ وَمُعَاذُ بْنُ جَبَلٍ وَأُبَيُّ بْنُ كَعْبٍ وَزَيْدُ بْنُ ثَابِتٍ وَرِجَالٌ، فَرُفِعَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الصَّبِيُّ وَنَفْسُهُ تَتَقَعْقَعُ، فَفَاضَتْ عَيْنَاهُ، فَقَالَ سَعْدٌ: يَا رَسُولَ اللهِ، مَا هَذَا؟ قَالَ: "هَذِهِ رَحْمَةٌ يَجْعَلُهَا اللهُ فِي قُلُوبِ عِبَادِهِ، وَإِنَّمَا يَرْحَمُ اللهُ مِنْ عِبَادِهِ الرُّحَمَاءَ". (ق,د,ن,جه)', 'ഉസാമത്തുബ്നു സൈദ്(റ): തന്റെ മകൻ മരണപ്പെട്ടിരിക്കുന്നുവെന്നും, ഇവിടെ വരെ വരണമെന്നും പ്രവാചക പുത്രി നബി(സ)യെ വിവരമറിയിച്ചു. സലാം പറഞ്ഞയച്ചുകൊണ്ട് നബി(സ) അറിയിച്ചു: "അല്ലാഹു നൽകുന്നതും തിരിച്ചെടുക്കുന്നതും അവന്റേതാണ്. എല്ലാ ജീവജാലങ്ങൾക്കും അല്ലാഹു ഒരു നിർണ്ണിത അവധി നിശ്ചയിച്ചിരിക്കുന്നു. അതുകൊണ്ട് നീ ക്ഷമിക്കുക. പ്രതിഫലം കാംക്ഷിക്കുക." വീണ്ടും അവർ അല്ലാഹുവിനെ മുൻനിർത്തിക്കൊണ്ട് നബി(സ)യോട് വരാൻ ആവശ്യപ്പെട്ട് വിവരം അറിയിച്ചു. അങ്ങനെ പ്രവാചകർ(സ) സഅദുബ്നു ഉബാദ(റ), മുആദുബ്നു ജബൽ(റ), ഉബയ്യുബ്നു കഅ്ബ്(റ), സൈദുബ്നു സാബിത്(റ) എന്നിവരെയും മറ്റു ചിലരെയും കൂട്ടി അവിടെ ചെന്നു. ശേഷം കുഞ്ഞിനെ പ്രവാചകന് എടുത്ത് കാണിച്ചു. തിരുമേനി(സ)യുടെ മനസ്സ് വിതുമ്പി, കണ്ണുകൾ നിറഞ്ഞു. അപ്പോൾ സഅദ്(റ) ചോദിച്ചു: എന്താണിത് പ്രവാചകരേ? നബി(സ) പറഞ്ഞു: "അല്ലാഹു അടിമകളുടെ ഹൃദയങ്ങളിൽ നിക്ഷേപിച്ച കാരുണ്യത്തിന്റെ നിദർശനമാണിത്. അവന്റെ അടിമകളിൽ നിന്ന് കാരുണ്യവാന്മാരോട് മാത്രമേ അവൻ കരുണ കാണിക്കുകയുള്ളൂ." (ബു,മു,ദ,ന,ജ)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമത്തുബ്നു സൈദ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 776, 776, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَتَى عَلَى امْرَأَةٍ تَبْكِي عَلَى صَبِيٍّ لَهَا، فَقَالَ لَهَا: "اتَّقِي اللهَ وَاصْبِرِي". فَقَالَتْ: وَمَا تُبَالِي بِمُصِيبَتِي. فَلَمَّا ذَهَبَ قِيلَ لَهَا: إِنَّهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَخَذَهَا مِثْلُ الْمَوْتِ، فَأَتَتْ بَابَهُ، فَلَمْ تَجِدْ عَلَى بَابِهِ بَوَّابِينَ، فَقَالَتْ: يَا رَسُولَ اللهِ لَمْ أَعْرِفْكَ، فَقَالَ: "إِنَّمَا الصَّبْرُ عِنْدَ أَوَّلِ صَدْمَةٍ". أَوْ قَالَ: "عِنْدَ أَوَّلِ الصَّدْمَةِ". (ق,د,ت,ن,جه)', 'അനസ്ബ്നു മാലിക്(റ): കുഞ്ഞ് മരിച്ചതിന്റെ പേരിൽ കരയുന്ന ഒരു സ്ത്രീയുടെ അടുക്കൽ ചെന്ന് നബി(സ) പറഞ്ഞു: "നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുക, ക്ഷമിക്കുക." അവൾ പറഞ്ഞു: എന്റെ ദുരിതത്തിൽ നിങ്ങൾക്കെന്ത്? നബി(സ) നടന്നു നീങ്ങിയപ്പോൾ അത് പ്രവാചകനായിരുന്നുവെന്ന് ആ സ്ത്രീയെ വിവരം ധരിപ്പിച്ചു. അവൾക്ക് മരണം പോലെ ബുദ്ധിമുട്ട് അനുഭവപ്പെട്ടു. അവർ നബി(സ)യുടെ കവാടത്തിൽ ചെന്നപ്പോൾ അവിടെ പാറാവുകാരൊന്നും ഉണ്ടായിരുന്നില്ല. അവർ നബി(സ)യോട് പറഞ്ഞു: നിങ്ങളായിരുന്നെന്ന് എനിക്കറിയില്ലായിരുന്നു." നബി(സ) പറഞ്ഞു: "വിപത്തിന്റെ പ്രാഥമിക ഘട്ടത്തിലാണ് സഹനം വേണ്ടത്." അല്ലെങ്കിൽ, "ആ വിപത്തിന്റെ പ്രാരംഭദശയിൽ എന്നാണ് പ്രവാചകൻ(സ) പറഞ്ഞത്." (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്ബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 776, 776, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ قُرَّةَ بْنِ إِيَاسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ ابْنٌ لَهُ، فَقَالَ لَهُ: "أَتُحِبُّهُ؟" فَقَالَ: أَحَبَّكَ اللهُ كَمَا أُحِبُّهُ. فَمَاتَ فَفَقَدَهُ فَسَأَلَ عَنْهُ، فَقَالَ: "مَا يَسُرُّكَ أَنْ لَا تَأْتِيَ بَابًا مِنْ أَبْوَابِ الْجَنَّةِ إِلَّا وَجَدْتَهُ عِنْدَهُ، يَسْعَى يَفْتَحُ لَكَ". (ق,د,ن,جه)', 'ഖുർറതുബ്നു ഇയാസ്(റ): ഒരാൾ തന്റെ മകനോടൊപ്പം നബി(സ)യെ സമീപിച്ചു. നബി(സ) ചോദിച്ചു: "നിങ്ങൾ മകനെ സ്നേഹിക്കുന്നുവോ?" അദ്ദേഹം പറഞ്ഞു: ഞാൻ ഇവനെ സ്നേഹിക്കുന്നപോലെ അല്ലാഹു അങ്ങയെ സ്നേഹിക്കട്ടെ. പിന്നീട് മകൻ മരണപ്പെട്ട് നഷ്ടം സഹിക്കുന്ന അദ്ദേഹം തിരുമേനി(സ)യോട് അതിനെക്കുറിച്ച് ആരാഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "സ്വർഗ്ഗത്തിന്റെ ഓരോ കവാടത്തിലും നിങ്ങൾ ചെല്ലുമ്പോൾ നിങ്ങൾക്ക് കവാടം തുറന്നു തരാൻ അവൻ ഓടി വരുന്നത് കാണാൻ നിങ്ങൾക്ക് കൗതുകമില്ലേ?" (ബു,മു,ദ,ന,ജ)', 'قُرَّةَ بْنِ إِيَاسٍ', 'ഖുർറതുബ്നു ഇയാസ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 776, 776, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَقُولُ اللهُ سُبْحَانَهُ: ابْنَ آدَمَ، إِنْ صَبَرْتَ وَاحْتَسَبْتَ عِنْدَ الصَّدْمَةِ الْأُولَى لَمْ أَرْضَ لَكَ ثَوَابًا دُونَ الْجَنَّةِ". (جه)', 'അബൂഉമാമ(റ): നബി(സ) പറഞ്ഞു: "പരിശുദ്ധനായ അല്ലാഹു പറയുന്നു: മനുഷ്യാ, ദുർഘടത്തിന്റെ പ്രാഥമിക ഘട്ടത്തിൽ നീ സഹനം വരിക്കുകയും, പ്രതിഫലം കാംക്ഷിക്കുകയും ചെയ്താൽ സ്വർഗ്ഗത്തിൽ കുറഞ്ഞ ഒരു പ്രതിഫലവും നിനക്ക് നൽകുന്നത് എനിക്ക് തൃപ്തിയാവില്ല." (ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 777, 777, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ، عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ أَبَا سَلَمَةَ حَدَّثَهَا: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ مُسْلِمٍ يُصَابُ بِمُصِيبَةٍ، فَيَفْزَعُ إِلَى مَا أَمَرَ اللهُ بِهِ مِنْ قَوْلِهِ: {إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ} [البقرة: ١٥٦] اللَّهُمَّ عِنْدَكَ احْتَسَبْتُ مُصِيبَتِي، فَأْجُرْنِي فِيهَا وَعَوِّضْنِي مِنْهَا، إِلَّا آجَرَهُ اللهُ عَلَيْهَا، وَعَاضَهُ خَيْرًا مِنْهَا". قَالَتْ: فَلَمَّا تُوُفِّيَ أَبُو سَلَمَةَ ذَكَرْتُ الَّذِي حَدَّثَنِي عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ. اللَّهُمَّ !عِنْدَكَ احْتَسَبْتُ مُصِيبَتِي هَذِهِ، فَأْجُرْنِي عَلَيْهَا. فَإِذَا أَرَدْتُ أَنْ أَقُولَ: وَعِضْنِي خَيْرًا مِنْهَا، قُلْتُ فِي نَفْسِي: أُعَاضُ خَيْرًا مِنْ أَبِي سَلَمَةَ؟ ثُمَّ قُلْتُهَا، فَعَاضَنِي اللهُ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَآجَرَنِي فِي مُصِيبَتِي. (م,د,جه)', 'ഉമ്മുസലമ(റ)യിൽ നിന്ന് ഉമറുബ്നു അബീസലമ(റ): നബി(സ) പറയുന്നതായി അബൂസലമ(റ) കേട്ടിട്ടുണ്ടെന്ന് അദ്ദേഹം ഉമ്മുസലമ(റ)യോട് പറഞ്ഞു: "ഒരു മുസ്ലിമിന് ഒരു അത്യാഹിതം സംഭവിക്കുകയും ഉടനെ അയാൾ ഇന്നാലില്ലാഹി..... (നാം അല്ലാഹുവിന്നുള്ളതാണ്, നാം അവനിലേക്ക് മടങ്ങേണ്ടവരുമാണ്) (അൽബഖറ 156) എന്ന സൂക്തത്തിലേക്ക് അഭയം പ്രാപിക്കുകയും, നിന്റെ അടുക്കൽ നിന്ന് ഞാൻ എന്റെ ദുരന്തത്തിന്റെ പ്രതിഫലം കാംക്ഷിക്കുന്നു, ഈ ദുരന്തത്തിൽ എനിക്ക് പ്രതിഫലം നൽകുകയും പകരം നൽകുകയും ചെയ്യേണമേ എന്ന് പറയുകയും ചെയ്താൽ, അല്ലാഹു അയാൾക്ക് അതിന്റെ പ്രതിഫലം നൽകുകയും അതിലും ഉദാത്തമായത് പകരം നൽകുകയും ചെയ്യുന്നതാണ്." ഉമ്മുസലമ(റ) പറയുന്നു: അങ്ങനെ (ഭർത്താവ്) അബൂസലമ(റ) മരണപ്പെട്ടപ്പോൾ അദ്ദേഹം നബി(സ)യിൽ ഉദ്ധരിച്ച ഈ ഹദീസ് സ്മരിച്ചു കൊണ്ട് ഞാൻ ഇങ്ങനെ പറഞ്ഞു: നാം അല്ലാഹുവിന്നുള്ളവരാണ്, നാം അവനിലേക്ക് മടങ്ങേണ്ടവരുമാണ്. അല്ലാഹുവേ, നിന്റെ അടുക്കൽ നിന്ന് എന്റെ ഈ ദുരന്തത്തിന്റെ പ്രതിഫലം ഞാൻ കാംക്ഷിക്കുന്നു. ഇതിൽ നീ എനിക്ക് പ്രതിഫലം നൽകേണമേ. ഇതിലും ഉത്തമമായത് പകരം നൽകേണമേ, എന്നുകൂടി പറയാൻ ഞാൻ ഉദ്ദേശിച്ചു. ഞാൻ സ്വയം മനസ്സിൽ മന്ത്രിച്ചു: അബുസലമയേക്കാൾ ഉത്തമരായി ആരെ പകരം നൽകപ്പെടാനാണ്? എന്തായാലും പിന്നെ ഞാൻ അതു കൂടി പറഞ്ഞു. അങ്ങനെ അല്ലാഹു എനിക്ക് മുഹമ്മദി(സ)നെ പകരം നൽകി എന്റെ ദുരന്തത്തിന് പ്രതിഫലമേകി. (മു,ദ,ജ)', 'عُمَرَ بْنِ أَبِي سَلَمَةَ، عَنْ أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], 'البقرة: ١٥٦', null, 777, 777, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنِ الْحُسَيْنِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أُصِيبَ بِمُصِيبَةٍ، فَذَكَرَ مُصِيبَتَهُ، فَأَحْدَثَ اسْتِرْجَاعًا - وَإِنْ تَقَادَمَ عَهْدُهَا - كَتَبَ اللهُ لَهُ مِنَ الْأَجْرِ مِثْلَهُ يَوْمَ أُصِيبَ". [ز: في إسناده ضعيف] (جه)', 'ഹുസൈൻ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾക്ക് മുമ്പൊരിക്കൽ ഒരു ദുരന്തം സംഭവിക്കുകയും പിന്നീട് ആ ദുരന്തത്തെ സ്മരിച്ചു കൊണ്ട് അയാൾ ''ഇന്നാലില്ലാഹി വഇന്നാ ഇലൈഹി റാജിഊൻ'' എന്ന് പറയുകയും ചെയ്താൽ അതിന്റെ കാലം എത്ര ദീർഘിച്ചാലും ദുരന്തം സംഭവിച്ച ദിവസേത്തതു പോലുള്ള പ്രതിഫലം അയാൾക്ക് നൽകപ്പെടുന്നതാണ്." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'الْحُسَيْنِ', 'ഹുസൈൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 777, 777, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: فَتَحَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَابًا بَيْنَهُ وَبَيْنَ النَّاسِ - أَوْ كَشَفَ سِتْرًا - فَإِذَا النَّاسُ يُصَلُّونَ وَرَاءَ أَبِي بَكْرٍ، فَحَمِدَ اللهَ عَلَى مَا رَأَى مِنْ حُسْنِ حَالِهِمْ، رَجَاءَ أَنْ يَخْلُفَهُ اللهُ فِيهِمْ بِالَّذِي رَآهُمْ، فَقَالَ: "يَا أَيُّهَا النَّاسُ، أَيُّمَا أَحَد مِنَ النَّاسِ – أَوْ مِنَ الْمُؤْمِنِينَ – أُصِيبَ بِمُصِيبَةٍ فَلْيَتَعَزَّ بِمُصِيبَتِه بِي عَنِ الْمُصِيبَةِ الَّتِي تُصِيبُهُ بِغَيْرِي، فَإِنَّ أَحَدًا مِنْ أُمَّتِي لَنْ يُصَابَ بِمُصِيبَةٍ بَعْدِي أَشَدَّ عَلَيْهِ مِنْ مُصِيبَتِي". [ز: في إسناده ضعيف] (جه)', 'ആഇശ(റ): നബി(സ) തനിക്കും ജനങ്ങൾക്കുമിടയിലെ കവാടം തുറന്നു അല്ലെങ്കിൽ മറ നീക്കി. അപ്പോൾ ജനങ്ങൾ അബൂബക്കറി(റ)ന്റെ പിന്നിൽ നിസ്കരിക്കുകയാണ്. ഈ നല്ല അവസ്ഥ കണ്ടതിനാലും തനിക്കു ശേഷം താൻ അഭിപ്രായപ്പെടുന്ന ഖലീഫയെ നിശ്ചയിക്കാൻ പോകുന്നുവെന്ന പ്രതീക്ഷയിലും തിരുമേനി(സ) അല്ലാഹുവിനെ സ്തുതിച്ചു. പിന്നെ ഇങ്ങനെ പറഞ്ഞു: "ജനങ്ങളേ, ജനങ്ങളിൽ നിന്ന് (സത്യവിശ്വാസികളിൽ നിന്ന്) ആർക്കെങ്കിലും വല്ല അത്യാഹിതവും സംഭവിക്കുന്നുവെങ്കിൽ എന്റെ നിര്യാണം മൂലമുള്ള അത്യാഹിതത്തെ അപേക്ഷിച്ച് ആർക്ക് സംഭവിക്കുന്ന അത്യാഹിതത്തെയും നിസ്സാരമായി പരിഗണിക്കുക. കാരണം, എന്റെ നിര്യാണം മൂലമുള്ള അത്യാഹിതത്തേക്കാൾ ഭീകരമായ ഒരു അത്യാഹിതവും എനിക്കുശേഷം എന്റെ സമുദായത്തിൽ ഒരാൾക്കും സംഭവിക്കാൻ പോകുന്നില്ല." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്വലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 777, 778, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ أبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إذَا مَاتَ وَلَدُ الْعَبْدِ قَالَ اللهُ لِمَلَائِكَتِه: قَبَضْتُمْ وَلَدَ عَبْدِي؟ فَيَقُولُونَ: نَعَمْ. فَيَقُولُ: قَبَضْتُمْ ثَمَرَةَ فُؤَادِه؟ فَيَقُولُونَ: نَعَمْ. فَيَقُولُ: مَاذَا قَالَ عَبْدِي؟ فَيَقُولُونَ: حَمِدَكَ وَاسْتَرْجَعَ. فَيَقُولُ اللهُ: ابْنُوا لِعَبْدِي بَيْتًا فِي الْجَنَّةِ، وَسَمُّوهُ بَيْتَ الْحَمْدِ". حَسَنٌ. (ت)', 'അബുമൂസൽ അശ്അരി(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഒരു അടിമയുടെ കുട്ടി മരിച്ചാൽ അല്ലാഹു മലക്കുകളോട് ചോദിക്കും. നിങ്ങൾ എന്റെ അടിമയുടെ കുട്ടിയെ പിടിച്ചോ? അവർ പറയും: ഉവ്വ്, അല്ലാഹു വീണ്ടും ചോദിക്കും: നിങ്ങൾ അവന്റെ ഹൃദയത്തിന്റെ കനി കവർന്നോ? അവർ പറയും: അതെ, അല്ലാഹു ചോദിക്കും: എന്റെ അടിമ എന്താണ് പറഞ്ഞത്? അവർ പറയും: അവൻ നിന്നെ സ്തുതിക്കുകയും ഇന്നാലില്ലാഹി...... പറയുകയും ചെയ്തു. അപ്പോൾ അല്ലാഹു പറയും: എങ്കിൽ എന്റെ അടിമക്ക് വേണ്ടി നിങ്ങൾ സ്വർഗത്തിൽ ഒരു വീട് നിർമിക്കുക. അതിന് സ്തുതി ഭവനം എന്ന് നാമകരണം ചെയ്യുക." (ഹദീസ് ഹസനാണ്). (തു)', 'أبِي مُوسَى الْأَشْعَرِيِّ', 'അബുമൂസൽ അശ്അരി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 778, 778, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ عُتْبَةَ بْنِ عَبْد السُّلَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ مُسْلِم يَمُوتُ لَهُ ثَلَاثَةٌ مِنَ الْوَلَدِ – لَمْ يَبْلُغُوا الْحِنْثَ – إِلَّا تَلَقَّوْهُ مِنْ أَبْوَابِ الْجَنَّةِ الثَّمَانِيَةِ، مِنْ أَيِّهَا شَاءَ دَخَلَ. (جه)', 'ഉത്ബതു ഇബ്നുഅബ്ദുസ്സുലമി(റ): പ്രവാചകൻ(സ) പറഞ്ഞതായി ഞാൻ കേട്ടു: "ഒരു മുസ്ലിമിന് മൂന്ന് കൂട്ടികൾ പ്രായപൂർത്തിയാവാതെ മരിക്കുന്നപക്ഷം സ്വർഗ്ഗത്തിൽ എട്ട് കവാടങ്ങളിൽ കൂടി അവർ അവനെ സ്വീകരിക്കാതിരിക്കില്ല. അവൻ ഉദ്ദേശിക്കുന്നതിൽ കൂടി അവൻ പ്രവേശിക്കും." (ജ)', 'عُتْبَةَ بْنِ عَبْد السُّلَمِيِّ', 'ഉത്ബതു ഇബ്നുഅബ്ദുസ്സുലമി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 778, 778, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ مُسْلِمَيْنِ يَتَوَفَّى لَهُمَا ثَلَاثَةٌ مِنَ الْوَلَدِ – لَمْ يَبْلُغُوا الْحِنْثَ – إِلَّا أَدْخَلَهُمُ اللهُ الْجَنَّةَ بِفَضْلِ رَحْمَةِ اللهِ إِيَّاهُمْ". (خ,ن,جه)', 'അനസുബ്ന് മാലിക്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "രണ്ടു മുസ്ലിംകളായ ഇണകൾക്ക് പ്രായപൂർത്തിയാവാതെ മൂന്ന് സന്താനങ്ങൾ മരിക്കുന്നപക്ഷം അവരോടുള്ള കൃപാ കടാക്ഷം നിമിത്തം അല്ലാഹു അവരെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുന്നതാണ്." (ബു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്ന് മാലിക്(റ)', null, null, array['خ','ن','جه']::text[], array['ബു','ന','ജ']::text[], null, null, 778, 778, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَمُوتُ لِأَحَد مِنَ الْمُسْلِمِينَ ثَلَاثَةٌ مِنَ الْوَلَدِ فَتَمَسَّهُ النَّارُ، إِلَّا تَحِلَّةَ الْقَسَمِ". حَسَنٌ صَحِيحٌ. (ق,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "മുസ്ലിംകളിൽ നിന്ന് ഒരാൾക്ക് മൂന്ന് സന്താനങ്ങൾ മരിക്കുന്നപക്ഷം അയാളെ നരകം സ്പർശിക്കുകയില്ല. സത്യത്തിന്റെ ലംഘനം മൂലമല്ലാതെ." ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,മു,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 779, 779, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَدَّمَ ثَلَاثَةً لَمْ يَبْلُغُوا الْحُلُمَ كَانُوا لَهُ حِصْنًا حَصِينًا مِنَ النَّارِ". قَالَ أَبُو ذَرٍّ: قَدَّمْتُ اثْنَيْنِ. قَالَ: "وَاثْنَيْنِ". فَقَالَ أُبَيُّ بْنُ كَعْبٍ، سَيِّدُ الْقُرَّاءِ: قَدَّمْتُ وَاحِدًا؟ فَقَالَ: "وَوَاحِدًا، وَلَكِنْ إِنَّمَا ذَاكَ عِنْدَ الصَّدْمَةِ الْأُولَى". (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "പ്രായപൂർത്തിയാവാത്ത മൂന്ന് സന്താനങ്ങൾ ഒരാൾക്ക് മുന്നോടിയായി മരിച്ചുകഴിഞ്ഞാൽ അവർ അയാൾക്ക് നരകത്തിൽനിന്ന് സംരക്ഷിക്കുന്ന കോട്ടയായി ഭവിക്കുന്നതാണ്." അബൂദർറ് ചോദിച്ചു: എനിക്ക് രണ്ട് പേർ മിരിച്ചല്ലോ, തിരുമേനി(സ) പറഞ്ഞു: "രണ്ടാണെങ്കിലും." അപ്പോൾ ഖുർആൻ ഹൃദിസ്ഥമാക്കിയവരുടെ നേതാവായ ഉബയ്യുബ്നു കഅ്ബ്(റ) ചോദിച്ചു: എനിക്ക് ഒരാൾ മരിച്ചാലോ? തിരുമേനി(സ) പറഞ്ഞു. "ഒന്നാണെങ്കിലും, പക്ഷേ അത് അത്യാഹിതത്തിന്റെ പ്രഥമ ഘട്ടത്തിലായിരിക്കണം എന്ന് മാത്രം." (തു,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 779, 779, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ كَانَ لَهُ فَرَطَانِ مِنْ أُمَّتِي أَدْخَلَهُ اللهُ بِهِمَا الْجَنَّةَ". فَقَالَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: فَمَنْ كَانَ لَهُ فَرَطٌ مِنْ أُمَّتِكَ؟ قَالَ: "وَمَنْ كَانَ لَهُ فَرَطٌ، يَا مُوَفَّقَةُ". قَالَتْ: فَمَنْ لَمْ يَكُنْ لَهُ فَرَطٌ مِنْ أُمَّتِكَ؟ قَالَ: "فَأَنَا فَرَطُ أُمَّتِي، لَنْ يُصَابُوا بِمِثْلِي". حَسَنٌ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിൽ നിന്ന് ഒരാൾക്ക് രണ്ട് സന്താനങ്ങൾ അവന്റെ മുമ്പ് മരിച്ചാൽ അവർ മുഖേന അല്ലാഹു അയാളെ സ്വർഗത്തിൽ പ്രവേശിപ്പിക്കും." ആഇശ(റ) ചോദിച്ചു: താങ്കളുടെ സമുദായത്തിൽ ഒരു കുട്ടിമാത്രം മരിച്ചുപോയയാളോ? നബി(സ) പറഞ്ഞു: "അനുഗ്രഹീതയായവളെ, ഒരു കുട്ടി മരിച്ചവനും (അപ്രകാരമാണ്)." ആഇശ(റ) പറഞ്ഞു: താങ്കളുടെ സമുദായത്തിൽ കുട്ടി മരിച്ചു പോകാത്തവർക്കോ? തിരുമേനി(സ) പറഞ്ഞു: "ഞാനായിരിക്കും എന്റെ സമുദായത്തിന് ആതിഥ്യമരുളുന്നവൻ. എന്റെ കാരണത്താലുള്ള (വഫാത്) വിഷമത്തേക്കാൾ വലിയ വിഷമം അവരാരും അനുഭവിച്ചിട്ടില്ല." (ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു). (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 779, 779, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ عَبْدٍ تُصِيبُهُ مُصِيبَةٌ فَيَقُولُ: إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا، إِلَّا أَجَرَهُ اللهُ فِي مُصِيبَتِهِ وَأَخْلَفَ لَهُ خَيْرًا مِنْهَا". قَالَتْ: فَلَمَّا تُوُفِّيَ أَبُو سَلَمَةَ قُلْتُ كَمَا أَمَرَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْلَفَ اللهُ لِي خَيْرًا مِنْهُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,د)', 'ഉമ്മുസലമ(റ): തിരുമേനി(സ) പറഞ്ഞു: "ആപത്ത് വരുമ്പോൾ ഇന്നാലില്ലാഹി വ ഇന്നാഇലൈഹി റാജിഊൻ (തീർച്ചയായും നാം അല്ലാഹുവിന്റേതാണ്, നാം അവനിലേക്ക് തന്നെ മടക്കപ്പെടും) എന്ന് പറയുകയും അല്ലാഹുവേ ഈ ആപത്തിൽനിന്ന് എനിക്ക് ആഭയം നൽകേണമേ! അതിന് പകരമായി അത്യുത്തമമായതിനെ എനിക്ക് പ്രദാനം ചെയ്യേണമേ എന്ന് പറയുകയും ചെയ്യുന്ന ഏതൊരടിമക്കും അല്ലാഹു ആപത്തിൽ അഭയം നൽകുകയും അതിനേക്കാൾ ഉത്തമമായത് നൽകുകയും ചെയ്യാതിരിക്കില്ല." അവർ തുടർന്നു. അങ്ങനെ അബുസലമ(റ) മരണമടഞ്ഞപ്പോൾ റസൂൽ(സ) എന്നോട് കൽപിച്ച പോലെ ഞാൻ പറഞ്ഞു. അങ്ങനെ അല്ലാഹു എനിക്ക് അദ്ദേഹത്തേക്കാൾ ഉത്തമനായ പ്രവാചകനെ(സ) പ്രദാനം ചെയ്തു. (മു,ദ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 779, 780, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَاتَ ابْنٌ لِأَبِي طَلْحَةَ، وَأَبُو طَلْحَةَ خَارِجٌ، فَلَمَّا رَأَتِ امْرَأَتُهُ أَنَّهُ قَدْ مَاتَ، هَيَّأَتْ شَيْئًا، وَنَحَّتْهُ فِي جَانِبِ الْبَيْتِ، فَلَمَّا جَاءَ أَبُو طَلْحَةَ قَالَ: كَيْفَ الْغُلَامُ؟ قَالَتْ: قَدْ هَدَأَتْ نَفْسُهُ وَأَرْجُو أَنْ يَكُونَ قَدِ اسْتَرَاحَ، فَبَاتَ، فَلَمَّا أَصْبَحَ اغْتَسَلَ، فَلَمَّا أَرَادَ أَنْ يَخْرُجَ أَعْلَمَتْهُ أَنَّهُ قَدْ مَاتَ، فَصَلَّى مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ أَخْبَرَهُ بِمَا كَانَ مِنْهُمَا، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَعَلَّ اللهَ أَنْ يُبَارِكَ لَكُمَا فِي لَيْلَتِكُمَا". قَالَ رَجُلٌ مِنَ الْأَنْصَارِ: فَرَأَيْتُ لَهُ تِسْعَةَ أَوْلَادٍ كُلُّهُمْ قَدْ قَرَؤُوا الْقُرْآنَ. (خ)', 'അനസ്(റ): അബൂത്വൽഹ(റ)യുടെ ഒരു മകൻ മരണപ്പെട്ടു. അബുത്വൽഹ(റ) പുറത്ത് പോയിരിക്കയായിരുന്നു. കുട്ടി മരിച്ചത് തന്റെ ഭാര്യ കണ്ടപ്പോൾ അവൾ അൽപം സജ്ജീകരണങ്ങൾ നടത്തുകയും കുട്ടിയെ വീടിന്റെ ഒരു ഭാഗത്ത് നീക്കിവെക്കുകയും ചെയ്തു. പിന്നീട് അബൂത്വൽഹ വന്നപ്പോൾ കുട്ടിയുടെ അവസ്ഥ ആരാഞ്ഞു. ഭാര്യ പറഞ്ഞു: അവൻ ശാന്തമായിരിക്കുന്നു. അവന് സൗഖ്യമായിരിക്കുമെന്ന് ഞാൻ പ്രതീക്ഷിക്കുന്നു. അങ്ങനെ അദ്ദേഹം അന്തിയുറങ്ങി. പ്രഭാതമായപ്പോൾ കുളിച്ചു. എന്നിട്ട് അദ്ദേഹം പുറത്ത് പോവാൻ ഉദ്ദേശിച്ചപ്പോൾ കുട്ടി മരിച്ചതായി ഭാര്യ അദ്ദേഹത്തെ അറിയിച്ചു. അദ്ദേഹം നബി(സ)യോടൊപ്പം നിസ്കരിക്കുകയും ശേഷം തങ്ങളുടെ വിവരം പറയുകയും ചെയ്തു. നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ രാത്രിയിൽ അല്ലാഹു അനുഗ്രഹിക്കട്ടെ." അൻസാറുകളിൽ നിന്ന് ഒരാൾ പറയുന്നു: പിന്നീട് അദ്ദേഹത്തിന് ഒമ്പത് മക്കൾ ഉണ്ടായത് ഞാൻ കണ്ടിട്ടുണ്ട്. അവർ എല്ലാവരും ഖുർആൻ പഠിച്ചവരായിരുന്നു. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 780, 780, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا جَاءَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَتْلُ ابْنِ حَارِثَةَ وَجَعْفَرٍ وَابْنِ رَوَاحَةَ جَلَسَ يُعْرَفُ فِيهِ الْحُزْنُ، وَأَنَا أَنْظُرُ مِنْ صَائِرِ الْبَابِ، شَقِّ الْبَابِ، فَأَتَاهُ رَجُلٌ فَقَالَ: إِنَّ نِسَاءَ جَعْفَرٍ، وَذَكَرَ بُكَاءَهُنَّ، فَأَمَرَهُ أَنْ يَنْهَاهُنَّ فَذَهَبَ، ثُمَّ أَتَاهُ الثَّانِيَةَ لَمْ يُطِعْنَهُ فَقَالَ: انْهَهُنَّ، فَأَتَاهُ الثَّالِثَةَ فَقَالَ: وَاللهِ لَقَدْ غَلَبْنَنَا يَا رَسُولَ اللهِ، فَزَعَمَتْ أَنَّهُ قَالَ: "فَاحْثُ فِي أَفْوَاهِهِنَّ التُّرَابَ". (ق,د,ن)', 'ആയിശ(റ): ഇബ്നുഹാരിസ(റ), ജഅ്ഫർ(റ), ഇബ്നുറവാഹ(റ) എന്നിവർ വധിക്കപ്പെട്ട വിവരം പ്രവാചകൻ(സ) അറിഞ്ഞപ്പോൾ ദുഃഖം പ്രകടമാവുന്ന നിലയിൽ നബി(സ) ഇരിപ്പിലായി. ഞാൻ വാതിൽ പാളിയിലൂടെ വീക്ഷിക്കുകയായിരുന്നു. തൽസമയം ഒരാൾ അവിടെ വന്ന് ജഅ്ഫറിന്റെ സ്ത്രീകളെയും അവർ കരയുന്ന കാര്യവും പരാമർശിച്ചു. പ്രവാചകൻ(സ) അദ്ദേഹത്തോട് അവരെ തടയാൻ കൽപിച്ചപ്പോൾ അദ്ദേഹം പോയി, രണ്ടാമതും വിന്നിട്ട് അവർ അദ്ദേഹത്തെ അനുസരിക്കുന്നില്ലെന്ന് അദ്ദേഹം നബി(സ)യെ അറിയിച്ചു. പ്രവാചകൻ(സ) പറഞ്ഞു: അവരെ തടയുക. മൂന്നാമതും അദ്ദേഹം വന്നിട്ട് ഇങ്ങനെ പറഞ്ഞു. പ്രവാചകരേ, സത്യമായും ആ സ്ത്രീകൾ നമ്മെ അതിജയിച്ചിരിക്കുകയാണ്. അപ്പോൾ തിരുമേനി(സ) ഇങ്ങനെയാണ് പറഞ്ഞത് എന്ന് ആഇശ(റ) തീർത്തു പറഞ്ഞു: "നീ അവരുടെ വായിൽ മണ്ണ് വാരിയിടുക." (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 780, 780, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ جَابِرِ بْنِ عَتِيكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَاءَ يَعُودُ عَبْدَ اللهِ بْنَ ثَابِتٍ، فَوَجَدَهُ قَدْ غُلِبَ، فَصَاحَ بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يُجِبْهُ، فَاسْتَرْجَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "غُلِبْنَا عَلَيْكَ يَا أَبَا الرَّبِيعِ". فَصَاحَ النِّسْوَةُ وَبَكَيْنَ، فَجَعَلَ ابْنُ عَتِيكٍ يُسَكِّتُهُنَّ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "دَعْهُنَّ، فَإِذَا وَجَبَ فَلَا تَبْكِيَنَّ بَاكِيَةٌ". قَالُوا: وَمَا الْوُجُوبُ يَا رَسُولَ اللهِ؟ قَالَ: "الْمَوْتُ". قَالَتِ ابْنَتُهُ: وَاللهِ إِنْ كُنْتُ لَأَرْجُو أَنْ تَكُونَ شَهِيدًا، فَإِنَّكَ كُنْتَ قَدْ قَضَيْتَ جِهَازَكَ. قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ عَزَّ وَجَلَّ قَدْ أَوْقَعَ أَجْرَهُ عَلَى قَدْرِ نِيَّتِهِ، وَمَا تَعُدُّونَ الشَّهَادَةَ". قَالُوا: الْقَتْلُ فِي سَبِيلِ اللهِ تَعَالَى. قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الشَّهَادَةُ سَبْعٌ سِوَى الْقَتْلِ فِي سَبِيلِ اللهِ: الْمَطْعُونُ شَهِيدٌ، وَالْغَرِقُ شَهِيدٌ، وَصَاحِبُ ذَاتِ الْجَنْبِ شَهِيدٌ، وَالْمَبْطُونُ شَهِيدٌ، وَصَاحِبُ الْحَرِيقِ شَهِيدٌ، وَالَّذِي يَمُوتُ تَحْتَ الْهَدْمِ شَهِيدٌ، وَالْمَرْأَةُ تَمُوتُ بِجُمْعٍ شَهِيدَةٌ". (د,ن,جه)', 'ജാബിറുബ്നു അതീക്(റ): നബി(സ) അബ്ദുല്ലാഹിബ്നു സാബിത്തിന്റെ രോഗം സന്ദർശിക്കാൻ പോയി. നിയന്ത്രണാതീതനായ നിലയിൽ നബി(സ) അദ്ദേഹത്തെ കണ്ടു. റസൂൽ(സ) അദ്ദേഹത്തെ വിളിച്ചു. മറുപടി ലഭിച്ചില്ല. നബി(സ) ''ഇന്നാലില്ലാഹി വ ഇന്നാ ഇലൈഹി റാജിഊൻ'' എന്ന് പറഞ്ഞ ശേഷം പറഞ്ഞു: "അബൂറബീഅേ, നീ ഞങ്ങളുടെ നിയന്ത്രണത്തിനപ്പുറത്തായല്ലോ?" അപ്പോൾ സ്ത്രീകൾ അട്ടഹസിച്ചു കരഞ്ഞു. ഇബ്നു അതീക്(റ) അവരെ നിശബ്ദരാക്കാൻ തുടങ്ങി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവരെ വിട്ടേക്ക്. വുജൂബായാൽ ഒരാളും കണ്ണീരൊലിപ്പിച്ച് കരയരുത്." അവർ ചോദിച്ചു: എന്താണ് അല്ലാഹുവിന്റെ ദൂതരെ വുജൂബ് എന്നാൽ? തിരുമേനി(സ) പറഞ്ഞു: "അത് മരണമാണ്." അദ്ദേഹത്തിന്റെ മകൾ പറഞ്ഞു: അല്ലാഹുവാണെ, താങ്കൾ ശഹീദാകാൻ ഞാൻ ആഗ്രഹിച്ചിരുന്നു. താങ്കൾ ഒരുങ്ങുകയും ചെയ്തിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "അദ്ദേഹത്തിന്റെ ഉദ്ദേശശ്യമനുസരിച്ച് പ്രതിഫലം ലഭിക്കും. എന്തിനേയാണ് നിങ്ങൾ രക്തസാക്ഷിത്തമായി എണ്ണുന്നത്?" അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ മരിക്കൽ എന്ന് അവർ പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള മരണം കൂടാതെ ശഹാദത്ത് ഏഴ് തരം ഉണ്ട്. പ്ലേഗ് ബാധിതൻ ശഹീദാണ്, മുങ്ങിമരിച്ചവൻ ശഹീദാണ്, പക്ഷവാതം പിടിപെട്ട് മരിച്ചവൻ ശഹീദാണ്, ഉദര രോഗം മൂലം മരിച്ചവൻ ശഹീദാണ്, കത്തിമരിച്ചവൻ ശഹീദാണ്, കെട്ടിടം തകർന്ന് മരിച്ചവൻ ശഹീദാണ്, ശിശു വയറ്റിലായിരിക്കെ രക്തസ്രാവം മൂലം മരിച്ചസ്ത്രീ രക്തസാക്ഷിയാണ്." (ദ,ന,ജ)', 'جَابِرِ بْنِ عَتِيكٍ', 'ജാബിറുബ്നു അതീക്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 780, 781, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَكَرَ الطَّاعُونَ فَقَالَ: "بَقِيَّةُ رِجْزٍ – أَوْ عَذَابٍ – أُرْسِلَ عَلَى طَائِفَةٍ مِنْ بَنِي إِسْرَائِيلَ، فَإِذَا وَقَعَ بِأَرْضٍ وَأَنْتُمْ بِهَا فَلَا تَخْرُجُوا مِنْهَا، وَإِذَا وَقَعَ بِأَرْضٍ وَلَسْتُمْ بِهَا فَلَا تَهْبِطُوا عَلَيْهَا". حَسَنٌ صَحِيحٌ. (ق,د,ت)', 'ഉസാമത്ത്ബ്നുസൈദ്(റ): നബി(സ) പ്ലേഗിനെ കുറിച്ച് പറഞ്ഞു: "ബനൂഇസ്റാഈലിലെ ഒരു വിഭാഗത്തിനിറക്കിയ ശിക്ഷയുടെ അവശിഷ്ടമാണത്. നിങ്ങൾ ഏതെങ്കിലും നാട്ടിലായിരിക്കെ അവിടെ പ്ലേഗ് ബാധ ഉണ്ടായാൽ അവിടെ നിന്നും പുറത്തു പോകരുത്. നിങ്ങൾ ഇല്ലാത്തൊരു നാട്ടിലാണതെങ്കിൽ നിങ്ങൾ അങ്ങോട്ട് പോകരുത്." (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ബു,മു,ദ,തു)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമത്ത്ബ്നുസൈദ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 781, 781, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ عَبْدِ اللهِ بْنِ يَسَارٍ قَالَ: كُنْتُ جَالِسًا وَسُلَيْمَانُ بْنُ صُرَدٍ وَخَالِدُ بْنُ عُرْفُطَةَ رَضِيَ اللهُ عَنْهُمَا، فَذَكَرُوا أَنَّ رَجُلًا تُوُفِّيَ مَاتَ بِبَطْنِهِ، فَإِذَا هُمَا يَشْتَهِيَانِ أَنْ يَكُونَا شُهَدَاءَ جَنَازَتِهِ، فَقَالَ أَحَدُهُمَا لِلْآخَرِ: أَلَمْ يَقُلْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ يَقْتُلْهُ بَطْنُهُ فَلَنْ يُعَذَّبَ فِي قَبْرِهِ". فَقَالَ الْآخَرُ: بَلَى. (ن)', 'അബ്ദുല്ലാഹിബ്നു യസാർ(റ): ഞാനും സുലൈമാനുബ്നു സ്വുറദും, ഖാലിദുബ്നു ഉർഫുത്വയും ഇരിക്കുമ്പോൾ ഒരാൾ ഉദരരോഗം കൊണ്ട് മരിച്ചു എന്ന് അവർ പറഞ്ഞു. അപ്പോൾ അവർ രണ്ടാളും ആ ജനാസ കാണാൻ ആഗ്രഹിക്കുന്നുണ്ടായിരുന്നു. അവരിൽ ഒരാൾ മറ്റെയാളോട് പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞിട്ടില്ലേ, "ആരെങ്കിലും ഉദര രോഗം കൊണ്ട് മരിച്ചാൽ അവന് ഖബറിൽ ചോദ്യമുണ്ടാകില്ല." അപ്പോൾ അപരൻ പറഞ്ഞു: അതെ. (ന)', 'عَبْدِ اللهِ بْنِ يَسَارٍ قَالَ', 'അബ്ദുല്ലാഹിബ്നു യസാർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 781, 781, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ عَامِرٍ الرَّامِ رَضِيَ اللهُ عَنْهُ قَالَ: إِنِّي لَبِبِلَادِنَا إِذْ رُفِعَتْ لَنَا رَايَاتٌ وَأَلْوِيَةٌ، فَقُلْتُ: مَا هَذَا؟ قَالُوا: هَذَا لِوَاءُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَتَيْتُهُ وَهُوَ تَحْتَ شَجَرَةٍ قَدْ بُسِطَ لَهُ كِسَاءٌ وَهُوَ جَالِسٌ عَلَيْهِ، وَقَدِ اجْتَمَعَ إِلَيْهِ أَصْحَابُهُ، فَجَلَسْتُ إِلَيْهِمْ، فَذَكَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْأَسْقَامَ فَقَالَ: "إِنَّ الْمُؤْمِنَ إِذَا أَصَابَهُ السَّقَمُ، ثُمَّ أَعْفَاهُ اللهُ مِنْهُ، كَانَ كَفَّارَةً لِمَا مَضَى مِنْ ذُنُوبِهِ، وَمَوْعِظَةً لَهُ فِيمَا يَسْتَقْبِلُ. وَإِنَّ الْمُنَافِقَ إِذَا مَرِضَ ثُمَّ أُعْفِيَ كَانَ كَالْبَعِيرِ: عَقَلَهُ أَهْلُهُ ثُمَّ أَرْسَلُوهُ، فَلَمْ يَدْرِ لِمَ عَقَلُوهُ وَلَمْ يَدْرِ لِمَ أَرْسَلُوهُ". فَقَالَ رَجُلٌ مِمَّنْ حَوْلَهُ: يَا رَسُولَ اللهِ، وَمَا الْأَسْقَامُ؟ وَاللهِ مَا مَرِضْتُ قَطُّ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "قُمْ عَنَّا فَلَسْتَ مِنَّا". فَبَيْنَا نَحْنُ عِنْدَهُ إِذْ أَقْبَلَ رَجُلٌ عَلَيْهِ كِسَاءٌ وَفِي يَدِهِ شَيْءٌ قَدِ الْتَفَّ عَلَيْهِ، فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي لَمَّا رَأَيْتُكَ أَقْبَلْتُ إِلَيْكَ، فَمَرَرْتُ بِغَيْضَةِ شَجَرٍ، فَسَمِعْتُ فِيهَا أَصْوَاتَ فِرَاخِ طَائِرٍ، فَأَخَذْتُهُنَّ فَوَضَعْتُهُنَّ فِي كِسَائِي، فَجَاءَتْ أُمُّهُنَّ فَاسْتَدَارَتْ عَلَى رَأْسِي، فَكَشَفْتُ لَهَا عَنْهُنَّ، فَوَقَعَتْ عَلَيْهِنَّ مَعَهُنَّ، فَلَفَفْتُهُنَّ بِكِسَائِي، فَهُنَّ أُولَاءِ مَعِي. قَالَ: "ضَعْهُنَّ عَنْكَ". فَوَضَعْتُهُنَّ، وَأَبَتْ أُمُّهُنَّ إِلَّا لُزُومَهُنَّ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِأَصْحَابِهِ: "أَتَعْجَبُونَ لِرُحْمِ أُمِّ الْأَفْرَاخِ فِرَاخَهَا". قَالُوا: نَعَمْ، يَا رَسُولَ اللهِ، قَالَ: "فَوَالَّذِي بَعَثَنِي بِالْحَقِّ لَلَّهُ أَرْحَمُ بِعِبَادِهِ مِنْ أُمِّ الْأَفْرَاخِ بِفِرَاخِهَا، ارْجِعْ بِهِنَّ حَتَّى تَضَعَهُنَّ مِنْ حَيْثُ أَخَذْتَهُنَّ وَأُمُّهُنَّ مَعَهُنَّ، فَرَجَعَ بِهِنَّ". (د)', 'ആമിറുർറാമി(റ): ഞാൻ എന്റെ നാട്ടിലായിരിക്കെ കുറെ പതാകകളും കൊടികളും ഉയർത്തപ്പെട്ടു. അപ്പോൾ ഞാൻ ചോദിച്ചു: എന്താണിത്? അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലിന്റെ പതാകയാണ്. ഞാൻ തിരുമേനി(സ)യുടെ അടുത്ത് ചെന്നു. അവിടുന്ന് മരച്ചുവട്ടിൽ വിരിച്ച ഒരു വിരിപ്പിൽ ഇരിക്കുകയായിരുന്നു. ചുറ്റും സഹാബികളുണ്ട്. ഞാനും അവരുടെ കൂടെ ഇരുന്നു. അപ്പോൾ റസൂൽ(സ) രോഗങ്ങളെ കുറിച്ച് സംസാരിച്ചു. നബി(സ) പറഞ്ഞു: "ഒരു വിശ്വാസിക്ക് രോഗം ബാധിക്കുകുയും പിന്നെ അല്ലാഹു അവന് ആശ്വാസം നൽകുകയും ചെയ്താൽ അത് അവൻ മുൻപ് ചെയ്ത പാപങ്ങൾക്ക് പ്രായശ്ചിത്തവും ഇനി വരാനുള്ള ജീവിതത്തിന് ഒരു പാഠവുമായിരിക്കും. ഒരു മുനാഫിഖിന് രോഗമായി അത് മാറിയാൽ ഒരു ഒട്ടകത്തെപ്പോലെയായിരിക്കും. കെട്ടിയിട്ട ശേഷം അഴിച്ചുവിട്ട ഒട്ടകത്തെപ്പോലെ, അതിനറിയില്ല എന്തിനാണ് താൻ ബന്ധിതനായത്, എന്തിനാണ് എന്നെ വിട്ടയച്ചത് എന്നൊന്നും." അപ്പോൾ ഒരാൾ എഴുന്നേറ്റു ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ എന്താണ് രോഗങ്ങൾ? എനിക്കൊരിക്കലും രോഗമുണ്ടായിട്ടില്ല. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "നീ ഞങ്ങളിൽ നിന്ന് എഴുന്നേൽക്കുക. നീ ഞങ്ങളിൽപെട്ടവനല്ല." അങ്ങനെ ഞങ്ങൾ നബി(സ)യുടെ അടുത്തുണ്ടായിരിക്കെ ഒരാൾ കയ്യിൽ ഒരു വസ്ത്രത്തിൽ എന്തോ ഒന്ന് പൊതിഞ്ഞ് കൊണ്ടുവന്നിട്ടു പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, ഞാൻ താങ്കളെ കണ്ടപ്പോൾ താങ്കളുടെ അടുക്കൽ വന്നതാണ്. ഞാൻ ഒരു മരങ്ങളുള്ള കാട്ടിലൂടെ നടക്കുകയായിരുന്നു. അപ്പോൾ പക്ഷികുഞ്ഞുങ്ങളുടെ സ്വരം കേട്ടു. ഞാൻ അവയെ എടുത്ത് എന്റെ വസ്ത്രത്തിൽ പൊതിഞ്ഞു. അപ്പോൾ അവയുടെ തള്ള വന്ന് എന്റെ തലക്ക് മുകളിലൂടെ പറക്കാൻ തുടങ്ങി. ഞാൻ അവയെ തുറന്നു. ആ തള്ള പക്ഷി കുഞ്ഞുങ്ങളുടെ മേലിരുന്നു. ഞാൻ അവയെ ഒന്നായി എന്റെ വസ്ത്രത്തിൽ പൊതിഞ്ഞു. അവയെല്ലാം ഇതാ എന്റെ അടുത്ത്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവയെ വെക്കൂ." അങ്ങനെ ഞാനത് വെച്ചു. തള്ള പക്ഷി അവയെ വിട്ടുപോകാൻ വിസമ്മതിച്ചു. അപ്പോൾ നബി(സ) സഹാബികളോട് ചോദിച്ചു: "തള്ള പക്ഷിക്ക് കുഞ്ഞുങ്ങളോടുള്ള ഈ കരുണയിൽ നിങ്ങൾക്ക് അത്ഭുതം തോന്നുന്നുണ്ടോ?" അവർ പറഞ്ഞു: അതെ പ്രവാചകരെ. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "എന്നെ നിയോഗിച്ചവനാണേ സത്യം അവന് തന്റെ അടിമകളോട് ഈ തള്ള പക്ഷിക്ക് കുഞ്ഞുങ്ങളോടുള്ളതിനേക്കാൾ കരുണയുണ്ട്. നീ മടങ്ങി പോയി തള്ളപക്ഷിയോടൊപ്പം കുഞ്ഞുങ്ങളെ എടുത്ത സ്ഥലത്ത് തന്നെ വക്കുക." അദ്ദേഹം അവയുമായി മടങ്ങി. (ദ)', 'عَامِرٍ الرَّامِ', 'ആമിറുർറാമി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 782, 783, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ مُحَمَّدِ بْنِ خَالِدٍ السُّلَمِيِّ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، وَكَانَتْ لَهُ صُحْبَةٌ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ الْعَبْدَ إِذَا سَبَقَتْ لَهُ مِنَ اللهِ مَنْزِلَةٌ لَمْ يَبْلُغْهَا بِعَمَلِهِ ابْتَلَاهُ اللهُ فِي جَسَدِهِ، أَوْ فِي مَالِهِ، أَوْ فِي وَلَدِهِ، ثُمَّ صَبَّرَهُ عَلَى ذَلِكَ حَتَّى يُبَلِّغَهُ الْمَنْزِلَةَ الَّتِي سَبَقَتْ لَهُ مِنَ اللهِ تَعَالَى". (د)', 'മുഹമ്മദ്ബ്നുഖാലിദുസ്സലമി തന്റെ പിതാവിൽ നിന്ന്, പിതാവ് പിതാമഹനിൽനിന്ന്, അദ്ദേഹം പ്രവാചകന്റെ(സ) സഹാബിയായിരുന്നു, അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഇപ്രകാരം പറഞ്ഞതായി ഞാൻ കേട്ടിരിക്കുന്നു. "നിശ്ചയം ഒരു അടിമക്ക് അല്ലാഹു നല്ല സ്ഥാനം നൽകാനുദ്ദേശിച്ചാൽ അവന്റെ കർമ്മങ്ങൾ കൊണ്ട് അത് പ്രാപിക്കുവാൻ അവന് പറ്റില്ല. അപ്പോൾ അല്ലാഹു അവന്റെ ശരീരത്തിലോ അവന്റെ മക്കളിലോ സമ്പത്തിലോ പരീക്ഷണം നടത്തും. എന്നിട്ട് അതിൽ ക്ഷമ നൽകുകയും അല്ലാഹു മൻകൂട്ടി നിശ്ചയിച്ച സ്ഥാനത്തേക്ക് അവനെ എത്തിക്കുകയും ചെയ്യും." (ദ)', 'مُحَمَّدِ بْنِ خَالِدٍ السُّلَمِيِّ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، وَكَانَتْ لَهُ صُحْبَةٌ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ', null, null, null, array['د']::text[], array['ദ']::text[], null, null, 783, 783, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غَيْرَ مَرَّةٍ وَلَا مَرَّتَيْنِ يَقُولُ: "إِذَا كَانَ الْعَبْدُ يَعْمَلُ عَمَلًا صَالِحًا، فَشَغَلَهُ عَنْهُ مَرَضٌ أَوْ سَفَرٌ، كُتِبَ لَهُ كَصَالِحِ مَا كَانَ يَعْمَلُ وَهُوَ صَحِيحٌ مُقِيمٌ". (خ,د)', 'അബൂമൂസ(റ): നബി(സ) അനേകം പ്രാവശ്യം ഇപ്രകാരം പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "ഒരു അടിമ ഒരു സൽകർമ്മം ചെയ്യുകയും രോഗമോ, യാത്രയോ അവനെ അതിൽ നിന്ന് തടയുകയും ചെയ്താൽ അവന് ആരോഗ്യമുള്ളപ്പോഴും നാട്ടിൽ താമസിക്കുമ്പോഴും ചെയ്തപോലെ അവയെ രേഖപ്പെടുത്തി വെക്കും." (ബു,ദ)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 783, 783, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ مَاتَ مَرِيضًا مَاتَ شَهِيدًا، وَوُقِيَ فِتْنَةَ الْقَبْرِ، وَغُدِيَ وَرِيحَ عَلَيْهِ بِرِزْقِهِ مِنَ الْجَنَّةِ". [ز: في إسناده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും രോഗിയായി മരിച്ചാൽ അവൻ രക്തസാക്ഷിയായി. ഖബറിലെ ശിക്ഷയിൽ നിന്നും അവൻ രക്ഷപ്പെടും. അവന് സ്വർഗ്ഗത്തിൽ വിശ്രമവും ഭക്ഷണവും ലഭിക്കും." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്വലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 783, 783, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: ابْتَاعَ بَنُو الْحَارِثِ بْنِ عَامِرِ بْنِ نَوْفَلٍ خُبَيْبًا، وَكَانَ خُبَيْبٌ هُوَ قَتَلَ الْحَارِثَ بْنَ عَامِرٍ يَوْمَ بَدْرٍ، فَلَبِثَ خُبَيْبٌ عِنْدَهُمْ أَسِيرًا حَتَّى أَجْمَعُوا لِقَتْلِهِ، فَاسْتَعَارَ مِنِ ابْنَةِ الْحَارِثِ مُوسَى يَسْتَحِدُّ بِهَا، فَأَعَارَتْهُ، فَدَرَجَ بُنَيٌّ لَهَا وَهِيَ غَافِلَةٌ حَتَّى أَتَتْهُ فَوَجَدَتْهُ مُخْلِيًا وَهُوَ عَلَى فَخِذِهِ، وَالْمُوسَى بِيَدِهِ، فَفَزِعَتْ فَزْعَةً عَرَفَهَا فِيهَا، فَقَالَ: أَتَخْشَيْنَ أَنْ أَقْتُلَهُ؟ مَا كُنْتُ لِأَفْعَلَ ذَلِكَ. (خ,د,ن)', 'അബൂഹുറൈറ(റ): ഹാരിസുബ്നു ആമിർ കുടുംബം ഖുബൈബി(റ)നെ വാങ്ങി. ബദർ ദിവസം ഹാരിസുബ്നു ആമിറിനെ ഖുബൈബ്(റ) വധിച്ചിരുന്നു. അങ്ങനെ ഖുബൈബ്(റ) അവരുടെ തടവിൽ കഴിയുകയും ശേഷം അവർ. അദ്ദേഹത്തെ വധിക്കാൻ തീരുമാനിക്കുകയും ചെയ്തു. ഖുബൈബ്(റ) ഗുഹ്യരോമങ്ങൾ കളയാൻ വേണ്ടി ഹാരിസിന്റെ മകളിൽ നിന്നും ഒരു കത്തി വായ്പ വാങ്ങി. അവൾ അശ്രദ്ധയായിരിക്കെ അവളുടെ കുഞ്ഞ് ഖുബൈബി(റ)ന്റെ അടുത്തെത്തി. അപ്പോൾ അവൾ അടുത്തുചെന്നു. അപ്പോൾ കുട്ടി ഖുബൈബ്(റ)വിന്റെ മടിയിലിരിക്കുകയായിരുന്നു. അദ്ദേഹത്തിന്റെ കയ്യിൽ കത്തിയുമുണ്ട്. അവൾ പേടിച്ചിട്ടുണ്ടെന്ന് ഖുബൈബിന് മനസ്സിലായി. അദ്ദേഹം ചോദിച്ചു: ഞാൻ കൊല്ലുമെന്ന് ഭയക്കുന്നുണ്ടോ? ഞാനൊരിക്കലും അങ്ങിനെ ചെയ്യില്ല. (ബു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 783, 784, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ لِضُرٍّ نَزَلَ بِهِ فِي الدُّنْيَا، وَلَكِنْ لِيَقُلِ: اللَّهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي". وَفِي رِوَايَةٍ: "أَلَا، لَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ لِضُرٍّ نَزَلَ بِهِ، فَإِنْ كَانَ لَا بُدَّ مُتَمَنِّيًا لِلْمَوْتِ فَلْيَقُلِ: اللَّهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي مَا كَانَتِ الْوَفَاةُ خَيْرًا لِي". (ق,د,ت,ن,جه)', 'അനസ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഇഹലോകത്ത് തനിക്ക് വന്നുപെട്ട ഒരു ദുരിതത്തിന്റെ പേരിൽ നിങ്ങളിൽ ആരും മരണം ആഗ്രഹിച്ചുപൊകരുത്. പ്രത്യുത വ്യക്തി ഇങ്ങനെ പറയട്ടെ. അല്ലാഹുവേ! ജീവിതം ഉത്തമമാകുന്ന കാലത്തോളം എന്നെ നീ ജീവിപ്പിക്കേണമേ, മരണം എനിക്ക് ഉത്തമമാണെങ്കിൽ എന്നെ മരിപ്പിക്കേണമേ." മറ്റൊരു നിവേദനം: "അറിയുക, തനിക്ക് വന്നുഭവിച്ച പ്രയാസം കാരണമായി നിങ്ങളിൽ ആരും മരണത്തെ ആഗ്രഹിക്കരുത്. ഇനി മരണത്തെ ആഗ്രഹിക്കൽ അത്യാവശ്യമെങ്കിൽ അവൻ ഇപ്രകാരം പറഞ്ഞുകൊള്ളട്ടെ: അല്ലാഹുവേ, ജീവിതം എനിക്ക് നന്മയാകുന്ന കാലംവരെ നീ എന്നെ ജീവിപ്പിക്കണേ, മരണം എനിക്ക് ഗുണകരമാകുമ്പോൾ എന്നെ നീ മരിപ്പിക്കണേ." (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 784, 784, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=72), 1, 'وَفِي رِوَايَةٍ: "أَلَا، لَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ لِضُرٍّ نَزَلَ بِهِ، فَإِنْ كَانَ لَا بُدَّ مُتَمَنِّيًا لِلْمَوْتِ فَلْيَقُلِ: اللَّهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي مَا كَانَتِ الْوَفَاةُ خَيْرًا لِي". (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: "അറിയുക, തനിക്ക് വന്നുഭവിച്ച പ്രയാസം കാരണമായി നിങ്ങളിൽ ആരും മരണത്തെ ആഗ്രഹിക്കരുത്. ഇനി മരണത്തെ ആഗ്രഹിക്കൽ അത്യാവശ്യമെങ്കിൽ അവൻ ഇപ്രകാരം പറഞ്ഞുകൊള്ളട്ടെ: അല്ലാഹുവേ, ജീവിതം എനിക്ക് നന്മയാകുന്ന കാലംവരെ നീ എന്നെ ജീവിപ്പിക്കണേ, മരണം എനിക്ക് ഗുണകരമാകുമ്പോൾ എന്നെ നീ മരിപ്പിക്കണേ." (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَتَمَنَّيَنَّ أَحَدٌ مِنْكُمُ الْمَوْتَ: إِمَّا مُحْسِنًا فَلَعَلَّهُ أَنْ يَزْدَادَ خَيْرًا، وَإِمَّا مُسِيئًا فَلَعَلَّهُ أَنْ يَسْتَعْتِبَ". وَفِي رِوَايَةٍ: "لَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ: إِمَّا مُحْسِنًا فَلَعَلَّهُ أَنْ يَعِيشَ يَزْدَادُ خَيْرًا، وَهُوَ خَيْرٌ لَهُ. وَإِمَّا مُسِيئًا فَلَعَلَّهُ أَنْ يَسْتَعْتِبَ". (ق,ن)', 'അബൂഹറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങളിൽ ആരും മരണത്തെ കൊതിക്കരുത്. ഒന്നുകിൽ അവൻ സുകൃതവാൻ ആയിരിക്കാം കൂടുതൽ നന്മ ചെയ്യാൻ അവനത് അവസരമുണ്ടാക്കിയേക്കാം. ഇനി കുറ്റവാളിയാണെങ്കിൽ, പശ്ചാതപിച്ച് അല്ലാഹുവിന്റെ തൃപ്തി കാംക്ഷിക്കാനായേക്കാം." മറ്റൊരു റിപ്പോർട്ട്: "നിങ്ങളിൽ ആരും മരണം ആഗ്രഹിക്കരുത്. സുകൃതവാനാണെങ്കിൽ കൂടുതൽ നന്മ പ്രവർത്തിച്ചു ജീവിച്ചെന്ന് വരാം. അതാണ് അയാൾക്ക് ഉത്തമം. അപരാധിയാണെങ്കിൽ പശ്ചാതപിച്ച് അല്ലാഹുവിന്റെ പ്രീതി കാംക്ഷിച്ചേക്കാം." (ബു,മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹറൈറ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 784, 784, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=73), 1, 'وَفِي رِوَايَةٍ: "لَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ: إِمَّا مُحْسِنًا فَلَعَلَّهُ أَنْ يَعِيشَ يَزْدَادُ خَيْرًا، وَهُوَ خَيْرٌ لَهُ. وَإِمَّا مُسِيئًا فَلَعَلَّهُ أَنْ يَسْتَعْتِبَ". (ق,ن)', 'മറ്റൊരു നിവേദന്: "നിങ്ങളിൽ ആരും മരണം ആഗ്രഹിക്കരുത്. സുകൃതവാനാണെങ്കിൽ കൂടുതൽ നന്മ പ്രവർത്തിച്ചു ജീവിച്ചെന്ന് വരാം. അതാണ് അയാൾക്ക് ഉത്തമം. അപരാധിയാണെങ്കിൽ പശ്ചാതപിച്ച് അല്ലാഹുവിന്റെ പ്രീതി കാംക്ഷിച്ചേക്കാം." (ബു,മു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ حَارِثَةَ بْنِ مُضَرِّبٍ قَالَ: دَخَلْتُ عَلَى خَبَّابٍ رَضِيَ اللهُ عَنْهُ وَقَدِ اكْتَوَى فِي بَطْنِهِ، فَقَالَ: مَا أَعْلَمُ أَحَدًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَقِيَ مِنَ الْبَلَاءِ مَا لَقِيتُ، لَقَدْ كُنْتُ وَمَا أَجِدُ دِرْهَمًا عَلَى عَهْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَفِي نَاحِيَةٍ مِنْ بَيْتِي أَرْبَعُونَ أَلْفًا، وَلَوْلَا أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَانَا – أَوْ: نَهَى – أَنْ نَتَمَنَّى الْمَوْتَ لَتَمَنَّيْتُ. حَسَنٌ صَحِيحٌ. (ق,ت)', 'ഹാരിസതു ബ്നു മുളർറിബ്(റ): ഉദരത്തിൽ ചൂട് പിടിപ്പിച്ച അവസ്ഥയിൽ ഞാൻ ഖബ്ബാബി(റ)നെ സമീപിച്ചു. അദ്ദേഹം പറഞ്ഞു. തിരുമേനി(സ)യുടെ അനുചരന്മാരിൽ ഞാൻ അഭിമുഖീകരിച്ചപോലെയുള്ള ദുരിതം അനുഭവിച്ച ഒരാളെയും എനിക്ക് അറിയില്ല. തിരുമേനി(സ)യുടെ കാലത്ത് ഒരു ദിർഹം പോലും എനിക്കുണ്ടായിരുന്നില്ല. (പക്ഷേ ഇന്നിപ്പോൾ) എന്റെ വീടിന്റെ ഒരു മൂലയിൽ നാൽപതിനായിരം ദിർഹമുണ്ട്. പ്രവാചകൻ(സ) മരണം ആഗ്രഹിക്കുന്നതിൽ നിന്ന് ഞങ്ങളെ വിരോധിച്ചിട്ടില്ലായിരുന്നുവെങ്കിൽ (അന്ന്) ഞാൻ മരണം ആഗ്രഹിക്കുമായിരുന്നു. ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,മു,തു)', 'حَارِثَةَ بْنِ مُضَرِّبٍ قَالَ', 'ഹാരിസതു ബ്നു മുളർറിബ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 784, 785, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ قَيْسِ بْنِ أَبِي حَازِمٍ قَالَ: دَخَلْتُ عَلَى خَبَّابٍ رَضِيَ اللهُ عَنْهُ وَقَدِ اكْتَوَى فِي بَطْنِهِ سَبْعًا، قَالَ: لَوْلَا أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَانَا أَنْ نَدْعُوَ بِالْمَوْتِ دَعَوْتُ بِهِ. (ق,ت,ن)', 'ഖൈസ്ബ്നു അബീഹാസിം(റ): ഞങ്ങൾ ഖബ്വാബി(റ)ന്റെ അടുക്കൽ ചെന്നു. അദ്ദേഹം തന്റെ വയറ്റിൽ ഏഴ് പ്രാവശ്യം മരുന്ന് കഴിച്ചിരിക്കുന്നു(ചൂട് വെച്ചിരുന്നു). അദ്ദേഹം പറഞ്ഞു: പ്രവാചകൻ(സ) നമ്മോട് മരണത്തിന് വേണ്ടി പ്രാർത്ഥിക്കുന്നത് നിരോധിച്ചിരുന്നില്ലെങ്കിൽ ഞാൻ അങ്ങനെ പ്രാർത്ഥിക്കുമായിരുന്നു. (ബു,മു,തു,ന)', 'قَيْسِ بْنِ أَبِي حَازِمٍ قَالَ', 'ഖൈസ്ബ്നു അബീഹാസിം(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 785, 785, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَحَبَّ لِقَاءَ اللهِ أَحَبَّ اللهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللهِ كَرِهَ اللهُ لِقَاءَهُ". فَقُلْتُ: يَا نَبِيَّ اللهِ، أَكَرَاهِيَةُ الْمَوْتِ؟ فَكُلُّنَا نَكْرَهُ الْمَوْتَ. قَالَ: "لَيْسَ كَذَلِكَ، وَلَكِنَّ الْمُؤْمِنَ إِذَا بُشِّرَ بِرَحْمَةِ اللهِ وَرِضْوَانِهِ وَجَنَّتِهِ أَحَبَّ لِقَاءَ اللهِ، فَأَحَبَّ اللهُ لِقَاءَهُ. وَإِنَّ الْكَافِرَ إِذَا بُشِّرَ بِعَذَابِ اللهِ وَسَخَطِهِ، كَرِهَ لِقَاءَ اللهِ وَكَرِهَ اللهُ لِقَاءَهُ". وَفِي رِوَايَةٍ عَنْ شُرَيْحِ بْنِ هَانِئٍ، عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَحَبَّ لِقَاءَ اللهِ أَحَبَّ اللهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللهِ، كَرِهَ اللهُ لِقَاءَهُ". قَالَ: فَأَتَيْتُ عَائِشَةَ فَقُلْتُ: يَا أُمَّ الْمُؤْمِنِينَ، سَمِعْتُ أَبَا هُرَيْرَةَ يَذْكُرُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَدِيثًا، إِنْ كَانَ كَذَلِكَ فَقَدْ هَلَكْنَا. فَقَالَتْ: إِنَّ الْهَالِكَ مَنْ هَلَكَ بِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَمَا ذَاكَ؟ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَحَبَّ لِقَاءَ اللهِ أَحَبَّ اللهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللهِ كَرِهَ اللهُ لِقَاءَهُ". لَيْسَ مِنَّا أَحَدٌ إِلَّا وَهُوَ يَكْرَهُ الْمَوْتَ؟ فَقَالَتْ: قَدْ قَالَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَيْسَ بِالَّذِي تَذْهَبُ إِلَيْهِ، وَلَكِنْ إِذَا شَخَصَ الْبَصَرُ، وَحَشْرَجَ الصَّدْرُ، وَاقْشَعَرَّ الْجِلْدُ، وَتَشَنَّجَتِ الْأَصَابِعُ، فَعِنْدَ ذَلِكَ مَنْ أَحَبَّ لِقَاءَ اللهِ أَحَبَّ اللهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللهِ كَرِهَ اللهُ لِقَاءَهُ. (م,ت,ن)', 'ആഇശ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഒരാൾ അല്ലാഹുവിനെ കാണാൻ ആഗ്രഹിച്ചാൽ അല്ലാഹു അയാളെ കാണാൻ ആഗ്രഹിക്കുന്നതാണ്. അല്ലാഹുവിനെ കാണാൻ ഒരാൾ വെറുത്താൽ അല്ലാഹു അയാളെ കാണാൻ വെറുക്കുന്നതാണ്." ഞാൻ ചോദിച്ചു: പ്രവാചകരേ! മരണത്തെ വെറുക്കുന്നതിനെ കുറിച്ചാണോ അങ്ങ് പറയുന്നത്? ഞങ്ങൾ എല്ലാവരും മരണം വെറുക്കുന്നവരാണല്ലോ? തിരുമേനി(സ) പറഞ്ഞു: "അതല്ല പറഞ്ഞത്. ഒരു സത്യവിശ്വാസിക്ക് അല്ലാഹുവിന്റെ കാരുണ്യം, കൃപ, സ്വർഗം എന്നിവയെ കുറിച്ച് സന്തോഷവാർത്ത നൽകപ്പെട്ടാൽ. അയാൾ അല്ലാഹുവിനെ കാണാൻ മോഹിക്കുന്നു അപ്പോൾ അല്ലാഹു അയാളെയും കാണാൻ മോഹിക്കുന്നു. ഒരു സത്യനിഷേധിയോട് അല്ലാഹുവിന്റെ ശിക്ഷ, കോപത്തെ കുറിച്ച് വാർത്ത നൽകപ്പെടുമ്പോൾ അയാൾ അല്ലാഹുവിനെ കാണാൻ വെറുക്കുന്നു അപ്പോൾ അല്ലാഹു അയാളെ കാണാനും വെറുക്കുന്നു." ശുറൈഹ്ബ്നു ഹാനിഇൽ നിന്നുള്ള റിപ്പോർട്ട് പ്രകാരം അബുഹുറൈറയിൽ നിന്ന് നിവേദനം: ശുറൈഹ്(റ) പറഞ്ഞു: പ്രവാചകൻ(സ) പറഞ്ഞു: "ഒരാൾ അല്ലാഹുവിനെ കാണാൻ മോഹിച്ചാൽ അല്ലാഹു അയാളെയും കാണാൻ മോഹിക്കും. ഒരാൾ അല്ലാഹുവിനെ കാണാൻ വെറുത്താൽ അല്ലാഹു അവനേയും കാണാൻ വെറുക്കും." അദ്ദേഹം പറഞ്ഞു: അങ്ങനെ ഞാൻ ആഇശ(റ)യുടെ അടുക്കൽ ചെന്നു ചോദിച്ചു. ഉമ്മുൽ മുഅ്മിനീൻ! അബുഹറൈറ(റ) തിരുമേനി(സ)യിൽ നിന്ന് ഒരു ഹദീസ് പറയുന്നതായി ഞാൻ കേട്ടു. അത് ആങ്ങനെയാണെങ്കിൽ നാമെല്ലാവരും നശിച്ചതു തന്നെ. ആഇശ(റ) പറഞ്ഞു: പ്രവാചകന്റെ(സ) വചനം കൊണ്ട് നശിച്ചവൻ നശിച്ചവൻതന്നെ. എന്താണ് ആ കാര്യം? അദ്ദേഹം പറഞ്ഞു: പ്രവാചകൻ(സ) പറഞ്ഞു: "ഒരാൾ അല്ലാഹുവിനെ കാണാൻ ആഗ്രഹിച്ചാൽ അല്ലാഹു അയാളെ കാണാൻ ആഗ്രഹിക്കും, ഒരാൾ അല്ലാഹുവിനെ കാണാൻ വെറുത്താൽ അല്ലാഹു അയാളെയും കാണാൻ വെറുക്കും." നമ്മിൽ ആരും മരണം വെറുക്കാത്തവരായിട്ട് ഇല്ലല്ലോ? ആഇശ(റ) പറഞ്ഞു: പ്രവാചകൻ(സ) അങ്ങനെ പറഞ്ഞത് ശരിയാണ്. അതിന്റെ ആശയം നീ വിചാരിക്കുന്നത് പോലെയല്ല. പക്ഷേ കണ്ണ് തുറിക്കുകയും, നെഞ്ചിൽ നിന്ന് കഫം കുറുകുന്ന ശബ്ദം കേൾക്കുകയും, ആത്മാവ് വിമ്മിഷ്ടപ്പെടുകയും, ചർമ്മം രോമാഞ്ചം കൊള്ളുകയും, വിരലുകൾ മരവിക്കുകയും ചെയ്യുന്ന അവസരത്തിൽ ആര് അല്ലാഹുവിനെ കാണാൻ ആഗ്രഹിക്കുന്നുവോ അവനെ അല്ലാഹു കാണാൻ ആഗ്രഹിക്കുന്നു. ആർ അല്ലാഹുവെ കാണാൻ വെറുക്കുന്നുവോ അവനെ കാണാൻ അല്ലാഹു വെറുക്കുകയും ചെയ്യുന്നു. (മു,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 785, 786, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=76), 1, 'وَفِي رِوَايَةٍ عَنْ شُرَيْحِ بْنِ هَانِئٍ، عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَحَبَّ لِقَاءَ اللهِ أَحَبَّ اللهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللهِ، كَرِهَ اللهُ لِقَاءَهُ". قَالَ: فَأَتَيْتُ عَائِشَةَ فَقُلْتُ: يَا أُمَّ الْمُؤْمِنِينَ، سَمِعْتُ أَبَا هُرَيْرَةَ يَذْكُرُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَدِيثًا، إِنْ كَانَ كَذَلِكَ فَقَدْ هَلَكْنَا. فَقَالَتْ: إِنَّ الْهَالِكَ مَنْ هَلَكَ بِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَمَا ذَاكَ؟ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَحَبَّ لِقَاءَ اللهِ أَحَبَّ اللهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللهِ كَرِهَ اللهُ لِقَاءَهُ". لَيْسَ مِنَّا أَحَدٌ إِلَّا وَهُوَ يَكْرَهُ الْمَوْتَ؟ فَقَالَتْ: قَدْ قَالَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَيْسَ بِالَّذِي تَذْهَبُ إِلَيْهِ، وَلَكِنْ إِذَا شَخَصَ الْبَصَرُ، وَحَشْرَجَ الصَّدْرُ، وَاقْشَعَرَّ الْجِلْدُ، وَتَشَنَّجَتِ الْأَصَابِعُ، فَعِنْدَ ذَلِكَ مَنْ أَحَبَّ لِقَاءَ اللهِ أَحَبَّ اللهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللهِ كَرِهَ اللهُ لِقَاءَهُ. (م,ت,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "قَالَ اللهُ تَعَالَى: إِذَا أَحَبَّ عَبْدِي لِقَائِي أَحْبَبْتُ لِقَاءَهُ، وَإِذَا كَرِهَ لِقَائِي كَرِهْتُ لِقَاءَهُ". (ن)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "അല്ലാഹു പറഞ്ഞു: എന്റെ അടിമ എന്നെ കാണാൻ ആഗ്രഹിച്ചാൽ, ഞാൻ അവനെ കാണാൻ ആഗ്രഹിക്കും. എന്നെ കാണാൻ വെറുത്താൽ, ഞാൻ അവനെയും കാണാൻ വെറുക്കും." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 786, 786, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَحَبَّ لِقَاءَ اللهِ أَحَبَّ اللهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللهِ كَرِهَ اللهُ لِقَاءَهُ". فَقِيلَ: يَا رَسُولَ اللهِ، كَرَاهِيَةُ لِقَاءِ اللهِ كَرَاهِيَةُ الْمَوْتِ؟ كُلُّنَا نَكْرَهُ الْمَوْتَ. قَالَ: "ذَاكَ عِنْدَ مَوْتِهِ: إِذَا بُشِّرَ بِرَحْمَةِ اللهِ وَمَغْفِرَتِهِ أَحَبَّ لِقَاءَ اللهِ وَأَحَبَّ اللهُ لِقَاءَهُ، وَإِذَا بُشِّرَ بِعَذَابِ اللهِ كَرِهَ لِقَاءَ اللهِ وَكَرِهَ اللهُ لِقَاءَهُ". (ن)', 'ആഇശ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിനെ കാണാൻ ആഗ്രഹിച്ചാൽ അവനെ കാണാൻ അല്ലാഹു ആഗ്രഹിക്കും. വല്ലവരും അല്ലാഹുവിനെ കാണാൻ വെറുത്താൽ അല്ലാഹു അവനെ കാണാനും വെറുക്കും." അപ്പോൾ നബി(സ)യോട് ചോദിക്കപ്പെട്ടു: പ്രവാചകരേ! അല്ലാഹുവിനെ കാണാൻ വെറുക്കുന്നത് മരണത്തെ വെറുക്കലല്ലേ? ഞങ്ങളെല്ലാം മരണം വെറുക്കുന്നുവല്ലോ? തിരുമേനി(സ) പറഞ്ഞു: "ഈ പറഞ്ഞത് മരണവേളയിലാണ്. അല്ലാഹുവിന്റെ കാരുണ്യം, പാപമോചനം എന്നിവ കൊണ്ട് ശുഭവാർത്ത ലഭിക്കപ്പെടുന്നവൻ അല്ലാഹുവിനെ കാണാൻ ആഗ്രഹിക്കുന്നു. അവനെ അല്ലാഹുവും കാണാൻ ആഗ്രഹിക്കുന്നു. ദൈവശിക്ഷ കൊണ്ട് ശുഭവാർത്ത ലഭിക്കപ്പെടുന്നവൻ അല്ലാഹുവിനെ കാണാൻ വെറുക്കുന്നു. അവനെ അല്ലാഹുവും കാണാൻ വെറുക്കുന്നു." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 786, 786, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَقِّنُوا مَوْتَاكُمْ لَا إِلَهَ إِلَّا اللهُ". (م,د,ت,ن,جه)', 'അബു സഈദിൽ ഖുദ്രി(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങളിൽ മരണം ആസന്നമായവർക്ക് നിങ്ങൾ ''ലാഇലാഹ ഇല്ലല്ലാഹ്'' എന്ന് ചൊല്ലിക്കൊടുക്കുക." (മു,ദ,തു,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബു സഈദിൽ ഖുദ്രി(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 786, 786, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ عَبْدِ اللهِ بْنِ جَعْفَرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَقِّنُوا مَوْتَاكُمْ: لَا إِلَهَ إِلَّا اللهُ الْحَلِيمُ الْكَرِيمُ، سُبْحَانَ اللهِ رَبِّ الْعَرْشِ الْعَظِيمِ، الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ". قَالُوا: يَا رَسُولَ اللهِ، كَيْفَ لِلْأَحْيَاءِ؟ قَالَ: "أَجْوَدُ، وَأَجْوَدُ". [ز: في إسناده راو مختلف في توثيقه] (جه)', 'അബ്ദുല്ലാഹിബ്നുജഅ്ഫർ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങളിൽ മരണം ആസന്നമായവർക്ക് ഇങ്ങനെ ചൊല്ലിക്കൊടുക്കുക: ലാഇലാഹ ഇല്ലല്ലാഹുൽ ഹലീമുൽ കരീം, സുബ്ഹാനല്ലാഹി......... (അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല. ഉദാരനും ക്ഷമാലുവുമായ അല്ലാഹു, മഹത്തായ സിംഹാസനത്തിന്റെ നാഥനായ അല്ലാഹുവിനെ ഞാൻ പരിശുദ്ധപ്പെടുത്തുന്നു. ലോക പരിപാലകനായ അല്ലാഹുവിന് സർവ്വസ്തോത്രങ്ങളും)" അവർ ചോദിച്ചു: പ്രവാചകരേ! ജീവിച്ചിരിക്കുന്നവർക്ക് ഇത് എങ്ങനെ? തിരുമേനി(സ) പറഞ്ഞു: "വളരെ നല്ലത് തന്നെ. വളരെ നല്ലത്." (ഇതിന്റെ പരമ്പരയിലെ ഒരു റിപ്പോർട്ടറുടെ വിശ്വാസ്യതയിൽ അഭിപ്രായ വ്യത്യാസമുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'عَبْدِ اللهِ بْنِ جَعْفَرٍ', 'അബ്ദുല്ലാഹിബ്നുജഅ്ഫർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده راو مختلف في توثيقه', null, 787, 787, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَتَانِي آتٍ مِنْ رَبِّي فَأَخْبَرَنِي، أَوْ قَالَ: بَشَّرَنِي أَنَّهُ مَنْ مَاتَ مِنْ أُمَّتِي لَا يُشْرِكُ بِاللهِ شَيْئًا دَخَلَ الْجَنَّةَ". قُلْتُ: وَإِنْ زَنَى وَإِنْ سَرَقَ؟ قَالَ: "وَإِنْ زَنَى وَإِنْ سَرَقَ". (خ)', 'അബൂദർറ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "എന്റെ നാഥനിൽ നിന്ന് മലക്ക് വന്ന് എന്നോട് ഇങ്ങനെ പറഞ്ഞു - അല്ലെങ്കിൽ ശുഭവാർത്ത അറിയിച്ചു എന്നാണ് നബി(സ) പറഞ്ഞത് -: എന്റെ സമുദായത്തിൽ നിന്ന് വല്ലവരും അല്ലാഹുവിന് പങ്ക് ചേർക്കാതെ മരണം വരിച്ചാൽ അയാൾ സ്വർഗത്തിൽ പ്രവേശിക്കും." ഞാൻ ചോദിച്ചു: അയാൾ വ്യഭിചരിക്കുകയും മോഷണം നടത്തുകയും ചെയ്തവനാണെങ്കിലോ? നബി(സ) മറുപടി പറഞ്ഞു: "വ്യഭിചരിച്ചാലും മോഷണം നടത്തിയാലും." (ബു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 787, 787, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ مَاتَ يُشْرِكُ بِاللهِ شَيْئًا دَخَلَ النَّارَ". وَقُلْتُ أَنَا: مَنْ مَاتَ لَا يُشْرِكُ بِاللهِ شَيْئًا دَخَلَ الْجَنَّةَ. (خ)', 'അബ്ദുല്ല(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "അല്ലാഹുവിൽ വല്ലതും പങ്ക്ചേർത്ത്കൊണ്ട് ഒരാൾ മരിച്ചാൽ അയാൾ നരകത്തിൽ പ്രവേശിക്കും." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിൽ ഒന്നിനെയും പങ്ക് ചേർക്കാത്തവൻ സ്വർഗത്തിൽ പ്രവേശിക്കും. (ബു)', 'عَبْدِ اللهِ', 'അബ്ദുല്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 787, 787, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَ آخِرُ كَلَامِهِ لَا إِلَهَ إِلَّا اللهُ دَخَلَ الْجَنَّةَ". (د)', 'മൂആദുബ്നുജബൽ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഒരാളുടെ അവസാന സംസാരം ''ലാഇലാഹ ഇല്ലല്ലാഹ്'' എന്നായാൽ അയാൾ സ്വർഗത്തിൽ പ്രവേശിക്കും." (ദ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മൂആദുബ്നുജബൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 787, 787, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ قَبْلَ مَوْتِهِ بِثَلَاثٍ: قَالَ: "لَا يَمُوتُ أَحَدُكُمْ إِلَّا وَهُوَ يُحْسِنُ الظَّنَّ بِاللهِ". (م,د,جه)', 'ജാബിർ ഇബ്നുഅബ്ദുല്ല(റ): മരിക്കുന്ന മൂന്ന് ദിവസം മുമ്പ് തിരുമേനി(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടു: "നിങ്ങളിൽ ആരും തന്നെ അല്ലാഹുവിനെ കുറിച്ച് നല്ലത് വിചാരിച്ചു കൊണ്ടല്ലാതെ മരിച്ചുപോകരുത്." (മു,ദ,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിർ ഇബ്നുഅബ്ദുല്ല(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 787, 787, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ لَمَّا حَضَرَهُ الْمَوْتُ دَعَا بِثِيَابٍ جُدُدٍ فَلَبِسَهَا، ثُمَّ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ الْمَيِّتَ يُبْعَثُ فِي ثِيَابِهِ الَّتِي يَمُوتُ فِيهَا". (د)', 'അബുസഈദുൽ ഖുദ്രി(റ): അദ്ദേഹത്തിന് മരണം അടുത്തപ്പോൾ അദ്ദേഹം പുതിയ വസ്ത്രം ആവശ്യപ്പെടുകയും അവ ധരിക്കുകയും ചെയ്തു. പിന്നീട് അദ്ദേഹം പറഞ്ഞു: തിരുമേനി(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "മരണവേളയിലെ വസ്ത്രത്തോടുകൂടിയാണ് മയ്യിത്ത് പുനർജീവിപ്പിക്കപ്പെടുക." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദുൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 788, 788, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَى شَابٍّ وَهُوَ فِي الْمَوْتِ، فَقَالَ: "كَيْفَ تَجِدُكَ". قَالَ: وَاللهِ – يَا رَسُولَ اللهِ – أَنِّي أَرْجُو اللهَ وَإِنِّي أَخَافُ ذُنُوبِي. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَجْتَمِعَانِ فِي قَلْبِ عَبْدٍ فِي مِثْلِ هَذَا الْمَوْطِنِ إِلَّا أَعْطَاهُ اللهُ مَا يَرْجُو، وَآمَنَهُ مِمَّا يَخَافُ". حَسَنٌ. (ت,جه)', 'അനസ്(റ): മരിക്കാറായ ഒരു യുവാവിന്റെ അടുക്കൽ പ്രവേശിച്ചുകൊണ്ട് നബി(സ) ചോദിച്ചു: "നിനക്ക് എന്തു തോന്നുന്നു?" അയാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, സത്യമായും ഞാൻ എന്റെ പാപങ്ങളുടെ കാര്യത്തിൽ ഭയപ്പെടുകയും അല്ലാഹുവിൽ പ്രതീക്ഷയർപ്പിക്കുകയും ചെയ്യുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇതുപോലെയുള്ള ഒരു സ്ഥലത്ത് ഒരു അടിമയുടെ മനസ്സിൽ ഈ രണ്ട് കാര്യങ്ങൾ ഒരുമിച്ചാൽ അവൻ പ്രതീക്ഷിച്ചത് അല്ലാഹു അവന് നൽകുകയും അവൻ ഭയപ്പെട്ടതിൽ നിന്ന് മോചനം നൽകുകയും തന്നെ ചെയ്യും." ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു. (തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 788, 788, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ حَافِظَيْنِ رَفَعَا إِلَى اللهِ مَا حَفِظَا مِنْ لَيْلٍ أَوْ نَهَارٍ، فَيَجِدُ اللهُ فِي أَوَّلِ الصَّحِيفَةِ وَفِي آخِرِ الصَّحِيفَةِ خَيْرًا، إِلَّا قَالَ اللهُ تَعَالَى: أُشْهِدُكُمْ أَنِّي قَدْ غَفَرْتُ لِعَبْدِي مَا بَيْنَ طَرَفَيِ الصَّحِيفَةِ". (ت)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "രാത്രിയിലോ പകലിലോ രണ്ട് ഹാഫിദുകൾ (നന്മ തിന്മകൾ രേഖപ്പെടുത്തുന്ന മലക്കുകൾ) തങ്ങൾ രേഖപ്പെടുത്തിയതിനെ അല്ലാഹുവിന്റെ മുന്നിൽ ഹാജറാക്കുകയും അതിന്റെ തുടക്കത്തിലുള്ളതിനേയും അവസാനത്തിനുള്ളതിനേയും അല്ലാഹു നന്നായി കാണുകയും ചെയ്താൽ മഹോന്നതനായ അല്ലാഹു പറയും: ഞാൻ നിങ്ങളെ സാക്ഷിയാക്കിക്കൊണ്ട് പറയുന്നു. ഞാൻ എന്റെ അടിമക്ക് പേജുകളുടെ രണ്ട് അറ്റത്തിന്റെയും ഇടയിലുള്ളത് പൊറുത്തുകൊടുത്തിരിക്കുന്നു." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 788, 788, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "نَفْسُ الْمُؤْمِنِ مُعَلَّقَةٌ بِدَيْنِهِ حَتَّى يُقْضَى عَنْهُ". حَسَنٌ. (ت,جه)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "സത്യവിശ്വാസിയുടെ ആത്മാവ് തന്റെ കടം വീട്ടുന്നത് വരെ അതുമായി ബന്ധപ്പെട്ടിരിക്കും." ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു. (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 788, 789, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا حَقُّ امْرِئٍ مُسْلِمٍ يَبِيتُ لَيْلَتَيْنِ، وَلَهُ شَيْءٌ يُوصِي فِيهِ، إِلَّا وَوَصِيَّتُهُ مَكْتُوبَةٌ عِنْدَهُ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "രണ്ട് രാത്രിയിലധികം കഴിച്ചുകൂട്ടുന്ന ഒരാൾ തന്റെ പക്കൽ വല്ല സാധനവുമുണ്ടെങ്കിൽ അതിനെക്കുറിച്ചുല്ല വസ്വിയ്യത്ത് അവന്റെ അടുക്കൽ എഴുതി വെച്ചിട്ടല്ലാതെ ഉണ്ടാവരുത്." (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 789, 789, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ سَعْدِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: عَادَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا مَرِيضٌ، فَقَالَ: "أَوْصَيْتَ". قُلْتُ: نَعَمْ. قَالَ: "بِكَمْ". قُلْتُ: بِمَالِي كُلِّهِ فِي سَبِيلِ اللهِ. قَالَ: "فَمَا تَرَكْتَ لِوَلَدِكَ". قُلْتُ: هُمْ أَغْنِيَاءُ بِخَيْرٍ. قَالَ: "أَوْصِ بِالْعُشْرِ". فَمَا زِلْتُ أُنَاقِصُهُ حَتَّى قَالَ: "أَوْصِ بِالثُّلُثِ، وَالثُّلُثُ كَثِيرٌ". حَسَنٌ صَحِيحٌ. (ق,ت)', 'സഅ്ദുബ്നു മാലിക്(റ): ഞാൻ രോഗിയായിരിക്കുമ്പോൾ നബി(സ) എന്നെ സന്ദർശിച്ചു. നബി(സ) ചോദിച്ചു: "നീ വസ്വിയത്ത് ചെയ്തിട്ടുണ്ടോ?" ഞാൻ പറഞ്ഞു: അതെ. നബി(സ) ചോദിച്ചു: "എത്രയാണ് ചെയ്തത്?" ഞാൻ പറഞ്ഞു: എന്റെ ധനം മുഴുവനും, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലേക്ക്. നബി(സ) ചോദിച്ചു: "അപ്പോൾ നിന്റെ മക്കൾക്ക് എന്താണുള്ളത്?" ഞാൻ പറഞ്ഞു: അവർ നന്മയിൽ സമ്പന്നരാണ്. നബി(സ) പറഞ്ഞു: "നീ പത്തിൽ ഒന്ന് വസ്വിയത്ത് ചെയ്താൽ മതി." ഞാൻ അത് കുറവായിക്കണ്ടു. അവസാനം നബി(സ) പറഞ്ഞു: "നീ മൂന്നിൽ ഒന്ന് വസ്വിയ്യത്ത് ചെയ്യുക. മൂന്നിൽ ഒന്ന് തന്നെ ധാരാളമാണ്." (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ബു,മു,തു)', 'سَعْدِ بْنِ مَالِكٍ', 'സഅ്ദുബ്നു മാലിക്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 789, 789, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: إِذَا خَرَجَتْ رُوحُ الْمُؤْمِنِ تَلَقَّاهَا مَلَكَانِ يُصْعِدَانِهَا، قَالَ حَمَّادٌ: فَذَكَرَ مِنْ طِيبِ رِيحِهَا وَذَكَرَ الْمِسْكَ، قَالَ: "وَيَقُولُ أَهْلُ السَّمَاءِ: رُوحٌ طَيِّبَةٌ، جَاءَتْ مِنْ قِبَلِ الْأَرْضِ، صَلَّى اللهُ عَلَيْكِ وَعَلَى جَسَدٍ كُنْتِ تَعْمُرِينَهُ. فَيَنْطَلِقُ بِهِ إِلَى رَبِّهِ عَزَّ وَجَلَّ، ثُمَّ يَقُولُ: انْطَلِقُوا بِهِ إِلَى آخِرِ الْأَجَلِ. قَالَ: وَإِنَّ الْكَافِرَ إِذَا خَرَجَتْ رُوحُهُ". قَالَ حَمَّادٌ: وَذَكَرَ مِنْ نَتْنِهَا وَذَكَرَ لَعْنًا، "وَيَقُولُ أَهْلُ السَّمَاءِ: رُوحٌ خَبِيثَةٌ جَاءَتْ مِنْ قِبَلِ الْأَرْضِ، قَالَ: فَيُقَالُ: انْطَلِقُوا بِهِ إِلَى آخِرِ الْأَجَلِ". قَالَ أَبُو هُرَيْرَةَ: فَرَدَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَيْطَةً كَانَتْ عَلَيْهِ عَلَى أَنْفِهِ هَكَذَا. (م)', 'അബുഹുറൈറ(റ): സത്യവിശ്വാസിയുടെ ആത്മാവ് പുറപ്പെടുമ്പോൾ വാനലോകത്തേക്ക് കയറ്റാൻ വേണ്ടി രണ്ട് മലക്കുകൾ അതിനെ ഏറ്റുവാങ്ങുന്നു; തിരുമേനി(സ) അതിന്റെ പരിമളത്തേയും കസ്തൂരിയുടെ ഗന്ധത്തേയും പരാമർശിച്ചുവെന്ന് ഹമ്മാദ് പറയുകയുണ്ടായി; അവിടുന്ന് പറഞ്ഞു: "ഭൂഗോളത്തിൽനിന്നും ഏത്തിച്ചേർന്ന വിശുദ്ധ ആത്മാവാണിതെന്ന് വാനവാസികൾ പറയും. നിന്നെയും നീ പരിപാലിച്ചിരുന്ന ശരീരത്തെയും അല്ലാഹു അനുഗ്രഹിക്കട്ടെ എന്ന് പറഞ്ഞ്കൊണ്ട് ആ ആത്മാവ് രക്ഷിതാവിലേക്ക് നയിക്കപ്പെടും. അതിനെ നിർണ്ണിത പരിധിയുടെ അവസാനത്തിലേക്ക് കൊണ്ടുപോകൂ എന്ന് അല്ലാഹു പറയും. അവിടുന്ന് പറഞ്ഞു: അവിശ്വാസിയുടെ ആത്മാവ് പുറപ്പെടുമ്പോൾ...." തിരുമേനി(സ) അതിന്റെ ദുർഗന്ധത്തെ പരാമർശിക്കുകയും ശപിക്കുകയും ചെയ്തുവെന്ന് ഹമ്മാദ് പറയുകയുണ്ടായി. "ഭൂലോകത്ത്നിന്ന് ഒരു ദുഷ്ട ആത്മാവ് വന്നിരിക്കുന്നുവെന്ന് വാന നിവാസികൾ പറയും. അവിടുന്ന് പറഞ്ഞു: നിർണ്ണിത പരിധിയുടെ അവസാനത്തിലേക്ക് അതിനേയും കൊണ്ടുപോകൂ എന്ന് പറയപ്പെടും." ഈ സമയം തിരുമേനി(സ) തന്റെ മേൽ വസ്ത്രം അവിടുന്ന് ഇപ്രകാരം മൂക്കിലേക്ക് തിരിച്ചുപിടിച്ചു എന്ന് അബൂഹുറൈറ(റ) പറയുകയുണ്ടായി. (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 789, 790, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: كَانَ يُحَدِّثُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّمَا نَسَمَةُ الْمُؤْمِنِ طَائِرٌ فِي شَجَرِ الْجَنَّةِ، حَتَّى يَبْعَثَهُ اللهُ عَزَّ وَجَلَّ إِلَى جَسَدِهِ يَوْمَ الْقِيَامَةِ". (ن)', 'കഅ്ബ്ബ്നു മാലിക്(റ): തിരുമേനി(സ) പറഞ്ഞതായി അദ്ദേഹം ഉദ്ധരിക്കുന്നു: "സത്യവിശ്വാസിയുടെ ആത്മാവ് സ്വർഗത്തിലെ വൃക്ഷത്തിലെ ഒരു പക്ഷിയായിരിക്കും, അന്ത്യനാളിൽ അല്ലാഹു അതിനെ അതിന്റെ ശരീരത്തിലേക്ക് യാത്രയാക്കുന്നത് വരെ." (ന)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബ്ബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 790, 790, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا وَعِنْدَهَا حَمِيمٌ لَهَا يَخْنُقُهُ الْمَوْتُ. فَلَمَّا رَأَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَا بِهَا قَالَ لَهَا: "لَا تَبْتَئِسِي عَلَى حَمِيمِكِ، فَإِنَّ ذَلِكَ مِنْ حَسَنَاتِهِ". (جه)', 'ആഇശ(റ): തിരുമേനി(സ) മഹതിയുടെ അടുക്കൽ പ്രവേശിച്ചു. അപ്പോൾ മരണം ആസന്നമായ മഹതിയുടെ ഒരു ഉറ്റ കൂട്ടുകാരി അവിടെ ഉണ്ടായിരുന്നു. ആഇശ(റ)യുടെ വ്യാകുലത കണ്ടപ്പോൾ തിരുനബി(സ) മഹതിയോടു പറഞ്ഞു. "കൂട്ടുകാരിയുടെ വിഷയത്തിൽ നീ വ്യാകുലപ്പെടേണ്ടതില്ല. ഈ മരണവും അവരുടെ സൽകർമ്മങ്ങളിൽ പെടും." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 790, 790, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمُؤْمِنُ يَمُوتُ بِعَرَقِ الْجَبِينِ". (جه)', 'ബുറൈദ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "സത്യവിശ്വാസി നെറ്റിത്തടം വിയർത്ത് കൊണ്ട് മരിക്കുന്നു." (ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 790, 790, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: مَتَى تَنْقَطِعُ مَعْرِفَةُ الْعَبْدِ مِنَ النَّاسِ؟ قَالَ: "إِذَا عَايَنَ". (جه)', 'അബുമൂസ(റ): ഞാൻ റസൂലി(സ)നോട് ചോദിച്ചു: ജനങ്ങളിൽ നിന്ന് ഒരാളുടെ അറിവ് എപ്പോഴാണ് അവസാനിക്കുന്നത്. നബി(സ) പറഞ്ഞു: "നേരിൽ കാണുമ്പോൾ (മരണത്തെ)." (ജ)', 'أَبِي مُوسَى', 'അബുമൂസ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 790, 790, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ عُمَرَ – رَضِيَ اللهُ عَنْهُ – بَيْنَ مَكَّةَ وَالْمَدِينَةِ، أَخَذَ يُحَدِّثُنَا عَنْ أَهْلِ بَدْرٍ فَقَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيُرِينَا مَصَارِعَهُمْ بِالْأَمْسِ، قَالَ: "هَذَا مَصْرَعُ فُلَانٍ إِنْ شَاءَ اللهُ غَدًا". قَالَ عُمَرُ: وَالَّذِي بَعَثَهُ بِالْحَقِّ، مَا أَخْطَئُوا تِيكَ، فَجُعِلُوا فِي بِئْرٍ، فَأَتَاهُمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَنَادَى: "يَا فُلَانَ بْنَ فُلَانٍ، يَا فُلَانَ بْنَ فُلَانٍ، هَلْ وَجَدْتُمْ مَا وَعَدَ رَبُّكُمْ حَقًّا؟ فَإِنِّي وَجَدْتُ مَا وَعَدَنِي اللهُ حَقًّا". فَقَالَ عُمَرُ: تُكَلِّمُ أَجْسَادًا لَا أَرْوَاحَ فِيهَا؟ فَقَالَ: "مَا أَنْتُمْ بِأَسْمَعَ لِمَا أَقُولُ مِنْهُمْ". (ن)', 'അനസ്(റ): മക്കയുടെയും മദീനയുടെയും ഇടയിൽ ഞങ്ങൾ ഉമറി(റ)ന്റെ കൂടെ ആയിരിക്കെ അദ്ദേഹം ഞങ്ങളോട് ബദ്റിൽ വധിക്കപ്പെട്ടവരെക്കുറിച്ച് സംസാരിക്കാൻ തുടങ്ങി. തുടർന്ന് അദ്ദേഹം പറഞ്ഞു: "നാളെ ഇത് ഇന്നവരുടെ മരണഭൂമിയായിരിക്കും, അല്ലാഹു ഉദ്ദേശിച്ചാൽ" എന്ന് പറഞ്ഞ്കൊണ്ട് തലേദിവസം തിരുമേനി(സ) ഞങ്ങൾക്ക് അവരുടെ പതനഭൂമി കാണിച്ചുതരികയുണ്ടായി. ഉമർ പറയുന്നു: സത്യവുമായി തിരുമേനിയെ നിയോഗിച്ചവനാണെ! പ്രസ്തുത സ്ഥലങ്ങളിൽ നിന്ന് അവർ വ്യതിചലിച്ചതുമില്ല. പിന്നീട് അവരെ ഒരു കിണറ്റിലിട്ടു. ശേഷം തിരുമേനി(സ) അവരെ സമീപിച്ചു, ഓരോ ആളുകളെയും പേർ എടുത്ത് വിളിച്ചുകൊണ്ട് ഇങ്ങനെ ചോദിച്ചു: "നിങ്ങളുടെ നാഥൻ നിങ്ങളോട് ചെയ്ത വാഗ്ദാനം നിങ്ങൾ സത്യമായി അനുഭവിച്ചുവോ? എന്നോട് അല്ലാഹു ചെയ്ത വാഗ്ദാനം ഞാൻ സത്യമായി അനുഭവിച്ചിരിക്കുന്നു." അപ്പോൾ ഉമർ(റ) ചോദിച്ചു. ആത്മാവില്ലാത്ത ജഡങ്ങളോട് അങ്ങ് സംസാരിക്കുകയാണോ? അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവരേക്കാൾ കൂടുതലായി ഞാൻ പറയുന്നത് നിങ്ങൾ കേൾക്കുന്നവരല്ല." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 790, 791, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعَ الْمُسْلِمُونَ مِنَ اللَّيْلِ بِبِئْرِ بَدْرٍ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَائِمٌ يُنَادِي: "يَا أَبَا جَهْلِ بْنَ هِشَامٍ، وَيَا شَيْبَةَ بْنَ رَبِيعَةَ، وَيَا عُتْبَةَ بْنَ رَبِيعَةَ، وَيَا أُمَيَّةَ بْنَ خَلَفٍ، هَلْ وَجَدْتُمْ مَا وَعَدَ رَبُّكُمْ حَقًّا؟ فَإِنِّي وَجَدْتُ مَا وَعَدَنِي رَبِّي حَقًّا". قَالُوا: يَا رَسُولَ اللهِ، أَوَ تُنَادِي قَوْمًا قَدْ جَيَّفُوا؟ فَقَالَ: "مَا أَنْتُمْ بِأَسْمَعَ لِمَا أَقُولُ مِنْهُمْ، وَلَكِنَّهُمْ لَا يَسْتَطِيعُونَ أَنْ يُجِيبُوا". (ن)', 'അനസ്(റ): ഒരു രാത്രി ബദ്റിലെ കിണറ്റിനരികെ നിന്നുകൊണ്ട് പ്രവാചകൻ(സ) ഇങ്ങനെ വിളിച്ചു പറയുന്നത് മുസ്ലിംകൾ കേട്ടു: "ഓ, അബൂജഹ്ല് ഇബ്നുഹിശാം, ശൈബത്തു ഇബ്ന റബീഅ, ഉത്ബത്ത് ഇബ്നുറബീഅ, ഉമയ്യത്ത് ഇബ്ൻഖലഫ്! നിങ്ങളുടെ നാഥൻ നിങ്ങളോട് ചെയ്ത വാഗ്ദാനം നിങ്ങൾ സത്യമായി അനുഭവിച്ചുവോ? എന്റെ നാഥൻ എന്നോട് ചെയ്ത വാഗ്ദാനം ഞാൻ സത്യമായി അനുഭവിച്ചു." അവർ ചോദിച്ചു: പ്രവാചകരെ! മൃതിയടഞ്ഞ ആളുകളെയാണോ താങ്കൾ വിളിക്കുന്നത്? തിരുമേനി(സ) പ്രത്യുത്തരം നൽകി: "അവരേക്കാൾ കൂടുതൽ ഞാൻ പറയുന്നത് നിങ്ങൾ കേൾക്കുന്നില്ല. പക്ഷേ അവർക്ക് മറുപടി പറയാൻ സാധിക്കുന്നില്ലെന്ന് മാത്രം." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 791, 791, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَفَ عَلَى قَلِيبِ بَدْرٍ فَقَالَ: "هَلْ وَجَدْتُمْ مَا وَعَدَ رَبُّكُمْ حَقًّا". قَالَ: "إِنَّهُمْ لَيَسْمَعُونَ الْآنَ مَا أَقُولُ لَهُمْ". فَذُكِرَ ذَلِكَ لِعَائِشَةَ، فَقَالَتْ: وَهَلَ ابْنُ عُمَرَ، إِنَّمَا قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهُمُ الْآنَ يَعْلَمُونَ أَنَّ الَّذِي كُنْتُ أَقُولُ لَهُمْ هُوَ الْحَقُّ". ثُمَّ قَرَأَتْ قَوْلَهُ {إِنَّكَ لَا تُسْمِعُ الْمَوْتَى} حَتَّى قَرَأَتِ الْآيَةَ. (خ,ن)', 'ഇബ്നുഉമർ(റ): ബദ്റിലെ കിണറ്റിന്റെ അരികെ നിന്നുകൊണ്ട് പ്രവാചകൻ(സ) ഇങ്ങനെ പറഞ്ഞു: "നിങ്ങളുടെ നാഥൻ നിങ്ങളോട് ചെയ്ത വാഗ്ദാനം സത്യമായി നിങ്ങൾ അനുഭവിച്ചുവോ?" തിരുമേനി(സ) പറഞ്ഞു: "ഞാൻ അവരോട് പറയുന്നത് അവർ ഇപ്പോൾ കേട്ടുകൊണ്ടിരിക്കുന്നു." ഇത് ചിലർ ആഇശ(റ)യോട് പറഞ്ഞു. മഹതി പറഞ്ഞു: (പ്രവാചകൻ(സ) ഇപ്രകാരം പറഞ്ഞു എന്നു പറഞ്ഞത്) ഇബ്നുഉമറിന് പിഴവ് പറ്റിയതാണ്. എന്നാൽ പ്രവാചകൻ(സ) പറഞ്ഞത് ഇത്ര മാത്രമാണ്. "ഞാൻ അവരോട് പറഞ്ഞിരുന്നത് സത്യമായിരുന്നു എന്ന് ഇപ്പോൾ അവർ അറിഞ്ഞു കാണും." ശേഷം ആയിശ(റ) ''തീർച്ചയായും നീ മരിച്ചവരെ കേൾപ്പിക്കുകയില്ല'' എന്ന സൂക്തം പൂർണ്ണമായി ഓതി കേൾപ്പിച്ചു. (ബു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 791, 791, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُلُّ بَنِي آدَمَ - وَفِي رِوَايَةٍ: كُلُّ ابْنِ آدَمَ - يَأْكُلُهُ التُّرَابُ إِلَّا عَجْبَ الذَّنَبِ، مِنْهُ خُلِقَ وَفِيهِ يُرَكَّبُ". (ق,د,ن)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "എല്ലാ ആദം സന്തതികളെയും തന്റെ പിൻഭാഗത്തെ എല്ല് ഒഴികെ മണ്ണ് തിന്ന് തീർക്കും. അതിൽ നിന്ന് അവന്റെ സൃഷ്ടികർമ്മം നടത്തി. അതിലൂടെ തന്നെ പുനഃസംയോജിക്കപ്പെടുകയും ചെയ്യും." (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 791, 791, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=99), 1, 'وَفِي رِوَايَةٍ: كُلُّ ابْنِ آدَمَ - يَأْكُلُهُ التُّرَابُ إِلَّا عَجْبَ الذَّنَبِ، مِنْهُ خُلِقَ وَفِيهِ يُرَكَّبُ". (ق,د,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ, عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ, قَالَ اللهُ عَزَّ وَجَلَّ: "كَذَّبَنِي ابْنُ آدَمَ وَلَمْ يَكُنْ يَنْبَغِي لَهُ أَنْ يُكَذِّبَنِي، وَشَتَمَنِي ابْنُ آدَمَ وَلَمْ يَكُنْ يَنْبَغِي لَهُ أَنْ يَشْتُمَنِي. أَمَّا تَكْذِيبُهُ إِيَّايَ فَقَوْلُهُ: إِنِّي لَا أُعِيدُهُ كَمَا بَدَأْتُهُ، وَلَيْسَ آخِرُ الْخَلْقِ بِأَعَزَّ عَلَيَّ مِنْ أَوَّلِهِ. وَأَمَّا شَتْمُهُ إِيَّايَ فَقَوْلُهُ اتَّخَذَ اللهُ وَلَدًا، وَأَنَا اللهُ الْأَحَدُ الصَّمَدُ، لَمْ أَلِدْ وَلَمْ أُولَدْ، وَلَمْ يَكُنْ لِي كُفُوًا أَحَدٌ". (ن)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "അല്ലാഹു പറഞ്ഞിരിക്കുന്നു: ആദം സന്തതി എന്നെ നിഷേധിച്ചു. എന്നെ നിഷേധിക്കുന്നത് അവന് ചേർന്നതായിരുന്നില്ല. ആദം സന്തതി എന്നെ ചീത്ത വിളിച്ചു. എന്നെ ചീത്ത വിളിക്കുന്നത് അവന് ചേർന്നതായിരുന്നില്ല. അവൻ എന്നെ നിഷേധിച്ചു എന്ന് പറഞ്ഞത് തുടക്കത്തിൽ സൃഷ്ടികർമ്മം നടത്തിയത് പോലെ അവന് നാം പുനഃസൃഷ്ടിക്കുകയില്ല എന്ന അവന്റെ പരാമർശമാണ്. പുനഃസൃഷ്ടി എന്നത് പ്രഥമ സൃഷ്ടിപ്പിനെക്കാൾ എനിക്ക് ശ്രമകരമേ അല്ല. എന്നെ ചീത്ത വിളിച്ചു എന്ന് പറഞ്ഞത് അല്ലാഹു മകനെ ഉണ്ടാക്കി എന്ന അവന്റെ പരാമർശത്തെകുറിച്ചാണ്. ഞാൻ അന്യാശ്രയനും ഏകനുമായ അല്ലാഹുവാണ്, ഞാൻ ജനിപ്പിച്ചവനോ ജനിച്ചവനോ അല്ല, എനിക്ക് തുല്യരായി ആരും ഇല്ലതന്നെ." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 791, 792, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَسْرَفَ عَبْدٌ عَلَى نَفْسِهِ، حَتَّى حَضَرَتْهُ الْوَفَاةُ قَالَ لِأَهْلِهِ: إِذَا أَنَا مُتُّ فَأَحْرِقُونِي، ثُمَّ اسْحَقُونِي، ثُمَّ اذْرُونِي فِي الرِّيحِ فِي الْبَحْرِ. فَوَاللهِ لَئِنْ قَدَرَ اللهُ عَلَيَّ لَيُعَذِّبَنِي عَذَابًا لَا يُعَذِّبُهُ أَحَدًا مِنْ خَلْقِهِ. قَالَ: فَفَعَلَ أَهْلُهُ ذَلِكَ، قَالَ اللهُ عَزَّ وَجَلَّ لِكُلِّ شَيْءٍ أَخَذَ مِنْهُ شَيْئًا: أَدِّ مَا أَخَذْتَ، فَإِذَا هُوَ قَائِمٌ، قَالَ اللهُ عَزَّ وَجَلَّ: مَا حَمَلَكَ عَلَى مَا صَنَعْتَ؟ قَالَ: خَشْيَتُكَ، فَغَفَرَ اللهُ لَهُ". (ن)', 'അബുഹുറൈറ(റ): തിരുമേനി(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടു: "ഒരു അടിമ സ്വന്തം ശരീരത്തോട് തെറ്റ് ചെയ്തു. മരണ വേളയിൽ തന്റെ കുടുംബത്തോട് അവൻ ഇങ്ങനെ പറഞ്ഞു: ഞാൻ മരിച്ച് കഴിഞ്ഞാൽ നിങ്ങൾ എന്നെ കരിച്ച് കളയുക, ശേഷം എന്നെ പൊടിപടലമാക്കുക, പിന്നീട് എന്നെ കാറ്റിൽ സമുദ്രത്തിൽ വിതറിക്കളയുക. കാരണം അല്ലാഹുവാണേ, അല്ലാഹു എന്നെയെങ്ങാനും പിടികൂടിയാൽ സൃഷ്ടികളിൽ മറ്റാരെയും ശിക്ഷിക്കാത്ത രൂപത്തിൽ എന്നെ ശിക്ഷിക്കും. നബി(സ) പറഞ്ഞു: അദ്ദേഹത്തിന്റെ കുടുംബം അപ്രകാരം ചെയ്തു. എന്നാൽ അല്ലാഹു ആ ശരീരത്തിൽ നിന്നും എന്തെങ്കിലും എടുത്ത ഒരോ വസ്തുവിനോടും അതു തിരിച്ചു നൽകാൻ പറഞ്ഞപ്പോൾ അവൻ അല്ലാഹുവിന്റെ മുന്നിൽ നിൽക്കുകയായി. ശേഷം നീ ഇപ്രകാരം പ്രവർത്തിക്കാൻ നിന്നെ പ്രേരിപ്പിച്ചതെന്ത്? എന്ന് അല്ലാഹു അവനോട് ചോദിച്ചു. നിന്നെ ഭയപ്പെട്ടുകൊണ്ടാണിത് ചെയ്തതെന്ന് അവൻ മറുപടി പറഞ്ഞപ്പോൾ അല്ലാഹു അവന് മാപ്പാക്കി." (ന)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 792, 792, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا حُضِرَ الْمُؤْمِنُ أَتَتْهُ مَلَائِكَةُ الرَّحْمَةِ بِحَرِيرَةٍ بَيْضَاءَ، فَيَقُولُونَ: اخْرُجِي رَاضِيَةً مَرْضِيًّا عَنْكِ إِلَى رَوْحِ اللهِ وَرَيْحَانٍ، وَرَبٍّ غَيْرِ غَضْبَانَ. فَتَخْرُجُ كَأَطْيَبِ رِيحِ الْمِسْكِ، حَتَّى أَنَّهُ لَيُنَاوِلُهُ بَعْضُهُمْ بَعْضًا حَتَّى يَأْتُونَ بِهِ بَابَ السَّمَاءِ، فَيَقُولُونَ: مَا أَطْيَبَ هَذِهِ الرِّيحَ الَّتِي جَاءَتْكُمْ مِنَ الْأَرْضِ. فَيَأْتُونَ بِهِ أَرْوَاحَ الْمُؤْمِنِينَ، فَلَهُمْ أَشَدُّ فَرَحًا بِهِ مِنْ أَحَدِكُمْ بِغَائِبِهِ يَقْدَمُ عَلَيْهِ، فَيَسْأَلُونَهُ: مَاذَا فَعَلَ فُلَانٌ؟ مَاذَا فَعَلَ فُلَانٌ؟ فَيَقُولُونَ: دَعُوهُ، فَإِنَّهُ كَانَ فِي غَمِّ الدُّنْيَا. فَإِذَا قَالَ: أَمَا أَتَاكُمْ؟ قَالُوا: ذُهِبَ بِهِ إِلَى أُمِّهِ الْهَاوِيَةِ. وَإِنَّ الْكَافِرَ إِذَا احْتُضِرَ أَتَتْهُ مَلَائِكَةُ الْعَذَابِ بِمِسْحٍ فَيَقُولُونَ: اخْرُجِي سَاخِطَةً مَسْخُوطًا عَلَيْكِ إِلَى عَذَابِ اللهِ عَزَّ وَجَلَّ. فَتَخْرُجُ كَأَنْتَنِ رِيحِ جِيفَةٍ، حَتَّى يَأْتُونَ بِهِ بَابَ الْأَرْضِ فَيَقُولُونَ: مَا أَنْتَنَ هَذِهِ الرِّيحَ، حَتَّى يَأْتُونَ بِهِ أَرْوَاحَ الْكُفَّارِ". (ن)', 'അബുഹുറൈറ(റ): തിരുമേനി(സ) പറഞ്ഞു: "ഒരു സത്യവിശ്വാസിയുടെ മരണവേളയിൽ കാരുണ്യത്തിന്റെ മാലാഖമാർ വെള്ള പട്ടുമായി അവനെ സമീപിച്ചുകൊണ്ട് ഇങ്ങനെ പറയും. ദൈവത്തിന്റെ പ്രീതിഭാജനവും സംപ്രീതനുമായി കാരുണ്യത്തിലേക്കും സുഗന്ധത്തിലേക്കും കോപിഷ്ഠനല്ലാത്ത നാഥനിലേക്കും നീ പുറപ്പെടുക. അങ്ങനെ കസ്തൂരിയുടെ സുഗന്ധപരിമളം പോലെ അവൻ പുറപ്പെടുന്നു. അങ്ങനെ അവർ പരസ്പരം അവനെ കൈമാറി അവർ അവനെ ആകാശകവാടത്തിൽ കൊണ്ടുചെല്ലുന്നു. ആകാശവാസികൾ പറയും: ഭൂലോകത്ത് നിന്ന് വന്നെത്തിയ നിങ്ങളിൽ എന്തൊരു പരിമളസുഗന്ധം. പിന്നീട് അവർ അവനെ സത്യവിശ്വാസികളുടെ ആത്മാവുകളുടെ അടുക്കൽ കൊണ്ടുചെല്ലുമ്പോൾ അപ്രത്യക്ഷനായ ഒരാൾ വന്ന്ചേരുമ്പോൾ നിങ്ങളിലൊരാൾക്കുണ്ടാകുന്ന സന്തോഷത്തേക്കാൾ കൂടുതൽ അവർക്ക് സന്തോഷമുണ്ടാകും. അവർ അവനോട് ചോദിക്കും: ഇന്നിന്ന വ്യക്തികൾ എന്തു ചെയ്തു? അപ്പോൾ അവർ പറയും: അവൻ ഐഹിക ജീവിതത്തെകുറിച്ച് വ്യസനത്തിലായിരിക്കുന്നു. അതുകൊണ്ട് അവനെ വീടു, അവൻ നിങ്ങളിലേക്ക് വന്ന് ചേർന്നില്ലേ, എന്ന് അവൻ ചോദിച്ചാൽ അവർ പറയും: അവനെ നരകത്തിലേക്ക് കൊണ്ടു പോയിരിക്കുന്നു. എന്നാൽ ഒരു സത്യ നിഷേധിക്ക് മരണം ആസന്നമാകുമ്പോൾ ശിക്ഷയുടെ മാലാഖമാർ പരുത്ത വസ്ത്രവുമായി അവനെ സമീപിക്കുന്നു. കോപിഷ്ഠനും കോപപാത്രവുമായി അല്ലാഹുവിന്റെ ശിക്ഷയിലേക്ക് നീ പുറപ്പെടുക എന്ന് അവനോട് പറയും. ശവം നാറുന്നതുപോലെ നാറുന്ന വാസനയുമായി അവൻ പുറപ്പെടും ഭൂമിയുടെ കവാടത്തിൽ അവനെകൊണ്ടുചെല്ലുമ്പോൾ എന്തൊരു ദുർഗന്ധമാണിത് എന്ന് അവർ പറയും. പിന്നീട് അവനെ സത്യനിഷേധികളുടെ ആത്മാവുകൾ ഉള്ള സ്ഥലത്തേക്ക് അവർ കൊണ്ടുപോകും." (ന)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 792, 793, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَاتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَإِنَّهُ لَبَيْنَ حَاقِنَتِي وَذَاقِنَتِي، فَلَا أَكْرَهُ شِدَّةَ الْمَوْتِ لِأَحَدٍ أَبَدًا بَعْدَ مَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'ആഇശ(റ): തിരുമേനി(സ) മരണപ്പെട്ടത് എന്റെ താടിയെല്ലിന്റെയും ഉള്ളൻ കയ്യിന്റെയും ഇടയിലായിട്ടാണ്. പ്രവാചകൻ(സ) വഫാത്താകുന്നത് ഞാൻ കണ്ടശേഷം ആരുടേയും മരണകാഠിന്യത്തെ ഞാൻ വെറുക്കുന്നില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 793, 793, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: آخِرُ نَظْرَةٍ نَظَرْتُهَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَشْفُ السِّتَارَةِ، وَالنَّاسُ صُفُوفٌ خَلْفَ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ، فَأَرَادَ أَبُو بَكْرٍ أَنْ يَرْتَدَّ، فَأَشَارَ إِلَيْهِمْ: أَنِ امْكُثُوا، وَأَلْقَى السِّجْفَ، وَتُوُفِّيَ مِنْ آخِرِ ذَلِكَ الْيَوْمِ، وَذَلِكَ يَوْمُ الِاثْنَيْنِ. (ن)', 'അനസ്(റ): ഞാൻ അവസാനമായി തിരുമേനി(സ)യെ നോക്കിയത് മറനീക്കിയിട്ടപ്പോഴാണ്. ജനങ്ങൾ അബൂബക്കറി(റ)ന്റെ പിന്നിൽ അണിനിരന്നിരിക്കുന്നു. അബുബക്കർ(റ) പിന്നോട്ട് മാറാൻ ഉദ്ദേശിച്ചപ്പോൾ അവിടെ തന്നെ നിൽക്കാൻ അവിടുന്ന് സൂചന നൽകി. അതോടെ വിരിതാഴ്ത്തി. ആ ദിവസത്തിന്റെ അവസാനത്തിൽ നബി(സ) വഫാതായി. അതൊരു തിങ്കളാഴ്ചയായിരുന്നു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 793, 793, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ عُبَيْدِ بْنِ خَالِدٍ السُّلَمِيِّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَوْتُ الْفَجْأَةِ أَخْذَةُ أَسَفٍ". (د)', 'നബി(സ)യിൽ നിന്ന് ഉബൈദുബ്നുഖാലിദിസ്സുലമി(റ): "പെട്ടെന്നുള്ള മരണം കോപാകുലന്റെ പിടുത്തമാണ്." (ദ)', 'عُبَيْدِ بْنِ خَالِدٍ السُّلَمِيِّ', 'നബി(സ)യിൽ നിന്ന് ഉബൈദുബ്നുഖാലിദിസ്സുലമി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 794, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَجُلًا قَالَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أُمِّي افْتُلِتَتْ نَفْسُهَا، وَأَظُنُّهَا لَوْ تَكَلَّمَتْ تَصَدَّقَتْ، فَهَلْ لَهَا أَجْرٌ إِنْ تَصَدَّقْتُ عَنْهَا؟ قَالَ: "نَعَمْ". (خ)', 'ആഇശ(റ): ഒരാൾ നബി(സ)യോട് പറഞ്ഞു: എന്റെ മാതാവിന്റെ ആത്മാവ് പിരിഞ്ഞ് പോയി. അവർ സംസാരിച്ചാൽ ദാനം ചെയ്യുമായിരുന്നു എന്ന് ഞാൻ വിചാരിക്കുന്നു. അവൾക്ക് വേണ്ടി ഞാൻ ദാനം ചെയ്താൽ അവൾക്ക് പ്രതിഫലം ലഭിക്കുമോ? നബി(സ) പറഞ്ഞു: "അതെ." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 794, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا أَغْبِطُ أَحَدًا بِهَوْنِ مَوْتٍ بَعْدَ الَّذِي رَأَيْتُ مِنْ شِدَّةِ مَوْتِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'ആഇശ(റ): നബി(സ)യുടെ മരണത്തിന്റെ കാഠിന്യം ഞാൻ കണ്ട ശേഷം, ആരുടെ മരണവും സ്വസ്ഥമാകില്ല എന്ന് ഞാൻ മനസ്സിലാക്കുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 794, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ نَفْسَ الْمُؤْمِنِ تَخْرُجُ رَشْحًا، وَلَا أُحِبُّ مَوْتًا كَمَوْتِ الْحِمَارِ". قِيلَ: وَمَا مَوْتُ الْحِمَارِ؟ قَالَ "مَوْتُ الْفَجْأَةِ". (ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു. "മുഅ്മിനിന്റെ ആത്മാവ് തീർച്ചയായും വിയർപ്പ് പോലെ പുറത്ത് വരും. കഴുതയുടെ മരണം പോലുള്ള ഒരു മരണം ഞാനിഷ്ടപ്പെടുന്നില്ല." ചോദിച്ചു: ഏതാണ് കഴുതയുടെ മരണം. പ്രവാചകൻ പറഞ്ഞു: "പെട്ടെന്നുള്ള മരണം." (തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 794, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ بِالْمَوْتِ، وَعِنْدَهُ قَدَحٌ فِيهِ مَاءٌ، وَهُوَ يُدْخِلُ يَدَهُ فِي الْقَدَحِ، ثُمَّ يَمْسَحُ وَجْهَهُ بِالْمَاءِ، ثُمَّ يَقُولُ: "اللَّهُمَّ أَعِنِّي عَلَى غَمَرَاتِ الْمَوْتِ. أَوْ: سَكَرَاتِ الْمَوْتِ". حَسَنٌ صَحِيحٌ غَرِيبٌ. (ت,جه)', 'ആഇശാ(റ): റസൂൽ(സ)യെ മരണാവസ്ഥയിൽ ഞാൻ കണ്ടു. തിരുമേനി(സ)യുടെ അടുക്കൽ ഒരു പാത്രത്തിൽ വെള്ളമുണ്ട്. അവിടുന്ന് കൈ പാത്രത്തിലിടും. പിന്നെ വെള്ളം കൊണ്ട് മുഖം തടവും. പിന്നെ പറയും: "അല്ലാഹുവേ, മരണത്തിന്റെ വിഷമത്തിൽ എന്നെ സഹായിക്കെണേ." (ഹദീസ് സ്വഹീഹും ഹസനും ഗരീബുമുണെന്ന് തുർമുദി പറയുന്നു) (തു,ജ)', 'عَائِشَةَ', 'ആഇശാ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 794, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ مُسْلِمٍ يَمُوتُ يَوْمَ الْجُمُعَةِ - أَوْ: لَيْلَةَ الْجُمُعَةِ - إِلَّا وَقَاهُ اللهُ فِتْنَةَ الْقَبْرِ". (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "വെള്ളിയാഴ്ച അല്ലെങ്കിൽ വെള്ളിയാഴ്ച രാത്രി മരിക്കുന്നവനെ ഖബറിലെ ഫിത്നയിൽ നിന്ന് അല്ലാഹു രക്ഷപ്പെടുത്തുക തന്നെ ചെയ്യും." (തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 794, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اكْثِرُوا ذِكْرَ هَادِمِ اللَّذَّاتِ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആനന്ദങ്ങളെ ഇല്ലാതാക്കുന്നതിനെ (മരണത്തെ) ഓർമ്മിക്കുന്നത് നിങ്ങൾ അധികരിപ്പിക്കുക." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 795, 795, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَعَى زَيْدًا وَجَعْفَرًا قَبْلَ أَنْ يَجِيءَ خَبَرُهُمْ، فَنَعَاهُمْ وَعَيْنَاهُ تَذْرِفَانِ. (ن)', 'അനസ്(റ): സൈദിന്റെ(റ)യും ജഅ്ഫറിന്റെ(റ)യും മരണം പ്രവാചകർ(സ)യെ അറിയിച്ചു. അവരുടെ മരണ വിവരം നാട്ടിൽ എത്തുന്നതിന്റെ മുമ്പ് കണ്ണീരൊഴുക്കിക്കൊണ്ടാണ് തിരുമേനി(സ) അവരുടെ മരണവിവരം മറ്റുള്ളവരെ അറിയിച്ചത്. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 795, 795, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَعَى لَهُمُ النَّجَاشِيَّ صَاحِبَ الْحَبَشَةِ الْيَوْمَ الَّذِي مَاتَ فِيهِ، وَقَالَ: "اسْتَغْفِرُوا لِأَخِيكُمْ". (خ,ن)', 'അബുഹുറൈറ(റ): അബ്സീനിയയുടെ ഭരണാധികാരി നജ്ജാശി മരിച്ച ദിവസം തിരുമേനി(സ) ജനങ്ങളോട് അദ്ദേഹത്തിന്റെ മരണവിവരം അറിയിച്ചു. തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങളുടെ സഹോദരന് വേണ്ടി നിങ്ങൾ പൊറുക്കൽ തേടുക." (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 795, 795, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَعَى النَّجَاشِيَّ فِي الْيَوْمِ الَّذِي مَاتَ فِيهِ، خَرَجَ إِلَى الْمُصَلَّى فَصَفَّ بِهِمْ وَكَبَّرَ أَرْبَعًا. (خ)', 'അബൂഹുറൈറ(റ): നജ്ജാശി മരണപ്പെട്ട ദിവസം പ്രവാചകർ(സ) അദ്ദേഹത്തിന്റെ മരണ വിവരം അറിയിച്ചു. അവിടുന്ന് നിസ്കാരസ്ഥലത്തേക്ക് പുറപ്പെടുകയും ജനങ്ങളെ അണിയാക്കിനിർത്തുകയും നാല് തക്ബീറോടെ മയ്യിത്ത് നിസ്കരിക്കുകയും ചെയ്തു. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 795, 795, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِيَّاكُمْ وَالنَّعْيَ، فَإِنَّ النَّعْيَ مِنْ عَمَلِ الْجَاهِلِيَّةِ". حَسَنٌ. (ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങൾ മരണംവിളിച്ചു കൂവുന്നത് സൂക്ഷിക്കുക, മരണം വിളിച്ചുകൂവുന്നത് ജാഹിലിയ്യാ ആചാരമാണ്." (ഹദീസ് ഹസനാണെന്ന് തുർമുദി) (തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 795, 795, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ رَضِيَ اللهُ عَنْهُ قَالَ: إِذَا مِتُّ فَلَا تُؤْذِنُوا بِي، إِنِّي أَخَافُ أَنْ يَكُونَ نَعْيًا، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنِ النَّعْيِ. حَسَنٌ صَحِيحٌ. (ت,جه)', 'ഹുദൈഫത്ബ്ന യമാനി(റ): ഞാൻ മരിച്ചാൽ നിങ്ങൾ എന്റെ മരണം വിളംബരം ചെയ്യരുത്. കാരണം അത് ''നഅ്യ്'' ആകും എന്ന് ഞാൻ ഭയപ്പെടുന്നു. പ്രവാചകൻ(സ) നഅ്യ് വിരോധിച്ചതായി ഞാൻ കേട്ടിട്ടുണ്ട്. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (തു,ജ)', 'حُذَيْفَةَ بْنِ الْيَمَانِ', 'ഹുദൈഫത്ബ്ന യമാനി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 795, 795, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ: أَنَّ مِسْكِينَةً مَرِضَتْ، فَأُخْبِرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمَرَضِهَا، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُ الْمَسَاكِينَ وَيَسْأَلُ عَنْهُمْ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا مَاتَتْ فَآذِنُونِي". فَأُخْرِجَ بِجَنَازَتِهَا لَيْلًا، وَكَرِهُوا أَنْ يُوقِظُوا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا أَصْبَحَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أُخْبِرَ بِالَّذِي كَانَ مِنْهَا، فَقَالَ: "أَلَمْ آمُرْكُمْ أَنْ تُؤْذِنُونِي بِهَا". قَالُوا: يَا رَسُولَ اللهِ، كَرِهْنَا أَنْ نُوقِظَكَ لَيْلًا. فَخَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى صَفَّ بِالنَّاسِ عَلَى قَبْرِهَا، وَكَبَّرَ أَرْبَعَ تَكْبِيرَاتٍ. (ن)', 'അബൂഉമാമത് ബ്നുസഹ്ൽ ഇബ്നുഹുനൈഫ്(റ): ഒരു പാവപ്പെട്ട സ്ത്രീക്ക് രോഗം ബാധിച്ചു. പ്രവാചക(സ)നോട് അവളുടെ രോഗവിവരം അറിയിച്ചു. പ്രവാചകൻ(സ) ദരിദ്രരുടെ രോഗം സന്ദർശിക്കുകയും വിവരം ആരായുകയും ചെയ്യുമായിരുന്നു. അങ്ങനെ പ്രവാചകൻ(സ) പറഞ്ഞു: "അവർ മരിച്ചാൽ എന്നെ അറിയിക്കുക." അവളുടെ മൃതശരീരം കൊണ്ടു പോയത് രാത്രിയിലായിരുന്നു. പ്രവാചകനെ(സ) ഉണർത്താൻ അവർ വൈമനസ്യം കാണിച്ചു. നേരം പുലർന്നപ്പോൾ അവളുടെ കാര്യം തിരുമേനി(സ)യെ അറിയിച്ചു. പ്രവാചകൻ(സ) പറഞ്ഞു: "അവൾ മരിച്ചാൽ എന്നെ വിവരം അറിയിക്കാൻ ഞാൻ നിങ്ങളോട് കൽപിച്ചിരുന്നില്ലേ." അവർ പറഞ്ഞു: പ്രവാചകരേ, രാത്രി താങ്കളെ വിളിച്ചുണർത്താൻ ഞങ്ങൾ വെറുത്തു. അങ്ങനെ പ്രവാചകൻ(സ) പുറത്ത് ഇറങ്ങി അവളുടെ ഖബ്റിന്റെ അരികിൽ ജനങ്ങളെ അണിനിരത്തി നാല് തക്ബീർ ചൊല്ലി നിസ്കരിച്ചു. (ന)', 'أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ', 'അബൂഉമാമത് ബ്നുസഹ്ൽ ഇബ്നുഹുനൈഫ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 795, 796, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: جِيءَ بِأَبِي يَوْمَ أُحُدٍ وَقَدْ مُثِّلَ بِهِ، فَوُضِعَ بَيْنَ يَدَيْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَدْ سُجِّيَ بِثَوْبٍ، فَجَعَلْتُ أُرِيدُ أَنْ أَكْشِفَ عَنْهُ فَنَهَانِي قَوْمِي، فَأَمَرَ بِهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرُفِعَ، فَلَمَّا رُفِعَ سَمِعَ صَوْتَ بَاكِيَةٍ، فَقَالَ: "مَنْ هَذِهِ". فَقَالُوا: هَذِهِ بِنْتُ عَمْرٍو أَوْ: أُخْتُ عَمْرٍو. قَالَ: "فَلَا تَبْكِي. أَوْ: فَلِمَ تَبْكِي؟ مَا زَالَتِ الْمَلَائِكَةُ تُظِلُّهُ بِأَجْنِحَتِهَا حَتَّى رُفِعَ". (ن)', 'ജാബിർ(റ): അംഗങ്ങൾ ഛേദിക്കപ്പെട്ട അവസ്ഥയിൽ ഉഹ്ദ് ദിവസം എന്റെ പിതാവിനെ കൊണ്ടുവന്ന് നബി(സ)യുടെ മുമ്പിൽ വെക്കപ്പെട്ടു. അദ്ദേഹത്തെ ഒരു വസ്ത്രം കൊണ്ട് മൂടപ്പെട്ടിരിക്കുന്നു. അത് നീക്കാൻ ഞാൻ ഉദ്ദേശിച്ചു. പക്ഷേ എന്റെ കൂട്ടുകാർ എന്നെ തടഞ്ഞു. നബി(സ) കൽപിച്ചപ്പോൾ അത് നീക്കി. അപ്പോൾ കരയുന്ന ഒരു സ്ത്രീയുടെ ശബ്ദം കേട്ട നബി(സ) ചോദിച്ചു: "ആരാണത്?" അവർ പറഞ്ഞു: അത് അംറിന്റെ മകളോ സഹോദരിയോ ആണ്. നബി(സ) പറഞ്ഞു: "നീ കരയേണ്ട - അല്ലെങ്കിൽ: എന്തിനാണ് നീ കരയുന്നത്? - അദ്ദേഹത്തെ ഉയർത്തപ്പെടുന്നത് വരെ മലക്കുകൾ തണലിട്ട് കൊണ്ടിരിക്കുകയായിരുന്നു." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 796, 796, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سُجِّيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ مَاتَ بِثَوْبٍ حِبَرَةٍ. (ق,د)', 'ഉമ്മുൽ മുഅ്മിനീൻ ആയിശ(റ): നബി(സ) വഫാതായപ്പോൾ അവിടുത്തെ ശരീരം ഒരു യമനീ വസ്ത്രം കൊണ്ട് മൂടി മറക്കപ്പെട്ടു. (ബു,മു,ദ)', 'عَائِشَةَ أُمِّ الْمُؤْمِنِينَ', 'ഉമ്മുൽ മുഅ്മിനീൻ ആയിശ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 796, 796, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا حَضَرْتُمُ الْمَيِّتَ فَقُولُوا خَيْرًا، فَإِنَّ الْمَلَائِكَةَ يُؤَمِّنُونَ عَلَى مَا تَقُولُونَ". فَلَمَّا مَاتَ أَبُو سَلَمَةَ قُلْتُ: يَا رَسُولَ اللهِ، مَا أَقُولُ؟ قَالَ: "قُولِي: اللَّهُمَّ اغْفِرْ لَهُ، وَأَعْقِبْنَا عُقْبَى صَالِحَةً". قَالَتْ: فَأَعْقَبَنِي اللهُ تَعَالَى بِهِ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,د,ت,ن,جه)', 'ഉമ്മുസലമ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങൾ മയ്യിത്തിന്റെ അടുക്കൽ ചെന്നാൽ നല്ല വാക്ക് പറഞ്ഞ് കൊള്ളുക. കാരണം നിങ്ങൾ പറയുന്നതിന് മലക്കുകൾ ആമീൻ പറഞ്ഞ് കൊണ്ടിരിക്കുന്നു." അബൂസലമ(റ) മരിച്ചപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദുതരേ, ഞാൻ എന്താണ് പറയേണ്ടത്? പ്രവാചകൻ(സ) പറഞ്ഞു: "അല്ലാഹുവേ അദ്ദേഹത്തിന് മാപ്പ് നൽകേണമേ, അദ്ദേഹത്തിന്റെ ശേഷം ഞങ്ങൾക്ക് ഉത്തമമായ പ്രതിനിധിയെ നൽകേണമേ." അവർ പറഞ്ഞു: അങ്ങനെ അല്ലാഹു മുഹമ്മദ് നബി(സ)യെ എനിക്ക് പ്രതിനിധിയാക്കി. (മു,ദ,തു,ന,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 796, 797, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَبَّلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عُثْمَانَ بْنَ مَظْعُونٍ وَهُوَ مَيِّتٌ. فَكَأَنِّي أَنْظُرُ إِلَى دُمُوعِهِ تَسِيلُ عَلَى خَدَّيْهِ. (د,ت,جه)', 'ആഇശ(റ): മരിച്ചശേഷം ഉസ്മാനുബ്നു മള്ഊനി(റ)നെ പ്രവാചകൻ(സ) ചുംബിച്ചിരുന്നു. നബി(സ)യുടെ കവിളുകളിൽ കൂടി കണ്ണുനീർ ഒഴുകുന്നത് ഇന്നും ഞാൻ കാണുന്നപോലെയുണ്ട്. (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 797, 797, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنِ ابْنِ عَبَّاسٍ وَعَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ أَبَا بَكْرٍ قَبَّلَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مَيِّتٌ. وَفِي رِوَايَةٍ: قَبَّلَ بَيْنَ عَيْنَيِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مَيِّتٌ. (خ,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ), ആഇശ(റ) എന്നിവരിൽ നിന്ന്: നബി(സ) വഫാതായപ്പോൾ അബൂബക്ർ(റ) പ്രവാചകനെ ചുംബിച്ചിരുന്നു. മറ്റൊരു റിപ്പോർട്ടുപ്രകാരം, നബി(സ) വഫാതായി കിടക്കവെ, അബൂബക്ർ(റ) അവിടുത്തെ രണ്ടു കണ്ണുകൾക്കിടയിൽ ചുംബിച്ചു. (ബു,ന,ജ)', 'ابْنِ عَبَّاسٍ وَعَنْ عَائِشَةَ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','ن','جه']::text[], array['ബു','ന','ജ']::text[], null, null, 797, 797, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=122), 1, 'وَفِي رِوَايَةٍ: قَبَّلَ بَيْنَ عَيْنَيِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مَيِّتٌ. (خ,ن,جه)', 'മറ്റൊരു നിവേദനുപ്രകാരം, നബി(സ) വഫാതായി കിടക്കവെ, അബൂബക്ർ(റ) അവിടുത്തെ രണ്ടു കണ്ണുകൾക്കിടയിൽ ചുംബിച്ചു. (ബു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ أَبَا بَكْرٍ رَضِيَ اللهُ عَنْهُ أَقْبَلَ عَلَى فَرَسٍ مِنْ مَسْكَنِهِ بِالسُّنْحِ حَتَّى نَزَلَ فَدَخَلَ الْمَسْجِدَ، فَلَمْ يُكَلِّمِ النَّاسَ حَتَّى دَخَلَ عَلَى عَائِشَةَ وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُسَجًّى بِبُرْدِ حِبَرَةٍ، فَكَشَفَ عَنْ وَجْهِهِ، ثُمَّ أَكَبَّ عَلَيْهِ فَقَبَّلَهُ فَبَكَى، ثُمَّ قَالَ: بِأَبِي أَنْتَ، وَاللهِ لَا يَجْمَعُ اللهُ عَلَيْكَ مَوْتَتَيْنِ أَبَدًا: أَمَّا الْمَوْتَةُ الَّتِي كَتَبَ اللهُ عَلَيْكَ فَقَدْ مُتَّهَا. (ن)', 'ആഇശ(റ): അബൂബക്ർ(റ) സുനുഹിലെ തന്റെ വാസസ്ഥലത്ത് നിന്ന് ഒരു കുതിരപ്പുറത്ത് വന്നിറങ്ങി പള്ളിയിൽ പ്രവേശിച്ചു. പിന്നീട് ജനങ്ങളോട് സംസാരിക്കാതെ ആഇശ(റ)യുടെ അടുക്കൽ പ്രവേശിച്ചു. അപ്പോൾ പ്രവാചകൻ(സ) ഒരു കരിമ്പടം കൊണ്ട് മൂടപ്പെട്ടിരിക്കുകയായിരുന്നു. അബൂബക്കർ(റ) തിരുമുഖത്ത് നിന്ന് വസ്ത്രം നീക്കി, പിന്നീട് മുഖം കുത്തി വീണുകൊണ്ട് നബിതിരുമേനി(സ)യെ ചുംബിക്കുകയും കരയുകയും ചെയ്തു. തുടർന്ന് ഇങ്ങനെ പറഞ്ഞു: നിങ്ങൾക്ക് എന്റെ പിതാവ് ബലി!. അല്ലാഹുവാണ, അല്ലാഹു ഒരിക്കലും താങ്കൾക്ക് രണ്ട് മരണം ഒന്നിച്ച് നൽകുകയില്ല. അല്ലാഹു താങ്കൾക്ക് വിധിച്ച ഒരു മരണം താങ്കൾ പൂകിക്കഴിഞ്ഞു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 797, 797, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: {وَلَا يَعْصِينَكَ فِي مَعْرُوفٍ} قَالَ: "النَّوْحُ". (ت,جه)', 'ഉമ്മുസലമ(റ): ''യാതെരു നന്മയിലും അങ്ങേക്കെതിരായി അവർ പ്രവർത്തിക്കുകയില്ല.'' (സൂറ: മുംതഹിന: 12) എന്ന് ഖുർആനിൽ പറഞ്ഞത് മരണപ്പെട്ടവരുടെ പേരിലുള്ള ആർത്തട്ടഹാസത്തെ കുറിച്ചാണെന്ന് തിരുമേനി(സ) പറഞ്ഞു. (തു,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 797, 797, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ: خَطَبَ بِحِمْصَ، فَذَكَرَ فِي خُطْبَتِهِ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ النَّوْحِ. (جه)', 'മുആവിയ(റ): ഹിംസിൽ വെച്ച് ഖുതുബ നിർവഹിക്കുമ്പോൾ തന്റെ ഖുതുബയിൽ മുആവിയ(റ) പറഞ്ഞു: പ്രവാചകൻ(സ) മരണപ്പെട്ടവരുടെ അടുക്കൽ ആർത്തട്ടഹാസം വിരോധിച്ചിരിക്കുന്നു. (ജ)', 'مُعَاوِيَةَ', 'മുആവിയ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 797, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنِ الْمُغِيرَةِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ كَذِبًا عَلَيَّ لَيْسَ كَكَذِبٍ عَلَى أَحَدٍ، مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ نِيحَ عَلَيْهِ يُعَذَّبُ بِمَا نِيحَ عَلَيْهِ". (خ)', 'മുഗീറ(റ): നബി(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "എന്റെ പേരിൽ കള്ളം പറയുന്നത് മറ്റൊരാളുടെ പേരിൽ കള്ളം പറയുന്നതു പോലെയല്ല. മനഃപൂർവ്വം എന്റെ പേരിൽ ഒരാൾ കള്ളം ആരോപിച്ചാൽ നരകത്തിൽ അവന്റെ ഇരിപ്പിടം അവൻ ഉറപ്പിച്ച്കൊള്ളട്ടെ." നബി(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടു: "വല്ല മയ്യിത്തിന്റെയും മേൽ ആർത്തട്ടഹസിക്കപ്പെട്ടാൽ ആ അട്ടഹാസം നിമിത്തം അവൻ ശിക്ഷിക്കപ്പെടുന്നതാണ്." (ബു)', 'الْمُغِيرَةِ', 'മുഗീറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 798, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ تُتْبَعَ جَنَازَةٌ مَعَهَا رَانَّةٌ. (جه)', 'ഇബ്നുഉമർ(റ): അട്ടഹസിച്ചു കരയാൻ ഏൽപിക്കപ്പെട്ട സ്ത്രീ കൂടെയുള്ള ജനാസയെ അനുഗമിക്കുന്നത് പ്രവാചകൻ(സ) വിരോധിച്ചിരിക്കുന്നു. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 798, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "النِّيَاحَةُ عَلَى الْمَيِّتِ مِنْ أَمْرِ الْجَاهِلِيَّةِ، فَإِنَّ النَّائِحَةَ - إِنْ لَمْ تَتُبْ قَبْلَ أَنْ تَمُوتَ - فَإِنَّهَا تُبْعَثُ يَوْمَ الْقِيَامَةِ عَلَيْهَا سَرَابِيلُ مِنْ قَطِرَانٍ، ثُمَّ يُعْلَى عَلَيْهَا بِدَرْعٍ مِنْ لَهَبِ النَّارِ". [ز: في إسناده مترك الحديث] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): തിരുമേനി(സ) അരുൾ ചെയ്തു: "മയ്യിത്തിന്റെ മേൽ ആർത്തനാദം മുഴക്കുന്നത് ജാഹിലിയാ ചര്യയാണ്. ഇങ്ങനെ കരയുന്നവൾ അവൾ മരിക്കുന്നതിന് മുമ്പ് പശ്ചാതപിച്ച് മടങ്ങിയില്ലെങ്കിൽ ഉഷ്ണചായം പൂശിയ വസ്ത്രത്തോടെ അവൾ പനഃരുദ്ധാന നാളിൽ ഉയർത്ത് എഴുന്നേൽപ്പിക്കപ്പെടുന്നതാണ്. തീജ്വാലയുടെ അങ്കി അവളുടെ മേൽ അണിയപ്പെടുകയും ചെയ്യും." (ഇതിന്റെ പരമ്പരയിൽ ഹദീസിന്റെ കാര്യത്തിൽ പരിഗണനീയനല്ലാത്ത വ്യക്തിയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مترك الحديث', null, 798, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ أَبِي مَالِكٍ الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَرْبَعٌ فِي أُمَّتِي مِنْ أَمْرِ الْجَاهِلِيَّةِ، لَا يَتْرُكُونَهُنَّ: الْفَخْرُ فِي الْأَحْسَابِ، وَالطَّعْنُ فِي الْأَنْسَابِ، وَالِاسْتِسْقَاءُ بِالنُّجُومِ، وَالنِّيَاحَةُ. وَقَالَ: النَّائِحَةُ إِذَا لَمْ تَتُبْ قَبْلَ مَوْتِهَا، تُقَامُ يَوْمَ الْقِيَامَةِ وَعَلَيْهَا سِرْبَالٌ مِنْ قَطِرَانٍ وَدِرْعٌ مِنْ جَرَبٍ". (م)', 'അബൂമാലികിൽ അശ്അരി(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നാല് കാര്യങ്ങൾ എന്റെ സമുദായത്തിൽ ജാഹിലിയ്യ ആചാരങ്ങളാണ്. അവരത് ഉപേക്ഷിക്കുകയില്ല. കുലമഹിമയിൽ അഭിമാനം പറയുക, വംശത്തിന്റെ പേരിൽ ആക്ഷേപിക്കുക, നക്ഷത്രം കൊണ്ട് മഴയെ തേടുക, മരിച്ചവരുടെ പേരിൽ അട്ടഹസിച്ച് കരയുക എന്നിവയാണവ. തുടർന്ന് നബി(സ) പറഞ്ഞു: ഇങ്ങനെ കരയുന്നവൾ മരണത്തിന്റെ മുമ്പ് പശ്ചാതപിച്ചില്ലെങ്കിൽ ചൂടു ചായം പൂശിയ വസ്ത്രത്തോടും അങ്കിയോടും കൂടി പുനരുദ്ധാരണനാളിൽ ഉയിർത്തെഴുന്നേൽപ്പിക്കപ്പെടുന്നതാണ്." (മു)', 'أَبِي مَالِكٍ الْأَشْعَرِيِّ', 'അബൂമാലികിൽ അശ്അരി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 798, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ عَلِيِّ بْنِ رَبِيعَةَ الْأَسَدِيِّ قَالَ: مَاتَ رَجُلٌ مِنَ الْأَنْصَارِ يُقَالُ لَهُ قَرَظَةُ بْنُ كَعْبٍ، فَنِيحَ عَلَيْهِ، فَجَاءَ الْمُغِيرَةُ بْنُ شُعْبَةَ - رَضِيَ اللهُ عَنْهُ - فَصَعِدَ الْمِنْبَرَ، فَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ وَقَالَ: مَا بَالُ النَّوْحِ فِي الْإِسْلَامِ؟ أَمَا إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ نِيحَ عَلَيْهِ عُذِّبَ بِمَا نِيحَ عَلَيْهِ". حَسَنٌ صَحِيحٌ. (ب,م,ق,ت)', 'അലിയ്യുബ്നു റബീഅതുൽ അസദി(റ): ഖറളതുബ്നു കഅ്ബ് എന്ന് പേര് വിളിക്കപ്പെടുന്ന ഒരു അൻസാരി മരിച്ചപ്പോൾ അയാൾക്ക് വേണ്ടി ആർത്തു കരയുകയുണ്ടായി. ഉടനെ മുഗീറത്തുബ്നു ശുഅ്ബ(റ) അവിടെ ചെന്ന് പ്രസംഗപീഠത്തിൽ കയറി. അല്ലാഹുവിനെ സ്തുതിക്കുകയും പ്രകീർത്തിക്കുകയും ചെയ്തുകൊണ്ട് ഇങ്ങനെ പറഞ്ഞു: എന്താണ് ഇസ്ലാമിൽ ഇങ്ങനെ കരയുന്നതിന്റെ സ്ഥിതി? പ്രവാചകൻ(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. "ആരുടെ പേരിലാണോ ഇപ്രകാരം കരയുന്നത് അയാൾ ഈ കരച്ചിൽ നിമിത്തം ശിക്ഷിക്കപ്പെടും." (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,തു)', 'عَلِيِّ بْنِ رَبِيعَةَ الْأَسَدِيِّ قَالَ', 'അലിയ്യുബ്നു റബീഅതുൽ അസദി(റ)', null, null, '{}'::text[], array['ബു','മു','തു']::text[], 'ب,م,ق,ت', null, 798, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَرْبَعٌ فِي أُمَّتِي مِنْ أَمْرِ الْجَاهِلِيَّةِ. لَنْ يَدَعَهُنَّ النَّاسُ: النِّيَاحَةُ، وَالطَّعْنُ فِي الْأَحْسَابِ، وَالْعَدْوَى: أَجْرَبَ بَعِيرٌ فَأَجْرَبَ مِائَةَ بَعِيرٍ، مَنْ أَجْرَبَ الْبَعِيرَ الْأَوَّلَ؟ وَالْأَنْوَاءُ: مُطِرْنَا بِنَوْءِ كَذَا وَكَذَا". حَسَنٌ. (ت)', 'അബുഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിൽ നാല് കാര്യങ്ങൾ ജാഹിലിയ്യ ആചാരങ്ങളാണ്. അവ ജനങ്ങൾ ഉപേക്ഷിക്കുകയില്ല. മരിച്ചവരുടെ പേരിൽ ആർത്തട്ടഹസിച്ച് കരയുക, വംശത്തിന്റെ പേരിൽ ആക്ഷേപിക്കുക, പകർച്ചവ്യാധിയിൽ വിശ്വസിക്കുക, ഒരു ചൊറി പിടിച്ച ഒട്ടകം നൂറ് ഒട്ടകത്തിന് ചൊറി പരത്തി എന്ന് പറയുമ്പോൾ, ഒന്നാമത്തെ ഒട്ടകത്തിന് ചൊറി പരത്തിയതാര്? നക്ഷത്രശാസ്ത്രത്തിൽ വിശ്വസിക്കുക, അതാതയത് ഇന്നിന്ന നക്ഷത്രം കൊണ്ടാണ് മഴ വർഷിച്ചത് എന്ന് പറയുക." (ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു). (തു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَانَا عَنِ النِّيَاحَةِ. (ق,د,ن)', 'ഉമ്മുഅതിയ്യ(റ): പ്രവാചകൻ(സ) ഞങ്ങളോട് മരണപ്പെട്ടവരുടെ പേരിൽ ആർത്തട്ടഹസിച്ച് കരയുന്നത് വിരോധിച്ചിരുന്നു. (ബു,മു,ദ,ന)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅതിയ്യ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: لَعَنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ النَّائِحَةَ وَالْمُسْتَمِعَةَ. (د)', 'അബൂസഈദുൽ ഖുദ്രി(റ): മരണപ്പെട്ടവരുടെ പേരിൽ അട്ടഹസിച്ച് കരയുന്നവളെയും, കട്ടു കേൾക്കുന്നവളെയും നബി(സ) ശപിച്ചിരിക്കുന്നു. (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْمَيِّتَ لَيُعَذَّبُ بِبُكَاءِ أَهْلِهِ عَلَيْهِ". فَذُكِرَ ذَلِكَ لِعَائِشَةَ رَضِيَ اللهُ عَنْهَا، فَقَالَتْ: وَهِلَ - تَعْنِي ابْنَ عُمَرَ - إِنَّمَا مَرَّ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى قَبْرٍ فَقَالَ: "إِنَّ صَاحِبَ هَذَا لَيُعَذَّبُ، وَأَهْلُهُ يَبْكُونَ عَلَيْهِ". ثُمَّ قَرَأَتْ {وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى} [الإسراء: 15] وَفِي رِوَايَةٍ: عَلَى قَبْرِ يَهُودِيٍّ. (م,د,ن)', 'ഇബ്നുഉമർ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "തന്റെ കുടുംബങ്ങൾ തനിക്ക് വേണ്ടി കരയുന്നത് നിമിത്തം മയ്യിത്ത് ശിക്ഷിക്കപ്പെടും." ഈ ഹദീസ് ആഇശ(റ)യോട് പറയപ്പെട്ടപ്പോൾ ആഇശ(റ) ഇങ്ങിനെ പറഞ്ഞു: ഇബ്നുഉമറി(റ)ന് ഇതിന്റെ ആശയം ഗ്രഹിക്കുന്നതിൽ പിശകുപറ്റി. തിരുമേനി(സ) ഒരു ഖബറിന്റെ അരികെ നടന്നുപോകുമ്പോൾ ഇപ്രകാരം പറഞ്ഞു: "നിശ്ചയം ഈ ഖബറാളി ശിക്ഷിക്കപ്പെടുന്നു. അവന്റെ കുടുംബങ്ങളോ അവന്റെ പേരിൽ കരയുകയാണ് താനും." പിന്നീട് അവർ ഓതി ''ഒരു ആത്മാവും മറ്റൊരു ആത്മാവിന്റെ പാപഭാരം ചുമക്കുകയില്ല.'' ( ഇസ്റാഅ്: 15) എന്ന സൂക്തം ഓതിക്കേൾപിച്ചു. ഒരു റിപ്പോർട്ടുപ്രകാരം ''ഒരു ജൂതന്റെ ഖബറിന്നരികിലൂടെ നടന്നുപോയപ്പോൾ..........'' എന്നാണ്. (മു,ദ,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], 'الإسراء: 15', null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=134), 1, 'وَفِي رِوَايَةٍ: عَلَى قَبْرِ يَهُودِيٍّ. (م,د,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ قَيْسِ بْنِ عَاصِمٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَا تَنُوحُوا عَلَيَّ، فَإِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمْ يُنَحْ عَلَيْهِ. (ن)', 'ഖൈസ്ബ്നു ആസിം(റ): നിങ്ങൾ എന്റെ മേൽ ആർത്തു കരയരുത്, കാരണം പ്രവാചക(സ)ന്റെ മേൽ ആർത്തു കരയപ്പെട്ടിട്ടില്ല. (ന)', 'قَيْسِ بْنِ عَاصِمٍ', 'ഖൈസ്ബ്നു ആസിം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَخَذَ عَلَى النِّسَاءِ حِينَ بَايَعَهُنَّ: أَنْ لَا يَنُحْنَ. فَقُلْنَ: يَا رَسُولَ اللهِ، إِنَّ نِسَاءً أَسْعَدْنَنَا فِي الْجَاهِلِيَّةِ، أَفَنُسْعِدُهُنَّ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا إِسْعَادَ فِي الْإِسْلَامِ". (ن)', 'അനസ്(റ): പ്രവാചകൻ(സ) സ്ത്രീകളോട് ഉടമ്പടി ചെയ്യുമ്പോൾ മരിച്ചവരുടെ പേരിൽ ആർത്തട്ടഹസിച്ച് കരയരുതെന്നും ഉടമ്പടി ചെയ്തു. അപ്പോൾ അവർ ചോദിച്ചു: പ്രവാചകരെ, ജാഹിലിയ്യാകാലത്ത് ഞങ്ങളെ കരയാൻ പ്രോത്സാഹിപ്പിച്ച സ്ത്രീകളെ ഞങ്ങൾ പ്രോത്സാഹിപ്പിക്കേണ്ടതില്ലേ? പ്രവാചകൻ(സ) പറഞ്ഞു: "ഇസ്ലാമിൽ അത്തരം പ്രോത്സാഹനമില്ല." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 800, 800, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنْ عُمَرَ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْمَيِّتُ يُعَذَّبُ فِي قَبْرِهِ بِالنِّيَاحَةِ عَلَيْهِ". (ن)', 'ഉമറി(റ)ൽനിന്ന് ഇബ്നുഉമർ(റ): പ്രവാചകൻ(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടു: "ആർത്തട്ടഹസിച്ച് കരയുന്നത് നിമിത്തം മയ്യിത്ത് ഖബറിൽ വെച്ച് ശിക്ഷിക്കപ്പെടുന്നതാണ്." (ന)', 'ابْنِ عُمَرَ', 'ഉമറി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 800, 800, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: الْمَيِّتُ يُعَذَّبُ بِنِيَاحَةِ أَهْلِهِ عَلَيْهِ. فَقَالَ لَهُ رَجُلٌ: أَرَأَيْتَ رَجُلًا مَاتَ بِخُرَاسَانَ، وَنَاحَ أَهْلُهُ عَلَيْهِ هَاهُنَا، أَكَانَ يُعَذَّبُ بِنِيَاحَةِ أَهْلِهِ؟ قَالَ: صَدَقَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَكَذَبْتَ أَنْتَ. (ن)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): കുടുംബങ്ങൾ ആർത്തട്ടഹസിച്ച് കരയുന്നത് നിമിത്തം മയ്യിത്ത് ശിക്ഷിക്കപ്പെടും. അപ്പോൾ ഒരാൾ ചോദിച്ചു: ഖുറാസാനിൽ ഒരാൾ മരിക്കുന്നു. ഇവിടെ അവന് വേണ്ടി അവന്റെ കുടുംബങ്ങൾ ആർത്തു കരയുമ്പോൾ തന്റെ കുടുംബങ്ങൾ കരയുന്നത് നിമിത്തം അവൻ ശിക്ഷിക്കപ്പെടുമോ? എന്താ നിന്റെ അഭിപ്രായം? അദ്ദേഹം പറഞ്ഞു: പ്രവാചകൻ(സ) പറഞ്ഞതാണ് സത്യം, നീ പറയുന്നത് അസത്യവും. (ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 800, 800, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، وَذُكِرَ لَهَا: أَنَّ عَبْدَ اللهِ بْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: "إِنَّ الْمَيِّتَ لَيُعَذَّبُ بِبُكَاءِ الْحَيِّ عَلَيْهِ". قَالَتْ عَائِشَةُ: يَغْفِرُ اللهُ لِأَبِي عَبْدِ الرَّحْمَنِ، أَمَا إِنَّهُ لَمْ يَكْذِبْ، وَلَكِنْ نَسِيَ أَوْ أَخْطَأَ، إِنَّمَا مَرَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى يَهُودِيَّةٍ يُبْكَى عَلَيْهَا، فَقَالَ: "إِنَّهُمْ لَيَبْكُونَ عَلَيْهَا وَإِنَّهَا لَتُعَذَّبُ". (ن)', 'ആയിശ(റ): "ജീവിച്ചിരിക്കുന്നവർ തനിക്ക് വേണ്ടി കരയുന്നത് നിമിത്തം മയ്യിത്ത് ശിക്ഷിക്കപ്പെടും'' എന്ന് അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) പറയുന്നു എന്ന് മഹതിയോട് പറയപ്പെട്ടു. ആയിശ(റ) പറഞ്ഞു. അല്ലാഹു അബൂഅബ്ദുറഹ്മാന് മാപ്പ് നൽകട്ടെ, അദ്ദേഹം കളവ് പറഞ്ഞതല്ല, പക്ഷേ ഒന്നുകിൽ മറന്നു. അല്ലെങ്കിൽ തെറ്റ് പറ്റി. കരച്ചിൽ നടക്കുന്ന ഒരു ജൂത സ്ത്രീയുടെ അരികെ തിരുമേനി(സ) നടക്കുമ്പോൾ തിരുമേനി(സ) ഇങ്ങനെ പറഞ്ഞതാണ്: "അവർ അവൾക്ക് വേണ്ടി കരഞ്ഞ്കൊണ്ടിരിക്കുന്നു. അവളോ ശിക്ഷിക്കപ്പെടുകയും ചെയ്യുന്നു." (ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 800, 800, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمَيِّتُ يُعَذَّبُ بِبُكَاءِ الْحَيِّ، إِذَا قَالُوا: وَا عَضُدَاهُ، وَا كَاسِيَاهُ، وَا نَاصِرَاهُ، وَا جَبَلَاهُ، وَنَحْوَ هَذَا. يُتَعْتَعُ وَيُقَالُ: أَنْتَ كَذَلِكَ؟ أَنْتَ كَذَلِكَ". (ت,جه)', 'അബൂമൂസൽ അശ്അരി(റ): നബി തിരുമേനി(സ) പറഞ്ഞു: "ജീവിച്ചിരിക്കുന്നവർ കരയുന്നത് നിമിത്തം മയ്യിത്ത് ശിക്ഷിക്കപ്പെടും. എന്റെ അവലംബമേ! പുടവ നൽകിയവനേ! സഹായമായവനേ! എന്റെ പർവതമേ! എന്നിങ്ങനെ അവർ പറയുമ്പോൾ ഇവന്റെ നാവ് ഇടറുന്നു. നീ അങ്ങനെയാണോ നീ അങ്ങനെയാണോ എന്ന് അവനോട് ചോദിക്കപ്പെടും." (തു,ജ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 800, 800, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا حُضِرَتْ بِنْتٌ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَغِيرَةٌ، فَأَخَذَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَضَمَّهَا إِلَى صَدْرِهِ، ثُمَّ وَضَعَ يَدَهُ عَلَيْهَا، فَقَضَتْ وَهِيَ بَيْنَ يَدَيْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَبَكَتْ أُمُّ أَيْمَنَ، فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا أُمَّ أَيْمَنَ، أَتَبْكِينَ وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عِنْدَكِ". فَقَالَتْ: مَا لِي لَا أَبْكِي وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَبْكِي؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَسْتُ أَبْكِي، وَلَكِنَّهَا رَحْمَةٌ". ثُمَّ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمُؤْمِنُ بِخَيْرٍ عَلَى كُلِّ حَالٍ تُنْزَعُ نَفْسُهُ مِنْ بَيْنِ جَنْبَيْهِ، وَهُوَ يَحْمَدُ اللهَ عَزَّ وَجَلَّ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യുടെ ഒരു ചെറിയ മകൾക്ക് മരണം ആസന്നമായപ്പോൾ തിരുമേനി(സ) കുട്ടിയെ എടുത്ത് തന്റെ നെഞ്ചോട് ചേർക്കുകയും തന്റെ കൈ അവളുടെ മേൽ വെക്കുകയും ചെയ്തു. അങ്ങനെ കുട്ടി തിരുമേനി(സ)യുടെ കൈകൾക്കിടയിലായി മരണം വരിച്ചു. അന്നേരം ഉമ്മുഐമൻ കരഞ്ഞപ്പോൾ തിരുമേനി(സ) മഹതിയോട് പറഞ്ഞു: "ഉമ്മുഐമൻ! പ്രവാചകൻ(സ) നിന്റെ അരികെ ഉണ്ടായിട്ടും നീ കരയുകയോ?" മഹതി പറഞ്ഞു: പ്രവാചകൻ(സ) തന്നെ കരയുമ്പോൾ ഞാൻ എങ്ങിനെ കരയാതിരിക്കും. നബി(സ) പറഞ്ഞു: "ഞാൻ കരയുകയല്ല; പക്ഷേ ഇത് കാരുണ്യമാണ്." പിന്നീട് പ്രവാചകൻ(സ) പറഞ്ഞു: "സത്യവിശ്വാസി എപ്പോഴും നന്മയിലേക്കാണ്. തന്റെ രണ്ടുപാർശ്വങ്ങൾക്കിടയിൽനിന്ന് ആത്മാവ് ഊരിയെടുക്കുമ്പോഴും അവൻ അല്ലാഹുവിനെ സ്തുതിക്കുന്നു." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 801, 801, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ فَاطِمَةَ بَكَتْ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ مَاتَ، فَقَالَتْ: يَا أَبَتَاهُ مِنْ رَبِّهِ مَا أَدْنَاهُ، يَا أَبَتَاهُ إِلَى جِبْرِيلَ نَنْعَاهْ، يَا أَبَتَاهُ جَنَّةُ الْفِرْدَوْسِ مَأْوَاهْ. (ن)', 'അനസ്(റ): നബി(സ) വഫാതായപ്പോൾ തിരുമേനി(സ)യുടെ മേൽ ഫാത്വിമ(റ) കരഞ്ഞു. മഹതി ഇങ്ങനെ പറഞ്ഞു: എന്റെ പിതാവേ! തന്റെ നാഥനിലേക്ക് എത്ര അടുത്ത് കഴിഞ്ഞു. എന്റെ പിതാവേ! ജിബ്രീലി(അ)നോട് ഞങ്ങൾ മരണവാർത്ത അറിയിക്കുന്നു. എന്റെ പിതാവേ! ഫിർദൗസ് എന്ന സ്വർഗമാണ് അഭയം. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 801, 801, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ أَبَاهُ قُتِلَ يَوْمَ أُحُدٍ، قَالَ: فَجَعَلْتُ أَكْشِفُ عَنْ وَجْهِهِ وَأَبْكِي، وَالنَّاسُ يَنْهَوْنَنِي وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يَنْهَانِي، وَجَعَلَتْ عَمَّتِي تَبْكِيهِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَبْكِيهِ، مَا زَالَتِ الْمَلَائِكَةُ تُظِلُّهُ بِأَجْنِحَتِهَا حَتَّى رَفَعْتُمُوهُ". (خ,ن)', 'ജാബിർ(റ): അദ്ദേഹത്തിന്റെ പിതാവ് ഉഹ്ദ് യുദ്ധത്തിൽ വധിക്കപ്പെട്ടു. അദ്ദേഹം പറയുന്നു: അങ്ങനെ ഞാൻ പിതാവിന്റെ മുഖം നീക്കി കരയാൻ തുടങ്ങി. അതേ സമയം ജനങ്ങൾ എന്നെ തടയുന്നുണ്ടായിരുന്നു; പ്രവാചകൻ(സ) എന്നെ തടയുന്നുമില്ല. എന്റെ അമ്മായിയും അവർക്ക് വേണ്ടി കരയുകയാണ്. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങൾ അദ്ദേഹത്തിന് വേണ്ടി കരയേണ്ട. നിങ്ങൾ അദ്ദേഹത്തെ ഉയർത്തുന്നത്വരെ മാലാഖമാർ അദ്ദേഹത്തിന് ചിറകുകൾകൊണ്ട് തണലേകിക്കൊണ്ടിരിക്കുന്നു." (ബു,ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 801, 801, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا أَتَى نَعْيُ زَيْدِ بْنِ حَارِثَةَ وَجَعْفَرِ بْنِ أَبِي طَالِبٍ وَعَبْدِ اللهِ بْنِ رَوَاحَةَ جَلَسَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعْرَفُ فِيهِ الْحُزْنُ، وَأَنَا أَنْظُرُ مِنْ صِئرِ الْبَابِ، فَجَاءَهُ رَجُلٌ فَقَالَ: إِنَّ نِسَاءَ جَعْفَرٍ يَبْكِينَ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "انْطَلِقْ فَانْهَهُنَّ". فَانْطَلَقَ ثُمَّ جَاءَ فَقَالَ: قَدْ نَهَيْتُهُنَّ فَأَبَيْنَ أَنْ يَنْتَهِينَ. فَقَالَ: "انْطَلِقْ فَانْهَهُنَّ". فَانْطَلَقَ ثُمَّ جَاءَ فَقَالَ: قَدْ نَهَيْتُهُنَّ فَأَبَيْنَ أَنْ يَنْتَهِينَ. قَالَ: "فَانْطَلِقْ، فَاحْثُ فِي أَفْوَاهِهِنَّ التُّرَابَ". فَقَالَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: فَقُلْتُ: أَرْغَمَ اللهُ أَنْفَ الْأَبْعَدِ، إِنَّكَ وَاللهِ مَا تَرَكْتَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَمَا أَنْتَ بِفَاعِلٍ. (ن)', 'ആയിശ(റ): സൈദുബ്നു ഹാരിസ്(റ), ജഅ്ഫറുബ്നു അബീത്വാലിബ്(റ), അബ്ദുല്ലാഹിബ്നു റവാഹഃ(റ) എന്നിവരുടെ മരണ വാർത്ത ലഭിച്ചപ്പോൾ തിരുമേനി(സ) ദുഃഖം തിരിച്ചറിയാവുന്ന വിധത്തിൽ ഇരിപ്പിലായി. ഞാൻ വാതിലിൽക്കൂടി നോക്കുന്നുണ്ടായിരുന്നു. അപ്പോൾ തിരുമേനി(സ)യുടെ അടുക്കൽ ഒരാൾ വന്നിട്ട് ജഅ്ഫറി(റ)ന്റെ സ്ത്രീകൾ കരയുന്നു എന്ന് അറിയിച്ചു. പ്രവാചകൻ(സ) പറഞ്ഞു: "നീ പോയി അവരെ വിലക്കുക." അദ്ദേഹം പോയി തിരിച്ച് വന്ന് പറഞ്ഞു: ഞാൻ അവരെ തടഞ്ഞിട്ടും അവർ നിർത്താൻ വിസമ്മതിക്കുകയാണ്. തിരുമേനി(സ) പറഞ്ഞു: "നീ പോയി അവരെ തടയുക." അദ്ദേഹം പോയി തിരിച്ചുവന്ന് പറഞ്ഞു: ഞാൻ തടഞ്ഞിട്ടും അവർ നിർത്താൻ വിസമ്മതിക്കുകയാണ്. തിരുമേനി(സ) പറഞ്ഞു: "നീ പോയി അവരുടെ വായിൽ മണ്ണ് വാരിയിടുക." അയിശ(റ) പറഞ്ഞു: അല്ലാഹുവിൽ നിന്ന് വിദൂരമായവരുടെ മൂക്ക് മണ്ണോട് ചേരട്ടെ. താങ്കൾ ഒരിക്കലും റസൂലിനെ ഉപേക്ഷിക്കുകയില്ല, നിങ്ങൾ അത് ചെയ്യുകയില്ല. (ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 801, 802, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَخَذَ عَلَيْنَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عِنْدَ الْبَيْعَةِ أَنْ لَا نَنُوحَ، فَمَا وَفَتْ مِنَّا امْرَأَةٌ غَيْرَ خَمْسٍ: أُمُّ سُلَيْمٍ، وَأُمُّ الْعَلَاءِ، وَابْنَةُ أَبِي سَبْرَةَ، امْرَأَةُ مُعَاذٍ، وَامْرَأَتَيْنِ، أَوِ ابْنَةُ أَبِي سَبْرَةَ وَامْرَأَةُ مُعَاذٍ وَامْرَأَةٌ أُخْرَى. (خ)', 'ഉമ്മുഅത്വിയ്യ(റ): തിരുമേനി(സ) ഞങ്ങളുടെ മേൽ ഉടമ്പടി സ്വീകരിക്കുമ്പോൾ ഞങ്ങൾ മയ്യിത്തിന്റെ അടുക്കൽ ആർത്തട്ടഹസിച്ച് കരയരുതെന്നും ഉടമ്പടി ചെയ്തു. എന്നാൽ ഞങ്ങളിൽ നിന്ന് അഞ്ച് സ്ത്രീകളല്ലാതെ ഒരു സ്ത്രീയും അത് പാലിച്ചില്ല. ഉമ്മുസുലൈം(റ), ഉമ്മുൽ അലാഅ്(റ), അബൂസബ്റയുടെ മകൾ, മൂആദിന്റെ ഭാര്യ, മറ്റ് രണ്ടു സ്ത്രീകളും. അല്ലെങ്കിൽ അബൂസബ്റയുടെ മകളും മൂആദിന്റെ ഭാര്യയും മറ്റൊരു സ്ത്രീയും ആണവർ. (ബു)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅത്വിയ്യ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 802, 802, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: شَهِدْنَا بِنْتًا لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ عَلَى الْقَبْرِ، قَالَ: فَرَأَيْتُ عَيْنَيْهِ تَدْمَعَانِ قَالَ: فَقَالَ: "هَلْ مِنْكُمْ رَجُلٌ لَمْ يُقَارِفِ اللَّيْلَةَ؟" فَقَالَ أَبُو طَلْحَةَ: أَنَا، قَالَ: "فَانْزِلْ". فَنَزَلَ فِي قَبْرِهَا. (خ)', 'അനസുബ്നു മാലിക്(റ): തിരുമേനി(സ)യുടെ ഒരു മകളുടെ മരണത്തിന് ഞങ്ങൾ സാക്ഷികളായി. അദ്ദേഹം പറയുന്നു. തിരുമേനി(സ) ഖബ്റിന്റെ മേൽ ഇരിക്കുകയാണ്. അദ്ദേഹം പറയുന്നു. അവിടത്തെ കണ്ണുകൾ ഈറനണിയുന്നത് ഞാൻ കണ്ടു. അദ്ദേഹം പറഞ്ഞു. "നിങ്ങളിൽ ഇന്നലെ രാത്രി തെറ്റു ചെയ്യാത്ത വല്ലവരുമുണ്ടോ?" എന്ന് തിരുമേനി(സ) ചോദിച്ചു. ഞാനുണ്ട് എന്ന് അബുതൽഹ(റ) പറഞ്ഞു. പ്രവാചകൻ(സ) പറഞ്ഞു: "എന്നാൽ നീ ഇറങ്ങു." അങ്ങനെ അദ്ദേഹം (മയ്യിത്തു വെക്കാൻ വേണ്ടി) അവളുടെ ഖബറിൽ ഇറങ്ങി. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 802, 802, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنِ ابْنِ أَبِي مُلَيْكَةَ قَالَ: لَمَّا هَلَكَتْ أُمُّ أَبَانَ حَضَرْتُ مَعَ النَّاسِ، فَجَلَسْتُ بَيْنَ عَبْدِ اللهِ بْنِ عُمَرَ وَابْنِ عَبَّاسٍ - رَضِيَ اللهُ عَنْهُمْ - فَبَكَيْنَ النِّسَاءُ، فَقَالَ ابْنُ عُمَرَ: أَلَا تَنْهَى هَؤُلَاءِ عَنِ الْبُكَاءِ؟ فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ الْمَيِّتَ لَيُعَذَّبُ بِبَعْضِ بُكَاءِ أَهْلِهِ عَلَيْهِ". فَقَالَ ابْنُ عَبَّاسٍ: قَدْ كَانَ عُمَرُ يَقُولُ بَعْضَ ذَلِكَ، خَرَجْتُ مَعَ عُمَرَ حَتَّى إِذَا كُنَّا بِالْبَيْدَاءِ رَأَى رَكْبًا تَحْتَ شَجَرَةٍ، فَقَالَ: انْظُرْ مَنِ الرَّكْبُ؟ فَذَهَبْتُ فَإِذَا صُهَيْبٌ وَأَهْلُهُ، فَرَجَعْتُ إِلَيْهِ فَقُلْتُ: يَا أَمِيرَ الْمُؤْمِنِينَ، هَذَا صُهَيْبٌ وَأَهْلُهُ. فَقَالَ: عَلَيَّ بِصُهَيْبٍ. فَلَمَّا دَخَلْنَا الْمَدِينَةَ أُصِيبَ عُمَرُ، فَجَلَسَ صُهَيْبٌ يَبْكِي عِنْدَهُ يَقُولُ: وَا أُخَيَّاهُ، وَا أُخَيَّاهُ. فَقَالَ عُمَرُ: يَا صُهَيْبُ، لَا تَبْكِ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ الْمَيِّتَ لَيُعَذَّبُ بِبَعْضِ بُكَاءِ أَهْلِهِ عَلَيْهِ". قَالَ فَذَكَرْتُ ذَلِكَ لِعَائِشَةَ رَضِيَ اللهُ عَنْهَا، فَقَالَتْ: أَمَا وَاللهِ مَا تُحَدِّثُونَ هَذَا الْحَدِيثَ عَنْ كَاذِبَيْنِ مُكَذَّبِينَ، وَلَكِنَّ السَّمْعَ يُخْطِئُ، وَإِنَّ لَكُمْ فِي الْقُرْآنِ لَمَا يَشْفِيكُمْ أَنْ: {لَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى} [الأنعام: ١٦٤] وَلَكِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللهَ لَيَزِيدُ الْكَافِرَ عَذَابًا بِبُكَاءِ أَهْلِهِ عَلَيْهِ". (خ,ن)', 'ഇബ്നുഅബൂമുലൈക(റ): ഉമ്മുഅബാന(റ) മരണപ്പെട്ടപ്പോൾ ഞാൻ ജനങ്ങളോടൊപ്പം സന്നിഹിതനായി. അങ്ങനെ ഞാൻ അബ്ദുല്ലാഹിബ്നു ഉമറി(റ)ന്റെയും ഇബ്നുഅബ്ബാസിന്റെ(റ)യും ഇടയിൽ ഇരിക്കുമ്പോൾ സ്ത്രീകൾ കരയാൻ തുടങ്ങി. അപ്പോൾ ഇബ്നുഉമർ(റ) പറഞ്ഞു. നീ ഈ സ്ത്രീകളുടെ കരച്ചിൽ തടയുന്നില്ലേ? പ്രവാചകൻ(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "തന്റെ മേൽ തന്റെ കുടുംബങ്ങളിൽ ചിലർ കരയുന്നത് കാരണം മയ്യിത്ത് ശിക്ഷിക്കപ്പെടും." ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: ഉമറും(റ) അങ്ങനെ ചിലത് പറയാറുണ്ടായിരുന്നു. ഞാൻ ഉമറി(റ)ന്റെ കൂടെ പോകുകയായിരുന്നു. അങ്ങനെ ഞങ്ങൾ മരുഭൂമിയിൽ എത്തിയപ്പോൾ ഒരു മരച്ചുവട്ടിൽ ഒരു യാത്രാസംഘത്തെ കണ്ടു. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: ആരാണ് യാത്രാ സംഘമെന്ന് നോക്കൂ. ഞാൻ പോയി നോക്കിയപ്പോൾ അത് സുഹൈബും(റ) കുടുംബവുമായിരുന്നു. അങ്ങനെ ഞാൻ ഉമറി(റ)ന്റെ അടുക്കൽ തിരിച്ച് ചെന്ന് അമീറുൽ മുഅ്മിനീൻ അത് സുഹൈബും കുടുംബവുമാണെന്ന് പറഞ്ഞു. അദ്ദേഹം സുഹൈബി(റ)നെ കൂട്ടാൻ പറഞ്ഞു. അങ്ങനെ ഞങ്ങൾ മദീനയിൽ കടന്നപ്പോൾ ഉമറി(റ)ന് അപകടമുണ്ടായി. അങ്ങനെ അദ്ദേഹത്തിന്റെ അരികെ ഇരുന്നുകൊണ്ട് സുഹൈബ്(റ) കൊച്ചുസഹോദരാ, കൊച്ചു സഹോദരാ എന്ന് വിലപിച്ച് പറയുന്നുണ്ടായിരുന്നു. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: സുഹൈബ് നീ കരയരുത്. പ്രവാചകൻ(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "തന്റെ മേൽ തന്റെ കുടുംബാംഗങ്ങളിൽ ചിലർ കരയുന്നത് നിമിത്തം മയ്യിത്ത് ശിക്ഷിക്കപ്പെടും." അദ്ദേഹം പറയുകയാണ്: പിന്നീട് ഇത് ഞാൻ ആയിഷ(റ)യോട് പറഞ്ഞപ്പോൾ, മഹതി പറഞ്ഞു: അല്ലാഹുവാണേ നിങ്ങൾ ഹദീസ് ഉദ്ധരിക്കുന്നത് വ്യാജം ചമക്കുന്ന രണ്ടു പേരിൽ നിന്നൊന്നുമല്ല. പക്ഷേ കേൾവിക്ക് അബദ്ധം പിണയും. ഈ ഖുർആൻ വാക്യം തീർച്ചയായും നിങ്ങൾക്ക് ശമനം നൽകും. ''ഒരു ആത്മാവും മറ്റൊരു ആത്മാവിന്റെ പാപഭാരം വഹിക്കുകയില്ല.'' (അൻആം: 164) എന്നാൽ പ്രവാചകൻ(സ) പറഞ്ഞത് "സത്യനിഷേധിയുടെ മേൽ തന്റെ കുടുംബം കരയുന്നത് നിമിത്തം അല്ലാഹു ശിക്ഷ വർദ്ധിപ്പിക്കും" എന്നാണ്. (ബു,ന)', 'ابْنِ أَبِي مُلَيْكَةَ قَالَ', 'ഇബ്നുഅബൂമുലൈക(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], 'الأنعام: ١٦٤', null, 802, 803, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وُلِدَ لِي اللَّيْلَةَ غُلَامٌ، فَسَمَّيْتُهُ بِاسْمِ أَبِي إِبْرَاهِيمَ". قَالَ أَنَسٌ: لَقَدْ رَأَيْتُهُ يَكِيدُ بِنَفْسِهِ بَيْنَ يَدَيْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَدَمَعَتْ عَيْنَا رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "تَدْمَعُ الْعَيْنُ، وَيَحْزَنُ الْقَلْبُ، وَلَا نَقُولُ إِلَّا مَا يُرْضِي رَبَّنَا، إِنَّا بِكَ يَا إِبْرَاهِيمُ لَمَحْزُونُونَ". (م,د)', 'അനസ് ഇബ്നുമാലിക്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "കഴിഞ്ഞ രാത്രി എനിക്കൊരു കുഞ്ഞു ജനിച്ചു. ഞാൻ അവന് എന്റെ പിതാവിന്റെ പേരായ ''ഇബ്രാഹിം'' എന്ന് പേര് വിളിച്ചു." അനസ്(റ) പറയുന്നു. തിരുമേനി(സ)യുടെ കൈകൾക്കിടയിൽ നിന്ന് അവൻ അന്ത്യശ്വാസം വലിക്കുന്നത് ഞാൻ കണ്ടു. അപ്പോൾ അവിടുത്തെ കണ്ണുകൾ ഈറനണിഞ്ഞു. തിരുമേനി(സ) പറഞ്ഞു: "കണ്ണു നിറഞ്ഞൊഴുകുന്നു. ഹൃദയം വ്യാകുലപ്പെടുന്നു. നമ്മുടെ നാഥന് ഇഷ്ടമല്ലാത്തത് നാം പറയില്ല. ഓ ഇബ്റാഹിം! നീ കാരണം ഞങ്ങൾ ദുഃഖം പേറുകയാണ്." (മു,ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ് ഇബ്നുമാലിക്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 803, 803, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ يَزِيدَ بْنِ أَوْسٍ قَالَ: دَخَلْتُ عَلَى أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ وَهُوَ ثَقِيلٌ، فَذَهَبَتِ امْرَأَتُهُ لِتَبْكِيَ، أَوْ تَهُمَّ بِهِ، فَقَالَ أَبُو مُوسَى: أَمَا سَمِعْتِ مَا قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَتْ: بَلَى، قَالَ: فَسَكَتَتْ، فَلَمَّا مَاتَ أَبُو مُوسَى قَالَ يَزِيدُ: لَقِيتُ الْمَرْأَةَ فَقُلْتُ لَهَا: مَا قَوْلُ أَبِي مُوسَى لَكِ: أَمَا سَمِعْتِ قَوْلَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ سَكَتَ؟ قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ مِنَّا مَنْ حَلَقَ وَمَنْ سَلَقَ وَمَنْ خَرَقَ". (م,د,ن,جه)', 'യസിദുബ്നു ഔസ്(റ): അബൂമൂസ(റ)യുടെ മരണരോഗത്തിൽ ഞാൻ അദ്ദേഹത്തിന്റെ അടുക്കൽ പ്രവേശിച്ചു, അപ്പോൾ അദ്ദേഹത്തിന്റെ ഭാര്യ കരയാൻ അല്ലെങ്കിൽ ദുഃഖിക്കാൻ തുടങ്ങി. അപ്പോൾ അബൂമൂസ(റ) പറഞ്ഞു: പ്രവാചകൻ(സ) പറഞ്ഞത് നീ കേട്ടിട്ടില്ലേ? അവർ പറഞ്ഞു: അതെ. റിപ്പോർട്ടർ പറയുന്നു: അങ്ങനെ അവർ മൗനിയായി. അങ്ങനെ അബൂമൂസ(റ)യുടെ മരണശേഷം യസീദ് പറയുന്നു. ഞാൻ ആ സ്ത്രീയെ കണ്ടു ചോദിച്ചു: നിന്നോട് അബൂമൂസ(റ) എന്താണ് പറഞ്ഞത്, നീ പ്രവാചകൻ(സ) പറഞ്ഞത് കേട്ടിട്ടില്ലേ, എന്ന് അദ്ദേഹം പറഞ്ഞപ്പോൾ നീ മൗനിയായല്ലോ? അവർ പറഞ്ഞു: പ്രവാചകൻ(സ) പറഞ്ഞതിതാണ്: "(മരണ ദുഃഖത്താൽ) തല മുണ്ഡനം ചെയ്തവനും വാവിട്ട് കരയുന്നവനും വസ്ത്രം പിച്ചിചീന്തുന്നവനും നമ്മിൽ പെട്ടവനല്ല." (മു,ദ,ന,ജ)', 'يَزِيدَ بْنِ أَوْسٍ قَالَ', 'യസിദുബ്നു ഔസ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 803, 804, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ أُسَيدِ بْنِ أَبِي أُسَيدِ، عَنِ امْرَأَةٍ مِنَ الْمُبَايِعَاتِ رَضِيَ اللهُ عَنْهُنَّ قَالَتْ: كَانَ فِيمَا أَخَذَ عَلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فِي الْمَعْرُوفِ الَّذِي أَخَذَ عَلَيْنَا أَنْ لَا نَعْصِيَةُ فِيهِ: أَنْ لَا نَخْمُشَ وَجْهًا، وَلَا نَدْعُوَ وَيْلًا، وَلَا نَشُقَّ جَيْبًا، وَأَنْ لَا نَنْشُرَ شَعَرًا. (د)', 'അസീദുബ്നു അബൂഅസീദ് പ്രവാചകനുമായി ഉടമ്പടി ചെയ്ത ഒരു സ്ത്രീയിൽ നിന്ന്: നബി(സ) ഞങ്ങളോട് കരാർ ചെയ്ത കൂട്ടത്തിൽ ഞങ്ങളോട് - അവിടുത്തെ കൽപ്പനക്കെതിരായി പ്രവർത്തിക്കാവതല്ലാത്ത - സുകൃതത്തിന്റെ കൂട്ടത്തിൽ ഇതും കൂടി ഉടമ്പടി സ്വീകരിച്ചിരുന്നു: മുഖം മാന്തി പിളർത്തരുത്, കഷ്ടമേ! എന്ന് വിളിച്ച് കൂവരുത്, മാറിടം (കുപ്പായം) കീറരുത്, മുടി ചിതറിയിടരുത്. (ദ)', 'أُسَيدِ بْنِ أَبِي أُسَيدِ، عَنِ امْرَأَةٍ مِنَ الْمُبَايِعَاتِ', null, null, null, array['د']::text[], array['ദ']::text[], null, null, 804, 804, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا تُوُفِّيَ ابْنُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ- إِبْرَاهِيمُ- بَكَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُ الْمُعَزِّي – إِمَّا أَبُو بَكْرٍ وَإِمَّا عُمَرُ –: أَنْتَ أَحَقُّ مَنْ عَظَّمَ اللهُ حَقَّهُ. قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَدْمَعُ الْعَيْنُ، وَيَحْزَنُ الْقَلْبُ، وَلَا نَقُولُ مَا يُسْخِطُ الرَّبَّ. لَوْلَا أَنَّهُ وَعْدٌ صَادِقٌ وَمَوْعُودٌ جَامِعٌ، وَأَنَّ الْآخِرَ تَابِعٌ لِلْأَوَّلِ، لَوَجَدْنَا عَلَيْكَ يَا إِبْرَاهِيمُ أَفْضَلَ مِمَّا وَجَدْنَا، وَإِنَّا بِكَ لَمَحْزُونُونَ". (جه)', 'അസ്മാഅ്ബിൻത് യസീദ്(റ): പ്രവാചകന്റെ(സ) മകൻ ഇബ്രാഹിം മരിച്ചപ്പോൾ പ്രവാചകൻ(സ) കരഞ്ഞു. അപ്പോൾ സമാശ്വാസകൻ, - അബൂബക്റോ(റ) ഉമറോ(റ) - പ്രവാചകർ(സ)യോട് പറഞ്ഞു. അല്ലാഹു മഹത്വം നൽകിയവരിൽ ഏറ്റവും മഹാനാണ് അങ്ങ്. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "കണ്ണ് ഈറനണിയുന്നു. ഹൃദയം ദുഖിക്കുന്നു. അല്ലാഹുവിനെ കോപിപ്പിക്കുന്നത് നാം പറയില്ല. ഇതൊരു സത്യസന്ധമായ വാഗ്ദാനവും സമഗ്രമായ വാഗ്ദത്വവും ആദ്യത്തേതിന്റെ അനുബന്ധമായ അവസാനത്തേതും ആയില്ലായിരുന്നുവെങ്കിൽ, ഇബ്റാഹീമേ, ഞങ്ങൾ ഇപ്പോഴുള്ളതിനേക്കാൾ കൂടുതലായി നിന്റെ മേൽ ദുഃഖിക്കുമായിരുന്നു. ഞങ്ങൾ നിന്റെ കാര്യത്തിൽ ദുഃഖിതരാണ്." (ജ)', 'أَسْمَاءَ بِنْتِ يَزِيدَ', 'അസ്മാഅ്ബിൻത് യസീദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 804, 804, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ حَمْنَةَ بِنْتِ جَحْشٍ رَضِيَ اللهُ عَنْهَا أَنَّهُ قِيلَ لَهَا: قُتِلَ أَخُوكِ. فَقَالَتْ: رَحِمَهُ اللهُ، وَإِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ. قَالُوا: قُتِلَ زَوْجُكِ. قَالَتْ: وَا حُزْنَاهُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ لِلزَّوْجِ مِنَ الْمَرْأَةِ لَشُعْبَةً مَا هِيَ لِشَيْءٍ". [ز: في إسناده ضعيف] (جه)', 'ഹംന ബിൻത് ജഹ്ശ്(റ): നിന്റെ സഹോദരൻ വധിക്കപ്പെട്ടു എന്ന് മഹതിയോട് പറയപ്പെട്ടപ്പോൾ ''അല്ലാഹു അവന്ന് കരുണ ചെയ്യട്ടെ, നാം അല്ലാഹുവിന്നുള്ളവരും അവങ്കലേക്ക് മടങ്ങുന്നവരുമാണ്'', എന്ന് മഹതി പറഞ്ഞു. തുടർന്ന് നിന്റെ ഭർത്താവും വധിക്കപ്പെട്ടു എന്ന് ആളുകൾ പറഞ്ഞപ്പോൾ എന്റെ കഷ്ടമേ, എന്ന് മഹതി പറഞ്ഞു. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു. "ഭർത്താവിന് ഭാര്യയിൽനിന്ന് ഒരു വിഹിതമുണ്ട്, അതിലെന്താണ്?" (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'حَمْنَةَ بِنْتِ جَحْشٍ', 'ഹംന ബിൻത് ജഹ്ശ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 804, 804, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِنِسَاءِ عَبْدِ الْأَشْهَلِ يَبْكِينَ هَلْكَاهُنَّ يَوْمَ أُحُدٍ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَكِنَّ حَمْزَةَ لَا بَوَاكِيَ لَهُ". فَجَاءَ نِسَاءُ الْأَنْصَارِ يَبْكِينَ حَمْزَةَ، فَاسْتَيْقَظَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "وَيْحَهُنَّ إِمَا انْقَلَبْنَ بَعْدُ؟ مُرُوهُنَّ فَلْيَنْقَلِبْنَ، وَلَا يَبْكِينَ عَلَى هَالِكٍ بَعْدَ الْيَوْمِ". (جه)', 'ഇബ്നുഉമർ(റ): അബ്ദുൽ അശ്ഹൽ ഗോത്രത്തിലെ വധിക്കപ്പെട്ടവരുടെ പേരിൽ കരയുന്ന സ്ത്രീകളുടെ അരികെ തിരുമേനി(സ) ഉഹ്ദ് ദിവസം നടക്കുമ്പോൾ ഇങ്ങനെ പറഞ്ഞു: "പക്ഷേ ഹംസക്ക് വേണ്ടി കരയാൻ സ്ത്രീകളില്ല." അപ്പോൾ അൻസാരി സ്ത്രീകൾ ഹംസ(റ)ക്ക് വേണ്ടി കരയാൻ വന്നു. അത് ശ്രദ്ധയിൽപ്പെട്ടപ്പോൾ നബി(സ) പറഞ്ഞു: "അവർക്ക് കഷ്ടം! ഇത്രവേഗം അവർ മാറിപ്പോയോ? അവരോട് കൽപ്പിക്കുക, അവർ മടങ്ങിപ്പോകട്ടെ! ഇനിമുതൽ ആര് മരിച്ചാലും (ആ മയ്യിത്തിന്റെ അടുക്കൽ) അവർ കരയരുത്." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 805, 805, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: اشْتَكَى سَعْدُ بْنُ عُبَادَةَ شَكْوَى لَهُ فَأَتَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُهُ مَعَ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ وَسَعْدِ بْنِ أَبِي وَقَّاصٍ وَعَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمْ، فَلَمَّا دَخَلَ عَلَيْهِ وَجَدَهُ فِي غَشِيَّةٍ فَقَالَ: "أَقَدْ قَضَى". قَالُوا: لَا يَا رَسُولَ اللهِ، فَبَكَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا رَأَى الْقَوْمُ بُكَاءَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَكَوْا، فَقَالَ: "أَلَا تَسْمَعُونَ؟ إِنَّ اللهَ لَا يُعَذِّبُ بِدَمْعِ الْعَيْنِ، وَلَا بِحُزْنِ الْقَلْبِ، وَلَكِنْ يُعَذِّبُ بِهَذَا – وَأَشَارَ إِلَى لِسَانِهِ – أَوْ يَرْحَمُ". (م)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): സഅ്ദുബ്നു ഉബാദത്(റ) മരണ രോഗം ബാധിച്ചപ്പോൾ അബ്ദുറഹിമാൻ ഇബ്നുഔഫ്(റ), സഅ്ദു ഇബ്നുഅബീവഖാസ്(റ), അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ) എന്നിവരുടെ കൂടെ പ്രവാചകൻ(സ) അദ്ദേഹത്തെ സന്ദർശിക്കാൻ പോയി. പ്രവാചകൻ(സ) അദ്ദേഹത്തിന്റെ അടുക്കൽ പ്രവേശിച്ചപ്പോൾ അദ്ദേഹം അബോധാവസ്ഥയിലായിരുന്നു. "അദ്ദേഹം മരിച്ചോ" എന്ന് പ്രവാചകൻ(സ) ചോദിച്ചപ്പോൾ അവർ പറഞ്ഞു: ഇല്ല പ്രവാചകരേ, അപ്പോൾ തിരുമേനി(സ) കരഞ്ഞു. പ്രവാചകൻ(സ) കരയുന്നത് കണ്ടപ്പോൾ ജനങ്ങളും കരഞ്ഞു. തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ കേൾക്കുന്നുണ്ടോ, കണ്ണുനീർ കൊണ്ടോ മനസ്സിന്റെ ദുഃഖം കൊണ്ടോ അല്ലാഹു ശിക്ഷിക്കുകയില്ല. - തന്റെ നാക്കിലേക്ക് ചൂണ്ടിക്കൊണ്ട് - ഇതുകൊണ്ടാണ് അല്ലാഹു ശിക്ഷിക്കുന്നതും അല്ലെങ്കിൽ കരുണ കാണിക്കുന്നതും." (മു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 805, 805, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ مَيِّتٍ يَمُوتُ، فَيَقُومُ بَاكِيهِ فَيَقُولُ: وَا جَبَلَاهْ! وَا سَيِّدَاهْ! أَوْ نَحْوَ ذَلِكَ، إِلَّا وُكِّلَ بِهِ مَلَكَانِ يَلْهَزَانِهِ: أَهَكَذَا كُنْتَ". حَسَنٌ غَرِيبٌ. (ت,جه)', 'അബൂമൂസൽ അശ്അരി(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഒരാൾ മരണപ്പെടുകയും തനിക്ക് വേണ്ടി കരയുന്നവർ എഴുന്നേറ്റ് നിന്ന് കൊണ്ട് എന്റെ പർവ്വതമേ, നേതാവേ എന്നിങ്ങനെ വിളിച്ചുപറയുകയും ചെയ്യുകയാണെങ്കിൽ രണ്ട് ഏൽപിക്കപ്പെട്ട മാലാഖമാർ അവനെ പരിഹസിച്ചുകൊണ്ട് നീ ഇങ്ങനെയായിരുന്നോ എന്ന് പറയുന്നതാണ്." (ഹദീസ് ഹസനും ഗരീബുമാണെന്ന് തുർമുദി പറയുന്നു) (തു,ജ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 805, 805, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي عَامَ حَجَّةِ الْوَدَاعِ مِنْ وَجَعٍ اشْتَدَّ بِي، فَقُلْتُ: إِنِّي قَدْ بَلَغَ بِي مِنَ الْوَجَعِ مَا تَرَي وَأَنَا ذُو مَالٍ وَلَا يَرِثُنِي إِلَّا ابْنَةٌ أَفَأَتَصَدَّقُ بِثُلُثَيْ مَالِي؟ قَالَ: "لَا". فَقُلْتُ: بِالشَّطْرِ؟ فَقَالَ: "لَا". ثُمَّ قَالَ: "الثُّلُثُ وَالثُّلُثُ كَبِيرٌ أَوْ كَثِيرٌ، إِنَّكَ أَنْ تَذَرَ وَرَثَتَكَ أَغْنِيَاءَ خَيْرٌ مِنْ أَنْ تَذَرَهُمْ عَالَةً يَتَكَفَّفُونَ النَّاسَ، وَإِنَّكَ لَنْ تُنْفِقَ نَفَقَةً تَبْتَغِي بِهَا وَجْهَ اللهِ إِلَّا أُجِرْتَ بِهَا، حَتَّى مَا تَجْعَلُ فِي فِي امْرَأَتِكَ". فَقُلْتُ: يَا رَسُولَ اللهِ أُخَلَّفُ بَعْدَ أَصْحَابِي؟ فَقَالَ: "إِنَّكَ لَنْ تُخَلَّفَ فَتَعْمَلَ عَمَلًا صَالِحًا إِلَّا ازْدَدْتَ بِهِ دَرَجَةً وَرِفْعَةً ثُمَّ لَعَلَّكَ أَنْ تُخَلَّفَ حَتَّى يَنْتَفِعَ بِكَ أَقْوَامٌ وَيُضَرَّ بِكَ آخَرُونَ، اللَّهُمَّ أَمْضِ لِأَصْحَابِي هِجْرَتَهُمْ وَلَا تَرُدَّهُمْ عَلَى أَعْقَابِهِمْ لَكِنِ الْبَائِسُ سَعْدُ بْنُ خَوْلَةَ". يَرْثِي لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ مَاتَ بِمَكَّةَ. (خ)', 'സഅ്ദുബ്നുഅബീവഖാസ്(റ): ഹജ്ജത്തുൽ വദാഇന്റെ വർഷം എനിക്ക് രോഗം അധികരിച്ചപ്പോൾ നബി(സ) എന്നെ സന്ദർശിച്ചു. ഞാൻ പറഞ്ഞു: എന്റെ രോഗം അങ്ങു കാണുന്നത്രയായിരിക്കുന്നു. ഞാനാകട്ടെ സമ്പന്നനുമാണ്. എനിക്കൊരു മകളല്ലാതെ അനന്തരാവകാശികളായി ആരുമില്ല. എന്റെ സ്വത്തിന്റെ മൂന്നിൽ രണ്ട് ഞാൻ ദാനം ചെയ്യട്ടയോ? നബി(സ) പറഞ്ഞു: "പാടില്ല." ഞാൻ ചോദിച്ചു: പകുതി കൊടുക്കട്ടെയോ? നബി(സ) പറഞ്ഞു: "പാടില്ല." പിന്നെ നബി(സ) പറഞ്ഞു: "മൂന്നിലൊന്ന് കൊടുക്കുക. മൂന്നിലൊന്ന് വലുതാണ്. നിന്റെ അനന്തരാവകാശികളെ ദരിദ്രരായി ജനങ്ങളുടെ മുന്നിൽ കൈനീട്ടാൻ വിടുന്നതിലും നല്ലത് അവരെ സമ്പന്നരായി വിടുന്നതാണ്. നീ അല്ലാഹുവിന്റെ പ്രീതി കാംക്ഷിച്ചു ചെയ്യുന്ന എല്ലാ ചിലവുകൾക്കും പ്രതിഫലം ലഭിക്കും. നീ നിന്റെ ഭാര്യയുടെ വായിൽ വെച്ച് കൊടുക്കുന്ന ഉരുളക്ക് പോലും." ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാൻ എന്റെ സ്നേഹിതരിൽ നിന്ന് പിൻതള്ളപ്പെടുമോ? നബി(സ) പറഞ്ഞു: "പദവിയും ഔന്നത്യവും വർദ്ധിച്ചിട്ടല്ലാതെ താങ്കൾ പിന്മാറ്റപ്പെടുകയോ സൽകർമ്മം നടത്തുകയോ ചെയ്യില്ല. പിന്നീട് താങ്കൾ ചിലപ്പോൾ പിന്മാറ്റപ്പെട്ടേക്കും. അപ്പോൾ ഒരു വിഭാഗം താങ്കളെ കൊണ്ട് ഉപകാരമെടുക്കുകയും ഒരു വിഭാഗം ഉപദ്രവമേൽക്കുകയും ചെയ്യും. അല്ലാഹുവേ എന്റെ സ്നേഹിതരുടെ ഹിജ്റ നീ സ്വീകരിക്കണം. അവരെ നീ പിൻതിരിപ്പിക്കരുത്. എന്നാൽ നിർഭാഗ്യവാൻ സഅ്ദുബ്നു ഖൗലയാണ്." മക്കയിൽ വെച്ച് അദ്ദേഹം മരണപ്പെട്ടപ്പോൾ നബി(സ) അദ്ദേഹത്തിന് അനുശോചനം നടത്തി. (ബു)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നുഅബീവഖാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 805, 806, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنِ ابْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمَرَاثِي. [ز: ضعيف] (جه)', 'ഇബ്നുഅബീഔഫ(റ): നബി(സ) മരിച്ചവരെ സംബന്ധിച്ച് വിലപിക്കൽ നിരോധിച്ചിരിക്കുന്നു. (ഹദീസ് ദുർബലമാണെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'ابْنِ أَبِي أَوْفَى', 'ഇബ്നുഅബീഔഫ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: ضعيف', 'ഹദീസ് ദുർബലമാണെന്ന് ഇബ്നുമാജ പറയുന്നു', 806, 806, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمَيِّتُ يُعَذَّبُ بِبُكَاءِ أَهْلِهِ عَلَيْهِ. فَقَالَتْ عَائِشَةُ: يَرْحَمُهُ اللهُ، لَمْ يَكْذِبْ، وَلَكِنَّهُ وَهِمَ، إِنَّمَا قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِرَجُلٍ مَاتَ يَهُودِيًّا: "إِنَّ الْمَيِّتَ لَيُعَذَّبُ، وَإِنَّ أَهْلَهُ لَيَبْكُونَ عَلَيْهِ". حَسَنٌ صَحِيحٌ. (ق,ت)', 'ഇബ്നുഉമർ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "തന്റെ മേൽ തന്റെ കുടുംബം കരയുന്നത് നിമിത്തം മയ്യിത്ത് ശിക്ഷിക്കപ്പെടും." ആയിശ(റ) പറഞ്ഞു: അല്ലാഹു അദ്ദേഹത്തെ അനുഗ്രഹിക്കട്ടെ, അദ്ദേഹം കളവ് പറഞ്ഞതല്ല, പക്ഷേ തെറ്റിദ്ധരിച്ചതാണ്. ജൂതനായി മരിച്ച ഒരു മനുഷ്യനെ പറ്റിയാണ് തിരുമേനി(സ) അത് പറഞ്ഞത്. "മയ്യിത്ത് ശിക്ഷിക്കപ്പെടുന്നു. അവന്റെ കുടുംബമാണെങ്കിൽ അവന് വേണ്ടി കരഞ്ഞ്കൊണ്ടിരിക്കുകയാണ്." (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തിർമിദി പറയുന്നു) (ബു,മു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 806, 806, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَخَذَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِيَدِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ فَانْطَلَقَ بِهِ إِلَى ابْنِهِ إِبْرَاهِيمَ، فَوَجَدَهُ يَجُودُ بِنَفْسِهِ، فَأَخَذَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَوَضَعَهُ فِي حِجْرِهِ فَبَكَى، فَقَالَ لَهُ عَبْدُ الرَّحْمَنِ: أَتَبْكِي، أَوَلَمْ تَكُنْ نَهَيْتَ عَنِ الْبُكَاءِ؟ قَالَ: "لَا، وَلَكِنْ نَهَيْتُ عَنْ صَوْتَيْنِ أَحْمَقَيْنِ فَاجِرَيْنِ: صَوْتٍ عِنْدَ مُصِيبَةٍ، خَمْشِ وُجُوهٍ وَشَقِّ جُيُوبٍ وَرَنَّةِ شَيْطَانٍ". حَسَنٌ. (ت)', 'ജാബിർ ഇബ്നുഅബ്ദുല്ല(റ): തിരുമേനി(സ) ഇബ്രാഹിമിന്റെ അടുക്കൽ ചെന്നപ്പോൾ മകൻ അന്ത്യശ്വാസം വലിച്ചുകൊണ്ടിരിക്കയാണ്. പ്രവാചകൻ(സ) കുട്ടിയെ വാങ്ങി തന്റെ മടിയിൽ വെച്ച് കരയാൻ തുടങ്ങി. അപ്പോൾ നബി(സ)യോട് അബ്ദുറഹിമാൻ ചോദിച്ചു: താങ്കളും കരയുകയാണോ? കരയുന്നത് താങ്കൾ നിരോധിച്ചിരുന്നില്ലേ? തിരുമേനി(സ) പറഞ്ഞു: "ഇല്ല ഞാൻ നിരോധിച്ചത് കുറ്റകരമായതും വിഢ്ഢിത്ത പരവുമായ രണ്ടു ശബ്ദത്തെ സംബന്ധിച്ചാണ്. വിപത്തിന്റെ അവസരത്തിലെ ശബ്ദവും, മുഖം മാന്തുന്നതും, കുപ്പായം പിച്ചിച്ചീന്തുന്നതും പിശാചിന്റെ മൂളലും." ഹദീസ് ഹസനാണെന്ന് തുർമുദി. (തു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിർ ഇബ്നുഅബ്ദുല്ല(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 806, 807, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: مَاتَ مَيِّتٌ مِنْ آلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَاجْتَمَعَ النِّسَاءُ يَبْكِينَ عَلَيْهِ، فَقَامَ عُمَرُ رَضِيَ اللهُ عَنْهُ يَنْهَاهُنَّ وَيَطْرُدُهُنَّ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "دَعْهُنَّ يَا عُمَرُ، فَإِنَّ الْعَيْنَ دَامِعَةٌ، وَالْقَلْبَ مُصَابٌ، وَالْعَهْدَ قَرِيبٌ". (ن,جه)', 'അബൂഹുറൈറ(റ): പ്രവാചക കുടുംബത്തിൽ നിന്ന് ഒരാൾ മരണപ്പെട്ടപ്പോൾ അതിന്റെ മേൽ കരയാൻ വേണ്ടി സ്ത്രീകൾ സമ്മേളിച്ചു. അപ്പോൾ ഉമർ(റ) എഴുന്നേറ്റ് അവരെ തടയുകയും ആട്ടുകയും ചെയ്തു. അന്നേരം പ്രവാചകൻ(സ) പറഞ്ഞു: "ഉമർ! അവരെ വിട്ടേക്കുക!. കണ്ണ് ഈറനണിയും, മനസ്സ് ദുഃഖിക്കും, കാലം സമീപമാണ്." (ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 807, 807, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ قَبِيصَةَ بْنِ ذُؤَيْبٍ رَضِيَ اللهُ عَنْهُ، عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: دَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى أَبِي سَلَمَةَ وَقَدْ شَقَّ بَصَرُهُ، فَأَغْمَضَهُ، ثُمَّ قَالَ: "إِنَّ الرُّوحَ إِذَا قُبِضَ تَبِعَهُ الْبَصَرُ". (م,د,جه)', 'ഖബീസതുബ്നു ദുഐബ്(റ) ഉമ്മുസലമ(റ)യിൽ നിന്ന്: മഹതി പറഞ്ഞു: പ്രവാചകൻ(സ) അബുസലമ(റ)യുടെ അടുക്കൽ ചെന്നപ്പോൾ അദ്ദേഹത്തിന്റെ കണ്ണുകൾ തുറന്ന് നിൽക്കയായിരുന്നു. പ്രവാചകൻ(സ) അത് അടച്ചു കൊടുത്തു. പിന്നീട് ഇങ്ങനെ പറഞ്ഞു: "പ്രാണൻ പിടിക്കപ്പെടുമ്പോൾ കണ്ണ് അതിനെ പിന്തുടരുന്നതാണ്." (മു,ദ,ജ)', 'قَبِيصَةَ بْنِ ذُؤَيْبٍ', 'ഖബീസതുബ്നു ദുഐബ്(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 807, 807, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا حَضَرْتُمْ مَوْتَاكُمْ فَأَغْمِضُوا الْبَصَرَ، فَإِنَّ الْبَصَرَ يَتْبَعُ الرُّوحَ، وَقُولُوا خَيْرًا، فَإِنَّ الْمَلَئِكَةَ يُؤَمِّنُ عَلَى مَا قَالَ أَهْلُ الْبَيْتِ". (جه)', 'ശദ്ദാദുബ്നു ഔസ്(റ): പ്രവാചൻ(സ) പറഞ്ഞു: "നിങ്ങളിൽ മരിച്ചവരുടെ അടുക്കൽ നിങ്ങൾ സന്നിഹിതരായാൽ നിങ്ങൾ കണ്ണ് അടച്ച് കൊടുക്കുക, കാരണം കണ്ണ് ആത്മാവിനെ പിന്തുടരുന്നു. നിങ്ങൾ നല്ലത് പറയുക കാരണം കുടുംബങ്ങൾ പറയുന്നതിന് മലക്കുകൾ ആമീൻ പറയും." (ജ)', 'شَدَّادِ بْنِ أَوْسٍ', 'ശദ്ദാദുബ്നു ഔസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 807, 807, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: دَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى أَبِي سَلَمَةَ وَقَدْ شَقَّ بَصَرُهُ فَأَغْمَضَهُ، فَصَيَّحَ نَاسٌ مِنْ أَهْلِهِ، فَقَالَ: "لَا تَدْعُوا عَلَى أَنْفُسِكُمْ إِلَّا بِخَيْرٍ، فَإِنَّ الْمَلَائِكَةَ يُؤَمِّنُونَ عَلَى مَا تَقُولُونَ". ثُمَّ قَالَ: "اللَّهُمَّ اغْفِرْ لِأَبِي سَلَمَةَ، وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ، وَاخْلُفْهُ فِي عَقِبِهِ فِي الْغَابِرِينَ، وَاغْفِرْ لَنَا وَلَهُ رَبَّ الْعَالَمِينَ، اللَّهُمَّ افْسَحْ لَهُ فِي قَبْرِهِ، وَنَوِّرْ لَهُ فِيهِ". (م,د,جه)', 'ഉമ്മുസലമ(റ): പ്രവാചകൻ(സ) അബുസലമ(റ)യുടെ അടുക്കൽ ചെന്നപ്പോൾ അദ്ദേഹത്തിന്റെ കണ്ണ് തുറന്ന് കിടക്കുകയായിരുന്നു. തിരുമേനി(സ) അദ്ദേഹത്തിന്റെ കണ്ണ് അടച്ചപ്പോൾ അദ്ദേഹത്തിന്റെ കുടുംബത്തിലെ ആളുകൾ ഒച്ചവെച്ചു. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങൾ നിങ്ങൾക്ക് വേണ്ടി നന്മ കൊണ്ടല്ലാതെ പ്രാർത്ഥിക്കരുത്. കാരണം നിങ്ങൾ പറയുന്നതിന് മലക്കുകൾ ആമീൻ പറഞ്ഞ് കൊണ്ടിരിക്കുന്നു." പിന്നീട് പ്രവാചകൻ(സ) പറഞ്ഞു: "അല്ലാഹുവേ അബൂസലമക്ക് മാപ്പ് നൽകേണമേ, സന്മാർഗികളുടെ കൂട്ടത്തിൽ അദ്ദേഹത്തിന്റെ സ്ഥാനം ഉയർത്തേണമേ, അദ്ദേഹത്തിന്റെ ശേഷം പിൻഗാമികളുടെ കൂട്ടത്തിൽ അദ്ദേഹത്തിന് പ്രതിനിധിയെ നൽകേണമേ, ലോക രക്ഷിതാവേ, ഞങ്ങൾക്കും അദ്ദേഹത്തിനും മാപ്പ് അരുളേണമേ, അദ്ദേഹത്തിന് തന്റെ ഖബറിൽ വിശാലത നൽകേണമേ, അദ്ദേഹത്തിന് ഖബറിൽ പ്രകാശം നൽകേണമേ." (മു,ദ,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 807, 808, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ مِنَّا مَنْ ضَرَبَ الْخُدُودَ، أَوْ شَقَّ الْجُيُوبَ، أَوْ دَعَا بِدَعْوَى الْجَاهِلِيَّةِ". وَفِي لَفْظٍ: "وَشَقَّ... وَدَعَا بِغَيْرِ أَلِفٍ". (م,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "(മയ്യിത്തിന്റെ പേരിൽ) കവിളിൽ അടിച്ചു കരയുന്നവരും മാറ് കീറുന്നവരും ജീഹിലിയ്യാ (കാലത്തുണ്ടായിരുന്നതു പോലുള്ള) നിലവിളി നടത്തുന്നവരും നമ്മിൽ പെട്ടവരല്ല." മറ്റൊരു റിപ്പോർട്ടിൽ: "മാറ് കീറുന്നവരും....... സത്യവിശ്വാസിക്ക് അനുയോജ്യമല്ലാത്ത വിധം നിലവിളി നടത്തുന്നവരും." (മു,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 808, 808, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=164), 1, null, 'മറ്റൊരു നിവേദനിൽ: "മാറ് കീറുന്നവരും....... സത്യവിശ്വാസിക്ക് അനുയോജ്യമല്ലാത്ത വിധം നിലവിളി നടത്തുന്നവരും." (മു,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَعَنَ الْخَامِشَةَ وَجْهَهَا، وَالشَّاقَّةَ جَيْبَهَا، وَالدَّاعِيَةَ بِالْوَيْلِ وَالثُّبُورِ. (جه)', 'അബു ഉമാമ(റ): മുഖം മാന്തി പിളർക്കുന്നവളെയും, കുപ്പായമാറ് വലിച്ച് കീറുന്നവളെയും, നാശമേ!, കഷ്ടമേ! എന്നൊക്കെ വിളിച്ചു കൂവുന്നവളെയും പ്രവാചകൻ(സ) ശപിച്ചിരിക്കുന്നു. (ജ)', 'أَبِي أُمَامَةَ', 'അബു ഉമാമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 808, 808, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ مِنَّا مَنْ لَطَمَ الْخُدُودَ، وَشَقَّ الْجُيُوبَ، وَدَعَا بِدَعْوَى الْجَاهِلِيَّةِ". (خ)', 'അബ്ദുല്ല(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "മുഖത്തടിക്കുന്നവരും കുപ്പായം പിച്ചിചീന്തുന്നവരും ജാഹിലിയ്യാ നിലവിളി നടത്തുന്നവരും നമ്മിൽ പെട്ടവരല്ല." (ബു)', 'عَبْدِ اللهِ', 'അബ്ദുല്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 808, 808, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ وَجِعَ وَجَعًا، فَغُشِيَ عَلَيْهِ وَرَأْسُهُ فِي حِجْرِ امْرَأَةٍ مِنْ أَهْلِهِ، فَبَكَتْ فَلَمْ يَسْتَطِعْ أَنْ يَرُدَّ عَلَيْهَا شَيْئًا، فَلَمَّا أَفَاقَ قَالَ: أَنَا بَرِيءٌ مِمَّنْ بَرِئَ مِنْهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَرِئَ مِنَ الصَّالِقَةِ وَالْحَالِقَةِ وَالشَّاقَّةِ. (خ)', 'അബൂമൂസ(റ): ഇദ്ദേഹത്തിന് കലശലായ വേദനയുണ്ടായി. തുടർന്ന് അബോധാവസ്ഥയിലായി. തന്റെ കുടുംബത്തിൽപെട്ട ഒരു സ്ത്രീയുടെ മടിത്തട്ടിലായിരുന്നു അദ്ദേഹത്തിന്റെ ശിരസ്സ്. ആ സ്ത്രീയപ്പോൾ കരഞ്ഞു. അദ്ദേഹത്തിനാണെങ്കിൽ അവളോട് ഒന്നും പ്രതികരിക്കാൻ സാധിച്ചില്ല. ബോധം തെളിഞ്ഞപ്പോൾ അദ്ദേഹം ഇങ്ങനെ പറഞ്ഞു: പ്രവാചകൻ(സ) ബന്ധം വിച്ഛേദിച്ചവരിൽ നിന്ന് ഞാനും ബന്ധം വിച്ഛേദിച്ചിരിക്കുന്നു. ആപൽഘട്ടത്തിൽ അലമുറകൂട്ടുന്നവൾ, തല മുണ്ഡനം ചെയ്യുന്നവൾ, വസ്ത്രം പിച്ചി ചീന്തുന്നവൾ എന്നിവരിൽ നിന്ന് പ്രവാചകൻ(സ) ബന്ധം വിച്ഛേദിച്ചിട്ടുണ്ട്. (ബു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 808, 808, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ أُمِّ حَبِيبَةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَرَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ تُحِدُّ عَلَى مَيِّتٍ فَوْقَ ثَلَاثٍ إِلَّا عَلَى زَوْجٍ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا". (خ)', 'നബി(സ)യുടെ പത്നി ഉമ്മുഹബീബ(റ): നബി(സ) ഇങ്ങനെ പറയുന്നതായി ഞാൻ കേട്ടിരിക്കുന്നു: "അല്ലാഹുവിലും അന്ത്യനാളിലും വിശ്വസിക്കുന്ന ഒരു സ്ത്രീക്ക് ഭർത്താവിന്റെ മരണത്തിൽ നാല് മാസവും പത്ത് ദിവസവും ദു:ഖിക്കുക എന്നതൊഴികെ, ഒരാളുടെ മരണത്തിലും മൂന്ന് ദിവസത്തിലധികം ദു:ഖാചരണം നടത്താൻ പാടില്ല." (ബു)', 'أُمِّ حَبِيبَةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَ', 'നബി(സ)യുടെ പത്നി ഉമ്മുഹബീബ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 809, 809, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ عَوْفِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى جَنَازَةٍ، فَحَفِظْتُ مِنْ دُعَائِهِ وَهُوَ يَقُولُ: "اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ، وَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ النَّارِ". حَتَّى تَمَنَّيْتُ أَنْ أَكُونَ ذَلِكَ الْمَيِّتَ. (م)', 'ഔഫുബ്നുമാലിക്(റ): നബി(സ) ഒരു ജനാസക്ക് വേണ്ടി നിസ്കരിച്ചു. ഞാൻ അവിടുത്തെ പ്രാർത്ഥന പഠിച്ചു. അവിടുന്ന് പ്രാർത്ഥിച്ചു: "അല്ലാഹുവേ, അദ്ദേഹത്തിന് നീ പൊറുത്തു കൊടുക്കുകയും കരുണ ചെയ്യുകയും സൗഖ്യം നൽകുകയും മാപ്പുകൊടുക്കുകയും ചെയ്യേണമേ. ഇദ്ദേഹത്തിന്റെ ആതിഥ്യം ആദരപൂർവ്വമാക്കേണമേ. പ്രവേശന സ്ഥലം വിശാലമാക്കേണമേ, വെള്ളം, ഹിമം, മഞ്ഞ് എന്നിവ കൊണ്ട് കഴുകേണമേ. നീ വെള്ള വസ്ത്രം അഴുക്കിൽ നിന്നും ശുചീകരിക്കുന്നതു പോലെ ഇദ്ദേഹത്തെ പാപങ്ങളിൽ നിന്ന് ശുചിയാക്കേണമേ. ഇദ്ദേഹത്തിന്റെ ഭവനത്തേക്കാൾ ഉത്തമ ഭവനവും കുടുംബത്തേക്കാൾ ഉത്തമകുടുംബവും ഇണയേക്കാൾ ഉത്തമ ഇണയേയും ഇദ്ദേഹത്തിന് നൽകേണമേ. അദ്ദേഹത്തെ നീ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുകയും, ഖബറിലെ ശിക്ഷയിൽ നിന്നും നരകത്തിലെ ശിക്ഷയിൽ നിന്നും അദ്ദേഹത്തിന് കാവൽ നൽകുകയും ചെയ്യേണമേ!" അങ്ങനെ ആ മയ്യിത്ത് ഞാനായിരുന്നെങ്കിലെന്ന് ഞാൻ ആഗ്രഹിച്ചു. (മു)', 'عَوْفِ بْنِ مَالِكٍ', 'ഔഫുബ്നുമാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 809, 809, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ عَبْدِ اللهِ بْنِ رُبَيِّعَةَ السُّلَمِيِّ رَضِيَ اللهُ عَنْهُ، وَكَانَ مِنْ أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، عَنْ عُبَيْدِ بْنِ خَالِدٍ السُّلَمِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ آخَى بَيْنَ رَجُلَيْنِ، فَقُتِلَ أَحَدُهُمَا وَمَاتَ الْآخَرُ بَعْدَهُ، فَصَلَّيْنَا عَلَيْهِ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا قُلْتُمْ". قَالُوا: دَعَوْنَا لَهُ: اللَّهُمَّ اغْفِرْ لَهُ، اللَّهُمَّ ارْحَمْهُ، اللَّهُمَّ أَلْحِقْهُ بِصَاحِبِهِ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَأَيْنَ صَلَاتُهُ بَعْدَ صَلَاتِهِ؟ وَأَيْنَ عَمَلُهُ بَعْدَ عَمَلِهِ؟ فَلَمَا بَيْنَهُمَا كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു റുബയ്യിഅതുസ്സുലമി(റ), (അദ്ദേഹം പ്രവാചകന്റെ അനുചരനായിരുന്നു) ഉബൈദുബ്നു ഖാലിദിസ്സുലമിയ്യി(റ)വിൽ നിന്ന്: റസൂൽ(സ) രണ്ട് പേരെ സഹോദന്മാരാക്കി. അവരിൽ ഒരാൾ കൊല്ലപ്പെട്ടു. ശേഷം മറ്റെയാൾ മരിച്ചു. അപ്പോൾ ഞങ്ങൾ അദ്ദേഹത്തിനായി നിസ്കരിച്ചു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "നിങ്ങൾ എന്താണ് പ്രാർത്ഥിച്ചത്?" അവർ പറഞ്ഞു: ഞങ്ങൾ അദ്ദേഹത്തിന് വേണ്ടി ഇപ്രകാരം പ്രാർത്ഥിച്ചു: ''അല്ലാഹുവേ അദ്ദേഹത്തിന് നീ പൊറുത്തു കൊടുക്കേണമേ. അല്ലാഹുവേ അദ്ദേഹത്തിന് നീ കരുണ ചെയ്യേണമേ, അല്ലാഹുവേ അദ്ദേഹത്തിന്റെ കൂട്ടുകാരനോടൊപ്പം നീ അദ്ദേഹത്തെ ചേർക്കണമേ.'' അപ്പോൾ നബി(സ) പറഞ്ഞു: "അയാളുടെ നിസ്കാരവും ഇയാളുടെ നിസ്കാരവും എവിടെ കിടക്കുന്നു! (പ്രതിഫലം ലഭിക്കുന്ന കാര്യത്തിൽ എത്രയോ അന്തരമുള്ളതായിരിക്കും!!) അയാളുടെ കർമ്മവും ഇയാളുടെ കർമ്മവും എവിടെ കിടക്കുന്നു!! അവർക്കിടയിൽ (ഉള്ള അകലം) ആകാശ ഭൂമികൾക്കിടയിലുള്ളതാണ്." (ന)', 'عَبْدِ اللهِ بْنِ رُبَيِّعَةَ السُّلَمِيِّ', 'അബ്ദുല്ലാഹിബ്നു റുബയ്യിഅതുസ്സുലമി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 809, 810, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا صَلَّيْتُمْ عَلَى الْمَيِّتِ فَأَخْلِصُوا لَهُ الدُّعَاءَ". (د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "നിങ്ങൾ മയ്യിത്ത് നിസ്കരിക്കുകയാണെങ്കിൽ അവന് വേണ്ടി ആത്മാർത്ഥമായി പ്രാർത്ഥിക്കുക." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 810, 810, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى عَلَى جَنَازَةٍ يَقُولُ: "اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَشَاهِدِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبِيرِنَا، وَذَكَرِنَا وَأُنْثَانَا. اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلَامِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِيمَانِ. اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُ وَلَا تُضِلَّنَا بَعْدَهُ". (د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) ജനാസ നിസ്കരിക്കുകയായിരുന്നു. അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹുവേ ഞങ്ങളിൽ ജീവിച്ചിരിക്കുന്നവർക്കും മരിച്ചവർക്കും, ഇവിടെ ഹാജറുള്ളവർക്കും ഇല്ലാത്തവർക്കും, ചെറിയവർക്കും വലിയവർക്കും, പുരുഷനും സ്ത്രീക്കും നീ മാപ്പു നൽകേണമേ, അല്ലാഹുവേ ഞങ്ങളിൽ നിന്ന് നീ ആരെ ജീവിപ്പിക്കുന്നുവോ അവരെ നീ ഇസ്ലാമിൽ ജീവിപ്പിക്കുകയും, ആരെ മരിപ്പിക്കുന്നുവോ അവനെ ഈമാനോടെ മരിപ്പിക്കുകയും ചെയ്യേണമേ. അല്ലാഹുവേ അദ്ദേഹത്തിന്റെ പേരിലുള്ള പ്രതിഫലം ഞങ്ങൾക്ക് നീ തടയരുതേ. അദ്ദേഹത്തിന് ശേഷം നീ ഞങ്ങളെ വഴി പിഴപ്പിക്കുകയും ചെയ്യരുതേ." (ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 810, 810, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ وَاثِلَةَ بْنِ الْأَسْقَعِ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى رَجُلٍ مِنَ الْمُسْلِمِينَ، فَأَسْمَعُهُ يَقُولُ: "اللَّهُمَّ، إِنَّ فُلَانَ بْنَ فُلَانٍ فِي ذِمَّتِكَ وَحَبْلِ جِوَارِكَ، فَقِهِ مِنْ فِتْنَةِ الْقَبْرِ وَعَذَابِ النَّارِ، وَأَنْتَ أَهْلُ الْوَفَاءِ وَالْحَقِّ، فَاغْفِرْ لَهُ وَارْحَمْهُ، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ". (د,جه)', 'വാഥിലതുബ്നു അസ്ഖഅ്(റ): മുസലിംകളിൽ പെട്ട ഒരാൾക്ക് നബി(സ) മയ്യിത്ത് നിസ്കരിച്ചു. അപ്പോൾ അവിടുന്ന് പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവേ ഇന്ന വ്യക്തി നിന്റെ സംരക്ഷണത്തിലും ഉത്തരവാദത്തിലുമാകുന്നു. അതിനാൽ അവന്റെ ഖബറിലെ ശിക്ഷയിൽനിന്നും നരകശിക്ഷയിൽ നിന്നും അവനെ നീ സംരക്ഷിക്കേണമേ. സത്യവും കരാറും പാലിക്കുന്നവനുമാണല്ലോ നീ. അല്ലാഹുവേ നീ അവന് കരുണചെയ്യുകയും പൊറുത്തുകൊടുക്കുകയും ചെയ്യേണമേ. നിശ്ചയം, നീയാണ് പൊറുക്കുന്നവനും കരുണചെയ്യുന്നവനും." (ദ,ജ)', 'وَاثِلَةَ بْنِ الْأَسْقَعِ', 'വാഥിലതുബ്നു അസ്ഖഅ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 810, 810, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ عَوْفِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: شَهِدْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى رَجُلٍ مِنَ الْأَنْصَارِ، فَسَمِعْتُهُ يَقُولُ: "اللَّهُمَّ صَلِّ عَلَيْهِ وَاغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ وَاعْفُ عَنْهُ، وَاغْسِلْهُ بِمَاءٍ وَثَلْجٍ وَبَرَدٍ، وَنَقِّهِ مِنَ الذُّنُوبِ وَالْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، وَأَبْدِلْهُ بِدَارِهِ دَارًا خَيْرًا مِنْ دَارِهِ وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَقِهِ فِتْنَةَ الْقَبْرِ وَعَذَابَ النَّارِ". قَالَ عَوْفٌ: فَلَقَدْ رَأَيْتُنِي فِي مُقَامِي ذَلِكَ أَتَمَنَّى أَنْ أَكُونَ مَكَانَ ذَلِكَ الرَّجُلِ. (ن,جه)', 'ഔഫ്ബ്നുമാലിക്(റ): അൻസ്വാരികളിൽപെട്ട ഒരാൾക്ക് നബി(സ) നിസ്കരിക്കുന്നതിന് ഞാൻ സാക്ഷിയായി. അപ്പോൾ അവിടുന്ന് ഇപ്രകാരം പറയുന്നതായി ഞാൻ കേട്ടു: "ഇദ്ദേഹത്തിന് നീ രക്ഷയേകുകയും പൊറുത്തു കൊടുക്കുകയും കരുണചെയ്യുകയും ചെയ്യേണമേ. വിട്ടുവീഴ്ച ചെയ്യുകയും സൗഖ്യം നൽകുകയും ചെയ്യേണമേ. വെള്ളം, മഞ്ഞ്, ഹിമം എന്നിവ കൊണ്ട് കഴുകയും ചെയ്യേണമേ. അഴുക്കുകളിൽ നിന്ന് വെള്ള വസ്ത്രം ശുചീകരിക്കുന്നത് പോലെ ഇദ്ദേഹത്തിന്റെ പാപങ്ങളെ നീ ശുദ്ധീകരിക്കേണമേ. ഇദ്ദേഹത്തിന്റെ ഭവനത്തേക്കാൾ ഉത്തമ ഭവനവും കുടുംബത്തേക്കാൾ ഉത്തമകുടുംബവും നീ നൽകേണമേ. നരകശിക്ഷയിൽ നിന്നും ഖബറിലെ ശിക്ഷയിൽ നിന്നും ഇദ്ദേഹത്തെ നീ രക്ഷിക്കേണമേ." ഔഫ് പറഞ്ഞു: ആ മനുഷ്യന്റെ സ്ഥാനത്ത് ഞാനായിരുന്നെങ്കിൽ എന്നു ഞാൻ ആശിച്ചു പോയി. (ന,ജ)', 'عَوْفِ بْنِ مَالِكٍ', 'ഔഫ്ബ്നുമാലിക്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 810, 811, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَا أُبَاحَ لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَا أَبُو بَكْرٍ، وَلَا عُمَرُ فِي شَيْءٍ مَا أَبَاحُوا فِي الصَّلَاةِ عَلَى الْمَيِّتِ. يَعْنِي لَمْ يُوَقِّتْ. [ز: في إسناده مدلس عنعنه] (جه)', 'ജാബിർ(റ): നബി(സ)യും അബൂബക്കറും(റ), ഉമറും(റ) മയ്യിത്ത് നിസ്കാരത്തിലേതു പോലെ ഒന്നിലും ഇങ്ങനെ അനുവദനീയമാക്കിത്തന്നിട്ടില്ല. അതായത് സമയം നിശ്ചയിച്ചിട്ടില്ല. (ഇതിന്റെ സനദിൽ അൻഅന യാക്കി ഉദ്ധരിച്ച മുദല്ലിസുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مدلس عنعنه', null, 811, 811, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ عَوْفِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَى مَيِّتٍ، فَفَهِمْتُ مِنْ صَلَاتِهِ عَلَيْهِ: "اللَّهُمَّ اغْفِرْ لَهُ، وَارْحَمْهُ، وَاغْسِلْهُ بِالْبَرَدِ، وَاغْسِلْهُ كَمَا يُغْسَلُ الثَّوْبُ". حَسَنٌ صَحِيحٌ. (م,ت,جه)', 'ഔഫ്ബ്നുമാലിക്(റ): ഒരു മയ്യിത്തിന് വേണ്ടി പ്രവാചകൻ(സ) നിസ്കരിക്കുന്നത് ഞാൻ ശ്രവിച്ചു. അവിടുത്തെ ആ നിസ്കാരത്തിൽ നിന്ന് ഞാൻ ഇപ്രകാരം ഗ്രഹിച്ചു: "അല്ലാഹുവേ നീ ഇദ്ദേഹത്തിന് പൊറുത്തുകൊടുക്കുകയും കരുണചെയ്യുകയും ചെയ്യേണമേ. ഇദ്ദേഹത്തെ നീ ഹിമം കൊണ്ട് കഴുകേണമേ. വസ്ത്രം കഴുകുന്നതുപോലെ നീ ഇദ്ദേഹത്തെ കഴുകേണമേ." ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (മു,തു,ജ)', 'عَوْفِ بْنِ مَالِكٍ', 'ഔഫ്ബ്നുമാലിക്(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 811, 811, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ مَرْوَانَ: سَأَلَ أَبَا هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: كَيْفَ سَمِعْتَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَى الْجَنَازَةِ؟ قَالَ أَبُو هُرَيْرَةَ: "اللَّهُمَّ أَنْتَ رَبُّهَا، وَأَنْتَ خَلَقْتَهَا، وَأَنْتَ هَدَيْتَهَا لِلْإِسْلَامِ، وَأَنْتَ قَبَضْتَ رُوحَهَا، وَأَنْتَ أَعْلَمُ بِسِرِّهَا وَعَلَانِيَتِهَا، جِئْنَاكَ شُفَعَاءَ فَاغْفِرْ لَهُ". (د)', 'മർവാൻ(റ): അദ്ദേഹം അബൂഹുറൈറ(റ)യോട് ചോദിച്ചു. നബി(സ) ജനാസ നിസ്കരിക്കുന്നത് എങ്ങനെയാണ് താങ്കൾ കേട്ടത്? അബൂഹുറൈറ(റ) പറഞ്ഞു: "അല്ലാഹുവേ നീ അതിന്റെ (മയ്യിത്തിന്റെ) റബ്ബാണ്. നീ അതിനെ സൃഷ്ടിച്ചു, നീ അതിനെ ഇസ്ലാമിലേക്ക് നയിച്ചു, നീ അതിന്റെ ആത്മാവിനെ പിടികൂടിയിരിക്കുന്നു. നീയാണിതിന്റെ രഹസ്യവും പരസ്യവും ഏറ്റവും അറിയുന്നത്. ഞങ്ങൾ നിന്റെയടുത്ത് ശുപാർശകരായി വന്നിരിക്കുന്നു. നീ അദ്ദേഹത്തിന്ന് പൊറുത്തു കൊടുക്കേണമേ." (ദ)', 'مَرْوَانَ', 'മർവാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 811, 811, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَخَاكُمْ قَدْ مَاتَ، فَقُومُوا فَصَلُّوا عَلَيْهِ". (ن)', 'ഇംറാനുബ്നു ഹുസൈ്വൻ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ സഹോദരൻ മരിച്ചിരിക്കുന്നു. അതിനാൽ എഴുന്നേറ്റ് നിസ്കരിക്കിൻ." (ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈ്വൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 811, 811, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ طَلْحَةَ بْنِ عَبْدِ اللهِ بْنِ عَوْفٍ قَالَ: صَلَّيْتُ خَلْفَ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا عَلَى جَنَازَةٍ، فَقَرَأَ بِفَاتِحَةِ الْكِتَابِ وَسُورَةٍ، وَجَهَرَ حَتَّى أَسْمَعَنَا، فَلَمَّا فَرَغَ أَخَذْتُ بِيَدِهِ فَسَأَلْتُهُ، فَقَالَ: سُنَّةٌ وَحَقٌّ. وَفِي رِوَايَةٍ: فَسَمِعْتُهُ يَقْرَأُ بِفَاتِحَةِ الْكِتَابِ، فَلَمَّا انْصَرَفَ أَخَذْتُ بِيَدِهِ فَسَأَلْتُهُ: تَقْرَأُ؟ قَالَ: نَعَمْ، إِنَّهُ حَقٌّ وَسُنَّةٌ. (ن)', 'ത്വൽഹത് ഇബ്നുഅബ്ദുല്ലാഹിബ്നു ഔഫ്(റ): ഞാൻ ഇബ്നുഅബ്ബാസി(റ)ന്റെ പിന്നിൽ നിന്ന് ഒരു ജനാസ നിസ്കരിച്ചു. അപ്പോൾ അദ്ദേഹം ഫാത്തിഹയും ഒരു സൂറത്തും പാരായണം ചെയ്തു. ഞങ്ങൾ കേൾക്കും വിധം അദ്ദേഹം ഉറക്കെയാണ് പാരായണം നടത്തിയത്. നിസ്കാരത്തിൽ നിന്നും വിരമിച്ച ശേഷം ഞാൻ അദ്ദേഹത്തിന്റെ കൈ പിടിച്ച് അതേപ്പറ്റി ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അത് സുന്നത്തും വാസ്തവവുമാണ്. മറ്റൊരു റിപ്പോർട്ടിൽ: അപ്പോൾ അദ്ദേഹം ഫാത്തിഹ ഓതുന്നത് ഞാൻ കേട്ടു. നിസ്കാരം കഴിഞ്ഞപ്പോൾ ഞാനദ്ദേഹത്തിന്റെ കൈ പിടിച്ചു. എന്നിട്ട് ചോദിച്ചു: താങ്കൾ ഖുർആൻ പാരായണം ചെയ്തു? അദ്ദേഹം പറഞ്ഞു: അത് ശരിയും സുന്നത്തുമാകുന്നു. (ന)', 'طَلْحَةَ بْنِ عَبْدِ اللهِ بْنِ عَوْفٍ قَالَ', 'ത്വൽഹത് ഇബ്നുഅബ്ദുല്ലാഹിബ്നു ഔഫ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 811, 811, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=179), 1, 'وَفِي رِوَايَةٍ: فَسَمِعْتُهُ يَقْرَأُ بِفَاتِحَةِ الْكِتَابِ، فَلَمَّا انْصَرَفَ أَخَذْتُ بِيَدِهِ فَسَأَلْتُهُ: تَقْرَأُ؟ قَالَ: نَعَمْ، إِنَّهُ حَقٌّ وَسُنَّةٌ. (ن)', 'മറ്റൊരു നിവേദനിൽ: അപ്പോൾ അദ്ദേഹം ഫാത്തിഹ ഓതുന്നത് ഞാൻ കേട്ടു. നിസ്കാരം കഴിഞ്ഞപ്പോൾ ഞാനദ്ദേഹത്തിന്റെ കൈ പിടിച്ചു. എന്നിട്ട് ചോദിച്ചു: താങ്കൾ ഖുർആൻ പാരായണം ചെയ്തു? അദ്ദേഹം പറഞ്ഞു: അത് ശരിയും സുന്നത്തുമാകുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: السُّنَّةُ فِي الصَّلَاةِ عَلَى الْجَنَازَةِ أَنْ يَقْرَأَ فِي التَّكْبِيرَةِ الْأُولَى بِأُمِّ الْقُرْآنِ مُخَافَتَةً، ثُمَّ يُكَبِّرَ ثَلَاثًا، وَالتَّسْلِيمُ عِنْدَ الْآخِرَةِ. (ن)', 'അബൂഉമാമ(റ): ജനാസ നിസ്കാരത്തിൽ ഒന്നാമത്തെ റക്അത്തിൽ ശബ്ദം താഴ്ത്തി ഫാതിഹ സൂറത്ത് ഓതലാണ് സുന്നത്ത്. പിന്നെ മൂന്ന് തക്ബീർ ചൊല്ലുകയും അവസാനത്തിൽ സലാം വീട്ടുകയും ചെയ്യണം. (ന)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 812, 812, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ السِّقْطَ لَيُرَاغِمُ رَبَّهُ إِذَا أَدْخَلَ أَبَوَيْهِ النَّارَ، فَيُقَالُ: أَيُّهَا السِّقْطُ الْمُرَاغِمُ رَبَّهُ، أَدْخِلْ أَبَوَيْكَ الْجَنَّةَ. فَيَجُرُّهُمَا بِسَرَرِهِ حَتَّى يُدْخِلَهُمَا الْجَنَّةَ". [ز: في سنده ضعف] (جه)', 'ആയിശ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ചാപ്പിള്ളയുടെ മാതാപിതാക്കളെ നരകത്തിൽ പ്രവേശിപ്പിച്ചാൽ അത് റബ്ബിനോട് തർക്കിക്കും. അപ്പോൾ ആ ചാപ്പിള്ളയോട് ഇങ്ങനെ പറയപ്പെടും: റബ്ബിനോട് തർക്കിക്കുന്ന ചാപ്പിള്ളേ, നീ നിന്റെ മാതാപിതാക്കളെ സ്വർഗത്തിൽ പ്രവേശിപ്പിച്ച് കൊള്ളൂ. അങ്ങനെ അവൻ തന്റെ പൊക്കിൾകൊടികൊണ്ട് വലിച്ച് അവരെ സ്വർഗത്തിൽ പ്രവേശിപ്പിക്കും." (ഇതിന്റെ പരമ്പരയിൽ ദുർബലതയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'عَلِيٍّ', 'ആയിശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലതയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 812, 812, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَسِقْطٌ أُقَدِّمُهُ بَيْنَ يَدَيَّ أَحَبُّ إِلَيَّ مِنْ فَارِسٍ أُخَلِّفُهُ خَلْفِي". [ز: في سنده ضعف] (جه)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "എന്റെ മുമ്പിലായി എനിക്ക് ഒരു ചാപ്പിള്ള മരിച്ചു പോകുന്നതാണ് എന്റെ പിന്നിലായി ഞാനൊരു അശ്വഭടനെ ഉപേക്ഷിച്ചുപോകുന്നതിനേക്കാൾ ഞാൻ ഇഷ്ടപ്പെടുന്നത്." (ഇതിന്റെ പരമ്പരയിൽ ദുർബലതയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലതയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 812, 812, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "وَالَّذِي نَفْسِي بِيَدِهِ، إِنَّ السِّقْطَ لَيَجُرُّ أُمَّهُ بِسَرَرِهِ إِلَى الْجَنَّةِ إِذَا احْتَسَبَتْهُ". [ز: في سنده ضعف] (جه)', 'മുആദുബ്നു ജബൽ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവനാണ് സത്യം, മാതാവ് ക്ഷമയോടെ പ്രതിഫലം കാംക്ഷിക്കുന്നപക്ഷം ചാപ്പിള്ള തന്റെ മാതാവിനെ പൊക്കിൾ കൊടികൊണ്ട് വലിച്ച് സ്വർഗത്തിലേക്ക് നയിക്കുന്നതാണ്."(ഇതിന്റെ പരമ്പരയിൽ ദുർബലതയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലതയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 812, 812, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى أَبِي سَيْفٍ الْقَيْنِ وَكَانَ ظِئْرًا لِإِبْرَاهِيمَ عَلَيْهِ السَّلَامُ، فَأَخَذَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِبْرَاهِيمَ فَقَبَّلَهُ وَشَمَّهُ، ثُمَّ دَخَلْنَا عَلَيْهِ بَعْدَ ذَلِكَ، وَإِبْرَاهِيمُ يَجُودُ بِنَفْسِهِ، فَجَعَلَتْ عَيْنَا رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَذْرِفَانِ، فَقَالَ لَهُ عَبْدُالرَّحْمَنِ بْنُ عَوْفٍ رَضِيَ اللهُ عَنْهُ: وَأَنْتَ يَا رَسُولَ اللهِ، فَقَالَ: "يَا ابْنَ عَوْفٍ إِنَّهَا رَحْمَةٌ". ثُمَّ أَتْبَعَهَا بِأُخْرَى فَقَالَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْعَيْنَ تَدْمَعُ، وَالْقَلْبَ يَحْزَنُ، وَلَا نَقُولُ إِلَّا مَا يَرْضَى رَبُّنَا، وَإِنَّا لِفِرَاقِكَ يَا إِبْرَاهِيمُ لَمَحْزُونُونَ". (خ)', 'അനസുബ്നു മാലിക്(റ): ഞങ്ങൾ പ്രവാചകർ(സ)യുടെ കൂടെ അബൂസൈഫുൽ ഖൈനിന്റെ അടുക്കൽ ചെന്നു. അദ്ദേഹം ഇബ്രാഹീമിന്റെ പരിപാലകനായിരുന്നു അങ്ങനെ തിരുമേനി(സ) ഇബ്രാഹിമിനെ വാങ്ങി മുത്തി മണത്തു. അതിനുശേഷം പിന്നീട് വീണ്ടും ഞങ്ങൾ ഇബ്രാഹിമിന്റെ അടുക്കൽ പ്രവേശിച്ചു. ഇബ്രാഹിം തന്റെ ആത്മാവ് ത്യജിച്ചുകൊണ്ടിരിക്കുകയാണ്. അപ്പോൾ പ്രവാചകന്റെ(സ) രണ്ടു കണ്ണുകൾ ഈറനണിയാൻ തുടങ്ങി. അപ്പോൾ നബി(സ)യോട് അബ്ദുറഹ്മാനുബ്നു ഔഫ്(റ) ചോദിച്ചു: പ്രവാചകരേ, താങ്കളും.. അവിടുന്ന് പറഞ്ഞു: "ഇബ്നുഔഫേ, ഇത് കാരുണ്യമാണ്." ഇതിനെ തുടർന്ന് ഇങ്ങനെയും കൂടി തിരുമേനി(സ) പറഞ്ഞു. "കണ്ണ് ബാഷ്പം പൊഴിക്കും, ഹൃദയം ദുഃഖിക്കും, എന്നാൽ നമ്മുടെ നാഥൻ തൃപ്തിപ്പെടാത്തതൊന്നും നാം പറയുകയില്ല. ഓ ഇബ്രാഹിം! നിന്റെ വേർപാടിൽ ഞങ്ങൾ ദുഃഖിതരാണ്." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 812, 813, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِنِسْوَةٍ مِنَ الْأَنْصَارِ: لَا يَمُوتُ لِإِحْدَاكُنَّ ثَلَاثَةٌ مِنَ الْوَلَدِ، فَتَحْتَسِبُهُ، إِلَّا دَخَلَتِ الْجَنَّةَ. فَقَالَتِ امْرَأَةٌ مِنْهُنَّ: أَوِ اثْنَانِ يَا رَسُولَ اللهِ؟ قَالَ: "أَوِ اثْنَانِ". [وباسناده آخر عنه مرفوعا: "لَا يَمُوتُ لِأَحَدٍ مِنَ الْمُسْلِمِينَ ثَلَاثَةٌ مِنَ الْوَلَدِ فَتَمَسَّهُ النَّارُ، إِلَّا تَحِلَّةَ الْقَسَمِ".] (م)', 'അബുഹുറൈറ(റ): പ്രവാചകൻ(സ) അൻസ്വാരി സ്ത്രീകളോട് പറഞ്ഞു: "നിങ്ങളിൽ ഒരാൾക്ക് മൂന്ന് കുട്ടികൾ മരിക്കുകയും അവർ ക്ഷമയോടെ, പ്രതിഫലകാംക്ഷയോടെ കഴിയുകയുമാണെങ്കിൽ അവർ സ്വർഗത്തിൽ പ്രവേശിക്കാതിരിക്കില്ല." മറ്റൊരു സത്രീ ചോദിച്ചു: രണ്ട് പേരാണെങ്കിലോ പ്രവാചകരേ? പ്രവാചകൻ(സ) പറഞ്ഞു: "രണ്ടാണെങ്കിലും ശരി." മർഫൂആയ മറ്റൊരു പരമ്പരയിൽ ഇങ്ങനെയുണ്ട്: "മുസ്ലിംകളിൽ നിന്ന് ഒരാൾക്ക് മൂന്ന് കുട്ടികൾ മരിക്കുന്നപക്ഷം അയാളെ നരകം സ്പർശിക്കുകയില്ല, സത്യം ചെയ്തതിന്റെ ലംഘനത്തിന്റെ പേരിലൊഴികെ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'وباسناده آخر عنه مرفوعا: "لَا يَمُوتُ لِأَحَدٍ مِنَ الْمُسْلِمِينَ ثَلَاثَةٌ مِنَ الْوَلَدِ فَتَمَسَّهُ النَّارُ، إِلَّا تَحِلَّةَ الْقَسَمِ".', null, 813, 813, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ لَا يَرْضَى لِعَبْدِهِ الْمُؤْمِنِ – إِذَا ذَهَبَ بِصَفِيِّهِ مِنْ أَهْلِ الْأَرْضِ، فَصَبَرَ وَاحْتَسَبَ وَقَالَ مَا أُمِرَ بِهِ – بِثَوَابٍ دُونَ الْجَنَّةِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഭൂനിവാസികളിൽ നിന്നും സത്യവിശ്വാസിയായ ഒരു അടിമയുടെ കുഞ്ഞിനെ അല്ലാഹു കൊണ്ടു പോവുകയും അതിൽ അവൻ ക്ഷമിക്കുകയും പ്രതിഫലം ആഗ്രഹിക്കുകയും കൽപിക്കപ്പെട്ടത് പറയുകയും ചെയ്താൽ സ്വർഗത്തിൽ കുറഞ്ഞ ഒരു പ്രതിഫലവും അവന് നൽകാൻ അല്ലാഹു ഇഷ്ടപ്പെടുകയില്ല." (ന)', 'عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 813, 813, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ احْتَسَبَ ثَلَاثَةً مِنْ صُلْبِهِ دَخَلَ الْجَنَّةَ". فَقَامَتِ امْرَأَةٌ فَقَالَتْ: أَوِ اثْنَانِ؟ قَالَ: "أَوِ اثْنَانِ". قَالَتِ الْمَرْأَةُ: يَا لَيْتَنِي قُلْتُ وَاحِدًا. (ن)', 'അനസ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "മൂന്ന് കുട്ടികളുടെ മരണത്തിൽ ക്ഷമയോടെ നിലകൊണ്ടവൻ സ്വർഗത്തിൽ പ്രവേശിക്കും." ഒരു സ്ത്രീ എഴുന്നേറ്റു ചോദിച്ചു: രണ്ടാണെങ്കിലോ? നബി(സ) പറഞ്ഞു: "രണ്ടാണെങ്കിലും." ആ സ്ത്രീ പിന്നീട് പറഞ്ഞു: ഞാൻ ഒന്നാണെങ്കിലോ എന്ന് ചോദിച്ചിരുന്നെങ്കിൽ. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 813, 813, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ مُسْلِمَيْنِ يَمُوتُ بَيْنَهُمَا ثَلَاثَةُ أَوْلَادٍ، لَمْ يَبْلُغُوا الْحِنْثَ، إِلَّا غَفَرَ اللهُ لَهُمَا بِفَضْلِ رَحْمَتِهِ إِيَّاهُمْ". (ن)', 'അബൂദർറ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "രണ്ട് മുസ്ലിംകൾക്കിടയിൽ നിന്ന്(ദമ്പതികൾ) മൂന്ന് കുട്ടികൾ പ്രായപൂർത്തിയാവാതെ മരിക്കുന്ന പക്ഷം അവരോടുള്ള കാരുണ്യം മൂലം അവർ രണ്ട് പേർക്കും അല്ലാഹു പൊറുത്ത് കൊടുക്കാതിരിക്കില്ല." (ന)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 813, 814, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ مُسْلِمَيْنِ يَمُوتُ بَيْنَهُمَا ثَلَاثَةُ أَوْلَادٍ، لَمْ يَبْلُغُوا الْحِنْثَ، إِلَّا أَدْخَلَهُمَا اللهُ بِفَضْلِ رَحْمَتِهِ إِيَّاهُمُ الْجَنَّةَ قَالَ: يُقَالُ لَهُمُ: ادْخُلُوا الْجَنَّةَ. فَيَقُولُونَ: حَتَّى يَدْخُلَ آبَاؤُنَا. فَيُقَالُ: ادْخُلُوا الْجَنَّةَ أَنْتُمْ وَآبَاؤُكُمْ". (خ,ن)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "രണ്ട് മുസ്ലിംകൾക്കിടയിൽ നിന്ന് പ്രായപൂർത്തിയാവാത്ത മൂന്ന് കുട്ടികൾ മരിക്കുന്നപക്ഷം അവരോടുള്ള കാരുണ്യം നിമിത്തം അവർ രണ്ട്പേരെയും അല്ലാഹു സ്വർഗത്തിൽ പ്രവേശിപ്പിക്കും. അവരോട് പറയപ്പെടും: നിങ്ങൾ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുക. അവർ പറയും: ഞങ്ങളുടെ പിതാക്കൾ പ്രവേശിക്കുന്നത് വരെ (ഞങ്ങൾ പ്രവേശിക്കുകയില്ല). അപ്പോൾ പറയപ്പെടും: നിങ്ങളും പിതാക്കളും സ്വർഗത്തിൽ പ്രവേശിക്കുക." (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 814, 814, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَتِ امْرَأَةٌ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِابْنٍ لَهَا يَشْتَكِي، فَقَالَتْ: يَا رَسُولَ اللهِ، أَخَافُ عَلَيْهِ، وَقَدْ قَدَّمْتُ ثَلَاثَةً؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَقَدِ احْتَظَرْتِ بِحِظَارٍ شَدِيدٍ مِنَ النَّارِ". (ن)', 'അബൂഹുറൈറ(റ): രോഗാതുരമായ ഒരു മകനേയും ചുമന്ന്കൊണ്ട് ഒരു സ്ത്രീ പ്രവാചക(സ)ന്റെ അടുക്കൽ വന്നിട്ട് പറഞ്ഞു: പ്രവാചകരേ! ഞാൻ ഇവന്റെ മേൽ ഭയപ്പെടുന്നു. മൂന്ന് പേർ മുമ്പ് മരിച്ചിട്ടുണ്ട്. നബി(സ) പറഞ്ഞു: "നിനക്ക് നരകത്തിൽ നിന്നും ഒരു ശക്തമായ കാവൽ ലഭിച്ചിരിക്കുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 814, 814, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا مَاتَتْ زَيْنَبُ بِنْتُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اغْسِلْنَهَا وِتْرًا: ثَلَاثًا أَوْ خَمْسًا، وَاجْعَلْنَ فِي الْخَامِسَةِ كَافُورًا، أَوْ: شَيْئًا مِنْ كَافُورٍ، فَإِذَا غَسَلْتُنَّهَا فَأَعْلِمْنَنِي". قَالَتْ: فَأَعْلَمْنَاهُ، فَأَعْطَانَا حِقْوَهُ وَقَالَ: "أَشْعِرْنَهَا إِيَّاهُ". (م)', 'ഉമ്മുഅതിയ്യ(റ): പ്രവാചകപുത്രി സൈനബ(റ) മരിച്ചപ്പോൾ ഞങ്ങളോട് പ്രവാചകൻ(സ) പറഞ്ഞു. "അവളെ ഒറ്റയായി, മൂന്നോ, അഞ്ചോ പ്രാവശ്യം കുളിപ്പിക്കുക. അഞ്ചാമത്തേതിൽ കർപ്പൂരം ചേർത്ത് കുളിപ്പിച്ച് കഴിഞ്ഞാൽ വിവരം എന്നെ അറിയിക്കുക." ആഇശ(റ) പറഞ്ഞു: അങ്ങനെ ഞങ്ങൾ വിവരം അറിയിച്ചു. അങ്ങനെ പ്രവാചകർ(സ)യുടെ തട്ടം ഞങ്ങൾക്ക് തന്നിട്ട് പറഞ്ഞു: "ഇത് അവർക്ക് അടിവസ്ത്രമാക്കുക." (മു)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅതിയ്യ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 814, 814, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لِيُغَسِّلْ مَوْتَاكُمُ الْمَأْمُونُونَ". [ز: في إسناده متهم بالكذب, ومدلس عنعنه] (جه)', 'റസൂൽ(സ) പറഞ്ഞതായി അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): "നിങ്ങളിൽ നിന്നും മരിച്ചവരെ വിശ്വസ്തർ കുളിപ്പിക്കട്ടെ." (ഇതിന്റെ സനദിൽ കള്ളം ആരോപിക്കപ്പെട്ടവനും, അൻഅനയാക്കി ഉദ്ധരിക്കുന്ന മുദല്ലിസുമുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'റസൂൽ(സ) പറഞ്ഞതായി അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده متهم بالكذب, ومدلس عنعنه', null, 814, 814, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ غَسَّلَ مَيِّتًا وَكَفَّنَهُ وَحَنَّطَهُ وَحَمَلَهُ وَصَلَّى عَلَيْهِ، وَلَمْ يُفْشِ عَلَيْهِ مَا رَأَى، خَرَجَ مِنْ خَطِيئَتِهِ مِثْلَ يَوْمٍ وَلَدَتْهُ أُمُّهُ". [ز: في إسناده متهم بالكذب] (جه)', 'പ്രവാചകൻ(സ) പറഞ്ഞതായി അലി(റ): "വല്ലവനും മൃതശരീരത്തെ കുളിപ്പിക്കുകയും കഫൻ ചെയ്യുകയും സുഗന്ധം പൂശുകയും ചുമക്കുകയും, അതിനുവേണ്ടി നിസ്കരിക്കുകയും, ശേഷം അവർ കണ്ട രഹസ്യം വെളിപ്പെടുത്താതിരിക്കുകയും ചെയ്യുകയാണെങ്കിൽ തന്റെ മാതാവ് പ്രസവിച്ച നാളിലേതുപോലെ അവൻ പാപങ്ങളിൽ നിന്ന് മോചിതനാവുന്നതാണ്." (ഇതിന്റെ സനദിൽ കള്ളം ആരേപിക്കപ്പെട്ട വ്യക്തി ഉണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'عَلِيٍّ', 'പ്രവാചകൻ(സ) പറഞ്ഞതായി അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده متهم بالكذب', null, 815, 815, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: تُوُفِّيَ ابْنِي فَجَزِعْتُ عَلَيْهِ، فَقُلْتُ لِلَّذِي يَغْسِلُهُ: لَا تَغْسِلِ ابْنِي بِالْمَاءِ الْبَارِدِ فَتَقْتُلَهُ. فَانْطَلَقَ عُكَّاشَةُ بْنُ مِحْصَنٍ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ بِقَوْلِهَا، فَتَبَسَّمَ ثُمَّ قَالَ: "مَا قَالَتْ؟ طَالَ عُمْرُهَا". فَلَا نَعْلَمُ امْرَأَةً عَمِرَتْ مَا عَمِرَتْ. (ن)', 'ഉമ്മുഖൈസ് ബിൻത് മഹ്സൻ(റ): എന്റെ മകൻ മരണപ്പെട്ടപ്പോൾ ഞാൻ അതിൽ വ്യാകുലയായിരുന്നു. അവനെ കുളിപ്പിക്കുന്ന ആളോട് ഞാൻ പറഞ്ഞു: എന്റെ മകനെ ശീതജലം കൊണ്ട് കുളിപ്പിക്കരുത്. അത് അവനെ കൊന്ന് കളയും. ഉക്കാശത്ബ്നു മിഹ്സൻ പോയി ഈ വിവരം പ്രവാചകനെ(സ) അറിയിച്ചു. പുഞ്ചിരിച്ചുകൊണ്ട് നബി(സ) പറഞ്ഞു: "എന്താണ് അവൾ പറഞ്ഞത്? അവൾക്ക് ആയുർദൈർഘ്യം നൽകട്ടെ." അവർ ജീവിച്ചപോലെ ദീർഘമായി ജീവിച്ച ഒരു സ്ത്രീയെയും ഞങ്ങൾക്ക് അറിയില്ല. (ന)', 'أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ', 'ഉമ്മുഖൈസ് ബിൻത് മഹ്സൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 815, 815, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: تُوُفِّيَتْ إِحْدَى بَنَاتِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "اغْسِلْنَهَا وِتْرًا: ثَلَاثًا أَوْ خَمْسًا أَوْ أَكْثَرَ مِنْ ذَلِكَ إِنْ رَأَيْتُنَّ، وَاغْسِلْنَهَا بِمَاءٍ وَسِدْرٍ، وَاجْعَلْنَ فِي الْآخِرَةِ كَافُورًا، أَوْ: شَيْئًا مِنْ كَافُورٍ. فَإِذَا فَرَغْتُنَّ فَآذِنَّنِي". فَلَمَّا فَرَغْنَا آذَنَّاهُ، فَأَلْقَى إِلَيْنَا حِقْوَهُ، فَقَالَ: "أَشْعِرْنَهَا بِهِ". وَفِي رِوَايَةٍ قَالَتْ: وَضَفَرْنَا شَعْرَهَا ثَلَاثَةَ قُرُونٍ، فَأَلْقَيْنَاهُ خَلْفَهَا. وَفِي رِوَايَةٍ قَالَتْ: وَقَالَ لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَابْدَأْنَ بِمَيَامِنِهَا وَمَوَاضِعِ الْوُضُوءِ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'ഉമ്മുഅതിയ്യ(റ): പ്രവാചകന്റെ(സ) ഒരു പുത്രി മരണപ്പെട്ടപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "അവളെ ഒറ്റയായി കുളിപ്പിക്കുക. മൂന്നോ അഞ്ചോ, ആവശ്യമെങ്കിൽ അതിലധികമായും. വെള്ളംകൊണ്ടും താളികൊണ്ടും കുളിപ്പിക്കുക. അവസാനത്തേതിൽ അൽപം കർപ്പൂരം ചേർക്കുക. കുളിപ്പിച്ച് കഴിഞ്ഞാൽ എന്നെ വിവരം അറിയിക്കുക." കഴിഞ്ഞപ്പോൾ ഞങ്ങൾ നബി(സ)യെ അറിയിച്ചു. നബി(സ) തന്റെ തട്ടം ഇട്ട് തന്ന്കൊണ്ട് പറഞ്ഞു: "ഇത് അവളുടെ അടിവസ്ത്രമാക്കുക." മറ്റൊരു റിപ്പോർട്ടുപ്രകാരം അവർ ഇങ്ങനെയും പറയുന്നുണ്ട്. മൂന്ന് ഭാഗങ്ങളിലായി ഞങ്ങൾ അവളുടെ മുടി മെടഞ്ഞു. അത് പിന്നിലൂടെ ഇട്ടു. മറ്റൊരു റിപ്പോർട്ടിൽ: തിരുമേനി(സ) ഞങ്ങളോട് പറഞ്ഞു: "അവളുടെ വലതുഭാഗം കൊണ്ടും വുളൂഇന്റെ ഭാഗംകൊണ്ടും തുടങ്ങുക." ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅതിയ്യ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 815, 815, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=195), 1, 'وَفِي رِوَايَةٍ قَالَتْ: وَضَفَرْنَا شَعْرَهَا ثَلَاثَةَ قُرُونٍ، فَأَلْقَيْنَاهُ خَلْفَهَا.', 'മറ്റൊരു നിവേദനുപ്രകാരം അവർ ഇങ്ങനെയും പറയുന്നുണ്ട്. മൂന്ന് ഭാഗങ്ങളിലായി ഞങ്ങൾ അവളുടെ മുടി മെടഞ്ഞു. അത് പിന്നിലൂടെ ഇട്ടു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=195), 2, 'وَفِي رِوَايَةٍ قَالَتْ: وَقَالَ لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَابْدَأْنَ بِمَيَامِنِهَا وَمَوَاضِعِ الْوُضُوءِ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: തിരുമേനി(സ) ഞങ്ങളോട് പറഞ്ഞു: "അവളുടെ വലതുഭാഗം കൊണ്ടും വുളൂഇന്റെ ഭാഗംകൊണ്ടും തുടങ്ങുക." ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنِ ابْنِ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا أَخَذُوا فِي غُسْلِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَادَاهُمْ مُنَادٍ مِنَ الدَّاخِلِ: لَا تَنْزِعُوا عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَمِيصَهُ. [ز: في إسناده ضعيف] (جه)', 'ഇബ്നുബുറൈദ(റ): തിരുമേനി(സ)യെ കുളിപ്പിക്കാൻ തുടങ്ങിയപ്പോൾ അകത്തുനിന്ന് ഒരാൾ ഇങ്ങനെ വിളിച്ചു പറഞ്ഞു: റസൂലിന്റെ വസ്ത്രം നീക്കരുത്. (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'ابْنِ بُرَيْدَةَ', 'ഇബ്നുബുറൈദ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 815, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا غَسَّلَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَهَبَ يَلْتَمِسُ مِنْهُ مَا يَلْتَمِسُ مِنَ الْمَيِّتِ، فَلَمْ يَجِدْهُ، فَقَالَ: بِأَبِي، الطَّيِّبُ، طِبْتَ حَيًّا وَطِبْتَ مَيِّتًا. (جه)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): തിരുമേനി(സ)യെ കുളിപ്പിക്കുമ്പോൾ സാധാരണ ഒരു മൃതശരീരത്തിൽനിന്ന് അന്വേഷിക്കുന്നത് അന്വേഷിക്കുകയുണ്ടായി. പക്ഷേ അത് കണ്ടില്ല. അലി(റ) പറയുന്നു: എന്റെ പിതാവിനെതന്നെയാണെ, സുഗന്ധം, ജീവിതകാലത്ത് നിങ്ങൾ പരിമളം പരത്തി. മിരിച്ചപ്പോഴും പരിമളം തന്നെ. (ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 816, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَنَا مُتُّ فَاغْسِلُونِي بِسَبْعِ قِرَبٍ مِنْ بِئْرِي: بِئْرِ غَرْسٍ". [ز: في إسناده ضعيف] (جه)', 'അലി(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഞാൻ മരിച്ചാൽ എന്റെ ഗർസിലെ കിണറ്റിൽ നിന്ന് ഏഴ് തോൽപ്പാത്രം വെള്ളം കൊണ്ട് നിങ്ങൾ എന്നെ കുളിപ്പിക്കുക." (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 816, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ حَفْصَةَ بِنْتِ سِيرِينَ قَالَتْ: حَدَّثَتْنَا أُمُّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا: أَنَّهُنَّ جَعَلْنَ رَأْسَ ابْنَةِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثَلَاثَةَ قُرُونٍ، قُلْتُ: نَقَضْنَهُ وَجَعَلْنَهُ ثَلَاثَةَ قُرُونٍ؟ قَالَتْ: نَعَمْ. (ن)', 'ഹഫ്സ ബിൻത് സീരീൻ(റ): ഉമ്മുഅതിയ്യ(റ) അവരോട് ഇങ്ങനെ പറഞ്ഞു: അവർ തിരുമേനി(സ)യുടെ പുത്രിയുടെ തലമുടി മൂന്ന് ഭാഗങ്ങളാക്കി. ഞാൻ ചോദിച്ചു: അത് കെട്ടഴിച്ച് മൂന്ന് ഭാഗങ്ങളാക്കുകയാണോ ചെയ്തത്. അവർ പറഞ്ഞു: അതെ. (ന)', 'حَفْصَةَ بِنْتِ سِيرِينَ قَالَتْ', 'ഹഫ്സ ബിൻത് സീരീൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 816, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَطْيَبُ الطِّيبِ الْمِسْكُ". وَفِي رِوَايَةٍ: "مِنْ خَيْرِ طِيبِكُمُ الْمِسْكُ". (م,د,ت,ن)', 'അബൂസഈദുൽ ഖുദ്രി(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഏറ്റവും നല്ല സുഗന്ധം കസ്തൂരിയാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ: "നിങ്ങളുടെ സുഗന്ധങ്ങളിൽ വെച്ച് ഏറ്റവും ഉത്തമമായത് കസ്തൂരിയാണ്." (മു,ദ,തു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 816, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=200), 1, 'وَفِي رِوَايَةٍ: "مِنْ خَيْرِ طِيبِكُمُ الْمِسْكُ". (م,د,ت,ن)', 'മറ്റൊരു നിവേദനിൽ: "നിങ്ങളുടെ സുഗന്ധങ്ങളിൽ വെച്ച് ഏറ്റവും ഉത്തമമായത് കസ്തൂരിയാണ്." (മു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَطْيَبُ الطِّيبِ الْمِسْكُ". وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنِ الْمِسْكِ، فَقَالَ: "هُوَ أَطْيَبُ طِيبِكُمْ". حَسَنٌ صَحِيحٌ. (م,د,ت)', 'അബൂസഈദുൽ ഖുദ്രി(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഏറ്റവും നല്ല സുഗന്ധം കസ്തൂരിയാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ)യോട് കസ്തൂരിയെ കുറിച്ച് ചോദിച്ചപ്പോൾ ഇങ്ങനെ പറഞ്ഞു: "അത് നിങ്ങളുടെ സുഗന്ധദ്രവ്യങ്ങളിൽ വെച്ച് ഏറ്റവും ഉത്തമമായതാണ്." (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (മു,ദ,തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 816, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=201), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنِ الْمِسْكِ، فَقَالَ: "هُوَ أَطْيَبُ طِيبِكُمْ". حَسَنٌ صَحِيحٌ. (م,د,ت)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ)യോട് കസ്തൂരിയെ കുറിച്ച് ചോദിച്ചപ്പോൾ ഇങ്ങനെ പറഞ്ഞു: "അത് നിങ്ങളുടെ സുഗന്ധദ്രവ്യങ്ങളിൽ വെച്ച് ഏറ്റവും ഉത്തമമായതാണ്." (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (മു,ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي غَسْلِ ابْنَتِهِ: "ابْدَأْنَ بِمَيَامِنِهَا وَمَوَاضِعِ الْوُضُوءِ مِنْهَا". (ن)', 'ഉമ്മുഅതിയ്യ(റ): പ്രവാചകന്റെ(സ) മകളെ കുളിപ്പിക്കുമ്പോൾ ഇപ്രകാരം നിർദ്ദേശം നൽകി: "അവളുടെ വലതു ഭാഗം കൊണ്ടും വുളൂഇന്റെ ഭാഗങ്ങൾകൊണ്ടും തുടങ്ങുക." (ന)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅതിയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 817, 817, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ مُحَمَّدِ بْنِ سِيرِينَ: أَنَّهُ كَانَ يَأْخُذُ الْغُسْلَ عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا: يَغْسِلُ بِالسِّدْرِ مَرَّتَيْنِ، وَالثَّالِثَةَ بِالْمَاءِ وَالْكَافُورِ. (د)', 'മുഹമ്മദ് ഇബ്നുസീരിൻ(റ): അദ്ദേഹം ഉമ്മുഅതിയ്യ(റ)യിൽ നിന്ന് പഠിച്ചത് മയ്യിത്തിനെ രണ്ട് പ്രാവശ്യം താളി ഉപയോഗിച്ചും മൂന്നാമതായി കർപ്പൂരം കലർത്തിയ വെള്ളം കൊണ്ടും കുളിപ്പിക്കണമെന്നായിരുന്നു. (ദ)', 'مُحَمَّدِ بْنِ سِيرِينَ', 'മുഹമ്മദ് ഇബ്നുസീരിൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 817, 817, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُبْرِزْ فَخِذَكَ، وَلَا تَنْظُرَنَّ إِلَى حَيٍّ وَلَا مَيِّتٍ". (د,جه)', 'അലി(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിന്റെ തുട വെളിവാക്കരുത്, ജീവിച്ചിരിക്കുന്നവനിലേക്കും മരിച്ചവനിലേക്കും നോക്കുകയും ചെയ്യരുത്." (ദ,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 817, 817, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا أَرَادُوا غَسْلَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالُوا: وَاللهِ مَا نَدْرِي: أَنُجَرِّدُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ ثِيَابِهِ كَمَا نُجَرِّدُ مَوْتَانَا، أَمْ نَغْسِلُهُ وَعَلَيْهِ ثِيَابُهُ؟ فَلَمَّا اخْتَلَفُوا أَلْقَى اللهُ عَلَيْهِمُ النَّوْمَ، حَتَّى مَا مِنْهُمْ رَجُلٌ إِلَّا وَذَقْنُهُ فِي صَدْرِهِ، ثُمَّ كَلَّمَهُمْ مُكَلِّمٌ مِنْ نَاحِيَةِ الْبَيْتِ لَا يَدْرُونَ مَنْ هُوَ: أَنِ اغْسِلُوا النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ ثِيَابُهُ، فَقَامُوا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَغَسَلُوهُ وَعَلَيْهِ قَمِيصُهُ، يَصُبُّونَ الْمَاءَ فَوْقَ الْقَمِيصِ، وَيُدَلِّكُونَهُ بِالْقَمِيصِ دُونَ أَيْدِيهِمْ. وَكَانَتْ عَائِشَةُ تَقُولُ: لَوِ اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ مَا غَسَلَهُ إِلَّا نِسَاؤُهُ. (د,جه)', 'ആയിശ(റ): നബി(സ)യെ കുളിപ്പിക്കാൻ ഉദ്ദേശിച്ചപ്പോൾ ജനങ്ങൾ ഇങ്ങനെ പറഞ്ഞു: അല്ല, റസൂലിനെ സാധാരണ രമിച്ചവരെ നാം കുളിപ്പിക്കുംപോലെ വിവസ്ത്രനാക്കിയാണോ അതോ വസ്ത്രത്തോട് കൂടിയാണോ കുളിപ്പിക്കേണ്ടത് എന്ന് നമുക്ക് അറിഞ്ഞുകൂടാ. അവർ അഭിപ്രായ ഭിന്നരായപ്പോൾ അല്ലാഹു അവർക്ക് ഉറക്കം നൽകി. താടിയെല്ല് നെഞ്ചിൽ വീഴുമാറ് എല്ലാവരും ഉറങ്ങി. പിന്നീട് വീടിന്റെ ഒരു ഭാഗത്ത് നിന്ന് അജ്ഞാതനായ ഒരാൾ അവരോട് ഇപ്രകാരം സംസാരിച്ചു: വസ്ത്രത്തോട് കൂടി നബി(സ)യെ കുളിപ്പിക്കുക. അങ്ങനെ അവർ എഴുന്നേറ്റ് കൊണ്ട് വസ്ത്രത്തോടു കൂടി നബി(സ)യെ കുളിപ്പിച്ചു. വസ്ത്രത്തിന്റെ മേലെ വെള്ളം ഒഴിക്കുകയും കൈകൾ സ്പർശിക്കാതെ വസ്ത്രംകൊണ്ട് തന്നെ തേച്ച് കഴുകുകയും ചെയ്തു. ആയിശ(റ) പറയുമായിരുന്നു: എനിക്ക് പിന്നീട് ബോധ്യപ്പെട്ടത് മുൻകൂട്ടി അറിയാമായിരുന്നുവെങ്കിൽ തിരുമേനി(സ)യെ തന്റെ പത്നിമാരല്ലാതെ കുളിപ്പിക്കില്ലായിരുന്നു. (ദ,ജ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 817, 817, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ غَسَّلَهُ الْغُسْلَ، وَمَنْ حَمَلَهُ الْوُضُوءُ يَعْنِي الْمَيِّتَ". حَسَنٌ. (د,ت,جه)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "മയ്യിത്തിനെ കുളിപ്പിച്ചാൽ കുളിക്കണം. ചുമന്നാൽ വുളൂ ചെയ്യുക." (ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു). (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 818, 818, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ غَسَّلَ مَيِّتًا فَلْيَغْتَسِلْ". (ت,جه)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "മയ്യിത്തിനെ കുളിപ്പിച്ചവൻ കുളിച്ച് കൊള്ളട്ടെ." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 818, 818, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَغْتَسِلُ مِنْ أَرْبَعٍ: مِنَ الْجَنَابَةِ، وَيَوْمَ الْجُمُعَةِ، وَمِنَ الْحِجَامَةِ، وَغُسْلِ الْمَيِّتِ. (د)', 'ആയിശ(റ): നബി(സ) നാല് കാര്യങ്ങൾക്ക് കുളിക്കാറുണ്ടായിരുന്നു: വലിയ അശുദ്ധി, വെള്ളിയാഴ്ച ദിവസം, കൊമ്പു വെക്കുക, മൃതശരീരം കുളിപ്പിക്കുക. (ദ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 818, 818, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: رَجَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ الْبَقِيعِ، فَوَجَدَنِي وَأَنَا أَجِدُ صُدَاعًا فِي رَأْسِي، وَأَنَا أَقُولُ: وَا رَأْسَاهُ. فَقَالَ: "بَلْ أَنَا - يَا عَائِشَةُ - وَا رَأْسَاهُ". ثُمَّ قَالَ: "مَا ضَرَّكِ لَوْ مِتِّ قَبْلِي، فَقُمْتُ عَلَيْكِ: فَغَسَّلْتُكِ وَكَفَّنْتُكِ وَصَلَّيْتُ عَلَيْكِ وَدَفَنْتُكِ". (خ,جه)', 'ആഇശ(റ): പ്രവാചകൻ(സ) ബഖീഇൽ നിന്ന് മടങ്ങി വന്നപ്പോൾ ഞാൻ തലവേദന അനുഭവിക്കുന്ന അവസ്ഥയിലാണ് എന്നെ കണ്ടത്. ഞാൻ ''എന്റെ തല'' എന്ന് പറയുന്നുണ്ടായിരുന്നു. പ്രവാചകൻ(സ) പറഞ്ഞു: "എനിക്കും ആയിശാ തലവേദനയുണ്ട്." പിന്നീട് പ്രവാചകൻ(സ) പറഞ്ഞു: "എന്റെ മുമ്പ് നീ മരിക്കുകയാണെങ്കിൽ നിനക്കൊരു ബുദ്ധിമുട്ടും ഉണ്ടാവില്ല. നിന്റെ എല്ലാ കാര്യവും ഞാൻതന്നെ നിർവ്വഹിക്കും. നിന്നെ കുളിപ്പിക്കും, കഫൻ ചെയ്യും, നിനക്ക് നിസ്കരിക്കും, മറവ് ചെയ്യും". (ബു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 818, 818, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُفِّنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي ثَلَاثَةِ أَثْوَابٍ بِيضٍ سَحُولِيَّةٍ مِنْ كُرْسُفٍ، لَيْسَ فِيهَا قَمِيصٌ وَلَا عِمَامَةٌ، أَمَّا الْحُلَّةُ فَإِنَّمَا شُبِّهَ عَلَى النَّاسِ فِيهَا أَنَّهَا اشْتُرِيَتْ لَهُ لِيُكَفَّنَ فِيهَا، فَتُرِكَتِ الْحُلَّةُ، وَكُفِّنَ فِي ثَلَاثَةِ أَثْوَابٍ بِيضٍ سَحُولِيَّةٍ، فَأَخَذَهَا عَبْدُ اللهِ بْنُ أَبِي بَكْرٍ، فَقَالَ: لَأَحْبِسَنَّهَا حَتَّى أُكَفَّنَ فِيهَا نَفْسِي، ثُمَّ قَالَ: لَوْ رَضِيَهَا اللهُ عَزَّ وَجَلَّ لِنَبِيِّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَكَفَّنَهُ فِيهَا، فَبَاعَهَا وَتَصَدَّقَ بِثَمَنِهَا. (ق,ت,ن,جه)', 'ആയിശ(റ): മൂന്ന് പരുക്കനായ വെള്ള പരുത്തി വസ്ത്രത്തിലാണ് തിരുമേനി(സ) കഫൻ ചെയ്യപ്പെട്ടത്. അതിൽ കുപ്പായവും തലപ്പാവും ഉണ്ടായിരുന്നില്ല. എന്നാൽ പ്രവാചകനെ(സ) കഫൻചെയ്യാൻ വേണ്ടി വാങ്ങിയ വസ്ത്രത്തിന്റെ കാര്യത്തിൽ ജനങ്ങൾക്ക് ആശങ്കയുണ്ടായി. അങ്ങനെ പൂർണ്ണ പുടവ ഉപേക്ഷിക്കപ്പെടുകയും തിരുമേനി(സ)യെ മൂന്ന് പരുക്കൻവെള്ള വസ്ത്രത്തിൽ കഫൻ ചെയ്യപ്പെടുകയും ചെയ്തു. പൂർണ്ണ പുടവ അബ്ദുല്ലാഹിബ്നു അബൂബക്ർ(റ) എടുത്തു. എന്റെ മൃതശരീരം കഫൻ ചെയ്യാൻ വേണ്ടി ഇത് ഞാൻ സൂക്ഷിക്കുകയാണ് എന്ന് അദ്ദേഹം പറഞ്ഞു. പിന്നീട് അദ്ദേഹം, ഇത് നബി(സ)ക്ക് വേണ്ടി അല്ലാഹു ഇഷ്ടപ്പെട്ടിരുന്നുവെങ്കിൽ നബി(സ) ഇതിൽ കഫൻ ചെയ്യപ്പെടുമായിരുന്നു എന്ന് പറഞ്ഞു. പിന്നീട് അദ്ദേഹമത് വിൽക്കുകയും വിലകൊണ്ട് ധർമ്മം ചെയ്യുകയും ചെയ്തു. (ബു,മു,തു,ന,ജ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 818, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ الْعَبَّاسُ بِالْمَدِينَةِ، فَطَلَبَتِ الْأَنْصَارُ ثَوْبًا يَكْسُونَهُ، فَلَمْ يَجِدُوا قَمِيصًا يَصْلُحُ عَلَيْهِ إِلَّا قَمِيصَ عَبْدِ اللهِ بْنِ أُبَيٍّ، فَكَسَوْهُ إِيَّاهُ. (ن)', 'ജാബിർ(റ): അബ്ബാസ് മദീനയിൽ ആയിരുന്നു. അൻസ്വാറുകൾ അദ്ദേത്തിന് ഒരു വസ്ത്രം ധരിപ്പിക്കാൻ ആഗ്രഹിച്ചു. അബ്ദുല്ലാഹിബ്നു ഉബയ്യിന്റെ കുപ്പായമല്ലാതെ അദ്ദേഹത്തിന് പാകമാകുന്നത് കണ്ടില്ല. അങ്ങനെ അത് അദ്ദേഹത്തിന് ധരിപ്പിച്ചു. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 819, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ خَبَّابِ بْنِ الْأَرَتِّ رَضِيَ اللهُ عَنْهُ قَالَ: هَاجَرْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَبْتَغِي وَجْهَ اللهِ تَعَالَى، فَوَجَبَ أَجْرُنَا عَلَى اللهِ، فَمِنَّا مَنْ مَاتَ لَمْ يَأْكُلْ مِنْ أَجْرِهِ شَيْئًا، مِنْهُمْ مُصْعَبُ بْنُ عُمَيْرٍ، قُتِلَ يَوْمَ أُحُدٍ فَلَمْ نَجِدْ شَيْئًا نُكَفِّنُهُ فِيهِ إِلَّا نَمِرَةً: كُنَّا إِذَا غَطَّيْنَا رَأْسَهُ خَرَجَتْ رِجْلَاهُ، وَإِذَا غَطَّيْنَا بِهَا رِجْلَيْهِ خَرَجَتْ رَأْسُهُ، فَأَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نُغَطِّيَ بِهَا رَأْسَهُ وَنَجْعَلَ عَلَى رِجْلَيْهِ إِذْخِرًا. وَمِنَّا مَنْ أَيْنَعَتْ لَهُ ثَمَرَتُهُ، فَهُوَ يَهْدُبُهَا. (خ,ن)', 'ഖബ്ബാബ്(റ): ഞങ്ങൾ പ്രവാചകന്റെ(സ) കൂടെ അല്ലാഹുവിന്റെ പ്രീതി കാംക്ഷിച്ച്കൊണ്ട് പലായനം ചെയ്തു. അങ്ങനെ ഞങ്ങളുടെ പ്രതിഫലം അല്ലാഹുവിന്റെ അടുക്കൽ ഉറപ്പായി. തന്റെ പ്രതിഫലത്തിൽ നിന്നും ഒന്നും തന്നെ ഭുജിക്കാതെ മരിച്ചവർ ഞങ്ങളിലുണ്ട്. അവരിൽ പെടുന്ന മിസ്അബുബ്നു ഉമൈർ(റ) ഉഹ്ദ് യുദ്ധത്തിൽ കൊല്ലപ്പെട്ടു. അദ്ദേഹത്തെ കഫൻ ചെയ്യാൻ ഒരു കരിമ്പടമല്ലാതെ ഞങ്ങൾക്ക് ലഭിച്ചില്ല. തല മൂടിയാൽ രണ്ടു കാലുകളും പുറത്താകും. കാലുകൾ മൂടിയാൽ തല പുറത്താകും. അങ്ങനെ പ്രവാചകൻ(സ) ഞങ്ങളോട് ആ കരിമ്പടം കൊണ്ട് തലമൂടാനും കാലുകളിൽ പുല്ല് വെക്കുവാനും കൽപിച്ചു. ഫലം പാകമായി അത് ഉപകരിച്ചവരും (ഹിജ്റയുടെ ഫലം ലഭിച്ചവർ) ഞങ്ങളിലുണ്ട്. (ബു,ന)', 'خَبَّابِ بْنِ الْأَرَتِّ', 'ഖബ്ബാബ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 819, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: حَدَّثَ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ خَطَبَ يَوْمًا، فَذَكَرَ رَجُلًا مِنْ أَصْحَابِهِ قُبِضَ، فَكُفِّنَ فِي كَفَنٍ غَيْرِ طَائِلٍ وَقُبِرَ لَيْلًا، فَزَجَرَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُقْبَرَ الرَّجُلُ بِاللَّيْلِ حَتَّى يُصَلَّى عَلَيْهِ، إِلَّا أَنْ يُضْطَرَّ إِنْسَانٌ إِلَى ذَلِكَ، وَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا كَفَّنَ أَحَدُكُمْ أَخَاهُ فَلْيُحْسِنْ كَفَنَهُ". (م,د,ن)', 'ജാബിർ(റ): നബി(സ) ഒരിക്കൽ പ്രസംഗിക്കുമ്പോൾ സഹാബികളിൽനിന്ന് ഒരാൾ മരണപ്പെട്ട വിവരം നബി(സ)യെ അറിയിച്ചു. വിശാലമല്ലാത്ത കഫൻ പുടവയിൽ രാത്രിയിലാണ് അദ്ദേഹം ഖബറടക്കം ചെയ്യപ്പെട്ടത്. അപ്പോൾ മയ്യിത്ത് നിസ്കരിക്കുന്നതിന്റെ മുമ്പ് ഒരാളെ രാത്രി മറമാടുന്നത് അത്യാവശ്യഘട്ടത്തിലല്ലാതെ പ്രവാചകൻ(സ) വിലക്കി. പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങളുടെ സഹോദരനെ കഫൻ ചെയ്യുമ്പോൾ നിങ്ങൾ നല്ല രൂപത്തിൽ കഫൻ ചെയ്യുക." (മു,ദ,ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിർ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 819, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أُدْرِجَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي ثَوْبِ حِبَرَةٍ، ثُمَّ أُخِّرَ عَنْهُ. (د)', 'ആഇശ(റ): ഒരു പരുത്തിവസ്ത്രത്തിൽ തിരുമേനി(സ) ആവരണം ചെയ്യപ്പെട്ടു. പിന്നീട് അത് ഊരുകയും ചെയ്തു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 819, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا تُوُفِّيَ أَحَدُكُمْ فَوَجَدَ شَيْئًا فَلْيُكَفَّنْ فِي ثَوْبِ حِبَرَةٍ". (د)', 'പ്രവാചകൻ(സ) പറയുന്നത് കേട്ടതായി ജാബിർ(റ): "നിങ്ങളിൽ ആരെങ്കിലും മരിച്ചാൽ (കഫൻ ചെയ്യാൻവേണ്ടി) വല്ലതും ലഭിക്കുകയാണെങ്കിൽ അയാളെ പരുത്തി വസ്ത്രത്തിൽ കഫൻ ചെയ്യുക." (ദ)', 'جَابِرٍ', 'പ്രവാചകൻ(സ) പറയുന്നത് കേട്ടതായി ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 819, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُفِّنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي ثَلَاثَةِ أَثْوَابٍ يَمَانِيَةٍ بِيضٍ، لَيْسَ فِيهَا قَمِيصٌ وَلَا عِمَامَةٌ. وَفِي رِوَايَةٍ: مِنْ كُرْسُفٍ. قَالَ: فَذُكِرَ لِعَائِشَةَ قَوْلُهُمْ: فِي ثَوْبَيْنِ وَبُرْدِ حِبَرَةٍ، فَقَالَتْ: قَدْ أُتِيَ بِالْبُرْدِ، وَلَكِنَّهُمْ رَدُّوهُ، وَلَمْ يُكَفِّنُوهُ فِيهِ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): യമനിലെ മൂന്ന് വെളുത്ത വസ്ത്രത്തിലാണ് നബി(സ) കഫൻ ചെയ്യപ്പെട്ടത്. അതിൽ കുപ്പായവും തലപ്പാവും ഉണ്ടായിരുന്നില്ല. മറ്റൊരു റിപ്പോർട്ടിൽ: പരുത്തി വസ്ത്രത്തിലാണ് (കഫൻചെയ്യപ്പെട്ടത്). രണ്ടു വസ്ത്രവും ഒരു പരുത്തി വസ്ത്രത്തിലുമാണ് കഫൻ ചെയ്തതെന്ന ചിലരുടെ പരാമർശം ആയിശ(റ)യോട് പറയപ്പെട്ടപ്പോൾ അവർ ഇങ്ങനെ പ്രതികരിച്ചു: പരുത്തി വസ്ത്രം കൊണ്ടുവന്നത് ശരിയാണ്. എന്നാൽ അവർ അത് മടക്കുകയാണുണ്ടായത്. അതിൽ നബി(സ) കഫൻ ചെയ്യപ്പെട്ടിട്ടില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 820, 820, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=216), 1, 'وَفِي رِوَايَةٍ: مِنْ كُرْسُفٍ. قَالَ: فَذُكِرَ لِعَائِشَةَ قَوْلُهُمْ: فِي ثَوْبَيْنِ وَبُرْدِ حِبَرَةٍ، فَقَالَتْ: قَدْ أُتِيَ بِالْبُرْدِ، وَلَكِنَّهُمْ رَدُّوهُ، وَلَمْ يُكَفِّنُوهُ فِيهِ. (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: പരുത്തി വസ്ത്രത്തിലാണ് (കഫൻചെയ്യപ്പെട്ടത്). രണ്ടു വസ്ത്രവും ഒരു പരുത്തി വസ്ത്രത്തിലുമാണ് കഫൻ ചെയ്തതെന്ന ചിലരുടെ പരാമർശം ആയിശ(റ)യോട് പറയപ്പെട്ടപ്പോൾ അവർ ഇങ്ങനെ പ്രതികരിച്ചു: പരുത്തി വസ്ത്രം കൊണ്ടുവന്നത് ശരിയാണ്. എന്നാൽ അവർ അത് മടക്കുകയാണുണ്ടായത്. അതിൽ നബി(സ) കഫൻ ചെയ്യപ്പെട്ടിട്ടില്ല. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُفِّنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي ثَلَاثَةِ أَثْوَابٍ نَجْرَانِيَّةٍ: الْحُلَّةُ ثَوْبَانِ – وَفِي رِوَايَةٍ: حُلَّةٌ حَمْرَاءُ – وَقَمِيصُهُ الَّذِي مَاتَ فِيهِ. (د,جه)', 'ഇബനുഅബ്ബാസ്(റ): നജ്റാനിലെ മൂന്ന് വസ്ത്രങ്ങളിലാണ് പ്രവാചകൻ(സ) കഫൻ ചെയ്യപ്പെട്ടത്. രണ്ട് ചുവന്ന വസ്ത്രങ്ങളും വഫാതാകുമ്പോൾ ഉണ്ടായിരുന്ന കുപ്പായവുമാണവ. (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബനുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 820, 820, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=217), 1, 'وَفِي رِوَايَةٍ: حُلَّةٌ حَمْرَاءُ – وَقَمِيصُهُ الَّذِي مَاتَ فِيهِ. (د,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُفِّنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي ثَلَاثَةِ أَثْوَابٍ: قَمِيصُهُ الَّذِي قُبِضَ فِيهِ، وَحُلَّةٌ نَجْرَانِيَّةٌ. [ز: في سنده راو ضعيف] (د,جه)', 'ഇബനുഅബ്ബാസ്(റ): റസൂൽ(സ) കഫൻ ചെയ്യപ്പെട്ടത് മൂന്ന് വസ്ത്രങ്ങളിലാണ്. വഫാതാകുമ്പോൾ ഉണ്ടായിരുന്ന കുപ്പായത്തിലും നജ്റാനിൽ നിന്നുള്ള സെറ്റ്വസ്ത്രത്തിലുമാണ്. (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനായ റിപ്പോർട്ടർ ഉണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബനുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], 'ز: في سنده راو ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനായ റിപ്പോർട്ടർ ഉണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 820, 820, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ أُمِّ الْعَلَاءِ امْرَأَةٍ مِنَ الْأَنْصَارِ رَضِيَ اللهُ عَنْهَا، وَهِيَ مِمَّنْ بَايَعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: إِنَّهُ اقْتُسِمَ الْمُهَاجِرُونَ قُرْعَةً فَطَارَ لَنَا عُثْمَانُ بْنُ مَظْعُونٍ، فَأَنْزَلْنَاهُ فِي أَبْيَاتِنَا فَوَجِعَ وَجَعَهُ الَّذِي تُوُفِّيَ فِيهِ، فَلَمَّا تُوُفِّيَ وَغُسِّلَ وَكُفِّنَ فِي أَثْوَابِهِ، دَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: رَحْمَةُ اللهِ عَلَيْكَ أَبَا السَّائِبِ فَشَهَادَتِي عَلَيْكَ لَقَدْ أَكْرَمَكَ اللهُ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَمَا يُدْرِيكِ أَنَّ اللهَ أَكْرَمَهُ". فَقُلْتُ: بِأَبِي أَنْتَ يَا رَسُولَ اللهِ فَمَنْ يُكْرِمُهُ اللهُ، فَقَالَ: "أَمَّا هُوَ فَقَدْ جَاءَهُ الْيَقِينُ وَاللهِ إِنِّي لَأَرْجُو لَهُ الْخَيْرَ، وَاللهِ مَا أَدْرِي وَأَنَا رَسُولُ اللهِ مَا يُفْعَلُ بِي". قَالَتْ: فَوَاللهِ لَا أُزَكِّي أَحَدًا بَعْدَهُ أَبَدًا. (خ)', 'അൻസ്വാരി സ്ത്രീകളിൽപെട്ട ഉമ്മുൽ അലാഅ്(റ): അവർ പ്രവാചക(സ)ന്റെ കൂടെ ഉടമ്പടി ചെയ്തവരാണ്. അവർ പറയുന്നു: മക്കയിൽ നിന്ന് ഹിജ്റ വന്നവർക്ക് നറുക്കെടുപ്പിലൂടെ വിഹിതം നൽകപ്പെട്ടു. അങ്ങനെ ഉസ്മാൻ ഇബ്നുമള്ഊൻ ഞങ്ങളിലേക്ക് വന്നു. അദ്ദേഹത്തെ ഞങ്ങളുടെ വീടുകളിൽ പാർപ്പിച്ചു. ഉടനെ അദ്ദേഹത്തിന് മരണ വേദന തുടങ്ങി. അദ്ദേഹം മരിച്ച് കുളിപ്പിക്കപ്പെടുകയും വസ്ത്രങ്ങളിൽ കഫൻ ചെയ്യപ്പെടുകയും ചെയ്തു കഴിഞ്ഞപ്പോൾ പ്രവാചകൻ(സ) അങ്ങോട്ട് കടന്നുവന്നു. അപ്പോൾ ഞാൻ പറഞ്ഞു: അബുസാഇബ്, അല്ലാഹുവിന്റെ കാരുണ്യം നിങ്ങൾക്ക് ഉണ്ടാവട്ടെ. നിങ്ങളെ അല്ലാഹു ആദരിച്ചിരിക്കുന്നുവെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "അല്ലാഹു അദ്ദേഹത്തെ ആദരിച്ചത് നിനക്ക് എങ്ങനെ അറിയാനാകും?" ഞാൻ പറഞ്ഞു: താങ്കൾക്ക് എന്റെ പിതാവിനെ കൊണ്ട് ബലി, പ്രവാചകരെ (താങ്കളെ കൂടാതെ മറ്റ്) ആരെയാണ് അല്ലാഹു ആദരിക്കുക!. പ്രവാചകൻ(സ) പറഞ്ഞു. "അദ്ദേഹത്തിന് മരണം സംഭവിച്ചു. അല്ലാഹുവാണെ, ഞാൻ അദ്ദേഹത്തിന് നന്മ പ്രതീക്ഷിക്കുന്നു. അല്ലാഹുവാണെ, പ്രവാചകനായ എന്നെപോലും അല്ലാഹു എന്താണ് ചെയ്യുകയെന്ന് എനിക്ക് അറിയില്ല." മഹതി പറയുന്നു: അതിന് ശേഷം ഒരിക്കലും ഞാൻ ആരെയും അപ്രകാരം പ്രശംസ നടത്താറില്ല. (ബു)', 'أُمِّ الْعَلَاءِ امْرَأَةٍ مِنَ الْأَنْصَارِ', 'അൻസ്വാരി സ്ത്രീകളിൽപെട്ട ഉമ്മുൽ അലാഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 820, 820, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا مَاتَ عَبْدُ اللهِ بْنُ أُبَيٍّ جَاءَ ابْنُهُ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: اعْطِنِي قَمِيصَكَ حَتَّى أُكَفِّنَهُ فِيهِ، وَصَلِّ عَلَيْهِ، وَاسْتَغْفِرْ لَهُ. فَأَعْطَاهُ قَمِيصَهُ، ثُمَّ قَالَ: "إِذَا فَرَغْتُمْ فَآذِنُونِي أُصَلِّي عَلَيْهِ". فَجَذَبَهُ عُمَرُ وَقَالَ: قَدْ نَهَاكَ اللهُ أَنْ تُصَلِّيَ عَلَى الْمُنَافِقِينَ. فَقَالَ: "أَنَا بَيْنَ خِيَرَتَيْنِ". قَالَ: {اسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ} [التوبة: ٨٠]. فَصَلَّى عَلَيْهِ، فَأَنْزَلَ اللهُ تَعَالَى {وَلَا تُصَلِّ عَلَى أَحَدٍ مِنْهُمْ مَاتَ أَبَدًا وَلَا تَقُمْ عَلَى قَبْرِهِ} [التوبة: ٨٤] فَتَرَكَ الصَّلَاةَ عَلَيْهِمْ. (ق,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): അബ്ദുല്ലാഹിബ്നു ഉബയ്യ് മരണപ്പെട്ടപ്പോൾ അദ്ദേഹത്തിന്റെ മകൻ പ്രവാചക(സ)നെ സമീപിച്ചുകൊണ്ട് ഇങ്ങനെ പറഞ്ഞു: താങ്കളുടെ കുപ്പായം നൽകിയാലും. പിതാവിനെ അതിൽ കഫൻ ചെയ്യാനാണ്. താങ്കൾ അദ്ദേഹത്തിന് നിസ്കരിക്കണം, പാപമോചനം തേടണം. പ്രവാചകൻ(സ) തന്റെ കുപ്പായം നൽകിയിട്ട് പറഞ്ഞു: "കുളിപ്പിച്ച് കഴിഞ്ഞാൽ എന്നെ വിവരം അറിയിക്കുക. ഞാൻ അദ്ദേഹത്തിന് നിസ്കരിക്കുന്നതാണ്." അപ്പോൾ പ്രവാചക(സ)നെ വലിച്ചുകൊണ്ട് ഉമർ(റ) പറഞ്ഞു. കപടവിശ്വാസികൾക്ക് വേണ്ടി നിസ്കരിക്കുന്നത് അല്ലാഹു താങ്കൾക്ക് വിലക്കിയിട്ടില്ലേ? പ്രവാചകൻ(സ) പറഞ്ഞു: "എനിക്ക് രണ്ടും ചെയ്യാൻ സ്വാതന്ത്ര്യമുണ്ട്." തുടർന്ന് ''താങ്കൾ അവർക്ക് വേണ്ടി പാപമോചനം തേടുക. അല്ലെങ്കിൽ അവർക്ക് പാപമോചനം തേടാതിരിക്കുക''. (തൗബ: 80) എന്ന സൂക്തം എടുത്തുപറഞ്ഞു. അദ്ദേഹത്തിന് വേണ്ടി നബി(സ) നിസ്കരിച്ചു. അപ്പോൾ ''അവരിൽനിന്നും മരിച്ച ഒരാൾക്കും താങ്കൾ നിസ്കരിക്കരുത്. ശ്മശാനത്തിൽ നിൽക്കുകയും അരുത്'' (തൗബ: 84) എന്ന സൂക്തം അല്ലാഹു അവതരിപ്പിച്ചു. പിന്നീട് അവർക്ക് വേണ്ടിയുള്ള നിസ്കാരം ഉപേക്ഷിച്ചു. (ബു,മു,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], 'التوبة: ٨٤', null, 821, 821, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنْ سَهْلٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَتِ امْرَأَةٌ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِبُرْدَةٍ مَنْسُوجَةٍ فِيهَا حَاشِيَتُهَا، أَتَدْرُونَ مَا الْبُرْدَةُ؟ قَالُوا: الشَّمْلَةُ، قَالَ: نَعَمْ، قَالَتْ: نَسَجْتُهَا بِيَدِي فَجِئْتُ لِأَكْسُوَكَهَا فَأَخَذَهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُحْتَاجًا إِلَيْهَا، فَخَرَجَ إِلَيْنَا، وَإِنَّهَا إِزَارُهُ، فَحَسَّنَهَا فُلَانٌ فَقَالَ: اكْسُنِيهَا مَا أَحْسَنَهَا! فَقَالَ الْقَوْمُ: مَا أَحْسَنْتَ، لَبِسَهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُحْتَاجًا إِلَيْهَا، ثُمَّ سَأَلْتَهُ وَعَلِمْتَ أَنَّهُ لَا يَرُدُّ، فَقَالَ: إِنِّي وَاللهِ مَا سَأَلْتُهُ لِأَلْبَسَهَا، إِنَّمَا سَأَلْتُهُ لِتَكُونَ كَفَنِي، قَالَ سَهْلٌ: فَكَانَتْ كَفَنَهُ. (خ)', 'സഹ്ൽ(റ): അരികുകൾ മെടഞ്ഞ് നെയ്തുണ്ടാക്കിയ ഒരു പുടവയുമായി പ്രവാചകന്റെ അടുക്കൽ ഒരു സ്ത്രീ വന്നു ബുർദത് എന്നാൽ എന്താണെന്നറിയുമോ എന്ന് നിവേദകൻ (സദസ്യരോട്) ചോദിച്ചപ്പോൾ അവർ പറഞ്ഞു: അത് ശംലത്(പുടവ) ആണ്. അദ്ദേഹം പറഞ്ഞു: അതെ. അങ്ങനെ ആ സ്ത്രീ പറഞ്ഞു: ഇത് തിരുമേനി(സ)യെ ഉടുപ്പിക്കുവാൻ വേണ്ടി ഞാൻ എന്റെ കൈകൊണ്ട് നെയ്ത് കൊണ്ടുവന്നതാണ്. അപ്പോൾ പ്രവാചകൻ(സ) താൽപര്യപൂർവ്വം അത് സ്വീകരിച്ചു. അങ്ങനെ അത് ഉടുത്തു കൊണ്ട് പ്രവാചകൻ(സ) ഞങ്ങളുടെ അടുത്തേക്ക് വന്നു. ഒരാൾ അതിനെ മനോഹരമായെന്ന് വർണ്ണിച്ചു. അദ്ദേഹം പറഞ്ഞു: അത് എന്നെ ഉടുപ്പിക്കുക. ഹാ എത്ര മനോഹരം. ആളുകൾ പറഞ്ഞു: പ്രവാചകൻ(സ) താൽപര്യപൂർവ്വം അത് അണിഞ്ഞിരിക്കെ നീ ചോദിച്ചത് ശരിയായില്ല. ചോദിച്ചവരെ അവിടുന്ന് മടക്കിയിരുന്നില്ല എന്ന് നിനക്ക് അറിഞ്ഞുകൂടെ. അപ്പോൾ അയാൾ പറഞ്ഞു. അല്ലാഹുവാണ്, ഞാനത് എനിക്ക് അണിയാൻ വേണ്ടി ചോദിച്ചതല്ല. എന്റെ കഫൻ പുടവയാക്കാൻ ചോദിച്ചതാണ്. റിപ്പോർട്ടർ സഹ്ൽ പറയുന്നു: പിന്നീട് അതായിരുന്നു അദ്ദേഹത്തിന്റെ കഫൻ പുടവ ആയത്. (ബു)', 'سَهْلٍ', 'സഹ്ൽ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 821, 821, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنْ لَيْلَى بِنْتِ قَانِفٍ الثَّقَفِيَّةِ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ فِيمَنْ غَسَّلَ أُمَّ كُلْثُومٍ بِنْتَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عِنْدَ وَفَاتِهَا، فَكَانَ أَوَّلُ مَا أَعْطَانَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْحِقَاءَ، ثُمَّ الدِّرْعَ، ثُمَّ الْخِمَارَ، ثُمَّ الْمِلْحَفَةَ، ثُمَّ أُدْرِجَتْ بَعْدُ فِي الثَّوْبِ الْآخَرِ، قَالَتْ: وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ عِنْدَ الْبَابِ، مَعَهُ كَفَنُهَا يُنَاوِلُنَاهَا ثَوْبًا ثَوْبًا. (د)', 'ലൈല ബിൻത് ഖാനിഫ് സഖഫിയ്യ(റ): പ്രവാചക(സ)ന്റെ മകൾ ഉമ്മുകുൽസും(റ) മരണപ്പെട്ടപ്പോൾ അവളെ കുളിപ്പിച്ചവരിൽ ഞാനും ഉണ്ടായിരുന്നു. പ്രവാചകൻ(സ) ആദ്യമായി ഞങ്ങൾക്ക് അരക്കച്ച പിന്നെ കുപ്പായം പിന്നെ മക്കനെ പിന്നീട് ആകെ മൂടുന്ന പുടവ എന്നിങ്ങനെയാണ് നൽകിയത്. പിന്നെ അവ മറ്റൊരു വസ്ത്രത്തിൽ പൊതിഞ്ഞു. അവർ പറയുന്നു: തിരുമേനി(സ) വാതിലിനു സമീപം ഉണ്ടായിരുന്നു. നബി(സ)യുടെ കൂടെയാണ് കഫൻചെയ്യൽ നിർവ്വഹിച്ചത്. അവളുടെ ഒരോ വസ്ത്രവും നബി(സ) എടുത്തു തരികയായിരുന്നു. (ദ)', 'لَيْلَى بِنْتِ قَانِفٍ الثَّقَفِيَّةِ', 'ലൈല ബിൻത് ഖാനിഫ് സഖഫിയ്യ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 821, 822, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَا تُغَالِ لِي فِي كَفَنٍ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَغَالَوْا فِي الْكَفَنِ، فَإِنَّهُ يُسْلَبُهُ سَلْبًا سَرِيعًا". (د)', 'അലി(റ): എന്റെ കഫൻ പുടവയിൽ നിങ്ങൾ അമിതത്വം കാണിക്കരുത്. പ്രവാചകൻ(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട് : "നിങ്ങൾ കഫൻ പുടവയിൽ ധാരാളിത്വം കാണിക്കരുത്. കാരണം, അത് വേഗം ദ്രവിച്ച് പോകുന്നതാണ്." (ദ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 822, 822, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنْ خَبَّابٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ مُصْعَبَ بْنَ عُمَيْرٍ قُتِلَ يَوْمَ أُحُدٍ وَلَمْ يَكُنْ لَهُ إِلَّا نَمِرَةٌ، كُنَّا إِذَا غَطَّيْنَا بِهَا رَأْسَهُ خَرَجَ رِجْلَاهُ، وَإِذَا غَطَّيْنَا رِجْلَيْهِ خَرَجَ رَأْسُهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "غَطُّوا بِهَا رَأْسَهُ، وَاجْعَلُوا عَلَى رِجْلَيْهِ شَيْئًا مِنَ الْإِذْخِرِ". (ق,د,ت,ن)', 'ഖബാബ്(റ): മിസ്അബുബ്നു ഉമൈർ(റ) ഉഹ്ദ് യദ്ധത്തിൽ വധിക്കപ്പെട്ടു. അദ്ദേഹത്തിന് ഒരു കരിമ്പടം മാത്രമേ ഉണ്ടായിരുന്നുള്ളൂ. അത് കൊണ്ട് ഞങ്ങൾ അദ്ദേഹത്തിന്റെ തല മൂടുമ്പോൾ കാലുകളും കാലുകൾ മൂടുമ്പോൾ തലയും പുറത്താകുമായിരുന്നു. പ്രവാചകൻ(സ) പറഞ്ഞു: "അത്കൊണ്ട് നിങ്ങൾ അദ്ദേഹത്തിന്റെ തല മൂടുക. കാലുകളിൽ പുല്ല് വെക്കുക." (ബു,മു,ദ,തു,ന)', 'خَبَّابٍ', 'ഖബാബ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 822, 822, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خَيْرُ الْكَفَنِ الْحُلَّةُ، وَخَيْرُ الْأُضْحِيَّةِ الْكَبْشُ الْأَقْرَنُ". (د,جه)', 'ഉബാദത്ത് ഇബ്നുസ്വാമിത്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "കഫൻ പുടവകളിൽ ഉത്തമം പൂർണ്ണമായ കഫൻ പുടവയും ഉള്ഹിയത്തിൽ ഏറ്റവും ഉത്തമം കൊമ്പുള്ള ആടുമാകുന്നു." (ദ,ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദത്ത് ഇബ്നുസ്വാമിത്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 822, 822, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اغْسِلُوا الْمُحْرِمَ فِي ثَوْبَيْهِ اللَّذَيْنِ أَحْرَمَ فِيهِمَا، وَاغْسِلُوهُ بِمَاءٍ وَسِدْرٍ، وَكَفِّنُوهُ فِي ثَوْبَيْهِ، وَلَا تُمِسُّوهُ بِطِيبٍ، وَلَا تُخَمِّرُوا رَأْسَهُ، فَإِنَّهُ يُبْعَثُ يَوْمَ الْقِيَامَةِ مُحْرِمًا". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഹജ്ജിൽ പ്രവേശിച്ചവൻ മരിച്ചാൽ ഇഹ്റാം കെട്ടുമ്പോഴുള്ള രണ്ട് വസ്ത്രങ്ങളിൽ കുളിപ്പിക്കുക. താളി ഉപയോഗിച്ച് കുളിപ്പിക്കുക. അവന് സുഗന്ധം പുരട്ടുകയോ തല മറക്കുകയോ അരുത്. കാരണം അവൻ പരലോകത്ത് ഹജ്ജ് ചെയ്യുന്നവനായി പുനർജീവിപ്പിക്കപ്പെടും." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 822, 822, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِرَجُلٍ وَقَصَتْهُ رَاحِلَتُهُ، فَمَاتَ وَهُوَ مُحْرِمٌ، فَقَالَ: "كَفِّنُوهُ فِي ثَوْبَيْهِ – وَفِي رِوَايَةٍ: فِي ثَوْبَيْنِ – وَاغْسِلُوهُ بِمَاءٍ وَسِدْرٍ، وَلَا تُخَمِّرُوا رَأْسَهُ – وَفِي رِوَايَةٍ – وَلَا تُحَنِّطُوهُ، فَإِنَّ اللهَ يَبْعَثُهُ يَوْمَ الْقِيَامَةِ يُلَبِّي". وَفِي رِوَايَةٍ قَالَ: وَقَصَتْ بِرَجُلٍ نَاقَتُهُ فَقَتَلَتْهُ، فَأُتِيَ بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "اغْسِلُوهُ وَكَفِّنُوهُ، وَلَا تُغَطُّوا رَأْسَهُ، وَلَا تُقَرِّبُوهُ طِيبًا، فَإِنَّهُ يُبْعَثُ يُهِلُّ". (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): വാഹനത്തിൽനിന്നും വീണ് കഴുത്ത് പൊട്ടിയ ഒരാളെ നബി(സ)യുടെ അടുത്ത് കൊണ്ടു വന്നു. അദ്ദേഹം ഇഹ്റാമിലായ അവസ്ഥയിൽ തന്നെ മരണമടയുകയും ചെയ്തു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അദ്ദേഹത്തെ അദ്ദേഹത്തിന്റെ രണ്ട് വസ്ത്രങ്ങളിൽ പൊതിയുക. മറ്റൊരു റിപ്പോർട്ടിൽ: രണ്ട് വസ്ത്രങ്ങളിൽ എന്നാണ്. അദ്ദേഹത്തെ വെള്ളം കൊണ്ടും താളി കൊണ്ടും കുളിപ്പിക്കുകയും ചെയ്യുക, തല മൂടരുത്. മറ്റൊരു റിപ്പോർട്ടിൽ നിങ്ങൾ അദ്ദേഹത്തെ സുഗന്ധം പുരട്ടരുത്. തൽബിയത്ത് ചെല്ലുന്നവനായികൊണ്ട് അദ്ദേഹത്തെ അല്ലാഹു അന്ത്യനാളിൽ ജീവിപ്പിക്കും." മറ്റൊരു റിപ്പോർട്ടിൽ ഇങ്ങനെയാണ്: ഒരാളെ തന്റെ ഒട്ടകം തള്ളിയിട്ടു കഴുത്തൊടിച്ചു. അദ്ദേഹം മരണപ്പെട്ടു. അദ്ദേഹത്തെ നബി(സ)യുടെ അടുത്ത് കൊണ്ടുവന്നു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അദ്ദേഹത്തെ കുളിപ്പിക്കുകയും കഫൻ ചെയ്യുകയും ചെയ്യുക. അദ്ദേഹത്തിന്റെ തല മൂടരുത്, സുഗന്ധം പൂശരുത്, അദ്ദേഹം അന്ത്യനാളിൽ തഹ്ലീൽ ചൊല്ലി പുനർജീവിപ്പിക്കപ്പെടും." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 823, 823, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=227), 1, 'وَفِي رِوَايَةٍ: فِي ثَوْبَيْنِ – وَاغْسِلُوهُ بِمَاءٍ وَسِدْرٍ، وَلَا تُخَمِّرُوا رَأْسَهُ –', 'മറ്റൊരു നിവേദനിൽ: രണ്ട് വസ്ത്രങ്ങളിൽ എന്നാണ്. അദ്ദേഹത്തെ വെള്ളം കൊണ്ടും താളി കൊണ്ടും കുളിപ്പിക്കുകയും ചെയ്യുക, തല മൂടരുത്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=227), 2, 'وَفِي رِوَايَةٍ – وَلَا تُحَنِّطُوهُ، فَإِنَّ اللهَ يَبْعَثُهُ يَوْمَ الْقِيَامَةِ يُلَبِّي".', 'മറ്റൊരു നിവേദനിൽ നിങ്ങൾ അദ്ദേഹത്തെ സുഗന്ധം പുരട്ടരുത്. തൽബിയത്ത് ചെല്ലുന്നവനായികൊണ്ട് അദ്ദേഹത്തെ അല്ലാഹു അന്ത്യനാളിൽ ജീവിപ്പിക്കും."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=227), 3, 'وَفِي رِوَايَةٍ قَالَ: وَقَصَتْ بِرَجُلٍ نَاقَتُهُ فَقَتَلَتْهُ، فَأُتِيَ بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "اغْسِلُوهُ وَكَفِّنُوهُ، وَلَا تُغَطُّوا رَأْسَهُ، وَلَا تُقَرِّبُوهُ طِيبًا، فَإِنَّهُ يُبْعَثُ يُهِلُّ". (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ ഇങ്ങനെയാണ്: ഒരാളെ തന്റെ ഒട്ടകം തള്ളിയിട്ടു കഴുത്തൊടിച്ചു. അദ്ദേഹം മരണപ്പെട്ടു. അദ്ദേഹത്തെ നബി(സ)യുടെ അടുത്ത് കൊണ്ടുവന്നു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അദ്ദേഹത്തെ കുളിപ്പിക്കുകയും കഫൻ ചെയ്യുകയും ചെയ്യുക. അദ്ദേഹത്തിന്റെ തല മൂടരുത്, സുഗന്ധം പൂശരുത്, അദ്ദേഹം അന്ത്യനാളിൽ തഹ്ലീൽ ചൊല്ലി പുനർജീവിപ്പിക്കപ്പെടും." (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْبَسُوا مِنْ ثِيَابِكُمُ الْبَيَاضَ، فَإِنَّهَا مِنْ خَيْرِ ثِيَابِكُمْ، وَكَفِّنُوا فِيهَا مَوْتَاكُمْ". حَسَنٌ صَحِيحٌ. (د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങൾ വെളുത്ത വസ്ത്രം ധരിക്കുക. അതാണ് ഉത്തമ മായ വസ്ത്രം. അതിൽതന്നെ നിങ്ങൾനിന്ന് മരണപ്പെട്ടവരെ കഫൻ ചെയ്യുക." (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 823, 823, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا وَلِيَ أَحَدُكُمْ أَخَاهُ فَلْيُحْسِنْ كَفَنَهُ". حَسَنٌ. (ت,جه)', 'അബൂഖതാദ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "വല്ലവനും തന്റെ സഹോദരന്റെ ഉത്തരവാദിത്വം ഏറ്റെടുക്കുന്ന പക്ഷം അദ്ദേഹത്തിന്റെ കഫൻ പുടവ മെച്ചമാക്കിക്കൊള്ളട്ടെ." (ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു) (തു,ജ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 823, 823, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 230, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْبَسُوا مِنْ ثِيَابِكُمُ الْبَيَاضَ، فَإِنَّهَا أَطْهَرُ وَأَطْيَبُ، وَكَفِّنُوا فِيهَا مَوْتَاكُمْ". (ن)', 'സമുറത് ഇബ്നുജുൻദുബ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ വസ്ത്രങ്ങളിൽ നിന്ന് വെള്ള വസ്ത്രം ധരിക്കുക, അത് പരിശുദ്ധവും ഉത്തമവുമാകുന്നു. അതിൽ തന്നെ പരേതരെ കഫൻ ചെയ്യുക." (ന)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറത് ഇബ്നുജുൻദുബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 823, 823, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 231, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا قُبِضَ إِبْرَاهِيمُ – ابْنُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – قَالَ لَهُمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُدْرِجُوهُ فِي أَكْفَانِهِ حَتَّى أَنْظُرَ إِلَيْهِ. فَأَتَاهُ فَانْكَبَّ عَلَيْهِ وَبَكَى". [ز: في إسناده ضعيف] (جه)', 'അനസ് ഇബ്നുമാലിക്(റ): തിരുമേനി(സ)യുടെ മകൻ ഇബ്രാഹിം മരണപ്പെട്ടപ്പോൾ പ്രവാചകൻ(സ) ഇങ്ങനെ പറഞ്ഞു. "ഞാൻ ഒന്ന് കാണുന്നതിന്റെ മുമ്പ് നിങ്ങൾ അവനെ കഫൻ പുടവയിൽ ആവരണം ചെയ്യരുത്." ശേഷം പ്രവാചകൻ(സ) അങ്ങോട്ട് ചെന്നിട്ട് അവന്റെ മേൽ മുഖം കുത്തി വീഴുകയും കരയുകയും ചെയ്തു. (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ് ഇബ്നുമാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 824, 824, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 232, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كَسْرُ عَظْمِ الْمَيِّتِ كَكَسْرِهِ حَيًّا". (د,جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "മയ്യിത്തിന്റെ എല്ല് പൊട്ടിക്കൽ ജീവനുള്ളതിന്റെ എല്ല് പൊട്ടിക്കും പോലെയാണ്." (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 824, 824, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 233, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كَسْرُ عَظْمِ الْمَيِّتِ كَكَسْرِ عَظْمِ الْحَيِّ فِي الْإِثْمِ". [في إسناده مجهول] (جه)', 'ഉമ്മുസലമ(റ): നബി(സ) പറഞ്ഞു: "മയ്യിത്തിന്റെ എല്ല് പൊട്ടിക്കുന്നതും ജീവനുള്ളതിന്റെ എല്ല് പൊട്ടിക്കുന്നതും പാപത്തിൽ ഒരു പോലെയാണ്." (ഇതിന്റെ പരമ്പരയിൽ അജ്ഞാതനായ ഒരു റിപ്പോർട്ടറുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في إسناده مجهول', null, 824, 824, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 234, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِنَّ عَمَّكَ الشَّيْخَ الضَّالَّ قَدْ مَاتَ، قَالَ: "اذْهَبْ فَوَارِ أَبَاكَ، ثُمَّ لَا تُحْدِثَنَّ شَيْئًا حَتَّى تَأْتِيَنِي". فَذَهَبْتُ فَوَارَيْتُهُ، وَجِئْتُهُ، فَأَمَرَنِي فَاغْتَسَلْتُ، وَدَعَا لِي. (د,ن)', 'അലി(റ): ഞാൻ നബി(സ)യോട് പറഞ്ഞു: താങ്കളുടെ വൃദ്ധനായ വഴികേടിലായ പിതൃവ്യൻ മരിച്ചിരിക്കുന്നു. നബി(സ) പറഞ്ഞു: "നീ പോയി പിതാവിനെ മറമാടുക. നീ പിന്നെ എന്റെ അടുത്ത് വരും വരെ നീ ഒന്നും ചെയ്യരുത്." ഞാൻ പോയി മറമാടി. ശേഷം നബി(സ)യുടെ അടുത്ത് വന്നു. നബി(സ)യുടെ കൽപന പ്രകാരം ഞാൻ കുളിച്ചു. എനിക്ക് വേണ്ടി നബി(സ) പ്രാർത്ഥിച്ചു. (ദ,ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 824, 824, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 235, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: رُمِيَ رَجُلٌ بِسَهْمٍ فِي صَدْرِهِ، أَوْ فِي حَلْقِهِ، فَمَاتَ، فَأُدْرِجَ فِي ثِيَابِهِ كَمَا هُوَ، قَالَ: وَنَحْنُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'ജാബിർ(റ): നെഞ്ചിൽ അമ്പ് കൊണ്ടിട്ട് (അല്ലെങ്കിൽ അദ്ദേഹത്തിന്റെ തൊണ്ടക്കുഴിയിൽ) ഒരാൾ മരിച്ചു. അദ്ദേഹത്തെ ആ സ്ഥിതിയിൽ തന്നെ തന്റെ വസ്ത്രത്തിനുള്ളിൽ പൊതിഞ്ഞു. അപ്പോൾ ഞങ്ങൾ റസൂലി(സ)ന്റെ കൂടെയായിരുന്നു. (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 824, 825, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 236, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَمَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِقَتْلَى أُحُدٍ أَنْ يُنْزَعَ عَنْهُمُ الْحَدِيدُ وَالْجُلُودُ، وَأَنْ يُدْفَنُوا بِدِمَائِهِمْ وَثِيَابِهِمْ. (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഉഹ്ദിൽ മരിച്ചവരുടെ ശരീരത്തിൽ നിന്ന് ഇരുമ്പുകളും തോലുകളും നീക്കി അവർ ധരിച്ച അതേ വസ്ത്രത്തിൽ രക്തത്തോടെ മറവുചെയ്യാൻ നബി(സ) കൽപിച്ചു. (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 825, 825, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 237, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ شُهَدَاءَ أُحُدٍ لَمْ يُغَسَّلُوا، وَدُفِنُوا بِدِمَائِهِمْ، وَلَمْ يُصَلَّ عَلَيْهِمْ. (د)', 'അനസ്(റ): ഉഹ്ദിലെ ശുഹദാക്കൾ കുളിപ്പിക്കപ്പെട്ടില്ല. അവരെ രക്തത്തോടൊപ്പം മറവുചെയ്തു. അവർക്കു വേണ്ടി നിസ്കരിച്ചിട്ടില്ല. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 825, 825, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 238, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِحَمْزَةَ وَقَدْ مُثِّلَ بِهِ، وَلَمْ يُصَلِّ عَلَى أَحَدٍ مِنَ الشُّهَدَاءِ غَيْرِهِ. (د)', 'അനസ്(റ): നബി(സ) ഹംസ(റ)യുടെ അടുത്തുകൂടെ നടന്നു. അദ്ദേഹം അംഗവിഛേദനം ചെയ്യപ്പെട്ടിരുന്നു. രക്തസാക്ഷികളിൽ അദ്ദേഹമല്ലാത്ത ഒരാൾക്കും നബി(സ) നിസ്കരിച്ചിട്ടില്ല. (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 825, 825, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 239, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَجْمَعُ بَيْنَ الرَّجُلَيْنِ مِنْ قَتْلَى أُحُدٍ – وَفِي رِوَايَةٍ: فِي ثَوْبٍ وَاحِدٍ – يَقُولُ: "أَيُّهُمَا أَكْثَرُ أَخْذًا لِلْقُرْآنِ". فَإِذَا أُشِيرَ لَهُ إِلَى أَحَدِهِمَا قَدَّمَهُ فِي اللَّحْدِ، وَقَالَ: "أَنَا شَهِيدٌ عَلَى هَؤُلَاءِ يَوْمَ الْقِيَامَةِ". وَأَمَرَ بِدَفْنِهِمْ بِدِمَائِهِمْ، وَلَمْ يُغَسَّلُوا. (خ,د,ت,جه)', 'ജാബിർ(റ): ഉഹ്ദിൽ മരിച്ച രണ്ടാളുകളെ പ്രവാചകൻ(സ) ഒരുമിച്ചുകൂട്ടിയിരുന്നു (മറ്റൊരു റിപ്പോർട്ടിൽ, ഒരു വസ്ത്രത്തിൽ എന്നുണ്ട്) അവിടുന്ന് ചോദിച്ചു: "ഇവരിൽ ആർക്കാണ് ഏറ്റവും കൂടുതൽ ഖുർആൻ അറിയുന്നത്?" അപ്പോൾ അവരിലൊരാളെക്കുറിച്ച് സൂചന കിട്ടിയാൽ അദ്ദേഹത്തെ ലഹ്ദിൽ ആദ്യം പ്രവേശിപ്പിച്ചിരുന്നു. അവിടുന്ന് പറഞ്ഞു: "അന്ത്യനാളിൽ ഞാൻ ആ കൂട്ടർക്ക് സാക്ഷിയാണ്." അവരുടെ രക്തത്തോടൊപ്പം തന്നെ അവരെ മറമാടാൻ പ്രവാചകൻ(സ) കൽപിച്ചു. അവർ കുളിപ്പിക്കപ്പെട്ടില്ല. (ബു,ദ,തു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിർ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 825, 825, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=239), 1, 'وَفِي رِوَايَةٍ: فِي ثَوْبٍ وَاحِدٍ – يَقُولُ: "أَيُّهُمَا أَكْثَرُ أَخْذًا لِلْقُرْآنِ". فَإِذَا أُشِيرَ لَهُ إِلَى أَحَدِهِمَا قَدَّمَهُ فِي اللَّحْدِ، وَقَالَ: "أَنَا شَهِيدٌ عَلَى هَؤُلَاءِ يَوْمَ الْقِيَامَةِ". وَأَمَرَ بِدَفْنِهِمْ بِدِمَائِهِمْ، وَلَمْ يُغَسَّلُوا. (خ,د,ت,جه)', 'മറ്റൊരു നിവേദനിൽ, ഒരു വസ്ത്രത്തിൽ എന്നുണ്ട്) അവിടുന്ന് ചോദിച്ചു: "ഇവരിൽ ആർക്കാണ് ഏറ്റവും കൂടുതൽ ഖുർആൻ അറിയുന്നത്?" അപ്പോൾ അവരിലൊരാളെക്കുറിച്ച് സൂചന കിട്ടിയാൽ അദ്ദേഹത്തെ ലഹ്ദിൽ ആദ്യം പ്രവേശിപ്പിച്ചിരുന്നു. അവിടുന്ന് പറഞ്ഞു: "അന്ത്യനാളിൽ ഞാൻ ആ കൂട്ടർക്ക് സാക്ഷിയാണ്." അവരുടെ രക്തത്തോടൊപ്പം തന്നെ അവരെ മറമാടാൻ പ്രവാചകൻ(സ) കൽപിച്ചു. അവർ കുളിപ്പിക്കപ്പെട്ടില്ല. (ബു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 240, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِسَبْعٍ، وَنَهَانَا عَنْ سَبْعٍ: أَمَرَنَا بِعِيَادَةِ الْمَرِيضِ، وَتَشْمِيتِ الْعَاطِسِ، وَإِبْرَارِ الْقَسَمِ، وَنُصْرَةِ الْمَظْلُومِ، وَإِفْشَاءِ السَّلَامِ، وَإِجَابَةِ الدَّاعِي، وَاتِّبَاعِ الْجَنَائِزِ. وَنَهَانَا عَنْ خَوَاتِيمِ الذَّهَبِ، وَعَنْ آنِيَةِ الْفِضَّةِ، وَعَنِ الْمَيَاثِرِ، وَالْقَسِّيَّةِ، وَالْإِسْتَبْرَقِ، وَالْحَرِيرِ، وَالدِّيبَاجِ. (خ,ن)', 'ബറാഅ് ഇബ്നുആസിബ്(റ): പ്രവാചകൻ(സ) ഞങ്ങളോട് ഏഴ് കാര്യങ്ങൾ കൽപ്പിക്കുകയും ഏഴ് കാര്യങ്ങൾ വിരോധിക്കുകയും ചെയ്തു. രോഗിയെ സന്ദർശിക്കുക, തുമ്മിയവന് അനുഗ്രഹ പ്രാർത്ഥന നടത്തുക, സത്യം പാലിക്കുക, മർദ്ദിതനെ സഹായിക്കുക, സലാം വ്യാപിപ്പിക്കുക, ക്ഷണിച്ചവന്റെ ക്ഷണം സ്വീകരിക്കുക, ജനാസയെ അനുഗമിക്കുക എന്നിവയാണ് ഞങ്ങളോട് കൽപിച്ചത്. വിരോധിച്ചത് സ്വർണ്ണ മോതിരം, വെള്ളിപ്പാത്രം, പട്ടിന്റെ നൂൽ കൊണ്ട് കര പിടിപ്പിച്ച വസ്ത്രം, പരുക്കൻ പട്ട്, പട്ടു കൊണ്ടുണ്ടാക്കുന്ന മിനുസമുള്ള വസ്ത്രം, ദീബാജ് (ഒരിനംപട്ട്) എന്നിവയാണ്. (ബു,ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഅ് ഇബ്നുആസിബ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 825, 825, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 241, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا اتَّبَعَ الْجِنَازَةَ لَمْ يَقْعُدْ حَتَّى تُوضَعَ فِي اللَّحْدِ، فَعَرَضَ لَهُ حَبْرٌ فَقَالَ: هَكَذَا نَصْنَعُ يَا مُحَمَّدُ. قَالَ: فَجَلَسَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "خَالِفُوهُمْ". (د,ت,جه)', 'ഉബാദതുബ്നു സ്വാമിത്ത്(റ): പ്രവാചകൻ(സ) ജനാസയെ അനുഗമിക്കുമ്പോൾ ഖബറിലേക്ക് താഴ്തുന്നത് വരെ ഇരിക്കാറുണ്ടായിരുന്നില്ല. ഒരിക്കൽ ഒരു ക്രിസ്തീയ പുരോഹിതൻ നബി(സ)യോട് പറഞ്ഞു: മുഹമ്മദേ, ഇപ്രകാരമാണ് ഞങ്ങൾ ചെയ്യുന്നത്. റിപ്പോർട്ടർ പറയുന്നു: അപ്പോൾ പ്രവാചകൻ(സ) ഇരുന്നുകൊണ്ട് ഇങ്ങനെ പറഞ്ഞു: "അവരോട് എതിർ കാണിക്കുക." (ദ,തു,ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്ത്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 826, 826, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 242, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَبِعَ جَنَازَةً حَتَّى يُصَلَّى عَلَيْهَا كَانَ لَهُ مِنَ الْأَجْرِ قِيرَاطٌ، وَمَنْ مَشَى مَعَ الْجَنَازَةِ حَتَّى تُدْفَنَ كَانَ لَهُ مِنَ الْأَجْرِ قِيرَاطَانِ، وَالْقِيرَاطُ مِثْلُ أُحُدٍ". (ن)', 'ബാറാഅ് ഇബ്നുആസിബ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഒരാൾ മയ്യിത്തിന് നിസ്കരിക്കുന്നതു വരെ ജനാസയെ അനുഗമിച്ചാൽ അയാൾക്ക് ഒരു ഖീറാത്ത് പ്രതിഫലമുണ്ട്. ഒരാൾ മറമാടപ്പെടുന്നത് വരെ ജനാസയുടെ കൂടെ നടന്നാൽ അയാൾക്ക് രണ്ട് ഖീറാത്ത് പ്രതിഫലമുണ്ട്. ''ഖീറാത്ത്'' എന്നത് ഉഹ്ദ് മലയോളം വരും." (ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബാറാഅ് ഇബ്നുആസിബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 826, 826, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 243, 'عَنْ عَبْدِ اللهِ بْنِ الْمُغَفَّلِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَبِعَ جَنَازَةً حَتَّى يُفْرَغَ مِنْهَا فَلَهُ قِيرَاطَانِ، فَإِنْ رَجَعَ قَبْلَ أَنْ يُفْرَغَ مِنْهَا فَلَهُ قِيرَاطٌ". (ن)', 'അബ്ദുല്ലാഹിബ്നു മുഗഫൽ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ജനാസയെ സംസ്കരിച്ചു കഴിയുന്നത് വരെ ഒരാൾ ജനാസയെ പിന്തുടർന്നാൽ അയാൾക്ക് രണ്ട് ഖീറാത്ത് പ്രതിഫലമുണ്ട്. സംസ്കരിക്കുന്നതിന് മുമ്പ് മടങ്ങിപോന്നാൽ അയാൾക്ക് ഒരു ഖീറാത്ത് പ്രതിഫലമുണ്ട്." (ന)', 'عَبْدِ اللهِ بْنِ الْمُغَفَّلِ', 'അബ്ദുല്ലാഹിബ്നു മുഗഫൽ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 826, 826, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 244, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ قِيلَ لَهُ إِنَّ أَبَا هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ يَقُولُ: مَنْ تَبِعَ جَنَازَةً فَلَهُ قِيرَاطٌ، فَقَالَ: أَكْثَرَ أَبُو هُرَيْرَةَ عَلَيْنَا، فَصَدَّقَتْ عَائِشَةُ أَبَا هُرَيْرَةَ رَضِيَ اللهُ عَنْهُمَا، وَقَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُهُ، فَقَالَ ابْنُ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: لَقَدْ فَرَّطْنَا فِي قَرَارِيطَ كَثِيرَةٍ. (خ)', 'ഇബ്നുഉമർ(റ): അബുഹുറൈറ(റ) ഇങ്ങനെ പറയുന്നുവെന്ന് അദ്ദേഹത്തോട് പറയപ്പെട്ടു. ഒരാൾ ജനാസയെ അനുഗമിച്ചാൽ അയാൾക്ക് ഒരു ഖീറാത്ത് പ്രതിഫലമുണ്ട്. അപ്പോൾ ഇബ്നുഉമർ(റ) പറഞ്ഞു: അബുഹുറൈറ(റ) നമുക്ക് കുറേ അധികമാക്കിയിരിക്കുന്നു. അന്നേരം ആയിശ(റ) അബൂഹുറൈറ(റ)യെ സത്യപ്പെടുത്തികൊണ്ട് പറഞ്ഞു. പ്രവാചകൻ(സ) അങ്ങനെ പറയുന്നതായി ഞാനും കേട്ടിട്ടുണ്ട്. അപ്പോൾ ഇബ്നുഉമർ(റ) പറഞ്ഞു: ധാരാളം ഖീറാത്തുകളിൽ നാം വീഴ്ച്ച കാണിച്ചിട്ടുണ്ട്. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 826, 826, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 245, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُتْبَعُ الْجَنَازَةُ بِصَوْتٍ وَلَا نَارٍ. وَفِي رِوَايَةٍ: وَلَا يُمْشَى بَيْنَ يَدَيْهَا". (د)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "തീയുമായും ശബ്ദകോലാഹലത്തോടു കൂടിയും ജനാസയെ അനുഗമിക്കരുത്. മറ്റൊരു റിപ്പോർട്ടിൽ: ജനാസയുടെ മുമ്പിൽ നടക്കരുത്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 826, 827, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=245), 1, 'وَفِي رِوَايَةٍ: وَلَا يُمْشَى بَيْنَ يَدَيْهَا". (د)', 'മറ്റൊരു നിവേദനിൽ: ജനാസയുടെ മുമ്പിൽ നടക്കരുത്." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 246, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَإِذَا نِسْوَةٌ جُلُوسٌ، فَقَالَ: "مَا يُجْلِسُكُنَّ". قُلْنَ: نَنْتَظِرُ الْجِنَازَةَ. قَالَ: "هَلْ تَغْسِلْنَ". قُلْنَ: لَا. قَالَ: "هَلْ تَحْمِلْنَ". قُلْنَ: لَا. قَالَ: "هَلْ تُدْلِينَ فِيمَنْ يُدْلِي". قُلْنَ: لَا. قَالَ: "فَارْجِعْنَ مَأْزُورَاتٍ، غَيْرَ مَأْجُورَاتٍ". [ز: في سنده راو مختلف فيه] (جه)', 'അലി(റ): പ്രവാചകൻ(സ) പുറത്തിറങ്ങിയപ്പോൾ കുറെ സ്ത്രീകൾ ഇരിക്കുന്നത് കണ്ടു. പ്രവാചകൻ(സ) ചോദിച്ചു: "നിങ്ങൾ എന്തിന് ഇരിക്കുന്നു?" അവർ പറഞ്ഞു: ഞങ്ങൾ ജനാസയെ പ്രതീക്ഷിക്കുകയാണ്. നബി(സ) ചോദിച്ചു: "നിങ്ങൾ ജനാസ കുളിപ്പിച്ചോ?" അവർ പറഞ്ഞു: ഇല്ല. "നിങ്ങൾ ജനാസ ചുമന്നുവോ?" അവർ പറഞ്ഞു: ഇല്ല. "താഴ്ത്തി വെക്കുന്നവരോടൊപ്പം നിങ്ങൾ താഴ്ത്തി വെച്ചിട്ടുണ്ടോ?" അവർ പറഞ്ഞു: ഇല്ല. പ്രവാചകൻ(സ) പറഞ്ഞു: "എങ്കിൽ നിങ്ങൾ പ്രതിഫലം ലഭിക്കാതെ നഷ്ടം സംഭവിച്ചവരായി മടങ്ങിക്കൊള്ളുക." (പരമ്പരയിലെ ഒരു റിപ്പോർട്ടറെക്കുറിച്ച് അഭിപ്രായ ഭിന്നതയുണ്ടന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده راو مختلف فيه', null, 827, 827, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 247, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنَّا نُنْهَى عَنِ اتِّبَاعِ الْجَنَائِزِ، وَلَمْ يُعْزَمْ عَلَيْنَا. (ق,د,جه)', 'ഉമ്മുഅതിയ്യ(റ): ജനാസയെ അനുഗമിക്കുന്നത് ഞങ്ങളോട് വിരോധിക്കപ്പെട്ടിരിക്കുന്നു. പക്ഷേ ഞങ്ങൾ കർകശമായി വിരോധിക്കപ്പെട്ടിട്ടില്ല. (ബു,മു,ദ,ജ)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅതിയ്യ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 827, 827, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 248, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: مُرَّ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِجِنَازَةٍ، فَقَامَ وَقَالَ: "قُومُوا، فَإِنَّ لِلْمَوْتِ فَزَعًا". (جه)', 'അബൂഹുറൈറ(റ): തിരുമേനി(സ)യുടെ അരികിലൂടെ ഒരു മയ്യിത്ത് കടന്നുപോയി. പ്രവാചകൻ(സ) എഴുന്നേറ്റ്കൊണ്ട് പറഞ്ഞു: "എഴുന്നേൽക്കുക, നിശ്ചയം മരണത്തിൽ വെപ്രാളമുണ്ട്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 827, 827, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 249, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِجِنَازَةٍ فَقُمْنَا، حَتَّى جَلَسَ فَجَلَسْنَا. (م,د,ت,ن,جه)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): ഒരു ജനാസക്ക് വേണ്ടി പ്രവാചകൻ(സ) എഴുന്നേറ്റ് നിന്നു. ഞങ്ങളും നിന്നു. പ്രവാചകൻ(സ) ഇരുന്നു ഞങ്ങളും ഇരുന്നു. (മു,ദ,തു,ന,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 827, 827, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 250, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ ذُكِرَ الْقِيَامُ فِي الْجَنَائِزِ حَتَّى تُوضَعَ، فَقَالَ عَلِيُّ بْنُ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَعَدَ. حَسَنٌ صَحِيحٌ. (م,د,ت,ن,جه)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): മൃതശരീരം താഴെ വെക്കുന്നത് വരെ എഴുന്നേൽക്കുന്നതിനെ കുറിച്ച് അദ്ദേഹത്തോട് പറയപ്പെട്ടു. അപ്പോൾ അലി(റ) പറഞ്ഞു: പ്രവാചകൻ(സ) എഴുന്നേറ്റ് നിന്നു, ശേഷം പിന്നെ ഇരുന്നു. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (മു,ദ,തു,ന,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 827, 827, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 251, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا رَأَيْتُمُ الْجَنَازَةَ فَقُومُوا لَهَا، فَمَنْ تَبِعَهَا فَلَا يَقْعُدَنَّ حَتَّى تُوضَعَ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن)', 'പ്രവാചകൻ(സ) പറഞ്ഞതായി അബൂസഈദുൽ ഖുദ്രീ(റ): "നിങ്ങൾ ജനാസയെ കണ്ടാൽ എഴുന്നേറ്റ് നിൽക്കുക. അതിനെ പിന്തുടരുന്നവർ അത് വെക്കുന്നതുവരെ ഇരിക്കരുത്." (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ബു,മു,ദ,തു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'പ്രവാചകൻ(സ) പറഞ്ഞതായി അബൂസഈദുൽ ഖുദ്രീ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 827, 828, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 252, 'عَنْ أَبِي هُرَيْرَةَ وَأَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُمَا قَالَا: مَا رَأَيْنَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَهِدَ جَنَازَةً قَطُّ فَجَلَسَ حَتَّى تُوضَعَ. (ن)', 'അബൂഹുറൈറ(റ), അബൂസഈദ്(റ): ജനാസയിൽ പങ്കെടുത്താൽ അത് വെക്കുന്നതുവരെ ഇരിക്കുന്നതായിട്ട് നബി(സ)യെ ഞങ്ങൾ കണ്ടിട്ടേയില്ല. (ന)', 'أَبِي هُرَيْرَةَ وَأَبِي سَعِيدٍ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 828, 828, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 253, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ تَبِعَ جَنَازَةً، وَحَمَلَهَا ثَلَاثَ مَرَّاتٍ، فَقَدْ قَضَى مَا عَلَيْهِ مِنْ حَقِّهَا". (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ആരെങ്കിലും മയ്യിതിനെ പിന്തുടരുകയും മൂന്നു പ്രാവശ്യം അതിനെ വഹിക്കുകയും ചെയ്താൽ, അതിനോടുള്ള അവന്റെ ഉത്തരവാദിത്തം നിറവേറ്റി." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 828, 828, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 254, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنْ عَامِرِ بْنِ رَبِيعَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا رَأَى أَحَدُكُمُ الْجَنَازَةَ، فَإِنْ لَمْ يَكُنْ مَاشِيًا مَعَهَا، فَلْيَقُمْ حَتَّى تُخَلِّفَهُ، أَوْ تُوضَعَ مِنْ قَبْلِ أَنْ تُخَلِّفَهُ". وَفِي رِوَايَةٍ: قَالَ: "إِذَا رَأَيْتُمُ الْجَنَازَةَ فَقُومُوا لَهَا حَتَّى تُخَلِّفَكُمْ أَوْ تُوضَعَ". (ق,د,ت,ن,جه)', 'ഇബ്നുഉമറി(റ)ൽനിന്ന് ആമിറുബിൻ റബീഅ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ ജനാസയെ കണ്ടാൽ നിങ്ങളതിനൊപ്പം പോകുന്നവരല്ലെങ്കിൽ, അത് അവനെ പിന്നിലാക്കുന്നതുവരെ, അല്ലെങ്കിൽ വെക്കുന്നതുവരെ എഴുന്നേറ്റ് നിൽക്കട്ടെ." മറ്റൊരു റിപ്പോർട്ടിൽ: "നിങ്ങൾ ജനാസയെ കണ്ടാൽ നിങ്ങളെ പിന്നിലാക്കുന്നതുവരെ അല്ലെങ്കിൽ വെക്കുന്നതുവരെ എഴുന്നേറ്റ് നിൽക്കുക." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമറി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 828, 828, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=254), 1, 'وَفِي رِوَايَةٍ: قَالَ: "إِذَا رَأَيْتُمُ الْجَنَازَةَ فَقُومُوا لَهَا حَتَّى تُخَلِّفَكُمْ أَوْ تُوضَعَ". (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: "നിങ്ങൾ ജനാസയെ കണ്ടാൽ നിങ്ങളെ പിന്നിലാക്കുന്നതുവരെ അല്ലെങ്കിൽ വെക്കുന്നതുവരെ എഴുന്നേറ്റ് നിൽക്കുക." (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 255, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ أَخَذَ بِيَدِ مَرْوَانَ وَهُمَا فِي جَنَازَةٍ فَجَلَسَا قَبْلَ أَنْ تُوضَعَ، فَجَاءَ أَبُو سَعِيدٍ رَضِيَ اللهُ عَنْهُ فَأَخَذَ بِيَدِ مَرْوَانَ فَقَالَ: قُمْ فَوَاللهِ لَقَدْ عَلِمَ هَذَا أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَانَا عَنْ ذَلِكَ، فَقَالَ أَبُو هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: صَدَقَ. (خ)', 'അബൂഹുറൈറ(റ): അദ്ദേഹം മർവാന്റെ കയ്യും പിടിച്ച് ഒരു ജനാസയോടൊത്തായിരുന്നു. അത് വെക്കുന്നതിനു മുമ്പേ അവർ രണ്ടാളും ഇരുന്നു. അപ്പോൾ അബൂസഈദ്(റ) വന്ന് മർവാന്റെ കൈ പിടിച്ച് പറഞ്ഞു: എഴുന്നേൽക്ക്, അല്ലാഹുവാണ് സത്യം, നബി(സ) അത് വിരോധിച്ചതാണെന്ന് ഇദ്ദേഹത്തിന് (അബൂഹുറൈറ) അറിയാം. അപ്പോൾ അബൂഹുറൈറ(റ) പറഞ്ഞു: സത്യമാണ്. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 828, 828, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 256, 'عَنْ يَزِيدَ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُمْ كَانُوا جُلُوسًا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَطَلَعَتْ جِنَازَةٌ، فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَامَ مَنْ مَعَهُ، فَلَمْ يَزَالُوا قِيَامًا حَتَّى نَفَذَتْ. (ن)', 'യസീദുബ്നു സാബിത്(റ): അവർ നബി(സ)യുടെ കൂടെ ഇരിക്കുമ്പോൾ ജനാസയെ കണ്ടു നബി(സ) എഴുന്നേറ്റു. അവിടത്തോടൊപ്പം അവരും എഴുന്നേറ്റു. വെക്കുന്നതുവരെ ആ നിറുത്തം തുടർന്നു. (ന)', 'يَزِيدَ بْنِ ثَابِتٍ', 'യസീദുബ്നു സാബിത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 828, 828, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 257, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى قَالَ: كَانَ سَهْلُ بْنُ حُنَيْفٍ وَقَيْسُ بْنُ سَعْدِ بْنِ عُبَادَةَ – رَضِيَ اللهُ عَنْهُمْ – بِالْقَادِسِيَّةِ، فَمُرَّ عَلَيْهِمَا بِجَنَازَةٍ فَقَامَا، فَقِيلَ لَهُمَا: إِنَّهَا مِنْ أَهْلِ الْأَرْضِ. فَقَالَا: مُرَّ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِجَنَازَةٍ فَقَامَ، فَقِيلَ لَهُ: إِنَّهُ يَهُودِيٌّ. فَقَالَ: "أَلَيْسَتْ نَفْسًا". (ن)', 'അബ്ദുറഹ്മാനുബ്നു അബീലൈല(റ): സഹ്ലുബ്നു ഹുനൈഫും ഖൈസുബ്നു സഅ്ദും ഖാദിസിയ്യയിലിരിക്കുകയായിരുന്നു. അതിലൂടെ ഒരു ജനാസ കൊണ്ടുപോയപ്പോൾ അവർ എഴുന്നേറ്റു നിന്നു. അപ്പോൾ അത് ഇന്നാട്ടിലെ ഒരു വ്യക്തിയുടെ ജനാസയാണെന്ന് അവരോട് പറഞ്ഞു. അവർ പറഞ്ഞു: ഒരിക്കൽ നബി(സ)യുടെ അടുത്തുകൂടെ ഒരു ജനാസ കൊണ്ടുപോയപ്പോൾ അവിടുന്ന് എഴുന്നേറ്റു നിന്നു. അതൊരു ജൂതന്റെ ജനാസയാണെന്ന് പറയപ്പെട്ടു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "അതും ഒരു ആത്മാവല്ലയോ?" (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى قَالَ', 'അബ്ദുറഹ്മാനുബ്നു അബീലൈല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 829, 829, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 258, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي جَنَازَةٍ، فَلَمَّا انْتَهَيْنَا إِلَى الْقَبْرِ وَلَمْ يُلْحَدْ فَجَلَسَ وَجَلَسْنَا حَوْلَهُ، كَأَنَّ عَلَى رُءُوسِنَا الطَّيْرَ. (ن,جه)', 'ബറാഅ്(റ): ഞങ്ങൾ പ്രവാചകന്റെ(സ) കൂടെ ഒരു ജനാസയുടെ കാര്യത്തിൽ പുറപ്പെട്ടു. ഞങ്ങൾ ഖബറിനടുത്തെത്തി. അത് അടക്കം ചെയ്യപ്പെട്ടിരുന്നില്ല. അപ്പോൾ അവിടുന്ന് ഇരുന്നു. ഞങ്ങളുടെ തലകൾക്ക് മുകളിൽ പക്ഷികൾ ഉള്ളത് പോലെ (അച്ചടക്കത്തിൽ) ചുറ്റും ഞങ്ങളും ഇരുന്നു. (ന,ജ)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 829, 829, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 259, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَّتْ جَنَازَةٌ، فَقَامَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقُمْنَا مَعَهُ، فَقُلْنَا: يَا رَسُولَ اللهِ، إِنَّهَا يَهُودِيَّةٌ! فَقَالَ: "إِنَّ الْمَوْتَ فَزَعٌ، فَإِذَا رَأَيْتُمُ الْجَنَازَةَ فَقُومُوا لَهَا". (ق,د,ن)', 'ജാബിർ(റ): ഒരു ജനാസ കൊണ്ടുപോകപ്പെട്ടപ്പോൾ റസൂൽ(സ) എഴുന്നേറ്റ് നിന്നു. ഞങ്ങളും അവിടത്തോടൊപ്പം നിന്നു. ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, അതൊരു യഹൂദി സ്ത്രീയാണ്! അപ്പോൾ (പ്രവാചകൻ) പറഞ്ഞു: "നിശ്ചയം മരണം നടുക്കമുണ്ടാക്കുന്നതാണ്. അതിനാൽ നിങ്ങൾ ജനാസ കണ്ടാൽ എഴുന്നേറ്റു നിൽക്കുക." (ബു,മു,ദ,ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 829, 829, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 260, 'عَنْ أَبِي مَعْمَرٍ قَالَ: كُنَّا عِنْدَ عَلِيٍّ رَضِيَ اللهُ عَنْهُ فَمَرَّتْ بِهِ جَنَازَةٌ، فَقَامُوا لَهَا، فَقَالَ عَلِيٌّ: مَا هَذَا؟ قَالُوا: أَمْرُ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ. فَقَالَ: إِنَّمَا قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِجَنَازَةٍ يَهُودِيَّةٍ، وَلَمْ يَعُدْ بَعْدَ ذَلِكَ. (ن)', 'അബൂമഅ്മർ(റ): ഞങ്ങൾ അലി(റ)യുടെ അടുക്കൽ ഉള്ളപ്പോൾ അദ്ദേഹത്തിന്റെ അടുത്തുകൂടെ ഒരു ജനാസകൊണ്ടുപോയി. അപ്പോൾ അവിടെയുള്ളവർ എഴുന്നേറ്റു നിന്നു. അലി(റ) ചോദിച്ചു: എന്താണിത്? അവർ പറഞ്ഞു അബൂമൂസ(റ)യുടെ നിർദ്ദേശമാണിത്. അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഒരു യഹൂദിയുടെ ജനാസക്ക് വേണ്ടി മാത്രമാണ് നിന്നത്. അതിന് ശേഷം അത് ആവർത്തിച്ചിട്ടില്ല. (ന)', 'أَبِي مَعْمَرٍ قَالَ', 'അബൂമഅ്മർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 829, 829, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 261, 'عَنْ مُحَمَّدِ بْنِ سِيرِينَ: أَنَّ جَنَازَةً مَرَّتْ بِالْحَسَنِ بْنِ عَلِيٍّ وَابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمْ، فَقَامَ الْحَسَنُ وَلَمْ يَقُمِ ابْنُ عَبَّاسٍ، فَقَالَ الْحَسَنُ: أَلَيْسَ قَدْ قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِجَنَازَةِ يَهُودِيٍّ؟ قَالَ ابْنُ عَبَّاسٍ: نَعَمْ، ثُمَّ جَلَسَ. وَفِي رِوَايَةٍ: قَامَ لَهَا ثُمَّ قَعَدَ. (ن)', 'മുഹമ്മദുബ്നുസീരീൻ: ഇബ്നുഅബ്ബാസി(റ)ന്റേയും ഹസന്റേയും(റ) അടുത്തുകൂടെ ഒരു ജനാസ കൊണ്ടുപോയി. ഹസൻ(റ) എഴുന്നേറ്റു നിന്നു, ഇബ്നുഅബ്ബാസ്(റ) എഴുന്നേറ്റില്ല. അപ്പോൾ ഹസൻ(റ) ചോദിച്ചു: ഒരു യഹൂദിയുടെ ജനാസക്ക് വേണ്ടി നബി(സ) എഴുന്നേറ്റിട്ടില്ലേ? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അതെ, പിന്നെ അവിടുന്ന് ഇരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) അതിന്നായി നിന്നു. പിന്നെ ഇരുന്നു. (ന)', 'مُحَمَّدِ بْنِ سِيرِينَ', 'മുഹമ്മദുബ്നുസീരീൻ', null, null, array['ن']::text[], array['ന']::text[], null, null, 829, 829, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=261), 1, 'وَفِي رِوَايَةٍ: قَامَ لَهَا ثُمَّ قَعَدَ. (ن)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) അതിന്നായി നിന്നു. പിന്നെ ഇരുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 262, 'عَنِ ابْنِ عَبَّاسٍ وَالْحَسَنِ بْنِ عَلِيٍّ رَضِيَ اللهُ عَنْهُمْ: مَرَّتْ بِهِمَا جَنَازَةٌ، فَقَامَ أَحَدُهُمَا وَقَعَدَ الآخِرُ، فَقَالَ الَّذِي قَامَ: أَمَا وَاللهِ لَقَدْ عَلِمْتُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ قَامَ. قَالَ لَهُ الَّذِي جَلَسَ: لَقَدْ عَلِمْتُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ جَلَسَ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ), ഹസനുബ്നു അലി(റ): അവരുടെ അടുത്ത് കൂടെ ഒരു ജനാസ കൊണ്ടു പോയി. അപ്പോൾ അവരിലൊരാൾ നിന്നു, മറ്റെയാൾ ഇരുന്നു. അപ്പോൾ നിന്നയാൾ പറഞ്ഞു: അല്ലാഹുവാണെ ഞാനറിഞ്ഞത് റസൂൽ(സ) നിന്നിട്ടുണ്ട് എന്നാണല്ലോ? ഇരുന്ന ആൾ പറഞ്ഞു: ഞാൻ അറിഞ്ഞത് റസൂൽ(സ) ഇരുന്നിട്ടുണ്ട് എന്നാണ്. (ന)', 'ابْنِ عَبَّاسٍ وَالْحَسَنِ بْنِ عَلِيٍّ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 830, 830, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 263, 'عَنِ الْحَسَنِ بْنِ عَلِيٍّ رَضِيَ اللهُ عَنْهُمَا: كَانَ جَالِسًا فَمُرَّ عَلَيْهِ بِجَنَازَةٍ، فَقَامَ النَّاسُ حَتَّى جَاوَزَتِ الْجَنَازَةِ، فَقَالَ الْحَسَنُ: إِنَّمَا مُرَّ بِجَنَازَةِ يَهُودِيٍّ وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى طَرِيقِهَا جَالِسًا، فَكَرِهَ أَنْ تَعْلُوَ رَأْسُهُ جَنَازَةُ يَهُودِيٍّ، فَقَامَ. (ن)', 'ഹസൻ(റ): അദ്ദേഹം ഇരിക്കുകയായിരുന്നപ്പോൾ ഒരു ജനാസ തന്റെ സമീപത്ത് കൂടെ കൊണ്ടുപോയി. ജനാസ കൊണ്ടുപോയി കഴിയുന്നത് വരെ ജനങ്ങൾ എഴുന്നേറ്റ് നിന്നു. അപ്പോൾ ഹസൻ(റ) പറഞ്ഞു. നബി(സ) വഴിയിലിരിക്കെ ഒരു യഹൂദിയുടെ ജനാസ കൊണ്ടുപോയി. ഒരു യഹൂദിയുടെ ജനാസ തന്റെ തലയേക്കാൾ ഉയരുന്നത് അവിടുന്ന് വെറുത്തു. അപ്പോൾ അവിടുന്ന് നിന്നു. (ന)', 'الْحَسَنِ بْنِ عَلِيٍّ', 'ഹസൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 830, 830, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 264, 'عَن جابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَامَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ لِجَنَازَةِ يَهُودِيٍّ – مَرَّتْ بِهِ – حَتَّى تَوَارَتْ. (ن)', 'ജാബിർ(റ): നബി(സ)യും അനുചരന്മാരും അതുവഴി കൊണ്ടുപോയ ഒരു യഹൂദിയുടെ ജനാസ കണ്ടപ്പോൾ എഴുന്നേറ്റ് നിന്നു. അത് അകന്ന് പോകുന്നത് (കാഴ്ചയിൽനിന്ന് മറയുന്നത്) വരെ. (ന)', 'جابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 830, 830, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 265, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ جَنَازَةً مَرَّتْ بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ فَقِيلَ: إِنَّهَا جَنَازَةُ يَهُودِيٍّ. فَقَالَ: "إِنَّمَا قُمْنَا لِلْمَلَائِكَةِ". (ن)', 'അനസ്(റ): ഒരു ജനാസ നബി(സ)യുടെ അടുത്തു കൂടെ കൊണ്ടുപോയപ്പോൾ അവിടുന്ന് എഴുന്നേറ്റ് നിന്നു. അപ്പോൾ അതൊരു യഹൂദിയുടെ ജനാസയാണെന്ന് പറയപ്പെട്ടു. പ്രവാചകൻ(സ) പറഞ്ഞു: "നാം നിന്നത് മലക്കുകൾക്ക് വേണ്ടിയാണ്." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 830, 830, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 266, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْنَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَامَ فَقُمْنَا، وَقَعَدَ فَقَعَدْنَا. يَعْنِي فِي الْجَنَازَةِ. (م,ن)', 'അലി(റ): നബി(സ) നിൽക്കുന്നതായി കണ്ടപ്പോൾ ഞങ്ങൾ നിന്നു. അവിടുന്ന് ഇരുന്നപ്പോൾ ഞങ്ങളും ഇരുന്നു. ജനാസയുടെ കാര്യമാണ് അദ്ദേഹം ഉദ്ദേശിച്ചത്. (മു,ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 830, 830, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 267, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ خَلْفَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَصَلَّى عَلَى أُمِّ كَعْبٍ، مَاتَتْ وَهِيَ نُفَسَاءُ، فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلصَّلَاةِ عَلَيْهَا وَسَطَهَا. (م,د,ت,ن,جه)', 'സമുറത്ബ്നു ജുൻദുബ്(റ): ഞാൻ നബി(സ)യുടെ പിന്നിൽ നിന്ന് ഉമ്മുകഅ്ബിന്ന് വേണ്ടി നിസ്കരിച്ചു. അവർ പ്രസവിച്ചുകിടക്കെ മരിച്ചതായിരുന്നു. നബി(സ) നിസ്കാരത്തിന്നായി അവരുടെ(മയ്യിത്തിന്റെ) നടുഭാഗത്ത് നിന്നു. (മു,ദ,തു,ന,ജ)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറത്ബ്നു ജുൻദുബ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 830, 831, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 268, 'عَن نَافِعٍ أَبِي غَالِبٍ قَالَ: كُنْتُ فِي سِكَّةِ الْمِرْبَدِ، فَمَرَّتْ جَنَازَةٌ مَعَهَا نَاسٌ كَثِيرٌ، قَالُوا: جَنَازَةُ عَبْدِ اللهِ بْنِ عُمَيْرٍ، فَتَبِعْتُهَا، فَإِذَا أَنَا بِرَجُلٍ عَلَيْهِ كِسَاءٌ رَقِيقٌ عَلَى بُرَيْذِينَتِهِ، وَعَلَى رَأْسِهِ خِرْقَةٌ تَقِيهِ مِنَ الشَّمْسِ، فَقُلْتُ: مَنْ هَذَا الدِّهْقَانُ؟ قَالُوا: هَذَا أَنَسُ بْنُ مَالِكٍ رَضِيَ اللهُ عَنْهُ، فَلَمَّا وُضِعَتِ الْجَنَازَةُ قَامَ أَنَسٌ، فَصَلَّى عَلَيْهَا وَأَنَا خَلْفَهُ لَا يَحُولُ بَيْنِي وَبَيْنَهُ شَيْءٌ، فَقَامَ عِنْدَ رَأْسِهِ فَكَبَّرَ أَرْبَعَ تَكْبِيرَاتٍ لَمْ يُطِلْ وَلَمْ يُسْرِعْ، ثُمَّ ذَهَبَ يَقْعُدُ، فَقَالُوا: يَا أَبَا حَمْزَةَ، الْمَرْأَةُ الْأَنْصَارِيَّةُ، فَقَرَّبُوهَا وَعَلَيْهَا نَعْشٌ أَخْضَرُ، فَقَامَ عِنْدَ عَجِيزَتِهَا، فَصَلَّى عَلَيْهَا نَحْوَ صَلَاتِهِ عَلَى الرَّجُلِ، ثُمَّ جَلَسَ. فَقَالَ الْعَلَاءُ بْنُ زِيَادٍ: يَا أَبَا حَمْزَةَ، هَكَذَا كَانَ يَفْعَلُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَى الْجَنَازَةِ كَصَلَاتِكَ، يُكَبِّرُ عَلَيْهَا أَرْبَعًا، وَيَقُومُ عِنْدَ رَأْسِ الرَّجُلِ وَعَجِيزَةِ الْمَرْأَةِ؟ قَالَ: نَعَمْ، قَالَ: يَا أَبَا حَمْزَةَ، غَزَوْتَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ، غَزَوْتُ مَعَهُ حُنَيْنًا، فَخَرَجَ الْمُشْرِكُونَ فَحَمَلُوا عَلَيْنَا حَتَّى رَأَيْنَا خَيْلَنَا وَرَاءَ ظُهُورِنَا، وَفِي الْقَوْمِ رَجُلٌ يَحْمِلُ عَلَيْنَا فَيَدُقُّنَا وَيَحْطِمُنَا، فَهَزَمَهُمُ اللهُ، وَجَعَلَ يُجَاءُ بِهِمْ فَيُبَايِعُونَهُ عَلَى الْإِسْلَامِ، فَقَالَ رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِنَّ عَلَيَّ نَذْرًا إِنْ جَاءَ اللهُ بِالرَّجُلِ الَّذِي كَانَ مُنْذُ الْيَوْمِ يَحْطِمُنَا لَأَضْرِبَنَّ عُنُقَهُ، فَسَكَتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَجِيءَ بِالرَّجُلِ، فَلَمَّا رَأَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَا رَسُولَ اللهِ، تُبْتُ إِلَى اللهِ، فَأَمْسَكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يُبَايِعُهُ لِيَفِيَ الْآخَرُ بِنَذْرِهِ، قَالَ: فَجَعَلَ الرَّجُلُ يَتَصَدَّى لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِيَأْمُرَهُ بِقَتْلِهِ، وَجَعَلَ يَهَابُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَقْتُلَهُ، فَلَمَّا رَأَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ لَا يَصْنَعُ شَيْئًا بَايَعَهُ، فَقَالَ الرَّجُلُ: يَا رَسُولَ اللهِ نَذْرِي، فَقَالَ: "إِنِّي لَمْ أُمْسِكْ عَنْهُ مُنْذُ الْيَوْمِ إِلَّا لِتُوفِيَ بِنَذْرِكَ". فَقَالَ: يَا رَسُولَ اللهِ، أَلَا أَوْمَضْتَ إِلَيَّ؟ فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهُ لَيْسَ لِنَبِيٍّ أَنْ يُومِضَ". قَالَ أَبُو غَالِبٍ: فَسَأَلْتُ عَنْ صَنِيعِ أَنَسٍ فِي قِيَامِهِ عَلَى الْمَرْأَةِ عِنْدَ عَجِيزَتِهَا، فَحَدَّثُونِي: أَنَّهُ إِنَّمَا كَانَ لِأَنَّهُ لَمْ تَكُنِ النُّعُوشُ، فَكَانَ الْإِمَامُ يَقُومُ حِيَالَ عَجِيزَتِهَا يَسْتُرُهَا مِنَ الْقَوْمِ. (د,ت,جه)', 'നാഫിഅ് (അബൂഗാലിബ്): ഞാൻ സിക്കത്തുൽ മിർബദിലായിരിക്കെ ഒരു ജനാസകൊണ്ടുപോയി. അതിന്റെ കൂടെ ഒരു വലിയ കൂട്ടം ആളുകളുണ്ടായിരുന്നു. അവർ പറഞ്ഞു: ഇത് അബ്ദുല്ലാഹിബ്നു ഉമൈറിന്റെ ജനാസയാണ് അപ്പോൾ ഞാനതിനെ പിന്തുടർന്നു. കുതിരപ്പുറത്ത് നേരിയ വസ്ത്രം ധരിച്ചിരിക്കുന്ന ഒരാളുടെ അടുത്തായിരുന്നു അപ്പോൾ ഞാൻ. അദ്ദേഹത്തിന്റെ തലക്ക് മുകളിൽ വെയിലിൽ നിന്ന് സുരക്ഷയേകുന്ന ഒരു തുണിക്കഷ്ണവുമുണ്ട്. അപ്പോൾ ഞാൻ ചോദിച്ചു: ഈ നേതാവ് ആരാണ്? അവർ പറഞ്ഞു: അനസുബ്നുമാലിക്(റ) ആണന്ന്. മയ്യിത്ത് കൊണ്ടുവന്ന് വെച്ചപ്പോൾ അനസ്(റ) എഴുന്നേറ്റു. അദ്ദേഹം നിസ്കരിച്ചു. പിന്നിൽ ഞാനും. ഞങ്ങൾക്കിടയിൽ യാതൊരു മറയുമുണ്ടായിരുന്നില്ല. അദ്ദേഹം അതിന്റെ തലയുടെ ഭാഗത്ത് നിന്നു. എന്നിട്ട് വേഗത്തിലോ നീളത്തിലോ ആകാത്ത വിധം നാല് തക്ബീറുകൾ ചൊല്ലി. പിന്നെ അദ്ദേഹം പോയി ഇരുന്നു. അപ്പോൾ അവർ പറഞ്ഞു: അബൂഹംസേ, ഒരു അൻസാരി സ്ത്രീയുടെ മയ്യിത്ത് എത്തിയിട്ടുണ്ട്. അവർ അതിനെ അടുപ്പിച്ചു. ഒരു പച്ച ശവമഞ്ചത്തിലായിരുന്നു അത്. അദ്ദേഹം ആ മയ്യിത്തിന്റെ മധ്യഭാഗത്തിനടുത്ത് നിന്നു. എന്നിട്ട് പുരുഷന് നിസ്കരിച്ചപോലെ ആമയ്യിത്തിനും അദ്ദേഹം നിസ്കരിച്ചു. പിന്നെ അദ്ദേഹം ഇരുന്നു. അലാഉബ്നുസിയാദ് പറഞ്ഞു: അബൂഹംസേ, ഇപ്രകാരമാണോ റസൂൽ(സ) ചെയ്തിരുന്നത്? അതായത് താങ്കൾ നമസ്കരിച്ചതുപോലെ നാലു തക്ബീർ ചൊല്ലുകയും പുരുഷന്റെ തലഭാഗത്തുനിൽക്കുകയും സ്ത്രീയുടെ മധ്യഭാഗത്ത് നിൽക്കുകയും ചെയ്തുകൊണ്ടാണോ നബി(സ) നിസ്കരിച്ചത്? അദ്ദേഹം പറഞ്ഞു: അതെ. അലാഅ് ചോദിച്ചു: അബൂഹംസേ, താങ്കൾ റസൂലി(സ)ന്റെ കൂടെ യുദ്ധം ചെയ്തിട്ടുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: അതെ, ഞാൻ അവിടുത്തോടൊപ്പം ഹുനൈൻ യുദ്ധത്തിൽ പങ്കെടുത്തു. മുശ്രിക്കുകൾ പുറപ്പെട്ടു. അവർ ഞങ്ങളെ ആക്രമിച്ചു. അങ്ങനെ ഞങ്ങളുടെ കുതിരയെ ഞങ്ങളുടെ പിന്നിൽ കണ്ടു. ആ കൂട്ടത്തിൽ ഒരാളുണ്ടായിരുന്നു. അയാൾ ഞങ്ങളെ തകർക്കുകയും ആക്രമിക്കുകയും ചെയ്യുന്നുണ്ടായിരുന്നു. അല്ലാഹു അവരെ പരാജയപ്പെടുത്തി. അങ്ങനെ അവരെ പ്രവാചകന്റെ(സ) പക്കൽ കൊണ്ട് വരാനും അവരുമായി ഉടമ്പടി ചെയ്യുവാനും തുടങ്ങി. അപ്പോൾ പ്രവാചകന്റെ(സ) അനുചരന്മാരിൽപ്പെട്ട ഒരാൾ പറഞ്ഞു: എനിക്കൊരു നേർച്ചയുണ്ട്. ഇന്നേ വരെ നമ്മെ ആക്രമിക്കുകയും തകർക്കുകയുമൊക്കെ ചെയ്ത ആ മനുഷ്യനെ ഇങ്ങോട്ട് അല്ലാഹു കൊണ്ടുവന്നാൽ ഞാൻ അവന്റെ പിരടി വെട്ടുക തന്നെ ചെയ്യും. പ്രവാചകൻ(സ) അപ്പോൾ (അതു കേട്ടപ്പോൾ) മൗനം അവലംബിച്ചു. ആ മനുഷ്യനെ കൊണ്ടുവന്നു. അയാൾ റസൂലി(സ)നെ കണ്ടപ്പോൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാൻ അല്ലാഹുവിലേക്ക് പശ്ചാതപിച്ച് മടങ്ങിരിക്കുന്നു. അപ്പോൾ പ്രവാചകൻ(സ), മറ്റേ ആൾ നേർച്ച പൂർത്തിയാക്കാൻവേണ്ടി ബൈഅത്ത് ചെയ്യാതെ പിടിച്ച് നിന്നു. അപ്പോൾ ആ മനുഷ്യൻ അയാളെ കൊല്ലാൻ റസൽ(സ) കൽപിക്കുന്നതിനുവേണ്ടി എത്തിനോക്കാൻ തുടങ്ങി. അയാളെ (കൽപനയില്ലാതെ) വധിച്ചാൽ റസൂൽ(സ) എന്തെങ്കിലും പറയുമോ എന്നും അദ്ദേഹം പേടിച്ചു. അയാൾ (നേർച്ച നേർന്നയാൾ) ഒന്നും ചെയ്യുന്നില്ലെന്ന് കണ്ടപ്പോൾ റസൂൽ(സ) അയാളുമായി ഉടമ്പടി ഉണ്ടാക്കി. അപ്പോൾ ആ (നേർച്ചനേർന്ന) മനുഷ്യൻ പറഞ്ഞു: പ്രവാചകരെ എന്റെ നേർച്ച. പ്രവാചകൻ(സ) പറഞ്ഞു: "ഞാൻ ഇതുവരെ പിടിച്ചുനിന്നത് നീ നേർച്ച പൂർത്തിയാക്കാൻ വേണ്ടിയായിരുന്നു." അപ്പോൾ അയാൾ പറഞ്ഞു: എന്താണ് താങ്കൾ എനിക്ക് കണ്ണുകൊണ്ട് സൂചന നൽകാതിരുന്നത്. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "ഒരു നബിക്കും കണ്ണ്കൊണ്ട് ആംഗ്യം കാണിക്കൽ ചേർന്നതല്ല." അബൂഗാലിബ് പയുന്നു: അന്യ സ്ത്രീക്ക് വേണ്ടി നിസ്കരിച്ചപ്പോൾ അവരുടെ നടുഭാഗത്തിനടുത്ത് നിന്നതിനെകുറിച്ച് ഞാൻ ചോദിച്ചു അപ്പോൾ അവർ എനിക്ക് പറഞ്ഞു തന്നു. അദ്ദേഹം അങ്ങനെ ചെയ്തത് ശവമഞ്ചത്തിൽ വെക്കാത്തതിനാലാണ്. അപ്പോൾ ഇമാം അവളുടെ നടുഭാഗം ജനങ്ങളിൽ നിന്ന് മറയത്തക്കവിധം നിൽക്കണം. (ദ,തു,ജ)', 'نَافِعٍ أَبِي غَالِبٍ قَالَ', null, null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 831, 832, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 269, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: صَلَّى عَلَى جِنَازَةِ رَجُلٍ فَقَامَ حِيَالَ رَأْسِهِ، فَجِيءَ بِجَنَازَةِ أُخْرَى بِامْرَأَةٍ، فَقَالُوا: يَا أَبَا حَمْزَةَ، صَلِّ عَلَيْهَا: فَقَامَ حِيَالَ وَسَطِ السَّرِيرِ، فَقَالَ لَهُ الْعَلَاءُ بْنُ زِيَادٍ: يَا أَبَا حَمْزَةَ، هَكَذَا رَأَيْتَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَامَ مِنَ الْجَنَازَةِ مُقَامَكَ مِنَ الرَّجُلِ، وَقَامَ مِنَ الْمَرْأَةِ مُقَامَكَ مِنَ الْمَرْأَةِ؟ قَالَ: نَعَمْ: فَأَقْبَلَ عَلَيْنَا فَقَالَ: احْفَظُوا. (د,ت,جه)', 'അനസുബ്നുമാലിക്(റ): അദ്ദേഹം ഒരു പുരുഷന്റെ ജനാസക്ക് വേണ്ടി അതിന്റെ തലയുടെ ഭാഗത്ത് നിന്ന് നിസ്കരിച്ചു. അപ്പോൾ ഒരു സ്ത്രീയുടെ ജനാസ കൊണ്ടുവന്നു. ജനങ്ങൾ പറഞ്ഞു: അബൂഹംസേ താങ്കൾ അതിന് നിസ്കരിക്കുക. അദ്ദേഹം കട്ടിലിന്റെ നടുഭാഗത്ത് നിന്നു. അപ്പോൾ അലാഅബ്നു സിയാദ് അദ്ദേഹത്തോട് ചോദിച്ചു: നിങ്ങൾ സ്ത്രീയുടെ നിസ്കാരത്തിൽ നിന്ന സ്ഥലത്തും പുരുഷന്റെ നിസ്കാരത്തിൽ നിന്ന സ്ഥലത്തും റസൂൽ(സ) നിൽക്കുന്നത് നിങ്ങൾ കണ്ടിട്ടുണ്ടോ? അദ്ദേഹം ''അതെ'' എന്ന് പറഞ്ഞു. അദ്ദേഹം ഞങ്ങളിലേക്ക് തിരിഞ്ഞിട്ട് പറഞ്ഞു: (ഇതാണ് സുന്നത്തെന്ന്) നിങ്ങൾ മനസ്സിലാക്കി വെക്കുക. (ദ,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 832, 832, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 270, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا لَمَّا تُوُفِّيَ سَعْدُ بْنُ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ أَرْسَلَ أَزْوَاجُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَمُرُّوا بِجَنَازَتِهِ فِي الْمَسْجِدِ، فَيُصَلِّينَ عَلَيْهِ، فَفَعَلُوا. فَوُقِفَ بِهِ عَلَى حُجَرِهِنَّ، يُصَلِّينَ عَلَيْهِ، أُخْرِجَ بِهِ مِنْ بَابِ الْجَنَائِزِ الَّذِي كَانَ إِلَى الْمَقَاعِدِ، فَبَلَغَهُنَّ أَنَّ النَّاسَ عَابُوا ذَلِكَ، وَقَالُوا: مَا كَانَتِ الْجَنَائِزُ يُدْخَلُ بِهَا الْمَسْجِدِ! فَبَلَغَ ذَلِكَ عَائِشَةَ، فَقَالَتْ: مَا أَسْرَعَ النَّاسَ إِلَى أَنْ يَعِيبُوا مَا لَا عِلْمَ لَهُمْ بِهِ! عَابُوا عَلَيْنَا أَنْ يُمَرَّ بِجَنَازَةٍ فِي الْمَسْجِدِ، وَمَا صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى سُهَيْلِ بْنِ بَيْضَاءَ إِلَّا فِي جَوْفِ الْمَسْجِدِ. (م)', 'ആഇശ(റ): സഅ്ദുബ്നു അബീവഖാസ്(റ) മരണപ്പെട്ടപ്പോൾ, ജനാസ പള്ളിയുടെ അടുത്തു കൂടെ കൊണ്ടു പോകണമെന്നും അവർക്ക് നിസ്കരിക്കണമെന്നുമുള്ള വിവരം പ്രവാചക പത്നിമാർ അറിയിച്ചു. അങ്ങനെ അവർ ചെയ്തു. അവരുടെ റൂമുകളുടെ അടുത്തു വെക്കുകയും അവർ നിസ്കരിക്കുകയും ചെയ്തു. ജനങ്ങൾ ഇരിക്കുന്ന സ്ഥലത്തേക്കുള്ള വാതിലിലൂടെ അതിനെ പുറത്തെടുക്കുകയും ചെയ്തു. ഇതിനെ ജനങ്ങൾ ആക്ഷേപിച്ച വിവരം പത്നിമാർക്കെത്തി. അവരുടെ അഭിപ്രായത്തിൽ ജനാസ പള്ളിയിൽ പ്രവേശിപ്പിക്കരുതെന്നായിരുന്നു. ഇതറിഞ്ഞ ആഇശ(റ) പറഞ്ഞു: അറിവില്ലാത്ത കാര്യത്തെപ്പറ്റി ജനങ്ങൾ എത്ര പെട്ടെന്നാണ് ആക്ഷേപിക്കുന്നത്? പള്ളിയിലൂടെ ജനാസ കൊണ്ടുപോകുന്നതിനെയാണ് അവർ ആക്ഷേപിച്ചത്. സുഹൈലുബ്നു ബൈദാഅ് എന്ന സഹാബിക്ക് നബി(സ) മയ്യിത്ത് നിസ്കരിച്ചത് പള്ളിയുടെ അകത്ത് വെച്ച് തന്നെയായിരുന്നു. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 832, 833, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 271, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: وَاللهِ مَا صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى سُهَيْلِ ابْنِ الْبَيْضَاءِ إِلَّا فِي الْمَسْجِدِ. وَفِي رِوَايَةٍ: قَالَتْ: وَاللهِ لَقَدْ صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى ابْنَيْ بَيْضَاءَ فِي الْمَسْجِدِ: سُهَيْلٍ، وَأَخِيه. (م,د,ت,ن,جه)', 'ആയിശ(റ): അല്ലാഹുവാണ് സത്യം, നബി(സ) സുഹൈലുബ്നു ബൈയ്ദാഇന്ന് പള്ളിയിൽ വെച്ചല്ലാതെ നിസ്കരിച്ചിട്ടില്ല. മറ്റൊരു റിപ്പോർട്ടിൽ: മഹതി പറഞ്ഞു: അല്ലാഹുവാണെ, ബൈദാഇന്റെ രണ്ട് മക്കളായ സുഹൈലിനും സഹോദരനും അല്ലാഹുവിന്റെ ദൂതൻ പള്ളിയിൽ വെച്ച് നിസ്കരിച്ചിരിക്കുന്നു. (മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 833, 833, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=271), 1, 'وَفِي رِوَايَةٍ: قَالَتْ: وَاللهِ لَقَدْ صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى ابْنَيْ بَيْضَاءَ فِي الْمَسْجِدِ: سُهَيْلٍ، وَأَخِيه. (م,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: മഹതി പറഞ്ഞു: അല്ലാഹുവാണെ, ബൈദാഇന്റെ രണ്ട് മക്കളായ സുഹൈലിനും സഹോദരനും അല്ലാഹുവിന്റെ ദൂതൻ പള്ളിയിൽ വെച്ച് നിസ്കരിച്ചിരിക്കുന്നു. (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 272, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَلَّى عَلَى جَنَازَةٍ فِي الْمَسْجِدِ فَلَا شَيْءَ عَلَيْهِ". (د,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും പള്ളിയിൽ വെച്ച് ജനാസ നിസ്കരിക്കുന്നതിന് യാതൊരു കുഴപ്പവുമില്ല." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 833, 833, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 273, 'عَنْ مَالِكِ بْنِ هُبَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ مُسْلِمٍ يَمُوتُ، فَيُصَلِّي عَلَيْهِ ثَلَاثَةُ صُفُوفٍ مِنَ الْمُسْلِمِينَ، إِلَّا أَوْجَبَ". فَكَانَ مَالِكٌ إِذَا اسْتَقَلَّ أَهْلَ الْجَنَازَةِ جَزَّأَهُمْ ثَلَاثَةَ صُفُوفٍ، لِلْحَدِيثِ. (د,ت,جه)', 'മാലിക്കുബ്നുഹുബൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു മുസ്ലിം മരിച്ചാൽ മൂന്ന് സ്വഫ്ഫ് മുസ്ലിംകൾ അയാൾക്കുവേണ്ടി നിസ്കരിച്ചാൽ സ്വർഗം അവന് ലഭിക്കാതിരിക്കില്ല." ഈ ഹദീസ് മനസ്സിലായതുമുതൽ മാലിക് ജനാസയുടെ ആളുകൾ കുറച്ചു മാത്രമാണുള്ളതെങ്കിൽ അവരെ മൂന്ന് സ്വഫാക്കിയിരുന്നു. (ദ,തു,ജ)', 'مَالِكِ بْنِ هُبَيْرَةَ', 'മാലിക്കുബ്നുഹുബൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 833, 833, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 274, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ صَلَّى عَلَيْهِ مِائَةٌ مِنَ الْمُسْلِمِينَ غُفِرَ لَهُ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞതായി അദ്ദേഹം റിപ്പോർട്ട് ചെയ്യുന്നു: "ആർക്കെങ്കിലും നൂറ് മുസലിംകൾ ജനാസ നിസ്കരിച്ചാൽ അവന്റെ പാപം പൊറുക്കപ്പെടും." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 833, 833, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 275, 'عَنْ كُرَيْبٍ مَوْلَى عَبْد اللهِ بْنِ عَبَّاسٍ – رَضِيَ اللهُ عَنْهُمَا – قَالَ: هَلَكَ ابْنٌ لِعَبْد اللهِ بْنِ عَبَّاسٍ، فَقَالَ لِي: يَا كُرَيْبُ، قُمْ فَانْظُرْ: هَلِ اجْتَمَعَ لِابْنِي أَحَدٌ؟ فَقُلْتُ: نَعَمْ. فَقَالَ: وَيْحَكَ، كَمْ تَرَاهُمْ، أَرْبَعِينَ؟ قُلْتُ: لَا، بَلْ هُمْ أَكْثَرُ. قَالَ: فَاخْرُجُوا بِابْنِي، فَأَشْهَدُ لَسَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ أَرْبَعِينَ مِنْ مُؤْمِنٍ يَشْفَعُونَ لِمُؤْمِنٍ إِلَّا شَفَّعَهُمُ اللهُ". (م,د,جه)', 'ഇബ്നുഅബ്ബാസിന്റെ അടിമ കുറൈബ്(റ): അബ്ദുല്ലാഹിബ്നു അബ്ബാസി(റ)ന്റെ മകൻ മരിച്ചു. അപ്പോൾ അദ്ദേഹം എന്നോട് പറഞ്ഞു: കുറൈബേ! എന്റെ മകന് വേണ്ടി ആരെങ്കിലും ഒരുമിച്ച് കൂടിയിരിക്കുന്നോ എന്നു നീ എഴുന്നേറ്റു നോക്കുക. ഞാൻ പറഞ്ഞു: അതെ. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: എത്രയാളുണ്ട്? നാൽപത് പേരുണ്ടോ? അല്ല അതിലധികമുണ്ടെന്ന് ഞാൻ പറഞ്ഞു. അദ്ദേഹം പറഞ്ഞു: എന്നാൽ എന്റെ മകനെ പുറത്തെടുക്കൂ. നബി(സ) പറഞ്ഞതിന് ഞാൻ സാക്ഷിയാണ്. നബി(സ) ഇപ്രകാരം പറഞ്ഞു: "ഒരു മുഅ്മിനിന്ന് വേണ്ടി നാൽപത് മുഅ്മിനുകൾ ശുപാർശ ചെയ്താൽ അല്ലാഹു ആ ശുപാർശ സ്വീകരിക്കുക തന്നെ ചെയ്യും." (മു,ദ,ജ)', 'كُرَيْبٍ مَوْلَى عَبْد اللهِ بْنِ عَبَّاسٍ –', 'ഇബ്നുഅബ്ബാസിന്റെ അടിമ കുറൈബ്(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 834, 834, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 276, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَمُوتُ أَحَدٌ مِنَ الْمُسْلِمِينَ، فَتُصَلِّيَ عَلَيْهِ أُمَّةٌ مِنَ الْمُسْلِمِينَ يَبْلُغُونَ أَنْ يَكُونُوا مِائَةً، فَيَشْفَعُوا لَهُ، إِلَّا شُفِّعُوا فِيهِ". حَسَنٌ صَحِيحٌ. (م,ت,ن)', 'നബി(സ) പറഞ്ഞതായി ആയിശ(റ): "മുസ്ലിംകളിൽ നിന്നുള്ള ഒരാൾ മരിക്കുകുയും മുസ്ലിം ഉമ്മത്തിൽ നിന്ന് നൂറോളം ആളുകൾ അയാൾക്ക് വേണ്ടി നിസ്കരിക്കുകയും ശുപാർശ ചെയ്യുകയും ചെയ്താൽ അവരുടെ ശുപാർശ സ്വീകരിക്കുക തന്നെ ചെയ്യും." ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി. (മു,തു,ന)', 'عَائِشَةَ', 'നബി(സ) പറഞ്ഞതായി ആയിശ(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 834, 834, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 277, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ – يَرْوِيه – قَالَ: "مَنْ تَبِعَ جَنَازَةً فَصَلَّى عَلَيْهَا فَلَهُ قِيرَاطٌ، وَمَنْ تَبِعَهَا حَتَّى يُفْرَغَ مِنْهَا فَلَهُ قِيرَاطَانِ أَصْغَرُهُمَا مِثْلُ أُحُدٍ. أَوْ: أَحَدُهُمَا مِثْلُ أُحُدٍ". (ق,ت,ن,جه)', 'അബൂഹുറൈറ(റ): "ആരെങ്കിലും ജനാസയെ തുടരുകയും അതിനുവേണ്ടി നിസ്കരിക്കുകയും ചെയ്താൽ അവന് രണ്ട് ഖീറാത്വുണ്ട്. അതിൽ നിന്ന് വിരമിക്കുന്നവരെ തുടർന്നാൽ അവന്ന് രണ്ട് ഖീറാത്വുണ്ട്. ആ രണ്ടിൽ ഏറ്റവും ചെറുത് ഉഹ്ദ് മലപോലെയാണ്. അല്ലങ്കിൽ അതിലൊന്ന് ഉഹ്ദ് പർവ്വതം പോലെയാണ്." (ബു,മു,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 834, 834, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 278, 'عَنْ عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ: أَنَّهُ كَانَ عِنْدَ ابْنِ عُمَرَ بْنِ الْخَطَّابِ – رَضِيَ اللهُ عَنْهُمَا – إِذْ طَلَعَ خَبَّابٌ فَقَالَ: يَا عَبْدَ اللهِ بْنَ عُمَرَ، أَلَا تَسْمَعُ مَا يَقُولُ أَبُو هُرَيْرَةَ؟ أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ خَرَجَ مَعَ جَنَازَةٍ مِنْ بَيْتِهَا وَصَلَّى عَلَيْهَا". فَذَكَرَ مَعْنَى الْحَدِيثِ. فَأَرْسَلَ ابْنُ عُمَرَ إِلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا فَقَالَتْ: صَدَقَ أَبُو هُرَيْرَةَ. (م,د)', 'ആമിറുബ്നു സഅ്ദ്ബ്നു അബീവഖാസ്: അദ്ദേഹം ഇബ്നുഉമറി(റ)ന്റെ അടുത്തായിരുന്നപ്പോൾ ഖബ്ബാബ്(റ) അവിടെ എത്തി, എന്നിട്ട് പറഞ്ഞു: അബ്ദുല്ലാഹിബ്നു ഉമറേ! അബൂഹുറൈറ(റ) പറയുന്നത് നിങ്ങൾ കേൾക്കുന്നില്ലയോ? പ്രവാചകൻ(സ) ഇപ്രകാരം പറയുന്നതായി അദ്ദേഹം കേട്ടിരിക്കുന്നു: "ആരെകിലും വീട്ടിൽ നിന്നും ജനാസയോടൊപ്പം പുറപ്പെടുകയും അതിന്ന് നിസ്കരിക്കുകയും ചെയ്താൽ....." എന്നിട്ട് അദ്ദേഹം ഹദീസിന്റെ ആശയം പറഞ്ഞു. അപ്പോൾ ഇബ്നുഉമർ(റ) ആഇശ(റ)യുടെ അടുക്കൽ ആളെ അയച്ചു. മഹതി പറഞ്ഞു: അബൂഹുറൈറ(റ) സത്യം പറഞ്ഞിരിക്കുന്നു. (മു,ദ)', 'عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'ആമിറുബ്നു സഅ്ദ്ബ്നു അബീവഖാസ്', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 834, 834, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 279, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ شَهِدَ الْجَنَازَةَ حَتَّى يُصَلَّى عَلَيْهَا فَلَهُ قِيرَاطٌ، وَمَنْ شَهِدَهَا حَتَّى تُدْفَنَ فَلَهُ قِيرَاطَانِ". قِيلَ: وَمَا الْقِيرَاطَانِ؟ قَالَ: "مِثْلُ الْجَبَلَيْنِ الْعَظِيمَيْنِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു ജനാസയുടെ അടുത്ത് നിസ്കരിക്കുന്നത് വരെ ഹാജരായാൽ അവന് ഒരു ഖീറാത്വുണ്ട്. ആരെങ്കിലും അത് മറമാടപ്പെടുന്നത് വരെ അവിടെ നിന്നാൽ അവന് രണ്ട് ഖീറാത്വുണ്ട്." അപ്പോൾ ചോദ്യമുയർന്നു: രണ്ട് ഖീറാത് എന്നത് എന്താണ്? പ്രവാചകൻ(സ) പറഞ്ഞു: "രണ്ട് മഹാപർവ്വതങ്ങൾ പോലുള്ളതാണത്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 834, 835, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 280, 'عَنْ عَبْد اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ مَاتَ ابْنٌ لَهُ بِقُدَيْدٍ أَوْ بِعُسْفَانَ، فَقَالَ: يَا كُرَيْبُ، انْظُرْ مَا اجْتَمَعَ لَهُ مِنَ النَّاسِ، قَالَ: فَخَرَجْتُ، فَإِذَا نَاسٌ قَدِ اجْتَمَعُوا لَهُ، فَأَخْبَرْتُهُ. فَقَالَ: تَقُولُ: هُمْ أَرْبَعُونَ؟ قَالَ: نَعَمْ، قَالَ: أَخْرِجُوهُ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ رَجُلٍ مُسْلِمٍ يَمُوتُ، فَيَقُومُ عَلَى جَنَازَتِهِ أَرْبَعُونَ رَجُلًا، لَا يُشْرِكُونَ بِاللهِ شَيْئًا، إِلَّا شَفَّعَهُمُ اللهُ فِيهِ". (م)', 'ഇബ്നുഅബ്ബാസ്(റ): ഉസ്ഫാനിലോ ഖുദൈദിലോ വെച്ച് അദ്ദേഹത്തിന്റെ ഒരു മകൻ മരിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: കുറൈബേ, അവന്ന് വേണ്ടി ജനങ്ങൾ ഒരുമിച്ച് കൂടിയത് എത്രപേരുണ്ടെന്ന് നീ നോക്കുക! കുറൈബ് പറയുന്നു: അങ്ങിനെ ഞാൻ പുറപ്പെട്ടു. അപ്പോഴതാ കുറച്ചാളുകൾ അവന്ന് വേണ്ടി ഒരുമിച്ച് കൂടിയിരിക്കുന്നു. ഞാൻ അദ്ദേഹത്തോട് ആ വിവരം പറഞ്ഞ് കൊടുത്തു. അദ്ദേഹം ചോദിച്ചു: അവർ നാൽപത് പേരുണ്ടെന്നാണോ നീ പറയുന്നത്? ഞാൻ പറഞ്ഞു: അതെ. അദ്ദേഹം പറഞ്ഞു: നിങ്ങൾ അവനെയും കൊണ്ട് പുറപ്പെടുക. "നിങ്ങളിൽ നിന്ന് ആരെങ്കിലും മരിക്കുകയും അല്ലാഹുവിങ്കൽ പങ്ക് ചേർക്കാത്ത നാൽപത് പേർ അവന് വേണ്ടി നമസ്കരിക്കുകയും ചെയ്താൽ അല്ലാഹു അവരുടെ ശുപാർശ സ്വീകരിക്കുക തന്നെ ചെയ്യും" എന്നു നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടിരിക്കുന്നു. (മു)', 'عَبْد اللهِ بْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 835, 835, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 281, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ مَيِّتٍ تُصَلِّي عَلَيْهِ أُمَّةٌ مِنَ الْمُسْلِمِينَ يَبْلُغُونَ مِائَةً – كُلُّهُمْ يَشْفَعُونَ لَهُ – إِلَّا شُفِّعُوا فِيهِ". (م,د,ن,جه)', 'നബി(സ)ൽ നിന്ന് ആഇശ(റ): "മുസ്ലിം ഉമ്മത്തിൽ നിന്ന് നൂറ് ആളുകൾ ഏതെങ്കിലും മയ്യിത്തിന് വേണ്ടി നിസ്കരിച്ചാൽ, എല്ലാവരും അവന് വേണ്ടി ശുപാർശ തേടികൊണ്ട്, അവന്റെ കാര്യത്തിൽ അവരുടെ ശുപാർശ സ്വീകരിക്കപ്പെടുക തന്നെ ചെയ്യും." (മു,ദ,ന,ജ)', 'عَائِشَةَ', 'നബി(സ)ൽ നിന്ന് ആഇശ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 835, 835, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 282, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَلَّى عَلَى جَنَازَةٍ فَلَهُ قِيرَاطٌ، وَمَنِ انْتَظَرَهَا حَتَّى تُوضَعَ فِي اللَّحْدِ فَلَهُ قِيرَاطَانِ، وَالْقِيرَاطَانِ مِثْلُ الْجَبَلَيْنِ الْعَظِيمَيْنِ". وَفِي رِوَايَةٍ: "مَنْ شَهِدَ جَنَازَةً حَتَّى يُصَلَّى عَلَيْهَا فَلَهُ قِيرَاطٌ، وَمَنْ شَهِدَ حَتَّى تُدْفَنَ فَلَهُ قِيرَاطَانِ". قِيلَ: وَمَا الْقِيرَاطَانِ يَا رَسُولَ اللهِ؟ قَالَ: "مِثْلُ الْجَبَلَيْنِ الْعَظِيمَيْنِ". وَفِي رِوَايَةٍ: "مَنْ تَبِعَ جَنَازَةَ رَجُلٍ مُسْلِمٍ احْتِسَابًا، فَصَلَّى عَلَيْهَا وَدَفَنَهَا، فَلَهُ قِيرَاطَانِ. وَمَنْ صَلَّى عَلَيْهَا ثُمَّ رَجَعَ قَبْلَ أَنْ تُدْفَنَ فَإِنَّهُ يَرْجِعُ بِقِيرَاطٍ مِنَ الْأَجْرِ". وَفِي رِوَايَةٍ: "مَنْ تَبِعَ جَنَازَةً فَصَلَّى عَلَيْهَا ثُمَّ انْصَرَفَ فَلَهُ قِيرَاطٌ مِنَ الْأَجْرِ، وَمَنْ تَبِعَهَا فَصَلَّى عَلَيْهَا ثُمَّ قَعَدَ حَتَّى يُفْرَغَ مِنْ دَفْنِهَا فَلَهُ قِيرَاطَانِ مِنَ الْأَجْرِ، كُلُّ وَاحِدٍ مِنْهُمَا أَعْظَمُ مِنْ أُحُدٍ". (ق,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു ജനാസക്ക് വേണ്ടി നിസ്കരിച്ചാൽ അവന് ഒരു ഖീറാത്വുണ്ട്. അത് ലഹ്ദിൽ വെക്കുന്നത് വരെ കാത്തിരുന്നവന് രണ്ട് ഖിറാത്വുണ്ട്. രണ്ട് ഖിറാത്വുകൾ വലിയ രണ്ട് മലകൾ പോലെയാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ: "ആരെങ്കിലും ഒരു ജനാസ നിസ്കാരം കഴിയുന്നത് വരെ അവിടെ ഉണ്ടായാൽ അവന് ഒരു ഖീറാത്വുണ്ട്. അത് മറമാടപ്പെടുന്നതുവരെ കാത്തിരുന്നാൽ അവന് രണ്ട് ഖീറാത്വുണ്ട്." അപ്പോൾ ചോദിക്കപ്പെട്ടു: എന്താണ് റസൂലേ രണ്ട് ഖിറാത്വുകൾ? പ്രവാചകൻ(സ) പറഞ്ഞു: "വലിയ രണ്ട് പർവ്വതങ്ങൾ പോലെയാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ: "ആരെങ്കിലും പ്രതിഫലം കാംക്ഷിച്ചുകൊണ്ട് ഒരു മുസ്ലിമിന്റെ ജനാസ പിന്തുടരുകയും അതിന് വേണ്ടി നിസ്കരിക്കുകയും മറമാടുകയും ചെയ്താൽ അവന് രണ്ട് ഖീറാത്വുകൾ ഉണ്ട്. ആരെങ്കിലും നിസ്കരിക്കുക മാത്രം ചെയ്ത് മറമാടുന്നതിന് മുമ്പ് മടങ്ങിയാൽ അവൻ മടങ്ങുന്നത് പ്രതിഫലത്തിൽ നിന്ന് ഒരു ഖീറാത്വുകൊണ്ടായിരിക്കും." മറ്റൊരു റിപ്പോർട്ടിൽ: "ആരെങ്കിലും ജനാസയെ പിന്തുടരുകയും അതിന് വേണ്ടി നിസ്കരിക്കുകയും എന്നിട്ട് പിരിഞ്ഞ് പോകുകയും ചെയ്താൽ അവന് പ്രതിഫലമായി ഒരു ഖീറാത്വു ലഭിക്കും. ആരെങ്കിലും അതിനെ പിന്തുടരുകയും അതിന് വേണ്ടി നിസ്കരിക്കുകയും എന്നിട്ട് അത് മറമാടപ്പെടുന്നത് വരെ അവിടെ ഇരിക്കുകയും ചെയ്താൽ അവന് രണ്ട് ഖീറാത്വു പ്രതിഫലം ലഭിക്കും. അവ രണ്ടിൽ ഓരോന്നും ഉഹ്ദിനേക്കാൾ വലുതാണ്." (ബു,മു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 835, 836, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=282), 1, 'وَفِي رِوَايَةٍ: "مَنْ شَهِدَ جَنَازَةً حَتَّى يُصَلَّى عَلَيْهَا فَلَهُ قِيرَاطٌ، وَمَنْ شَهِدَ حَتَّى تُدْفَنَ فَلَهُ قِيرَاطَانِ". قِيلَ: وَمَا الْقِيرَاطَانِ يَا رَسُولَ اللهِ؟ قَالَ: "مِثْلُ الْجَبَلَيْنِ الْعَظِيمَيْنِ".', 'മറ്റൊരു നിവേദനിൽ: "ആരെങ്കിലും ഒരു ജനാസ നിസ്കാരം കഴിയുന്നത് വരെ അവിടെ ഉണ്ടായാൽ അവന് ഒരു ഖീറാത്വുണ്ട്. അത് മറമാടപ്പെടുന്നതുവരെ കാത്തിരുന്നാൽ അവന് രണ്ട് ഖീറാത്വുണ്ട്." അപ്പോൾ ചോദിക്കപ്പെട്ടു: എന്താണ് റസൂലേ രണ്ട് ഖിറാത്വുകൾ? പ്രവാചകൻ(സ) പറഞ്ഞു: "വലിയ രണ്ട് പർവ്വതങ്ങൾ പോലെയാണ്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=282), 2, 'وَفِي رِوَايَةٍ: "مَنْ تَبِعَ جَنَازَةَ رَجُلٍ مُسْلِمٍ احْتِسَابًا، فَصَلَّى عَلَيْهَا وَدَفَنَهَا، فَلَهُ قِيرَاطَانِ. وَمَنْ صَلَّى عَلَيْهَا ثُمَّ رَجَعَ قَبْلَ أَنْ تُدْفَنَ فَإِنَّهُ يَرْجِعُ بِقِيرَاطٍ مِنَ الْأَجْرِ".', 'മറ്റൊരു നിവേദനിൽ: "ആരെങ്കിലും പ്രതിഫലം കാംക്ഷിച്ചുകൊണ്ട് ഒരു മുസ്ലിമിന്റെ ജനാസ പിന്തുടരുകയും അതിന് വേണ്ടി നിസ്കരിക്കുകയും മറമാടുകയും ചെയ്താൽ അവന് രണ്ട് ഖീറാത്വുകൾ ഉണ്ട്. ആരെങ്കിലും നിസ്കരിക്കുക മാത്രം ചെയ്ത് മറമാടുന്നതിന് മുമ്പ് മടങ്ങിയാൽ അവൻ മടങ്ങുന്നത് പ്രതിഫലത്തിൽ നിന്ന് ഒരു ഖീറാത്വുകൊണ്ടായിരിക്കും."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=282), 3, 'وَفِي رِوَايَةٍ: "مَنْ تَبِعَ جَنَازَةً فَصَلَّى عَلَيْهَا ثُمَّ انْصَرَفَ فَلَهُ قِيرَاطٌ مِنَ الْأَجْرِ، وَمَنْ تَبِعَهَا فَصَلَّى عَلَيْهَا ثُمَّ قَعَدَ حَتَّى يُفْرَغَ مِنْ دَفْنِهَا فَلَهُ قِيرَاطَانِ مِنَ الْأَجْرِ، كُلُّ وَاحِدٍ مِنْهُمَا أَعْظَمُ مِنْ أُحُدٍ". (ق,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: "ആരെങ്കിലും ജനാസയെ പിന്തുടരുകയും അതിന് വേണ്ടി നിസ്കരിക്കുകയും എന്നിട്ട് പിരിഞ്ഞ് പോകുകയും ചെയ്താൽ അവന് പ്രതിഫലമായി ഒരു ഖീറാത്വു ലഭിക്കും. ആരെങ്കിലും അതിനെ പിന്തുടരുകയും അതിന് വേണ്ടി നിസ്കരിക്കുകയും എന്നിട്ട് അത് മറമാടപ്പെടുന്നത് വരെ അവിടെ ഇരിക്കുകയും ചെയ്താൽ അവന് രണ്ട് ഖീറാത്വു പ്രതിഫലം ലഭിക്കും. അവ രണ്ടിൽ ഓരോന്നും ഉഹ്ദിനേക്കാൾ വലുതാണ്." (ബു,മു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 283, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَلَّى عَلَى جَنَازَةٍ فَلَهُ قِيرَاطٌ، وَمَنْ شَهِدَهَا حَتَّى تُدْفَنَ فَلَهُ قِيرَاطَانِ. وَالَّذِي نَفْسُ مُحَمَّد بِيَدِه، الْقِيرَاطُ أَعْظَمُ مِنْ أُحُدٍ هَذَا". [ز: في إسناده ضعيف ومدلس عنعنه] (جه)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു ജനാസ നിസ്കരിച്ചാൽ അവന് ഒരു ഖീറാത്വുണ്ട്. മറമാടപ്പെടുന്നത് വരെ അവിടെ നിന്നവന് രണ്ട് ഖീറാത്വുണ്ട്. ആരുടെ കയ്യിലാണോ മുഹമ്മദിന്റെ ആത്മാവുള്ളത് അവൻതന്നെ സത്യം, ഖീറാത്ത് ഈ ഉഹ്ദ് മലയേക്കാൾ വലുതാണ്." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനും ഇതിനെ അൻഅനയാക്കി ഉദ്ധരിച്ച മുദല്ലിസുമുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف ومدلس عنعنه', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനും ഇതിനെ അൻഅനയാക്കി ഉദ്ധരിച്ച മുദല്ലിസുമുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 836, 836, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 284, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى عُثْمَانَ بْنِ مَظْعُونٍ، وَكَبَّرَ عَلَيْهِ أَرْبَعًا. [ز: في سنده راو متفق علي تضعيفه] (جه)', 'ഉസ്മാനുബ്നു അഫാൻ(റ): നബി(സ) ഉസ്മാനുബ്നു മദ്ഊനി(റ)ന് വേണ്ടി മയ്യിത്ത് നിസ്കരിച്ചു. തിരുമേനി(സ) നാല് തക്ബീർ ചൊല്ലി. (ഇതിന്റെ സനദിൽ ദുർബലനെന്ന് ഐക്യകണ്ഠേന പറയപ്പെട്ട റാവിയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാനുബ്നു അഫാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده راو متفق علي تضعيفه', 'ഇതിന്റെ സനദിൽ ദുർബലനെന്ന് ഐക്യകണ്ഠേന പറയപ്പെട്ട റാവിയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 836, 836, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 285, 'عَنْ إِبْرَاهِيمَ بْنِ مُسْلِمٍ الْهَجَرِيِّ قَالَ: صَلَّيْتُ مَعَ عَبْدِ اللهِ بْنِ أَبِي أَوْفَى الْأَسْلَمِيِّ، رَضِيَ اللهُ عَنْهُمَا – صَاحِب رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – عَلَى جَنَازَة ابْنَة لَهُ، فَكَبَّرَ عَلَيْهَا أَرْبَعًا، فَمَكَثَ بَعْدَ الرَّابِعَة شَيْئًا، قَالَ: فَسَمِعْتُ الْقَوْمَ يُسَبِّحُونَ بِهِ مِنْ نَوَاحِي الصُّفُوفِ، فَسَلَّمَ ثُمَّ قَالَ: أَكُنْتُمْ تَرَوْنَ أَنِّي مُكَبِّرٌ خَمْسًا؟ قَالُوا: تَخَوَّفْنَا ذَلِكَ. قَالَ: لَمْ أَكُنْ لِأَفْعَلَ، وَلَكِنْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُكَبِّرُ أَرْبَعًا، ثُمَّ يَمْكُثُ سَاعَةً، فَيَقُولُ مَا شَاءَ اللهُ أَنْ يَقُولَ، ثُمَّ يُسَلِّمُ. [ز: في سنده ضعيف] (جه)', 'ഇബ്റാഹീമുബ്നുൽ മുസ്ലിമുൽ ഹജരിയ്യ്(റ): ഞാൻ അബ്ദുല്ലാഹിബ്നു അബീഔഫ(റ)യുടെ കൂടെ അദ്ദേഹത്തിന്റെ ഒരു മകളുടെ ജനാസ നിസ്കരിച്ചു. അദ്ദേഹം അതിന്ന് വേണ്ടി നാല് തക്ബീർ ചൊല്ലി. നാലാമത്തെ തക്ബീറിന്ന് ശേഷം അൽപം താമസിച്ചു. അപ്പോൾ സ്വഫ്ഫിന്റെ ഭാഗങ്ങളിൽ നിന്ന് ജനങ്ങൾ തസ്ബീഹ് ചൊല്ലുന്നത് ഞാൻ കേട്ടു. തുടർന്ന് അദ്ദേഹം സലാം വീട്ടി. പിന്നെ ചോദിച്ചു. ഞാൻ അഞ്ച് തക്ബീർ ചൊല്ലുമെന്ന് നിങ്ങൾ വിചാരിച്ചോ? അവർ പറഞ്ഞു: അങ്ങനെയുണ്ടാകുമെന്ന് ഞങ്ങൾ ഭയപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: ഞാൻ അങ്ങനെ ചെയ്യുകയില്ല. എന്നാൽ നബി(സ) നാല് തക്ബീറായിരുന്നു ചൊല്ലിയിരുന്നത്. എന്നിട്ട് കുറച്ചു സമയം താമസിക്കും. അപ്പോൾ അല്ലാഹു ഉദ്ദേശിച്ചത് അവിടുന്ന് ചൊല്ലും. പിന്നെ സലാം വീട്ടും. (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'إِبْرَاهِيمَ بْنِ مُسْلِمٍ الْهَجَرِيِّ قَالَ', 'ഇബ്റാഹീമുബ്നുൽ മുസ്ലിമുൽ ഹജരിയ്യ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 836, 837, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 286, 'عَنِ الشَّعْبِيِّ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِقَبْرٍ رَطْبٍ فَصَفُّوا عَلَيْهِ، وَكَبَّرَ عَلَيْهِ أَرْبَعًا، فَقِيلَ: مَنْ حَدَّثَكَ؟ قَالَ: الثِّقَةُ مَنْ شَهِدَهُ عَبْدُ اللهِ بْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا. (ق,د)', 'ശഅ്ബിയ്യ്(റ): നബി(സ) ഒരു നനവുള്ള ഖബറിന്റെ അടുത്തുകൂടെ നടന്നു പോയി. അപ്പോൾ അവർ അവിടെ അണിയായി നിന്നു. എന്നിട്ട് നാല് തക്ബീർ ചൊല്ലി. ആരാണിത് താങ്കളോട് പറഞ്ഞത് എന്ന് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: ഒരു വിശ്വസ്തൻ, അവിടെ സൻഹിതരായിരുന്ന അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ). (ബു,മു,ദ)', 'الشَّعْبِيِّ', 'ശഅ്ബിയ്യ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 837, 837, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 287, 'عَنِ ابْنِ أَبِي لَيْلَى قَالَ: كَانَ زَيْدُ بْنُ أَرْقَمَ رَضِيَ اللهُ عَنْهُ يُكَبِّرُ عَلَى جَنَائِزِنَا أَرْبَعًا، وَإِنَّهُ كَبَّرَ عَلَى جَنَازَةٍ خَمْسًا، فَسَأَلْتُهُ، فَقَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُكَبِّرُهَا. (م,د,ت,ن,جه)', 'ഇബ്നുഅബീലൈല(റ): സൈദുബ്നു അർഖം(റ) ഞങ്ങളിൽ നിന്നുള്ള ജനാസകൾക്ക് നാല് തക്ബീർ ചൊല്ലാറുണ്ടായിരുന്നു. ഒരു ജനാസക്ക് അദ്ദേഹം അഞ്ച് തക്ബീറുകൾ ചൊല്ലി. ഞാൻ അദ്ദേഹത്തോട് ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ) അപ്രകാരം തക്ബീർ ചൊല്ലിയിരുന്നു. (മു,ദ,തു,ന,ജ)', 'ابْنِ أَبِي لَيْلَى قَالَ', 'ഇബ്നുഅബീലൈല(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 837, 837, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 288, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرِضَت امْرَأَة مِنْ أَهْلِ الْعَوَالِي، وَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَحْسَنَ شَيْءٍ عِيَادَةً لِلْمَرِيضِ، فَقَالَ: "إِذَا مَاتَتْ فَآذِنُونِي". فَمَاتَتْ لَيْلًا، فَدَفَنُوهَا وَلَمْ يُعْلِمُوا النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا أَصْبَحَ سَأَلَ عَنْهَا فَقَالُوا: كَرِهْنَا أَنْ نُوقِظَكَ يَا رَسُولَ اللهِ. فَأَتَى قَبْرَهَا فَصَلَّى عَلَيْهَا وَكَبَّرَ أَرْبَعًا. (ن)', 'അബൂഉമാമത്തുബ്നു സഹ്ൽ(റ): അവാലി ഗോത്രത്തിൽപെട്ട ഒരു സ്ത്രീ രോഗിണിയായി. നബി(സ) രോഗിയെ ഏറ്റവും നന്നായി സന്ദർശിച്ചിരുന്നു. തിരുമേനി(സ) പറഞ്ഞു: "അവൾ മരിച്ചാൽ നിങ്ങൾ എന്നെ വിവരമറിയിക്കുക." അങ്ങനെ അവൾ രാത്രിയിൽ മരിച്ചു. നബി(സ)യെ അറിയിക്കാതെ അവർ ആ സ്ത്രീയെ മറമാടി. പ്രഭാതമായപ്പോൾ നബി(സ) അവളെ കുറിച്ച് ചോദിച്ചു. അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ! താങ്കളെ ഉണർത്തുന്നത് ഞങ്ങൾ ഇഷ്ടപ്പെട്ടില്ല. അപ്പോൾ നബി(സ) അവളുടെ ഖബറിന്റെ അടുത്തു ചെന്ന് നാല് തക്ബീറുകൾ ചൊല്ലി. (ന)', 'أَبِي أُمَامَةَ بْنِ سَهْلٍ', 'അബൂഉമാമത്തുബ്നു സഹ്ൽ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 837, 837, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 289, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَعَى لِلنَّاسِ النَّجَاشِيَ فِي الْيَوْمِ الَّذِي مَاتَ فِيه، فَخَرَجَ بِهِمْ إِلَى الْمُصَلَّى، وَكَبَّرَ أَرْبَعَ تَكْبِيرَاتٍ. (ق,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നജ്ജാശി മരിച്ച ദിവസം നബി(സ) ജനങ്ങളെ മരണവിവരം അറിയിച്ചു. അവരുമായി പ്രവാചകൻ(സ) നിസ്കാരസ്ഥലത്തേക്ക് പുറപ്പെട്ടു. എന്നിട്ട് നാല് തക്ബീറുകൾ ചൊല്ലി. (ബു,മു,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 837, 837, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 290, 'عَنْ عَمْرِو بْنِ عَوْفِ بْنِ زَيْدٍ الْمُزَنِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَبَّرَ خَمْسًا. [ز: شديد الضعف] (جه)', 'അംറുബ്നു ഔഫ്(റ): റസൂൽ(സ) അഞ്ച് തക്ബീറുകൾ ചൊല്ലി (ഹദീസ് അങ്ങേയറ്റം ദുർബ്ബലമാണെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'عَمْرِو بْنِ عَوْفِ بْنِ زَيْدٍ الْمُزَنِيِّ', 'അംറുബ്നു ഔഫ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: شديد الضعف', 'ഹദീസ് അങ്ങേയറ്റം ദുർബ്ബലമാണെന്ന് ഇബ്നുമാജ പറയുന്നു', 837, 837, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 291, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ النَّجَاشِيَّ قَدْ مَاتَ". فَخَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ إِلَى الْبَقِيعِ فَصَفَّنَا خَلْفَهُ، وَتَقَدَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَكَبَّرَ أَرْبَعَ تَكْبِيرَاتٍ. (خ,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നജ്ജാശി മരിച്ചിരിക്കുന്നു." നബി(സ)യും അനുചരന്മാരും ബഖീഇലേക്ക് പുറപ്പെട്ടു. ഞങ്ങളെ തിരുമേനി(സ) അവിടുത്തെ പിന്നിൽ അണിയായി നിരത്തി. നബി(സ) മുന്നിൽ (ഇമാമായി) നിൽക്കുകയും നാല് തക്ബീറുകൾ ചൊല്ലുകയും ചെയ്തു. (ബു,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ت','ن','جه']::text[], array['ബു','തു','ന','ജ']::text[], null, null, 838, 838, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 292, 'عَنْ عِمْرَانَ بْنِ الْحُصَيْنِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ أَخَاكُمُ النَّجَاشِيَّ قَدْ مَاتَ، فَصَلُّوا عَلَيْهِ". قَالَ: فَقَامَ فَصَلَّيْنَا خَلْفَهُ، وَإِنِّي لَفِي الصَّفِّ الثَّانِي، فَصَلَّى عَلَيْهِ صَفَّيْنِ. (ت,ن,جه)', 'ഇംറാനുബ്നുൽ ഹുസൈൻ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ സഹോദരൻ നജ്ജാശി മരിച്ചിരിക്കുന്നു. അത് കൊണ്ട് നിങ്ങൾ അദ്ദേഹത്തിന് വേണ്ടി നിസ്കരിക്കുവിൻ." അങ്ങനെ നബി(സ) എഴുന്നേറ്റു നിന്ന് നിസ്കരിച്ചു, പിന്നിൽ നിന്ന് ഞങ്ങളും. ഞാൻ രണ്ടാം സ്വഫ്ഫിലായിരുന്നു. അങ്ങനെ രണ്ട് സ്വഫ്ഫായി നിസ്കരിച്ചു. (തു,ന,ജ)', 'عِمْرَانَ بْنِ الْحُصَيْنِ', 'ഇംറാനുബ്നുൽ ഹുസൈൻ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 838, 838, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 293, 'عَنْ حُذَيْفَةَ بْنِ أَسِيدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ بِهِمْ فَقَالَ: "صَلُّوا عَلَى أَخٍ لَكُمْ مَاتَ بِغَيْرِ أَرْضِكُمْ". قَالُوا: مَنْ هُوَ؟ قَالَ: "النَّجَاشِيُّ". (جه)', 'ഹുദൈഫ(റ): നബി(സ) അവരേയും (സ്വഹാബികളേയും) കൊണ്ട് പുറപ്പെട്ടു. എന്നിട്ട് പറഞ്ഞു: "നിങ്ങളുടെ നാടിന് പുറത്തു വെച്ച് മരിച്ച നിങ്ങളുടെ സഹോദരന് വേണ്ടി നിങ്ങൾ നിസ്കരിക്കുക." അവർ ചോദിച്ചു: ആരാണത്? പ്രവാചകൻ(സ) പ്രതിവചിച്ചു: "നജ്ജാശിയാണത്." (ജ)', 'حُذَيْفَةَ بْنِ أَسِيدٍ', 'ഹുദൈഫ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 838, 838, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 294, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ فِي الصَّفِّ الثَّانِي يَوْمَ صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى النَّجَاشِيِّ. (ن)', 'ജാബിർ(റ): നബി(സ) നജ്ജാശിക്ക് വേണ്ടി നിസ്കരിച്ച ദിവസം ഞാൻ രണ്ടാം സ്വഫ്ഫിലായിരുന്നു. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 838, 838, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 295, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نَنْطَلِقَ إِلَى أَرْضِ النَّجَاشِيِّ،... قَالَ النَّجَاشِيُّ: أَشْهَدُ أَنَّهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَأَنَّهُ الَّذِي بَشَّرَ بِهِ عِيسَى ابْنُ مَرْيَمَ، وَلَوْلَا مَا أَنَا فِيه مِنَ الْمُلْك لَأَتَيْتُهُ حَتَّى أَحْمِلَ نَعْلَيْه. (د)', 'അബൂമൂസാ(റ): നബി(സ) ഞങ്ങളോട് നജ്ജാശിയുടെ നാട്ടിലേക്ക് പോകാൻ പറഞ്ഞു. നജ്ജാശി പറഞ്ഞു: അദ്ദേഹം (നബി) അല്ലാഹുവിന്റെ ദൂതനാണെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. മർയമിന്റെ പുത്രൻ ഈസ സന്തോഷവാർത്ത അറിയിച്ച ആൾ അദ്ദേഹമാണ്. ഞാൻ രാജാവായിരുന്നില്ലെങ്കിൽ അദ്ദേഹത്തിന്റെ അടുത്ത് ചെന്ന് അദ്ദേഹത്തിന്റെ ഇരു ചെരുപ്പുകൾ ഞാൻ വഹിക്കുമായിരുന്നു. (ദ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസാ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 838, 838, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 296, 'عَنْ شَدَّاد بْنِ الْهَاد رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا مِنَ الْأَعْرَابِ جَاءَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَآمَنَ بِهِ وَاتَّبَعَهُ، ثُمَّ قَالَ: أُهَاجِرُ مَعَكَ. فَأَوْصَى بِهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْضَ أَصْحَابِه، فَلَمَّا كَانَتْ غَزْوَةٌ غَنِمَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَبْيًا، فَقَسَمَ وَقَسَمَ لَهُ، فَأَعْطَى أَصْحَابَهُ مَا قَسَمَ لَهُ، وَكَانَ يَرْعَى ظَهْرَهُمْ، فَلَمَّا جَاءَ دَفَعُوهُ إِلَيْهِ، فَقَالَ: مَا هَذَا؟ قَالُوا: قَسْمٌ قَسَمَهُ لَكَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَأَخَذَهُ فَجَاءَ بِهِ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَا هَذَا؟ قَالَ: "قَسَمْتُهُ لَكَ". قَالَ: مَا عَلَى هَذَا اتَّبَعْتُكَ، وَلَكِنِّي اتَّبَعْتُكَ عَلَى أَنْ أُرْمَى إِلَى هَاهُنَا – وَأَشَارَ إِلَى حَلْقِه – بِسَهْمٍ فَأَمُوتَ فَأَدْخُلَ الْجَنَّةَ. فَقَالَ: "إِنْ تَصْدُقِ اللهَ يَصْدُقْكَ". فَلَبِثُوا قَلِيلًا ثُمَّ نَهَضُوا فِي قِتَالِ الْعَدُوِّ، فَأُتِيَ بِهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُحْمَلُ قَدْ أَصَابَهُ سَهْمٌ حَيْثُ أَشَارَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَهُوَ هُوَ". قَالُوا: نَعَمْ. قَالَ: "صَدَقَ اللهَ فَصَدَقَهُ". ثُمَّ كَفَّنَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي جُبَّةِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَدَّمَهُ فَصَلَّى عَلَيْهِ، فَكَانَ فِيمَا ظَهَرَ مِنْ صَلَاتِهِ: "اللَّهُمَّ هَذَا عَبْدُكَ، خَرَجَ مُهَاجِرًا فِي سَبِيلِكَ، فَقُتِلَ شَهِيدًا، أَنَا شَهِيدٌ عَلَى ذَلِكَ". (ن)', 'ശദ്ദാദുബ്നുൽ ഹാദ്(റ): അഅ്റാബികളിൽ പെട്ട ഒരാൾ നബി(സ)യുടെ അടുത്ത്വന്ന് തിരുമേനി(സ)യിൽ വിശ്വസിക്കുകയും പിന്തുടരുകയും ചെയ്തു. പിന്നെ പറഞ്ഞു: ഞാൻ താങ്കളുടെ കൂടെ ഹിജ്റ ചെയ്യും. അപ്പോൾ നബി(സ) അദ്ദേഹത്തെ ചില അനുചരന്മാരെ ഏൽപിച്ചു. ഒരു യുദ്ധം നടന്നപ്പോൾ നബി(സ) ഗനീമത്ത് ഓഹരി വെച്ചു. ഒരു ഓഹരി അയാൾക്കും. അയാൾക്കുള്ള ഓഹരി നബി(സ) ചില സ്വഹാബികളെ ഏൽപിച്ചു. അദ്ദേഹം അവരുടെ മൃഗങ്ങളെ മേക്കുകയായിരുന്നു. അദ്ദേഹം വന്നപ്പോൾ അവരത് അദ്ദേഹത്തെ ഏൽപിച്ചു. അദ്ദേഹം ചോദിച്ചു: എന്താണിത്? അവർ പറഞ്ഞു: റസൂൽ(സ) താങ്കൾക്ക് വെച്ച ഓഹരിയാണിത്. അദ്ദേഹം അതും എടുത്തുകൊണ്ട് പ്രവാചകന്റെ(സ) അടുക്കൽചെന്നു. എന്നിട്ട് ചോദിച്ചു: എന്താണിത്? തിരുമേനി(സ) പറഞ്ഞു: "ഞാൻ നിനക്ക് വെച്ച ഓഹരിയാണിത്." അദ്ദേഹം പറഞ്ഞു: ഞാൻ ഇതിനല്ല താങ്കളെ പിൻപറ്റിയത്. എന്നാൽ ഞാൻ താങ്കളെ പിൻപറ്റിയത് എന്റെ ഇവിടെ അമ്പ് കൊണ്ട് മരിച്ച് സ്വർഗത്തിൻ പ്രവേശിക്കാനാണ്. (തൊണ്ടയിലേക്ക് ചൂണ്ടി കൊണ്ടാണ് അദ്ദേഹം ഇത് പറഞ്ഞത്). "നീ പറഞ്ഞത് സത്യമാണെങ്കിൽ അല്ലാഹു അതംഗീകരിക്കും" എന്ന് നബി(സ) അയാളോട് പറഞ്ഞു. കുറച്ചുകാലം കഴിഞ്ഞു. പിന്നെ അവർ ശത്രുവിനോട് യുദ്ധം ആരംഭിച്ചു. അപ്പോൾ അദ്ദേഹം ചൂണ്ടിയിരുന്ന ഭാഗത്ത് അസ്ത്രം ഏറ്റ നിലയിൽ പ്രവാചകന്റെ(സ) അടുക്കൽ കൊണ്ടുവരപ്പെട്ടു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "അദ്ദേഹമാണോ ഇത്." അവർ പറഞ്ഞു: അതെ. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "അദ്ദേഹം വാക്ക് പാലിച്ചു അദ്ദേഹത്തോട് അല്ലാഹുവും." പിന്നെ പ്രവാചകൻ(സ) തന്റെ നീളക്കുപ്പായത്തിൽ അദ്ദേഹത്തെ പൊതിയുകയും അദ്ദേഹത്തെ കൊണ്ടുപോയി അദ്ദേഹത്തിന് വേണ്ടി നിസ്കരിക്കുകയും ചെയ്തു. തിരുമേനി(സ)യുടെ ആ നിസ്കാരത്തിൽ ഇങ്ങനെ ചെല്ലുന്നതായി കേട്ടു: "അല്ലാഹുവേ ഇത് നിന്റെ അടിമയാകുന്നു. അദ്ദേഹം നിന്റെ മാർഗ്ഗത്തിൽ പലായനം ചെയ്തിട്ടുണ്ട്, അങ്ങനെ അദ്ദേഹം രക്തസാക്ഷിയായി. ഞാൻ അതിന്ന് സാക്ഷിയാണ്." (ന)', 'شَدَّاد بْنِ الْهَاد', 'ശദ്ദാദുബ്നുൽ ഹാദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 839, 839, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 297, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الشُّهَدَاءُ خَمْسٌ: الْمَطْعُونُ، وَالْمَبْطُونُ، وَالْغَرِق، وَصَاحِبُ الْهَدْمِ، وَالشَّهِيدُ فِي سَبِيل اللهِ". حَسَنٌ صَحِيحٌ. (ق,ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "രക്തസാക്ഷികൾ അഞ്ചിനമുണ്ട്. പ്ലേഗ് പിടിച്ച് മരിച്ചവർ, ഉദരരോഗം ബാധിച്ച് മരിച്ചവർ, മുങ്ങിമരിച്ചവർ, തകർച്ചയിൽ മരിച്ചവർ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ രക്തസാക്ഷിയായവർ എന്നിവരാണത്." (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 839, 839, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 298, 'عَنْ جَابِر بْنِ عَبْد اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَجْمَعُ بَيْنَ الرَّجُلَيْنِ مِنْ قَتْلَى أُحُد فِي ثَوْب وَاحِد، ثُمَّ يَقُولُ: "أَيُّهُمْ أَكْثَرُ أَخْذًا لِلْقُرْآنِ". فَإِذَا أُشِيرَ لَهُ إِلَى أَحَدِهِمَا قَدَّمَهُ فِي اللَّحْدِ، وَقَالَ: "أَنَا شَهِيدٌ عَلَى هَؤُلَاءِ يَوْمَ الْقِيَامَةِ". وَأَمَرَ بِدَفْنِهِمْ فِي دِمَائِهِمْ، وَلَمْ يُغَسَّلُوا وَلَمْ يُصَلَّ عَلَيْهِمْ. (خ,د,ت,ن,جه)', 'ജാബിർ(റ): ഉഹ്ദിൽ മരിച്ച രണ്ടു പേരെ നബി(സ) ഒറ്റ വസ്ത്രത്തിലാക്കിയിട്ടു ചോദിച്ചു: "ഇവരിലാരാണ് കൂടുതൽ ഖുർആൻ പഠിച്ചത്?" അപ്പോൾ അവരിലൊരാളെ കുറിച്ച് സൂചന കിട്ടിയാൽ ലഹ്ദിലേക്ക് അദ്ദേഹത്തെ മുന്തിക്കും. ശേഷം നബി(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ ഞാൻ ഇവർക്ക് സാക്ഷിയാണ്." നബി(സ) പറഞ്ഞു. അവരുടെ രക്തത്തോടെ തന്നെ അവരെ മറമാടാൻ തിരുമേനി(സ) കൽപ്പിച്ചു. അവർ കുളിപ്പിക്കപ്പെടുകയോ അവർക്കു വേണ്ടി നിസ്കരിക്കുകയോ ചെയ്തില്ല. (ബു,ദ,തു,ന,ജ)', 'جَابِر بْنِ عَبْد اللهِ', 'ജാബിർ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 839, 840, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 299, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِقَتْلَى أُحُدٍ أَنْ يُرَدُّوا إِلَى مَصَارِعِهِمْ، وَكَانُوا نُقِلُوا إِلَى الْمَدِينَةِ. (د,ت,ن,جه)', 'ജാബിർ(റ): ഉഹ്ദിൽ മരിച്ച ആളുകളെ അവർ വീണസ്ഥലത്തേക്ക് തന്നെ മടക്കാൻ നബി(സ) കൽപിച്ചു. അവർ മദീനയിലേക്ക് നീക്കപ്പെട്ടിരുന്നു. (ദ,തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 840, 840, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 300, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أُتِيَ بِهِمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ أُحُدٍ، فَجَعَلَ يُصَلِّي عَلَى عَشَرَةٍ عَشَرَةٍ، وَحَمْزَةُ هُوَ كَمَا هُوَ، يُرْفَعُونَ وَهُوَ كَمَا هُوَ مَوْضُوعٌ. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഉഹ്ദുദിനത്തിൽ അവർ (രക്തസാക്ഷികൾ) നബി(സ)യുടെ അടുക്കലേക്ക് കൊണ്ടുവരപ്പെട്ടു. പത്തു പേർക്ക് വീതം നബി(സ) നിസ്കരിച്ചു. ഹംസ(റ)യുടെ മൃതദേഹമാകട്ടെ, എപ്രകാരമായിരുന്നുവോ അത് ഉണ്ടായിരുന്നത് അപ്രകാരം തന്നെ അവശേഷിച്ചു (അദ്ദേഹത്തിന് വേണ്ടി നിസ്കരിച്ചില്ല). അവർ (മറ്റു രക്തസാക്ഷികൾ) ഉയർത്തപ്പെടുകയും, അതേ സമയം ഹംസ(റ)യുടെ മൃതദേഹം അതേ അവസ്ഥയിൽ തന്നെ കിടക്കുകയും ചെയ്തു. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 840, 840, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 301, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: مَرِضَ رَجُلٌ، فَصِيحَ عَلَيْهِ، فَجَاءَ جَارُهُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَهُ: إِنَّهُ قَدْ مَاتَ، قَالَ: "وَمَا يُدْرِيكَ". قَالَ: أَنَا رَأَيْتُهُ، قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهُ لَمْ يَمُتْ". قَالَ: فَرَجَعَ، فَصِيحَ عَلَيْهِ، فَجَاءَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّهُ قَدْ مَاتَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهُ لَمْ يَمُتْ". فَرَجَعَ، فَصِيحَ عَلَيْهِ، فَقَالَتِ امْرَأَتُهُ: انْطَلِقْ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبِرْهُ، فَقَالَ الرَّجُلُ: اللَّهُمَّ الْعَنْهُ، قَالَ: ثُمَّ انْطَلَقَ الرَّجُلُ، فَرَآهُ قَدْ نَحَرَ نَفْسَهُ بِمَشْقَصٍ مَعَهُ، فَانْطَلَقَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ أَنَّهُ قَدْ مَاتَ، فَقَالَ: "وَمَا يُدْرِيكَ". قَالَ: رَأَيْتُهُ يَنْحَرُ نَفْسَهُ بِمَشَاقِصَ مَعَهُ، قَالَ: "أَنْتَ رَأَيْتَهُ". قَالَ: نَعَمْ، قَالَ: "إِذًا لَا أُصَلِّي عَلَيْهِ". (م,د,ت,ن,جه)', 'ജാബിറുബ്നു സമുറ(റ): ഒരാൾ രോഗിയായി. അദ്ദേഹത്തിന് വേണ്ടി അട്ടഹസിച്ചു കരഞ്ഞു. അപ്പോൾ അദ്ദേഹത്തിന്റെ അയൽക്കാരൻ നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: അദ്ദേഹം മരിച്ചിരിക്കുന്നു. പ്രവാചകൻ(സ) അയാളോട് ചോദിച്ചു: "താങ്കൾക്ക് എങ്ങനെ മനസ്സിലായി?" അയാൾ പറഞ്ഞു: ഞാൻ അദ്ദേഹത്തെ കണ്ടു. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "അയാൾ മരിച്ചിട്ടില്ല." അയാൾ മടങ്ങി. അപ്പോൾ വീണ്ടും കരച്ചിൽ കേട്ടു. ആ മനുഷ്യൻ നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: അയാൾ മരിക്കുക തന്നെ ചെയ്തു. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "അദ്ദേഹം മരിച്ചിട്ടില്ല." അയാൾ തിരിച്ചു പോയി. അപ്പോൾ അയാൾക്ക് വേണ്ടി കരയുന്നത് കേട്ടു. അയാളുടെ ഭാര്യ പറഞ്ഞു: നീ പ്രവാചകനോട് പോയി വിവരമറയിക്കൂ! ആ മനുഷ്യൻ പറഞ്ഞു: അല്ലാഹുവേ, നീ അവനെ ശപിക്കണേ!. പിന്നെ അദ്ദേഹം പോയി. അയാൾ കുന്തമുനകൊണ്ട് ആത്മഹത്യ ചെയ്യുന്നത് കണ്ടു. അപ്പോൾ അയാൾ മരിച്ചിട്ടുണ്ടെന്ന് നബി(സ)യെ അറിയിച്ചു. നബി(സ) ചോദിച്ചു: "താങ്കൾക്ക് എങ്ങനെ മനസ്സിലായി?" അവൻ കുന്തമുനകൊണ്ട് കുത്തി മരിക്കുന്നത് ഞാൻ കണ്ടു. നബി(സ) ചോദിച്ചു: "നീ കണ്ടോ?" അയാൾ പറഞ്ഞു: അതെ. "എന്നാൽ ഞാൻ അയാൾക്ക് നിസ്കരിക്കുകയില്ല" എന്ന് നബി(സ) പറഞ്ഞു. (മു,ദ,തു,ന,ജ)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 840, 841, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 302, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِرَجُلٍ قَتَلَ نَفْسَهُ بِمَشَاقِصَ، فَلَمْ يُصَلِّ عَلَيْهِ. (م,ت,ن)', 'ജാബിറുബ്നു സമുറ(റ): കുന്തമുനകൊണ്ട് ആത്മഹത്യ ചെയ്ത ഒരാളെ പ്രവാചകർ(സ)യുടെ അടുക്കൽ കൊണ്ടുവന്നു. പ്രവാചകൻ(സ) അവന് വേണ്ടി നിസ്കരിച്ചില്ല. (മു,തു,ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 841, 841, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 303, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ تَرَدَّى مِنْ جَبَلٍ فَقَتَلَ نَفْسَهُ فَهُوَ فِي نَارِ جَهَنَّمَ يَتَرَدَّى، خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا. وَمَنْ تَحَسَّى سُمًّا فَقَتَلَ نَفْسَهُ فَسُمُّهُ فِي يَدِهِ يَتَحَسَّاهُ فِي نَارِ جَهَنَّمَ، خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا. وَمَنْ قَتَلَ نَفْسَهُ بِحَدِيدَةٍ كَانَتْ حَدِيدَتُهُ فِي يَدِهِ يَجَأُ بِهَا فِي بَطْنِهِ فِي نَارِ جَهَنَّمَ، خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും പർവ്വതത്തിന് മുകളിൽ നിന്ന് ചാടി മരിച്ചാൽ അവൻ നരകത്തിൽ കാലാകാലം ചാടി മരിച്ചുകൊണ്ടിരിക്കും. ആരെങ്കിലും വിഷം ഉപയോഗിച്ച് ആത്മഹത്യ ചെയ്താൽ നരകത്തീയിൽ എന്നെന്നും അവന്റെ കയ്യിലുള്ള ആ വിഷം അവൻ കഴിച്ചുകൊണ്ടിരിക്കും. ആരെങ്കിലും ഇരുമ്പ് ഉപയോഗിച്ച് കുത്തിമരിച്ചാൽ അവന്റെ ആ ഇരുമ്പ് കൊണ്ട് നരകത്തീയിൽ വെച്ച് അവന്റെ വയറ്റിൽ എന്നെന്നും കുത്തിക്കൊണ്ടിരിക്കും." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 841, 841, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 304, 'عَنْ أَبِي بَرْزَةَ الْأَسْلَمِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمْ يُصَلِّ عَلَى مَاعِزِ بْنِ مَالِكٍ وَلَمْ يَنْهَ عَنِ الصَّلَاةِ عَلَيْهِ. (د)', 'അബൂബർസ(റ): മാഇസുബ്നു മാലിക്കി(റ)ന് നബി(സ) നിസ്കരിച്ചില്ല. എന്നാൽ അവന് വേണ്ടി നിസ്കരിക്കുന്നതിൽ നിന്ന് മറ്റുള്ളവരെ തടഞ്ഞതുമില്ല. (ദ)', 'أَبِي بَرْزَةَ الْأَسْلَمِيِّ', 'അബൂബർസ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 841, 841, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 305, 'عَنْ ثَابِتِ بْنِ الضَّحَّاكِ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ حَلَفَ بِمِلَّةٍ غَيْرِ الْإِسْلَامِ كَاذِبًا مُتَعَمِّدًا فَهُوَ كَمَا قَالَ، وَمَنْ قَتَلَ نَفْسَهُ بِحَدِيدَةٍ عُذِّبَ بِهَا فِي نَارِ جَهَنَّمَ". (خ)', 'സാബിതുബ്നു ളഹ്ഹാക്(റ): നബി(സ) പറഞ്ഞു: "ഇസ്ലാമല്ലാത്ത വല്ല മാർഗ്ഗവുമായി ആരെങ്കിലും കരുതികൂട്ടി കള്ളം പറഞ്ഞ് സഖ്യം ചെയ്താൽ അവൻ ആ പറഞ്ഞപോലെയായിരിക്കും. ആരെങ്കിലും ഇരുമ്പ് കൊണ്ട് ആത്മഹത്യ ചെയ്താൽ അത് കൊണ്ടവൻ നരകത്തീയിൽ ശിക്ഷിക്കപ്പെടും." (ബു)', 'ثَابِتِ بْنِ الضَّحَّاكِ', 'സാബിതുബ്നു ളഹ്ഹാക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 841, 841, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 306, 'عَنْ جُنْدَبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كَانَ بِرَجُلٍ جِرَاحٌ فَقَتَلَ نَفْسَهُ فَقَالَ اللهُ: بَدَرَنِي عَبْدِي بِنَفْسِهِ حَرَّمْتُ عَلَيْهِ الْجَنَّةَ". (خ)', 'ജുൻദുബ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾക്കൊരു മുറിവുണ്ടായിരുന്നുഷ അയാൾ ആത്മഹത്യചെയ്തു. അപ്പോൾ അല്ലാഹു പറഞ്ഞു: എന്റെ അടിമ സ്വയം തിരക്കുകൂട്ടി. അതിനാൽ അവനു ഞാൻ സ്വർഗം നിഷേധിച്ചു." (ബു)', 'جُنْدَبٍ', 'ജുൻദുബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 841, 841, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 307, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الَّذِي يَخْنُقُ نَفْسَهُ يَخْنُقُهَا فِي النَّارِ، وَالَّذِي يَطْعُنُ نَفْسَهُ يَطْعُنُهَا فِي النَّارِ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "സ്വന്തം കഴുത്തുമുറുക്കി മരിച്ചവൻ നരകത്തിലും അത് മുറുക്കും. സ്വന്തം കുത്തിമരിക്കുന്നവൻ നരകത്തിലും അങ്ങനെ കുത്തും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 841, 841, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 308, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى حَمْزَةَ يَوْمَ أُحُدٍ، فَوَقَفَ عَلَيْهِ فَرَآهُ قَدْ مُثِّلَ بِهِ، فَقَالَ: "لَوْلَا أَنْ تَجِدَ صَفِيَّةُ فِي نَفْسِهَا لَتَرَكْتُهُ حَتَّى تَأْكُلَهُ الْعَافِيَةُ، حَتَّى يُحْشَرَ يَوْمَ الْقِيَامَةِ مِنْ بُطُونِهَا". قَالَ: ثُمَّ دَعَا بِنَمِرَةٍ فَكَفَّنَهُ فِيهَا، فَكَانَتْ إِذَا مُدَّتْ عَلَى رَأْسِهِ بَدَتْ رِجْلَاهُ، وَإِذَا مُدَّتْ عَلَى رِجْلَيْهِ بَدَا رَأْسُهُ. قَالَ: فَكَثُرَ الْقَتْلَى وَقَلَّتِ الثِّيَابُ. قَالَ: فَكُفِّنَ الرَّجُلُ وَالرَّجُلَانِ وَالثَّلَاثَةُ فِي الثَّوْبِ الْوَاحِدِ، ثُمَّ يُدْفَنُونَ فِي قَبْرٍ وَاحِدٍ، فَجَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَسْأَلُ عَنْهُمْ: "أَيُّهُمْ أَكْثَرُ قُرْآنًا". فَيُقَدِّمُهُ إِلَى الْقِبْلَةِ. قَالَ: فَدَفَنَهُمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَمْ يُصَلِّ عَلَيْهِمْ. حَسَنٌ. (د,ت)', 'അനസ്(റ): നബി(സ) ഉഹ്ദ് ദിവസം ഹംസ(റ)യുടെ അടുത്ത് വന്നു അദ്ദേഹത്തിന്റെ അടുത്തു നിന്നു. അദ്ദേഹം അംഗവിച്ഛേദനം ചെയ്യപ്പെട്ടതായി കണ്ടു. അവിടുന്ന് പറഞ്ഞു: "സ്വഫിയ്യ കാണുകയില്ലായിരുന്നെങ്കിൽ ഞാൻ അദ്ദേഹത്തെ ഉപേക്ഷിക്കുമായിരുന്നു. അങ്ങനെ വല്ലതും അദ്ദേഹത്തെ തിന്നും. അന്ത്യനാളിൽ അവയുടെ വയറ്റിൽ നിന്ന് അദ്ദേഹത്തെ ഒരുമിച്ചുകൂട്ടുന്നത് വരെ." പിന്നെ ഒരു പുതപ്പുകൊണ്ടുവരാൻ ആവശ്യപ്പെട്ടു. അദ്ദേഹത്തെ അതിൽ കഫൻ ചെയ്തു. തല മൂടിയാൽ കാല് വെളിവാകുന്നതും കാല് മൂടിയാൽ തല വെളിവാകുന്നതും ആയിരുന്നു ആ പുതപ്പ്. മരണപ്പെട്ടവർ അധികവും വസ്ത്രം കുറവുമായി. അങ്ങനെ ഒന്നും രണ്ടും മൂന്നും പേർ ഒരു വസ്ത്രത്തിൽ പൊതിയപ്പെട്ടു. പിന്നെ അവരെ ഒറ്റ ഖബറിൽ മറമാടുകയും ചെയ്തു. അപ്പോൾ നബി(സ) അവരോടു ചോദിക്കും: "അവരിലാർക്കാണ് കൂടുതൽ ഖുർആൻ അറിയുക." എന്നിട്ട് അദ്ദേഹത്തെ (ഖുർആൻ കൂടുതൽ അറിയുന്നയാളെ) ഖിബ്‌ലക്ക് മുന്നിൽ കിടത്തും. അങ്ങനെ റസൂൽ(സ) അവരെ മറമാടി. അവർക്ക് വേണ്ടി നിസ്കരിച്ചില്ല. (ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു) (ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 842, 842, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 309, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أُتِيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِصَبِيٍّ مِنْ صِبْيَانِ الْأَنْصَارِ فَصَلَّى عَلَيْهِ، قَالَتْ عَائِشَةُ: فَقُلْتُ: طُوبَى لِهَذَا، عُصْفُورٌ مِنْ عَصَافِيرِ الْجَنَّةِ، لَمْ يَعْمَلْ سُوءًا وَلَمْ يُدْرِكْهُ. قَالَ: "أَوْ غَيْرَ ذَلِكَ يَا عَائِشَةُ، خَلَقَ اللهُ عَزَّ وَجَلَّ الْجَنَّةَ وَخَلَقَ لَهَا أَهْلًا، وَخَلَقَهُمْ فِي أَصْلَابِ آبَائِهِمْ. وَخَلَقَ النَّارَ وَخَلَقَ لَهَا أَهْلًا، وَخَلَقَهُمْ فِي أَصْلَابِ آبَائِهِمْ". (ن)', 'ആഇശ(റ): അൻസാരികളിൽ പെട്ട ഒരു കുട്ടിക്ക് വേണ്ടി റസൂൽ(സ) നിസ്കരിച്ചു. ആഇശ(റ) പറഞ്ഞു: ഇവന്ന് സന്തോഷം. സ്വർഗ്ഗകുരുവികളിലെ ഒരു കുരുവിയാണിവൻ. അവനൊരു തെറ്റും ചെയ്തിട്ടില്ല. തെറ്റ് അവനെത്തിയിട്ടുമില്ല. തിരുമേനി(സ) പറഞ്ഞു: "ആഇശ(റ)! മറ്റെന്തെങ്കിലുമുണ്ടോ? അല്ലാഹു സ്വർഗ്ഗവും അതിന്റെ ആളുകളെയും സൃഷ്ടിച്ചു. അവരെ പിതാക്കളുടെ മുതുകിൽ വെച്ചുതന്നെ സൃഷ്ടിച്ചു. നരകത്തെയും അതിന്റെ ആളുകളെയും സൃഷ്ടിച്ചു. അവരെ പിതാക്കളുടെ മുതുകിൽ വെച്ചുതന്നെ സൃഷ്ടിച്ചു." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 842, 842, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 310, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَاتَ إِبْرَاهِيمُ بْنُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ ابْنُ ثَمَانِيَةَ عَشَرَ شَهْرًا، فَلَمْ يُصَلِّ عَلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'ആഇശ(റ): നബി(സ)യുടെ മകൻ ഇബ്രാഹീം മരിച്ചു. അദ്ദേഹത്തിന് എട്ട് മാസമായിരുന്നു. അവന് വേണ്ടി നബി(സ) നിസ്കരിച്ചില്ല. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 842, 842, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 311, 'عَنِ الْبَهِيِّ قَالَ: لَمَّا مَاتَ إِبْرَاهِيمُ بْنُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْمَقَاعِدِ. وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى ابْنِهِ إِبْرَاهِيمَ وَهُوَ ابْنُ سَبْعِينَ لَيْلَةً. [مرسل] (د)', 'ബഹിയ്യ്(റ): പ്രവാചക(സ)ന്റെ പുത്രൻ ഇബ്റാഹീം മരണപ്പെട്ടപ്പോൾ മഖാഇദിൽ വെച്ച് പ്രവാചകൻ(സ) അവന് വേണ്ടി നിസ്കരിച്ചു. മറ്റൊരു റിപ്പോർട്ടിൽ: തന്റെ എഴുപത് ദിവസം പ്രായമായ മകൻ ഇബ്രാഹീമിന് വേണ്ടി നബി(സ) നിസ്കരിച്ചു. (ഹദീസ് മുർസലാണെന്ന് അബൂദാവൂദ് പറയുന്നു) (ദ)', 'الْبَهِيِّ قَالَ', 'ബഹിയ്യ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'مرسل', null, 843, 843, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=311), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى ابْنِهِ إِبْرَاهِيمَ وَهُوَ ابْنُ سَبْعِينَ لَيْلَةً. [مرسل] (د)', 'മറ്റൊരു നിവേദനിൽ: തന്റെ എഴുപത് ദിവസം പ്രായമായ മകൻ ഇബ്രാഹീമിന് വേണ്ടി നബി(സ) നിസ്കരിച്ചു. (ഹദീസ് മുർസലാണെന്ന് അബൂദാവൂദ് പറയുന്നു) (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 312, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الرَّاكِبُ خَلْفَ الْجَنَازَةِ، وَالْمَاشِي حَيْثُ شَاءَ مِنْهَا، وَالطِّفْلُ يُصَلَّى عَلَيْهِ". (د,ت,ن,جه)', 'മുഗീറത്തുബ്നു ശുഅ്ബ(റ): നബി(സ) പറഞ്ഞു: "വാഹനത്തിൽ യാത്രചെയ്യുന്നവൻ മയ്യിത്തിന് പിന്നിൽ വരണം. നടക്കുന്നവന് ഇടമുള്ളതിലൂടെ നടക്കാം. കുട്ടിക്ക് മയ്യിത്ത് നിസ്കരിക്കണം." (ദ,തു,ന,ജ)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറത്തുബ്നു ശുഅ്ബ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 843, 843, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 313, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا اسْتَهَلَّ الصَّبِيُّ صُلِّيَ عَلَيْهِ وَوُرِّثَ". (ت,جه)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "ജനന സമയത്ത് കുട്ടി ശബ്ദിച്ചാൽ (ശേഷം മരിക്കുകയും ചെയ്താൽ) അവന് നിസ്കരിക്കണം. അവൻ അനന്തരമെടുക്കപ്പെടുകയും വേണം." (തു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 843, 843, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 314, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَلُّوا عَلَى أَطْفَالِكُمْ، فَإِنَّهُمْ مِنْ أَفْرَاطِكُمْ". [ز: في سنده ضعيف متهم بالوضع] (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിങ്ങളുടെ കുട്ടികൾക്ക് നിസ്കരിക്കുക. കാരണം അവർ നിങ്ങളുടെ സൂക്ഷിപ്പുമുതലാണ്." (ഈ ഹദീസിന്റെ സനദിൽ ഹദീസ് കെട്ടിച്ചമക്കുന്നവനെന്ന് ആരേപിക്കപ്പെട്ട വ്യക്തിയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف متهم بالوضع', null, 843, 843, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 315, 'عَنْ إِسْمَعِيلَ بْنِ أَبِي خَالِدٍ قَالَ: قُلْتُ لِعَبْدِ اللهِ بْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُمَا: رَأَيْتَ إِبْرَاهِيمَ ابْنَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: مَاتَ وَهُوَ صَغِيرٌ، وَلَوْ قُضِيَ أَنْ يَكُونَ بَعْدَ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَبِيٌّ لَعَاشَ ابْنُهُ، وَلَكِنْ لَا نَبِيَّ بَعْدَهُ. (خ,جه)', 'ഇസ്മാഈലുബ്നു അബീഖാലിദ്: അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ)യോട് ഞാൻ പറഞ്ഞു: പ്രവാചക(സ)ന്റെ പുത്രൻ ഇബ്രാഹീമിനെ താങ്കൾ കണ്ടിട്ടുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: അവൻ കുട്ടിയായിരിക്കെ മരണപ്പെട്ടു. മുഹമ്മദ് നബി(സ)ക്ക് ശേഷം ഒരു പ്രവാചകൻ ഉണ്ടാകണമെന്ന് വിധി ഉണ്ടായിരുന്നെങ്കിൽ തിരുമേനി(സ)യുടെ മകൻ ജീവിക്കുമായിരുന്നു. പക്ഷെ അവിടുത്തേക്ക് ശേഷം ഒരു നബിയും ഉണ്ടാകുന്നതല്ല. (ബു,ജ)', 'إِسْمَعِيلَ بْنِ أَبِي خَالِدٍ قَالَ', 'ഇസ്മാഈലുബ്നു അബീഖാലിദ്', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 843, 843, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 316, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا مَاتَ إِبْرَاهِيمُ ابْنُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "إِنَّ لَهُ مُرْضِعًا فِي الْجَنَّةِ، وَلَوْ عَاشَ لَكَانَ صِدِّيقًا نَبِيًّا، وَلَوْ عَاشَ لَعَتَقَتْ أَخْوَالُهُ الْقِبْطُ، وَمَا اسْتُرِقَّ قِبْطِيٌّ". [ز: في سنده ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)യുടെ പുത്രൻ ഇബ്രാഹീം മരിച്ചപ്പോൾ പ്രവാചകൻ(സ) അവന് വേണ്ടി (മയ്യിത്ത്) നിസ്കരിച്ചു. പ്രവാചകൻ(സ) പറഞ്ഞു: "നിശ്ചയം അവന് സ്വർഗ്ഗത്തിൽ മുലയൂട്ടാൻ ആളുണ്ട്. അവൻ ജീവിച്ചിരുന്നെങ്കിൽ സത്യസന്ധനും പ്രവാചകനുമാകുമായിരുന്നു, അവൻ ജീവിച്ചിരുന്നെങ്കിൽ ഖിബ്ത്വികളായ അവന്റെ അമ്മാവന്മാർ മോചിതരാകുമായിരുന്നു. ഒരു ഖിബ്ത്വിയും അടിമയാക്കപ്പെടില്ല." (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 843, 844, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 317, 'عَنِ الْحُسَيْنِ بْنِ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا تُوُفِّيَ الْقَاسِمُ ابْنُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَتْ خَدِيجَةُ رَضِيَ اللهُ عَنْهَا: يَا رَسُولَ اللهِ، دَرَّتْ لُبَيْنَةُ الْقَاسِمِ، فَلَوْ كَانَ اللهُ أَبْقَاهُ حَتَّى يَسْتَكْمِلَ رِضَاعَهُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ إِتْمَامَ رَضَاعِه فِي الْجَنَّةِ". قَالَتْ: لَوْ أَعْلَمُ ذَلِكَ يَا رَسُولَ اللهِ لَهَوَّنَ عَلَيَّ أَمْرَهُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنْ شِئْت دَعَوْتُ اللهَ تَعَالَى فَأَسْمِعَك صَوْتَهُ". قَالَتْ: يَا رَسُولَ اللهِ، بَلْ أُصَدِّقُ اللهَ وَرَسُولَهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (جه)', 'ഹുസൈനുബ്നു അലി(റ): റസൂലി(സ)ന്റെ പുത്രൻ ഖാസിം മരണപ്പെട്ടപ്പോൾ ഖദീജ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, ഖാസിമിന് വേണ്ടി മുലപ്പാൽ ചുരത്തിയിരിക്കുന്നു. മുലകുടി പൂർത്തിയാക്കുന്നത് വരെ അല്ലാഹു അവനെ അവശേഷിപ്പിച്ചിരുന്നെങ്കിൽ. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "അവന്റെ മുലകുടി പൂർത്തിയാകുന്നത് സ്വർഗ്ഗത്തിൽ വെച്ചാണ്." അവർ പറഞ്ഞു: ഞാനതറിഞ്ഞിരുന്നെങ്കിൽ എനിക്ക് അവന്റെ കാര്യം എളുപ്പമാകുമായിരുന്നു. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു. "നീ ഉദ്ദേശിക്കുന്നെങ്കിൽ ഞാൻ അല്ലാഹുവിനോട് പ്രാർത്ഥിച്ച് അവന്റെ ശബ്ദം നിനക്ക് കേൾപ്പിക്കാം." അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, ഞാൻ അല്ലാഹുവിനേയും അവന്റെ ദൂതരെയും സത്യപ്പെടുത്തുന്നു. (ജ)', 'الْحُسَيْنِ بْنِ عَلِيٍّ', 'ഹുസൈനുബ്നു അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 844, 844, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 318, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الطِّفْلُ لَا يُصَلَّى عَلَيْهِ، وَلَا يَرِثُ وَلَا يُورَثُ، حَتَّى يَسْتَهِلَّ". (ت)', 'നബി(സ)യിൽ നിന്ന് ജാബിർ(റ): "ജനിച്ച സമയത്ത് ശബ്ദിക്കാത്ത കുട്ടിക്ക് വേണ്ടി നിസ്കാരമില്ല. അവൻ അനന്തരം എടുക്കുകയോ എടുക്കപ്പെടുകയോ ഇല്ല." (തു)', 'جَابِرٍ', 'നബി(സ)യിൽ നിന്ന് ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 844, 844, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 319, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَدْخَلَ رَجُلًا قَبْرَهُ لَيْلًا، وَأُسْرِجَ فِي قَبْرِهِ. (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഒരാളെ രാത്രി മറമാടി. ആ ഖബ്റിൽ വിളക്ക് കത്തിക്കുകയുംചെയ്തു. (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 844, 844, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 320, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ قَبْرًا لَيْلًا، فَأُسْرِجَ لَهُ سِرَاجٌ، فَأَخَذَهُ مِنْ قِبَلِ الْقِبْلَةِ وَقَالَ: "رَحِمَكَ اللهُ، إِنْ كُنْتَ لَأَوَّاهًا تَلَّاءً لِلْقُرْآنِ". وَكَبَّرَ عَلَيْهِ أَرْبَعًا. حَسَنٌ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഒരു രാത്രി ഒരാളെ ഖബ്റിൽ പ്രവേശിപ്പിച്ചു. അവിടുത്തേക്ക് വേണ്ടി ഒരു വിളക്ക് കത്തിക്കപ്പെട്ടു. എന്നിട്ട് നബി(സ) അദ്ദേഹത്തെ ഖിബ്‌ലയുടെ ഭാഗത്ത് വെച്ചു, എന്നിട്ട് പറഞ്ഞു: "നിന്നെ അല്ലാഹു അനുഗ്രഹിക്കട്ടെ. നീ ഏറെ ഖുർആൻ പാരായണം ചെയ്യുന്നവനും കരഞ്ഞ് പശ്ചാതപിക്കുന്നവനുമായിരുന്നു." നബി(സ) അയാൾക്ക് വേണ്ടി നാല് തക്ബീർ ചൊല്ലിക്കൊണ്ട് (നമസ്കരിച്ചു). ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു. (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 844, 844, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 321, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَى نَاسٌ نَارًا فِي الْمَقْبَرَةِ، فَأَتَوْهَا، فَإِذَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْقَبْرِ، وَإِذَا هُوَ يَقُولُ: "نَاوِلُونِي صَاحِبَكُمْ". فَإِذَا هُوَ الرَّجُلُ الَّذِي كَانَ يَرْفَعُ صَوْتَهُ بِالذِّكْرِ. (د,ت)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): ജനങ്ങൾ മഖ്ബറയിൽ തീ കണ്ടു. അവർ അതിനടുത്തു വന്നു. അപ്പോഴതാ റസൂൽ(സ) ഖബ്റിൽ. അപ്പോൾ തിരുമേനി(സ) ഇപ്രകാരം പറയുകയായിരുന്നു. "നിങ്ങളുടെ കൂട്ടുകാരനെ എനിക്ക് എടുത്ത് തരൂ!" നോക്കുമ്പോൾ അയാൾ ഉച്ചത്തിൽ ദിക്റ് ചെല്ലുന്ന ആളായിരുന്നു. (ദ,തു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 844, 845, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 322, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَدْفِنُوا مَوْتَاكُمْ بِاللَّيْلِ إِلَّا أَنْ تُضْطَرُّوا". (جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിർബന്ധിതമായ സാഹചര്യമുണ്ടായാലല്ലാതെ രാത്രി നിങ്ങൾ ഖബറടക്കരുത്." (ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 845, 845, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 323, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "صَلُّوا عَلَى مَوْتَاكُمْ بِاللَّيْلِ وَالنَّهَارِ". [ز: في سنده راو ضعيف، ومدلس عنعنه] (جه)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "രാവിലും പകലിലും നിങ്ങൾ മരണപ്പെട്ടവർക്ക് നിസ്കരിച്ചുകൊള്ളുക." (ഇതിന്റെ സനദിൽ ദുർബലനായ റാവിയും ഇതിനെ അൻഅനയാക്കി ഉദ്ധരിച്ച മുദല്ലിസും ഉണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده راو ضعيف، ومدلس عنعنه', 'ഇതിന്റെ സനദിൽ ദുർബലനായ റാവിയും ഇതിനെ അൻഅനയാക്കി ഉദ്ധരിച്ച മുദല്ലിസും ഉണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 845, 845, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 324, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ – رَضِيَ اللهُ عَنْهُ – أَنَّهُ قَالَ: اشْتَكَتِ امْرَأَةٌ بِالْعَوَالِي مِسْكِينَةٌ، فَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَسْأَلُهُمْ عَنْهَا، وَقَالَ: "إِنْ مَاتَتْ فَلَا تَدْفِنُوهَا حَتَّى أُصَلِّيَ عَلَيْهَا". فَتُوُفِّيَتْ، فَجَاءُوا بِهَا إِلَى الْمَدِينَةِ بَعْدَ الْعَتَمَةِ، فَوَجَدُوا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ نَامَ، فَكَرِهُوا أَنْ يُوقِظُوهُ، فَصَلَّوْا عَلَيْهَا وَدَفَنُوهَا بِبَقِيعِ الْغَرْقَدِ، فَلَمَّا أَصْبَحَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَاءُوا فَسَأَلَهُمْ عَنْهَا فَقَالُوا: قَدْ دُفِنَتْ يَا رَسُولَ اللهِ، وَقَدْ جِئْنَاكَ فَوَجَدْنَاكَ نَائِمًا، فَكَرِهْنَا أَنْ نُوقِظَكَ. قَالَ: "فَانْطَلِقُوا". فَانْطَلَقَ يَمْشِي وَمَشَوْا مَعَهُ حَتَّى أَرُوهُ قَبْرَهَا، فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَصَفُّوا وَرَاءَهُ، فَصَلَّى عَلَيْهَا وَكَبَّرَ أَرْبَعًا. (ن)', 'അബൂഉമാമത്തുബ്നു സഹ്ല്(റ): അവാലിയിൽപ്പെട്ട ഒരു സാധു സ്ത്രീ രോഗിണിയായി. നബി(സ) അവരെ കുറിച്ച് ചോദിച്ചിരുന്നു. തിരുമേനി(സ) പറഞ്ഞു: "അവൾ മരിച്ചാൽ ഞാൻ നിസ്കരിക്കുന്നത് വരെ അവളെ മറമാടരുത്." അവൾ മരിച്ചു. രാത്രി വൈകിയശേഷം അവർ അവളെ മദീനയിലേക്ക് കൊണ്ടുവന്നു. റസൂൽ(സ) ഉറങ്ങിയതായി അവർ കണ്ടു. തിരുമേനി(സ)യെ ഉണർത്തുന്നത് അവർ വെറുത്തു. അവർ അവൾക്ക് വേണ്ടി നിസ്കരിച്ച് ബഖീഇൽ ഖബറടക്കി. നേരം പുലർന്ന സമയം അവർ തിരുമേനി(സ)യുടെ അടുക്കൽ വന്നപ്പോൾ പ്രവാചകൻ(സ) അവളെക്കുറിച്ച് ചോദിച്ചു. അവർ പറഞ്ഞു: പ്രവാചകരേ, അവൾ മറമാടപ്പെട്ടു. ഞങ്ങൾ താങ്കളുടെ അടുക്കൽ വന്നപ്പോൾ താങ്കൾ ഉറങ്ങുകയായിരുന്നു. താങ്കളെ ഉണർത്താൻ ഞങ്ങൾ ഇഷ്ടപ്പെട്ടില്ല. പ്രവാചകൻ(സ) അവരോട് പുറപ്പെടാൻ പറഞ്ഞു. നബി(സ)യും കൂടെ അവരും പുറപ്പെട്ടു. അവർ നബി(സ)ക്ക് ഖബർ കാണിച്ചു കൊടുത്തു. പ്രവാചകൻ(സ) നിന്നു. അവർ പിന്നിലും അണിയായി നിന്നു. പ്രവാചകൻ(സ) നാല് തക്ബീർ ചൊല്ലി അവൾക്ക് വേണ്ടി നിസ്കരിച്ചു. (ന)', 'أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ –', 'അബൂഉമാമത്തുബ്നു സഹ്ല്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 845, 845, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 325, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: ثَلَاثُ سَاعَاتٍ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْهَانَا أَنْ نُصَلِّيَ فِيهِنَّ أَوْ نَقْبُرَ فِيهِنَّ مَوْتَانَا: حِينَ تَطْلُعُ الشَّمْسُ بَازِغَةً حَتَّى تَرْتَفِعَ، وَحِينَ يَقُومُ قَائِمُ الظَّهِيرَةِ حَتَّى تَزُولَ الشَّمْسُ، وَحِينَ تَضَيَّفُ الشَّمْسُ لِلْغُرُوبِ. (م,د,ت,ن,جه)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): മൂന്നു സമയങ്ങളിൽ മയ്യിത്ത് നിസ്കരിക്കുന്നതും ഖബറടക്കുന്നതും നബി(സ) ഞങ്ങൾക്ക് നിരോധിച്ചിരുന്നു. സൂര്യൻ ഉദിച്ചതുമുതൽ ഉയരുന്നത് വരെ, ഉച്ചക്കുള്ള സൂര്യൻ നീങ്ങുന്നത് വരെ, സൂര്യൻ അസ്തമിക്കാൻ തുടങ്ങുന്നത് മുതൽ പൂർണ്ണമായി അസ്തമിക്കുന്നത് വരെ. (മു,ദ,തു,ന,ജ)', 'عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 845, 845, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 326, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ رَجُلًا مِنْ أَصْحَابِهِ مَاتَ، فَقُبِرَ لَيْلًا، وَكُفِّنَ فِي كَفَنٍ غَيْرِ طَائِلٍ، فَزَجَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُقْبَرَ إِنْسَانٌ لَيْلًا إِلَّا أَنْ يُضْطَرَّ إِلَى ذَلِكَ. (ن)', 'ജാബിർ(റ): മരണപ്പെടുകയും നീളമില്ലാത്ത ഒരു പുടവയിൽ കഫൻ ചെയ്യപ്പെടുകയും രാത്രി മറമാടപ്പെടുകയും ചെയ്ത ഒരു സ്വഹാബിയെ കുറിച്ച് നബി(സ) ഒരു പ്രസംഗത്തിൽ പറഞ്ഞു, ശേഷം പ്രവാചകൻ(സ) നിർബന്ധിത സാഹചര്യത്തിലല്ലാതെ രാത്രിയിൽ ഖബറടക്കപ്പെടുന്നത് നിരോധിച്ചു. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 846, 846, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 327, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا مَاتَ عَبْدُ اللهِ بْنُ أُبَيِّ ابْنِ سَلُولَ دُعِيَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِيُصَلِّيَ عَلَيْهِ، فَلَمَّا قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَثَبْتُ إِلَيْهِ فَقُلْتُ: يَا رَسُولَ اللهِ، تُصَلِّي عَلَى ابْنِ أُبَيٍّ وَقَدْ قَالَ يَوْمَ كَذَا وَكَذَا كَذَا وَكَذَا؟ أُعَدِّدُ عَلَيْهِ، فَتَبَسَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "أَخِّرْ عَنِّي يَا عُمَرُ". فَلَمَّا أَكْثَرْتُ عَلَيْهِ قَالَ: "إِنِّي قَدْ خُيِّرْتُ فَاخْتَرْتُ، فَلَوْ عَلِمْتُ أَنِّي لَوْ زِدْتُ عَلَى السَّبْعِينَ غُفِرَ لَهُ لَزِدْتُ عَلَيْهَا". فَصَلَّى عَلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ انْصَرَفَ، فَلَمْ يَمْكُثْ إِلَّا يَسِيرًا حَتَّى نَزَلَتِ الْآيَتَانِ مِنْ بَرَاءَةَ: {وَلَا تُصَلِّ عَلَى أَحَدٍ مِنْهُمْ مَاتَ أَبَدًا وَلَا تَقُمْ عَلَى قَبْرِهِ إِنَّهُمْ كَفَرُوا بِاللَّهِ وَرَسُولِهِ وَمَاتُوا وَهُمْ فَاسِقُونَ} [التوبة: ٨٤]. فَعَجِبْتُ بَعْدُ مِنْ جُرْأَتِي عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَئِذٍ، وَاللهُ وَرَسُولُهُ أَعْلَمُ. (ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): ഉമർ(റ) പറഞ്ഞു: അബ്ദുല്ലാഹിബ്നു ഉബയ്യുബ്നു സുലൂൽ മരണപ്പെട്ടപ്പോൾ അദ്ദേഹത്തിന് വേണ്ടി നിസ്കരിക്കാൻ നബി(സ) ക്ഷണിക്കപ്പെട്ടു. നബി(സ) നിസ്കരിക്കാൻ നിന്നപ്പോൾ ഞാൻ തിരുമേനി(സ)യുടെ അടുത്തേക്ക് ചാടിവീണു. എന്നിട്ട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലെ! അങ്ങനെയും ഇങ്ങനെയുമൊക്കെ പറഞ്ഞ ഇബ്നുഉബയ്യിന് വേണ്ടി താങ്കൾ നിസ്കരിക്കുകയോ? ഞാൻ ഓരോ കാര്യങ്ങൾ എണ്ണിപ്പറഞ്ഞു. അപ്പോൾ നബി(സ) ചിരിച്ചിട്ടു പറഞ്ഞു: "ഉമറേ! എന്റെ അടുത്ത് നിന്ന് പിന്നോട്ട് പോകൂ!" എന്നിട്ട് പറഞ്ഞു: "എനിക്ക് നല്ലതായി തോന്നിയത് ഞാൻ എടുത്തു. ഞാൻ എഴുപത് പ്രാവശ്യത്തിലധികം പൊറുക്കലിനെ തേടിയാൽ അദ്ദേഹത്തിന് പൊറുത്തു കിട്ടുമെങ്കിൽ ഞാൻ അത്രയും വർദ്ധിപ്പിക്കും." അങ്ങനെ നബി(സ) നിസ്കരിച്ചു. പിന്നെ പിരിഞ്ഞു പോയി. അൽപം കഴിഞ്ഞപ്പോഴേക്കും സുറഃ ബറാഅഃയിലെ രണ്ടായത്തുകൾ ഇറങ്ങി. ''അവരിൽ നിന്ന് മരിച്ച ഒരാൾക്കും ഒരിക്കലും അങ്ങ് നിസ്കരിക്കരുത്. അവരുടെ ഖബറിൻ മുകളിൽ നിൽക്കരുത്. അവർ അല്ലാഹുവിലും റസൂലിലും അവിശ്വസിക്കുകയും തെമ്മാടികളായി മരിക്കുകയും ചെയ്തിരിക്കുന്നു.'' (അത്തൗബഃ: 84) അന്ന് റസൂലിനോട് കാണിച്ച ധൈര്യമോർത്ത് ഞാൻ പിന്നീട് അത്ഭുതപ്പെട്ടുപോയി. അല്ലാഹുവും അവന്റെ ദൂതനും ഏറ്റവും അറിയുന്നവരാണ്. (ന)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'التوبة: ٨٤', null, 846, 846, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 328, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَاتَ رَأْسُ الْمُنَافِقِينَ بِالْمَدِينَةِ، وَأَوْصَى أَنْ يُصَلِّيَ عَلَيْهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَأَنْ يُكَفِّنَهُ فِي قَمِيصِهِ. فَصَلَّى عَلَيْهِ وَكَفَّنَهُ فِي قَمِيصِهِ وَقَامَ عَلَى قَبْرِهِ، فَأَنْزَلَ اللهُ: {وَلَا تُصَلِّ عَلَى أَحَدٍ مِنْهُمْ مَاتَ أَبَدًا وَلَا تَقُمْ عَلَى قَبْرِهِ}. (جه)', 'ജാബിർ(റ): മുനാഫിഖുകളുടെ നേതാവ് മദീനയിൽ വെച്ച് മരണപ്പെട്ടു. നബി(സ) അയാൾക്ക് വേണ്ടി നിസ്കരിക്കണമെന്നും അവിടുത്തെ കുപ്പായത്തിൽ കഫൻ ചെയ്യണമെന്നും അയാൾ വസ്വിയ്യത് ചെയ്തു. നബി(സ) അദ്ദേഹത്തിന് വേണ്ടി നിസ്കരിക്കുകയും തിരുമേനി(സ)യുടെ വസ്ത്രത്തിൽ അദ്ദേഹത്തെ കഫൻ ചെയ്യുകയും ഖബറിന്റെ അടുത്ത് (പ്രാർത്ഥനക്ക്) നിൽക്കുകയും ചെയ്തു. ആ ഘട്ടത്തിൽ ''അവരിൽ നിന്ന് മരിച്ച ആരുടേയും ഖബ്റിന്നരികിൽ നീ നിൽക്കുകയോ അവർക്ക് വേണ്ടി നിസ്കരിക്കുകയോ ചെയ്യരുത്'' എന്ന ആയത്തിറങ്ങി. (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 846, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 329, 'عَنْ وَاثِلَةَ بْنِ الْأَسْقَعِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَلُّوا عَلَى كُلِّ مَيِّتٍ، وَجَاهِدُوا مَعَ كُلِّ أَمِيرٍ". [ز: سنده ضعيف] (جه)', 'വാസിലതുബ്നുൽ അസ്കഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ എല്ലാ മയ്യിത്തിനും നിസ്കരിക്കുക, എല്ലാ അമീറിനും പിന്നിൽ നിന്ന് യുദ്ധം ചെയ്യുക." (പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ).', 'وَاثِلَةَ بْنِ الْأَسْقَعِ', 'വാസിലതുബ്നുൽ അസ്കഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: سنده ضعيف', 'പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 330, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جُرِحَ، فَآذَتْهُ الْجِرَاحَةُ، فَدَبَّ إِلَى مَشَاقِصَ فَذَبَحَ بِهَا نَفْسَهُ، فَلَمْ يُصَلِّ عَلَيْهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ: وَكَانَ ذَلِكَ مِنْهُ أَدَبًا. (ت,جه)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ)യുടെ സഹാബിമാരിലൊരാൾക്ക് മുറിവ് പറ്റി. വേദന അയാൾക്ക് വളരെ പ്രയാസമായി. അയാൾ ഒരു കുന്തത്തിനടുത്തേക്ക് നിരങ്ങിയെത്തി അത് കൊണ്ട് സ്വയം അറുത്തു. നബി(സ) അയാൾക്കു വേണ്ടി നിസ്കരിച്ചില്ല. റിപ്പോർട്ടർ പറയുന്നു: അത് അവിടുന്നുള്ള മര്യാദയായിരുന്നു. (തു,ജ)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 331, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَرَأَ عَلَى الْجِنَازَةِ بِفَاتِحَةِ الْكِتَابِ. (خ,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഒരു ജനാസക്ക് ഫാതിഹ ഓതി. (ബു,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','ت','جه']::text[], array['ബു','തു','ജ']::text[], null, null, 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 332, 'عَنْ أُمِّ شَرِيكٍ الْأَنْصَارِيَّةِ رَضِيَ اللهُ عَنْهُمَا قَالَتْ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نَقْرَأَ عَلَى الْجِنَازَةِ بِفَاتِحَةِ الْكِتَابِ. (جه)', 'ഉമ്മുശരീക്(റ): ജനാസക്ക് ഫാതിഹ ഓതാൻ നബി(സ) ഞങ്ങളോട് കൽപ്പിച്ചു. (ജ)', 'أُمِّ شَرِيكٍ الْأَنْصَارِيَّةِ', 'ഉമ്മുശരീക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 333, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: صَلَّى عَلَى جِنَازَةٍ فَقَرَأَ بِفَاتِحَةِ الْكِتَابِ، قَالَ: لِيَعْلَمُوا أَنَّهَا سُنَّةٌ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): അദ്ദേഹം ഒരു ജനാസ നിസ്കരിച്ചു. അപ്പോൾ ഫാതിഹ ഓതി. അദ്ദേഹം പറഞ്ഞു: ഇത് സുന്നത്താണെന്ന് അവരറിയാനാണ്. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 334, 'عَنْ مَعْقِلِ بْنِ يَسَارٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اقْرَءُوا {يس} عَلَى مَوْتَاكُمْ". (د,جه)', 'മുഅ്ഖിലുബ്നുയസാർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ മരണം ആസന്നമായവർക്ക് നിങ്ങൾ യാസീൻ ഓതുക." (ദ,ജ)', 'مَعْقِلِ بْنِ يَسَارٍ', 'മുഅ്ഖിലുബ്നുയസാർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 335, 'عَنْ طَلْحَةَ بْنِ عَبْدِ اللهِ بْنِ عَوْفٍ قَالَ: صَلَّيْتُ مَعَ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا عَلَى جِنَازَةٍ فَقَرَأَ بِفَاتِحَةِ الْكِتَابِ، فَقَالَ: إِنَّهَا مِنَ السُّنَّةِ. (خ,د,ت,ن)', 'ത്വൽഹ(റ): ഞാൻ ഇബ്നുഅബ്ബാസി(റ)നോടൊത്ത് ഒരു ജനാസ നിസ്കരിച്ചു. അദ്ദേഹം ഫാതിഹ പാരായണം ചെയ്തു. തുടർന്ന് പറഞ്ഞു: അത് സുന്നത്തിൽപെട്ടതാണ്. (ബു,ദ,തു,ന)', 'طَلْحَةَ بْنِ عَبْدِ اللهِ بْنِ عَوْفٍ قَالَ', 'ത്വൽഹ(റ)', null, null, array['خ','د','ت','ن']::text[], array['ബു','ദ','തു','ന']::text[], null, null, 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 336, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِرَجُلٍ مِنَ الْأَنْصَارِ لِيُصَلِّيَ عَلَيْهِ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَلُّوا عَلَى صَاحِبِكُمْ، فَإِنَّ عَلَيْهِ دَيْنًا". قَالَ أَبُو قَتَادَةَ: هُوَ عَلَيَّ. قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بِالْوَفَاءِ". قَالَ: بِالْوَفَاءِ. فَصَلَّى عَلَيْهِ. (ت,ن)', 'അബൂഖതാദ(റ): അൻസാരികളിലൊരാളുടെ മയ്യിത്ത് നബി(സ)യുടെ അടുത്ത് നിസ്കരിക്കാനായി കൊണ്ടുവന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ സുഹൃത്തിന് വേണ്ടി നിങ്ങൾ നിസ്കരിക്കുക. അദ്ദേഹത്തിന് കടബാധ്യതയുണ്ട്." അബൂഖതാദ(റ) പറഞ്ഞു: ആ ബാധ്യത ഞാൻ ഏറ്റെടുക്കാം. നബി(സ) അദ്ദേഹത്തോട് വാക്ക് പൂർത്തീകരിക്കാണമെന്നു പറഞ്ഞു. അദ്ദേഹം അത് സമ്മതിച്ചു. അപ്പോൾ നബി(സ) മയ്യിത്തിന് വേണ്ടി നിസ്കരിച്ചു. (തു,ന)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 848, 848, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 337, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُ قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِجَنَازَةٍ، فَقَالُوا: يَا نَبِيَّ اللهِ، صَلِّ عَلَيْهَا. قَالَ: "هَلْ تَرَكَ عَلَيْهِ دَيْنًا". قَالُوا: نَعَمْ. قَالَ: "هَلْ تَرَكَ مِنْ شَيْءٍ". قَالُوا: لَا. قَالَ: "صَلُّوا عَلَى صَاحِبِكُمْ". قَالَ رَجُلٌ مِنَ الْأَنْصَارِ يُقَالُ لَهُ أَبُو قَتَادَةَ: صَلِّ عَلَيْهِ وَعَلَيَّ دَيْنُهُ. فَصَلَّى عَلَيْهِ. (ن)', 'സലമതുബ്നുൽ അക്വഅ്(റ): നബി(സ)യുടെ അടുത്ത് ഒരു ജനാസ കൊണ്ടുവന്നു, അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, ഇദ്ദേഹത്തിന് വേണ്ടി താങ്കൾ നിസ്കരിക്കുക. നബി(സ) ചോദിച്ചു: "അദ്ദേഹത്തിന് വല്ല കടബാധ്യതയുമുണ്ടോ?" അവർ പറഞ്ഞു: അതെ. "അദ്ദേഹം വിട്ടേച്ചുപോയ വല്ല സ്വത്തുമുണ്ടോ?" നബി(സ) ചോദിച്ചു. അവർ ഇല്ലെന്ന് പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ സുഹൃത്തിന് വേണ്ടി നിങ്ങൾ നിസ്കരിച്ചുകൊള്ളുക." അപ്പോൾ അൻസാരികളിൽ പെട്ട അബൂഖതാദ(റ) പറഞ്ഞു: അദ്ദേഹത്തിന്റെ കടം ഞാൻ ഏറ്റെടുക്കാം. താങ്കൾ അദ്ദേഹത്തിന് വേണ്ടി നിസ്കരിക്കുക. അപ്പോൾ നബി(സ) നിസ്കരിച്ചു. (ന)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നുൽ അക്വഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 848, 848, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 338, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يُصَلِّي عَلَى رَجُلٍ عَلَيْهِ دَيْنٌ، فَأُتِيَ بِمَيِّتٍ فَسَأَلَ: "أَعَلَيْهِ دَيْنٌ". قَالُوا: نَعَمْ، عَلَيْهِ دِينَارَانِ. قَالَ: "صَلُّوا عَلَى صَاحِبِكُمْ". قَالَ أَبُو قَتَادَةَ: هُمَا عَلَيَّ يَا رَسُولَ اللهِ. فَصَلَّى عَلَيْهِ، فَلَمَّا فَتَحَ اللهُ عَلَى رَسُولِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَنَا أَوْلَى بِكُلِّ مُؤْمِنٍ مِنْ نَفْسِهِ، مَنْ تَرَكَ دَيْنًا فَعَلَيَّ، وَمَنْ تَرَكَ مَالًا فَلِوَرَثَتِهِ". (ن)', 'ജാബിർ(റ): നബി(സ) കടക്കാർക്ക് വേണ്ടി മയ്യിത്ത് നിസ്കരിച്ചിരുന്നില്ല. ഒരു മയ്യിത്ത് തിരുമേനി(സ)യുടെ അടുത്ത് കൊണ്ടുവന്നു. തിരുമേനി(സ) ചോദിച്ചു. "അയാൾക്ക് കടബാധ്യതയുണ്ടോ?" അവർ പറഞ്ഞു. അതെ. അദ്ദേഹത്തിന് രണ്ട് ദീനാർ കടമുണ്ട്. പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങളുടെ കൂട്ടുകാരന് വേണ്ടി നിങ്ങൾ നിസ്കിരിക്കുക." അബൂഖതാദ(റ) പറഞ്ഞു: അത് രണ്ടും ഞാൻ ഏറ്റെടുത്തു അല്ലാഹുവിന്റെ ദൂതരെ. അപ്പോൾ നബി(സ) അദ്ദേഹത്തിനുവേണ്ടി നിസ്കരിച്ചു. ശേഷം അല്ലാഹു റസൂലി(സ)ന് വിജയം നൽകിയപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ഓരോ സത്യവിശ്വാസിക്കും അവനേക്കാൾ അടുത്ത ആൾ ഞാനാണ്. ആരെങ്കിലും കടത്തോടെ മരിച്ചാൽ അവന്റെ കടം വീട്ടൽ എന്റെ ബാധ്യതയാണ്. ആരെങ്കിലും സ്വത്തുപേക്ഷിച്ചുപോയാൽ അത് അവന്റെ അനന്തരാവകാശിക്കാണ്." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 848, 848, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 339, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُؤْتَى بِالرَّجُلِ الْمُتَوَفَّى، عَلَيْهِ الدَّيْنُ، فَيَقُولُ: "هَلْ تَرَكَ لِدَيْنِهِ مِنْ قَضَاءٍ". فَإِنْ حُدِّثَ أَنَّهُ تَرَكَ وَفَاءً صَلَّى عَلَيْهِ، وَإِلَّا قَالَ لِلْمُسْلِمِينَ: "صَلُّوا عَلَى صَاحِبِكُمْ". فَلَمَّا فَتَحَ اللهُ عَلَيْهِ الْفُتُوحَ قَامَ فَقَالَ: "أَنَا أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ، فَمَنْ تُوُفِّيَ مِنَ الْمُسْلِمِينَ فَتَرَكَ دَيْنًا عَلَيَّ قَضَاؤُهُ، وَمَنْ تَرَكَ مَالًا فَهُوَ لِوَرَثَتِهِ". حَسَنٌ صَحِيحٌ. (ق,ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ)യുടെ അടുത്ത് കടബാധ്യതയുള്ള ആരെയെങ്കിലും കൊണ്ടുവന്നാൽ ചോദിക്കും: "അയാളുടെ കടം വീട്ടാൻ വല്ലതും വെച്ചിട്ടുണ്ടോ?" വെച്ചിട്ടുണ്ട് എന്ന് മറുപടി ലഭിച്ചാൽ നബി(സ) നിസ്കരിക്കും. ഇല്ല എന്ന് അവർ പറഞ്ഞാൽ നബി(സ) പറയും: "നിങ്ങളുടെ സുഹൃത്തിന് നിങ്ങൾ നിസ്കരിക്കുക." നബി(സ)ക്ക് അല്ലാഹു വിജയം നൽകിയപ്പോൾ നബി(സ) പറഞ്ഞു: "മുഅ്മിനുകളുമായി അവരേക്കാൾ അടുത്തവനാണ് ഞാൻ. ആരെങ്കിലും കടത്തോടെ മരിച്ചാൽ അത് വീട്ടൽ എന്റെ ബാധ്യതയാണ്. ആരെങ്കിലും സമ്പത്തുപേക്ഷിച്ചാൽ അത് അവന്റെ അനന്തരാവകാശികൾക്കാണ്." ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,മു,തുന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തുന']::text[], null, null, 848, 849, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 340, 'عَنْ زَيْدِ بْنِ خَالِدٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَاتَ رَجُلٌ بِخَيْبَرَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَلُّوا عَلَى صَاحِبِكُمْ، إِنَّهُ غَلَّ فِي سَبِيلِ اللهِ". فَفَتَّشْنَا مَتَاعَهُ فَوَجَدْنَا فِيهِ خَرَزًا مِنْ خَرَزِ يَهُودَ، مَا يُسَاوِي دِرْهَمَيْنِ. (ن)', 'സൈദുബ്നുഖാലിദ്(റ): ഒരാൾ ഖൈബറിൽ വെച്ച് മരണമടഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിങ്ങളുടെ സഹോദരന് വേണ്ടി നിസ്കരിക്കുക. അദ്ദേഹം ദൈവമാർഗ്ഗത്തിൽ പോരാടിക്കൊണ്ടിരിക്കെ പൂഴ്തിവെപ്പ് നടത്തിയിരിക്കുന്നു." ഞങ്ങൾ അദ്ദേഹത്തിന്റെ സാധനങ്ങൾ പരിശോധിച്ചു. അപ്പോൾ യഹൂദികൾ ഉപയോഗിക്കുന്ന രണ്ട് ദിർഹം വിലവരുന്ന ഒരു മണി അതിൽ കണ്ടു. (ന)', 'زَيْدِ بْنِ خَالِدٍ', 'സൈദുബ്നുഖാലിദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 849, 849, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 341, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا مِنْ أَسْلَمَ جَاءَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاعْتَرَفَ بِالزِّنَا، فَأَعْرَضَ عَنْهُ، ثُمَّ اعْتَرَفَ فَأَعْرَضَ عَنْهُ، حَتَّى شَهِدَ عَلَى نَفْسِهِ أَرْبَعَ مَرَّاتٍ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَبِكَ جُنُونٌ". قَالَ: لَا. قَالَ: "أَحْصَنْتَ". قَالَ: نَعَمْ. فَأَمَرَ بِهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرُجِمَ، فَلَمَّا أَذْلَقَتْهُ الْحِجَارَةُ فَرَّ، فَأُدْرِكَ فَرُجِمَ فَمَاتَ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَيْرًا، وَلَمْ يُصَلِّ عَلَيْهِ. (ن)', 'ജാബിർ(റ): അസ്ലം ഗോത്രത്തിൽപെട്ട ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്ന് വ്യഭിചാരകുറ്റം ഏറ്റുപറഞ്ഞു. നബി(സ) അദ്ദേഹത്തിൽ നിന്നും തിരിഞ്ഞു. വീണ്ടും അദ്ദേഹം കുറ്റം ഏറ്റു പറഞ്ഞു. അപ്പോഴും നബി(സ) തിരിഞ്ഞു. വീണ്ടും അദ്ദേഹം കുറ്റം നബി(സ)യോട് ഏറ്റുപറഞ്ഞു. നബി(സ) വീണ്ടും തിരിഞ്ഞു. അങ്ങനെ നാല് പ്രാവശ്യം അദ്ദേഹം സ്വന്തം സാക്ഷ്യം വഹിച്ചു. പ്രവാചകൻ(സ) അയാളോട് ചോദിച്ചു: "താങ്കൾക്ക് ഭ്രാന്തുണ്ടോ?" അയാൾ പറഞ്ഞു: ഇല്ല. പിന്നെ നബി(സ) ചോദിച്ചു: "നീ വിവാഹിതനാണോ?" അയാൾ ''അതെ'' എന്ന് പറഞ്ഞു. നബി(സ)യുടെ കൽപനപ്രകാരം അയാളെ കല്ലെറിഞ്ഞു. ഏറ് കൊണ്ട് സഹിക്കാതായപ്പോൾ അയാൾ ഓടി. അദ്ദേഹത്തെ പിടിച്ചുവെച്ച് എറിഞ്ഞ് കൊന്നു. നബി(സ) അദ്ദേഹത്തിന് വേണ്ടി നല്ലത് പറഞ്ഞു. മയ്യിത്ത് നിസ്കരിച്ചില്ല. (ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 849, 849, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 342, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةً مِنْ جُهَيْنَةَ أَتَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: إِنِّي زَنَيْتُ. وَهِيَ حُبْلَى، فَدَفَعَهَا إِلَى وَلِيِّهَا فَقَالَ: "أَحْسِنْ إِلَيْهَا، فَإِذَا وَضَعَتْ فَأْتِنِي بِهَا". فَلَمَّا وَضَعَتْ جَاءَ بِهَا، فَأَمَرَ بِهَا فَشُكَّتْ عَلَيْهَا ثِيَابُهَا، ثُمَّ رَجَمَهَا، ثُمَّ صَلَّى عَلَيْهَا. فَقَالَ لَهُ عُمَرُ رَضِيَ اللهُ عَنْهُ: أَتُصَلِّي عَلَيْهَا وَقَدْ زَنَتْ؟ فَقَالَ: "لَقَدْ تَابَتْ تَوْبَةً لَوْ قُسِمَتْ بَيْنَ سَبْعِينَ مِنْ أَهْلِ الْمَدِينَةِ لَوَسِعَتْهُمْ، وَهَلْ وَجَدْتَ تَوْبَةً أَفْضَلَ مِنْ أَنْ جَادَتْ بِنَفْسِهَا لِلَّهِ عَزَّ وَجَلَّ". (ن)', 'ഇംറാൻ ഇബ്നുഹുസൈൻ(റ): ജുഹൈന ഗോത്രക്കാരിയായ ഒരു സ്ത്രീ നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: ഞാൻ വ്യഭിചരിച്ചു, - അവൾ ഗർഭിണിയായിരുന്നു. - അപ്പോൾ നബി(സ) അവരെ അവളുടെ രക്ഷിതാവിനെ ഏൽപിച്ചിട്ടു പറഞ്ഞു: "നിങ്ങൾ അവളോട് നന്നായി വർത്തിക്കുക. പ്രസവിച്ചു കഴിഞ്ഞാൽ എന്റെ അടുത്ത് കൊണ്ടുവരിക." പ്രസവം കഴിഞ്ഞപ്പോൾ അവളേയും കൂട്ടി നബി(സ)യുടെ അടുത്തു വന്നു. വസ്ത്രം അവളിലേക്ക് മുറുക്കി ഉടുപ്പിച്ചു. പിന്നെ അവളെ എറിഞ്ഞുകൊന്നു. അവൾക്ക് വേണ്ടി നബി(സ) നിസ്കരിക്കുകയും ചെയ്തു. അപ്പോൾ ഉമർ(റ) നബി(സ)യോട് ചോദിച്ചു: വ്യഭിചരിച്ച ആ സ്ത്രീക്ക് വേണ്ടി താങ്കൾ നിസ്കരിക്കുകയോ? അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവൾ ചെയ്ത ആ തൗബ മദീനയിലെ എഴുപത് ആളുകൾക്ക് ഓഹരി വെച്ച് കൊടുത്താൽ അവർക്ക് മുഴുവൻ അത് മതിയാകും. മഹോന്നതനായ അല്ലാഹുവിന് സ്വന്തത്തെ അർപ്പിച്ച ഈ സ്ത്രീയുടേതിനേക്കാൾ നല്ല വല്ല തൗബയും നീ കണ്ടിട്ടുണ്ടോ?" (ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാൻ ഇബ്നുഹുസൈൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 850, 850, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 343, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا أَعْتَقَ سِتَّةً مَمْلُوكِينَ لَهُ عِنْدَ مَوْتِهِ، وَلَمْ يَكُنْ لَهُ مَالٌ غَيْرُهُمْ، فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَغَضِبَ مِنْ ذَلِكَ وَقَالَ: "لَقَدْ هَمَمْتُ أَنْ لَا أُصَلِّيَ عَلَيْهِ". ثُمَّ دَعَا مَمْلُوكِيهِ فَجَزَّأَهُمْ ثَلَاثَةَ أَجْزَاءٍ، ثُمَّ أَقْرَعَ بَيْنَهُمْ، فَأَعْتَقَ اثْنَيْنِ وَأَرَقَّ أَرْبَعَةً. (ن)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): ഒരാൾ തന്റെ പക്കലുണ്ടായിരുന്ന ആറ് അടിമകളേയും തന്റെ മരണസമത്ത് മോചിപ്പിച്ചു. അവരല്ലാത്ത ഒരു ധനവും അദ്ദേഹത്തിന് ഉണ്ടായിരുന്നില്ല. ആ വിവരം നബി(സ)ക്ക് ലഭിച്ചു. നബി(സ) ദേഷ്യപ്പെട്ടുകൊണ്ട് പറഞ്ഞു: "അവന് വേണ്ടി നിസ്കരിക്കുകയില്ല എന്ന് ഞാൻ തീരുമാനിച്ചിരിക്കുന്നു." പിന്നീട് നബി(സ) ആ അടിമകളെ വിളിച്ച് മൂന്ന് ഓഹരിയാക്കി. പിന്നെ അവർക്കിടയിൽ നറുക്കിട്ടു. രണ്ടാളെ മോചിപ്പിച്ചു. നാല് പേരെ അടിമകളാക്കി. (ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 850, 850, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 344, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ يَوْمًا فَصَلَّى عَلَى أَهْلِ أُحُدٍ صَلَاتَهُ عَلَى الْمَيِّتِ ثُمَّ انْصَرَفَ إِلَى الْمِنْبَرِ، فَقَالَ: "إِنِّي فَرَطُكُمْ، وَأَنَا شَهِيدٌ عَلَيْكُمْ، وَإِنِّي وَاللهِ لَأَنْظُرُ إِلَى حَوْضِي الْآنَ، وَإِنِّي أُعْطِيتُ مَفَاتِيحَ خَزَائِنِ الْأَرْضِ أَوْ مَفَاتِيحَ الْأَرْضِ، وَإِنِّي وَاللهِ مَا أَخَافُ عَلَيْكُمْ أَنْ تُشْرِكُوا بَعْدِي، وَلَكِنْ أَخَافُ عَلَيْكُمْ أَنْ تَنَافَسُوا فِيهَا". (خ,ن)', 'ഉഖ്ബത്തുബ്നു ആമിർ(റ): നബി(സ) ഒരു ദിവസം പുറഞ്ഞിറങ്ങി, ഉഹ്ദുകാർക്ക് മയ്യിത്ത് നിസ്കരിച്ചു. പിന്നെ മിമ്പറിലേക്ക് തിരിഞ്ഞു. എന്നിട്ട് പറഞ്ഞു: "ഞാൻ നിങ്ങൾക്ക് മുമ്പേ എത്തുന്നവനാണ്. നിങ്ങൾക്ക് മേലുള്ള സാക്ഷിയാണ് ഞാൻ. അല്ലാഹുവാണെ, ഇപ്പോൾ തീർച്ചയായും ഞാനെന്റെ ഹൗളിലേക്ക് നോക്കുകയാണ്. നിശ്ചയം ഭൂമിയുടെ ഖജനാവുകളുടെ താക്കോലുകൾ എനിക്ക് ലഭിച്ചിരിക്കുന്നു. നിശ്ചയം, അല്ലാഹുവാണ എനിക്ക് ശേഷം നിങ്ങൾ ശിർക്ക് ചെയ്യുന്നതിനെ തീർച്ചയായും ഞാൻ ഭയപ്പെടുന്നില്ല. എന്നാൽ നിങ്ങൾ എനിക്കുശേഷം അതിൽ (ഐഹികതയിൽ) മൽസരിക്കുമെന്ന് ഞാൻ ഭയപ്പെടുന്നു." (ബു,ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബത്തുബ്നു ആമിർ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 850, 851, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 345, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: انْطَلَقَ عُمَرُ رَضِيَ اللهُ عَنْهُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي رَهْطٍ قِبَلَ ابْنِ صَيَّادٍ حَتَّى وَجَدُوهُ يَلْعَبُ مَعَ الصِّبْيَانِ عِنْدَ أُطُمِ بَنِي مَغَالَةَ، وَقَدْ قَارَبَ ابْنُ صَيَّادٍ الْحُلُمَ فَلَمْ يَشْعُرْ حَتَّى ضَرَبَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ، ثُمَّ قَالَ لِابْنِ صَيَّادٍ: "تَشْهَدُ أَنِّي رَسُولُ اللهِ". فَنَظَرَ إِلَيْهِ ابْنُ صَيَّادٍ فَقَالَ: أَشْهَدُ أَنَّكَ رَسُولُ الْأُمِّيِّينَ، فَقَالَ ابْنُ صَيَّادٍ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَتَشْهَدُ أَنِّي رَسُولُ اللهِ. فَرَفَضَهُ وَقَالَ: "آمَنْتُ بِاللهِ وَبِرُسُلِهِ". فَقَالَ لَهُ: "مَاذَا تَرَى؟" قَالَ ابْنُ صَيَّادٍ: يَأْتِينِي صَادِقٌ وَكَاذِبٌ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خُلِّطَ عَلَيْكَ الْأَمْرُ". ثُمَّ قَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي قَدْ خَبَأْتُ لَكَ خَبْئًا". فَقَالَ ابْنُ صَيَّادٍ: هُوَ الدُّخُّ، فَقَالَ: "اخْسَأْ، فَلَنْ تَعْدُوَ قَدْرَكَ". فَقَالَ عُمَرُ رَضِيَ اللهُ عَنْهُ: دَعْنِي يَا رَسُولَ اللهِ أَضْرِبْ عُنُقَهُ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنْ يَكُنْهُ فَلَنْ تُسَلَّطَ عَلَيْهِ، وَإِنْ لَمْ يَكُنْهُ فَلَا خَيْرَ لَكَ فِي قَتْلِهِ". قَالَ ابْنُ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: ثُمَّ انْطَلَقَ بَعْدَ ذَلِكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأُبَيُّ بْنُ كَعْبٍ إِلَى النَّخْلِ الَّتِي فِيهَا ابْنُ صَيَّادٍ، وَهُوَ يَخْتِلُ أَنْ يَسْمَعَ مِنِ ابْنِ صَيَّادٍ شَيْئًا، قَبْلَ أَنْ يَرَاهُ ابْنُ صَيَّادٍ، فَرَآهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مُضْطَجِعٌ فِي قَطِيفَةٍ لَهُ فِيهَا رَمْزَةٌ، فَرَأَتْ أُمُّ ابْنِ صَيَّادٍ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَتَّقِي بِجُذُوعِ النَّخْلِ فَقَالَتْ لِابْنِ صَيَّادٍ: يَا صَافِ، وَهُوَ اسْمُ ابْنِ صَيَّادٍ، هَذَا مُحَمَّدٌ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَثَارَ ابْنُ صَيَّادٍ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْ تَرَكَتْهُ بَيَّنَ". (ق)', 'ഇബ്നുഉമർ(റ): ഉമർ(റ) നബി(സ)യോടൊപ്പം ഒരു സംഘവുമായി ഇബ്നുസയ്യാദിനെ കാണാൻ പോയി. അവൻ ബനൂമഗാല ഗോത്രത്തിന്റെ ഒരുമതിലിനടുത്ത് കുറെ കുട്ടികളുമായി കളിക്കുന്നതാണ് അവർ കണ്ടത്. ഇബ്നുസയ്യാദ് പ്രായപൂർത്തിക്കടുത്ത് വരുന്നേ ഉണ്ടായിരുന്നുള്ളൂ അന്ന്. നബി(സ) അവനെ കൈകൊണ്ട് തട്ടുന്നത് വരെ അവർ അവിടെ വന്നത് അവൻ അറിഞ്ഞിരുന്നില്ല. പിന്നെ നബി(സ) ഇബ്നുസയ്യാദിനോട് ചോദിച്ചു: "ഞാൻ അല്ലാഹുവിന്റെ ദൂതനാണെന്ന് നീ സാക്ഷ്യം വഹിക്കുന്നുണ്ടോ?" താങ്കൾ അക്ഷരജ്ഞാനമില്ലാത്തവരുടെ പ്രവാചകനാണെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു എന്ന് അവൻ നബി(സ)യെ നോക്കികൊണ്ട് പറഞ്ഞു. തുടർന്ന് ഇബ്നുസയ്യാദ് നബി(സ)യോട് ചോദിച്ചു: ഞാൻ അല്ലാഹുവിന്റെ ദൂതനാണെന്ന് താങ്കൾ സമ്മതിക്കുന്നുണ്ടോ? നബി(സ) അത് വിസമ്മതിച്ചുകൊണ്ട് പറഞ്ഞു: "ഞാൻ അല്ലാഹുവിലും അവന്റെ ദൂതന്മാരിലും വിശ്വസിച്ചിരിക്കുന്നു." "നിന്റെ അഭിപ്രായമെന്താണ്" എന്ന് ചോദിച്ചപ്പോൾ എനിക്ക് സത്യവും അസത്യവുമായ വിവരങ്ങൾ ലഭിക്കുന്നുവെന്ന് ഇബ്നുസയ്യാദ് മറുപടി പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിനക്ക് കാര്യങ്ങളുടെ യാഥാർത്ഥ്യം മനസ്സിലാകാതെ വന്നിട്ടുണ്ട്." ശേഷം പറഞ്ഞു: "നിന്നെ പരീക്ഷിക്കാൻ വേണ്ടി ഞാൻ എന്റെ മനസ്സിൽ ഒരു സംഗതി മറച്ച് വെച്ചിട്ടുണ്ട്." താങ്കൾ മനസ്സിൽ ഒളിപ്പിച്ചു വെച്ച കാര്യം ''ദുഖ്'' (പുക) ആണ് എന്ന് ഇബ്നുസയ്യാദ് പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "മിണ്ടാതിരിക്കൂ, നിനക്ക് നിന്റെ നിലവാരത്തിൽ നിന്ന് ഉയരാൻ കഴിയില്ല." അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ: അവന്റെ പിരടി വെട്ടാൻ എന്നെ അനുവദിച്ചാലും. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇവൻ നാം ഉദ്ദേശിച്ചവനാണെങ്കിൽ അവന്റെ മേൽ നിനക്ക് അധികാരം നൽകിയിട്ടില്ല. ഇവൻ അപ്പറഞ്ഞവനല്ലെങ്കിൽ ഇവനെ കൊല്ലുന്നതിൽ താങ്കൾക്ക് യാതൊരു നന്മയുമില്ലതാനും." ഇബ്നുഉമർ(റ) പറയുന്നു: പിന്നീട് നബി(സ) ഉബയ്യി(റ)ന്റെ കൂടെ ഇബ്നുസയ്യാദ് താമസിക്കുന്ന ഈതപനത്തോട്ടത്തിലേക്ക് പോയി. ഇബ്നുസയ്യാദ് നബി(സ)യെ കാണുന്നതിന് മുമ്പ് അവനിൽ നിന്ന് എന്തെങ്കിലും കേൾക്കാൻ ഒന്നും ശ്രദ്ധിക്കാത്ത മട്ടിൽ നബി(സ) അവിടെ ചെന്നു. അവൻ ഒരു വസ്ത്രത്തിൽ കിടന്ന് എന്തോ പിറുപിറുക്കുന്നതായി നബി(സ) കണ്ടു. അപ്പോൾ ഇബ്നുസയ്യാദിന്റെ മാതാവ് റസൂലി(സ)നെ കണ്ടു. അവിടുന്ന് ഈത്തപ്പനമറവിൽ പതിഞ്ഞ് നിൽക്കുകയായിരുന്നു. അപ്പോൾ അവൾ ഇബ്നുസയ്യാദിനോട് പറഞ്ഞു: സ്വാഫീ - അതായിരുന്നു ഇബ്നുസയ്യാദിന്റെ പേര് - മുഹമ്മദ്(സ) ഇതാ നിൽക്കുന്നു. അപ്പോൾ ഇബ്നുസയ്യാദ് ചാടിയെണീറ്റു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവൾ അവനെ വിട്ടിരുന്നുവെങ്കിൽ കാര്യം വ്യക്തമാകുമായിരുന്നു." (ബു,മു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 851, 852, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 346, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ مَوْلُودٍ يُولَدُ إِلَّا يُولَدُ عَلَى الْفِطْرَةِ، فَأَبَوَاهُ يُهَوِّدَانِهِ أَوْ يُنَصِّرَانِهِ، أَوْ يُمَجِّسَانِهِ كَمَا تُنْتَجُ الْبَهِيمَةُ بَهِيمَةً جَمْعَاءَ هَلْ تُحِسُّونَ فِيهَا مِنْ جَدْعَاءَ". ثُمَّ يَقُولُ أَبُو هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: {فِطْرَةَ اللهِ الَّتِي فَطَرَ النَّاسَ عَلَيْهَا لَا تَبْدِيلَ لِخَلْقِ اللهِ ذَلِكَ الدِّينُ الْقَيِّمُ}. (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ശുദ്ധപ്രകൃതിയിൽ ജനിക്കാത്ത ഒരു കുഞ്ഞുമില്ല. പിന്നെ അവന്റെ മാതാപിതാക്കൾ അവനെ ജൂതനോ കൃസ്ത്യാനിയോ മജൂസിയോ ആക്കുന്നു. പരിപൂർണ്ണ അവയവങ്ങളുമായി ജനിക്കുന്ന മൃഗങ്ങളെ പോലെ (അവൻ ജനിക്കുന്നു); മൂക്കോ, ചെവിയോ നഷ്ടപ്പെട്ട രീതിയിൽ അവ ജനിക്കുന്നത് നിങ്ങൾ കണ്ടിട്ടുണ്ടോ?" എന്നിട്ട് അബൂഹുറൈറ(റ) ഈ അർത്ഥം വരുന്ന ആയത്ത് ഓതി: ''അല്ലാഹു മനുഷ്യരെ ഏതൊരു പ്രകൃയിലാണോ സൃഷ്ടിച്ചത് ആ പ്രകൃതിയത്രെ അത്. അല്ലാഹുവിന്റെ സൃഷ്ടിപ്പിന് യാതൊരു മാറ്റവും ഇല്ല. അതത്രെ വക്രതയില്ലാത്ത മതം.'' (റൂം: 30) (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 852, 852, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 347, 'عَنْ عَطَاءِ بْنِ أَبِي رَبَاحٍ – عَنْ عَمَّارٍ رَضِيَ اللهُ عَنْهُ – قَالَ: حَضَرَتْ جَنَازَةُ صَبِيٍّ وَامْرَأَةٍ، فَقُدِّمَ الصَّبِيُّ مِمَّا يَلِي الْقَوْمَ وَوُضِعَتِ الْمَرْأَةُ وَرَاءَهُ، فَصَلَّى عَلَيْهِمَا، وَفِي الْقَوْمِ أَبُو سَعِيدٍ الْخُدْرِيُّ وَابْنُ عَبَّاسٍ وَأَبُو قَتَادَةَ وَأَبُو هُرَيْرَةَ رَضِيَ اللهُ عَنْهُمْ، فَسَأَلْتُهُمْ عَنْ ذَلِكَ؟ فَقَالُوا: السُّنَّةُ. (ن)', 'അത്വാഉബ്നു അബീറബാഹ്(റ) അമ്മാറി(റ)ൽ നിന്ന്: അദ്ദേഹം പറഞ്ഞു: ഒരു കുട്ടിയുടേയും സ്ത്രീയുടേയും ജനാസ കൊണ്ടുവരപ്പെട്ടു. ജനങ്ങളോട് ഏറ്റവും അടുത്ത ഭാഗത്ത് കുട്ടിയെ വെച്ചു. അതിന്റെ പിന്നിൽ സ്ത്രീയേയും. അവർക്ക് രണ്ടാൾക്കും നിസ്കരിച്ചു. അവിടെയുണ്ടായിരുന്നവരുടെ കൂട്ടത്തിൽ അബുസഈദിൽ ഖുദ്രി(റ), ഇബ്നുഅബ്ബാസ്(റ), അബൂഖതാദ(റ) എന്നിവരുണ്ടായിരുന്നു. ഞാനവരോട് ഇതിനെ കുറിച്ച് ചോദിച്ചപ്പോൾ സുന്നത്താണ് എന്നായിരുന്നു അവരുടെ മറുപടി. (ന)', 'عَطَاءِ بْنِ أَبِي رَبَاحٍ – عَنْ عَمَّارٍ', 'അത്വാഉബ്നു അബീറബാഹ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 852, 852, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 348, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ صَلَّى عَلَى تِسْعِ جَنَائِزَ جَمِيعًا، فَجَعَلَ الرِّجَالَ يَلُونَ الْإِمَامَ وَالنِّسَاءَ يَلِينَ الْقِبْلَةَ، فَصَفَّهُنَّ صَفًّا وَاحِدًا، وَوُضِعَتْ جَنَازَةُ أُمِّ كُلْثُومٍ بِنْتِ عَلِيٍّ – امْرَأَةِ عُمَرَ بْنِ الْخَطَّابِ – وَابْنٍ لَهَا يُقَالُ لَهُ زَيْدٌ، وُضِعَا جَمِيعًا، وَالْإِمَامُ يَوْمَئِذٍ سَعِيدُ بْنُ الْعَاصِ، وَفِي النَّاسِ ابْنُ عُمَرَ وَأَبُو هُرَيْرَةَ وَأَبُو سَعِيدٍ وَأَبُو قَتَادَةَ، فَوُضِعَ الْغُلَامُ مِمَّا يَلِي الْإِمَامَ، فَقَالَ رَجُلٌ: فَأَنْكَرْتُ ذَلِكَ، فَنَظَرْتُ إِلَى ابْنِ عَبَّاسٍ وَأَبِي هُرَيْرَةَ وَأَبِي سَعِيدٍ وَأَبِي قَتَادَةَ فَقُلْتُ: مَا هَذَا؟ قَالُوا: هِيَ السُّنَّةُ. (ن)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം ഒമ്പത് ജനാസകൾക്ക് ഒന്നായി നിസ്കരിച്ചു. പുരുഷന്മാർ ഇമാമിനടുത്തും സ്ത്രീകൾ ഖിബ്‌ലക്ക് അടുത്തുമായിരുന്നു. ഉമറി(റ)ന്റെ പത്നിയും അലി(റ)യുടെ മകളുമായ ഉമ്മുകുൽസൂമി(റ)ന്റെ മയ്യിത്തും അവളുടെ മകൻ സൈദിന്റെ മയ്യിത്തും ഒന്നായി വച്ചു. സഈദുബ്നുൽ ആസായിരുന്നുഅന്ന് ഇമാം. ജനങ്ങളുടെ കൂട്ടത്തിൽ ഇബ്നുഉമർ(റ), അബൂഹുറൈറ(റ), അബൂസഈദ്(റ), അബൂഖതാദ(റ) എന്നിവരുണ്ടായിരുന്നു. കുട്ടിയെ ഇമാമിന്റെ അടുത്തു വെച്ചു. അപ്പോൾ ഒരാൾ പറഞ്ഞു: ഞാൻ അത് വെറുത്തു. ശേഷം ഞാൻ ഇബ്നുഅബ്ബാസ്(റ), അബൂഹുറൈറ(റ),അബൂസഈദ്(റ), അബൂഖതാദ(റ) എന്നിവരിലേക്ക് നോക്കികൊണ്ട് ചോദിച്ചു: ഇതെന്താണ്? അവർ പറഞ്ഞു: ഇതാണ് സുന്നത്ത്. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 852, 853, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 349, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى أُمِّ فُلَانٍ، مَاتَتْ فِي نِفَاسِهَا، فَقَامَ فِي وَسَطِهَا. (ن)', 'സമുറത്ബ്നു ജുൻദുബ്(റ): നബി(സ) ഒരാളുടെ മാതാവിന് വേണ്ടി ജനാസ നിസ്കരിച്ചു. പ്രസവസമയത്താണ് അവർ മരിച്ചത്. നബി(സ) അവളുടെ മധ്യഭാഗത്തിന് നേരെ നിന്ന് നിസ്കരിച്ചു. (ന)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറത്ബ്നു ജുൻദുബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 853, 853, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 350, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَبَّرَ عَلَى جَنَازَةٍ، فَرَفَعَ يَدَيْهِ فِي أَوَّلِ تَكْبِيرَةٍ، وَوَضَعَ الْيُمْنَى عَلَى الْيُسْرَى. (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) ഒരു ജനാസ നിസ്കാരത്തിന് തക്ബീർ ചൊല്ലി. ഒന്നാമത്തെ തക്ബീറിൽ കൈയുയർത്തുകയും വലതുകൈ ഇടതുകൈയ്യിന്മേൽ വെക്കുകയും ചെയ്തു. (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 853, 853, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 351, 'عَنْ عَبْدِ اللهِ بْنِ جَعْفَرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا جَاءَ نَعْيُ جَعْفَرٍ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اصْنَعُوا لِآلِ جَعْفَرٍ طَعَامًا، فَقَدْ أَتَاهُمْ مَا يَشْغَلُهُمْ: أَوْ: أَمْرٌ يَشْغَلُهُمْ". (د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നുജഅ്ഫർ(റ): ജഅ്ഫറി(റ)ന്റെ മരണവാർത്ത എത്തിയപ്പോൾ നബി(സ) പറഞ്ഞു: "ജഅ്ഫർ കുടുബത്തിന് നിങ്ങൾ ഭക്ഷണം ഒരുക്കുക. അവരെ അശ്രദ്ധരാക്കുന്ന അവസ്ഥ അവർക്കു വന്നിരിക്കുന്നു. (അല്ലെങ്കിൽ വ്യാപൃതരാക്കുന്ന കാര്യം)." (ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ جَعْفَرٍ', 'അബ്ദുല്ലാഹിബ്നുജഅ്ഫർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 853, 853, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 352, 'عَنْ أَسْمَاءَ بِنْتِ عُمَيْسٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا أُصِيبَ جَعْفَرٌ – رَضِيَ اللهُ عَنْهُ – رَجَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى أَهْلِهِ فَقَالَ: "إِنَّ آلَ جَعْفَرٍ قَدْ شُغِلُوا بِشَأْنِ مَيِّتِهِمْ، فَاصْنَعُوا لَهُمْ طَعَامًا". [ز: في سنده مجهولان] (جه)', 'അസ്മാബിൻത് ഉമൈസ്(റ): ജഅ്ഫർ(റ) വധിക്കപ്പെട്ടപ്പോൾ നബി(സ) അവിടുത്തെ കുടുംബത്തിലേക്ക് മടങ്ങി. എന്നിട്ട് പറഞ്ഞു: "നിശ്ചയം ജഅ്ഫർ കുടുംബം മയ്യിത്തിന്റെ കാര്യത്തിൽ വ്യാപൃതരായിരിക്കുന്നു. നിങ്ങൾ അവർക്ക് ഭക്ഷണമുണ്ടാക്കി കൊടുക്കുക." (ഇതിന്റെ പരമ്പരയിൽ രണ്ട് അജ്ഞാതരുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَسْمَاءَ بِنْتِ عُمَيْسٍ', 'അസ്മാബിൻത് ഉമൈസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده مجهولان', null, 853, 853, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 353, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللهِ الْبَجَلِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَرَى الاجْتِمَاعَ إِلَى أَهْلِ الْمَيِّتِ وَصَنْعَةَ الطَّعَامِ مِنَ النِّيَاحَةِ. (جه)', 'ജരീർ(റ): മയ്യിത്തിന്റെ വീട്ടിൽ ഒരുമിച്ച് കൂടി ഭക്ഷണമുണ്ടാക്കുന്നത് നിയാഹതിൽ (മയ്യിത്തിനുവേണ്ടി അട്ടഹസിച്ചു കരയൽ) പെട്ടതായിട്ടാണ് ഞങ്ങൾ കണ്ടിരുന്നത്. (ജ)', 'جَرِيرِ بْنِ عَبْدِ اللهِ الْبَجَلِيِّ', 'ജരീർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 853, 853, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 354, 'عَنْ قُرَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا جَلَسَ يَجْلِسُ إِلَيْهِ نَفَرٌ من أَصْحَابه، وَفِيهِمْ رَجُلٌ لَهُ ابْنٌ صَغِيرٌ، يَأْتِيهِ مِنْ خَلْفِ ظَهْرِهِ فَيُقْعِدُهُ بَيْنَ يَدَيْهِ، فَهَلَكَ، فَامْتَنَعَ الرَّجُلُ أَنْ يَحْضُرَ الْحَلْقَةَ لِذِكْرِ ابْنِهِ فَحَزِنَ عَلَيْهِ، فَفَقَدَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مَالِي لَا أَرَى فُلَانًا". قَالُوا: يَا رَسُولَ اللهِ، بُنَيُّهُ الَّذِي رَأَيْتَهُ هَلَكَ. فَلَقِيَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ عَنْ بُنَيِّهِ فَأَخْبَرَهُ: أَنَّهُ هَلَكَ، فَعَزَّاهُ عَلَيْهِ ثُمَّ قَالَ: "يَا فُلَانُ، أَيُّمَا كَانَ أَحَبَّ إِلَيْكَ: أَنْ تَمَتَّعَ بِهِ عُمُرَكَ؟ أَوْ: لَا تَأْتِي غَدًا إِلَى بَابٍ مِنْ أَبْوَابِ الْجَنَّةِ إِلَّا وَجَدْتَهُ قَدْ سَبَقَكَ إِلَيْهِ يَفْتَحُهُ لَكَ". قَالَ: يَا نَبِيَّ اللهِ، بَلْ يَسْبِقُنِي إِلَى بَابِ الْجَنَّةِ فَيَفْتَحُهَا لِي لَهُوَ أَحَبُّ إِلَيَّ. قَالَ: "فَذَاكَ لَكَ". (ن)', 'ഖുർറഃ(റ): നബി(സ) ഇരുന്നാൽ അവിടുത്തെ അടുത്ത് ഒരു സംഘം സ്വഹാബികളും ഇരിക്കുമായിരുന്നു. ചെറിയ ഒരു മകനുള്ള ഒരാളും അക്കൂട്ടത്തിലുണ്ടായിരുന്നു. അദ്ദേഹം അവനെ പിന്നിലൂടെ കൊണ്ടുവന്ന് തന്റെ മുന്നിലിരുത്തും. അങ്ങിനെ ഇരിക്കെ ആ കുട്ടി മരിച്ചു. തന്റെ മകനെ ഓർത്ത് അദ്ദേഹത്തിന് ഉത്ബോധന സദസ്സിലെത്താൻ കഴിഞ്ഞില്ല. അദ്ദേഹം ദുഃഖിച്ചു. അദ്ദേഹത്തെ കാണാതായപ്പോൾ നബി(സ) ചോദിച്ചു: "എന്ത് പറ്റി, ഒരാളെ കാണാനില്ലല്ലോ?" അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ താങ്കൾ കണ്ട, അദ്ദേഹത്തിന്റെ മകൻ മരിച്ചു പോയി. നബി(സ) അദ്ദേഹത്തെ കണ്ട് മകനെ കുറിച്ച് ചോദിച്ചു. അവൻ മരിച്ചു എന്ന് അയാൾ മറുപടി പറഞ്ഞു. അപ്പോൾ നബി(സ) ആശ്വസിപ്പിച്ചു. പിന്നെ പറഞ്ഞു: "ഏ മനുഷ്യാ, ഒന്നുകിൽ ആ കുട്ടിയെ കൊണ്ട് നിന്റെ ജീവിതം മുഴുവൻ ആസ്വദിക്കുക, അല്ലെങ്കിൽ നാളെ നീ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുമ്പോൾ അവൻ നിനക്ക് വാതിൽ തുറന്ന് തരിക. ഇതിലേതാണ് നീ കൂടുതൽ ഇഷ്ടപ്പെടുന്നത്." അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, അവൻ എന്റെ മുമ്പ് സ്വർഗ്ഗത്തിൽ കടന്ന് എനിക്ക് വാതിൽ തുറന്ന് തരുന്നതാണ് എനിക്കിഷ്ടം. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിനക്കതു മതി." (ന)', 'قُرَّةَ', 'ഖുർറഃ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 854, 854, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 355, 'عَنْ أَبِي بَرْزَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ عَزَّى ثَكْلَى كُسِيَ بُرْدًا فِي الْجَنَّةِ". (ت)', 'അബൂബർസ(റ): നബി(സ) പറഞ്ഞു: "കുട്ടി മരിച്ച ഒരു സ്ത്രീയെ ആരെങ്കിലും ആശ്വസിപ്പിച്ചാൽ അവൻ സ്വർഗ്ഗത്തിൽ ഒരു പുതപ്പ് പുതക്കപ്പെടും." (തു)', 'أَبِي بَرْزَةَ', 'അബൂബർസ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 854, 854, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 356, 'عَنْ عَبْد الله بْن عمرو بْن الْعَاصِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قبرْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – يَعْنِي مَيِّتًا – فَلَمَّا فَرَغْنَا انْصَرَفَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَانْصَرَفْنَا مَعَهُ، فَلَمَّا حَاذَى بَابَهُ وَقَفَ فَإِذَا نَحْنُ بِامْرَأَةٍ مُقْبِلَةٍ، قَالَ: أظُنُّهُ عرفها، فَلَمَّا ذَهَبَتْ إِذَا هِيَ فَاطِمَةُ رَضِيَ اللهُ عَنْهَا، فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا أخرجك يَا فاطمة من بيتك". فَقَالَتْ: أَتَيْتُ يَا رَسُولَ اللهِ أَهْلَ هَذَا الْبَيْتِ، فَرَحَّمْتُ إِلَيْهِمْ مَيِّتَهُمْ، أَوْ: عَزَّيْتُهُمْ بِهِ. فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَلَعَلَّكِ بَلَغْتِ مَعَهُمُ الْكُدَى". قَالَتْ: مَعَاذَ اللهِ وَقَدْ سمعتُكَ تذكُرُ فيها ما تذكُرُ. قَالَ: "لَوْ بَلَغْتِ مَعَهُمُ الْكُدَى". فَذَكَرَ تَشْدِيدًا في ذلك. (د,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ): ഞങ്ങൾ റസൂലി(സ)ന്റെ കൂടെ ഒരു മയ്യിത്ത് ഖബ്റടക്കി. ഖബ്റടക്കം കഴിഞ്ഞപ്പോൾ റസൂലും(സ) ഞങ്ങളും മടങ്ങി. നബി(സ) വാതിലിനടുത്തെത്തിയപ്പോൾ അവിടുന്ന് നിന്നു. അപ്പോൾ ഒരു സ്ത്രീ വരുന്നുണ്ട്. റിപ്പോർട്ടർ പറയുന്നു: നബി(സ) ആ സ്ത്രീയെ മനസ്സിലാക്കിയെന്ന് ഞാൻ വിചാരിക്കുന്നു, അവൾ പോയപ്പോൾ അത് ഫാത്വിമ(റ)യായിരുന്നെന്ന് മനസ്സിലായി. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ഫാത്വിമാ, വീട്ടിൽ നിന്ന് പുറപ്പെടാൻ കാരണം?" മഹതി പറഞ്ഞു: ദൈവ ദൂതരേ, ഞാൻ ഈ വീട്ടുകാരുടെ അടുത്ത് ചെന്ന് അവരെ ആശ്വസിപ്പിച്ചു. അപ്പോൾ റസൂൽ(സ) മഹതിയോട് പറഞ്ഞു: "അവരുടെ കൂടെ ഖബറിടത്തിലും നീ പോയിരിക്കും." മഹതി പറഞ്ഞു: അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുന്നു. താങ്കൾ തൽസംബന്ധമായി ചിലത് പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. നബി(സ) പറഞ്ഞു: "അവരോടൊപ്പം നീ ഖബ്റിടത്തിൽ പോയിരുന്നുവെങ്കിൽ..." നബി(സ) അതിന് താക്കീത് കൊടുത്തുകൊണ്ട് സംസാരിച്ചു." (ദ,ന)', 'عَبْد الله بْن عمرو بْن الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 854, 855, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 357, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اللَّحْدُ لَنَا، وَالشَّقُّ لِغَيْرِنَا". (د,ت,ن,جه)', 'ഉബ്നുഅബ്ബാസ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഖബർ തുരക്കുന്നത് നമുക്ക് വേണ്ടി. കീറിയുണ്ടാക്കുന്നത് മറ്റുള്ളവർക്കും." (ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഉബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 855, 855, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 358, 'عَنْ عَامِرِ بْنِ سَعْدٍ: أَنَّ سَعْدَ بْنَ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ فِي مَرَضِهِ الَّذِي هَلَكَ فِيهِ: الْحَدُوا لِي لَحْدًا، وَانْصِبُوا عَلَيَّ اللَّبِنَ نَصْبًا، كَمَا صُنِعَ بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,ن,جه)', 'ആമിറുബ്നു സഅ്ദ്(റ): സഅ്ദുബ്നു അബീവഖാസ് തന്റെ മരണകാരണമായ രോഗം ഉണ്ടായപ്പോൾ പറഞ്ഞു: നിങ്ങൾ എനിക്ക് വേണ്ടി ഒരു ലഹ്ദ്(ഖബ്ർ) ഉണ്ടാക്കുക. എനിക്ക് മുകളിൽ നിങ്ങൾ ഒരു കല്ല് നാട്ടുക, നബി(സ)ക്ക് ചെയ്തപോലെ. (മു,ന,ജ)', 'عَامِرِ بْنِ سَعْدٍ', 'ആമിറുബ്നു സഅ്ദ്(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 855, 855, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 359, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا تُوُفِّيَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ بِالْمَدِينَةِ رَجُلٌ يَلْحَدُ وَآخَرُ يَضْرَحُ، فَقَالُوا: نَسْتَخِيرُ رَبَّنَا وَنَبْعَثُ إِلَيْهِمَا، فَأَيُّهُمَا سُبِقَ تَرَكْنَاهُ. فَأُرْسِلَ إِلَيْهِمَا، فَسَبَقَ صَاحِبُ اللَّحْدِ، فَلَحَدُوا لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (جه)', 'അനസുബ്നു മാലിക്(റ): പ്രവാചകൻ(സ) വഫാതായപ്പോൾ ഖബർ തുരന്നുണ്ടാക്കുന്ന ഒരാളും കീറിയുണ്ടാക്കുന്ന മറ്റൊരാളും മദീനയിൽ ഉണ്ടായിരുന്നു നമുക്ക് റബ്ബിനോട് ഏതാണ് നല്ലതെന്ന് ആരായാം. രണ്ട് പേരെയും വരുത്താം എന്ന് അവർ പറഞ്ഞു. അവരിൽ ആരാണ് ആദ്യം വരുന്നത് അവനെ തീരുമാനിക്കാം, അങ്ങനെ രണ്ടുപേരുടെയും അടുക്കൽ ആളെ അയച്ചു. ആദ്യം വന്നത് തുരക്കുന്ന ആളായിരുന്നു. അങ്ങനെ പ്രവാചക(സ)ന്റെ ഖബർ തുരന്നുണ്ടാക്കി. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 855, 855, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 360, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا مَاتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اخْتَلَفُوا فِي اللَّحْدِ وَالشَّقِّ، حَتَّى تَكَلَّمُوا فِي ذَلِكَ وَارْتَفَعَتْ أَصْوَاتُهُمْ. فَقَالَ عُمَرُ: لَا تَصْخَبُوا عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَيًّا وَلَا مَيِّتًا. أَوْ كَلِمَةً نَحْوَهَا، فَأَرْسَلُوا إِلَى الشَّقَّاقِ وَاللَّاحِدِ جَمِيعًا فَجَاءَ اللَّاحِدُ، فَلَحَدَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ دُفِنَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (جه)', 'ആയിശ(റ): പ്രവാചകൻ(സ) വഫാതായപ്പോൾ ഖബർ കീറിയാണോ തുരന്നാണോ ഉണ്ടാക്കേണ്ടത് എന്നതിൽ അവർ ഭിന്നാഭിപ്രായക്കാരായി. ഈ വിഷയത്തിൽ സംസാരിച്ച് അവരുടെ ശബ്ദം ഉയർന്നപ്പോൾ, പ്രവാചകൻ(സ)യുടെ അരികെ വെച്ച് ജീവിച്ചിരിക്കുമ്പോഴും മരിച്ചിരിക്കുമ്പോഴും നിങ്ങൾ ഒച്ചവെക്കരുത് എന്ന് ഉമർ(റ) പറഞ്ഞു. അങ്ങനെ അവർ കീറി ഖബർ ഉണ്ടാക്കുന്നവന്റെയും തുരന്നുണ്ടാക്കുന്നവന്റെയും അടുക്കലേക്ക് ആളെ അയച്ചു. തുരന്നുണ്ടാക്കുന്നവർ വന്നു. അങ്ങനെ തിരുമേനി(സ)ക്ക് വേണ്ടി ഖബർ തുരന്നുണ്ടാക്കുകയും പിന്നീട് മറവ് ചെയ്യുകയും ചെയ്തു. (ജ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 855, 855, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 361, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أُدْخِلَ الْمَيِّتُ الْقَبْرَ قَالَ: "بِسْمِ اللهِ، وَعَلَى مِلَّةِ رَسُولِ اللهِ". وَفِي رِوَايَةٍ: إِذَا وُضِعَ الْمَيِّتُ فِي لَحْدِهِ قَالَ: "بِسْمِ اللهِ، وَعَلَى سُنَّةِ رَسُولِ اللهِ". وَفِي رِوَايَةٍ: "بِسْمِ اللهِ وَفِي سَبِيلِ اللهِ، وَعَلَى مِلَّةِ رَسُولِ اللهِ". (د,ت,جه)', 'ഇബ്നുഉമർ(റ): മയ്യിത്ത് ഖബ്റിൽ പ്രവേശിപ്പിക്കപ്പെട്ടാൽ നബി(സ) ഇങ്ങനെ പറഞ്ഞിരുന്നു: "അല്ലാഹുവിന്റെ നാമത്തിൽ അവന്റെ പ്രവാചകന്റെ മാർഗ്ഗത്തിൽ." മറ്റൊരു റിപ്പോർട്ടിൽ: മയ്യിത്ത് ഖബറിൽ വെക്കപ്പെട്ടാൽ തിരുമേനി(സ) ഇങ്ങനെ പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവിന്റെ നാമത്തിൽ, അവന്റെ റസൂലിന്റെ സുന്നത്ത്പ്രകാരം." മറ്റൊരു റിപ്പോർട്ടിൽ: "അല്ലാഹുവിന്റെ നാമത്തിൽ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ, അല്ലാഹുവിന്റെ ദൂതന്റെ മാർഗ്ഗത്തിൽ." (ദ,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 856, 856, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=361), 1, 'وَفِي رِوَايَةٍ: إِذَا وُضِعَ الْمَيِّتُ فِي لَحْدِهِ قَالَ: "بِسْمِ اللهِ، وَعَلَى سُنَّةِ رَسُولِ اللهِ".', 'മറ്റൊരു നിവേദനിൽ: മയ്യിത്ത് ഖബറിൽ വെക്കപ്പെട്ടാൽ തിരുമേനി(സ) ഇങ്ങനെ പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവിന്റെ നാമത്തിൽ, അവന്റെ റസൂലിന്റെ സുന്നത്ത്പ്രകാരം."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=361), 2, 'وَفِي رِوَايَةٍ: "بِسْمِ اللهِ وَفِي سَبِيلِ اللهِ، وَعَلَى مِلَّةِ رَسُولِ اللهِ". (د,ت,جه)', 'മറ്റൊരു നിവേദനിൽ: "അല്ലാഹുവിന്റെ നാമത്തിൽ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ, അല്ലാഹുവിന്റെ ദൂതന്റെ മാർഗ്ഗത്തിൽ." (ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 362, 'عَنْ أَبِي رَافِعٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَلَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَعْدًا، وَرَشَّ عَلَى قَبْرِهِ مَاءً. [ز: في سنده ضعيفان] (جه)', 'അബുറാഫിഅ്(റ): നബി(സ) സഅ്ദിനെ ഖബ്റടക്കി. അദ്ദേഹത്തിന്റെ ഖബറിനു മുകളിൽ വെള്ളം കുടഞ്ഞു. (സനദിൽ ദുർബ്ബലരുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَبِي رَافِعٍ', 'അബുറാഫിഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيفان', 'സനദിൽ ദുർബ്ബലരുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 856, 856, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 363, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أُخِذَ مِنْ قِبَلِ الْقِبْلَةِ، وَاسْتُقْبِلَ اسْتِقْبَالًا، وَاسْتُلَّ إِسْتِلَالًا. [ز: في إسناده ضعيف] (جه)', 'അബൂസഈദ്(റ): നബി(സ) ഖിബ്ലയുടെ ഭാഗത്ത് വെക്കപ്പെട്ടു. ഖിബ്ലക്ക് മുന്തിക്കപ്പെട്ടു. ഖബറു മൂടപ്പെട്ടു. (സനദിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'സനദിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 856, 856, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 364, 'عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ قَالَ: حَضَرْتُ ابْنَ عُمَرَ – رَضِيَ اللهُ عَنْهُمَا – فِي جِنَازَةٍ، فَلَمَّا وَضَعَهَا فِي اللَّحْدِ قَالَ: "بِسْمِ اللهِ، وَفِي سَبِيلِ اللهِ، وَعَلَى مِلَّةِ رَسُولِ اللهِ". فَلَمَّا أُخِذَ فِي تَسْوِيَةِ اللَّبِنِ عَلَى اللَّحْدِ قَالَ: "اللَّهُمَّ أَجِرْهَا مِنَ الشَّيْطَانِ وَمِنْ عَذَابِ الْقَبْرِ. اللَّهُمَّ جَافِ الْأَرْضَ عَنْ جَنْبَيْهَا، وَصَعِّدْ رُوحَهَا، وَلَقِّهَا مِنْكَ رِضْوَانًا". قُلْتُ: يَا ابْنَ عُمَرَ، أَشَيْءٌ سَمِعْتَهُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، أَمْ قُلْتَهُ بِرَأْيِكَ؟ قَالَ: إِنِّي إِذًا لَقَادِرٌ عَلَى الْقَوْلِ، بَلْ شَيْءٌ سَمِعْتُهُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. [ز: في إسناده ضعيف] (جه)', 'സഈദുബ്നുൽ മുസയ്യബ്(റ): ഒരു ജനാസയുടെ കാര്യത്തിൽ ഞാൻ ഇബ്നുഉമറി(റ)ന്റെ അടുക്കൽ വന്നു. അദ്ദേഹം അയാളെ ലഹ്ദിൽ വെച്ചപ്പോൾ പറഞ്ഞു: "അല്ലാഹുവിന്റെ നാമത്തിൽ അവന്റെ റസൂലി(സ)ന്റെ മാർഗ്ഗത്തിൽ." ലഹ്ദിന്റെ മേൽ ഇഷ്ടിക ശരിയാക്കുവാൻ തുടങ്ങിയപ്പോൾ അദ്ദേഹം പറഞ്ഞു: "അല്ലാഹുവേ നരകശിക്ഷയിൽ നിന്നും പിശാചിൽ നിന്നും നീ ഇതിനെ രക്ഷിക്കേണമേ. അല്ലാഹുവേ മണ്ണിനെ നീ ഇതിന്റെ രണ്ട് വശങ്ങളിൽ നിന്നും അകറ്റേണമേ. നീ അതിന്റെ റൂഹിനെ അകറ്റി നിന്റെ തൃപ്തി അതിന് നൽകേണമേ." ഞാൻ ചോദിച്ചു: ഇബ്നുഉമറേ! ഇത് താങ്കൾ റസൂലിൽ നിന്നും കേട്ടതാണോ, അല്ലെങ്കിൽ താങ്കളുടെ അഭിപ്രായപ്രകാരം പറഞ്ഞതാണോ? അദ്ദേഹം പറഞ്ഞു: ഞാൻ പറയാൻ കഴിയുന്നവനാണ്. എന്നാൽ ഞാൻ നബി(സ)യിൽ നിന്നും കേട്ടതാണിത്. (ഇതിന്റെ സനദിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ). (ജ)', 'سَعِيدِ بْنِ الْمُسَيَّبِ قَالَ', 'സഈദുബ്നുൽ മുസയ്യബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ സനദിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ', 856, 856, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 365, 'عَنْ عَلِيِّ بْنِ حُسَيْنِ بْنِ عَلِيٍّ – رَضِيَ اللهُ عَنْهُمَا – قَالَ: الَّذِي أَلْحَدَ قَبْرَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَبُو طَلْحَةَ، وَالَّذِي أَلْقَى الْقَطِيفَةَ تَحْتَهُ شُقْرَانُ مَوْلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. وَفِي رِوَايَةٍ: قَالَ شُقْرَانُ: أَنَا – وَاللهِ – طَرَحْتُ الْقَطِيفَةَ تَحْتَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْقَبْرِ. حَسَنٌ. (ت)', 'അലിയ്യുബ്നുൽ ഹുസൈൻ(റ): റസൂലി(സ)നെ ലഹ്ദിൽ വെച്ചത് അബൂത്വൽഹ(റ) ആയിരുന്നു. തിരുമേനി(സ)യുടെ കീഴെ പട്ടുകൊണ്ടുള്ള വസ്ത്രം വെച്ചത് റസൂലി(സ)ന്റെ അടിമയായിരുന്ന ശുഖ്റാനാ(റ)യിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: ശുഖ്റാൻ(റ) പറഞ്ഞു: അല്ലാഹുവാണേ, ഞാനാണ് ഖബ്റിൽ പ്രവാചക(സ)ന്റെ ചുവട്ടിൽ പട്ടുവസ്ത്രം വെച്ചത്. (ഹദീസ് ഹസനാണ്) (തു)', 'عَلِيِّ بْنِ حُسَيْنِ بْنِ عَلِيٍّ –', 'അലിയ്യുബ്നുൽ ഹുസൈൻ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 857, 857, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=365), 1, 'وَفِي رِوَايَةٍ: قَالَ شُقْرَانُ: أَنَا – وَاللهِ – طَرَحْتُ الْقَطِيفَةَ تَحْتَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْقَبْرِ. حَسَنٌ. (ت)', 'മറ്റൊരു നിവേദനിൽ: ശുഖ്റാൻ(റ) പറഞ്ഞു: അല്ലാഹുവാണേ, ഞാനാണ് ഖബ്റിൽ പ്രവാചക(സ)ന്റെ ചുവട്ടിൽ പട്ടുവസ്ത്രം വെച്ചത്. (ഹദീസ് ഹസനാണ്) (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 366, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: جُعِلَ فِي قَبْرِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَطِيفَةٌ حَمْرَاءُ. حَسَنٌ صَحِيحٌ. (م,د,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യുടെ ഖബറിൽ ചുവന്ന പട്ടുവസ്ത്രം വെച്ചു. ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (മു,ദ,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 857, 857, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 367, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: فَقَدْتُهُ – تَعْنِي النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – فَإِذَا هُوَ بِالْبَقِيعِ، فَقَالَ: "السَّلَامُ عَلَيْكُمْ، دَارَ قَوْمٍ مُؤْمِنِينَ. أَنْتُمْ لَنَا فَرَطٌ، وَإِنَّا بِكُمْ لَاحِقُونَ. اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُمْ، وَلَا تَفْتِنَّا بَعْدَهُمْ". (جه)', 'ആഇശ(റ): റസൂലി(സ)നെ ഒരിക്കൽ കാണാതായി. അവിടുന്ന് അപ്പോൾ ബഖീഇലായിരുന്നു. അവിടുന്ന് പറഞ്ഞു: "മുഅ്മിനുകളുടെ ഭവനമേ, അല്ലാഹുവിന്റെ രക്ഷ നിങ്ങൾക്കുണ്ടാകട്ടെ. നിങ്ങൾ ഞങ്ങൾക്ക് മുമ്പേ പോയവരാണ്. ഞങ്ങൾ നിങ്ങളോട് ചേരുന്നവരുമാണ്. അല്ലാഹുവേ അവരുടെ പ്രതിഫലം ഞങ്ങൾക്ക് നീ തടയരുതേ. അവർക്ക് ശേഷം ഞങ്ങളെ പരീക്ഷിക്കല്ലേ." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 857, 857, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 368, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ إِلَى الْمَقْبَرَةِ فَقَالَ: "السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ، وَإِنَّا إِنْ شَاءَ اللهُ بِكُمْ لَاحِقُونَ". (م,د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) ഒരു ഖബ്റിടത്തിലേക്ക് പുറപ്പെട്ടു. അവിടുന്ന് പറഞ്ഞു: "മുഅ്മിനുകളുടെ ഭവനമേ, അല്ലാഹുവിന്റെ രക്ഷ നിങ്ങളുടെ മേലുണ്ടാകട്ടെ. നിശ്ചയം, അല്ലാഹു ഉദ്ദേശിക്കുമ്പോൾ നിങ്ങളെ ഞങ്ങൾ കണ്ടുമുട്ടും." (മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 857, 857, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 369, 'عَنْ بَشِيرٍ رَضِيَ اللهُ عَنْهُ، مَوْلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: وَكَانَ اسْمُهُ فِي الْجَاهِلِيَّةِ: زَحْمُ بْنُ مَعْبَدٍ، فَهَاجَرَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "مَا اسْمُكَ". قَالَ: زَحْمٌ، قَالَ: "بَلْ أَنْتَ بَشِيرٌ". قَالَ: بَيْنَمَا أَنَا أُمَاشِي رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِقُبُورِ الْمُشْرِكِينَ، فَقَالَ: "لَقَدْ سَبَقَ هَؤُلَاءِ خَيْرًا كَثِيرًا". ثَلَاثًا، ثُمَّ مَرَّ بِقُبُورِ الْمُسْلِمِينَ فَقَالَ: "لَقَدْ أَدْرَكَ هَؤُلَاءِ خَيْرًا كَثِيرًا". وَحَانَتْ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَظْرَةً فَإِذَا رَجُلٌ يَمْشِي فِي الْقُبُورِ عَلَيْهِ نَعْلَانِ، فَقَالَ: "يَا صَاحِبَ السِّبْتِيَّتَيْنِ، وَيْحَكَ! أَلْقِ سِبْتِيَّتَيْكَ". فَنَظَرَ الرَّجُلُ، فَلَمَّا عَرَفَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَلَعَهُمَا فَرَمَى بِهِمَا. (د,ن,جه)', 'ബശീർ(റ): ജാഹിലിയ്യ കാലത്ത് അദ്ദേഹത്തിന്റെ പേര് സഹ്മുബ്നുമഅ്ബദ് എന്നായിരുന്നു. അദ്ദേഹം റസൂലി(സ)ന്റെ അടുത്തേക്ക് ഹിജ്റ ചെയ്തു. പ്രവാചകൻ(സ) ചോദിച്ചു: "എന്താണ് താങ്കളുടെ പേര്?" അദ്ദേഹം പറഞ്ഞു: സഹ്മ്. നബി(സ) പറഞ്ഞു: "എന്നാൽ നീ ബശീറാണ്." ഞാൻ നബി(സ)യുടെ കൂടെ നടക്കുമ്പോൾ മുശ്രിക്കുകളുടെ ഖബ്റുകളുടെ അടുത്തുകൂടെ നടന്നു. "ഇക്കൂട്ടർ ഒരുപാട് നന്മകളെ മുൻകടന്നിരിക്കുന്നു" എന്ന് പ്രവാചകൻ(സ) മൂന്ന് പ്രാവശ്യം പറഞ്ഞു. പിന്നെ പ്രവാചകൻ(സ) മുസ്ലിംകളുടെ ഖബറിനടുത്തുകൂടെ നടന്നു. പ്രവാചകൻ(സ) പറഞ്ഞു: "ഇക്കൂട്ടർ ഒരുപാട് നന്മ ചെയ്തിരിക്കുന്നു." നബി(സ) ഒന്ന് നോക്കി. അപ്പോൾ ഒരാൾ ഖബ്റുകളിലൂടെ ചെരുപ്പിട്ട് നടന്നിരുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "രണ്ട് ചെരുപ്പുകളുടെ ഉടമസ്ഥാ! നാശം! നിന്റെ ചെരുപ്പ് നീ ഊരുക." ആ മനുഷ്യൻ നോക്കി. റസൂലി(സ)നെ മനസ്സിലായപ്പോൾ അദ്ദേഹം അത് രണ്ടും ഊരി എറിഞ്ഞു. (ദ,ന,ജ)', 'بَشِيرٍ', 'ബശീർ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 857, 858, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 370, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ قَالَ: "إِنَّ الْعَبْدَ إِذَا وُضِعَ فِي قَبْرِهِ وَتَوَلَّى عَنْهُ أَصْحَابُهُ: إِنَّهُ لَيَسْمَعُ قَرْعَ نِعَالِهِمْ". (ق,د,ن)', 'നബി(സ)ൽ നിന്ന് അനസ്(റ): നബി(സ) പറഞ്ഞു: "അടിമ ഖബ്റിൽ വെക്കപ്പെട്ടശേഷം ആളുകൾ അവനെ വിട്ടുപിരിയുമ്പോൾ അവരുടെ ചെരുപ്പടിശബ്ദം അവൻ കേൾക്കും." (ബു,മു,ദ,ന)', 'أَنَسٍ', 'നബി(സ)ൽ നിന്ന് അനസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 858, 858, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 371, 'عَنْ بَشِيرِ بْنِ الْخَصَاصِيَةِ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا أَنَا أَمْشِي مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا ابْنَ الْخَصَاصِيَةِ، مَا تَنْقِمُ عَلَى اللهِ؟ أَصْبَحْتَ تُمَاشِي رَسُولَ اللهِ". فَقُلْتُ: يَا رَسُولَ اللهِ، مَا أَنْقِمُ عَلَى اللهِ شَيْئًا، كُلُّ خَيْرٍ قَدْ آتَانِيهِ اللهُ. فَمَرَّ عَلَى مَقَابِرِ الْمُسْلِمِينَ فَقَالَ: "أَدْرَكَ هَؤُلَاءِ خَيْرًا كَثِيرًا". ثُمَّ مَرَّ عَلَى مَقَابِرِ الْمُشْرِكِينَ فَقَالَ: "سَبَقَ هَؤُلَاءِ خَيْرًا كَثِيرًا". قَالَ: فَالْتَفَتَ فَرَأَى رَجُلًا يَمْشِي بَيْنَ الْمَقَابِرِ فِي نَعْلَيْهِ، فَقَالَ: "يَا صَاحِبَ السِّبْتِيَّتَيْنِ، أَلْقِهِمَا". (د,ن,جه)', 'ബശീറുബ്നുൽ ഖസ്വാസിയ്യ(റ): ഞാൻ നബി(സ)യുടെ കൂടെ നടക്കുമ്പോൾ അവിടുന്ന് എന്നോടു പറഞ്ഞു: "ഇബ്നുൽ ഖസ്വാസിയ്യത്തേ! എന്താണ് നീ അല്ലാഹുവിനോട് കോപിക്കുന്നത്? അല്ലാഹുവിന്റെ റസൂലിന്റെ കൂടെയാണ് നീ പ്രഭാത സഞ്ചാരം നടത്തുന്നത്." ഞാൻ പറഞ്ഞു: റസൂലേ, ഞാൻ അല്ലാഹുവിനോട് കോപിച്ചിട്ടില്ല. എല്ലാ നന്മയും അല്ലാഹു നൽകിയതാണ്. അങ്ങനെ അവിടുന്ന് മുസ്ലിംകളുടെ ഖബറിടത്തിലൂടെ നടന്നു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അവർ ഒരുപാട് നന്മ ചെയ്തിട്ടുണ്ട്." പിന്നെ അവിടുന്ന് മുശ്രിക്കുകളുടെ ഖബറിനടുത്തുകൂടെ നടന്നു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ഇക്കൂട്ടർ ഒരുപാട് നന്മകളെ മുൻകടന്നിരിക്കുന്നു." അവിടുന്ന് തിരിഞ്ഞുനോക്കി. അപ്പോൾ ഒരാൾ ചെരുപ്പ് ധരിച്ചു ഖബറിടങ്ങൾക്കിടയിലൂടെ നടക്കുകയായിരുന്നു. പ്രവാചകൻ(സ) അയാളെ വിളിച്ചു പറഞ്ഞു: "ഇരു ചെരുപ്പുകൾ ധരിച്ചവനേ, അവ രണ്ടും ഊരിക്കളയുക." (ദ,ന,ജ)', 'بَشِيرِ بْنِ الْخَصَاصِيَةِ', 'ബശീറുബ്നുൽ ഖസ്വാസിയ്യ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 858, 858, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 372, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ امْرَأَةً سَوْدَاءَ كَانَتْ تَقُمُّ الْمَسْجِدَ – أَوْ شَابًّا – فَفَقَدَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَ عَنْهَا – أَوْ عَنْهُ – فَقَالُوا: مَاتَ، [ مَاتَتْ] قَالَ: "أَفَلَا كُنْتُمْ آذَنْتُمُونِي". قَالَ: فَكَأَنَّهُمْ صَغَّرُوا أَمْرَهَا أَوْ أَمْرَهُ، فَقَالَ: "دُلُّونِي عَلَى [قَبْرِهَا]قَبْرِهِ". فَدَلُّوهُ فَصَلَّى عَلَيْهَا، ثُمَّ قَالَ: "إِنَّ هَذِهِ الْقُبُورَ مَمْلُوءَةٌ ظُلْمَةً عَلَى أَهْلِهَا، وَإِنَّ اللهَ عَزَّ وَجَلَّ يُنَوِّرُهَا لَهُمْ بِصَلَاتِي عَلَيْهِمْ". (ق,د,جه)', 'അബൂഹുറൈറ(റ): പള്ളിയടിച്ചുവാരുന്ന ഒരു കറുത്ത സ്ത്രീയെ/യുവാവിനെ നബി(സ) കുറച്ചുനാൾ കാണാതായി. നബി(സ) അവളെ/അവനെ ചോദിച്ചു. അവർ പറഞ്ഞു: അവൾ/അവൻ മരിച്ചുപോയി. നബി(സ) ചോദിച്ചു. "നിങ്ങൾക്ക് എന്നെ വിവരമറിയിച്ചുകൂടായിരുന്നോ?" അവർ അവന്റെ/അവളുടെ കാര്യം ചെറുതായികണ്ടതുപോലെ. അവന്റെ/അവളുടെ ഖബർ കാണിച്ചുകൊടുക്കുവാൻ നബി(സ) ആവശ്യപ്പെട്ടു. സ്വഹാബികൾ കാണിച്ചു കൊടുത്തു. നബി(സ) അവിടെ വെച്ച് നിസ്കരിച്ചു. പിന്നെ നബി(സ) പറഞ്ഞു: "ഈ ഖബറുകൾ അതിന്റെയാളുകൾക്ക് ഇരുട്ട് നിറഞ്ഞതായിരുന്നു. എന്റെ നിസ്കാരം കൊണ്ട് അല്ലാഹു അത് പ്രകാശപൂരിതമാക്കി." (ബു,മു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], 'قَبْرِهَا', null, 858, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 373, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُمْ خَرَجُوا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ فَرَأَى قَبْرًا جَدِيدًا، فَقَالَ: "مَا هَذَا". قَالُوا: هَذِهِ فُلَانَةُ، مَوْلَاةُ بَنِي فُلَانٍ – فَعَرَفَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – مَاتَتْ ظُهْرًا وَأَنْتَ نَائِمٌ قَائِلٌ، فَلَمْ نُحِبَّ أَنْ نُوقِظَكَ بِهَا. فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَصَفَّ النَّاسَ خَلْفَهُ وَكَبَّرَ عَلَيْهَا أَرْبَعًا، ثُمَّ قَالَ: "لَا يَمُوتُ فِيكُمْ مَيِّتٌ مَا دُمْتُ بَيْنَ أَظْهُرِكُمْ إِلَّا آذَنْتُمُونِي بِهِ، فَإِنَّ صَلَاتِي لَهُ رَحْمَةٌ". (ن)', 'സൈദുബ്ന് സാബിത്(റ): ഒരുനാൾ സഹാബികൾ നബി(സ)യുടെ കൂടെ പുറപ്പെട്ടു. അപ്പോൾ ഒരു പുതിയ ഖബർ കണ്ടു. നബി(സ) ചോദിച്ചു: "ഇതാരുടേതാണ്?" അവർ പറഞ്ഞു: ഇത് ഇന്നവളാണ്, ഇന്ന ഗോത്രത്തിലെ അടിമസ്ത്രീയാണ്. - നബി(സ)ക്ക് ആളെ മനസ്സിലായി - അവൾ മരിച്ചത് ഉച്ചക്കാണ്. താങ്കൾ ഉറങ്ങുകയായിരുന്നു. താങ്കളെ ഉണർത്താൻ ഞങ്ങൾ ഇഷ്ടപ്പെട്ടില്ല. അപ്പോൾ നബി(സ) അവൾക്ക് വേണ്ടി നാല് തക്ബീറോടെ നിസ്കരിച്ചു. പിന്നിൽ സ്വഹാബികൾ അണിയായി നിന്ന് നിസ്കരിച്ചു. പിന്നെ നബി(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങളിൽ ഉണ്ടായിരിക്കെ നിങ്ങളിൽ ആര് മരിച്ചാലും എന്നെ അറിയിക്കണം. കാരണം എന്റെ നിസ്കാരം അയാൾക്ക് അനുഗ്രഹമാണ്." (ന)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്ന് സാബിത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 859, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 374, 'عَنِ الشَّعْبِيِّ قَالَ: أَخْبَرَنِي مَنْ مَرَّ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى قَبْرٍ مُنْتَبِذٍ، فَأَمَّهُمْ وَصَفَّ خَلْفَهُ. قِيلَ: مَنْ هُوَ يَا أَبَا عَمْرٍو؟ قَالَ: ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا. وَفِي رِوَايَةٍ: قَالَ: أَخْبَرَنِي مَنْ رَأَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِقَبْرٍ مُنْتَبِذٍ فَصَلَّى عَلَيْهِ، وَصَفَّ أَصْحَابَهُ خَلْفَهُ. قِيلَ: مَنْ حَدَّثَكَ؟ قَالَ: ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا. (ق,ت,ن)', 'ശഅ്ബിയ്യ്(റ): ഒരു മറമാടപ്പെട്ട ഖബ്റിന്റെ അടുത്ത് കൂടെ നബി(സ)യോടെപ്പം നടന്ന ഒരാൾ തിരുമേനി(സ) അവർക്കിമായി നിസ്കരിച്ചതതായി എനിക്ക് പറഞ്ഞു തന്നു. അപ്പോൾ ചോദിക്കപ്പെട്ടു: അതാരായിരുന്നു അബൂഅംറേ? അദ്ദേഹം പറഞ്ഞു: അത് ഇബ്നുഅബ്ബാസ്(റ) ആയിരുന്നു. മറ്റൊരു റിപ്പോർട്ട്: മറവ് ചെയ്യപ്പെട്ട ഒരു ഖബ്റിനടുത്തുകൂടെ നബി(സ) നടക്കുകയും ആ മയ്യിത്തിന് വേണ്ടി നിസ്കരിക്കുകയും പിന്നിൽ സ്വഹാബികൾ അണിയായി നിസ്കരിക്കുകയും ചെയ്യുന്നത് കണ്ട ഒരാൾ എന്നോട് പറഞ്ഞു. ആരോ ചോദിച്ചു: അബൂഅംറേ ആരാണ് താങ്കളോട് ഇത് പറഞ്ഞത്. അദ്ദേഹം പറഞ്ഞു: ഇബ്നുഅബ്ബാസ്(റ) ആണ്. (ബു,മു,തു,ന)', 'الشَّعْبِيِّ قَالَ', 'ശഅ്ബിയ്യ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 859, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=374), 1, 'وَفِي رِوَايَةٍ: قَالَ: أَخْبَرَنِي مَنْ رَأَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِقَبْرٍ مُنْتَبِذٍ فَصَلَّى عَلَيْهِ، وَصَفَّ أَصْحَابَهُ خَلْفَهُ. قِيلَ: مَنْ حَدَّثَكَ؟ قَالَ: ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا. (ق,ت,ن)', 'മറ്റൊരു നിവേദന്: മറവ് ചെയ്യപ്പെട്ട ഒരു ഖബ്റിനടുത്തുകൂടെ നബി(സ) നടക്കുകയും ആ മയ്യിത്തിന് വേണ്ടി നിസ്കരിക്കുകയും പിന്നിൽ സ്വഹാബികൾ അണിയായി നിസ്കരിക്കുകയും ചെയ്യുന്നത് കണ്ട ഒരാൾ എന്നോട് പറഞ്ഞു. ആരോ ചോദിച്ചു: അബൂഅംറേ ആരാണ് താങ്കളോട് ഇത് പറഞ്ഞത്. അദ്ദേഹം പറഞ്ഞു: ഇബ്നുഅബ്ബാസ്(റ) ആണ്. (ബു,മു,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 375, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى قَبْرِ امْرَأَةٍ بَعْدَ مَا دُفِنَتْ. (ن)', 'ജാബിർ(റ): നബി(സ) ഒരു സ്ത്രീക്ക് വേണ്ടി അവൾ മറമാടപ്പെട്ട ശേഷം ഖബറിടത്തിൽ വെച്ച് ജനാസ നിസ്കരിച്ചു. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 859, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 376, 'عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ: أَنَّ أُمَّ سَعْدٍ – رَضِيَ اللهُ عَنْهَا – مَاتَتْ وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غَائِبٌ، فَلَمَّا قَدِمَ صَلَّى عَلَيْهَا، وَقَدْ مَضَى لِذَلِكَ شَهْرٌ. (ت)', 'സഈദുബ്നുൽ മുസയ്യബ്(റ): നബി(സ) സ്ഥലത്തില്ലാത്ത സമയത്ത് ഉമ്മുസഅ്ദ്(റ) മരണപ്പെട്ടു. നബി(സ) വന്നപ്പോൾ അവൾക്ക് വേണ്ടി നിസ്കരിച്ചു. ഒരു മാസത്തിന് ശേഷമായിരുന്നു അത്. (തു)', 'سَعِيدِ بْنِ الْمُسَيَّبِ', 'സഈദുബ്നുൽ മുസയ്യബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 859, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 377, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ امْرَأَةً سَوْدَاءَ كَانَتْ تَقُمُّ الْمَسْجِدَ، فَفَقَدَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلَ عَنْهَا بَعْدَ أَيَّامٍ، فَقِيلَ لَهُ: إِنَّهَا مَاتَتْ. قَالَ: "فَهَلَّا آذَنْتُمُونِي". فَأَتَى قَبْرَهَا فَصَلَّى عَلَيْهَا. (ق,د,جه)', 'അബൂഹുറൈറ(റ): പള്ളിയടിച്ചുവാരുന്ന ഒരു കറുത്ത സ്ത്രീയെ നബി(സ) കുറച്ചുനാൾ കാണാതായി. കുറെ ദിവസങ്ങൾക്ക് ശേഷം അവളെപ്പറ്റി നബി(സ) ചോദിച്ചു. അവൾ മരണപ്പെട്ടു എന്ന മറുപടി ലഭിച്ചു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "എന്നിട്ടെന്താണ് നിങ്ങൾ അതെന്നോട് പറയാതിരുന്നത്?" നബി(സ) അവളുടെ ഖബറിനടുത്ത് വന്ന് അവൾക്ക് വേണ്ടി നിസ്കരിച്ചു. (ബു,മു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 860, 860, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 378, 'عَنْ يَزِيدَ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا وَرَدَ الْبَقِيعَ فَإِذَا هُوَ بِقَبْرٍ جَدِيدٍ، فَسَأَلَ عَنْهُ قَالُوا: فُلَانَةُ. قَالَ: فَعَرَفَهَا، وَقَالَ: "أَلَا آذَنْتُمُونِي بِهَا". قَالُوا: كُنْتَ قَائِلًا صَائِمًا، فَكَرِهْنَا أَنْ نُؤْذِيَكَ. قَالَ: "فَلَا تَفْعَلُوا، لَا أَعْرِفَنَّ مَا مَاتَ مِنْكُمْ مَيِّتٌ – مَا كُنْتُ بَيْنَ أَظْهُرِكُمْ – إِلَّا آذَنْتُمُونِي بِهِ، فَإِنَّ صَلَاتِي عَلَيْهِ لَهُ رَحْمَةٌ". ثُمَّ أَتَى الْقَبْرَ، فَصَفَفْنَا خَلْفَهُ، فَكَبَّرَ عَلَيْهِ أَرْبَعًا. (ن,جه)', 'യസീദുബ്നു ഥാബിത്(റ): ഞങ്ങൾ നബി(സ)യുടെ കൂടെ പുറപ്പെട്ടു. ബഖീഇൽ എത്തിയപ്പോൾ നബി(സ) ഒരു പുതിയ ഖബറിന് സമീപമെത്തി. നബി(സ) അതിനെ കുറിച്ച് ചോദിച്ചു. അവർ പറഞ്ഞു: ഇത് ഇന്ന സ്ത്രീയാണ്. അപ്പോൾ നബി(സ)ക്ക് അവളെ മനസ്സിലായി. നബി(സ) ചോദിച്ചു: "എന്തുകൊണ്ട് നിങ്ങൾ അവളെപറ്റി എന്നെ അറിയിച്ചില്ല?" അവർ മറുപടി പറഞ്ഞു: താങ്കൾ നോമ്പ് നോറ്റ് ഉച്ചയുറക്കത്തിലായിരുന്നു. അതിനാൽ താങ്കളെ ബുദ്ധിമുട്ടിക്കാൻ ഞങ്ങൾ മടിച്ചു. സബി(സ) പറഞ്ഞു: "നിങ്ങൾ അങ്ങനെ ചെയ്യരുത്. ഞാൻ നിങ്ങൾക്കിടയിലായിരിക്കവേ നിങ്ങളിൽ ഒരാളാൾ മരിച്ചാൽ എന്നെ അറിയിച്ചാലല്ലാതെ ഞാനത് അറിയില്ല. എന്റ നിസ്കാരം ആ മരണപ്പെട്ടവന് ഒരു അനുഗ്രഹമാണ്." പിന്നെ നബി(സ) ഖബ്റിങ്കലെത്തി ഞങ്ങൾ പിന്നൽ അണിയായിനിന്നു. നബി(സ) നാല് തക്ബീർ ചൊല്ലികൊണ്ട് നിസ്കരിച്ചു. (ന,ജ)', 'يَزِيدَ بْنِ ثَابِتٍ', 'യസീദുബ്നു ഥാബിത്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 860, 860, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 379, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَاتَ رَجُلٌ، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُهُ، فَدَفَنُوهُ بِاللَّيْلِ، فَلَمَّا أَصْبَحَ أَعْلَمُوهُ، فَقَالَ: "مَا مَنَعَكُمْ أَنْ تُعْلِمُونِي". قَالُوا: كَانَ اللَّيْلُ، وَكَانَتِ الظُّلْمَةُ، فَكَرِهْنَا أَنْ نَشُقَّ عَلَيْكَ. فَأَتَى قَبْرَهُ فَصَلَّى عَلَيْهِ. (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ മരണപ്പെട്ടു, നബി(സ) അയാളുടെ രോഗം സന്ദർശിച്ചിരുന്നു, അവർ (സഹാബികൾ) അദ്ദേഹത്തെ രാത്രിയിൽ മറമാടി. പ്രഭാതമായപ്പോൾ ആ കാര്യം അവർ നബി(സ)യെ അറിയിച്ചു. നബി(സ) അവരോട് ചോദിച്ചു: "നിങ്ങളെന്നെ അറിയിക്കുന്നതിൽ നിന്ന് തടഞ്ഞതെന്താണ്?" അവർ പറഞ്ഞു: രാത്രിയും ഇരുട്ടുമായിരുന്നതിനാൽ താങ്കളെ പ്രയാസപ്പെടുത്തുന്നത് ഞങ്ങൾ ഇഷ്ടപ്പെട്ടില്ല. നബി(സ) അദ്ദേഹത്തിന്റെ ഖബ്റിനടുത്ത് വന്ന് നിസ്കരിച്ചു. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 860, 860, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 380, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى قَبْرٍ بَعْدَ مَا قُبِرَ. (م,جه)', 'അനസ്(റ): അടക്കം ചെയ്യപ്പെട്ട ഒരു ഖബ്റിടത്തിൽ വെച്ച് നബി(സ) നിസ്കരിച്ചു. (മു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 860, 860, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 381, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى مَيِّتٍ بَعْدَ مَا دُفِنَ. (جه)', 'ബുറൈദ(റ): മറമാടപ്പെട്ട ശേഷം ഒരു മയ്യിത്തിന് വേണ്ടി നബി(സ) നിസ്കരിച്ചു. (ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 860, 860, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 382, 'عَنْ هِشَامِ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: شَكَوْنَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ أُحُدٍ، فَقُلْنَا: يَا رَسُولَ اللهِ، الْحَفْرُ عَلَيْنَا لِكُلِّ إِنْسَانٍ شَدِيدٌ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "احْفِرُوا وَأَعْمِقُوا وَأَحْسِنُوا، وَادْفِنُوا الِاثْنَيْنِ وَالثَّلَاثَةَ فِي قَبْرٍ وَاحِدٍ". قَالُوا: فَمَنْ نُقَدِّمُ يَا رَسُولَ اللهِ؟ قَالَ: "قَدِّمُوا أَكْثَرَهُمْ قُرْآنًا". قَالَ: فَكَانَ أَبِي ثَالِثَ ثَلَاثَةٍ فِي قَبْرٍ وَاحِدٍ. (د,ت,ن,جه)', 'ഹിശാമുബ്നു ആമിർ(റ): ഞങ്ങൾ ഉഹ്ദ് ദിനത്തിൽ നബി(സ)യോട് പരാതി പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, എല്ലാ ആളുകൾക്കും വേണ്ടി കുഴികുഴിക്കാൻ ഞങ്ങൾക്ക് വളരെ പ്രയാസമാണ്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ആഴത്തിൽ നന്നായി ഖബർ കുഴിക്കുക. ഒരു ഖബറിൽ രണ്ടും മൂന്നും പേരെ മറമാടുക." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ ആരെയാണ് ഞങ്ങൾ മുന്തിക്കേണ്ടത്? നബി(സ) പറഞ്ഞു: "അവരിൽ ഖുർആൻ ഏറ്റവും കൂടുതൽ അറിയുന്നവരെ നിങ്ങൾ മുന്തിക്കുക." അദ്ദേഹം (ഹിശാം) പറഞ്ഞു: എന്റെ പിതാവ് ഒരു ഖബറിൽ മൂന്നിൽ മൂന്നാമനായിരുന്നു. (ദ,തു,ന,ജ)', 'هِشَامِ بْنِ عَامِرٍ', 'ഹിശാമുബ്നു ആമിർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 860, 861, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 383, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "زُورُوا الْقُبُورَ، فَإِنَّهَا تُذَكِّرُكُمُ الْآخِرَةَ". (م,د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഖബറുകൾ സന്ദർശിക്കുക. നിശ്ചയം, അത് നിങ്ങൾക്ക് പരലോകത്തെ ഓർമ്മിപ്പിച്ചു തരും." (മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 861, 861, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 384, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَخَّصَ فِي زِيَارَةِ الْقُبُورِ. (جه)', 'ആഇശ(റ): നബി(സ) ഖബർ സന്ദർശനത്തിൽ ഇളവ് നൽകി. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 861, 861, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 385, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كُنْتُ نَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ، فَزُورُوهَا، فَإِنَّهَا تُزَهِّدُ فِي الدُّنْيَا وَتُذَكِّرُ الْآخِرَةَ". (جه)', 'ഇബ്നുമസ്ഊദ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങൾക്ക് ഖബർ സന്ദർശനം വിലക്കിയിരുന്നു. (ഇനി) നിങ്ങൾ അവ സന്ദർശിച്ചു കൊള്ളുക. കാരണം അത് ഐഹിക ലോകത്തോട് വിരക്തിയും പരലോക സ്മരണയും ഉണ്ടാക്കും." (ജ)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 861, 861, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 386, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "نَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ، فَزُورُوهَا. وَنَهَيْتُكُمْ عَنْ لُحُومِ الْأَضَاحِيِّ فَوْقَ ثَلَاثَةِ أَيَّامٍ، فَامْسِكُوا مَا بَدَا لَكُمْ. وَنَهَيْتُكُمْ عَنِ النَّبِيذِ إِلَّا فِي سِقَاءٍ، فَاشْرَبُوا فِي الْأَسْقِيَةِ كُلِّهَا، وَلَا تَشْرَبُوا مُسْكِرًا". (م,ن)', 'ബുറൈദ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് ഖബ്ർസന്ദർശനം ഞാൻ നിരോധിച്ചിരുന്നു. അവ നിങ്ങൾ സന്ദർശിച്ചു കൊള്ളുക. ബലിമാംസം മൂന്ന് ദിവസത്തിലധികം ഉപയോഗിക്കുന്നത് ഞാൻ നിരോധിച്ചിരുന്നു. എന്നാൽ നിങ്ങൾക്ക് (ഉപയോഗിക്കുന്നതിൽ ദോഷമില്ല എന്ന്) തോന്നുന്ന അത്രനാൾ അത് സൂക്ഷിക്കാം. വെള്ളപ്പാത്രത്തിലല്ലാത്ത മുന്തിരിച്ചാറാണ് ഞാൻ നിരോധിച്ചിരുന്നത്. അതിനാൽ എല്ലാ ജലപ്പാത്രങ്ങളിലും നിങ്ങൾ കുടിക്കുക, ലഹരിയുണ്ടാക്കുന്നവ നിങ്ങൾ കുടിക്കരുത്." (മു,ന)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 861, 861, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 387, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ فِي مَجْلِسٍ فِيهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "إِنِّي كُنْتُ نَهَيْتُكُمْ أَنْ تَأْكُلُوا لُحُومَ الْأَضَاحِيِّ إِلَّا ثَلَاثًا، فَكُلُوا وَأَطْعِمُوا وَادَّخِرُوا مَا بَدَا لَكُمْ. وَذَكَرْتُ لَكُمْ أَنْ لَا تَنْتَبِذُوا فِي الظُّرُوفِ: الدُّبَّاءِ وَالْمُزَفَّتِ وَالنَّقِيرِ وَالْحَنْتَمِ، انْتَبِذُوا فِيمَا رَأَيْتُمْ وَاجْتَنِبُوا كُلَّ مُسْكِرٍ. وَنَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ، فَمَنْ أَرَادَ أَنْ يَزُورَ فَلْيَزُرْ، وَلَا تَقُولُوا هُجْرًا". (ن)', 'ബുറൈദ(റ): അദ്ദേഹം പ്രവാചക സന്നിധിയിലായിരുന്നു. പ്രവാചകൻ(സ) പറഞ്ഞു: "മൂന്ന് ദിവസം സൂക്ഷിച്ച ബലി മാംസം കഴിക്കുന്നത് ഞാൻ വിലക്കിയിരുന്നു. നിങ്ങൾക്ക് തോന്നുന്നത്ര ദിവസം തിന്നുകയും സൂക്ഷിച്ചു വക്കുകയും ഭക്ഷിപ്പിക്കുകയും ചെയ്യുക. ചുരക്കയുടെ പാത്രം, ടാർ പൂശിയ പാത്രം, മരം തുരന്നുണ്ടാക്കിയ പാത്രം, (കളിമണ്ണ്, മുടി, രക്തം) എന്നിവയുടെ മിശ്രിതത്തിൽ നിന്നുണ്ടാക്കിയ പാത്രം തുടങ്ങിയവയിൽ മുന്തിരി, കാരക്ക തുടങ്ങിയവ കുറുക്കരുതെന്ന് നിങ്ങളോട് പറഞ്ഞിരുന്നു. എന്നാൽ നിങ്ങൾ ഇഷ്ടമുള്ളതിൽ കുറുക്കുക. എല്ലാ ലഹരിയുണ്ടാക്കുന്നതും നിങ്ങൾ വെടിയുക. ഖബ്ർ സന്ദർശനം ഞാൻ വിലക്കിയിരുന്നു. എന്നാൽ സന്ദർശനം ആഗ്രഹിക്കുന്നവർക്ക് സന്ദർശിക്കാം. നിങ്ങൾ മോശമായ സംസാരം നടത്തരുത്." (ന)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 861, 862, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 388, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَبْرَ أُمِّهِ، فَبَكَى وَأَبْكَى مَنْ حَوْلَهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اسْتَأْذَنْتُ رَبِّي تَعَالَى عَلَى أَنْ أَسْتَغْفِرَ لَهَا فَلَمْ يُؤْذَنْ لِي، فَاسْتَأْذَنْتُ أَنْ أَزُورَ قَبْرَهَا فَأَذِنَ لِي، فَزُورُوا الْقُبُورَ، فَإِنَّهَا تُذَكِّرُ بِالْمَوْتِ". (م,د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) തന്റെ മാതാവിന്റെ ഖബ്റിടത്തിലെത്തി. അവിടെ നിന്നും കരഞ്ഞു. അത് തിരുമേനി(സ)യുടെ ചുറ്റുമുള്ളവരെ കരയിപ്പിച്ചു. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "എന്റെ മാതാവിന് വേണ്ടി പാപമോചനത്തിനർത്തിക്കാൻ ഞാൻ എന്റെ നാഥനോട് അനുവാദം ചോദിച്ചു. എനിക്ക് അനുവാദം കിട്ടിയില്ല. അപ്പോൾ എന്റെ മാതാവിന്റെ ഖബർ സന്ദർശിക്കാൻ ഞാൻ അനുവാദം ചോദിച്ചു. എനിക്ക് അനുവാദം കിട്ടി. അത് കൊണ്ട് നിങ്ങൾ ഖബറുകൾ സന്ദർശിക്കുക. അത് മരണത്തെ ഓർമ്മിപ്പിക്കും." (മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 862, 862, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 389, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَّ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِامْرَأَةٍ تَبْكِي عِنْدَ قَبْرٍ فَقَالَ: "اتَّقِي اللهَ وَاصْبِرِي". قَالَتْ: إِلَيْكَ عَنِّي فَإِنَّكَ لَمْ تُصَبْ بِمُصِيبَتِي وَلَمْ تَعْرِفْهُ، فَقِيلَ لَهَا إِنَّهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَتَتْ بَابَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلَمْ تَجِدْ عِنْدَهُ بَوَّابِينَ، فَقَالَتْ: لَمْ أَعْرِفْكَ، فَقَالَ: "إِنَّمَا الصَّبْرُ عِنْدَ الصَّدْمَةِ الْأُولَى". (ق,د,ت,ن,جه)', 'അനസുബ്നുമാലിക്(റ): ഒരു ഖബ്റിന്റെ അടുക്കൽ വെച്ച് കരഞ്ഞുകൊണ്ടിരിക്കുന്ന ഒരു സ്ത്രീയോട് നബി(സ) പറഞ്ഞു: "നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുക, ക്ഷമിക്കുക." അപ്പോൾ നബി(സ)യെ തിരിച്ചറിയാതെ അവൾ പറഞ്ഞു: എന്നെ വിടൂ, എനിക്ക് ബാധിച്ച അപകടം നിങ്ങൾക്ക് ബാധിക്കുകയോ നിങ്ങൾ മനസ്സിലാക്കിയിട്ടോ ഇല്ല. അത് (ഉപദേശിച്ചത്) പ്രവാചകനാണെന്ന് ശേഷം അവളോട് പറയപ്പെട്ടു. അവൾ പ്രവാചക(സ)ന്റെ വാതിൽക്കലെത്തി. അവിടെ പാറാവുകാരില്ലായിരുന്നു. അവൾ തിരുമേനി(സ)യോട് പറഞ്ഞു: എനിക്ക് താങ്കളെ മനസ്സിലായില്ല. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "ക്ഷമ അതിന്റെ ആദ്യ ഘട്ടത്തിലാണ്." (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 862, 862, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 390, 'عَنْ عَبْدِ اللهِ بْنِ أَبِي مُلَيْكَةَ قَالَ: تُوُفِّيَ عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرٍ – رَضِيَ اللهُ عَنْهُمَا – بِالْحُبْشِيِّ، قَالَ: فَحُمِلَ إِلَى مَكَّةَ فَدُفِنَ فِيهَا، فَلَمَّا قَدِمَتْ عَائِشَةُ – رَضِيَ اللهُ عَنْهَا – أَتَتْ قَبْرَ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ، فَقَالَتْ:
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 391, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَعَنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ زُوَّارَاتِ الْقُبُورِ. (د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഖബ്റുകൾ സന്ദർശിക്കുന്ന സ്ത്രീകളെ ശപിച്ചിരിക്കുന്നു. (ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 863, 863, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 392, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَعَنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ زَائِرَاتِ الْقُبُورِ، وَالْمُتَّخِذِينَ عَلَيْهَا الْمَسَاجِدَ وَالسُّرُجَ. (د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഖബ്റുകൾ സന്ദർശിക്കുന്ന സ്ത്രീകളേയും അവയുടെ മുകളിൽ പള്ളികളുണ്ടാക്കുകയും വിളക്കുവെക്കുകയും ചെയ്യുന്നവരെയും റസൂൽ(സ) ശപിച്ചിരിക്കുന്നു. (ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 863, 863, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 393, 'عَنْ سَالِم عَنْ أَبِيه قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، إِنَّ أَبِي كَانَ يَصِلُ الرَّحِمَ، وَكَانَ وَكَانَ، فَأَيْنَ هُوَ؟ قَالَ: "فِي النَّارِ". قَالَ: فَكَأَنَّهُ وَجَدَ مِنْ ذَلِكَ، فَقَالَ: يَا رَسُولَ اللهِ، فَأَيْنَ أَبُوكَ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "حَيْثُمَا مَرَرْتَ بِقَبْرِ مُشْرِكٍ فَبَشِّرْهُ بِالنَّارِ". قَالَ: فَأَسْلَمَ الْأَعْرَابِيُّ بَعْدُ، وَقَالَ: لَقَدْ كَلَّفَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَعَبًا، مَا مَرَرْتُ بِقَبْرِ كَافِرٍ إِلَّا بَشَّرْتُهُ بِالنَّارِ. (جه)', 'സാലിം തന്റെ പിതാവിൽനിന്ന്: ഒരു അഅ്റാബി നബി(സ)യുടെ അടുത്ത് വന്നിട്ട് പറഞ്ഞു. അല്ലാഹുവിന്റെ ദൂതരേ, എന്റെ പിതാവ് കുടുംബ ബന്ധം ചേർത്തിരുന്നു. അദ്ദേഹം അങ്ങിനെയും ഇങ്ങിനെയുമൊക്കെയായിരുന്നു, അത് കൊണ്ട് അദ്ദേഹം എവിടെയാണ്. പ്രവാചകൻ(സ) പ്രതിവചിച്ചു: "നരകത്തിൽ." അയാൾ നബി(സ)യുടെ മറുപടിയിൽ ദേഷ്യം പിടിച്ചപോലെ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ, അപ്പോൾ താങ്കളുടെ പിതാവ് എവിടെയാണ്. പ്രവാചകൻ(സ) പറഞ്ഞു: "നീ ഒരു മുശ്രിക്കിന്റെ ഖബ്റിനടുത്തുകൂടെ നടന്ന് പോകുമ്പോഴെക്കെ അയാൾക്ക് നരകം കൊണ്ട് സന്തോഷ വാർത്ത നൽകുക." റിപ്പോർട്ടർ പറഞ്ഞു: പിന്നീട് അഅ്റാബി മുസ്ലിമായി. അദ്ദേഹം പറഞ്ഞു: വളരെ പ്രയാസകരമായ കാര്യം ചെയ്യാൻ റസൂൽ(സ) എന്നെ നിർബന്ധിച്ചിരിക്കുന്നു. ഞാൻ ഏതൊരു കാഫിറിന്റെ ഖബ്റിനരികിലൂടെ പോകുമ്പോഴും അയാൾക്ക് നരകം കൊണ്ട് സുവാർത്ത അറിയിക്കണം. (ജ)', 'سَالِم عَنْ أَبِيه قَالَ', 'സാലിം തന്റെ പിതാവിൽനിന്ന്', null, null, array['جه']::text[], array['ജ']::text[], null, null, 863, 863, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=115 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 394, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْعَبْدَ إِذَا وُضِعَ فِي قَبْرِهِ، وَتَوَلَّى عَنْهُ أَصْحَابُهُ، إِنَّهُ لَيَسْمَعُ قَرْعَ نِعَالِهِمْ. [زَادَ فِي رِوَايَةٍ: إِذَا انْصَرَفُوا]. قَالَ: يَأْتِيهِ مَلَكَانِ فَيُقْعِدَانِهِ، فَيَقُولَانِ لَهُ: مَا كُنْتَ تَقُولُ فِي هَذَا الرَّجُلِ؟ قَالَ: فَأَمَّا الْمُؤْمِنُ فَيَقُولُ: أَشْهَدُ أَنَّهُ عَبْدُ اللهِ وَرَسُولُهُ. قَالَ: فَيُقَالُ لَهُ: انْظُرْ إِلَى مَقْعَدِكَ مِنَ النَّارِ قَدْ أَبْدَلَكَ اللهُ بِهِ مَقْعَدًا مِنَ الْجَنَّةِ. قَالَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: فَيَرَاهُمَا جَمِيعًا. قَالَ قَتَادَةُ: وَذُكِرَ لَنَا أَنَّهُ يُفْسَحُ لَهُ فِي قَبْرِهِ سَبْعُونَ ذِرَاعًا، وَيُمْلَأُ عَلَيْهِ خَضِرًا إِلَى يَوْمِ يُبْعَثُونَ". (م,ن)', 'അനസുബ്നുമാലിക്(റ): നബി(സ) പറഞ്ഞു: "ഒരു അടിമയെ ഖബ്റിൽ വെക്കുകയും അതിന്റെ ആളുകൾ പിരിഞ്ഞ് പോകുകയും ചെയ്താൽ അവരുടെ ചെരുപ്പിന്റെ ശബ്ദം അവൻ കേൾക്കും. അവന്റെ അടുത്ത് രണ്ട് മലക്കുകൾ വരും, അവർ അവനെ ഇരുത്തും. അവർ അവനോട് ചോദിക്കും: ഈ മനുഷ്യരെ കുറിച്ച് നീ എന്ത് പറയുന്നു? മുഅ്മിനായവൻ പറയും: അദ്ദേഹം അല്ലാഹുവിന്റെ അടിമയും ദൂതനുമാണെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. അപ്പോൾ അവനോട് പറയും: നരകത്തിൽ നിനക്കുള്ള സ്ഥാനം നീ നോക്കുക, അതിന് പകരം സ്വർഗ്ഗത്തിൽ അല്ലാഹു നിനക്ക് ഒരു സ്ഥാനം നൽകിയിരിക്കുന്നു. നബി(സ) പറഞ്ഞു: അവൻ അത് മുഴുവൻ നോക്കി കാണും. ഖതാദ പറഞ്ഞു: അവന്റെ ഖബർ എഴുപത് മുഴം വരെ വിശാലമാകും, അന്ത്യനാൾ വരെ അവന്ന് പച്ചപ്പ് ലഭിക്കും എന്ന് ഞങ്ങളേട് പറഞ്ഞു." (മു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], 'زَادَ فِي رِوَايَةٍ: إِذَا انْصَرَفُوا', null, 863, 864, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 395, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "{يُثَبِّتُ اللهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ} [فَقَالَ]: نَزَلَتْ فِي عَذَابِ الْقَبْرِ، يُقَالُ لَهُ: مَنْ رَبُّكَ؟ فَيَقُولُ: رَبِّيَ اللهُ، وَنَبِيِّي مُحَمَّدٌ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَذَلِكَ قَوْلُهُ عَزَّ وَجَلَّ: {يُثَبِّتُ اللهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ} [إبراهيم: ٢٧]". (م,ن)', 'ബറാഉബ്നുആസിബ്(റ): നബി(സ)യിൽ നിന്ന്: "അല്ലാഹു വിശ്വാസികൾക്ക് സ്ഥിരപ്പെട്ട വൃത്താന്തം കൊണ്ട് സ്ഥൈര്യം നൽകും എന്ന ആയത്ത് ഖബ്റിലെ ശിക്ഷയെ കുറിച്ചാണ്. അവനോട് (ഖബ്റിലെ വ്യക്തിയോട്) ചോദിക്കും: ആരാണ് നിന്റെ നാഥൻ? അവൻ പറയും: എന്റെ നാഥൻ അല്ലാഹുവാണ്, എന്റെ പ്രവാചകൻ മുഹമ്മദ് നബി(സ)യുമാണ്. അതാണ്: ''ഐഹിക ജീവിതത്തിലും പാരത്രികജീവിതത്തിലും ഉറച്ച വൃത്താന്തം കൊണ്ട് സത്യവിശ്വാസികൾക്ക് അല്ലാഹു സ്ഥൈര്യം നൽകും'' (ഇബ്റാഹീം: 27) എന്ന ആയത്ത്." (മു,ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നുആസിബ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], 'إبراهيم: ٢٧', null, 864, 864, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 396, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَمِعَ صَوْتًا مِنْ قَبْرٍ، فَقَالَ: "مَتَى مَاتَ هَذَا". قَالُوا: مَاتَ فِي الْجَاهِلِيَّةِ، فَسُرَّ بِذَلِكَ وَقَالَ: "لَوْلَا أَنْ لَا تَدَافَنُوا لَدَعَوْتُ اللهَ أَنْ يُسْمِعَكُمْ عَذَابَ الْقَبْرِ". (ن)', 'അനസ്(റ): നബി(സ) ഒരു ഖബ്റിൽ നിന്ന് ഒരു ശബ്ദം കേട്ടു. അവിടുന്ന് ചോദിച്ചു, "ഇയാൾ എപ്പോഴാണ് മരിച്ചത്?" ജാഹിലിയ്യാ കാലത്ത്, അവർ പറഞ്ഞു. നബി(സ) സന്തോഷിച്ചു. എന്നിട്ട് പറഞ്ഞു: "നിങ്ങൾ പരസ്പരം മറമാടുക എന്നതില്ലായിരുന്നെങ്കിൽ ഖബ്റിലെ ശിക്ഷ നിങ്ങളെ കേൾപ്പിക്കാൻ ഞാൻ അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുമായിരുന്നു." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 864, 864, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 397, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ أَبِي أَيُّوبَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْدَ مَا غَرَبَتِ الشَّمْسُ، فَسَمِعَ صَوْتًا، فَقَالَ: "يَهُودُ تُعَذَّبُ فِي قُبُورِهَا". (ق,ن)', 'ബറാഉബ്നുആസ്ബ്(റ): നബി(സ) സൂര്യാസ്തമയ ശേഷം പുറപ്പെട്ടു. അപ്പോൾ ഒരു ശബ്ദം കേട്ടു. അവിടുന്ന് പറഞ്ഞു: "യഹൂദികൾ തങ്ങളുടെ ഖബറുകളിൽ ശിക്ഷിക്കപ്പെടുന്നു." (ബു,മു,ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നുആസ്ബ്(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 864, 864, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 398, 'عَنْ سُلَيْمَانَ بْنِ صُرَد: أَنَّهُ قَالَ لِخَالِد بْنِ عُرْفُطَةَ – أَوْ خَالِدٌ لِسُلَيْمَانَ – رَضِيَ اللهُ عَنْهُمَا: أَمَا سَمِعْتَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ قَتَلَهُ بَطْنُهُ لَمْ يُعَذَّبْ فِي قَبْرِهِ". فَقَالَ أَحَدُهُمَا لِصَاحِبِهِ: نَعَمْ. حَسَنٌ. (ت)', 'സുലൈമാനുബ്നു സുറദ്(റ): അദ്ദേഹം ഖാദിലിദുബ്നു ഉർഫയോടോ, അല്ലെങ്കിൽ ഖാലിദ് സുലൈമാനോടോ ചോദിച്ചു: "ആരെയെങ്കിലും വയറുരോഗം കൊന്നിട്ടുണ്ടെങ്കിൽ അവൻ ഖബ്റിൽ ശിക്ഷിക്കപ്പെടില്ല" എന്ന് പ്രവാചകൻ(സ) പറയുന്നത് താങ്കൾ കേട്ടിട്ടില്ലേ? അപ്പോൾ അവരിലൊരാൾ സുഹൃത്തിനോട് പറഞ്ഞു. അതെ. (ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു). (തു)', 'سُلَيْمَانَ بْنِ صُرَد', 'സുലൈമാനുബ്നു സുറദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 865, 865, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 399, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أُقْعِدَ الْمُؤْمِنُ فِي قَبْرِهِ أُتِيَ، ثُمَّ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ فَذَلِكَ قَوْلُهُ {يُثَبِّتُ اللهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ}". (خ)', 'നബി(സ)യിൽ നിന്ന് ബറാഉബ്നു ആസിബ്(റ): "മുഅ്മിൻ തന്റെ ഖബറിൽ ഇരുത്തപ്പെട്ടാൽ അല്ലാഹു അല്ലാതെ ഒരു ആരാധ്യനില്ല എന്നും മുഹമ്മദ്(സ) അവന്റെ ദൂതനാണെന്നും അവൻ സാക്ഷ്യം വഹിക്കുന്നു. അതാണ് ''സ്ഥിരമായ വൃത്താന്തം കൊണ്ട് അല്ലാഹു വിശ്വാസികൾക്ക് സൈഥര്യം നൽകും'' എന്ന ആയത്ത് കൊണ്ടുദ്ദേശിക്കുന്നത്." (ബു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'നബി(സ)യിൽ നിന്ന് ബറാഉബ്നു ആസിബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 865, 865, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 400, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا قُبِرَ الْمَيِّتُ – أَوْ قَالَ: أَحَدُكُمْ – أَتَاهُ مَلَكَانِ أَسْوَدَانِ أَزْرَقَانِ، يُقَالُ لِأَحَدِهِمَا: الْمُنْكَرُ، وَالْآخَرُ: النَّكِيرُ، فَيَقُولَانِ: مَا كُنْتَ تَقُولُ فِي هَذَا الرَّجُلِ؟ فَيَقُولُ مَا كَانَ يَقُولُ، هُوَ عَبْدُ اللهِ وَرَسُولُهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ. فَيَقُولَانِ: قَدْ كُنَّا نَعْلَمُ أَنَّكَ تَقُولُ هَذَا. ثُمَّ يُفْسَحُ لَهُ فِي قَبْرِهِ سَبْعُونَ ذِرَاعًا فِي سَبْعِينَ، ثُمَّ يُنَوَّرُ لَهُ فِيهِ، ثُمَّ يُقَالُ لَهُ: نَمْ. فَيَقُولُ: أَرْجِعُ إِلَى أَهْلِي فَأُخْبِرُهُمْ؟ فَيَقُولَانِ: نَمْ كَنَوْمَةِ الْعَرُوسِ الَّذِي لَا يُوقِظُهُ إِلَّا أَحَبُّ أَهْلِهِ إِلَيْهِ، حَتَّى يَبْعَثَهُ اللهُ مِنْ مَضْجَعِهِ ذَلِكَ. وَإِنْ كَانَ مُنَافِقًا قَالَ: سَمِعْتُ النَّاسَ يَقُولُونَ فَقُلْتُ مِثْلَهُ، لَا أَدْرِي. فَيَقُولَانِ: قَدْ كُنَّا نَعْلَمُ أَنَّكَ تَقُولُ ذَلِكَ. فَيُقَالُ لِلْأَرْضِ: الْتَئِمِي عَلَيْهِ. فَتَلْتَئِمُ عَلَيْهِ، فَتَخْتَلِفُ فِيهَا أَضْلَاعُهُ، فَلَا يَزَالُ فِيهَا مُعَذَّبًا حَتَّى يَبْعَثَهُ اللهُ مِنْ مَضْجَعِهِ ذَلِكَ". حَسَنٌ. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മയ്യിത്ത് (അല്ലെങ്കിൽ നിങ്ങളിൽ ഒരാൾ) ഖബറടക്കപ്പെട്ടാൽ അവന്റെ അടുത്ത് നീലക്കണ്ണുകളുള്ള രണ്ട് കറുത്ത മലക്കുകൾ വരും. അവരിലൊരാൾ മുൻകർ മറ്റെയാൾ നകീർ. അവർ അവനോട് ചോദിക്കും: നിങ്ങൾ ഈ മനുഷ്യനെ കുറിച്ച് എന്താണ് പറയുന്നത്? താൻ മുമ്പ് പറയാറുള്ളത് അവൻ പറയും: അല്ലാഹുവിന്റെ അടിമയും ദൂതനുമാണ് അദ്ദേഹം. അല്ലാഹു അല്ലാതെ ഒരു ഇലാഹില്ലെന്നും മുഹമ്മദ്(സ) അവന്റെ അടിമയും ദൂതനുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. അവർ രണ്ടാളും അവനോട് പറയും: താങ്കൾ അങ്ങനെ പറയുമെന്ന് ഞങ്ങൾക്കറിയാം. പിന്നെ അദ്ദേഹത്തിന്റെ ഖബർ എഴുപത് മുഴം (നീളവും വീതിയും) വിശാലമാക്കപ്പെടും. പിന്നെ അതിൽ പ്രകാശിപ്പിക്കപ്പെടും, പിന്നെ അവനോട് പറയപ്പെടും: നീ ഉറങ്ങികൊള്ളുക. അപ്പോൾ അവൻ ചോദിക്കും: ഞാൻ എന്റെ കുടുംബത്തിൽ പോയി അവരോട് ഇത് പറയെട്ടെയോ? അപ്പോൾ അവർ പറയും. നീ പുതുമാരൻ ഉറങ്ങുന്നത് പോലെ ഉറങ്ങിക്കൊള്ളുക. അവന്റെ കുടുംബത്തിൽ അവൻ ഏറ്റവും ഇഷ്ടപ്പെടുന്നവരല്ലാതെ അവനെ ഉണർത്തുകയില്ല. അല്ലാഹു അവനെ ഉണർത്തുന്നത് വരെ (അവൻ ആ ഖബ്റിൽ ഉറങ്ങും). അത് ഒരു മുനാഫിഖാണെങ്കിൽ അവൻ പറയും: ജനങ്ങൾ പറയുന്നത് പോലെ ഞാനും പറഞ്ഞിരുന്നു. എനിക്കറിയില്ല. അവർ പറയും: നീ ഇങ്ങനെ പറയുമെന്ന് ഞങ്ങൾക്കറിയാമായിരുന്നു. അപ്പോൾ ഭൂമിയോട് പറയും: നീ ഇവന്റെ മേൽ ഇടുങ്ങുക. അത് ഇടുങ്ങും. അതിൽ അവന്റെ വാരിയെല്ലുകൾ തെറ്റും. അന്ത്യനാളിൽ അല്ലാഹു അവനെ ഉയർത്തെഴുന്നേൽപ്പിക്കുന്നത് വരെ (അവൻ അതിൽ ശിക്ഷിക്കപ്പെടും)." (ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു). (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 865, 865, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 401, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعَلِّمُهُمْ هَذَا الدُّعَاءَ كَمَا يُعَلِّمُهُمُ السُّورَةَ مِنَ الْقُرْآنِ: "قُولُوا: اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): ഖുർആനിലെ ആയത്തെന്ന പോലെ പ്രവാചകൻ(സ) ഈ പ്രാർത്ഥന ഇപ്രകാരം അവരെ പഠിപ്പിച്ചിരുന്നു. "നിങ്ങൾ പറയുക: അല്ലാഹുവേ നരകശിക്ഷയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. ഖബ്ർ ശിക്ഷയിൽ നിന്ന് ഞാൻ കാവൽ തേടുന്നു. മസീഹുദ്ദജ്ജാലിന്റെ കുഴപ്പത്തിൽ നിന്നും ഞാൻ കാവൽ ചോദിക്കുന്നു. ജീവിതത്തിലും മരണത്തിലും നേരിടുന്ന കുഴപ്പത്തിൽ നിന്നും നിന്നോട് കാവൽ ചോദിക്കുന്നു." (ന)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 866, 866, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 402, 'عَنْ عَائِشَةَ رضي الله عنها قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعِنْدِي امْرَأَةٌ مِنَ الْيَهُودِ وَهِيَ تَقُولُ: إِنَّكُمْ تُفْتَنُونَ فِي الْقُبُورِ. فَارْتَاعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "إِنَّمَا تُفْتَنُ يَهُودُ". وَقَالَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: فَلَبِثْنَا لَيَالِيَ، ثُمَّ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهُ أُوحِيَ إِلَيَّ أَنَّكُمْ تُفْتَنُونَ فِي الْقُبُورِ". قَالَتْ عَائِشَةُ: فَسَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْدُ يَسْتَعِيذُ مِنْ عَذَابِ الْقَبْرِ. (ن)', 'ആഇശ(റ): നബി(സ) എന്റെ അടുത്തുവന്നു. അപ്പോൾ എന്റെ അടുത്ത് ഒരു യഹൂദ സ്ത്രീയുണ്ടായിരുന്നു. അവൾ ഇപ്രകാരം പറയുന്നുണ്ടായിരുന്നു: നിങ്ങൾ ഖബ്റിൽ ശിക്ഷിക്കപ്പെടും. അപ്പോൾ റസൂൽ(സ) ദേഷ്യത്തോടെ പറഞ്ഞു: "യഹൂദികൾ മാത്രമാണ് ശിക്ഷിക്കപ്പെടുക." ആഇശ(റ) പറയുന്നു: അങ്ങനെ കുറേ ദിവസം കഴിഞ്ഞു. പിന്നെ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഖബറിൽ ശിക്ഷിക്കപ്പെടുമെന്ന് എനിക്ക് വഹ്യ് ലഭിച്ചിരുന്നു." ആഇശ(റ) പറയുന്നു: അതിന്റെ ശേഷം ഖബ്ർ ശിക്ഷയിൽ നിന്ന് റസൂൽ(സ) അല്ലാഹുവോട് കാവൽ ചോദിക്കുന്നത് ഞാൻ കേട്ടു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 866, 866, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 403, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَسْتَعِيذُ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الدَّجَّالِ، وَقَالَ: "إِنَّكُمْ تُفْتَنُونَ فِي قُبُورِكُمْ". (ن)', 'ആഇശ(റ): നബി(സ) ഖബ്ർ ശിക്ഷയിൽ നിന്നും, ദജ്ജാലിന്റെ ശിക്ഷയിൽ നിന്നും രക്ഷ തേടുയിരുന്നു. അവിടുന്ന് പറഞ്ഞു: "നിശ്ചയം നിങ്ങൾ ഖബ്റുകളിൽ ശിക്ഷിക്കപ്പെടും." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 866, 866, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 404, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: دَخَلَتْ يَهُودِيَّةٌ عَلَيْهَا فَاسْتَوْهَبَتْهَا شَيْئًا، فَوَهَبَتْ لَهَا عَائِشَةُ، فَقَالَتْ: أَجَارَكِ اللهُ مِنْ عَذَابِ الْقَبْرِ. قَالَتْ عَائِشَةُ: فَوَقَعَ فِي نَفْسِي مِنْ ذَلِكَ حَتَّى جَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرْتُ ذَلِكَ لَهُ، فَقَالَ: "إِنَّهُمْ لَيُعَذَّبُونَ فِي قُبُورِهِمْ عَذَابًا تَسْمَعُهُ الْبَهَائِمُ". (ن)', 'ആഇശ(റ): എന്റെ അടുത്ത് ഒരു യഹൂദി സ്ത്രീ വന്ന് ദാനം ചോദിച്ചപ്പോൾ ഞാൻ അവൾക്ക് നൽകി. അപ്പോൾ അവൾ പറഞ്ഞു: അല്ലാഹു നിങ്ങളെ ഖബ്ർ ശിക്ഷയിൽ നിന്ന് രക്ഷിക്കെട്ടെ. ആയിശ(റ) പറയുന്നു: എന്റെ മനസ്സിൽ അക്കാര്യത്തിൽ സംശയമുണ്ടായി. അങ്ങനെ പ്രവാചകൻ(സ) വന്നു. അവിടുത്തോട് ഞാൻ കാര്യം പറഞ്ഞു. അവിടുന്ന് പറഞ്ഞു: "അവർ ഖബ്റിൽ ശിക്ഷിക്കപ്പെടും, അത് മൃഗങ്ങൾ കേൾക്കും." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 866, 866, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 405, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: دَخَلَتْ عَلَيَّ عَجُوزَتَانِ مِنْ عُجُزِ يَهُودِ الْمَدِينَةِ، فَقَالَتَا: إِنَّ أَهْلَ الْقُبُورِ يُعَذَّبُونَ فِي قُبُورِهِمْ. قَالَ: "صَدَقَتَا، إِنَّهُمْ يُعَذَّبُونَ عَذَابًا تَسْمَعُهُ الْبَهَائِمُ كُلُّهَا". فَمَا رَأَيْتُهُ صَلَّى صَلَاةً إِلَّا تَعَوَّذَ مِنْ عَذَابِ الْقَبْرِ. (ن)', 'ആഇശ(റ): എന്റെ അടുത്ത് മദീനയിലെ രണ്ട് യഹൂദി വൃദ്ധകൾ വന്നു. അവർ പറഞ്ഞു: ഖബ്റിലുള്ളവർ അവരുടെ ഖബ്റുകളിൽ ശിക്ഷിക്കപ്പെടും. പ്രവാചകൻ(സ) പറഞ്ഞു: "അവർ സത്യം പറഞ്ഞു. അവർ ഖബ്റിൽ ശിക്ഷിക്കപ്പെടുക തന്നെ ചെയ്യും. അത് മൃഗങ്ങൾ കേൾക്കും." ശേഷം ഖബ്ർ ശിക്ഷയിൽ നിന്ന് ശരണം തേടിയിട്ടല്ലാതെ പ്രവാചകൻ(സ) ഒരു നിസ്കാരവും നിർവ്വഹിക്കുന്നത് ഞാൻ കണ്ടിട്ടില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 866, 867, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 406, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: اطَّلَعَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى أَهْلِ الْقَلِيبِ فَقَالَ: "وَجَدْتُمْ مَا وَعَدَ رَبُّكُمْ حَقًّا". فَقِيلَ لَهُ: تَدْعُو أَمْوَاتًا! فَقَالَ: "مَا أَنْتُمْ بِأَسْمَعَ مِنْهُمْ، وَلَكِنْ لَا يُجِيبُونَ". (خ)', 'ഇബ്നുഉമർ(റ): പൊട്ടക്കിണറിലേക്ക് എറിയപ്പെട്ട ആളുകളുടെ അടുത്ത് പോയി നബി(സ) ചോദിച്ചു: "നിങ്ങളുടെ റബ്ബ് വാഗ്ദാനം ചെയ്തിരുന്നത് സത്യമായി കണ്ടില്ലയോ?" അപ്പോൾ ആരോ ചോദിച്ചു: മരിച്ചവരെ വിളിക്കുകയോ? നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് അവരേക്കാൾ കേൾക്കാൻ കഴിയില്ല. പക്ഷേ അവർ മറുപടി പറയുകയില്ല." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 867, 867, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 407, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ النَّارِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ". قَالَ أَبُو هُرَيْرَةَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْدَ ذَلِكَ يَسْتَعِيذُ مِنْ عَذَابِ الْقَبْرِ. (خ,ن)', 'റസൂലി(സ)ൽ നിന്ന് അബൂഹുറൈറ(റ): "അല്ലാഹുവേ, നിശ്ചയമായും ഞാൻ ഖബ്ർ ശിക്ഷയിൽ നിന്നും, നരകശിക്ഷയിൽ നിന്നും, ജീവിതമരണങ്ങളിലെ കുഴപ്പങ്ങളിൽ നിന്നും, മസീഹുദ്ദജ്ജാലിന്റെ ഫിത്നയിൽ നിന്നും നിന്നോട് കാവൽ തേടുന്നു" എന്ന് നബി(സ) പറഞ്ഞിരുന്നു. അബൂഹുറൈറ(റ) പറയുന്നു: അതിന്റെ ശേഷം റസൂൽ(സ) ഖബ്ർ ശിക്ഷയിൽ നിന്നും ശരണം തേടുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'റസൂലി(സ)ൽ നിന്ന് അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 867, 867, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 408, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا قَالَتْ: قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ الْفِتْنَةَ الَّتِي يُفْتَنُ بِهَا الْمَرْءُ فِي قبره، فَلَمَّا ذَكَرَ ذَلِكَ ضَجَّ الْمُسْلِمُونَ ضَجَّةً حَالَتْ بَيْنِي وَبَيْنَ أَنْ أَفْهَمَ كَلَامَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا سَكَنَتْ ضَجَّتُهُمْ قُلْتُ لِرَجُلٍ قَرِيبٍ مِنِّي: أَيْ بَارَكَ اللهُ لَكَ، مَاذَا قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي آخِرِ قَوْلِه؟ قَالَ: "قَدْ أُوحِيَ إِلَيَّ أَنَّكُمْ تُفْتَنُونَ فِي الْقُبُورِ قَرِيبًا مِنْ فِتْنَةِ الدَّجَّالِ". (خ,ن)', 'അബൂബക്കറി(റ)ന്റെ പുത്രി അസ്മാഅ്(റ): നബി(സ) എഴുന്നേറ്റുനിന്നു, ഖബ്റിലെ മനുഷ്യന് ലഭിച്ചേക്കുന്ന ശിക്ഷയെ കുറിച്ച് അവിടുന്ന് സംസാരിച്ചു. നബി(സ) അത് പറഞ്ഞപ്പോൾ ജനങ്ങൾ ശബ്ദകോലാഹലമുണ്ടാക്കി. റസൂൽ(സ) പറഞ്ഞത് കേൾക്കുന്നതിൽ നിന്ന് എനിക്കത് തടസ്സമായി. അവരുടെ കോലാഹലം അടങ്ങിയപ്പോൾ ഞാൻ എന്റെ അടുത്തുള്ള ഒരാളോട് പറഞ്ഞു: അല്ലാഹു താങ്കെളെ അനുഗ്രഹിക്കെട്ടെ. പ്രവാചകൻ(സ) അവസാനമായി എന്താണ് പറഞ്ഞത്? അദ്ദേഹം പറഞ്ഞു: "നിങ്ങൾക്ക് ഖബറുകളിൽ ഏകദേശം ദജ്ജാലിന്റെ ഫിത്ന പോലെയുള്ളത് സംഭവിക്കുമെന്ന് എനിക്ക് വഹ്യ് ലഭിച്ചിരിക്കുന്നു." (ബു,ന)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അബൂബക്കറി(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 867, 867, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 409, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حَائِطٍ لِبَنِي النَّجَّارِ عَلَى بَغْلَةٍ لَهُ، وَنَحْنُ مَعَهُ، إِذْ حَادَتْ بِهِ فَكَادَتْ تُلْقِيهِ، وَإِذَا أَقْبُرٌ سِتَّةٌ أَوْ خَمْسَةٌ أَوْ أَرْبَعَةٌ – قَالَ: كَذَا كَانَ يَقُولُ الْجُرَيْرِيُّ – فَقَالَ: "مَنْ يَعْرِفُ أَصْحَابَ هَذِهِ الْأَقْبُرِ". فَقَالَ رَجُلٌ: أَنَا، قَالَ: "فَمَتَى مَاتَ هَؤُلَاءِ". قَالَ: مَاتُوا فِي الْإِشْرَاكِ. فَقَالَ: "إِنَّ هَذِهِ الْأُمَّةَ تُبْتَلَى فِي قُبُورِهَا، فَلَوْلَا أَنْ لَا تَدَافَنُوا لَدَعَوْتُ اللهَ أَنْ يُسْمِعَكُمْ مِنْ عَذَابِ الْقَبْرِ الَّذِي أَسْمَعُ مِنْهُ". ثُمَّ أَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ: "تَعَوَّذُوا بِاللهِ مِنْ عَذَابِ النَّارِ". فَقَالُوا: نَعُوذُ بِاللهِ مِنْ عَذَابِ النَّارِ. قَالَ: فَقَالَ: "تَعَوَّذُوا بِاللهِ مِنْ عَذَابِ الْقَبْرِ". فَقَالُوا: نَعُوذُ بِاللهِ مِنْ عَذَابِ الْقَبْرِ. قَالَ: "تَعَوَّذُوا بِاللهِ مِنَ الْفِتَنِ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ". قَالُوا: نَعُوذُ بِاللهِ مِنَ الْفِتَنِ، مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ. قَالَ: "تَعَوَّذُوا بِاللهِ مِنْ فِتْنَةِ الدَّجَّالِ". قَالُوا: نَعُوذُ بِاللهِ مِنْ فِتْنَةِ الدَّجَّالِ. (م)', 'സൈദുബ്നു സാബിത്(റ): നബി(സ) തന്റെ കോവർകഴുതപ്പുറത്ത് ബനുന്നജ്ജാർ ഗോത്രക്കാരുടെ ഒരു തോട്ടത്തിലായിരുന്നു. അവിടത്തോടൊപ്പം ഞങ്ങളുമുണ്ടായിരുന്നു. അപ്പോൾ കോവർകഴുത തിരുമേനി(സ)യെ തള്ളിയിടും പോലെ തിരിഞ്ഞു. അവിടെ നാലോ അഞ്ചോ ആറോ ഖബ്റുകളുണ്ടായിരുന്നു ഇങ്ങനെയാണ് ജുവൈരി പറഞ്ഞിരുന്നത്: പ്രവാചകൻ(സ) ചോദിച്ചു: "ഈ ഖബ്ർവാസികളെ ആർക്കാണറിയുക?" അപ്പോൾ ഒരാൾ പറഞ്ഞു: ഞാൻ (അറിയും). പ്രവാചകൻ(സ) ചോദിച്ചു: "എപ്പോഴാണ് അവർ മരിച്ചത്?" അവർ ബഹുദൈവാരാധനയിലാണ് മരിച്ചത് എന്ന് അയാൾ പ്രതിവചിച്ചു. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "നിശ്ചയം ഈ സമുദായം തങ്ങളുടെ ഖബ്റുകളിൽ ശിക്ഷിക്കപ്പെടും. മരിച്ചവരെ നിങ്ങൾ പരസ്പരം മറമാടുകയില്ലായിരുന്നുവെങ്കിൽ ഞാൻ കേൾക്കുന്ന ഖബ്റിലെ ശിക്ഷ നിങ്ങളേയും കേൾപ്പിക്കാൻ അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുമായിരുന്നു." പിന്നെ അവിടുന്ന് ഞങ്ങളിലേക്ക് മുഖം തിരിച്ചിട്ടു പറഞ്ഞു: "നിങ്ങൾ നരകശിക്ഷയിൽ നിന്നും അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുക." അവർ പറഞ്ഞു: നരകശിക്ഷയിൽ നിന്ന് ഞങ്ങൾ അല്ലാഹുവിനോട് ശരണം തേടുന്നു. പിന്നെ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഖബ്ർ ശിക്ഷയിൽ നിന്ന് അല്ലാഹുവോട് കാവൽ തേടുക." അവർ പറഞ്ഞു: നരകശിക്ഷയിൽ നിന്ന് ഞങ്ങൾ അല്ലാഹുവോട് കാവൽ തേടുന്നു. അവിടുന്ന് പറഞ്ഞു: "രഹസ്യവും പരസ്യവുമായ എല്ലാ കുഴപ്പങ്ങളിൽ നിന്നും നിങ്ങൾ അല്ലാഹുവോട് ശരണം തേടുക." അവർ പറഞ്ഞു: രഹസ്യവും പരസ്യവുമായ എല്ലാ കുഴപ്പങ്ങളിൽ നിന്നും ഞങ്ങൾ അല്ലാഹുവോട് ശരണം തേടുന്നു. നബി(സ) തുടർന്നു: "ദജ്ജാലിന്റെ കുഴപ്പത്തിൽ നിന്ന് നിങ്ങൾ അല്ലാഹുവോട് ശരണം തേടുക." അവർ പറഞ്ഞു: ദജ്ജാലിന്റെ കുഴപ്പത്തിൽ നിന്ന് ഞങ്ങൾ അല്ലാഹുവോട് ശരണം തേടുന്നു. (മു)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 867, 868, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 410, 'عَنْ مُحَمَّدِ بْنِ قَيْسٍ أَنَّهُ قَالَ يَوْمًا: أَلَا أُخَبِّرُكُمْ عَنِّي وَعَنْ أُمِّي؟ قَالَ: فَظَنَنَّا أَنَّهُ يُرِيدُ أُمَّهُ الَّتِي وَلَدَتْهُ، قَالَ: قَالَتْ عَائِشَةُ: أَلَا أُحَدِّثُكُمْ عَنِّي وَعَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قُلْنَا: بَلَى، قَالَ: قَالَتْ: لَمَّا كَانَتْ لَيْلَتِي الَّتِي [كَانَ] النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِيهَا عِنْدِي انْقَلَبَ فَوَضَعَ رِدَاءَهُ، وَخَلَعَ نَعْلَيْهِ فَوَضَعَهُمَا عِنْدَ رِجْلَيْهِ، وَبَسَطَ طَرَفَ إِزَارِه عَلَى فِرَاشِه فَاضْطَجَعَ، فَلَمْ يَلْبَثْ إِلَّا رَيْثَمَا ظَنَّ أَنْ قَدْ رَقَدْتُ، فَأَخَذَ رِدَاءَهُ رُوَيْدًا، وَانْتَعَلَ رُوَيْدًا، وَفَتَحَ الْبَابَ [رُوَيْدًا] فَخَرَجَ ثُمَّ أَجَافَهُ رُوَيْدًا، فَجَعَلْتُ دِرْعِي فِي رَأْسِي، وَاخْتَمَرْتُ، وَتَقَنَّعْتُ إِزَارِي، ثُمَّ انْطَلَقْتُ عَلَى إِثْرِه، حَتَّى جَاءَ الْبَقِيعَ، فَقَامَ فَأَطَالَ الْقِيَامَ، ثُمَّ رَفَعَ يَدَيْه ثَلَاثَ مَرَّاتٍ، ثُمَّ انْحَرَفَ، فَانْحَرَفْتُ، فَأَسْرَعَ فَأَسْرَعْتُ، فَهَرْوَلَ فَهَرْوَلْتُ، فَأَحْضَرَ فَأَحْضَرْتُ فَسَبَقْتُهُ، فَدَخَلْتُ، فَلَيْسَ إِلَّا أَنِ اضْطَجَعْتُ، فَدَخَلَ فَقَالَ: "مَا لَك يَا عَائِش حَشْيَا رَابِيَةً". قَالَتْ: قُلْتُ: لَابِي شَيْءٍ، قَالَ: "لَتُخْبِرِينِي أَوْ لَيُخْبِرَنِّي اللَّطِيفُ الْخَبِيرُ". قَالَتْ: قُلْتُ: يَا رَسُولَ اللهِ بِأَبِي أَنْتَ وَأُمِّي، فَأَخْبَرْتُهُ، قَالَ: "فَأَنْتِ السَّوَادُ الَّذِي رَأَيْتُ أَمَامِي". قُلْتُ: نَعَمْ، فَلَهَدَنِي فِي صَدْرِي لَهْدَةً أَوْجَعَتْنِي، ثُمَّ قَالَ: "أَظَنَنْت أَنْ يَحِيفَ اللهُ عَلَيْك وَرَسُولُهُ". قَالَتْ: مَهْمَا يَكْتُمِ النَّاسُ يَعْلَمْهُ اللهُ، نَعَمْ. قَالَ: "فَإِنَّ جِبْرِيلَ عَلَيْهِ السَّلَامُ أَتَانِي حِينَ رَأَيْت فَنَادَانِي فَأَخْفَاهُ مِنْك، فَأَجَبْتُهُ فَأَخْفَيْتُهُ مِنْك، وَلَمْ يَكُنْ يَدْخُلُ عَلَيْك وَقَدْ وَضَعْت ثِيَابَك، وَظَنَنْت أَنْ قَدْ رَقَدْت فَكَرِهْتُ أَنْ أُوقِظَك، وَخَشِيتُ أَنْ تَسْتَوْحِشِي، فَقَالَ: إِنَّ رَبَّك يَأْمُرُك أَنْ تَأْتِيَ أَهْلَ الْبَقِيعِ، فَتَسْتَغْفِرَ لَهُمْ". قَالَتْ: قُلْتُ: كَيْفَ أَقُولُ لَهُمْ يَا رَسُولَ اللهِ؟ قَالَ: "السَّلَامُ عَلَى أَهْلِ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَيَرْحَمُ اللهُ الْمُسْتَقْدِمِينَ مِنَّا وَالْمُسْتَأْخِرِينَ، وَإِنَّا إِنْ شَاءَ اللهُ بِكُمْ لَلَاحِقُونَ". (م,ن)', 'മുഹമ്മദുബ്നുഖൈസ്(റ) ഒരിക്കൽ പറഞ്ഞു: എന്നെക്കുറിച്ചും എന്റെ മാതാവിനെ കുറിച്ചും നിങ്ങൾക്ക് പറഞ്ഞ് തരട്ടെയോ? (കേട്ടുനിന്ന) ഒരാൾ പറഞ്ഞു: അപ്പോൾ ഞങ്ങൾ വിചാരിച്ചു; അദ്ദേഹമുദ്ദേശിക്കുന്നത് സ്വന്തം പെറ്റുമ്മയെ കുറിച്ചാണെന്നാണ്. അദ്ദേഹം പറഞ്ഞു: ആഇശ(റ) പറഞ്ഞു: എന്നെ കുറിച്ചും റസൂലി(സ)നെ കുറിച്ചും ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞു തരട്ടെയോ? ഞങ്ങൾ പറഞ്ഞു: അതെ. മഹതി പറഞ്ഞു: റസൂൽ(സ) എന്റെ അടുത്തായിരിക്കേണ്ട ഒരു രാത്രി മടങ്ങിവന്നു. തന്റെ തട്ടം യഥാസ്ഥാനത്ത് വെച്ചു. രണ്ട് ചെരുപ്പുമൂരി കാലുകൾക്ക് അരികിൽ വെച്ചു. തന്റെ ഉടുപ്പിന്റെ അറ്റം വിരിപ്പിൽ വെച്ചു എന്നിട്ട് കിടന്നു. ഞാൻ ഉറങ്ങി എന്ന് തോന്നുന്നത് വരെ മാത്രം. തിരുമേനി(സ) അവിടെ കിടന്നു. പിന്നെ മെല്ലെ തന്റെ തട്ടമെടുത്തു പതുക്കെ ചെരുപ്പ് ധരിച്ച് വാതിൽ തുറന്നു പുറത്തേക്കിറങ്ങി. മെല്ലെ വാതിൽ അടച്ചു. അപ്പോൾ ഞാൻ എന്റെ വീട്ടുവസ്ത്രം തലയിൽ വെച്ചു, എന്നിട്ട് മക്കന ധരിച്ചു. വസ്ത്രം പുതച്ചു. പിന്നെ തിരുമേനി(സ)യുടെ പിറകെ പോയി. അങ്ങനെ അവിടുന്ന് ബഖീഇ(ഖബർ സ്ഥാനത്തിന്റെ പേര്)ലെത്തി. അവിടുന്ന് ദീർഘനേരം അവിടെ നിന്നു. പിന്നെ മൂന്ന് പ്രാവശ്യം കൈ ഉയർത്തി. പിന്നെ അവിടുന്ന് തിരിഞ്ഞു. ഞാനും തിരിഞ്ഞു. അദ്ദേഹം വേഗത്തിൽ നടന്നു, ഞാനും വേഗത്തിൽ നടന്നു. പിന്നെ അവിടുന്ന് ഓടും പോലെ നടന്നു. ഞാനും അങ്ങിനെ നടന്നു. അവിടുന്ന് പിന്നെയും വേഗതകൂട്ടി. ഞാനും തിരുമേനി(സ)യെ മുൻകടന്നു വന്നു. അങ്ങനെ ഞാൻ വീട്ടിൽ പ്രവേശിച്ചു. പിന്നെ ഞാൻ കിടന്നപ്പോഴേക്കും തിരുമേനി(സ)യും വന്നു. എന്നിട്ട് ചോദിച്ചു: "ആഇശാ നിനക്കെന്ത് പറ്റി? കിതക്കുന്നതെന്താണ്?" ഞാൻ പറഞ്ഞു: എനിക്കൊന്നും പറ്റിയിട്ടില്ല. നബി(സ) പറഞ്ഞു: "നീ എന്നോട് പറയൂ, അല്ലെങ്കിൽ സൂക്ഷ്മ ജ്ഞാനിയായ അല്ലാഹു എനിക്കും പറഞ്ഞ് തരും." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ മാതാവും പിതാവുമാണെ സത്യം....... ഞാൻ നടന്ന സംഭവം പറഞ്ഞു കൊടുത്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ ആയിരുന്നുവല്ലേ എന്റെ മുന്നിലുണ്ടായിരുന്ന കറുത്ത രൂപം?" ഞാൻ പറഞ്ഞു: അതെ. അപ്പോൾ എന്റെ നെഞ്ചത്ത് ഒരടിയടിച്ചു. അത് എന്നെ വേദനിപ്പിച്ചു. പിന്നെ പറഞ്ഞു: "അല്ലാഹുവും അവന്റെ റസൂലും നിന്നോട് ദ്രോഹം ചെയ്യുമെന്ന് നീ വിചാരിച്ചുവോ?" ആഇശ(റ) പറഞ്ഞു: ശരിയാണ്, മനുഷ്യർ മറച്ച് വെക്കുന്നതൊക്കെ അല്ലാഹു അറിയും. നബി(സ) പറഞ്ഞു: "നീ കണ്ടപ്പോൾ ജിബ്രീൽ(അ) എന്റെ അടുത്ത് വന്നു എന്നെ വിളിച്ചു. അതിനെ നിന്നിൽ നിന്ന് ഗോപ്യമാക്കി. ഞാൻ ഗോപ്യമായി മറുപടിയും നൽകി. നീ വസ്ത്രം ഒഴിവാക്കിയ സമയത്ത് ജിബ്രീൽ(അ) നിന്റടുത്ത് പ്രവേശിക്കുകയില്ല. നീ ഉറങ്ങിയിട്ടുണ്ടെന്നാണ് ഞാൻ വിചാരിച്ചത്. അതിനാൽ ഞാൻ നിന്നെ ഉണർത്താൻ ഇഷ്ടപ്പെട്ടില്ല. നീ ഒറ്റക്കാകുമെന്ന് ഞാൻ പേടിക്കുകയും ചെയ്തു. ജീബ്രീൽ(അ) പറഞ്ഞു: നിന്റെ റബ്ബ് നിന്നോട് ബഖീഇലുള്ളവരുടെ അടുത്തേക്ക് പോകാൻ കൽപിച്ചിട്ടുണ്ട്. എന്നിട്ട് അവർക്ക് പാപമോചനം തേടാനും." ഞാൻ ചോദിച്ചു, അല്ലാഹുവിന്റെ ദൂതരെ! ഞാൻ അവരുടെ അടുത്ത് നിന്ന് എന്താണ് ചൊല്ലേണ്ടത്? അവിടുന്ന് പറഞ്ഞു: "ഖബറിലുള്ള മുസ്ലിംകളെ, സത്യവിശ്വാസികളെ! അല്ലാഹുവിന്റെ രക്ഷ നിങ്ങൾക്കുണ്ടാകട്ടെ, മുമ്പും പിമ്പും നമ്മിൽ നിന്നും മരിച്ചവർക്ക് അല്ലാഹു അനുഗ്രഹം ചൊരിയട്ടെ. അല്ലാഹു ഉദ്ദേശിച്ചാൽ ഞങ്ങൾ നിങ്ങളോട് ചേരും." (മു,ന)', 'مُحَمَّدِ بْنِ قَيْسٍ أَنَّهُ قَالَ يَوْمًا', 'മുഹമ്മദുബ്നുഖൈസ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], 'رُوَيْدًا', null, 868, 869, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 411, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَأَنْ يَجْلِسَ أَحَدُكُمْ عَلَى جَمْرَةٍ، فَتُحْرِقَ ثِيَابَهُ حَتَّى تَخْلُصَ إِلَى جِلْدِه، خَيْرٌ لَهُ مِنْ أَنْ يَجْلِسَ عَلَى قَبْرٍ". (م,د,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ തീ കനലിലിരിക്കുകയും അത് അവന്റെ വസ്ത്രം കരിച്ച് തോലുമായി ചേരുന്നതുമാണ് ഖബ്റിന്റെ മുകളിൽ ഇരിക്കുന്നതിനേക്കാൾ അവന് നല്ലത്." (മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 869, 869, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 412, 'عَنْ وَاثِلَةَ بْنِ الْأَسْقَعِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ أَبَا مَرْثَدٍ الْغَنَوِيَّ رَضِيَ اللهُ عَنْهُ يَقُولُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَجْلِسُوا عَلَى الْقُبُورِ وَلَا تُصَلُّوا إِلَيْهَا". (م,د,ت,ن)', 'വാസിലത്തുബ്നുൽ അസ്ഖഅ്(റ): അബൂമർസദ്(റ) പറയുന്നതായി ഞാൻ കേട്ടിരിക്കുന്നു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഖബ്റുകളിന്മേൽ ഇരിക്കരുത്, അതിലേക്ക് തിരിഞ്ഞ് നിസ്കരിക്കുകയും ചെയ്യരുത്." (മു,ദ,തു,ന)', 'وَاثِلَةَ بْنِ الْأَسْقَعِ', 'വാസിലത്തുബ്നുൽ അസ്ഖഅ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 413, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَأَنْ أَمْشِيَ عَلَى جَمْرَةٍ أَوْ سَيْفٍ، أَوْ أَخْصِفَ نَعْلِي بِرِجْلِي، أَحَبُّ إِلَيَّ مِنْ أَنْ أَمْشِيَ عَلَى قَبْرِ مُسْلِمٍ. وَمَا أُبَالِي: أَوَسْطَ الْقُبُورِ قَضَيْتُ حَاجَتِي أَوْ وَسَطَ السُّوقِ". (جه)', 'ഉഖ്ബത്തുബ്നുആമിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ തീക്കട്ടയുടേയോ വാളിന്റേയോ മുകളിലൂടെ നടക്കുക, അല്ലെങ്കിൽ എന്റെ ചെരുപ്പ് കാലിനോട് ഒട്ടിക്കുക, എന്നിവയാണ് ഒരു മുസ്ലിമിന്റെ ഖബ്റിന്റെ മുകളിലൂടെ നടക്കുന്നതിനേക്കാൾ എനിക്ക് നല്ലത്. അങ്ങാടിയുടേയോ ഖബ്റുകളുടെയോ നടുക്ക് ആവശ്യം നിർവ്വഹിക്കുന്നത് എനിക്ക് ചേർന്നതല്ല." (ജ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബത്തുബ്നുആമിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 414, 'عَنْ عَمْرِو بْنِ حَزْمٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقْعُدُوا عَلَى الْقُبُورِ". (ن)', 'അംറുബ്നു ഹസ്മ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഖബ്റിന് മുകളിൽ ഇരിക്കരുത്." (ന)', 'عَمْرِو بْنِ حَزْمٍ', 'അംറുബ്നു ഹസ്മ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 415, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: خَرَجْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي جَنَازَةِ رَجُلٍ مِنَ الْأَنْصَارِ، فَانْتَهَيْنَا إِلَى الْقَبْرِ وَلَمْ يُلْحَدْ بَعْدُ، فَجَلَسَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُسْتَقْبِلَ الْقِبْلَةِ، وَجَلَسْنَا مَعَهُ. (د,ن,جه)', 'ബറാഅ്ബ്നു ആസിബ്(റ): ഞങ്ങൾ റസൂലി(സ)ന്റെ കൂടെ ഒരു അൻസാരിയുടെ ജനാസയുടെ കാര്യത്തിൽ പുറപ്പെട്ടു. ഞങ്ങൾ ഖബ്റിന് അടുത്ത് എത്തി. അത് മറചെയ്യപ്പെട്ടിട്ടില്ല. അപ്പോൾ നബി(സ) ഖിബ്ലക്ക് തിരിഞ്ഞ് ഇരുന്നു. ഞങ്ങളും കൂടെ ഇരുന്നു. (ദ,ന,ജ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഅ്ബ്നു ആസിബ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 416, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِقُبُورِ الْمَدِينَةِ، فَأَقْبَلَ عَلَيْهِمْ بِوَجْهِهِ فَقَالَ: "السَّلَامُ عَلَيْكُمْ يَا أَهْلَ الْقُبُورِ، يَغْفِرُ اللهُ لَنَا وَلَكُمْ، أَنْتُمْ سَلَفُنَا وَنَحْنُ بِالْأَثَرِ". حَسَنٌ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) മദീനയിലെ ഖബ്റുകളുടെ അടുത്തുകൂടെ നടന്നു. അവിടുന്ന് അവരിലേക്ക് മുഖം തിരിച്ചിട്ട് പറഞ്ഞു: "ഖബ്റിലുള്ളവരേ, അല്ലാഹുവിന്റെ രക്ഷ നിങ്ങൾക്കുണ്ടാകട്ടെ. അല്ലാഹു ഞങ്ങൾക്കും നിങ്ങൾക്കും പൊറുത്തു തരട്ടെ. നിങ്ങൾ മുൻഗാമികൾ, ഞങ്ങൾ പിന്നിലുണ്ട്." ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു. (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=122 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 417, 'عَنْ ثُمَامَةَ بْنِ شُفَيٍّ قَالَ: كُنَّا مَعَ فَضَالَةَ بْنِ عُبَيْدٍ رَضِيَ اللهُ عَنْهُ بِأَرْضِ الرُّومِ، فَتُوُفِّيَ صَاحِبٌ لَنَا، فَأَمَرَ فَضَالَةُ بِقَبْرِهِ فَسُوِّيَ، ثُمَّ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُ بِتَسْوِيَتِهَا. (م,ن)', 'സുമാമത്ത്ബ്നു ശുഫയ്യ്(റ): ഞങ്ങൾ ഫുദാലത്ത്ബ്നു ഉബൈദിന്റെ കൂടെ റോമിലുള്ളപ്പോൾ ഞങ്ങളുടെ ഒരു സുഹൃത്ത് മരണമടഞ്ഞു. അദ്ദേഹത്തിന്റെ ഖബ്ർ നിരപ്പാക്കാൻ കൽപിച്ചു. അത് നിരപ്പാക്കപ്പെട്ടു. പിന്നെ ഫുദാല പറഞ്ഞു: ഖബർ നിരപ്പാക്കാൻ നബി(സ) പറഞ്ഞത് ഞാൻ കേട്ടിട്ടുണ്ട്. (മു,ന)', 'ثُمَامَةَ بْنِ شُفَيٍّ قَالَ', 'സുമാമത്ത്ബ്നു ശുഫയ്യ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 870, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 418, 'عَنْ أَبِي الْهَيَّاجِ الْأَسَدِيِّ قَالَ: قَالَ لِي عَلِيُّ بْنُ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: أَلَا أَبْعَثُك عَلَى مَا بَعَثَنِي عَلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنْ لَا تَدَعَ تَمْثَالًا إِلَّا طَمَسْتَهُ، وَلَا قَبْرًا مُشْرِفًا إِلَّا سَوَّيْتَهُ". (م,د,ت,ن)', 'അബുൽ ഹയ്യാജ് അൽ അസദിയ്യ്(റ): എന്നോട് അലി(റ) പറഞ്ഞു: റസൂൽ(സ) എന്നെ ഏൽപ്പിച്ച കാര്യം ഞാൻ താങ്കളെ ഏൽപിക്കുന്നു. "ഒരു വിഗ്രഹവും നീ തകർക്കാതെ വിടരുത്. ഉയർത്തപ്പെട്ട ഒരു ഖബ്റും നിരപ്പാക്കാതെയും." (മു,ദ,തു,ന)', 'أَبِي الْهَيَّاجِ الْأَسَدِيِّ قَالَ', 'അബുൽ ഹയ്യാജ് അൽ അസദിയ്യ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 871, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 419, 'عَنِ الْقَاسِمِ بْنِ مُحَمَّدِ بْنِ أَبِي بَكْرٍ – رَضِيَ اللهُ عَنْهُمَا – قَالَ: دَخَلْتُ عَلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا فَقُلْتُ: يَا أُمَّهْ، اكْشِفِي لِي عَنْ قَبْرِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَصَاحِبَيْهِ رَضِيَ اللهُ عَنْهُمَا، فَكَشَفَتْ لِي عَنْ ثَلَاثَةِ قُبُورٍ، لَا مُشْرِفَة وَلَا لَاطِئَة، مَبْطُوحَة بِبَطْحَاءِ الْعَرْصَةِ الْحَمْرَاءِ. (د)', 'ഖാസിമുബ്നു മുഹമ്മദുബ്നു അബീബക്കർ(റ): ഞാൻ ആഇശ(റ)യുടെ അടുക്കൽ പ്രവേശിച്ചു. എന്നിട്ട് പറഞ്ഞു: ഉമ്മാ, എനിക്ക് നബി(സ)യുടേയും രണ്ട് അനുചരന്മാരുടേയും ഖബർ കാണിച്ചു തരുമോ? മഹതി എനിക്ക് മൂന്ന് ഖബർ കാണിച്ചു തന്നു. അവ ഉയർന്നതോ താഴ്ന്നതോ ആയിരുന്നില്ല. ചുവന്ന ചരൽ കല്ല് വിരിച്ചതായിരുന്നു അത്. (ദ)', 'الْقَاسِمِ بْنِ مُحَمَّدِ بْنِ أَبِي بَكْرٍ –', 'ഖാസിമുബ്നു മുഹമ്മദുബ്നു അബീബക്കർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 871, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 420, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَعَنَ اللهُ قَوْمًا اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ". (ن)', 'ആഇശ(റ): നിശ്ചയം നബി(സ) പറഞ്ഞു: "തങ്ങളുടെ പ്രവാചകന്മാരുടെ ഖബ്റുകൾ പള്ളിയാക്കുന്ന ജനതയെ അല്ലാഹു ശപിച്ചിരിക്കുന്നു." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 871, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=124 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 421, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ: "لَعَنَ اللهُ الْيَهُودَ وَالنَّصَارَى اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ". قَالَتْ: وَلَوْلَا ذَلِكَ لَأَبْرَزُوا قَبْرَهُ غَيْرَ أَنِّي أَخْشَى أَنْ يُتَّخَذَ مَسْجِدًا. (ق,د,ن)', 'ആഇശാ(റ): നബി(സ) മരിക്കുമ്പോൾ ഉണ്ടായ രോഗത്തിന്റെ അവസരത്തിൽ പറഞ്ഞു: "അല്ലാഹു യഹൂദികളെയും നസ്രാണികളെയും ശപിച്ചിരിക്കുന്നു. അവർ അവരുടെ പ്രവാചകന്മാരുടെ ഖബ്റുകൾ പള്ളികളാക്കി." ആഇശ(റ) പറഞ്ഞു: ഇതില്ലായിരുന്നുവെങ്കിൽ അവർ നബി(സ)യുടെ ഖബർ പുറത്ത് കൊണ്ട് വന്നേനെ. എങ്കിലും തിരുമേനി(സ)യുടെ ഖബ്ർ പള്ളിയാക്കുന്നത് ഞാൻ ഭയക്കുന്നു. (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശാ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 871, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=124 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 422, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: دُفِنَ مَعَ أَبِي رَجُلٌ فِي الْقَبْرِ، فَلَمْ يَطِبْ قَلْبِي حَتَّى أَخْرَجْتُهُ وَدَفَنْتُهُ عَلَى حِدَةٍ. (ن)', 'ജാബിർ(റ): എന്റെ പിതാവിന്റെ കൂടെ ഖബ്റിൽ ഒരാൾ മറമാടപ്പെട്ടു. അദ്ദേഹത്തെ പുറത്തെടുത്ത് ഒറ്റക്ക് മറമാടും വരെ എന്റെ മനസ്സ് സ്വസ്ഥമായില്ല. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 871, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=125 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 423, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَبْدَ اللهِ بْنَ أُبَيٍّ بَعْدَ مَا أُدْخِلَ فِي قَبْرِهِ، فَأَمَرَ بِه فَأُخْرِجَ، فَوَضَعَهُ عَلَى رُكْبَتَيْهِ وَنَفَثَ عَلَيْهِ مِنْ رِيقِهِ وَأَلْبَسَهُ قَمِيصَهُ. وَفِي رِوَايَةٍ: إِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِعَبْدِ اللهِ بْنِ أُبَيٍّ فَأَخْرَجَهُ مِنْ قَبْرِهِ، فَوَضَعَ رَأْسَهُ عَلَى رُكْبَتَيْهِ، فَتَفَلَ فِيهِ مِنْ رِيقِهِ، وَأَلْبَسَهُ قَمِيصَهُ. قَالَ جَابِرٌ: وَصَلَّى عَلَيْهِ. (خ,ن)', 'ജാബിർ(റ): പ്രവാചകൻ(സ)യുടെ കൽപ്പനപ്രകാരം അബ്ദുല്ലാഹിബ്നു ഉബയ്യിനെ ഖബ്റിൽ വെക്കപ്പെട്ട ശേഷം (ഖബ്റിൽനിന്നും) പുറത്തെടുക്കുകയും, നബി(സ)യുടെ അടുക്കലേക്ക് കൊണ്ടുവരപ്പെടുകയും ചെയ്തു. അപ്പോൾ നബി(സ) അദ്ദേഹത്തെ (മയ്യത്തിനെ) തന്റെ ഇരു കാൽമുട്ടിന്മേലായി വെക്കുകയും, (അദ്ദേഹത്തിന്റെ മേൽ) തന്റെ തുപ്പൽ ഊതുകയും അദ്ദേഹത്തെ തന്റെ വസ്ത്രമണിയിക്കുകയും ചെയ്തു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=423), 1, 'وَفِي رِوَايَةٍ: إِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِعَبْدِ اللهِ بْنِ أُبَيٍّ فَأَخْرَجَهُ مِنْ قَبْرِهِ، فَوَضَعَ رَأْسَهُ عَلَى رُكْبَتَيْهِ، فَتَفَلَ فِيهِ مِنْ رِيقِهِ، وَأَلْبَسَهُ قَمِيصَهُ. قَالَ جَابِرٌ: وَصَلَّى عَلَيْهِ. (خ,ن)', 'മറ്റൊരു നിവേദനിൽ: പ്രവാചകൻ(സ)യുടെ കൽപ്പനപ്രകാരം അബ്ദുല്ലാഹിബ്നു ഉബയ്യിനെ ഖബ്റിൽ വെക്കപ്പെട്ടശേഷം (ഖബ്റിൽനിന്നും) പുറത്തെടുത്തു. അപ്പോൾ തിരുമേനി(സ) അദ്ദേഹത്തിന്റെ (മയ്യത്തിന്റെ) തല തന്റെ ഇരു കാൽമുട്ടിന്മേലായി വെക്കുകയും, (അദ്ദേഹത്തിന്റെ മേൽ) തന്റെ തുപ്പൽ ഊതുകയും അദ്ദേഹത്തെ തന്റെ വസ്ത്രമണിയിക്കുകയും ചെയ്തു. ജാബിർ(റ) പറയുന്നു: തിരുമേനി(സ) അദ്ദേഹത്തിനുവേണ്ടി നിസ്കരിക്കുകയും ചെയ്തു. (ബു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 424, 'عَنِ الْأَدْرَعِ السُّلَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: جِئْتُ لَيْلَةً أَحْرُسُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَإِذَا رَجُلٌ قِرَاءَتُهُ عَالِيَةٌ، فَخَرَجَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: يَا رَسُولَ اللهِ، هَذَا مُرَاءٍ. قَالَ: فَمَاتَ بِالْمَدِينَةِ، فَفَرَغُوا مِنْ جَهَازِهِ، فَحَمَلُوا نَعْشَهُ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ارْفُقُوا بِه، رَفَقَ اللهُ بِه. إِنَّهُ كَانَ يُحِبُّ اللهَ وَرَسُولَهُ". قَالَ: وَحَفَرَ حُفْرَتَهُ، فَقَالَ: "أَوْسِعُوا لَهُ، أَوْسَعَ اللهُ عَلَيْهِ". فَقَالَ بَعْضُ أَصْحَابِه: يَا رَسُولَ اللهِ، لَقَدْ حَزِنْتَ عَلَيْهِ؟ فَقَالَ: "أَجَلْ، إِنَّهُ كَانَ يُحِبُّ اللهَ وَرَسُولَهُ". [ز: في إسناده راو مختلف فيه] (جه)', 'അദ്റഉസ്സുലമി(റ): നബി(സ)ക്ക് രാത്രി കാവലിന് വേണ്ടി ഞാൻ ചെന്നു. അവിടെ ഉറക്കെ ഓതുന്ന ഒരാളുണ്ടായിരുന്നു. നബി(സ) പുറത്ത് വന്നപ്പോൾ ഞാൻ പറഞ്ഞു: റസൂലേ, ഇയാൾ ലോകമാന്യനാണ്. മദീനയിൽ വെച്ച് അദ്ദേഹം മരണപ്പെട്ടു. അനന്തര കർമ്മങ്ങൾ പൂർത്തിയാക്കി. അവർ അദ്ദേഹത്തിന്റെ മയ്യിത്ത് വഹിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അദ്ദേഹത്തോട് ലോലമായി പെരുമാറുക. അല്ലാഹു അദ്ദേഹത്തോട് ലോലമായി പെരുമാറിയിട്ടുണ്ട്. അദ്ദേഹം അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും സ്നേഹിച്ചിട്ടുണ്ട്." അദ്ദേഹത്തിന്റെ ഖബർ കുഴിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "അദ്ദേഹത്തിന്റെ ഖബർ വിശാലമാക്കുക. അല്ലാഹു അദ്ദേഹത്തിന്റെ മേൽ വിശാലത ചെയ്തിട്ടുണ്ട്." ചില സ്വഹാബികൾ ചോദിച്ചു: അങ്ങേക്ക് അദ്ദേഹത്തിന്റെ മരണത്തിൽ ദുഃഖമുണ്ടോ? നബി(സ) പറഞ്ഞു: "അതെ, അദ്ദേഹം അല്ലാഹുവിനെയും റസൂലിനെയും ഇഷ്ടപ്പെട്ടിരുന്നു." (ഇതിന്റെ സനദിലെ ഒരു റിപ്പോർട്ടറെക്കുറിച്ച് അഭിപ്രായ ഭിന്നതയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'الْأَدْرَعِ السُّلَمِيِّ', 'അദ്റഉസ്സുലമി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده راو مختلف فيه', null, 872, 872, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=126 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 425, 'عَنْ هِشَامِ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُتِلَ أَبِي يَوْمَ أُحُدٍ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "احْفِرُوا وَأَوْسِعُوا وَأَحْسِنُوا، وَادْفِنُوا الِاثْنَيْنِ وَالثَّلَاثَةَ فِي الْقَبْرِ، وَقَدِّمُوا أَكْثَرَهُمْ قُرْآنًا". فَكَانَ أَبِي ثَالِثَ ثَلَاثَةٍ، وَكَانَ أَكْثَرَهُمْ قُرْآنًا، فَقُدِّمَ. وَفِي رِوَايَةٍ: قَالَ: اشْتَدَّ الْجِرَاحُ يَوْمَ أُحُدٍ، فَشُكِيَ ذَلِكَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "احْفِرُوا وَأَوْسِعُوا وَأَحْسِنُوا، وَادْفِنُوا فِي الْقَبْرِ الاثْنَيْنِ وَالثَّلَاثَةِ، وَقَدِّمُوا أَكْثَرَهُمْ قُرْآنًا". وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "احْفِرُوا وَأَحْسِنُوا، وَادْفِنُوا فِي الْقَبْرِ الاثْنَيْنِ وَالثَّلَاثَةِ، وَقَدِّمُوا أَكْثَرَهُمْ قُرْآنًا". (ن)', 'ഹിശാമുബിനു ആമിർ(റ): ഉഹ്ദ് ദിനത്തിൻ എന്റെ പിതാവ് വധിക്കപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ വിശാലമായും നന്നാക്കിയും കുഴികൾ ഉണ്ടാക്കുക. ഒരു ഖബറിൽ രണ്ടും മൂന്നും പേരെ അടക്കം ചെയ്യുക. അവരിൽ കൂടുതൽ ഖുർആൻ അറിയുന്ന ആളെ മുന്തിക്കുക." എന്റെ പിതാവ് മൂന്നിൽ മൂന്നാമത്തെ ആളായിരുന്നു. അദ്ദേഹത്തിന് കൂടുതൽ ഖുർആൻ അറിയുമായിരുന്നു. അതിനാൽ അദ്ദേഹം മുന്തിക്കപ്പെട്ടു. മറ്റൊരു റിപ്പോർട്ടിൽ: ഉഹ്ദ് ദിവസം ശക്തമായ മുറിവുകൾ ഉണ്ടായി. അത് നബി(സ)യെ അറിയിക്കപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ വിശാലമായും നന്നാക്കിയും ഖബ്ർ കുഴിക്കുക. ഒരു ഖബ്റിൽ രണ്ടും മൂന്നും ആളുകളെ മറമാടുക. അതിൽ ഏറ്റവും കൂടുതൽ ഖുർആൻ അറിയുന്ന ആളെ മുന്തിക്കുക."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=425), 1, 'وَفِي رِوَايَةٍ: قَالَ: اشْتَدَّ الْجِرَاحُ يَوْمَ أُحُدٍ، فَشُكِيَ ذَلِكَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "احْفِرُوا وَأَوْسِعُوا وَأَحْسِنُوا، وَادْفِنُوا فِي الْقَبْرِ الاثْنَيْنِ وَالثَّلَاثَةِ، وَقَدِّمُوا أَكْثَرَهُمْ قُرْآنًا".', 'മറ്റൊരു നിവേദനിൽ: ഉഹ്ദ് ദിവസം ശക്തമായ മുറിവുകൾ ഉണ്ടായി. അത് നബി(സ)യെ അറിയിക്കപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ വിശാലമായും നന്നാക്കിയും ഖബ്ർ കുഴിക്കുക. ഒരു ഖബ്റിൽ രണ്ടും മൂന്നും ആളുകളെ മറമാടുക. അതിൽ ഏറ്റവും കൂടുതൽ ഖുർആൻ അറിയുന്ന ആളെ മുന്തിക്കുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=425), 2, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "احْفِرُوا وَأَحْسِنُوا، وَادْفِنُوا فِي الْقَبْرِ الاثْنَيْنِ وَالثَّلَاثَةِ، وَقَدِّمُوا أَكْثَرَهُمْ قُرْآنًا". (ن)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നന്നായി കുഴിക്കുക. രണ്ടും മൂന്നും ആളുകളെ ഒന്നായി ഖബറടക്കുക. അവരിൽ ഏറ്റവും കൂടുതൽ ഖുർആൻ അറിയുന്ന ആളെ മുന്തിക്കുക." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 426, 'عَنْ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: غَسَّلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلِيٌّ وَالْفَضْلُ وَأُسَامَةُ بْنُ زَيْدٍ، وَهُمْ أَدْخَلُوهُ قَبْرَهُ. قَالَ: حَدَّثَنِي مُرَحِّبٌ، أَوْ أَبُو مَرْحَبٍ: أَنَّهُمْ أَدْخَلُوا مَعَهُمْ عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ، فَلَمَّا فَرَغَ عَلِيٌّ قَالَ: إِنَّمَا يَلِي الرَّجُلَ أَهْلُهُ. (د)', 'ആമിർ(റ): നബി(സ)യെ അലി(റ), ഫദ്ൽ(റ), ഉസാമത്ത്ബ്നു സൈദ്(റ) എന്നിവർ കുളിപ്പിച്ചു. അവർ നബി(സ)യെ ഖബ്റിൽ വെച്ചു. മുറഹ്ഹബ്(അല്ലെങ്കിൽ അബൂമർഹബ്) പറയുന്നു: അവർ അബ്ദുറഹ്മാനുബ്നു ഔഫിനെ(റ) കൂടെ കൂട്ടി. അലി(റ) വിരമിച്ചപ്പോൾ പറഞ്ഞു: ഒരാളുടെ കാര്യം ഏറ്റെടുക്കേണ്ടത് അവന്റെ കുടുംബക്കാരാണ്. (ദ)', 'عَامِرٍ', 'ആമിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 873, 873, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=128 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 427, 'عَنْ أَبِي مُرَحِّبٍ: أَنَّ عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ نَزَلَ فِي قَبْرِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: كَأَنِّي أَنْظُرُ إِلَيْهِمْ أَرْبَعَةً. (د)', 'അബുമുറഹ്ഹബ്(റ): അബ്ദുറഹ്മാനുബ്നു ഔഫ്(റ) നബി(സ)യുടെ ഖബറിൽ പ്രവേശിച്ചു. അദ്ദേഹം തുടർന്നു. ഞാൻ അവരെ നോക്കിയപ്പോൾ നാല് പേരുണ്ടായിരുന്ന പോലെയുണ്ട്. (ദ)', 'أَبِي مُرَحِّبٍ', 'അബുമുറഹ്ഹബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 873, 873, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=128 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 428, 'عَنْ أَبِي إِسْحَقَ قَالَ: أَوْصَى الْحَارِثُ أَنْ يُصَلِّيَ عَلَيْهِ عَبْدُ اللهِ بْنُ يَزِيدَ، فَصَلَّى عَلَيْهِ، ثُمَّ أَدْخَلَهُ الْقَبْرَ مِنْ قِبَلِ رِجْلَيِ الْقَبْرِ وَقَالَ: هَذَا مِنَ السُّنَّةِ. (د)', 'അബൂഇസ്ഹാഖ്(റ): തന്റെമേൽ അബ്ദുല്ലാഹിബ്നുയസീദ് നിസ്ക്കരിക്കണമെന്ന് ഹാരിസ് വസിയ്യത്ത് ചെയ്തു. അങ്ങനെ അദ്ദേഹം നിസ്കരിച്ചു. അദ്ദേഹത്തെ ഖബ്റിലേക്ക് രണ്ട് കാലിന്റെ ഭാഗത്തുകൂടെ പ്രവേശിപ്പിച്ചു. അദ്ദേഹം പറഞ്ഞു: ഇത് സുന്നത്താണ്. (ദ)', 'أَبِي إِسْحَقَ قَالَ', 'അബൂഇസ്ഹാഖ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 873, 873, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=129 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 429, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا فَرَغَ مِنْ دَفْنِ الْمَيِّتِ وَقَفَ عَلَيْهِ فَقَالَ: "اسْتَغْفِرُوا لِأَخِيكُمْ، وَسَلُوا لَهُ بِالتَّثْبِيتِ، فَإِنَّهُ الْآنَ يُسْأَلُ". (د)', 'ഉസ്മാൻ(റ): നബി(സ) മയ്യിത്തിനെ മറമാടിക്കഴിഞ്ഞാൽ അവിടെ നിൽക്കും. എന്നിട്ട് പറയും: "നിങ്ങൾ നിങ്ങളുടെ സഹോദരനു വേണ്ടി പൊറുക്കലിനെ തേടുക, സൈഥര്യം ലഭിക്കാൻ വേണ്ടി ചോദിക്കുക. കാരണം ഇപ്പോൾ അദ്ദേഹം ചോദിക്കപ്പെടും." (ദ)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 873, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=130 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 430, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ يَوْمًا، فَصَلَّى عَلَى أَهْلِ أُحُدٍ صَلَاتَهُ عَلَى الْمَيِّتِ، ثُمَّ انْصَرَفَ. وَفِي رِوَايَةٍ: إِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى قَتْلَى أُحُدٍ بَعْدَ ثَمَانِي سِنِينَ، كَالْمُوَدِّعِ لِلْأَحْيَاءِ وَالْأَمْوَاتِ. (ق,د,ن)', 'ഉഖ്ബത്ബ്നു ആമിർ(റ): നബി(സ) ഒരു ദിവസം പുറപ്പെട്ടു. ഉഹ്ദുകാർക്കുവേണ്ടി മയ്യിത്ത് നിസ്കരിച്ചു. പിന്നെ അവിടുന്ന് പിന്തിരിഞ്ഞു. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) ഉഹ്ദ് യുദ്ധത്തിൽ മരിച്ചവർക്ക് വേണ്ടി എട്ട് കൊല്ലത്തിന് ശേഷം നിസ്കരിച്ചു. തിരുമേനി(സ) മരിച്ചവർക്കും ജീവിക്കുന്നവർക്കും യാത്ര പറയുന്ന പോലെയുണ്ടായിരുന്നു. (ബു,മു,ദ,ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബത്ബ്നു ആമിർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 874, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=430), 1, 'وَفِي رِوَايَةٍ: إِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى قَتْلَى أُحُدٍ بَعْدَ ثَمَانِي سِنِينَ، كَالْمُوَدِّعِ لِلْأَحْيَاءِ وَالْأَمْوَاتِ. (ق,د,ن)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) ഉഹ്ദ് യുദ്ധത്തിൽ മരിച്ചവർക്ക് വേണ്ടി എട്ട് കൊല്ലത്തിന് ശേഷം നിസ്കരിച്ചു. തിരുമേനി(സ) മരിച്ചവർക്കും ജീവിക്കുന്നവർക്കും യാത്ര പറയുന്ന പോലെയുണ്ടായിരുന്നു. (ബു,മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 431, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا عَقْرَ فِي الْإِسْلَامِ". (د)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "ഇസ്ലാമിൽ അറവില്ല." (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 874, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=132 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 432, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يَقْعُدَ عَلَى الْقَبْرِ، وَأَنْ يُقَصَّصَ وَيُبْنَى عَلَيْهِ. وَفِي رِوَايَةٍ: أَوْ أَنْ يُكْتَبَ عَلَيْهِ، أَوْ يُزَادَ عَلَيْهِ. (م,د,ت,ن,جه)', 'ജാബിർ(റ): നബി(സ) ഖബറിൽ ഇരിക്കലും അതിന്മേൽ കുമ്മായം തേക്കലും കെട്ടിടം പണിയലും നിരോധിച്ചിരിക്കുന്നതായി ഞാൻ കേട്ടു. മറ്റൊരു റിപ്പോർട്ടിൽ: അതിന്റെ മേൽ എഴുതൽ, ഉയർത്തൽ എന്നിവ നിരേധിച്ചു. (മു,ദ,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 874, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=133 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=432), 1, 'وَفِي رِوَايَةٍ: أَوْ أَنْ يُكْتَبَ عَلَيْهِ، أَوْ يُزَادَ عَلَيْهِ. (م,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: അതിന്റെ മേൽ എഴുതൽ, ഉയർത്തൽ എന്നിവ നിരേധിച്ചു. (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 433, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ تُجَصَّصَ الْقُبُورُ، وَأَنْ يُكْتَبَ عَلَيْهَا، وَأَنْ يُبْنَى عَلَيْهَا، وَأَنْ تُوطَأَ. حَسَنٌ صَحِيحٌ. (م,ت,ن,جه)', 'ജാബിർ(റ): ഖബ്റുകൾക്ക് കുമ്മായമിടുന്നതും അതിന്മേൽ എഴുതുന്നതും കെട്ടിടമുണ്ടാക്കുന്നതും ചവിട്ടപ്പെടുന്നതും നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി). (മു,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 874, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=133 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 434, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ تَقْصِيصِ الْقُبُورِ، أَوْ يُبْنَى عَلَيْهَا، أَوْ يَجْلِسَ عَلَيْهَا أَحَدٌ. (ن)', 'ജാബിർ(റ): ഖബ്റിൽ കുമ്മായമിടുക, അതിൽ കെട്ടിടം പണിയൽ, അതിലിരിക്കുക എന്നിവയൊക്കെ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 874, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=133 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 435, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِحَائِطٍ مِنْ حِيطَانِ مَكَّةَ أَوِ الْمَدِينَةِ، سَمِعَ صَوْتَ إِنْسَانَيْنِ يُعَذَّبَانِ فِي قُبُورِهِمَا، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يُعَذَّبَانِ وَمَا يُعَذَّبَانِ فِي كَبِيرٍ". ثُمَّ قَالَ: بَلَى، كَانَ أَحَدُهُمَا لَا يَسْتَبْرِئُ مِنْ بَوْلِهِ، وَكَانَ الْآخَرُ يَمْشِي بِالنَّمِيمَةِ". ثُمَّ دَعَا بِجَرِيدَةٍ فَكَسَرَهَا كِسْرَتَيْنِ، فَوَضَعَ عَلَى كُلِّ قَبْرٍ مِنْهُمَا كِسْرَةً، فَقِيلَ لَهُ: يَا رَسُولَ اللهِ، لِمَ فَعَلْتَ هَذَا؟ قَالَ: "لَعَلَّهُ أَنْ يُخَفَّفَ عَنْهُمَا مَا لَمْ يَيْبَسَا". أَوْ: إِلَى أَنْ يَيْبَسَا". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) മദീനയിലേയോ മക്കയിലേയോ ഒരു മതിലിനടുത്തുകൂടെ നടന്നുപോയി. അപ്പോൾ രണ്ട് പേർ ഖബ്റിൽ ശിക്ഷിക്കപ്പെടുന്ന ശബ്ദം കേട്ടു. നബി(സ) പറഞ്ഞു: "അവർ രണ്ടുപേരും ശിക്ഷിക്കപ്പെടുന്നുണ്ട്. വലിയ കാര്യത്തിനൊന്നുമല്ല ശിക്ഷിക്കപ്പെടുന്നത്. ശേഷം പറഞ്ഞു: അതെ, അവരിലൊരാൾ മൂത്രമൊഴിച്ചാൽ ശുദ്ധി ചെയ്യാറുണ്ടായിരുന്നില്ല. മറ്റേ ആൾ ഏഷണിയുമായി നടക്കാറായിരുന്നു." പിന്നെ നബി(സ) ഒരു മട്ടലെടുത്ത് രണ്ട് കഷ്ണമാക്കി രണ്ടു ഖബ്റിന്മേലും ഓരോ കഷ്ണം വീതം വെച്ചു. അപ്പോൾ നബി(സ) ചോദിക്കപ്പെട്ടു. അല്ലാഹുവിന്റെ ദൂതരേ! എന്തിനാണ് താങ്കൾ ഇപ്രകാരം ചെയ്തത്? നബി(സ) പറഞ്ഞു: "ആ മട്ടൽ ഉണങ്ങുന്നത് വരെ അവരുടെ ശിക്ഷ ലഘൂകരിക്കപ്പെട്ടേക്കാം." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 875, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=134 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 436, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا إِنَّ أَحَدَكُمْ إِذَا مَاتَ عُرِضَ عَلَيْهِ مَقْعَدُهُ بِالْغَدَاةِ وَالْعَشِيِّ: إِنْ كَانَ مِنْ أَهْلِ الْجَنَّةِ فَمِنْ أَهْلِ الْجَنَّةِ، وَإِنْ كَانَ مِنْ أَهْلِ النَّارِ فَمِنْ أَهْلِ النَّارِ، حَتَّى يَبْعَثَهُ اللهُ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ". وَفِي رِوَايَةٍ: "يُعْرَضُ عَلَى أَحَدِكُمْ إِذَا مَاتَ مَقْعَدُهُ مِنَ الْغَدَاةِ وَالْعَشِيِّ: فَإِنْ كَانَ مِنْ أَهْلِ النَّارِ فَمِنْ أَهْلِ النَّارِ، قِيلَ: هَذَا مَقْعَدُكَ حَتَّى يَبْعَثَكَ اللهُ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ". وَفِي رِوَايَةٍ: "إِذَا مَاتَ أَحَدُكُمْ عُرِضَ عَلَى مَقْعَدِهِ بِالْغَدَاةِ وَالْعَشِيِّ: إِنْ كَانَ مِنْ أَهْلِ الْجَنَّةِ فَمِنْ أَهْلِ الْجَنَّةِ، وَإِنْ كَانَ مِنْ أَهْلِ النَّارِ فَمِنْ أَهْلِ النَّارِ. فَيُقَالُ: هَذَا مَقْعَدُكَ حَتَّى يَبْعَثَكَ اللهُ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ". (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ മരിച്ചാൽ അവന്റെ സ്ഥാനം അവന് രാവിലെയും വൈകുന്നേരവും കാണിക്കപ്പെടും. ഗ്വർഗ്ഗാവകാശിക്ക് സ്വർഗ്ഗത്തിൽ നിന്നും നരകാവകാശിക്ക് നരകത്തിൽ നിന്നുമായിരിക്കുമത്. അന്ത്യനാൾ വരെ അത് തുടരും." മറ്റൊരു റിപ്പോർട്ടിൽ: "നിങ്ങളിൽ ഒരാൾ മരിച്ചാൽ പ്രഭാതത്തിലും പ്രദോഷത്തിലും അവന്റെ സ്ഥാനം കാണിക്കപ്പെടും. അവൻ നരകാവകാശിയെങ്കിൽ അത് നരകത്തിൽ നിന്നായിയിരിക്കും. അവനോട് പറയപ്പെടും അല്ലാഹു അന്ത്യനാളിൽ നിന്നെ നിയോഗിക്കുന്നതുവരെ നിന്റെ സ്ഥനമാണിത്." മറ്റൊരു റിപ്പോർട്ടിൽ: "നിങ്ങളിലൊരുത്തൻ മരിച്ചാൽ രാവിലെയും വൈകുന്നേരവും അവന്റെ സ്ഥാനം കാണിക്കപ്പെടും. അവൻ സ്വർഗ്ഗാവകാശിയെങ്കിൽ സ്വർഗ്ഗത്തിൽ നിന്നും നരകാവകാശിയെങ്കിൽ നരകത്തിൽ നിന്നും. അല്ലാഹു നിന്നെ അന്ത്യനാളിൽ എഴുന്നേൽപ്പിക്കും വരെ ഇതായിരിക്കും നിന്റെ സ്ഥാനം എന്ന് അവനോട് പറയപ്പെടും." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 875, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=134 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=436), 1, 'وَفِي رِوَايَةٍ: "يُعْرَضُ عَلَى أَحَدِكُمْ إِذَا مَاتَ مَقْعَدُهُ مِنَ الْغَدَاةِ وَالْعَشِيِّ: فَإِنْ كَانَ مِنْ أَهْلِ النَّارِ فَمِنْ أَهْلِ النَّارِ، قِيلَ: هَذَا مَقْعَدُكَ حَتَّى يَبْعَثَكَ اللهُ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ".', 'മറ്റൊരു നിവേദനിൽ: "നിങ്ങളിൽ ഒരാൾ മരിച്ചാൽ പ്രഭാതത്തിലും പ്രദോഷത്തിലും അവന്റെ സ്ഥാനം കാണിക്കപ്പെടും. അവൻ നരകാവകാശിയെങ്കിൽ അത് നരകത്തിൽ നിന്നായിയിരിക്കും. അവനോട് പറയപ്പെടും അല്ലാഹു അന്ത്യനാളിൽ നിന്നെ നിയോഗിക്കുന്നതുവരെ നിന്റെ സ്ഥനമാണിത്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=436), 2, 'وَفِي رِوَايَةٍ: "إِذَا مَاتَ أَحَدُكُمْ عُرِضَ عَلَى مَقْعَدِهِ بِالْغَدَاةِ وَالْعَشِيِّ: إِنْ كَانَ مِنْ أَهْلِ الْجَنَّةِ فَمِنْ أَهْلِ الْجَنَّةِ، وَإِنْ كَانَ مِنْ أَهْلِ النَّارِ فَمِنْ أَهْلِ النَّارِ. فَيُقَالُ: هَذَا مَقْعَدُكَ حَتَّى يَبْعَثَكَ اللهُ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ". (ن)', 'മറ്റൊരു നിവേദനിൽ: "നിങ്ങളിലൊരുത്തൻ മരിച്ചാൽ രാവിലെയും വൈകുന്നേരവും അവന്റെ സ്ഥാനം കാണിക്കപ്പെടും. അവൻ സ്വർഗ്ഗാവകാശിയെങ്കിൽ സ്വർഗ്ഗത്തിൽ നിന്നും നരകാവകാശിയെങ്കിൽ നരകത്തിൽ നിന്നും. അല്ലാഹു നിന്നെ അന്ത്യനാളിൽ എഴുന്നേൽപ്പിക്കും വരെ ഇതായിരിക്കും നിന്റെ സ്ഥാനം എന്ന് അവനോട് പറയപ്പെടും." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 437, 'عَنْ عَبْدِ اللهِ بْنِ ثَعْلَبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِقَتْلَى أُحُدٍ: "زَمِّلُوهُمْ بِدِمَائِهِمْ، فَإِنَّهُ لَيْسَ كَلْمٌ يُكْلَمُ فِي اللهِ إِلَّا يَأْتِي يَوْمَ الْقِيَامَةِ يَدْمَى، لَوْنُهُ لَوْنُ الدَّمِ وَرِيحُهُ رِيحُ الْمِسْكِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു സഅ്ലബ്(റ): ഉഹ്ദിൽ മരിച്ചവരെ സംബന്ധിച്ച് നബി(സ) പറഞ്ഞു: "നിങ്ങളവരെ രക്തത്തോടെ പൊതിയുക. നിങ്ങളിലാർക്കെങ്കിലും അല്ലാഹുവിന്റെ മാർഗത്തിൽ മുറിവു പറ്റിയാൽ അന്ത്യനാളിൽ രക്തം പുരണ്ടവനായികൊണ്ട് തന്നെയാണ് എഴുന്നേൽപിക്കപ്പെടുക. അവന്റെ നിറം രക്തത്തിന്റെ നിറവും വാസന കസ്തൂരിയുടെ വാസനയുമായിരിക്കും." (ന)', 'عَبْدِ اللهِ بْنِ ثَعْلَبَةَ', 'അബ്ദുല്ലാഹിബ്നു സഅ്ലബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 875, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=135 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 438, 'عَنِ الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ قَالَ: لَمَّا مَاتَ عُثْمَانُ بْنُ مَظْعُونٍ أُخْرِجَ بِجَنَازَتِهِ فَدُفِنَ، فَأَمَرَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلًا أَنْ يَأْتِيَهُ بِحَجَرٍ، فَلَمْ يَسْتَطِعْ حَمْلَهُ، فَقَامَ إِلَيْهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَحَسَرَ عَنْ ذِرَاعَيْهِ، قَالَ الْمُطَّلِبُ: قَالَ الَّذِي يُخْبِرُنِي ذَلِكَ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: كَأَنِّي أَنْظُرُ إِلَى بَيَاضِ ذِرَاعَيْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ حَسَرَ عَنْهُمَا، ثُمَّ حَمَلَهَا فَوَضَعَهَا عِنْدَ رَأْسِهِ، وَقَالَ: "أَتَعَلَّمُ بِهَا قَبْرَ أَخِي، وَأَدْفِنُ إِلَيْهِ مَنْ مَاتَ مِنْ أَهْلِي". (د,جه)', 'മുത്വലിബ്നു അബിവിദാഅഃ(റ): ഉസ്മാനുബ്നു മള്ഊൻ(റ) മരണപ്പെട്ടപ്പോൾ അദ്ദേഹത്തിന്റെ ജനാസ മറമാടപ്പെട്ടു. അപ്പോൾ നബി(സ) ഒരാളോട് ഒരു കല്ല് കൊണ്ട് വരാൻ ആവശ്യപ്പെട്ടു. അദ്ദേഹത്തിന് അത് എടുത്ത് ഉയർത്താൻ കഴിഞ്ഞില്ല. അപ്പോൾ നബി(സ) അങ്ങോട്ട് വന്നു. തന്റെ മുഴം കൈയിൽ നിന്ന് വസ്ത്രം നീക്കി, മുത്വലിബ് പറയുന്നു: എന്നോട് ഇത് പറഞ്ഞു തന്ന ആൾ പറഞ്ഞു: നബി(സ) വസ്ത്രം നീക്കിയപ്പോൾ അവിടുത്തെ കൈയിന്റെ വെളുപ്പ് ഞാൻ കാണുന്ന പോലെയുണ്ടായിരുന്നു. പിന്നെ നബി(സ) ആ കല്ലെടുത്ത് ഖബറിന്റെ തലയുടെ അടുത്ത് വെച്ചു. പിന്നെ നബി(സ) പറഞ്ഞു: "ഇതുകൊണ്ട് ഞാൻ എന്റെ സഹോദരന്റെ ഖബർ മനസ്സിലാക്കും. എന്റെ കുടുംബത്തിൽ മരിച്ചവരെ ഞാൻ അതിലേക്ക് മറമാടും." (ദ,ജ)', 'الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ قَالَ', 'മുത്വലിബ്നു അബിവിദാഅഃ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 876, 876, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=136 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 439, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا فِي جَنَازَةٍ فِي بَقِيعِ الْغَرْقَدِ فَأَتَانَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَعَدَ وَقَعَدْنَا حَوْلَهُ وَمَعَهُ مِخْصَرَةٌ فَنَكَّسَ، فَجَعَلَ يَنْكُتُ بِمِخْصَرَتِهِ، ثُمَّ قَالَ: "مَا مِنْكُمْ مِنْ أَحَدٍ مَا مِنْ نَفْسٍ مَنْفُوسَةٍ إِلَّا كُتِبَ مَكَانُهَا مِنَ الْجَنَّةِ وَالنَّارِ، وَإِلَّا قَدْ كُتِبَ شَقِيَّةً أَوْ سَعِيدَةً". فَقَالَ رَجُلٌ: يَا رَسُولَ اللهِ، أَفَلَا نَتَّكِلُ عَلَى كِتَابِنَا وَنَدَعُ الْعَمَلَ، فَمَنْ كَانَ مِنَّا مِنْ أَهْلِ السَّعَادَةِ فَسَيَصِيرُ إِلَى عَمَلِ أَهْلِ السَّعَادَةِ، وَأَمَّا مَنْ كَانَ مِنَّا مِنْ أَهْلِ الشَّقَاوَةِ فَسَيَصِيرُ إِلَى عَمَلِ أَهْلِ الشَّقَاوَةِ؟ قَالَ: "أَمَّا أَهْلُ السَّعَادَةِ فَيُيَسَّرُونَ لِعَمَلِ السَّعَادَةِ وَأَمَّا أَهْلُ الشَّقَاوَةِ فَيُيَسَّرُونَ لِعَمَلِ الشَّقَاوَةِ". ثُمَّ قَرَأَ {فَأَمَّا مَنْ أَعْطَى وَاتَّقَى} الْآيَةَ. (خ)', 'അലി(റ): ഞങ്ങൾ ബഖീഇൽ ഒരു മയ്യിത്ത് സംസ്കരണവേളയിലായിരിക്കെ നബി(സ) ഞങ്ങളുടെ അടുത്ത് വന്നു. അവിടുന്ന് ഇരുന്നു. ചുറ്റും ഞങ്ങളും ഇരുന്നു. നബി(സ)യുടെ കൂടെ ഒരു വടിയുണ്ടായിരുന്നു. അതിന്റെ കീഴ് ഭാഗം മുകളിലാക്കി. പിന്നെ തന്റെ വടി കൊണ്ട് നിലത്ത് ചികയാൻ തുടങ്ങി. പിന്നെ പറഞ്ഞു: "നിങ്ങളിൽ ഓരോരുത്തർക്കും സ്വർഗ്ഗത്തിലും നരകത്തിലും ഉള്ള സ്ഥാനം രേഖപ്പെടുത്തപ്പെട്ടിരിക്കുന്നു. അവൻ സൗഭാഗ്യവനോ നിർഭാഗ്യവനോ എന്നും രേഖപ്പെടുത്തിയിരിക്കുന്നു." അപ്പോൾ ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞങ്ങളുടെ കിതാബിനെ ഞങ്ങൾ അവലംബിക്കുകയും ഞങ്ങൾ കർമ്മം ചെയ്യാതിരിക്കുകയും ചെയ്യട്ടെയോ? സൗഭാഗ്യവാന്മാർ അവരുടെ കർമ്മവും നിർഭാഗ്യർ അവരുടെ കർമ്മവും ചെയ്യും? നബി(സ) പറഞ്ഞു: "സൗഭാഗ്യവാന്മാർക്ക് തങ്ങളുടെ കർമ്മം ചെയ്യാൻ എളുപ്പമുണ്ടാകും.നിർഭാഗ്യവാന്മാർക്ക് തങ്ങളുടെ കർമ്മം ചെയ്യാനും എളുപ്പമാകും." പിന്നീട് ''ആരെങ്കിലും നൽകുകയും തഖ്വ ചെയ്യുകയും ചെയ്താൽ'' എന്ന സൂക്തം ഓതി. (ബു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 876, 876, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=137 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 440, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أُرْسِلَ مَلَكُ الْمَوْتِ إِلَى مُوسَى عَلَيْهِمَا السَّلَامُ، فَلَمَّا جَاءَهُ صَكَّهُ، فَرَجَعَ إِلَى رَبِّهِ فَقَالَ: أَرْسَلْتَنِي إِلَى عَبْدٍ لَا يُرِيدُ الْمَوْتَ، فَرَدَّ اللَّهُ عَلَيْهِ عَيْنَهُ وَقَالَ: ارْجِعْ فَقُلْ لَهُ: يَضَعُ يَدَهُ عَلَى مَتْنِ ثَوْرٍ فَلَهُ بِكُلِّ مَا غَطَّتْ بِهِ يَدُهُ بِكُلِّ شَعْرَةٍ سَنَةٌ، قَالَ: أَيْ رَبِّ ثُمَّ مَاذَا؟ قَالَ: ثُمَّ الْمَوْتُ، قَالَ: فَالْآنَ، فَسَأَلَ اللَّهَ أَنْ يُدْنِيَهُ مِنَ الْأَرْضِ الْمُقَدَّسَةِ رَمْيَةً بِحَجَرٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَلَوْ كُنْتُ ثَمَّ، لَأَرَيْتُكُمْ قَبْرَهُ إِلَى جَانِبِ الطَّرِيقِ عِنْدَ الْكَثِيبِ الْأَحْمَرِ". (خ)', 'അബൂഹുറൈറ(റ): മരണത്തിന്റെ മലക്ക് (അസ്റാഈൽ) മൂസാ(അ)യുടെ അടുക്കലേക്ക് അയക്കപ്പെട്ടു. മലക്ക് വന്നപ്പോൾ മൂസാ നബി(അ) അടിച്ചു. തുടർന്ന് മലക്ക് അല്ലാഹുവിങ്കലേക്ക് മടങ്ങിച്ചെന്ന് പറഞ്ഞു: മരിക്കാൻ ഉദ്ദേശിക്കാത്ത ഒരടിമയുടെ അടുത്തേക്കാണ് നീ എന്നെ പറഞ്ഞയച്ചത്. അല്ലാഹു മലക്കിന്റെ കണ്ണ് തിരിച്ചു നൽകിക്കൊണ്ട് പറഞ്ഞു: നീ മടങ്ങിച്ചെല്ലുക. എന്നിട്ട് അദ്ദേഹത്തോട് പറയുക: താങ്കൾ താങ്കളുടെ കൈ ഒരു കാളയുടെ മുതുകിൽ വെക്കുക. അപ്പോൾ താങ്കളുടെ കയ്യാൽ മറക്കപ്പെടുന്ന രോമം എത്രയോ അത്രയും വർഷം താങ്കൾക്കിവിടെ താമസിക്കാം. (അങ്ങനെ ചോദിച്ചപ്പോൾ) മൂസാ(അ) ചോദിച്ചു: പിന്നെ എന്താണ്? മലക്ക് പറഞ്ഞു: പിന്നെ മരണം. മൂസാ(അ) പറഞ്ഞു: എന്നാൽ മരണം ഇപ്പോൾ തന്നെ ആവട്ടെ. പരിശുദ്ധ ഭൂമികൊള്ളെ (ബൈത്തുൽ മുഖദ്ദസ്) ഒരു കല്ലെറിഞ്ഞാൽ കൊള്ളാവുന്ന ദൂരം അടുപ്പിച്ചു തരാൻ അദ്ദേഹം അല്ലാഹുവോട് പ്രാർത്ഥിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ അവിടെ ആയിരുന്നെങ്കിൽ, ചുവന്ന മണൽ കുന്നിന്റെ അടുത്തായി അദ്ദേഹത്തിന്റെ ഖബർ ഞാൻ നിങ്ങൾക്ക് കാണിച്ചു തരുമായിരുന്നു." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 441, 'عن ابن عُمَر رَضِيَ اللهُ عَنْهُمَا، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "هَذَا الذي تَحَرَّكَ لَهُ العَرْشُ، وَفُتِحَتْ لَهُ أَبْوَابُ السَّمَاءِ، وَشَهِدَهُ سَبْعُونَ أَلْفًا من الْمَلَائِكَةِ: لَقَدْ ضُمَّ ضَمَّةً ثُمَّ فُرِّجَ عَنْهُ". (ن)', 'റസൂൽ(സ)യിൽ നിന്ന് ഇബ്നുഉമർ(റ): "ഇദ്ദേഹത്തിനു വേണ്ടി അർഷ് (അല്ലാഹുവിന്റെ സിംഹാസനം) ഇളകിയിട്ടുണ്ട്. ആകാശത്തിന്റെ വാതിലുകൾ തുറക്കപ്പെട്ടിട്ടുണ്ട്. എഴുപതിനായിരം മലക്കുകൾ ഇദ്ദേഹത്തിന് സാക്ഷിയായിട്ടുണ്ട്. ആ ഖബർ ഒന്ന് കൂട്ടപ്പെടുകയും പിന്നെ വിശാലമാവുകയും ചെയ്തു." (ന)', 'ابن عُمَر', 'റസൂൽ(സ)യിൽ നിന്ന് ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=139 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 442, 'عَنْ أبي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى جِنَازَةٍ، ثُمَّ أَتَى قَبْرَ الْمَيِّتِ فَحَثَى عَلَيْه من قبل رَأسه ثَلَاثًا. (جه)', 'അബുഹുറൈറ(റ): നബി(സ) ഒരു ജനാസ നിസ്കാരം നടത്തി. പിന്നെ മയ്യിത്തിന്റെ ഖബ്റിനടുത്തു വന്ന് തല ഭാഗത്ത് നിന്ന് മൂന്ന് പ്രാവശ്യം മണ്ണ് വാരിയിട്ടു. (ജ)', 'أبي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 443, 'عَنْ أنس بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: مُرَّ بِجَنَازَةٍ فَأُثْنِيَ عَلَيْهَا خَيْرٌ، فَقَالَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَجَبَتْ وَجَبَتْ وَجَبَتْ". وَمُرَّ بِجَنَازَةٍ فَأُثْنِيَ عَلَيْهَا شَرًّا، فَقَالَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَجَبَتْ وَجَبَتْ وَجَبَتْ". فَقَالَ عُمَرُ: فِدًى لَكَ أَبِي وَأُمِّي، مُرَّ بِجَنَازَةٍ فَأُثْنِيَ عَلَيْهَا خَيْرًا، فَقُلْتَ: "وَجَبَتْ وَجَبَتْ وَجَبَتْ". وَمُرَّ بِجَنَازَةٍ فَأُثْنِيَ عَلَيْهَا شَرًّا، فَقُلْتَ: "وَجَبَتْ وَجَبَتْ وَجَبَتْ". فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَثْنَيْتُمْ عَلَيْهِ خَيْرًا وَجَبَتْ لَهُ الْجَنَّةُ، وَمَنْ أَثْنَيْتُمْ عَلَيْهِ شَرًّا وَجَبَتْ لَهُ النَّارُ. أَنْتُمْ شُهَدَاءُ اللهِ فِي الْأَرْضِ، أَنْتُمْ شُهَدَاءُ اللهِ فِي الْأَرْضِ، أَنْتُمْ شُهَدَاءُ اللهِ فِي الْأَرْضِ". (ق,ت,ن,جه)', 'അനസുബ്നുമാലിക്(റ): ഒരു ജനാസ കൊണ്ടുപോയപ്പോൾ അതിനെ കുറിച്ച് നല്ലത് പറയപ്പെട്ടു. അല്ലാഹുവിന്റെ ദൂതൻ(സ) പറഞ്ഞു: "അത് നിർബന്ധമായിരിക്കുന്നു, അത് നിർബന്ധമായിരിക്കുന്നു, അത് നിർബന്ധമായിരിക്കുന്നു (ആ പറഞ്ഞ കാര്യം അനിവാര്യമായിരിക്കുന്നു)." മറ്റൊരു ജനാസ കൊണ്ടുപോയപ്പോൾ അതിനെ കുറിച്ച് ചീത്തപറയപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "ആ കാര്യം അനിവാര്യമായി, അനിവാര്യമായി, അനിവാര്യമായി." അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: ഒരു ജനാസ കൊണ്ടുപോകുകയും അതിനെ കുറിച്ച് നല്ലത് പറയപ്പെടുകയും ചെയ്തപ്പോൾ താങ്കൾ അത് അനിവാര്യമായി എന്നും മറ്റൊരു ജനാസയെ കുറിച്ച് മോശമായത് പറഞ്ഞപ്പോൾ അതും അനിവാര്യമായി എന്നും പറഞ്ഞുവല്ലോ? അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ആരെകുറിച്ചെങ്കിലും നന്മപറഞ്ഞാൽ അവന് സ്വർഗ്ഗം അനിവാര്യമായി, നിങ്ങൾ ആരെകുറിച്ചെങ്കിലും ചീത്ത പറഞ്ഞാൽ അവന് നരകമുറപ്പായി. നിങ്ങൾ ഭൂമിയിൽ അല്ലാഹുവിന്റെ സാക്ഷികളാണ്, നിങ്ങൾ ഭൂമിയിൽ അല്ലാഹുവിന്റെ സാക്ഷികളാണ്, നിങ്ങൾ ഭൂമിയിൽ അല്ലാഹുവിന്റെ സാക്ഷികളാണ്." (ബു,മു,തു,ന,ജ)', 'أنس بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 877, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 444, 'عَنْ أبي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: مَرُّوا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِجَنَازَةٍ فَأَثْنَوْا عَلَيْهَا خَيْرًا، فَقَالَ: "وَجَبَتْ". ثُمَّ مَرُّوا بِأُخْرَى فَأَثْنَوْا عَلَيْهَا شَرًّا، فَقَالَ: "وَجَبَتْ". ثُمَّ قَالَ: "إِنَّ بَعْضَكُمْ عَلَى بَعْضٍ شُهَدَاءُ". (د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ)യുടെ അരികിലൂടെ അവർ ഒരു ജനാസ കൊണ്ടുപോയി. അവർ അതിനെ കുറിച്ച് നല്ലത് പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അത് നിർബന്ധമായിരിക്കുന്നു." പിന്നെ മറ്റൊരാളെകൊണ്ടുപോയപ്പോൾ അവർ അതിനെ കുറിച്ച് മോശമായത് പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് അനിവാര്യമായി." പിന്നെ നബി(സ) പറഞ്ഞു: "നിശ്ചയം നിങ്ങൾ പരസ്പരം സാക്ഷികളാണ്." (ദ,ന)', 'أبي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 878, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 445, 'عَنْ أبي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قِيلَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَرَأَيْتَ الرَّجُلَ يَعْمَلُ الْعَمَلَ مِنَ الْخَيْرِ وَيَحْمَدُهُ النَّاسُ عَلَيْهِ؟ قَالَ: "تِلْكَ عَاجِلُ بُشْرَى الْمُؤْمِنِ". (م)', 'അബൂദർറ്(റ): പരസ്യമായി ഒരു പ്രവർത്തനം ചെയ്യുകയും ജനങ്ങൾ അതിന് അയാളെ സ്തുതിക്കുകയും ചെയ്യുന്നു. ഇതിൽ എന്ത് അഭിപ്രായപ്പെടുന്നു എന്ന് നബി(സ) ചോദിക്കപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "അത് മുഅ്മിനിന്റെ പെട്ടെന്നുള്ള സന്തോഷമാണ്." (മു)', 'أبي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 878, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 446, 'عَنْ أبي قَتَادَةَ بْنِ رِبْعِيٍّ رَضِيَ اللهُ عَنْهُ أَنَّهُ كَانَ يُحَدِّثُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُرَّ عَلَيْهِ بِجَنَازَةٍ، فَقَالَ: "مُسْتَرِيحٌ وَمُسْتَرَاحٌ مِنْهُ". قَالُوا: يَا رَسُولَ اللهِ، مَا الْمُسْتَرِيحُ وَمَا الْمُسْتَرَاحُ مِنْهُ؟ فَقَالَ: "الْعَبْدُ الْمُؤْمِنُ يَسْتَرِيحُ مِنْ نَصَبِ الدُّنْيَا، وَالْعَبْدُ الْفَاجِرُ يَسْتَرِيحُ مِنْهُ الْعِبَادُ وَالْبِلَادُ وَالشَّجَرُ وَالدَّوَابُّ". (م,ن)', 'അബുഖതാദതിബ്നു രിബ്ഇയ്യി(റ): പ്രവാചക(സ)ന്റെ അരികിൽ കൂടി ഒരു ജനാസ കൊണ്ടുപോയപ്പോൾ "ഇവൻ മുക്തി നേടി, ഇവനിൽ നിന്നും മറ്റുള്ളവർ മുക്തി നേടി" എന്നിങ്ങനെ അവിടുന്ന് പറഞ്ഞു. അവർ പറഞ്ഞു: പ്രവാചകരേ, ''ഇവൻ മുക്തി നേടി, ഇവനിൽ നിന്നും മറ്റുള്ളവർ മുക്തി നേടി'' എന്നിങ്ങനെ അവിടുന്ന് പറഞ്ഞതിന്റെ ഉദ്ദേശ്യം എന്താണ്? തിരുമേനി(സ) പറഞ്ഞു: "സത്യവിശ്വാസിയായ അടിമ ഐഹിക പ്രാരാബ്ധങ്ങളിൽ നിന്നും മുക്തി നേടുന്നു. ദുർമാർഗ്ഗിയായ അടിമയിൽ നിന്നും മറ്റ് അടിമകളും നാടുകളും വൃക്ഷങ്ങളും ജീവജാലങ്ങളും മുക്തി നേടുന്നു." (മു,ന)', 'أبي قَتَادَةَ بْنِ رِبْعِيٍّ', 'അബുഖതാദതിബ്നു രിബ്ഇയ്യി(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 878, 879, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=142 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 447, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا جُلُوسًا عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذْ طَلَعَتْ جَنَازَةٌ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مُسْتَرِيحٌ وَمُسْتَرَاحٌ مِنْهُ: الْمُؤْمِنُ يَمُوتُ فَيَسْتَرِيحُ مِنْ أَوْصَابِ الدُّنْيَا وَنَصَبِهَا وَأَذَاهَا، وَالْفَاجِرُ يَمُوتُ فَيَسْتَرِيحُ مِنْهُ الْعِبَادُ وَالْبِلَادُ وَالشَّجَرُ وَالدَّوَابُّ". (ن)', 'അബൂഖതാദ(റ): ഞങ്ങൾ തിരുമേനി(സ)യുടെ സമീപം ഇരിക്കുന്നതിനിടയിൽ ഒരു ജനാസ (കൊണ്ടുവരുന്നതു) കണ്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇവൻ മുക്തി നേടി, ഇവനിൽ നിന്നും ഇതരർ മുക്തി നേടി, ഒരു സത്യവിശ്വാസി മരിക്കുമ്പോൾ അവൻ ഐഹിക പ്രയാസങ്ങളിൽ നിന്നും ക്ലേശങ്ങളിൽ നിന്നും വിഷമങ്ങളിൽ നിന്നും വിമുക്തി നേടുന്നു. ഒരു ദുർമാർഗ്ഗി മരിക്കുമ്പോൾ അവനിൽ നിന്ന് അടിമകളും നാടുകളും മരങ്ങളും ജീവജാലങ്ങളും വിമുക്തി നേടുന്നു." (ന)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 879, 879, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=142 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 448, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ أَحَدَكُمْ إِذَا مَاتَ عُرِضَ عَلَيْهِ مَقْعَدُهُ بِالْغَدَاةِ وَالْعَشِيِّ: إِنْ كَانَ من أَهْلِ الْجَنَّةِ فَمِنْ أَهْلِ الْجَنَّةِ، وَإِنْ كَانَ من أَهْلِ النَّارِ فَمِنْ أَهْلِ النَّارِ، يُقَالُ: هَذَا مَقْعَدُكَ حَتَّى يَبْعَثَكَ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ". (ق,ت,ن)', 'ഇബ്നുഉമർ(റ): അല്ലാഹുവിന്റെ ദൂതർ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ മരിച്ചാൽ രാവിലെയും വൈകുന്നേരവും അവന്റെ സ്ഥാനം അവന് കാണിക്കപ്പെടും. അവൻ സ്വർഗ്ഗാവകാശിയാണെങ്കിൽ അത് സ്വർഗ്ഗത്തിൽ നിന്നായിരിക്കും. അവൻ നരകാവകാശിയാണെങ്കിൽ അത് നരകത്തിൽ നിന്നായിരിക്കും. അവനോട് പറയും: അന്ത്യനാളിൽ അല്ലാഹു നിന്നെ എഴുന്നേൽപിക്കുന്നതുവരെ നിന്റെ സ്ഥാനമിതാണ്." (ബു,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','തു','ന']::text[], null, null, 879, 879, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=143 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 449, 'عَنْ أَبِي الْأَسْوَدِ الدِّيلِيِّ قَالَ: قَدِمْتُ الْمَدِينَةَ، فَجَلَسْتُ إِلَى عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ، فَمَرُّوا بِجَنَازَةٍ فَأَثْنَوْا عَلَيْهَا خَيْرًا، فَقَالَ عُمَرُ: وَجَبَتْ. فَقُلْتُ لِعُمَرَ: وَمَا وَجَبَتْ؟ قَالَ: أَقُولُ: كَمَا قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ مُسْلِمٍ يَشْهَدُ لَهُ ثَلَاثَةٌ إِلَّا وَجَبَتْ لَهُ الْجَنَّةُ". قَالَ: قلنا: وَاثْنَانِ؟ قَالَ: "وَاثْنَانِ". قَالَ: وَلَمْ نَسْأَلْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْوَاحِدِ. حَسَنٌ صَحِيحٌ. (ق,ت)', 'അബുൽ അസ്വ്ദു ദൈലി: ഞാൻ മദീനയിൽ ചെന്നു, ഉമർ ഇബ്നുൽഖതാബ്(റ)ന്റെ അടുക്കൽ ഞാൻ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരു മൃതശരീരം കൊണ്ടുപൊയി. തുടർന്ന് ജനങ്ങൾ അദ്ദേഹത്തിന്റെ നന്മകൾ പ്രകീർത്തിച്ചപ്പോൾ ഉമർ(റ) അനിവാര്യമായി എന്ന് പറഞ്ഞു. ഞാൻ ഉമറി(റ)നോട് ചോദിച്ചു. എന്താണ് അനിവാര്യമായത്? അദ്ദേഹം പറഞ്ഞു: ഞാൻ പ്രവാചകൻ(സ) പറഞ്ഞത് പോലെ പറഞ്ഞതാണ്. പ്രവാചകൻ(സ) പറഞ്ഞിട്ടുണ്ട്: "ഒരു മുസ്ലിമിന് വേണ്ടി മൂന്ന്പേർ സാക്ഷ്യം വഹിച്ചാൽ അദ്ദേഹത്തിന് സ്വർഗം ലഭിക്കുക എന്നത് അനിവാര്യമായി." അദ്ദേഹം പറയുന്നു: ഞങ്ങൾ പറഞ്ഞു: രണ്ട് പേരാണെങ്കിലോ? അവിടുന്ന് പറഞ്ഞു: "രണ്ടാളാണെങ്കിലും." ഉമർ(റ) പറഞ്ഞു: ഒരാളാണെങ്കിലോ എന്ന് ഞങ്ങൾ പ്രവോചകനോ(സ)ട് ചോദിച്ചിട്ടില്ല. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,തു)', 'أَبِي الْأَسْوَدِ الدِّيلِيِّ قَالَ', 'അബുൽ അസ്വ്ദു ദൈലി', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 879, 879, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 450, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَخَذَ الرَّايَةَ زَيْدٌ فَأُصِيبَ، ثُمَّ أَخَذَهَا جَعْفَرٌ فَأُصِيبَ، ثُمَّ أَخَذَهَا عَبْدُاللَّهِ بْنُ رَوَاحَةَ فَأُصِيبَ، وَإِنَّ عَيْنِي رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَتَذْرِفَانِ، ثُمَّ أَخَذَهَا خَالِدُ بْنُ الْوَلِيدِ مِنْ غَيْرِ إِمْرَةٍ فَفُتِحَ لَهُ". (خ)', 'അനസ് ഇബനുമാലിക്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "സൈദ് പതാക വഹിച്ചു അദ്ദേഹത്തിന് ആപത്ത് പിണഞ്ഞു. പിന്നീട് ജഅ്ഫർ പതാക വഹിച്ചു. അദ്ദേഹത്തിനും ആപത്ത് പിണഞ്ഞു. പിന്നീട് അബ്ദുല്ലാഹിബ്നു റവാഹ വഹിച്ചു. അദ്ദേഹത്തിനും ആപത്ത് പിണഞ്ഞു. പ്രവാചകന്റെ(സ) രണ്ട് കണ്ണുകളും ബാഷ്പം പൊഴിക്കുന്നുണ്ടായിരുന്നു. പിന്നീട് ഖാലിദുബ്നു വലീദ് ഒരു ഇടർച്ചയുമില്ലാതെ പതാക വഹിച്ചു. അദ്ദേഹത്തിന് വിജയം ലഭിച്ചു." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ് ഇബനുമാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 880, 880, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 451, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: مَرُّوا بِجَنَازَةٍ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَثْنَوْا عَلَيْهَا خَيْرًا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَجَبَتْ". ثُمَّ مَرُّوا بِجَنَازَةٍ أُخْرَى فَأَثْنَوْا عَلَيْهَا شَرًّا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَجَبَتْ". قَالُوا: يَا رَسُولَ اللهِ، قَوْلُكَ الْأُولَى وَالْأُخْرَى: "وَجَبَتْ". فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمَلَائِكَةُ شُهَدَاءُ اللهِ فِي السَّمَاءِ، وَأَنْتُمْ شُهَدَاءُ اللهِ فِي الْأَرْضِ". (ن)', 'അബൂഹുറൈറ(റ): പ്രവാചകന്റെ(സ) അടുക്കൽ കൂടി ഒരു ജനാസ കൊണ്ടുപോയപ്പോൾ ജനങ്ങൾ അതിന്റെ നന്മകൾ പ്രകീർത്തിച്ചു. അപ്പോൾ പ്രാചകൻ(സ) "അനിവാര്യമായി" എന്ന് പറഞ്ഞു. മറ്റൊരു ജനാസ കൊണ്ടുപോയപ്പോൾ അവർ അതിന്റെ തിന്മകൾ പ്രകീർത്തിച്ചു. അപ്പോഴും പ്രവാചകൻ(സ) പറഞ്ഞു: "അനിവാര്യമായി". അനുചരന്മാർ ചോദിച്ചു: റസൂലേ! "അനിവാര്യമായി" എന്ന് അവിടുന്ന് ഒന്നാം പ്രാവശ്യവും രണ്ടാം പ്രാവശ്യവും പറഞ്ഞതിന്റെ പൊരുൾ എന്താണ്. തിരുമേനി(സ) പറഞ്ഞു: "മലക്കുകൾ ആകാശത്തിൽ അല്ലാഹുവിന്റെ സാക്ഷികളാണ്. നിങ്ങൾ ഭൂമിയിൽ അല്ലാഹുവിന്റെ സാക്ഷികളാണ്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 880, 880, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 452, 'عَنْ أَبِي الْأَسْوَدِ الدِّيلِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ الْمَدِينَةَ، فَجَلَسْتُ إِلَى عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ، فَمُرَّ بِجَنَازَةٍ فَأُثْنِيَ عَلَى صَاحِبِهَا خَيْرًا، فَقَالَ عُمَرُ: وَجَبَتْ. ثُمَّ مُرَّ بِأُخْرَى فَأُثْنِيَ عَلَى صَاحِبِهَا شَرًّا، فَقَالَ عُمَرُ: وَجَبَتْ. فَقُلْتُ: وَمَا وَجَبَتْ يَا أَمِيرَ الْمُؤْمِنِينَ؟ قَالَ: قُلْتُ كَمَا قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَيُّمَا مُسْلِمٍ شَهِدَ لَهُ أَرْبَعَةٌ قَالُوا خَيْرًا أَدْخَلَهُ اللهُ الْجَنَّةَ". قُلْنَا: أَوْ ثَلَاثَةٌ؟ قَالَ: "أَوْ ثَلَاثَةٌ". قُلْنَا: أَوِ اثْنَانِ؟ قَالَ: "أَوِ اثْنَانِ". (خ,ن)', 'അബുൽ അസ്വദുദ്ദയിലി(റ): ഞാൻ മദീനയിൽ ചെന്നു ഉമറുബ്നു ഖതാബി(റ)ന്റെ അടുക്കൽ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരു ജനാസ കൊണ്ടുപോകുകയും അദ്ദേഹത്തിന്റെ നന്മകൾ പുകഴ്ത്തപ്പെടുകയും ചെയ്തു. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അത് അനിവാര്യമായി. പിന്നീട് മറ്റൊരു ജനാസ കൊണ്ടുപോയപ്പോൾ അതിന്റെ തിന്മകൾ അപകീർത്തിക്കപ്പെടുകയുണ്ടായി. ഉമർ(റ) പറഞ്ഞു: അനിവാര്യമായി. ഞാൻ ചോദിച്ചു: അമീറുൽ മുഅ്മിനീൻ എന്താണ് അനിവാര്യമായത്? അദ്ദേഹം പറഞ്ഞു: ഞാൻ പ്രവാചകൻ(സ) പറഞ്ഞത് പോലെ പറഞ്ഞതാണ്. "വല്ല മുസ്ലിമിനും നാല് പേർ നല്ലത് പറഞ്ഞ് സാക്ഷ്യംവഹിക്കുന്നപക്ഷം അദ്ദേഹത്തെ സ്വർഗത്തിൽ പ്രവേശിപ്പിക്കുന്നതാണ്." ഞങ്ങൾ ചോദിച്ചു: മൂന്ന് പേരാണെങ്കിലോ? നബി(സ) പറഞ്ഞു: "അല്ലെങ്കിൽ മൂന്ന്പേർ." ഞങ്ങൾ ചോദിച്ചു: രണ്ട് പേരാണെങ്കിലോ? നിബി(സ) പറഞ്ഞു: "അല്ലെങ്കിൽ രണ്ട് പേർ." (ബു,ന)', 'أَبِي الْأَسْوَدِ الدِّيلِيِّ', 'അബുൽ അസ്വദുദ്ദയിലി(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 880, 880, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 453, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اذْكُرُوا مَحَاسِنَ مَوْتَاكُمْ، وَكُفُّوا عَنْ مَسَاوِيهِمْ". (ت,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ മരണപ്പെട്ടവരുടെ നന്മകൾ പറയുക. അവരുടെ ദൂഷ്യതകൾ അടക്കിവെക്കുക." (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 881, 881, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=145 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 454, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: ذُكِرَ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ هَالِكٌ بِسُوءٍ، فَقَالَ: "لَا تَذْكُرُوا هَلْكَاكُمْ إِلَّا بِخَيْرٍ". (ن)', 'ആഇശ(റ): നബി(സ)യുടെ അടുത്ത് ഒരു പരേതനെക്കുറിച്ച് മോശമായത് പറയപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിങ്ങളിൽ നിന്ന് മരിച്ചവരെ നന്മ കൊണ്ടല്ലാതെ സ്മരിക്കരുത്." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 881, 881, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=145 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 455, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَسُبُّوا الْأَمْوَاتَ، فَإِنَّهُمْ قَدْ أَفْضَوْا إِلَى مَا قَدَّمُوا". (خ,ن)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ മരിച്ചവരെ ചീത്ത പറയരുത്. കാരണം അവർ മുമ്പ് ചെയ്തതിൽ എത്തിയിരിക്കുന്നു." (ബു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 881, 881, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 456, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَتْبَعُ الْمَيِّتَ ثَلَاثَةٌ: أَهْلُهُ وَمَالُهُ وَعَمَلُهُ، فَيَرْجِعُ اثْنَانِ: أَهْلُهُ وَمَالُهُ، وَيَبْقَى وَاحِدٌ عَمَلُهُ". (ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "മയ്യിത്തിനെ മൂന്ന് കാര്യങ്ങൾ പിന്തുടരും. അവന്റെ കുടുംബം, സമ്പത്ത്, പ്രവർത്തനങ്ങൾ എന്നിവയാണവ. അതിൽ രണ്ടെണ്ണം അഥവാ കുടുംബം, ധനം എന്നിവ മടങ്ങും. ഒന്നു ബാക്കിയാവും. അവന്റെ പ്രവർത്തനങ്ങളാണത്." (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 881, 881, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 457, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لِلْمُؤْمن عَلَى الْمُؤْمن ستٌّ خصال: يَعُودُهُ إِذَا مَرِضَ، وَيَشْهَدُهُ إِذَا مَاتَ، وَيُجِيبُهُ إِذَا دَعَاهُ، وَيُسَلِّمُ عَلَيْهِ إِذَا لَقِيَهُ، وَيُشَمِّتُهُ إِذَا عَطَسَ، وَيَنْصَحُ لَهُ إِذَا غَابَ أَوْ شَهِدَ". (ن)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു വിശ്വാസിക്ക് മറ്റൊരു വിശ്വാസിയോട് ആറ് കടമകളുണ്ട്. അവൻ രോഗിയായാൽ സന്ദർശിക്കുക, മരിച്ചാൽ ശേഷക്രിയയിൽ പങ്കെടുക്കുക, ക്ഷണിച്ചാൽ സ്വീകരിക്കുക, കണ്ടാൽ സലാം പറയുക, തുമ്മിയാൽ അനുഗ്രഹത്തിനായി പ്രാർത്ഥിക്കുക, അവൻ ഉള്ളപ്പോഴും ഇല്ലാത്തപ്പോഴും ഗുണകാംക്ഷ പുലർത്തുക." (ന)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 881, 881, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 458, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ أَوْلَادِ الْمُشْرِكِينَ؟ فَقَالَ: "خَلَقَهُمُ اللهُ حِينَ خَلَقَهُمْ، وَهُوَ يَعْلَمُ بِمَا كَانُوا عَامِلِينَ". وَفِي رِوَايَةٍ: سُئِلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَرَارِيِّ الْمُشْرِكِينَ؟ فَقَالَ: "اللهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): മുശ്രിക്കുകളുടെ സന്താനങ്ങളെകുറിച്ച് നബി(സ) ചോദിക്കപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവർ ചെയ്യുന്നതിനെ കുറിച്ച് ഏറ്റവും അറിയുന്നവനായിട്ടാണ് അല്ലാഹു അവരെ സൃഷ്ടിച്ചപ്പോൾ സൃഷ്ടിച്ചത്." മറ്റൊരു റിപ്പോർട്ടിൽ: മുശ്രിക്കുകളുടെ സന്താനങ്ങളെകുറിച്ച് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവർ ചെയ്യുന്നതിനെ കുറിച്ച് ഏറ്റവും അറിയുന്നവൻ അല്ലാഹുവാണ്." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 881, 882, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=147 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=458), 1, 'وَفِي رِوَايَةٍ: سُئِلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَرَارِيِّ الْمُشْرِكِينَ؟ فَقَالَ: "اللهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ". (ن)', 'മറ്റൊരു നിവേദനിൽ: മുശ്രിക്കുകളുടെ സന്താനങ്ങളെകുറിച്ച് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവർ ചെയ്യുന്നതിനെ കുറിച്ച് ഏറ്റവും അറിയുന്നവൻ അല്ലാഹുവാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 459, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ أَوْلَادِ الْمُشْرِكِينَ فَقَالَ: "اللهُ إِذْ خَلَقَهُمْ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): മുശ്രിക്കുകളുടെ സന്താനങ്ങളെ കുറിച്ച് നബി(സ) ചോദിക്കപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹു അവരെ സൃഷ്ടിച്ച സ്ഥിതിക്ക് അവനാണ് അവരുടെ പ്രവർത്തനങ്ങളെ കുറിച്ച് അറിയുന്നവൻ." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 882, 882, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=147 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 460, 'عَنْ سَمُرَةَ بْنِ جُنْدَب رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى صَلَاةً أَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ: "مَنْ رَأَى مِنْكُمُ اللَّيْلَةَ رُؤْيَا؟" فَإِنْ رَأَى أَحَدٌ قَصَّهَا فَيَقُولُ: "مَا شَاءَ اللهُ". فَسَأَلَنَا يَوْمًا فَقَالَ: هَلْ رَأَى أَحَدٌ مِنْكُمْ رُؤْيَا؟ فَقُلْنَا: لَا، قَالَ: "لَكِنِّي رَأَيْتُ اللَّيْلَةَ رَجُلَيْنِ أَتَيَانِي فَأَخَذَا بِيَدِي فَأَخْرَجَانِي إِلَى الْأَرْضِ الْمُقَدَّسَةِ، فَإِذَا رَجُلٌ جَالِسٌ وَرَجُلٌ قَائِمٌ بِيَدِهِ كَلُّوبٌ مِنْ حَدِيدٍ يُدْخِلُهُ فِي شِدْقِهِ حَتَّى يَبْلُغَ قَفَاهُ ثُمَّ يَفْعَلُ بِشِدْقِهِ الْآخَرِ مِثْلَ ذَلِكَ وَيَلْتَئِمُ شِدْقُهُ هَذَا فَيَعُودُ فَيَصْنَعُ مِثْلَهُ، قُلْتُ: مَا هَذَا؟ قَالَا: انْطَلِقْ، فَانْطَلَقْنَا حَتَّى أَتَيْنَا عَلَى رَجُلٍ مُضْطَجِعٍ عَلَى قَفَاهُ وَرَجُلٌ قَائِمٌ عَلَى رَأْسِهِ بِفِهْرٍ أَوْ صَخْرَةٍ فَيَشْدَخُ بِهِ رَأْسَهُ فَإِذَا ضَرَبَهُ تَدَهْدَهَ فَانْطَلَقَ إِلَيْهِ لِيَأْخُذَهُ فَلَا يَرْجِعُ إِلَى هَذَا حَتَّى يَلْتَئِمَ رَأْسُهُ وَعَادَ رَأْسُهُ كَمَا هُوَ فَعَادَ إِلَيْهِ فَضَرَبَهُ، قُلْتُ: مَنْ هَذَا؟ قَالَا: انْطَلِقْ فَانْطَلَقْنَا إِلَى ثَقْبٍ مِثْلِ التَّنُّورِ، أَعْلَاهُ ضَيِّقٌ وَأَسْفَلُهُ وَاسِعٌ، يَتَوَقَّدُ تَحْتَهُ نَارًا فَإِذَا اقْتَرَبَ ارْتَفَعُوا حَتَّى كَادَ أَنْ يَخْرُجُوا فَإِذَا خَمَدَتْ رَجَعُوا فِيهَا، وَفِيهَا رِجَالٌ وَنِسَاءٌ عُرَاةٌ، فَقُلْتُ: مَنْ هَذَا؟ قَالَا: انْطَلِقْ، فَانْطَلَقْنَا حَتَّى أَتَيْنَا عَلَى نَهَرٍ مِنْ دَمٍ فِيهِ رَجُلٌ قَائِمٌ عَلَى وَسَطِ النَّهْرِ وَعَلَى شَطِّ النَّهْرِ رَجُلٌ بَيْنَ يَدَيْهِ حِجَارَةٌ، فَأَقْبَلَ الرَّجُلُ الَّذِي فِي النَّهْرِ فَإِذَا أَرَادَ أَنْ يَخْرُجَ رَمَى الرَّجُلُ بِحَجَرٍ فِي فِيهِ فَرَدَّهُ حَيْثُ كَانَ، فَجَعَلَ كُلَّمَا جَاءَ لِيَخْرُجَ رَمَى فِي فِيهِ بِحَجَرٍ فَيَرْجِعُ كَمَا كَانَ، فَقُلْتُ: مَا هَذَا؟ قَالَا: انْطَلِقْ، فَانْطَلَقْنَا حَتَّى انْتَهَيْنَا إِلَى رَوْضَةٍ خَضْرَاءَ فِيهَا شَجَرَةٌ عَظِيمَةٌ، وَفِي أَصْلِهَا شَيْخٌ وَصِبْيَانٌ وَإِذَا رَجُلٌ قَرِيبٌ مِنَ الشَّجَرَةِ بَيْنَ يَدَيْهِ نَارٌ يُوقِدُهَا فَصَعِدَا بِي فِي الشَّجَرَةِ وَأَدْخَلَانِي دَارًا لَمْ أَرَ قَطُّ أَحْسَنَ مِنْهَا، فِيهَا رِجَالٌ شُيُوخٌ وَشَبَابٌ وَنِسَاءٌ وَصِبْيَانٌ، ثُمَّ أَخْرَجَانِي مِنْهَا فَصَعِدَا بِي الشَّجَرَةَ فَأَدْخَلَانِي دَارًا، هِيَ أَحْسَنُ وَأَفْضَلُ مِنْهَا، فِيهَا شُيُوخٌ وَشَبَابٌ، قُلْتُ: طَوَّفْتُمَانِي اللَّيْلَةَ فَأَخْبِرَانِي عَمَّا رَأَيْتُ قَالَا: نَعَمْ، أَمَّا الَّذِي رَأَيْتَهُ يُشَقُّ شِدْقُهُ فَكَذَّابٌ يُحَدِّثُ بِالْكَذْبَةِ، فَتُحْمَلُ عَنْهُ حَتَّى تَبْلُغَ الْآفَاقَ فَيُصْنَعُ بِهِ إِلَى يَوْمِ الْقِيَامَةِ، وَالَّذِي رَأَيْتَهُ يُشْدَخُ رَأْسُهُ فَرَجُلٌ عَلَّمَهُ اللهُ الْقُرْآنَ، فَنَامَ عَنْهُ بِاللَّيْلِ، وَلَمْ يَعْمَلْ فِيهِ بِالنَّهَارِ، يُفْعَلُ بِهِ إِلَى يَوْمِ الْقِيَامَةِ، وَالَّذِي رَأَيْتَهُ فِي الثَّقْبِ فَهُمُ الزُّنَاةُ، وَالَّذِي رَأَيْتَهُ فِي النَّهْرِ آكِلُوا الرِّبَا، وَالشَّيْخُ فِي أَصْلِ الشَّجَرَةِ إِبْرَاهِيمُ عَلَيْهِ السَّلَامُ وَالصِّبْيَانُ حَوْلَهُ فَأَوْلَادُ النَّاسِ، وَالَّذِي يُوقِدُ النَّارَ مَالِكٌ خَازِنُ النَّارِ، وَالدَّارُ الْأُولَى الَّتِي دَخَلْتَ دَارُ عَامَّةِ الْمُؤْمِنِينَ، وَأَمَّا هَذِهِ الدَّارُ فَدَارُ الشُّهَدَاءِ، وَأَنَا جِبْرِيلُ وَهَذَا مِيكَائِيلُ، فَارْفَعْ رَأْسَكَ، فَرَفَعْتُ رَأْسِي فَإِذَا فَوْقِي مِثْلُ السَّحَابِ قَالَا: ذَاكَ مَنْزِلُكَ قُلْتُ: دَعَانِي أَدْخُلْ مَنْزِلِي، قَالَا: إِنَّهُ بَقِيَ لَكَ عُمُرٌ لَمْ تَسْتَكْمِلْهُ، فَلَوِ اسْتَكْمَلْتَ أَتَيْتَ مَنْزِلَكَ". (خ)', 'സമുറതുബ്നു ജുൻദുബ്(റ): നബി(സ) നിസ്കാരം കഴിഞ്ഞാൽ ഞങ്ങളുടെ അടുത്ത് വന്ന് ചോദിക്കും: "കഴിഞ്ഞ രാത്രി നിങ്ങളിലാരെങ്കിലും സ്വപ്നം കണ്ടുവോ?" ആരെങ്കിലും കണ്ടിട്ടുണ്ടെങ്കിൽ അത് വിവരിക്കും. അപ്പോൾ റസൂൽ, "മാശാ അല്ലാഹ്!" എന്ന് പറയും. അങ്ങനെ ഒരു ദിവസം നിങ്ങളാരെങ്കിലും സ്വപ്നം കണ്ടോ? എന്ന് ചോദിച്ചു. ഞങ്ങൾ ഇല്ല എന്ന് പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "പക്ഷെ, ഞാൻ ഇന്നലെ രാത്രി എന്റെ അടുത്ത് രണ്ട് പേർ വന്നത് സ്വപ്നത്തിൽ കണ്ടു. അവർ എന്റെ ഇരു കൈകളും പിടിച്ച് പരിശുദ്ധ ഭൂമിയിലേക്ക് കൊണ്ടു പോയി. അപ്പോൾ നിൽക്കുന്ന ഒരാളെയും ഇരിക്കുന്ന ഒരാളെയും കണ്ടു. നിൽക്കുന്ന ആളുടെ കയ്യിൽ ഇരുമ്പിന്റെ ഒരു കൊളുത്തുണ്ട്. അത് കവിളിലൂടെ പ്രവേശിപ്പിച്ച് പിരടി വരെ എത്തുന്നു. മറ്റേ കവിളിലും അങ്ങനെ ചെയ്യുന്നു. കവിൾ പൂർവ്വ സ്ഥിതി പ്രാപിക്കുന്നു. വീണ്ടും അവൻ ഇത് ആവർത്തിക്കുന്നു. ഞാൻ ചോദിച്ചു: ഇതെന്താണ്? അവർ മുന്നോട്ട് പോകാൻ പറഞ്ഞു. പിരടിയുടെ മേൽ (മലർന്ന്) കിടക്കുന്ന ഒരാളെ ഞങ്ങൾ കണ്ടു. മറ്റൊരാൾ ഒരു കല്ലുമായി ഇയാളുടെ തല തല്ലിത്തകർക്കുന്നു. കല്ല് ഉരുണ്ടപോകുന്നു. കല്ലെടുത്ത് അയാൾ തിരിച്ചു വരുമ്പോഴേക്കും തല ഒരുമിച്ചു ചേർന്നു പഴയ പടിയാവുന്നു. അപ്പോൾ അയാൾ വീണ്ടും തല്ലിത്തകർക്കുന്നു. ഇതെന്താണെന്ന് ഞാൻ ചോദിച്ചു. അവർ മുന്നോട്ട് പോകാൻ പറഞ്ഞു. ഞങ്ങൾ ഒരു അടുപ്പ് പോലുള്ള മാളത്തിനടുത്തെത്തി. അതിന്റെ മുകൾ ഭാഗം ഇടുങ്ങിയതും താഴ് ഭാഗം വിശാലമായതുമുണ്. അതിനടിയിൽ തീ കത്തുന്നു. അവരതിൽ അകപ്പെട്ടിരിക്കുന്നു. അതിൽ നഗ്നരായ സ്ത്രീ പുരുഷന്മാരുണ്ട്. ഞാൻ ഇതാരാണെന്ന് ചോദിച്ചു. അവർ മുന്നേട്ട് പോകാൻ പറഞ്ഞു അങ്ങനെ ഞങ്ങൾ ഒരു രക്തപ്പുഴയുടെ അടുത്ത് ചെന്നു. നദി മധ്യത്തിൽ ഒരാൾ നിൽക്കുന്നു. നദിക്കരയിൽ ഒരാളുണ്ട്. അവന്റെ മുന്നിൽ കല്ലുണ്ട്. നദിയിലുള്ള ആൾ പുറത്ത് വരാൻ ഉദ്ദേശിക്കുമ്പോൾ ഇയാൾ അദ്ദേഹത്തിന്റെ വായിലേക്ക് കല്ലെറിഞ്ഞ് അവന്റെ പഴയ സ്ഥലത്തേക്ക് തന്നെ മടക്കി. ഇത് ആവർത്തിച്ചു കൊണ്ടിരുന്നു. ഇതെന്താണെന്ന് ഞാൻ ചോദിച്ചു. അവർ മുന്നോട്ട് പോകാൻ പറഞ്ഞു. ഞങ്ങൾ പച്ചപ്പുള്ള ഒരു തോട്ടത്തിലെത്തി. അതിൽ വലിയൊരു മരമുണ്ട്. മരച്ചുവട്ടിൽ ഒരു വൃദ്ധനും കുട്ടികളുമുണ്ട്. മരത്തിനടുത്തൊരാളുണ്ട്. അദ്ദേഹത്തിന്റെ മുന്നിൽ കത്തുന്ന തീയുണ്ട്. അവർ രണ്ടു പേരും എന്നെ മരത്തിൽ കയറ്റി. ഇതുവരെ ഞാൻ കണ്ടിട്ടില്ലാത്തവിധം സുന്ദരമായ ഒരു വീട്ടിൽ എന്നെ പ്രവേശിപ്പിച്ചു. അതിൽ വൃദ്ധരും യുവാക്കളും സ്ത്രീകളും കുട്ടികളുമുണ്ട്. പിന്നെ അതിൽ നിന്ന് പുറപ്പെട്ട് മരത്തിനു മുകളിലേക്ക് കയറ്റി. മുമ്പത്തേതിനേക്കാൾ സുന്ദരമായ മറ്റൊരു വീട്ടിൽ കയറി. അതിൽ വൃദ്ധരും യുവാക്കളുമുണ്ട്. ഞാൻ പറഞ്ഞു: രാത്രി നിങ്ങൾ എന്നെയും കൊണ്ട് ചുറ്റി. ഞാൻ കണ്ടതിനെപ്പറ്റി എനിക്ക് പറഞ്ഞ് തരിക. അവർ അതെ എന്ന് പറഞ്ഞു. കവിൾ കുത്തിപ്പറിക്കപ്പെടുന്ന വ്യക്തി കളവു പറയുന്നവനാണ്. അവന്റെ കളവ് ചക്രവാളങ്ങളിലെത്തുന്നു. അന്ത്യനാൾ വരെ ഇത് അവനെക്കൊണ്ട് ചെയ്യിക്കും. തല കുത്തിപ്പൊളിക്കപ്പെടുന്ന വ്യക്തി ഖുർആൻ പഠിച്ച് രാത്രി കിടന്നുറങ്ങുകയും പകലിൽ അതനുസരിച്ച് പ്രവർത്തിക്കാതിരിക്കുകയും ചെയ്തവനാണ്. അന്ത്യനാൾ വരെ ഇത് അവനെക്കൊണ്ട് ചെയ്യിക്കും. കുഴിയിൽ കത്തുന്നവർ വ്യഭിചാരികളാണ്. നദിയിൽ കണ്ടവർ പലിശ തിന്നുന്നവരാണ്. മരച്ചുവട്ടിലുള്ള വൃദ്ധൻ ഇബ്റാഹീം നബി(അ) ആണ്. അദ്ദേഹത്തിനു ചുറ്റുമുള്ള കുട്ടികൾ ജനങ്ങളുടെ കുട്ടികളാണ്. തീ കത്തിക്കുന്ന ആൾ തീ കാക്കുന്ന മാലിക്കാണ്. ആദ്യം ഞാൻ പ്രവേശിച്ച വീട് എല്ലാ മുഅ്മിനുകൾക്കുമായുള്ള വീടാണ്. ഈ വീട് രക്ത സാക്ഷികളുടെ വീടാണ്. ഞാൻ ജിബ്രീലും ഇദ്ദേഹം മീകാഈലുമാണ്. അങ്ങ് തല ഉയർത്തുക. തല ഉയർത്തിയപ്പോൾ കാർമേഘം പോലെയുള്ളത് മുകളിൽ കണ്ടു. അവർ പറഞ്ഞു: അതാണ് നിന്റെ വീട്. ഞാനെന്റെ വീട്ടിൽ പ്രവേശിക്കട്ടെ എന്ന് ഞാൻ പറഞ്ഞു. അപ്പോൾ അവർ പറഞ്ഞു: അങ്ങേക്ക് ഇനിയും ആയുസ്സ് തികയാനുണ്ട്. ആയുസ്സ് തികഞ്ഞാൽ അങ്ങയുടെ വീട്ടിൽ പ്രവേശിക്കാം." (ബു)', 'سَمُرَةَ بْنِ جُنْدَب', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 882, 883, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=147 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 461, 'عَنِ الْمُسَيَّبِ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا حَضَرَتْ أَبَا طَالِبٍ الْوَفَاةُ دَخَلَ عَلَيْهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعِنْدَهُ أَبُو جَهْلٍ وَعَبْدُ اللهِ بْنُ أَبِي أُمَيَّةَ، فَقَالَ: "أَيْ عَمِّ، قُلْ: لَا إِلَهَ إِلَّا اللهُ، كَلِمَةً أُحَاجُّ لَكَ بِهَا عِنْدَ اللهِ عَزَّ وَجَلَّ". فَقَالَ لَهُ أَبُو جَهْلٍ وَعَبْدُ اللهِ بْنُ أَبِي أُمَيَّةَ: يَا أَبَا طَالِبٍ، أَتَرْغَبُ عَنْ مِلَّةِ عَبْدِ الْمُطَّلِبِ؟ فَلَمْ يَزَالَا يُكَلِّمَانِهِ حَتَّى كَانَ آخِرُ شَيْءٍ كَلَّمَهُمْ بِهِ: عَلَى مِلَّةِ عَبْدِ الْمُطَّلِبِ. فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَأَسْتَغْفِرَنَّ لَكَ مَا لَمْ أُنْهَ عَنْكَ". فَنَزَلَتْ: {مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ} [التوبة: ١١٣]. وَنَزَلَتْ: {إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ} [القصص: ٥٦]. (خ,ن)', 'മുസയ്യബ്(റ): അബൂത്വാലിബിന്ന് മരണമാസന്നമായി. നബി(സ) അദ്ദേഹത്തിന്റെ അടുത്തുചെന്നു. അവിടെ അപ്പോൾ അബൂജഹലും അബ്ദുല്ലാഹിബ്നു അബീഉമയ്യയുമുണ്ടായിരുന്നു. നബി(സ) പറഞ്ഞു: "പിതൃവ്യാ താങ്കൾ ''ലാ ഇലാഹ ഇല്ലല്ലാഹ്'' എന്ന് പറയുക. അത്യുന്നതനും മഹാനുമായ അല്ലാഹുവിങ്കൽ ഞാൻ തെളിവായെടുക്കുന്ന വചനം." അപ്പോൾ അബൂജഹ്ലും അബ്ദുല്ലാഹിബ്നു അബീഉമയ്യയും പറഞ്ഞു: അബൂത്വാലിബേ, അബ്ദുൽ മുത്തലിബിന്റെ പാത താങ്കൾ വെടിയുകയോ? അങ്ങനെ അവർ രണ്ട് പേരും സംസാരിക്കുകയും അദ്ദേഹത്തിന്റെ അവസാന സംസാരം ''അബ്ദുൽ മുത്തലിബിന്റെ പാതയിൽ'' എന്നാവുകയും ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "താങ്കളുടെ കാര്യത്തിൽ എനിക്ക് വിലക്ക് വരുന്നത് വരെ താങ്കൾക്ക് വേണ്ടി ഞാൻ അല്ലാഹുവിനോട് പാപമോചനം തേടും." അപ്പോഴാണ് ''പ്രവാചകനും വിശ്വാസികളും മുശ്രിക്കുകൾക്ക് വേണ്ടി പാപമോചനം തേടാൻ പറ്റില്ല'' എന്ന (അതൗബ: 113) ആയത്തും, ''അങ്ങേക്ക് ഇഷ്ടമുള്ളവരെ നേർമാർഗ്ഗത്തിലാക്കാൻ അങ്ങേക്ക് കഴിയില്ല'' എന്ന (അൽഖസസ്: 56) ആയത്തും ഇറങ്ങിയത്. (ബു,ന)', 'الْمُسَيَّبِ', 'മുസയ്യബ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], 'القصص: ٥٦', null, 883, 884, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 462, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَجُلًا يَسْتَغْفِرُ لأَبَوَيْهِ وَهُمَا مُشْرِكَانِ، فَقُلْتُ: أَتَسْتَغْفِرُ لَهُمَا وَهُمَا مُشْرِكَانِ؟ فَقَالَ: أَوَ لَمْ يَسْتَغْفِرْ إِبْرَاهِيمُ لأَبِيهِ؟ فَأَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ ذَلِكَ لَهُ، فَنَزَلَتْ: {وَمَا كَانَ اسْتِغْفَارُ إِبْرَاهِيمَ لأَبِيهِ إِلَّا عَنْ مَوْعِدَةٍ وَعَدَهَا إِيَّاهُ} [التوبة: ١١٤]. (ن)', 'അലി(റ): മുശ്രിക്കുകളായ മാതാപിതാക്കൾക്ക് വേണ്ടി പാപമോചന പ്രാർത്ഥന നടത്തുന്ന ഒരാളെ ഞാൻ കണ്ടു. ഞാൻ ചോദിച്ചു: അവർ രണ്ടു പേരും മുശ്രിക്കുകളായിരിക്കെ നീ അവർക്ക് പാപമോചനം നടത്തുകയോ? അദ്ദേഹം ചോദിച്ചു: ഇബ്രാഹീം നബി(അ) തന്റെ പിതാവിന് പാപമോചന പ്രാർത്ഥന നടത്തിയില്ലേ? അങ്ങനെ ഞാൻ നബി(സ)യുടെ അടുത്തു ചെന്ന് കാര്യം പറഞ്ഞു: അപ്പോൾ ''ഇബ്രാഹീം(അ) തന്റെ പിതാവിന് വേണ്ടി നടത്തിയ പാപമോചനം അദ്ദേഹം ചെയ്ത വാഗ്ദത്തത്തിന്റെ പേരിൽ മാത്രമായിരുന്നു'' എന്ന (അത്തൗബ: 114) ആയത്തിറങ്ങി. (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], 'التوبة: ١١٤', null, 884, 884, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 463, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ فَلَبِسَ ثِيَابَهُ ثُمَّ خَرَجَ، قَالَتْ: فَأَمَرْتُ جَارِيَتِي بَرِيرَةَ تَتْبَعُهُ، فَتَبِعَتْهُ حَتَّى جَاءَ الْبَقِيعَ، فَوَقَفَ فِي أَدْنَاهُ مَا شَاءَ اللهُ أَنْ يَقِفَ، ثُمَّ انْصَرَفَ، فَسَبَقَتْهُ بَرِيرَةُ فَأَخْبَرَتْنِي، فَلَمْ أَذْكُرْ لَهُ شَيْئًا حَتَّى أَصْبَحْتُ، ثُمَّ ذَكَرْتُ ذَلِكَ لَهُ، فَقَالَ: "إِنِّي بُعِثْتُ إِلَى أَهْلِ الْبَقِيعِ لِأُصَلِّيَ عَلَيْهِمْ". (ن)', 'ആഇശ(റ): നബി(സ) വസ്ത്രം ധരിച്ചു കൊണ്ട് പുറത്തിറങ്ങി. ഞാൻ എന്റെ അടിമസ്ത്രീ ബരീറയോട് തിരുമേനി(സ)യെ തുടരാൻ ആവശ്യപ്പെട്ടു. അങ്ങനെ അവൾ തിരുമേനി(സ)യെ തുടർന്ന് ബഖീഇലെത്തി. എവിടെയാണോ തിരുമേനി(സ)യെ നിൽക്കാൻ അല്ലാഹു ഉദ്ദേശിച്ചത് അവിടെ തിരുമേനി(സ) നിന്നു. പിന്നെ തിരുമേനി(സ) പിന്തിരിഞ്ഞു. ബരീറ നബി(സ)യെ മുൻകടന്ന് എന്റെ അടുത്തുവന്നു കാര്യങ്ങൾ പറഞ്ഞു തന്നു. നേരം പുലരുന്നത് വരെ ഞാനൊന്നും പറഞ്ഞില്ല. പിന്നെ ഞാൻ അതിനെകുറിച്ച് റസൂലി(സ)നോടു ചോദിച്ചു. തിരുമേനി(സ) പറഞ്ഞു: "ബഖീഉകാർക്ക് വേണ്ടി പ്രാർത്ഥിക്കാൻ അയക്കപ്പെട്ടതായിരുന്നു ഞാൻ." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 884, 884, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 464, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كُلَّمَا كَانَتْ لَيْلَتُهَا مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْرُجُ فِي آخِرِ اللَّيْلِ إِلَى الْبَقِيعِ، فَيَقُولُ: "السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ، وَإِنَّا وَإِيَّاكُمْ مُتَوَاعِدُونَ غَدًا، أَوْ: مُوَاكِلُونَ، وَإِنَّا إِنْ شَاءَ اللهُ بِكُمْ لَاحِقُونَ. اللَّهُمَّ اغْفِرْ لِأَهْلِ بَقِيعِ الْغَرْقَدِ". (ن)', 'ആഇശ(റ): നബി(സ) ആയിശയോടൊപ്പമുണ്ടാകുന്ന ദിവസങ്ങളിലെല്ലാം രാത്രിയുടെ അവസാനം ബഖീഇലേക്ക് പുറപ്പെടും. എന്നിട്ട് പറയും: "മുഅ്മിനുകളേ, നിങ്ങൾക്ക് സലാം. നിശ്ചയം നിങ്ങളും ഞങ്ങളും നാളെ അന്യോന്യം കരാർചെയ്യുന്നവരാണ്. അല്ലാഹു ഉദ്ദേശിച്ചാൽ നാളെ ഞങ്ങൾ നിങ്ങളോട് ചേരും. അല്ലാഹുവേ! ബഖീഇലുള്ളവർക്ക് നീ പൊറുത്തു കൊടുക്കേണമേ." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 885, 885, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 465, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَتَى عَلَى الْمَقَابِرِ قَالَ: "السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللهُ بِكُمْ لَاحِقُونَ. أَنْتُمْ لَنَا فَرَطٌ، وَنَحْنُ لَكُمْ تَبَعٌ، أَسْأَلُ اللهَ الْعَافِيَةَ لَنَا وَلَكُمْ". (م,ن,جه)', 'ബുറൈദ(റ): നബി(സ) ഖബ്ർ സ്ഥാനിലെത്തിയാൽ ഇങ്ങനെ പറയുമായിരുന്നു: "സത്യവിശ്വാസികളും മുസ്ലിംകളുമായ ഖബർ വാസികളെ, നിങ്ങൾക്ക് അല്ലാഹുവിന്റെ രക്ഷയുണ്ടാവട്ടെ. അല്ലാഹു ഉദ്ദേശിച്ചാൽ ഞങ്ങൾ നിങ്ങളുമായി ചേരുന്നതാണ്. നിങ്ങൾ ഞങ്ങളുടെ മുൻഗാമികൾ, ഞങ്ങൾ നിങ്ങളുടെ പിൻഗാമികൾ. നിങ്ങൾക്കും ഞങ്ങൾക്കും സൗഖ്യം നൽകാൻ ഞാൻ അല്ലാഹുവോട് പ്രാർത്ഥിക്കുന്നു." (മു,ന,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 885, 885, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 466, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا مَاتَ النَّجَاشِيُّ قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اسْتَغْفِرُوا لَهُ". (ن)', 'അബൂഹുറൈറ(റ): നജ്ജാശി നിര്യാതനായപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അദ്ദേഹത്തിന് വേണ്ടി പാപമോചനത്തിന് പ്രാർത്ഥിക്കുക." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 885, 885, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 467, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْعَبْدَ إِذَا وُضِعَ فِي قَبْرِهِ وَتَوَلَّى عَنْهُ أَصْحَابُهُ إِنَّهُ لَيَسْمَعُ قَرْعَ نِعَالِهِمْ، أَتَاهُ مَلَكَانِ فَيُقْعِدَانِهِ فَيَقُولَانِ لَهُ: مَا كُنْتَ تَقُولُ فِي هَذَا الرَّجُلِ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ فَأَمَّا الْمُؤْمِنُ فَيَقُولُ: أَشْهَدُ أَنَّهُ عَبْدُ اللهِ وَرَسُولُهُ. فَيُقَالُ لَهُ: انْظُرْ إِلَى مَقْعَدِكَ مِنَ النَّارِ، قَدْ أَبْدَلَكَ اللهُ بِهِ مَقْعَدًا خَيْرًا مِنْهُ. قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَيَرَاهُمَا جَمِيعًا. وَأَمَّا الْكَافِرُ أَوِ الْمُنَافِقُ فَيُقَالُ لَهُ: مَا كُنْتَ تَقُولُ فِي هَذَا الرَّجُلِ؟ فَيَقُولُ: لَا أَدْرِي، كُنْتُ أَقُولُ كَمَا يَقُولُ النَّاسُ. فَيُقَالُ لَهُ: لَا دَرَيْتَ وَلَا تَلَيْتَ. ثُمَّ يُضْرَبُ ضَرْبَةً بَيْنَ أُذُنَيْهِ، فَيَصِيحُ صَيْحَةً يَسْمَعُهَا مَنْ يَلِيهِ غَيْرَ الثَّقَلَيْنِ". (خ,ن)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "ഒരു അടിമ ഖബ്റിൽ വെക്കപ്പെടുകയും ആളുകൾ പിന്തിരിയുകയും ചെയ്താൽ അവരുടെ ചെരുപ്പിന്റെ ശബ്ദം അവൻ കേൾക്കും. രണ്ട് മലക്കുകൾ വന്ന് അവനെ ഇരുത്തികൊണ്ട് ചോദിക്കും: നിങ്ങൾ ഈ മനുഷ്യനെ കുറിച്ച് എന്തു പറയുന്നു? അപ്പോൾ വിശ്വാസി ഇങ്ങനെ മറുപടി പറയും: അദ്ദേഹം അല്ലാഹുവിന്റെ ദൂതനാണെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. അപ്പോൾ അവനോട് പറയും, നിനക്ക് നരകത്തിലുള്ള സ്ഥാനത്തിലേക്ക് നീ നോക്കുക. ഇതിന് പകരമായി നല്ല സ്ഥാനം അല്ലാഹു നിനക്ക് നൽകിയിരിക്കുന്നു. അങ്ങനെ അവൻ അവ രണ്ടും മുഴുവനായി കാണും. എന്നാൽ കാഫിറിനോടും, മുനാഫിഖിനോടും ഈ മനുഷ്യനെക്കുറിച്ച് എന്ത് പറയുന്നു? എന്ന് ചോദിച്ചാൽ അവൻ പറയും: എനിക്കറിയില്ല. ഞാൻ ജനങ്ങൾ പറയുന്നത് പറയാറുണ്ടായിരുന്നു. അപ്പോൾ അവനോട് പറയും: നീ ബുദ്ധിയുപയോഗിച്ച് മനസിലാക്കിയില്ല, പിൻപറ്റുകയും ചെയ്തില്ല. പിന്നെ അവന്റെ ഇരു ചെവികൾക്കുമിടയിൽ അടിക്കപ്പെടുകയും അവൻ ഉറക്കെ അട്ടഹസിക്കുകയും ചെയ്യും. മനുഷ്യരും ജിന്നുകളുമല്ലാത്ത എല്ലാവരും അത് കേൾക്കും." (ബു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 885, 886, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=150 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 468, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا قُبِضَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اخْتَلَفُوا فِي دَفْنِهِ، فَقَالَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ: سَمِعْتُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَيْئًا مَا نَسِيتُهُ، قَالَ: "مَا قَبَضَ اللهُ نَبِيًّا إِلَّا فِي الْمَوْضِعِ الَّذِي يُحِبُّ أَنْ يُدْفَنَ فِيهِ". ادْفِنُوهُ فِي مَوْضِعِ فِرَاشِهِ. (ت)', 'ആഇശ(റ): നബി(സ) വഫാതായപ്പോൾ നബി(സ)യെ മറമാടേണ്ട സ്ഥലത്തെക്കുറിച്ച് സ്വഹാബികൾക്കിടയിൽ അഭിപ്രായഭിന്നതയുണ്ടായി. അപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: ഒരു സംഗതി ഞാൻ നബി(സ)യിൽ നിന്ന് കേട്ടിട്ടുണ്ട്. ഞാനത് മറന്നിട്ടില്ല. "താൻ മറവുചെയ്യപ്പെടണമെന്ന് ഒരു നബി ഉദ്ദേശിക്കുന്ന സ്ഥലത്തു വച്ചേ അല്ലാഹു ആ നബിയുടെ റൂഹ് പിടിക്കുകയുള്ളൂ." അതിനാൽ നിങ്ങൾ നബി(സ)യെ അവിടുത്തെ വിരിപ്പിന്റെ സ്ഥാനത്ത് മറമാടുക. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 886, 886, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=151 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 469, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا قُبِضَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَأَبُو بَكْرٍ عِنْدَ امْرَأَتِهِ ابْنَةَ خَارِجَةَ بِالْعَوَالِي، فَجَعَلُوا يَقُولُونَ: لَمْ يَمُتِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، إِنَّمَا هُوَ بَعْضُ مَا كَانَ يَأْخُذُهُ عِنْدَ الْوَحْيِ. فَجَاءَ أَبُو بَكْرٍ فَكَشَفَ عَنْ وَجْهِهِ وَقَبَّلَ بَيْنَ عَيْنَيْهِ، وَقَالَ: أَنْتَ أَكْرَمُ عَلَى اللهِ مِنْ أَنْ يُمِيتَكَ مَرَّتَيْنِ. قَدْ – وَاللهِ – مَاتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. وَعُمَرُ فِي نَاحِيَةِ الْمَسْجِدِ يَقُولُ: وَاللهِ مَا مَاتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَا يَمُوتُ حَتَّى يَقْطَعَ أَيْدِيَ أُنَاسٍ مِنَ الْمُنَافِقِينَ كَثِيرٍ وَأَرْجُلَهُمْ. فَقَامَ أَبُو بَكْرٍ فَصَعِدَ الْمِنْبَرَ فَقَالَ: مَنْ كَانَ يَعْبُدُ اللهَ فَإِنَّ اللهَ حَيٌّ لَمْ يَمُتْ، وَمَنْ كَانَ يَعْبُدُ مُحَمَّدًا فَإِنَّ مُحَمَّدًا قَدْ مَاتَ: {وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُ أَفَإِنْ مَاتَ أَوْ قُتِلَ انْقَلَبْتُمْ عَلَى أَعْقَابِكُمْ وَمَنْ يَنْقَلِبْ عَلَى عَقِبَيْهِ فَلَنْ يَضُرَّ اللهَ شَيْئًا وَسَيَجْزِي اللهُ الشَّاكِرِينَ} [آل عمران: ١٤٤]. قَالَ عُمَرُ رَضِيَ اللهُ عَنْهُ: فَلَكَأَنِّي لَمْ أَقْرَأْهَا إِلَّا يَوْمَئِذٍ. (خ,ن,جه)', 'ആഇശ(റ): നബി(സ) വഫാതായപ്പോൾ അബൂബക്കർ(റ) ഖാരിജഃയുടെ പുത്രിയായ തന്റെ പത്നിയുടെ കൂടെ അവാലിയിലായിരുന്നു. എല്ലാവരും കൂടെ പറഞ്ഞു: നബി(സ) മരണപ്പെട്ടിട്ടില്ല. വഹ്യ് ഇറങ്ങുന്ന അവസരത്തിൽ ഉണ്ടാകുന്ന ചില സംഗതിയാണ് അവിടത്തേക്ക് ബാധിച്ചത്. അപ്പോൾ അബൂബക്കർ(റ) വന്ന് നബി(സ)യുടെ മുഖം തുറന്ന് കണ്ണുകൾക്കിടയിൽ ചുംബിച്ചു. എന്നിട്ട് പറഞ്ഞു: അല്ലാഹു താങ്കളെ രണ്ട് പ്രാവശ്യം മരിപ്പിക്കാതിരിക്കാൻ മാത്രം അല്ലാഹുവിങ്കൾ അങ്ങ് ബഹുമാന്യനാണ്. അതെ അല്ലാഹുവാണ, ദൈവദൂതർ(സ) വഫാതായിരിക്കുന്നു. അപ്പോൾ ഉമർ(റ) പള്ളിയുടെ ഒരു ഭാഗത്ത് നിന്ന് ഇങ്ങനെ പറയുന്നുണ്ടായിരുന്നു. അല്ലാഹുവാണെ സത്യം, അല്ലാഹുവിന്റെ ദൂതർ വഫാതായിട്ടില്ല, മുനാഫിഖുകളായ അനേകമാളുകളുടെ കൈകാലുകൾ ഛേദിക്കപ്പെടുന്നതുവരെ അവിടുന്ന് വഫാതാവുകയില്ല. അപ്പോൾ അബൂബക്കർ(റ) മിമ്പറിൽ കയറിയിട്ട് പറഞ്ഞു: ആരെങ്കിലും അല്ലാഹുവിനെ ആരാധിക്കുന്നുവെങ്കിൽ അവൻ ജീവിക്കുന്നവനാണ്, അവൻ മരിച്ചിട്ടില്ല. ആരെങ്കിലും മുഹമ്മദിനെ ആരാധിച്ചിരുന്നുവെങ്കിൽ മുഹമ്മദ് ഇതാ വഫാതായിരിക്കുന്നു. എന്നിട്ട് അദ്ദേഹം ''മുഹമ്മദ് അല്ലാഹുവിന്റെ ദൂതൻ മാത്രമാണ്. അവിടത്തേക്ക് മുമ്പും ഒരുപാട് പ്രവാചകന്മാർ കഴിഞ്ഞ് പോയിരിക്കുന്നു. അവിടുന്ന് മരിച്ചുപോകുകയോ, വധിക്കപ്പെടുകയോ ചെയ്താൽ നിങ്ങൾ പിന്തിരിഞ്ഞു പോകുകയോ? ആരെങ്കിലും അങ്ങിനെ പിന്തിരിഞ്ഞ് പോയാൽ അവൻ അല്ലാഹുവിന് ഒരു ഉപദ്രവവും ചെയ്യുന്നില്ല. നന്ദിയുള്ളവർക്ക് അല്ലാഹു പ്രതിഫലം നൽകും" (ആലുഉംറാൻ: 144) എന്ന ആയത്ത് ഓതി. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: ഇന്നത്തേതിന് മുമ്പ് ഞാനീ സൂക്തം പാരായണം ചെയ്യാത്ത പോലുണ്ട്. (ബു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن','جه']::text[], array['ബു','ന','ജ']::text[], 'آل عمران: ١٤٤', null, 886, 887, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 470, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا أَرَادُوا أَنْ يَحْفِرُوا لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعَثُوا إِلَى أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ، وَكَانَ يَضْرَحُ كَضَرِيحِ أَهْلِ مَكَّةَ. وَبَعَثُوا إِلَى أَبِي طَلْحَةَ، وَكَانَ هُوَ الَّذِي يَحْفِرُ لِأَهْلِ الْمَدِينَةِ، وَكَانَ يَلْحَدُ. فَبَعَثُوا إِلَيْهِمَا رَسُولَيْنِ، وَقَالُوا: اللَّهُمَّ خِرْ لِرَسُولِكَ، فَوَجَدُوا أَبَا طَلْحَةَ، فَجِيءَ بِهِ، وَلَمْ يُوجَدْ أَبُو عُبَيْدَةَ، فَلَحَدَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ: فَلَمَّا فَرَغُوا مِنْ جِهَازِهِ يَوْمَ الثُّلَاثَاءِ وُضِعَ عَلَى سَرِيرِهِ فِي بَيْتِهِ، ثُمَّ دَخَلَ النَّاسُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَرْسَالًا يُصَلُّونَ عَلَيْهِ، حَتَّى إِذَا فَرَغُوا أَدْخَلُوا النِّسَاءَ، حَتَّى إِذَا فَرَغُوا أَدْخَلُوا الصِّبْيَانَ، وَلَمْ يَؤُمَّ النَّاسَ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَحَدٌ. لَقَدِ اخْتَلَفَ الْمُسْلِمُونَ فِي الْمَكَانِ الَّذِي يُحْفَرُ لَهُ، فَقَالَ قَائِلُونَ: يُدْفَنُ فِي مَسْجِدِهِ. وَقَالَ قَائِلُونَ: يُدْفَنُ مَعَ أَصْحَابِهِ. فَقَالَ أَبُو بَكْرٍ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا قُبِضَ نَبِيٌّ إِلَّا دُفِنَ حَيْثُ يُقْبَضُ". قَالَ: فَرَفَعُوا فِرَاشَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الَّذِي تُوُفِّيَ عَلَيْهِ، فَحَفَرُوا لَهُ، ثُمَّ دُفِنَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَسَطَ اللَّيْلِ مِنْ لَيْلَةِ الْأَرْبِعَاءِ. وَنَزَلَ فِي حُفْرَتِهِ عَلِيُّ بْنُ أَبِي طَالِبٍ، وَالْفَضْلُ بْنُ الْعَبَّاسِ، وَقُثَمُ أَخُوهُ، وَشُقْرَانُ مَوْلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. وَقَالَ أَوْسُ بْنُ خَوْلِيٍّ – وَهُوَ أَبُو لَيْلَى – لِعَلِيِّ بْنِ أَبِي طَالِبٍ: أَنْشُدُكَ اللهَ وَحَظَّنَا مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ لَهُ عَلِيٌّ: انْزِلْ. وَكَانَ شُقْرَانُ مَوْلَاهُ أَخَذَ قَطِيفَةً كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَلْبَسُهَا، فَدَفَنَهَا فِي الْقَبْرِ، وَقَالَ: وَاللهِ لَا يَلْبَسُهَا أَحَدٌ بَعْدَكَ أَبَدًا. فَدُفِنَتْ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. [ز: في سنده مختلف فيه] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)ക്ക് ഖബ്ർ കുഴിക്കാൻ സഹാബികൾ ഉദ്ദേശിച്ചപ്പോൾ അവർ അബൂഉബൈദ(റ)യുടെ അടുത്തേക്ക് ആളെ അയച്ചു. അദ്ദേഹം മക്കക്കരുടെത് പോലെയുള്ള ഖബ്ർ കുഴിക്കുമായിരുന്നു. അബൂത്വൽഹ(റ)യുടെ അടുത്തേക്കും ആളെ അയച്ചിരുന്നു. അദ്ദേഹം ആയിരുന്നു മദീനക്കാർക്ക് വേണ്ടി കുഴിക്കാറുണ്ടായിരുന്നത്. അദ്ദേഹം ലഹ്ദും ഉണ്ടാക്കാറുണ്ടായിരുന്നു. അവർ രണ്ട് പേരുടേയും അടുത്തേക്ക് രണ്ട് ദൂതന്മാരെ വിട്ടുകൊണ്ട് സ്വഹാബികൾ പറഞ്ഞു: അല്ലാഹുവേ നീ നിന്റെ റസൂലിന് വേണ്ടി തിരഞ്ഞെടുക്കുക. അവർ അബൂത്വൽഹ(റ)യെ കണ്ടു. അബൂഉബൈദ(റ)യെ കണ്ടില്ല. അദ്ദേഹം ദൈവദൂതന് വേണ്ടി ലഹ്ദുണ്ടാക്കി. ചൊവ്വാഴ്ച ദിവസം അവർ ഒരുക്കത്തിൽ നിന്നും വിരമിച്ചപ്പോൾ പ്രവാചകൻ(സ) സ്വഗൃഹത്തിലെ കട്ടിലിന്മേൽ വെക്കപ്പെട്ടു. പിന്നെ പുരുഷന്മാർ കൂട്ടം കൂട്ടമായി വന്നു നിസ്കരിച്ചു. ശേഷം സ്ത്രീകളെ പ്രവേശിപ്പിച്ചു. ശേഷം കുട്ടികളേയും. നബി(സ)യുടെ ജനാസ നിസ്കാരത്തിന് ജനങ്ങളിലാരും നേതൃത്വം നൽകിയില്ല. പ്രവാചകനെ(സ) അടക്കം ചെയ്യേണ്ട സ്ഥാനത്തെകുറിച്ച് മുസ്ലിംകൾ അഭിപ്രായവിത്യാസത്തിലകപ്പെട്ടു. ചിലർ പറഞ്ഞു പള്ളിയിൽ മറമാടണം, മറ്റുചിലർ പറഞ്ഞു: പ്രവാചകനെ അനുചരന്മാരുടെയടുത്ത് മറമാടണം. അപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞതായി ഞാൻ കേട്ടിട്ടുണ്ട്. "ഒരു പ്രവാചകനും മരിച്ച സ്ഥലത്ത് മറമാടപ്പെട്ടിട്ടല്ലാതെ ഞാൻ കണ്ടിട്ടില്ല." അപ്പോൾ അവർ നബി(സ) വഫാതായികിടന്ന വിരിപ്പുയർത്തി ഖബർ കുഴിച്ചു. പിന്നീട് ബുധനാഴ്ച അർദ്ധരാത്രി നബി(സ) മറമാടപ്പെട്ടു. അവിടുത്തെ ഖബറിൽ അലി(റ), ഫള്ലുബ്നു അബ്ബാസ്(റ), ഖുസ്സം(റ), നബി(സ)യുടെ മൗലയായ ശുഖ്റാൻ(റ) എന്നിവർ ഇറങ്ങി. അപ്പോൾ ഔസുബ്നുഖൗലി (അബൂലൈല) അലി(റ)യോട് പറഞ്ഞു: ദൈവത്തിന്റെ പേരിൽ ഞങ്ങൾക്ക് റസൂലിന്റെ കൂടെ ഇറങ്ങാൻ അവസരം തരണം. അലി(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: നീ ഇറങ്ങുക. നബി(സ) ധരിക്കാറുണ്ടായിരുന്ന ഒരു വില്ലുസ് പട്ട് എടുത്തിട്ട് ശുഖ്റാൻ(റ) ഖബറിൽ മറമാടി, എന്നിട്ട് പറഞ്ഞു: അല്ലാഹുവാണെ, താങ്കൾക്ക് ശേഷം ആരും അത് ധരിക്കുകയില്ല. അത് നബി(സ)യുടെ കൂടെ ഖബറിൽ മറമാടപ്പെട്ടു. (ഇതിന്റെ സനദിൽ അഭിപ്രായഭിന്നതയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده مختلف فيه', null, 887, 887, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 471, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا كَانَ الْيَوْمُ الَّذِي دَخَلَ فيه رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ أَضَاءَ مِنْهَا كُلُّ شَيْءٍ، فَلَمَّا كَانَ الْيَوْمُ الَّذِي مَاتَ فِيهِ أَظْلَمَ مِنْهَا كُلُّ شَيْءٍ، وَمَا نَفَضْنَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْأَيْدِيَ حَتَّى أَنْكَرْنَا قُلُوبَنَا. غريب صحيح. (ت,جه)', 'അനസ്(റ): നബി(സ) മദീനയിൽ പ്രവേശിച്ച ദിവസം അവിടെയുള്ള എല്ലാ വസ്തുക്കളും പ്രകാശിച്ചു. നബി(സ) മരിച്ച ദിവസം അവിടെയുള്ള എല്ലാ വസ്തുക്കളും ഇരുട്ടിലായി. ഞങ്ങളുടെ ഹൃദയത്തെ ഞങ്ങൾ നിഷേധിച്ചിട്ടല്ലാതെ (അവിശ്വസനീയമായതിനാൽ സ്വയം അന്താളിച്ചുകൊണ്ടല്ലാതെ) ദൈവദൂതരിൽ നിന്ന് ഞങ്ങൾ കൈ വേർപ്പെടുത്തിയിട്ടില്ല (നബി(സ)യെ മറമാടുന്നതിൽനിന്ന് വിരമിച്ചിട്ടില്ല). ഈ ഹദീസ് ഗരീബും സഹീഹുമാണെന്ന് തുർമുദി. (തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 888, 888, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 472, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا نَتَّقِي الْكَلَامَ وَالْانْبِسَاطَ إِلَى نِسَائِنَا عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، مَخَافَةً أَنْ يَنْزِلَ فِينَا الْقُرْآنُ، فَلَمَّا مَاتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَكَلَّمْنَا. (خ,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ)യുടെ കാലത്ത് ഖുർആൻ അവതരിക്കുമോ എന്ന ഭയത്താൽ ഭാര്യമാരോട് സല്ലപിക്കുന്നതും സംസാരിക്കുന്നതും ഞങ്ങൾ സൂക്ഷിച്ചിരുന്നു. നബി(സ) മരണപ്പെട്ടപ്പോൾ അവരോ ഞങ്ങൾ സംസാരിക്കാൻ തുടങ്ങി. (ബു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 888, 888, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 473, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَإِنَّمَا وَجْهُنَا وَاحِدٌ، فَلَمَّا قُبِضَ نَظَرْنَا هَكَذَا وَهَكَذَا. [ز: في سنده انقطاع] (جه)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): ഞങ്ങൾ നബി(സ)യുടെ കൂടെ ഉണ്ടായിരിക്കുമ്പോൾ ഏകാഭിപ്രായകാരായിരുന്നു. അല്ലാഹു അവിടുത്തെ ആത്മാവ് പിടിച്ചപ്പോൾ ഞങ്ങൾ വ്യത്യസ്ത അഭിപ്രായങ്ങൾ പ്രകടിപ്പിച്ചു. (ഇതിന്റെ പരമ്പരയിൽ വിടവുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده انقطاع', null, 888, 888, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 474, 'عَنْ أُمِّ سَلَمَةَ بِنْتِ أَبِي أُمَيَّةَ رَضِيَ اللهُ عَنْهَا – زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – أَنَّهَا قَالَتْ: كَانَ النَّاسُ فِي عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِذَا قَامَ الْمُصَلِّي يُصَلِّي لَمْ يَعْدُ بَصَرُ أَحَدِهِمْ مَوْضِعَ قَدَمَيْهِ، فَلَمَّا تُوُفِّيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: فَكَانَ النَّاسُ إِذَا قَامَ أَحَدُهُمْ يُصَلِّي لَمْ يَعْدُ بَصَرُ أَحَدِهِمْ مَوْضِعَ جَبِينِهِ. فَتُوُفِّيَ أَبُو بَكْرٍ وَكَانَ عُمَرُ: فَكَانَ النَّاسُ إِذَا قَامَ أَحَدُهُمْ يُصَلِّي لَمْ يَعْدُ بَصَرُ أَحَدِهِمْ مَوْضِعَ الْقِبْلَةِ. وَكَانَ عُثْمَانُ بْنُ عَفَّانَ: فَكَانَتِ الْفِتْنَةُ، فَتَلَفَّتَ النَّاسُ يَمِينًا وَشِمَالًا. (جه)', 'പ്രവാചക പത്നി ഉമ്മുസലമ(റ): നബി(സ)യുടെ കാലത്ത് ജനങ്ങളിൽ നിന്ന് ഒരാൾ നിസ്കരിച്ചാൽ അവന്റെ ദൃഷ്ടി ഇരു കാലുകളേയും വിട്ടു കടക്കുമായിരുന്നില്ല. നബി(സ) വഫാതായ ശേഷം ജനങ്ങളിലാരെങ്കിലും നിസ്കരിച്ചാൽ അവന്റെ ദൃഷ്ടി നെറ്റി വെക്കുന്ന സ്ഥലത്തെ വിട്ടു കടക്കുമായിരുന്നില്ല. അങ്ങനെ അബൂബക്കർ(റ) മരിച്ചു. ഉമറി(റ)ന്റെ കാലമായി. അന്ന് ജനങ്ങളിലാരെങ്കിലും നിസ്കരിച്ചാൽ അവന്റെ ദൃഷ്ടി ഖിബ്‌ലയിൽ നിന്ന് വിട്ടുകടക്കുമായിരുന്നില്ല. പിന്നീട് ഉസ്മാൻ(റ)ന്റെ കാലം വന്നു. അത് ഫിത്നയുടേതായിരുന്നു. ജനങ്ങൾ ഇടത്തോട്ടും വലത്തോട്ടും തിരിഞ്ഞ് നോക്കാൻ തുടങ്ങി. (ജ)', 'أُمِّ سَلَمَةَ بِنْتِ أَبِي أُمَيَّةَ', 'പ്രവാചക പത്നി ഉമ്മുസലമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 888, 888, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 475, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ أَبُو بَكْرٍ بَعْدَ وَفَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِعُمَرَ: انْطَلِقْ بِنَا إِلَى أُمِّ أَيْمَنَ نَزُورُهَا، كَمَا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَزُورُهَا. قَالَ: فَلَمَّا انْتَهَيْنَا إِلَيْهَا بَكَتْ، فَقَالَا لَهَا: مَا يُبْكِيكِ؟ فَمَا عِنْدَ اللهِ خَيْرٌ لِرَسُولِه. قَالَتْ: إِنِّي لَأَعْلَمُ أَنَّ مَا عِنْدَ اللهِ خَيْرٌ لِرَسُولِه، وَلَكِنْ أَبْكِي لِأَنَّ الْوَحْيَ قَدِ انْقَطَعَ مِنَ السَّمَاءِ. قَالَ: فَهَيَّجَتْهُمَا عَلَى الْبُكَاءِ، فَجَعَلَا يَبْكِيَانِ مَعَهَا. (جه)', 'അനസ്(റ): നബി(സ)യുടെ മരണശേഷം അബൂബക്കർ(റ) ഉമറി(റ)നോട് പറഞ്ഞു: വരൂ പ്രവാചകൻ(സ) ചെയ്യാറുള്ളത് പോലെ നമുക്ക് ഉമ്മുഅയ്മനെ(റ) സന്ദർശിക്കാം. ഞങ്ങൾ ഉമ്മുഐമന്റെ(റ) അടുത്തെത്തിയപ്പോൾ മഹതി കരഞ്ഞു. അപ്പോൾ അബുബക്കറും(റ) ഉമറും(റ) മഹതിയോട് ചോദിച്ചു: എന്താണ് മഹതിയെ കരയിക്കുന്നത്? പ്രവാചകർ(സ)ക്കുവേണ്ടി നന്മയാണല്ലോ അല്ലാഹുവിന്റെ പക്കലുള്ളത്. മഹതി പറഞ്ഞു: നിശ്ചയം എനിക്കറിയാം, അല്ലാഹുവിന്റെ അടുത്ത് അവന്റെ പ്രവാചകനുള്ളത് നന്മയാണ് എന്ന്. എന്നാൽ ഞാൻ കരയുന്നത് ആകാശത്തിൽ നിന്നുള്ള വഹ്‌യ് അവസാനിച്ചതിനാലാണ്. ഇത് അവരുടെ കരച്ചിലിനെ ഇളക്കിവിട്ടു. അവർ രണ്ട് പേരും മഹതിയോടൊപ്പം കരഞ്ഞു. (ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 888, 889, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 476, 'عَنْ أَوْسِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ أَفْضَلِ أَيَّامِكُمْ يَوْمَ الْجُمُعَةِ: فِيهِ خُلِقَ آدَمُ، وَفِيهِ النَّفْخَةُ، وَفِيهِ الصَّعْقَةُ. فَأَكْثِرُوا عَلَيَّ مِنَ الصَّلَاةِ فِيهِ، فَإِنَّ صَلَاتَكُمْ مَعْرُوضَةٌ عَلَيَّ". فَقَالَ رَجُلٌ: يَا رَسُولَ اللهِ، كَيْفَ تُعْرَضُ صَلَاتُنَا عَلَيْكَ وَقَدْ أَرِمْتَ؟ يَعْنِي بَلِيتَ. قَالَ: "إِنَّ اللهَ حَرَّمَ عَلَى الْأَرْضِ أَنْ تَأْكُلَ أَجْسَادَ الْأَنْبِيَاءِ". (د,ن,جه)', 'ഔസുബ്നു ഔസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ ദിനങ്ങളിൽ ഏറ്റവും ശ്രേഷ്ഠമായ ദിനം വെള്ളിയാണ്. അതിലാണ് ആദം സൃഷ്ടിക്കപ്പെട്ടത്. അന്നാണ് കാഹളത്തിലൂതുക. അന്നാണ് ലോകാവസാനം. അതുകൊണ്ട് അന്ന് നിങ്ങൾ എനിക്കുള്ള സ്വലാത്ത് അധികരിപ്പിക്കുക. നിങ്ങളുടെ സ്വലാത്ത് എനിക്ക് അവതരിക്കപ്പെടും." അപ്പോൾ ഒരാൾ ചോദിച്ചു: താങ്കൾ ദ്രവിച്ച ശേഷം ഞങ്ങളുടെ സ്വലാത്ത് എങ്ങനെ താങ്കളിലെത്തും? നബി(സ) പറഞ്ഞു: "പ്രവാചകന്മാരുടെ ശരീരം തിന്നുകളയുന്നത് അല്ലാഹു ഭൂമിക്ക് നിഷദ്ധമാക്കിയിരിക്കുന്നു." (ദ,ന,ജ)', 'أَوْسِ بْنِ أَوْسٍ', 'ഔസുബ്നു ഔസ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 889, 889, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 477, 'عَنْ أَنَسِ بْنِ مَالكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَتْ لِي فَاطِمَةُ: يَا أَنَسُ، كَيْفَ سَخَتْ أَنْفُسُكُمْ أَنْ تَحْثُوا التُّرَابَ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. وَعَنْهُ: أَنَّ فَاطِمَةَ – رَضِيَ اللهُ عَنْهَا قَالَتْ حِينَ قُبِضَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: وَا أَبَتَاهُ، إِلَى جِبْرَائِيلَ أَنْعَاهُ، وَا أَبَتَاهُ، مِنْ رَبِّهِ مَا أَدْنَاهُ. وَا أَبَتَاهُ، جَنَّةُ الْفِرْدَوْسِ مَأْوَاهُ. وَا أَبَتَاهُ، أَجَابَ رَبًّا دَعَاهُ. قَالَ حَمَّادٌ: فَرَأَيْتُ ثَابِتًا – حِينَ حَدَّثَ بِهَذَا الْحَدِيثِ – بَكَى حَتَّى رَأَيْتُ أَضْلَاعَهُ تَخْتَلِفُ. (خ,جه)', 'അനസുബ്നുമാലിക്(റ): എന്നോട് ഫാതിമ(റ) ചോദിച്ചു: അനസേ, അല്ലാഹുവിന്റെ റസൂലി(സ)ന്റെ ശരീരത്തിലേക്ക് മണ്ണ് വാരിയിടാൻ നിങ്ങളുടെ ഹൃദയങ്ങൾക്ക് എങ്ങനെ സാധിച്ചു? അദ്ദേഹത്തിൽ നിന്ന് തന്നെ നിവേദനം: റസൂൽ(സ) വഫാതായപ്പോൾ ഫാതിമ(റ) പറഞ്ഞു: എന്റെ പിതാവേ, ജിബ്രീലിന് ഞാൻ താങ്കളുടെ മരണവാർത്ത അറിയിക്കുന്നു. എന്റെ പിതാവേ, താങ്കളുടെ റബ്ബിനോട് തങ്ങൾ എത്ര അടുത്താണ്. എന്റെ പിതാവേ താങ്കളുടെ സങ്കേതം ജന്നത്തുൽ ഫിർദൗസാണ്. എന്റെ പിതാവേ, താങ്കൾ റബ്ബിന്റെ വിളിക്കുത്തരം നൽകിയല്ലോ. ഹമ്മാദ് പറയുന്നു: ഈ ഹദീസ് പറഞ്ഞപ്പോൾ സാബിത് കരഞ്ഞത് ഞാൻ കണ്ടിട്ടുണ്ട്. കരഞ്ഞ് അദ്ദേഹത്തിന്റെ വാരിയെല്ലുകൾ വേർപെടുന്നതും ഞാൻ കണ്ടിട്ടുണ്ട്. (ബു,ജ)', 'أَنَسِ بْنِ مَالكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 889, 889, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 478, 'عَنْ أَنَسِ بْنِ مَالكٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا وَجَدَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ كَرْبِ الْمَوْتِ مَا وَجَدَ قَالَتْ فَاطِمَةُ: وَا كَرْبَ أَبَتَاهُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا كَرْبَ عَلَى أَبِيكِ بَعْدَ الْيَوْمِ، إِنَّهُ قَدْ حَضَرَ مِنْ أَبِيكِ مَا لَيْسَ بِتَارِكٍ مِنْهُ أَحَدًا، الْمُوَافَاةُ يَوْمَ الْقِيَامَةِ". [ز: في سنده راو مختلف فيه] (جه)', 'അനസുബ്നുമാലിക്(റ): നബി(സ)ക്ക് മരണവേദന അനുഭവപ്പെട്ടപ്പോൾ ഫാതിമ(റ) പറഞ്ഞു: പ്രിയപിതാവിന്റെ വേദനയേ. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "ഇന്നത്തേതിന്റെ ശേഷം നിന്റെ പിതാവിന്ന് ഒരു വേദനയുമില്ല. ഒരാളേയും വിട്ടുകളയാത്ത ഒന്ന് നിന്റെ പിതാവിന് ഹാജരായിട്ടുണ്ട്. പരസ്പരം യോജിക്കൽ അന്ത്യനാളിലാണ്." (ഇതിന്റെ സനദിലെ ഒരു റിപ്പോർട്ടറെക്കുറിച്ച് അഭിപ്രായവ്യത്യാസമുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'أَنَسِ بْنِ مَالكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده راو مختلف فيه', null, 889, 889, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 479, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنْ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيَتَعَذَّرُ فِي مَرَضِه: "أَيْنَ أَنَا الْيَوْمَ، أَيْنَ أَنَا غَدًا". اسْتِبْطَاءً لِيَوْمِ عَائِشَةَ، فَلَمَّا كَانَ يَوْمِي، قَبَضَهُ اللهُ بَيْنَ سَحْرِي وَنَحْرِي، وَدُفِنَ فِي بَيْتِي. (خ)', 'ആഇശ(റ): നബി(സ) തന്റെ രോഗത്തിൽ ഇങ്ങനെ പറഞ്ഞു: "ഇന്ന് ഞാനെവിടെ! നാളെ ഞാനെവിടെയായിരിക്കും." അഇശ(റ)യുടെ ദിവസം ആഗ്രഹിച്ചുകൊണ്ടായിരുന്നു അത്. അങ്ങനെ എന്റെ ദിവസം എത്തിയപ്പോൾ എന്റെ കഴുത്തിന്റെയും നെഞ്ചിന്റെയും ഇടയിൽ വെച്ച് അവിടുന്ന് വഫാതായി. എന്റെ വീട്ടിൽ മറമാടപ്പെട്ടു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 890, 890, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=153 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 480, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: تُوُفِّيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ رَاضٍ عَنْ هَؤُلَاءِ النَّفَرِ السِّتَّةِ: فَسَمَّى: عُثْمَانَ، وَعَلِيًّا، وَطَلْحَةَ، وَالزُّبَيْرَ، وَعَبْدَالرَّحْمَنِ بْنِ عَوْفٍ، وَسَعْدَ بْنَ أَبِي وَقَّاصٍ، رَضِيَ اللهُ عَنْهُمْ. (خ)', 'ഉമർ(റ): ആറ് പേരെ തൃപ്തിപ്പെട്ടുകൊണ്ട് നബി(സ) മരണപ്പെട്ടു. ഉസ്മാൻ(റ), അലി(റ), ത്വൽഹ(റ), സുബൈർ(റ), അബ്ദുറഹ്മാനുബ്നു ഔഫ്(റ), സഅ്ദുബ്നു അബീവഖ്ഖാസ്(റ) എന്നിവരാണവർ. (ബു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 890, 890, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=153 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 481, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَوْتُ غُرْبَةٍ شَهَادَةٌ". [وَفِي إِسْنَادِه ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): "വിദേശത്ത് നിന്നുള്ള മരണം രക്തസാക്ഷിത്വമാണ്." (ഇതിന്റെ പരമ്പരയിൽ ദൗർബല്യമുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'وَفِي إِسْنَادِه ضعيف', null, 890, 890, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 482, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: تُوُفِّيَ رَجُلٌ بِالْمَدِينَةِ مِمَّنْ وُلِدَ بِالْمَدِينَةِ، فَصَلَّى عَلَيْهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "يَا لَيْتَهُ مَاتَ فِي غَيْرِ مَوْلِدِه". فَقَالَ رَجُلٌ مِنَ النَّاسِ: وَلِمَ يَا رَسُولَ اللهِ؟ قَالَ: "إِنَّ الرَّجُلَ إِذَا مَاتَ فِي غَيْرِ مَوْلِدِه قِيسَ لَهُ مِنْ مَوْلِدِه إِلَى مُنْقَطَعِ أَثَرِه فِي الْجَنَّةِ". (ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): മദീനയിൽ ജനിച്ച ഒരാൾ അവിടെ വെച്ച് മരണപ്പെട്ടു. നബി(സ) അദ്ദേഹത്തിനുവേണ്ടി നിസ്കരിച്ചു. തുടർന്നു പറഞ്ഞു: "അദ്ദേഹം സ്വന്തം ജന്മനാട്ടിൽ മരിക്കാതിരുന്നെങ്കിൽ എത്ര നന്നായിരുന്നു." അപ്പോൾ ഒരാൾ ചോദിച്ചു: എന്തുകൊണ്ടാണ് റസൂലേ? നബി(സ) പറഞ്ഞു: "നിശ്ചയം ഒരാൾ സ്വന്തം നാട്ടിന് പുറത്തുവച്ച് മരിച്ചാൽ അവന്റെ ജന്മനാടുമുതൽ യാത്ര അവസാനിച്ച അത്ര സ്ഥാനം അവന് സ്വർഗ്ഗത്തിൽ ലഭിക്കും." (ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 890, 890, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 483, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا حَمَلْنَا الْقَتْلَى يَوْمَ أُحُدٍ لِنَدْفِنَهُمْ، فَجَاءَ مُنَادِي النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكُمْ أَنْ تَدْفِنُوا الْقَتْلَى فِي مَضَاجِعِهِمْ فَرَدَدْنَاهُمْ. (د,ت,ن,جه)', 'ജാബിർ(റ): ഉഹ്ദ് ദിവസം മരണമടഞ്ഞവരെ മറമാടാനായി ഞങ്ങൾ എടുത്തു കൊണ്ടുപോയിരുന്നു. അപ്പോൾ നബി(സ) പറയുന്ന കാര്യം വിളിച്ച് പറയുന്ന ആൾ പറഞ്ഞു: നബി(സ) നിങ്ങളോട് മരിച്ചവരെ അവർ മരിച്ച സ്ഥലത്ത് തന്നെ മറമാടാൻ പറയുന്നു. അപ്പോൾ ഞങ്ങൾ കൊണ്ടുപോയവരെ തിരിച്ച് കൊണ്ടു വന്നു. (ദ,തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 890, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=155 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 484, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: دُفِنَ مَعَ أَبِي رَجُلٌ، فَكَانَ فِي نَفْسِي مِنْ ذَلِكَ حَاجَةٌ، فَأَخْرَجْتُهُ بَعْدَ سِتَّةِ أَشْهُرٍ، فَمَا أَنْكَرْتُ مِنْهُ شَيْئًا إِلَّا شُعَيْرَاتٍ كُنَّ فِي لِحْيَتِه مِمَّا يَلِي الْأَرْضَ. (خ,د,ن)', 'ജാബിർ(റ): എന്റെ പിതാവിന്റെ കൂടെ ഒരാൾ മറമാടപ്പെട്ടു. അതെന്തെങ്കിലും ചെയ്യണം എന്ന ആവശ്യം എന്റെ മനസ്സിൽ ഉണ്ടായിരുന്നു. ഞാൻ അദ്ദേഹത്തെ ആറു മാസങ്ങൾക്കുശേഷം പുറത്തെടുത്തു. താടിയിൽ നിന്ന് വിട്ടുപോയ ചില രോമങ്ങൾ അല്ലാതെ അതിൽ നിന്ന് ഒന്നും ഞാൻ വിട്ടുകളഞ്ഞില്ല. (ബു,ദ,ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=156 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 485, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا وُضِعَ الرَّجُلُ الصَّالِحُ عَلَى سَرِيرِه قَالَ: قَدِّمُونِي قَدِّمُونِي. وَإِذَا وُضِعَ الرَّجُلُ – يَعْنِي السُّوءَ – عَلَى سَرِيرِه قَالَ: يَا وَيْلِي، أَيْنَ تَذْهَبُونَ بِي". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "സൽസ്വഭാവിയായ ഒരു മനുഷ്യനെ മയ്യിത്ത് കട്ടിലിൽ വെക്കപ്പെടുമ്പോൾ ''എന്നെ വേഗം കൊണ്ടുപോകൂ''. ''എന്നെ വേഗം കൊണ്ടുപോകൂ!'' എന്ന് അയാൾ പറയും. ദുഷ്കർമിയായ ഒരു മനുഷ്യനെ കട്ടിലിൽ വെക്കപ്പെടുമ്പോൾ എന്റെ കഷ്ടം, എന്നെ നിങ്ങൾ എവിടേക്ക് കൊണ്ടുപോകുന്നു എന്ന് അയാൾ പറയും." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 486, 'عَنِ الْحُصَيْنِ بْنِ وَحْوَحٍ رَضِيَ اللهُ عَنْهُ: أَنَّ طَلْحَةَ بْنَ الْبَرَاءِ مَرِضَ، فَأَتَاهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُهُ، فَقَالَ: "إِنِّي لَا أَرَى طَلْحَةَ إِلَّا قَدْ حَدَثَ فِيهِ الْمَوْتُ، فَآذِنُونِي بِه وَعَجِّلُوا، فَإِنَّهُ لَا يَنْبَغِي لِجِيفَةِ مُسْلِمٍ أَنْ تُحْبَسَ بَيْنَ ظَهْرَانَيْ أَهْلِه". (د)', 'ഹുസൈൻ ഇബ്നുവഹ്വഹ്(റ): ത്വൽഹത് ഇബ്നുബറാഇ(റ)ന് രോഗം ബാധിച്ചപ്പോൾ പ്രവാചകൻ(സ) അദ്ദേഹത്തെ സന്ദർശിക്കാൻ ചെന്നു. ഇങ്ങനെ പറഞ്ഞു: "ത്വൽഹതിന് മരണം സംഭവിക്കാൻ പോവുകയാണെന്ന് എനിക്ക് തോന്നുന്നത്. മരിച്ചാൽ എന്നെ വിവരം അറിയിക്കുക. നിങ്ങൾ ധൃതി കാണിക്കുക. കാരണം ഒരു മുസ്ലിമിന്റെ മൃതദേഹത്തെ തന്റെ കുടുംബത്തിനിടയിൽ തടഞ്ഞ് വെക്കുന്നത് അനുചിതമല്ല." (ദ)', 'الْحُصَيْنِ بْنِ وَحْوَحٍ', 'ഹുസൈൻ ഇബ്നുവഹ്വഹ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 487, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَسْرِعُوا بِالْجِنَازَةِ، فَإِنْ تَكُ صَالِحَةً فَخَيْرٌ – [ لَعَلَّهُ قَالَ] تُقَدِّمُونَهَا إِلَيْهِ، وَإِنْ تَكُ غَيْرَ ذَلِكَ فَشَرٌّ تَضَعُونَهُ عَنْ رِقَابِكُمْ". (ق,د,ت,ن,جه)', 'പ്രവാചകൻ(സ) പറഞ്ഞതായി അബുഹുറൈറ(റ): "നിങ്ങൾ മൃതശരീരം വേഗം കൊണ്ടുപോകുക. അത് സുകൃതം ചെയ്തവനാണെങ്കിൽ നന്മയിലേക്ക് നിങ്ങൾ അതിനെ ആനയിക്കുകയാണ്. ദുഷ്കർമ്മിയാണെങ്കിൽ ഒരു തിന്മയെ നിങ്ങൾ ചുമലുകളിൽ നിന്നും ഇറക്കിവെക്കുകയാണ്." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'പ്രവാചകൻ(സ) പറഞ്ഞതായി അബുഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], 'لَعَلَّهُ قَالَ', null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 488, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ جَوْشَنٍ الْغَطْفَانِيِّ: أَنَّهُ كَانَ فِي جِنَازَةِ عُثْمَانَ بْنِ أَبِي الْعَاصِ، وَكُنَّا نَمْشِي مَشْيًا خَفِيفًا، فَلَحِقَنَا أَبُو بَكْرَةَ رَضِيَ اللهُ عَنْهُ فَرَفَعَ سَوْطَهُ فَقَالَ: لَقَدْ رَأَيْتُنَا وَنَحْنُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَرْمُلُ رَمَلًا. وَفِي رِوَايَةٍ: فِي جِنَازَةِ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ، وَقَالَ: فَحَمَلَ عَلَيْهِمْ بِغَلْتَهُ وَأَهْوَى بِالسَّوْطِ. (د,ن)', 'അബ്ദുറഹിമാൻ ഇബ്നുജൗശനുൽ ഗത്ഫാനീ(റ): അദ്ദേഹം ഉസ്മാൻ ഇബ്നുഅബുൽ ആസി(റ)യുടെ ജനാസസയിലായിരുന്നു. ഞങ്ങൾ പതുക്കെ നടക്കുകയായിരുന്നു. അപ്പോൾ അബുബക്റഃ(റ) എത്തിച്ചേരുകയും തന്റെ ചാട്ടവാർ ഉയർത്തുകയും ചെയ്തു. അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ പ്രവാചകന്റെ(സ) കൂടെ ആകുമ്പോൾ ധൃതിയിൽ നടക്കുമായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: അബ്ദുറഹ്മാനുബ്നു സമുറ(റ)യുടെ ജനാസയിൽ എന്നാണ്. അബൂബക്റ(റ) കഴുതയുമായി അവരുടെ നേരെ ചെന്ന് ചാട്ടവാർ വീശി എന്നുകൂടി അതിൽ പറയുന്നുണ്ട്. (ദ,ന)', 'عَبْدِ الرَّحْمَنِ بْنِ جَوْشَنٍ الْغَطْفَانِيِّ', 'അബ്ദുറഹിമാൻ ഇബ്നുജൗശനുൽ ഗത്ഫാനീ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 891, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=488), 1, 'وَفِي رِوَايَةٍ: فِي جِنَازَةِ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ، وَقَالَ: فَحَمَلَ عَلَيْهِمْ بِغَلْتَهُ وَأَهْوَى بِالسَّوْطِ. (د,ن)', 'മറ്റൊരു നിവേദനിൽ: അബ്ദുറഹ്മാനുബ്നു സമുറ(റ)യുടെ ജനാസയിൽ എന്നാണ്. അബൂബക്റ(റ) കഴുതയുമായി അവരുടെ നേരെ ചെന്ന് ചാട്ടവാർ വീശി എന്നുകൂടി അതിൽ പറയുന്നുണ്ട്. (ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 489, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْنَا نَبِيَّنَا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمَشْيِ مَعَ الْجِنَازَةِ، فَقَالَ: "مَا دُونَ الْخَبَبِ، إِنْ يَكُنْ خَيْرًا تُعَجَّلْ إِلَيْهِ، وَإِنْ يَكُنْ غَيْرَ ذَلِكَ فَبُعْدًا لِأَهْلِ النَّارِ. وَالْجِنَازَةُ مَتْبُوعَةٌ وَلَا تُتْبَعُ، لَيْسَ مَعَهَا مَنْ تَقَدَّمَهَا". ضعيف. (د,ت,جه)', 'ഇബ്നുമസ്ഊദ്(റ): ഞങ്ങൾ നബി(സ)യോട് ജനാസയുടെ കൂടെ എങ്ങനെ നടക്കേണ്ടത് എന്ന് ചോദിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "ഓടാതെ വേഗത്തിൽ, നല്ലവനാണെങ്കിൽ നന്മയിലേക്ക് വേഗത്തിൽ അവൻ എത്തുന്നു, അതല്ലെങ്കിൽ നരകവാസികൾക്ക് നാശം! (അവർ അകന്നു പോവട്ടെ!). മയ്യിത്ത് പിന്തുടരപ്പെടുകയാണ് വേണ്ടത്. (മയ്യിത്ത് ആളുകളെ) പിന്തുടരുകയല്ല. അതിന്റെ മുമ്പിൽ പോകുന്നവർ അതിന്റെ കൂടെയുള്ളവരല്ല." ഹദീസിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു. (ദ,തു,ജ)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 892, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 490, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ جَوْشَنٍ قَالَ: شَهِدْتُ جِنَازَةَ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ، وَخَرَجَ زِيَادٌ يَمْشِي بَيْنَ يَدَيِ السَّرِيرِ، فَجَعَلَ رِجَالٌ مِنْ أَهْلِ عَبْدِ الرَّحْمَنِ وَمَوَالِيهِمْ يَسْتَقْبِلُونَ السَّرِيرَ وَيَمْشُونَ عَلَى أَعْقَابِهِمْ، وَيَقُولُونَ: رُوَيْدًا رُوَيْدًا، بَارَكَ اللهُ فِيكُمْ. فَكَانُوا يَدُبُّونَ دَبِيبًا، حَتَّى إِذَا كُنَّا بِبَعْضِ طَرِيقِ الْمِرْبَدِ لَحِقَنَا أَبُو بَكْرَةَ رَضِيَ اللهُ عَنْهُ عَلَى بَغْلَةٍ، فَلَمَّا رَأَى الَّذِي يَصْنَعُونَ حَمَلَ عَلَيْهِمْ بِبَغْلَتِه وَأَهْوَى إِلَيْهِمْ بِالسَّوْطِ، وَقَالَ: خَلُّوا، فَوَالَّذِي أَكْرَمَ وَجْهَ أَبِي الْقَاسِمِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَقَدْ رَأَيْتُنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَإِنَّا لَنَكَادُ نَرْمُلُ بِهَا رَمَلًا. فَانْبَسَطَ الْقَوْمُ. (ن)', 'അബ്ദുറഹ്മാൻ ഇബ്നുജൗശൻ(റ): ഞാൻ അബ്ദുറഹ്മാൻ ഇബ്നുസമുറ(റ)യുടെ ജനാസയിൽ പങ്കുവഹിച്ചു. സിയാദ് മയ്യിത്ത് കട്ടിലിന്റെ മുമ്പിലൂടെ നടന്നു. അബ്ദുറഹ്മാന്റെ ആളുകളും അടിമകളും മയ്യിത്ത് കട്ടിൽ ആനയിച്ചുകൊണ്ട് പതുക്കെ നടക്കുന്നു. പതുക്കെ പതുക്കെ, അല്ലാഹു നിങ്ങളെ അനുഗ്രഹിക്കട്ടെ എന്ന് അവർ പറയുന്നുണ്ടായിരുന്നു. അങ്ങനെ അവർ ഇഴഞ്ഞ് നീങ്ങുകയായിരുന്നു. ഞങ്ങൾ മിർബതിലെ വഴിയിൽ എത്തിയപ്പോൾ ഒരു കോവർ കഴുതപ്പുറത്ത് അബൂബകറ(റ) അവിടെ എത്തി. ജനങ്ങളുടെ ചെയ്തികണ്ടപ്പോൾ അദ്ദേഹം കോവർ കഴുതയുമായി അവരുടെ നേരെ ചെല്ലുകയും ചാട്ടവാർ വീശുകയും ചെയ്തു. അദ്ദേഹം പറഞ്ഞു: വീടൂ, അബുൽഖാസിമിന്റെ(സ) മുഖം ആദരിച്ച അല്ലാഹുവാണ, ഞാൻ പ്രവാചകന്റെ(സ) കൂടെയാകുമ്പോൾ ഞങ്ങൾ കുലുങ്ങി നടക്കുന്നതായിട്ടാണ് കണ്ടിട്ടുള്ളത്. അപ്പോൾ ജനങ്ങൾ വേഗത്തിൽ നടന്നു. (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ جَوْشَنٍ قَالَ', 'അബ്ദുറഹ്മാൻ ഇബ്നുജൗശൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 892, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 491, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا وُضِعَتِ الْجِنَازَةُ، فَاحْتَمَلَهَا الرِّجَالُ عَلَى أَعْنَاقِهِمْ: فَإِنْ كَانَتْ صَالِحَةً قَالَتْ: قَدِّمُونِي قَدِّمُونِي. وَإِنْ كَانَتْ غَيْرَ صَالِحَةٍ قَالَتْ: يَا وَيْلَهَا، إِلَى أَيْنَ تَذْهَبُونَ بِهَا. يَسْمَعُ صَوْتَهَا كُلُّ شَيْءٍ إِلَّا الْإِنْسَانَ، وَلَوْ سَمِعَهَا الْإِنْسَانُ لَصَعِقَ". (ن)', 'പ്രവാചകൻ(സ) പറഞ്ഞതായി അബൂസഈദുൽ ഖുദ്രി(റ): "മൃതശരീരം കട്ടിലിലാക്കി ജനങ്ങൾ അവരുടെ ചുമലുകളിൽ വഹിക്കുമ്പോൾ സുകൃതവാനാണെങ്കിൽ എന്നെ വേഗം കൊണ്ടുപോകൂ, എന്നെ വേഗം കൊണ്ടുപോകൂ എന്ന് പറയും. സുകൃതവാനല്ലായെങ്കിൽ നാശമേ! എന്നെ എങ്ങോട്ട്കൊണ്ടുപോകുന്നു? എന്നവൻ പറയും. മനുഷ്യനല്ലാത്ത എല്ലാം അതിന്റെ ശബ്ദം കേൾക്കും. അത് മനുഷ്യൻ കേൾക്കുകയാണെങ്കിൽ ബോധം കെട്ട് വീഴും." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'പ്രവാചകൻ(സ) പറഞ്ഞതായി അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 892, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 492, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُؤَخِّرُوا الْجِنَازَةَ إِذَا حَضَرَتْ". (ت,جه)', 'പ്രവാചകൻ(സ) പറഞ്ഞതായി അലിയ്യിബ്നു അബൂത്വാലിബ്(റ): "മരിച്ച് കഴിഞ്ഞാൽ ജനാസയെ നിങ്ങൾ താമസിപ്പിക്കരുത്." (തു,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'പ്രവാചകൻ(സ) പറഞ്ഞതായി അലിയ്യിബ്നു അബൂത്വാലിബ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 893, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 493, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ: أَوْصَى حِينَ حَضَرَهُ الْمَوْتُ فَقَالَ: لَا تُتْبِعُونِي بِمَجْمَرٍ. قَالُوا لَهُ: أَوَ سَمِعْتَ فِيهِ شَيْئًا؟ قَالَ: نَعَمْ، مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (جه)', 'അബൂമുസൽ അശ്അരി(റ): മരണം അടുത്തപ്പോൾ അദ്ദേഹം ഇങ്ങനെ വസ്വിയ്യത്ത് ചെയ്തു. മിജ്മറു(ധൂപക്കുറ്റി)മായി നിങ്ങൾ എന്നെ പിന്തുടരുത്. അവർ ചോദിച്ചു: ഈ വിഷയത്തിൽ വല്ലതും കേട്ടിട്ടുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: അതെ, പ്രവാചകൻ(സ)യിൽനിന്ന് കേട്ടിട്ടുണ്ട്. (ജ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമുസൽ അശ്അരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 893, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 494, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَنِ اتَّبَعَ جِنَازَةً فَلْيَحْمِلْ بِجَوَانِبِ السَّرِيرِ كُلِّهَا، فَإِنَّهُ مِنَ السُّنَّةِ. ثُمَّ إِنْ شَاءَ فَلْيَتَطَوَّعْ، وَإِنْ شَاءَ فَلْيَدَعْ. [ز: في سنده انقطاع] (جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ജനാസയെ അനുഗമിക്കുന്നവർ കട്ടിലിന്റെ എല്ലാ ഭാഗങ്ങളിൽ നിന്നും ചുമക്കുക അതാണ് നബിചര്യ. ഉദ്ദേശിക്കുന്നവൻ ചര്യ അനുവർത്തിക്കട്ടെ. ഉദ്ദേശിക്കുന്നവർ ഉപേക്ഷിച്ചുകൊള്ളട്ടെ. (ഇതിന്റെ പരമ്പരയിൽ വിടവുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده انقطاع', null, 893, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 495, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "يَا عَلِيُّ، ثَلَاثٌ لَا تُؤَخِّرْهَا: الصَّلَاةُ إِذَا أَتَتْ وَالْجِنَازَةُ إِذَا حَضَرَتْ، وَالْأَيِّمُ إِذَا وَجَدْتَ لَهَا كُفْئًا". (ت,جه)', 'പ്രവാചകൻ(സ) പറഞ്ഞതായി അലിയ്യ് ഇബ്നുഅബൂത്വാലിബ്(റ): നബി(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "ഓ അലി! മൂന്ന് കാര്യങ്ങൾ താമസിപ്പിക്കരുത്. നിസ്കാരം സമയം ആയാൽ, മരിച്ചാൽ മൃതശരീരം, കന്യകക്കു വേണ്ടി നീ ഇണയെ കണ്ടെത്തിയാൽ." (തു,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'പ്രവാചകൻ(സ) പറഞ്ഞതായി അലിയ്യ് ഇബ്നുഅബൂത്വാലിബ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 893, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 496, 'عَنْ عِمْرَانَ بْنِ الْحُصَيْنِ وَأَبِي بَرْزَةَ – رَضِيَ اللهُ عَنْهُمْ – قَالَا: خَرَجْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي جِنَازَةٍ، فَرَأَى قَوْمًا قَدْ طَرَحُوا أَرْدِيَتَهُمْ يَمْشُونَ فِي قُمُصٍ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَبِفِعْلِ الْجَاهِلِيَّةِ تَأْخُذُونَ؟ أَوْ: بِصُنْعِ الْجَاهِلِيَّةِ تَشَبَّهُونَ؟ لَقَدْ هَمَمْتُ أَنْ أَدْعُوَ عَلَيْكُمْ دَعْوَةً تَرْجِعُونَ فِي غَيْرِ صُوَرِكُمْ". قَالَ: فَأَخَذُوا أَرْدِيَتَهُمْ وَلَمْ يَعُودُوا لِذَلِكَ. [في إسناده ضعيف] (جه)', 'ഇംറാൻ ഇബ്നുഹുസൈൻ(റ), അബൂബർസ(റ): ഞങ്ങൾ പ്രവാചക(സ)ന്റെ കൂടെ ഒരു ജനാസയിൽ പോകുമ്പോൾ. പുടവയില്ലാത്ത കേവലം കുപ്പായമണിഞ്ഞ് നടന്നുപോകുന്ന ഒരു കൂട്ടം ആളുകളെ തിരുമേനി(സ) കണ്ടു. അവിടുന്ന് പറഞ്ഞു: "നിങ്ങൾ ജാഹിലിയ്യ പ്രവർത്തനം സ്വീകരിക്കുകയാണോ അല്ലെങ്കിൽ: നിങ്ങൾ ജാഹിലിയ്യ ചര്യയുമായി താദാത്മ്യപ്പെടുകയാണോ? നിങ്ങളെ മറ്റൊരു രൂപത്തിലേക്ക് മാറ്റിമറിക്കാൻ വേണ്ടി ഒരു പ്രാർത്ഥന നടത്താൻ ഞാൻ ചിന്തിച്ചുപോയി." റിപ്പോർട്ടർ പറയുന്നു: അപ്പോഴവർ പുടവയണിഞ്ഞു. പിന്നീട് അവരത് ആവർത്തിച്ചിട്ടില്ല. (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ) (ജ)', 'عِمْرَانَ بْنِ الْحُصَيْنِ وَأَبِي بَرْزَةَ –', 'ഇംറാൻ ഇബ്നുഹുസൈൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ', 893, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=158 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 497, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى ابْنِ الدَّحْدَاحِ، ثُمَّ أُتِيَ بِفَرَسٍ عُرْيٍ، فَعَقَلَهُ رَجُلٌ فَرَكِبَهُ، فَجَعَلَ يَتَوَقَّصُ بِه وَنَحْنُ نَتْبَعُهُ نَسْعَى خَلْفَهُ، قَالَ: فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: إِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كَمْ مِنْ عِذْقٍ مُعَلَّقٍ أَوْ مُدَلًّى فِي الْجَنَّةِ لِابْنِ الدَّحْدَاحِ". (م)', 'ജാബിർ ഇബ്നുസമുറ(റ): പ്രവാചകൻ(സ) ഇബ്നുദ്ദഹ്ദാഹി(റ)നു വേണ്ടി മയ്യിത്ത് നിസ്കരിച്ചു. ശേഷം ഒരു ജീനിയില്ലാത്ത കുതിരയെ കൊണ്ടു വന്നു. ഒരാൾ അതിനെ കെട്ടിയ ശേഷം പ്രവാചകൻ(സ) അതിന് മുകളിൽ കയറുകയും അതിനെ ഓടിച്ചു പോകുകയും ചെയ്തു. ഞങ്ങൾ പ്രവാചക(സ)ന്റെ പിന്നിൽ ധൃതിപ്പെട്ടുകൊണ്ട് പിൻതുടരുന്നുണ്ടായിരുന്നു. അപ്പോൾ ജനക്കൂട്ടത്തിൽനിന്ന് ഒരാൾ പറഞ്ഞു: പ്രവാചകൻ(സ) പറയുകയുണ്ടായി: "ഇബ്നുദ്ദഹ്ദാഹിന് വേണ്ടി സ്വർഗത്തിൽ ഈത്തപ്പഴക്കുലകൾ എത്രമാത്രം തൂങ്ങിക്കിടക്കുന്നു." (മു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിർ ഇബ്നുസമുറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=159 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 498, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى جَنَازَةِ أَبِي الدَّحْدَاحِ، فَلَمَّا رَجَعَ أُتِيَ بِفَرَسٍ مَعْرُورًى فَرَكِبَ، وَمَشَيْنَا مَعَهُ. (ن)', 'ജാബിർ ഇബ്നുസമുറ(റ): പ്രവാചകൻ(സ) അബുദ്ദഹ്ദാഹി(റ)ന്റെ ജനാസയോടൊപ്പം പുറപ്പെട്ടു. മടങ്ങുമ്പോൾ ജീനിയില്ലാത്ത ഒരു കുതിരയെ കൊണ്ടുവന്നു. പ്രവാചകൻ(സ) അതിന്മേൽ കയറി, ഞങ്ങൾ നബി(സ)യുടെ കൂടെ നടന്നു. (ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിർ ഇബ്നുസമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=159 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 499, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبَا بَكْرٍ وَعُمَرَ يَمْشُونَ أَمَامَ الْجِنَازَةِ. (د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): പ്രവാചക(സ)നും, ആബൂബക്കറും(റ), ഉമറും(റ) ജനാസയുടെ മുന്നിലൂടെ നടക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=160 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 500, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْجِنَازَةُ مَتْبُوعَةٌ وَلَيْسَتْ بِتَابِعَةٍ، لَيْسَ مَعَهَا مَنْ تَقَدَّمَهَا". (د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "മയ്യിത്ത് അനുഗമിക്കപ്പെടുകയാണ് വേണ്ടത്. അത് ആളുകളെ അനുഗമിക്കുകയല്ല. അതിന്റെ മുന്നിൽ പോകുന്നവർ അതിന്റെ കൂടെയല്ല." (ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=160 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 501, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي جِنَازَةٍ، فَرَأَى نَاسًا رُكْبَانًا، فَقَالَ: "أَلَا تَسْتَحْيُونَ؟ إِنَّ مَلَائِكَةَ اللهِ عَلَى أَقْدَامِهِمْ وَأَنْتُمْ عَلَى ظُهُورِ الدَّوَابِّ". (ت,جه)', 'സൗബാൻ(റ): ഞങ്ങൾ തുരുമേനി(സ)യുടെ കൂടെ ഒരു ജനാസയിൽ പോകുമ്പോൾ വാഹനത്തിൽ കയറിയ ജനങ്ങളെ കണ്ടപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ ലജ്ജിക്കുന്നില്ലേ? അല്ലാഹുവിന്റെ മലക്കുകൾ പാദങ്ങളിൽ നടക്കുമ്പോൾ നിങ്ങൾ വാഹനപ്പുറത്ത് സഞ്ചരിക്കുന്നു!" (തു,ജ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=160 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 502, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ رَأَى جِنَازَةً يُسْرِعُونَ بِهَا، قَالَ: "لِتَكُنْ عَلَيْكُمُ السَّكِينَةُ". [ز: في سنده ضعيف] (جه)', 'പ്രവാചകൻ(സ)യിൽ നിന്ന് അബൂമുസ(റ): ജനങ്ങൾ ഒരു മൃതശരീരത്തെ ധൃതിപ്പെട്ട് കൊണ്ടുപോകുന്നത് കണ്ടപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു. "നിങ്ങൾ അടക്കം പാലിക്കുക." (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'أَبِي مُوسَى', 'പ്രവാചകൻ(സ)യിൽ നിന്ന് അബൂമുസ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 894, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=161 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 503, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ، رَفَعَهُ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "الرَّاكِبُ يَسِيرُ خَلْفَ الْجِنَازَةِ، وَالْمَاشِي يَمْشِي خَلْفَهَا وَأَمَامَهَا وَعَنْ يَمِينِهَا وَعَنْ يَسَارِهَا قَرِيبًا مِنْهَا، وَالسِّقْطُ يُصَلَّى عَلَيْهِ وَيُدْعَى لِوَالِدَيْهِ بِالْمَغْفِرَةِ وَالرَّحْمَةِ". (د,ت,ن,جه)', 'പ്രവാചകൻ(സ) പറഞ്ഞതായി മുഗീറത്ത് ഇബ്നുശുഅ്ബ(റ): "വാഹനത്തിൽ സഞ്ചരിക്കുന്നവൻ ജനാസയുടെ പിന്നിൽ സഞ്ചരിക്കണം. കാൽ നടക്കാരൻ ജനാസയുടെ സമീപത്തായി പിന്നിലോ മുന്നിലോ വലത് ഭാഗത്തോ ഇടത് ഭാഗത്തോ നടക്കണം. ചാപിള്ളക്ക് വേണ്ടി നിസ്കരിക്കണം അതിന്റെ മാതാപിതാക്കൾക്ക് വേണ്ടി പാപമോചനത്തിനും കാരുണ്യത്തിനും വേണ്ടി പ്രാർത്ഥിക്കണം." (ദ,തു,ന,ജ)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'പ്രവാചകൻ(സ) പറഞ്ഞതായി മുഗീറത്ത് ഇബ്നുശുഅ്ബ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=161 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 504, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِدَابَّةٍ وَهُوَ مَعَ الْجِنَازَةِ، فَأَبَى أَنْ يَرْكَبَهَا، فَلَمَّا انْصَرَفَ أُتِيَ بِدَابَّةٍ فَرَكِبَ، فَقِيلَ لَهُ، فَقَالَ: "إِنَّ الْمَلَائِكَةَ كَانَتْ تَمْشِي، فَلَمْ أَكُنْ لِأَرْكَبَ وَهُمْ يَمْشُونَ، فَلَمَّا ذَهَبُوا رَكِبْتُ". (د)', 'സൗബാൻ(റ): ഒരു ജനാസയെ അനുഗമിക്കുമ്പോൾ പ്രവാചകൻ(സ)യുടെ അടുക്കൽ ഒരു മൃഗത്തെ കൊണ്ടുവന്നു. തിരുമേനി(സ) അതിൽ കയറുവാൻ വിസമ്മതിച്ചു. മടങ്ങി പോരുമ്പോൾ ഒരു മൃഗത്തെ കൊണ്ടു വന്നപ്പോൾ തിരുമേനി(സ) അതിൽ കയറി. അതിനെക്കുറിച്ച് ചോദിച്ചപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "മലക്കുകൾ നടക്കുകയായിരുന്നു അവർ നടക്കുമ്പോൾ വാഹനത്തിൽ കയറാൻ ഞാൻ ഇഷ്ടപെട്ടില്ല. അവർ പോയപ്പോൾ ഞാൻ കയറി." (ദ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=161 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 505, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى ابْنِ الدَّحْدَاحِ وَنَحْنُ شُهُودٌ ثُمَّ أُتِيَ بِفَرَسٍ فَعُقِلَ حَتَّى رَكِبَهُ، فَجَعَلَ يَتَوَقَّصُ بِه وَنَحْنُ نَسْعَى حَوْلَهُ. (م,د,ت)', 'ജാബിറുബ്നു സമുറ(റ): ഇബ്നുദ്ദഹ്ദാഹി(റ)നുവേണ്ടി തിരുമേനി(സ) മയ്യിത്ത് നിസ്കരിച്ചു. ഞങ്ങൾ അവിടെ സന്നിഹിതരായിരുന്നു. പിന്നീട് ഒരു കുതിരയെ കൊണ്ടുവന്നു. അതിനെ ബന്ധിച്ചുകൊണ്ട് തിരുമേനി(സ) അതിന്മേൽ കയറി. തിരുമേനി(സ) അതിനെ വേഗത കുറച്ച് ഓടിക്കുകയും ഞങ്ങൾ നബി(സ)യുടെ ചുറ്റും ധൃതിയിൽ പോവുകയും ചെയ്തു. (മു,ദ,തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=161 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 506, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْنَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمَشْيِ خَلْفَ الْجِنَازَةِ؟ قَالَ: "مَا دُونَ الْخَبَبِ، فَإِنْ كَانَ خَيْرًا عَجَّلْتُمُوهُ، وَإِنْ كَانَ شَرًّا فَلَا يُبَعَّدُ إِلَّا أَهْلُ النَّارِ، الْجِنَازَةُ مَتْبُوعَةٌ وَلَا تَتْبَعُ، وَلَيْسَ مِنَّا مَنْ تَقَدَّمَهَا". (د,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞങ്ങൾ തിരുമേനി(സ)യോട് ജനാസയുടെ പിന്നിൽ നടക്കുന്നതിനെ കുറിച്ചു ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "വളരെ വേഗത്തിലല്ല. അവൻ സുകൃതവാനാണെങ്കിൽ നിങ്ങൾ അവനെ ധൃതിയിൽ നയിക്കുന്നു. അവൻ ദുഷ്കർമ്മിയാണെങ്കിൽ നരകവാസികളിൽ നിന്ന് തിന്മ വിദൂരത്തല്ല. ജനാസ അനുഗമിക്കുകയല്ല അനുഗമിക്കപ്പെടുകയാണ് വേണ്ടത്. മുമ്പിൽ പോകുന്നവൻ നമ്മളിൽ പെട്ടവനല്ല." (ദ,തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=161 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 507, 'عَنْ رَاشِدِ بْنِ سَعْدٍ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللهِ، مَا بَالُ الْمُؤْمِنِينَ يُفْتَنُونَ فِي قُبُورِهِمْ إِلَّا الشَّهِيدَ؟ قَالَ: "كَفَى بِبَارِقَةِ السُّيُوفِ عَلَى رَأْسِه فِتْنَةً". (ن)', 'ഒരു സഹാബിയിൽ നിന്ന് റാശിദുബ്നു സഅ്ദ് നിവേദനം: ഒരാൾ നബി(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഖബറിൽ ശിക്ഷിക്കപ്പെടുന്ന രക്തസാക്ഷികളല്ലാത്തവരുടെ അവസ്ഥ എന്ത്? നബി(സ) പറഞ്ഞു: "അവന്റെ തലക്കുമുകളിലുള്ള വാൾ തന്നെ മതി ശിക്ഷയായിട്ട്." (ന)', 'رَاشِدِ بْنِ سَعْدٍ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ', null, null, null, array['ن']::text[], array['ന']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=162 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 508, 'عَنْ صَفْوَانَ بْنِ أُمَيَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: "الطَّاعُونُ وَالْمَبْطُونُ وَالْغَرِيقُ وَالنُّفَسَاءُ شَهَادَةٌ". قَالَ: وَرَفَعَهُ مَرَّةً إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'സഫ്വാനുബ്നു ഉമയ്യ(റ): "പ്ലേഗ് രോഗം, ഉദരരോഗം, മുങ്ങൽ, പ്രസവം എന്നിവകൊണ്ട് മരിക്കൽ രക്തസാക്ഷിത്വമാണ്." ഇത് നബി(സ)യിലേക്ക് മർഫൂആയും വന്നിട്ടുണ്ട്. (ന)', 'صَفْوَانَ بْنِ أُمَيَّةَ', 'സഫ്വാനുബ്നു ഉമയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=162 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 509, 'عَنْ عُبَيْدِ اللهِ بْنِ مُعَيَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: أُصِيبَ رَجُلَانِ مِنَ الْمُسْلِمِينَ يَوْمَ الطَّائِفِ، فَحُمِلَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَ أَنْ يُدْفَنَا حَيْثُ أُصِيبَا. وَكَانَ ابْنُ مُعَيَّةَ وُلِدَ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'ഉബൈദുല്ലാഹിബ്നു മുഅയ്യഃ(റ): ത്വാഇഫ് ദിനത്തിൽ രണ്ട് മുസ്ലിംകൾ കൊല്ലപ്പെട്ടു. അവരെ റസൂലി(സ)ന്റെ അടുക്കൽ കൊണ്ടുവന്നു. അവർ കൊല്ലപ്പെട്ട സ്ഥാനത്ത് തന്നെ മറമാടാൻ അവിടുന്ന് കൽപ്പിച്ചു. നബി(സ)യുടെ കാലത്താണ് ഇബ്നുമുഅയ്യഃ ജനിച്ചത്. (ന)', 'عُبَيْدِ اللهِ بْنِ مُعَيَّةَ', 'ഉബൈദുല്ലാഹിബ്നു മുഅയ്യഃ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=163 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 510, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ادْفِنُوا الْقَتْلَى فِي مَصَارِعِهِمْ". (ن)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: " (യുദ്ധത്തിൽ) കൊല്ലപ്പെട്ടവരെ അവർ വീണ സ്ഥലത്ത് തന്നെ മറമാടുക." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=163 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 511, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ عَلَى الْمِنْبَرِ يَقُولُ: "إِنَّكُمْ مُلَاقُو اللهِ عَزَّ وَجَلَّ حُفَاةً عُرَاةً غُرْلًا". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) മിമ്പറിൽ വെച്ച് ഇങ്ങനെ ഖുത്വുബ പറയുന്നത് ഞാൻ കേട്ടു: "നിശ്ചയം, നിങ്ങൾ നഗ്നപാദരും, നഗ്നരും, ചേലാകർമ്മം ചെയ്യാത്തവരും ആയ നിലയിൽ അല്ലാഹുവിനെ കണ്ടുമുട്ടുന്നവരാണ്." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=164 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 512, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يُحْشَرُ النَّاسُ يَوْمَ الْقِيَامَةِ عُرَاةً غُرْلًا، وَأَوَّلُ الْخَلَائِقِ يُكْسَى إِبْرَاهِيمُ عَلَيْهِ السَّلَامُ". ثُمَّ قَرَأَ: {كَمَا بَدَأْنَا أَوَّلَ خَلْقٍ نُعِيدُهُ} [الأنبياء: ١٠٤]. (ن)', 'നബി(സ)ൽ നിന്ന് ഇബ്നുഅബ്ബാസ്(റ): "അന്ത്യനാളിൽ ജനങ്ങൾ നഗ്നരും ചേലാകർമ്മം ചെയ്യപ്പെടാത്തവരും ആയ നിലയിൽ ഒരുമിച്ച് കൂട്ടപ്പെടും. സൃഷ്ടികളിൽ ആദ്യമായി വസ്ത്രം ധരിപ്പിക്കപ്പെടുക ഇബ്റാഹിം(അ) ആയിരിക്കും." പിന്നെ നബി(സ) ''ആദ്യസൃഷ്ടി നാം എങ്ങനെ തുടങ്ങിയോ അങ്ങനെ നാം മടക്കി സൃഷ്ടിക്കും'' (അൽഅൻബിയാഅ്: 104) എന്ന ആയത്തോതി. (ന)', 'ابْنِ عَبَّاسٍ', 'നബി(സ)ൽ നിന്ന് ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الأنبياء: ١٠٤', null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=164 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 513, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يُبْعَثُ النَّاسُ يَوْمَ الْقِيَامَةِ حُفَاةً عُرَاةً غُرْلًا". فَقَالَتْ عَائِشَةُ: فَكَيْفَ بِالْعَوْرَاتِ؟ قَالَ: "لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ". (ن)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ ജനങ്ങൾ നഗ്നപാദരും, നഗ്നരും ചേലാകർമ്മം ചെയ്യപ്പെടാത്തവരും ആയ നിലയിൽ എഴുന്നേൽപ്പിക്കപ്പെടും." അപ്പോൾ ആഇശ(റ) ചോദിച്ചു: എങ്ങിനെയാണ് ഔറത്ത് കാണിച്ചു നിൽക്കുക? നബി(സ) പറഞ്ഞു: "അന്ന് എല്ലാ ഓരോ മനുഷ്യനും അവന്റേതായ കാര്യങ്ങൾ ശ്രദ്ധിക്കാനുണ്ടാകും." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 897, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=164 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 514, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّكُمْ تُحْشَرُونَ حُفَاةً عُرَاةً". قُلْتُ: الرِّجَالُ وَالنِّسَاءُ، يَنْظُرُ بَعْضُهُمْ إِلَى بَعْضٍ؟ قَالَ: "إِنَّ الْأَمْرَ أَشَدُّ مِنْ أَنْ يُهِمَّهُمْ ذَلِكَ". (ن)', 'നബി(സ)യിൽ നിന്ന് അഇശ(റ): "നിങ്ങൾ അന്ത്യനാളിൽ നഗ്നരും, നഗ്നപാദരുമായി ഒരുമിച്ച് കൂട്ടപ്പെടും." ഞാൻ ചോദിച്ചു: സ്ത്രീകളും പുരുഷന്മാരും പരസ്പരം നോക്കുകയില്ലേ. നബി(സ) പറഞ്ഞു: "ഇത് ശ്രദ്ധിക്കുന്നതിലും ഗൗരവമേറിയ കാര്യത്തിലായിരിക്കും അവർ ഉണ്ടാവുക." (ന)', 'عَائِشَةَ', 'നബി(സ)യിൽ നിന്ന് അഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 897, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=164 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 515, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يُحْشَرُ النَّاسُ يَوْمَ الْقِيَامَةِ عَلَى ثَلَاثِ طَرَائِقَ، رَاغِبِينَ رَاهِبِينَ: اثْنَانِ عَلَى بَعِيرٍ، وَثَلَاثَةٌ عَلَى بَعِيرٍ، وَأَرْبَعَةٌ عَلَى بَعِيرٍ، وَعَشَرَةٌ عَلَى بَعِيرٍ. وَتَحْشُرُ بَقِيَّتَهُمُ النَّارُ، تَقِيلُ مَعَهُمْ حَيْثُ قَالُوا، وَتَبِيتُ مَعَهُمْ حَيْثُ بَاتُوا، وَتُصْبِحُ مَعَهُمْ حَيْثُ أَصْبَحُوا، وَتُمْسِي مَعَهُمْ حَيْثُ أَمْسَوْا". (ن)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ ജനങ്ങൾ മൂന്നു വഴിയിൽ എഴുന്നേൽപ്പിക്കപ്പെടും. പ്രതീക്ഷിക്കുന്നവരും, ഭയപ്പെടുന്നവരുമായ നിലയിൽ, രണ്ടു പേർ ഒരു ഒട്ടകപ്പുറത്ത്, മൂന്ന് പേർ ഒരു ഒട്ടകപ്പുറത്ത്, നാലു പേർ ഒരു ഒട്ടകപ്പുറത്ത്, പത്ത് പേർ ഒരു ഒട്ടകപ്പുറത്ത് (ഈ രീതിയിലായിരിക്കും വരിക). ബാക്കിയുള്ളവർ നരകത്തിൽ ഒരുമിച്ച് കൂട്ടപ്പെടും. നരകം അവർ ഉറങ്ങിയ സ്ഥലത്ത് ഉച്ചയുറങ്ങും, അവരുടെ കൂടെ രാത്രിയുറങ്ങും, അവർ പ്രഭാതത്തിലുള്ള സ്ഥലത്ത് നരകവുമുണ്ടാകും, അവർ വൈകുന്നേരസമയത്തുള്ളിടത്ത് നരകവുമുണ്ടാകും." (ന)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 897, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=164 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 516, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ الصَّادِقَ الْمَصْدُوقَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَدَّثَنِي: "أَنَّ النَّاسَ يُحْشَرُونَ ثَلَاثَةَ أَفْوَاجٍ: فَوْجٌ رَاكِبِينَ طَاعِمِينَ كَاسِينَ، وَفَوْجٌ تَسْحَبُهُمُ الْمَلَائِكَةُ عَلَى وُجُوهِهِمْ وَتَحْشُرُهُمُ النَّارُ، وَفَوْجٌ يَمْشُونَ وَيَسْعَوْنَ، يُلْقِي اللهُ الْآفَةَ عَلَى الظَّهْرِ فَلَا يَبْقَى، حَتَّى إِنَّ الرَّجُلَ لَتَكُونُ لَهُ الْحَدِيقَةُ يُعْطِيهَا بِذَاتِ الْقَتَبِ لَا يَقْدِرُ عَلَيْهَا". (ن)', 'അബൂദർറ്(റ): സത്യപ്രവാചകൻ(സ) എനിക്ക് പറഞ്ഞു തന്നു: "നിശ്ചയം ജനങ്ങൾ മൂന്ന് വിഭാഗമായി ഒരുമിച്ച് കൂട്ടപ്പെടും. വാഹനം കയറിയവരും, ഭക്ഷണം കഴിച്ചവരും, വസ്ത്രം ധരിച്ചവരുമായ സംഘം. മുഖം നിലത്തിട്ട് മലക്കുകൾ വലിച്ചിഴക്കുന്ന മറ്റൊരു വിഭാഗം. അവർ നരകത്തിൽ ഒരുമിച്ച് കൂടും. ഓടുകയും നടക്കുകയും ചെയ്യുന്ന വേറൊരു വിഭാഗം. മൃഗങ്ങളെ മുഴുവൻ അല്ലാഹു നശിപ്പിക്കും. ഒട്ടകത്തിന്റെ പൂഞ്ഞക്കു ചുറ്റും വെക്കുന്ന സാധനത്തിന് പകരമായി പോലും ഒരു തോട്ടം പകരമായി നൽകുന്ന അവസ്ഥ വരും." (ന)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 897, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=164 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 517, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْمَوْعِظَةِ فَقَالَ: "يَا أَيُّهَا النَّاسُ، إِنَّكُمْ مَحْشُورُونَ إِلَى اللهِ عَزَّ وَجَلَّ عُرَاةً، حُفَاةً غُرْلًا، كَمَا بَدَأْنَا أَوَّلَ خَلْقٍ نُعِيدُهُ. قَالَ: أَوَّلُ مَنْ يُكْسَى يَوْمَ الْقِيَامَةِ إِبْرَاهِيمُ عَلَيْهِ السَّلَامُ، وَإِنَّهُ سَيُؤْتَى – وَفِي رِوَايَةٍ: يُجَاءُ – بِرِجَالٍ مِنْ أُمَّتِي، فَيُؤْخَذُ بِهِمْ ذَاتَ الشِّمَالِ، فَأَقُولُ: رَبِّ أَصْحَابِي، فَيُقَالُ: إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ. فَأَقُولُ كَمَا قَالَ الْعَبْدُ الصَّالِحُ: {وَكُنْتُ عَلَيْهِمْ شَهِيدًا مَا دُمْتُ فِيهِمْ فَلَمَّا تَوَفَّيْتَنِي – إِلَى قَوْلِه – وَإِنْ تَغْفِرْ لَهُمْ} الْآيَةَ. فَيُقَالُ: إِنَّ هَؤُلَاءِ لَمْ يَزَالُوا مُدْبِرِينَ – وَفِي رِوَايَةٍ: مُرْتَدِّينَ – عَلَى أَعْقَابِهِمْ مُنْذُ فَارَقْتَهُمْ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഒരു ഉപദേശം നടത്തി. അതിൽ ഇപ്രകാരം പറഞ്ഞു: "ജനങ്ങളേ, നിശ്ചയം നിങ്ങൾ മഹോന്നതനായ അല്ലാഹുവിന്റെ മുന്നിൽ നഗ്നരും, നഗ്നപാദരും ചേലാകർമ്മം ചെയ്യപ്പെടാത്തവരുമായ നിലയിൽ ഒരുമിച്ച് കൂട്ടപ്പെടും. നാം (അല്ലാഹു) ഒന്നാമത് സൃഷ്ടി കർമ്മം എപ്രകാരം ആരംഭിച്ചുവോ അതേ പ്രകാരമാക്കി സൃഷ്ടിക്കുന്നതാണ്. അന്ത്യനാളിൽ ആദ്യമായി വസ്ത്രം ധരിപ്പിക്കപ്പെടുക ഇബ്രാഹിം നബി(അ) ആയിരിക്കും. എന്റെ സമുദായത്തിലെ ചില ആളുകൾ കൊണ്ടുവരപ്പെടും. അവർ ഇടതുവശത്ത് നിർത്തപ്പെടും. അപ്പോൾ ഞാൻ പറയും: എന്റെ രക്ഷിതാവേ, അവർ എന്റെ ആളുകളാണ്. അപ്പോൾ ഇങ്ങനെ മറുപടി ലഭിക്കും: അങ്ങേക്ക് ശേഷം അവർ പുതുതായി ഉണ്ടാക്കിയത് എന്തെല്ലാമാണെന്ന് അങ്ങേക്കറിയില്ല. അപ്പോൾ ആ സന്മാർഗ്ഗിയായ ആൾ (ഈസാനബി) പറഞ്ഞത് ഞാനും പറയും: ''ഞാൻ അവരിലുണ്ടായിരുന്ന കാലത്തോളം ഞാൻ അവരുടെ സാക്ഷിയായിരുന്നു. നീ എന്നെ തിരിച്ചു വിളിച്ചപ്പോൾ അവരുടെ നിരീക്ഷകൻ നീ തന്നെയായിരുന്നില്ലെ. നീ സകലതിനും സാക്ഷിയാകുന്നു. നീ അവരെ ശിക്ഷിക്കുന്നുവെങ്കിൽ അവർ നിന്റെ ദാസന്മാരാണ്. നീ അവർക്ക് മാപ്പ് നൽകുന്നുവെങ്കിൽ നീ മഹാനും യുക്തിജ്ഞനുമാണ്.'' (117, 118) അപ്പോൾ പറയപ്പെടും: നിശ്ചയം താങ്കൾ അവരെ പിരിഞ്ഞതുമുതൽ ഇക്കൂട്ടർ പിന്തിരിഞ്ഞുകൊണ്ടേയിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: വിശ്വാസഭ്രംശം സംഭവിച്ചവരായിക്കൊണ്ടേയിരുന്നു." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 898, 898, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=165 where b.volume_id=1 and b.book_no=31 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=517), 1, 'وَفِي رِوَايَةٍ: يُجَاءُ – بِرِجَالٍ مِنْ أُمَّتِي، فَيُؤْخَذُ بِهِمْ ذَاتَ الشِّمَالِ، فَأَقُولُ: رَبِّ أَصْحَابِي، فَيُقَالُ: إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ. فَأَقُولُ كَمَا قَالَ الْعَبْدُ الصَّالِحُ: {وَكُنْتُ عَلَيْهِمْ شَهِيدًا مَا دُمْتُ فِيهِمْ فَلَمَّا تَوَفَّيْتَنِي – إِلَى قَوْلِه – وَإِنْ تَغْفِرْ لَهُمْ} الْآيَةَ. فَيُقَالُ: إِنَّ هَؤُلَاءِ لَمْ يَزَالُوا مُدْبِرِينَ –', 'മറ്റൊരു നിവേദനിൽ: വിശ്വാസഭ്രംശം സംഭവിച്ചവരായിക്കൊണ്ടേയിരുന്നു." (ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=31 and h.hadith_no=517), 2, 'وَفِي رِوَايَةٍ: مُرْتَدِّينَ – عَلَى أَعْقَابِهِمْ مُنْذُ فَارَقْتَهُمْ". (ن)', null);
